  [data-scope='checkbox'][data-part='label'],
  [data-scope='checkbox-group'][data-part='label'],
  [data-scope='color-picker'][data-part='label'],
  [data-scope='date-field'][data-part='label'],
  [data-scope='editable'][data-part='label'],
  [data-scope='field'][data-part='label'],
  [data-scope='file-upload'][data-part='label'],
  [data-scope='number-field'][data-part='label'],
  [data-scope='password-input'][data-part='label'],
  [data-scope='pin-input'][data-part='label'],
  [data-scope='radio-group'][data-part='label'],
  [data-scope='rating'][data-part='label'],
  [data-scope='signature-pad'][data-part='label'],
  [data-scope='slider'][data-part='label'],
  [data-scope='switch'][data-part='label'],
  [data-scope='tags-input'][data-part='label'],
  [data-scope='text-field'][data-part='label'],
  [data-scope='time-field'][data-part='label'] {
    line-height: var(--xh-leading-none);
  }

