/* family/motion.css */
/* 定义 motion 样式。 */

/* 共享关键帧的唯一真源。
 *
 * 动画名的查找只认「文档里有没有这个名字」：引用别处文件里的名字，那份文件不一定在场，
 * 动画会静默地整个不跑。所以引用这里任一名字的皮肤都 @import 本文件，单独引入那份皮肤时
 * 关键帧仍在场；全量入口由 emit-unlayered 按物理文件去重，有层入口靠打包器对同一 URL 的
 * @import 去重，同名同帧体即使重复插入也无副作用。
 *
 * 本文件只放跨皮肤共用的关键帧，皮肤内不得重定义这些名字（check-keyframe-refs 判红）；
 * 组件专属关键帧仍住在各自皮肤。幅度只引 --xh-motion-distance-sm / -md 与 --xh-motion-scale-enter /
 * -exit，整幅位移经私有槽取 --xh-motion-travel，减弱动效档由令牌层把它们归零。四个方向槽
 * --xh-_overlay-enter-* 由浮层皮肤按 placement 写在 positioner 上，四个都没写时位移退回 0。
 */
@layer xihan.motion {
  /* ── 锚定列表 / 菜单：沿落位方向短位移，不缩放文字与选中标记 ──
     Menu、Select、Combobox、Cascader、ContextMenu、Menubar、Mention、TreeSelect、
     Date / Time picker、Tooltip */
  @keyframes xh-overlay-slide-in {
    from {
      opacity: 0;
      translate:
        calc((var(--xh-_overlay-enter-right, 0) - var(--xh-_overlay-enter-left, 0)) * var(--xh-motion-distance-sm))
        calc((var(--xh-_overlay-enter-down, 0) - var(--xh-_overlay-enter-up, 0)) * var(--xh-motion-distance-sm));
    }

    to {
      opacity: 1;
      translate: 0 0;
    }
  }

  @keyframes xh-overlay-slide-out {
    from {
      opacity: 1;
      translate: 0 0;
    }

    to {
      opacity: 0;
      translate:
        calc((var(--xh-_overlay-enter-right, 0) - var(--xh-_overlay-enter-left, 0)) * var(--xh-motion-distance-sm))
        calc((var(--xh-_overlay-enter-down, 0) - var(--xh-_overlay-enter-up, 0)) * var(--xh-motion-distance-sm));
    }
  }

  /* ── 锚定面板：从锚点那一侧冒出来，缩放叠短位移 ──
     Popover、HoverCard、Popconfirm、Tour、Command。
     起点朝哪个方向退让由 placement 写进四个方向槽（那一侧写 1），四个都没写就退回原地缩放 */
  @keyframes xh-overlay-pop-in {
    from {
      opacity: 0;
      scale: var(--xh-motion-scale-enter);
      translate:
        calc((var(--xh-_overlay-enter-right, 0) - var(--xh-_overlay-enter-left, 0)) * var(--xh-motion-distance-sm))
        calc((var(--xh-_overlay-enter-down, 0) - var(--xh-_overlay-enter-up, 0)) * var(--xh-motion-distance-sm));
    }

    to {
      opacity: 1;
      scale: 1;
      translate: 0 0;
    }
  }

  /* 退场只缩放淡出，不再沿方向退让；锚定面板与无锚定弹出共用 */
  @keyframes xh-pop-out {
    from {
      opacity: 1;
      scale: 1;
    }

    to {
      opacity: 0;
      scale: var(--xh-motion-scale-exit);
    }
  }

  /* ── 无锚定弹出：原地缩放淡入，没有方向 ──
     NavigationMenu、SideNav popout、FloatingPanel、FloatButton 列表、Pagination 弹层；
     页内浮现的小件也取它：Approval、QuestionFlow 的结果标记，MessageFeed、Log 的回底钮 */
  @keyframes xh-pop-in {
    from {
      opacity: 0;
      scale: var(--xh-motion-scale-enter);
    }

    to {
      opacity: 1;
      scale: 1;
    }
  }

  /* ── 遮罩与全屏面：只动不透明度 ──
     Dialog / Drawer / ImageViewer / Tour / Command 的遮罩，Avatar / Image 的载入揭示，
     Cascader 列项的淡入 */
  @keyframes xh-fade-in {
    from {
      opacity: 0;
    }

    to {
      opacity: 1;
    }
  }

  @keyframes xh-fade-out {
    from {
      opacity: 1;
    }

    to {
      opacity: 0;
    }
  }

  /* 页内内容的上浮进场：淡入叠一小段向上位移。Command 的分组、EmptyState、QuestionFlow */
  @keyframes xh-rise-in {
    from {
      opacity: 0;
      translate: 0 var(--xh-motion-distance-sm);
    }

    to {
      opacity: 1;
      translate: 0 0;
    }
  }

  /* ── Surface 级 disclosure：行高 0fr → 1fr，内缩同帧动 ──
     Accordion、Collapsible、Reasoning、ToolCall 的 content。
     内缩不归零的话，border-box 会把盒子钳在上下内缩之和上，收不干净。
     两端内缩由各皮肤在 content 上写进 --xh-_disclosure-pt / --xh-_disclosure-pb，
     没写的那一端按 0 动（与该端本来就没有内缩的皮肤一致） */
  @keyframes xh-disclosure-expand {
    from {
      grid-template-rows: 0fr;
      padding-block-start: 0;
      padding-block-end: 0;
    }

    to {
      grid-template-rows: 1fr;
      padding-block-start: var(--xh-_disclosure-pt, 0);
      padding-block-end: var(--xh-_disclosure-pb, 0);
    }
  }

  @keyframes xh-disclosure-collapse {
    from {
      grid-template-rows: 1fr;
      padding-block-start: var(--xh-_disclosure-pt, 0);
      padding-block-end: var(--xh-_disclosure-pb, 0);
    }

    to {
      grid-template-rows: 0fr;
      padding-block-start: 0;
      padding-block-end: 0;
    }
  }

  /* ── 列表条目进场：淡入叠一段向上位移，比页内上浮大一档 ──
     Approval、MessageFeed、QuestionFlow、ToolCall 的条目 */
  @keyframes xh-item-in {
    from {
      opacity: 0;
      translate: 0 var(--xh-motion-distance-md);
    }

    to {
      opacity: 1;
      translate: 0 0;
    }
  }

  /* 自上而下的显现：新揭开的内容从上方落位。DiffView 展开的折叠块、Form 的错误汇总 */
  @keyframes xh-drop-in {
    from {
      opacity: 0;
      translate: 0 calc(-1 * var(--xh-motion-distance-sm));
    }

    to {
      opacity: 1;
      translate: 0 0;
    }
  }

  /* ── 面板（sheet）：模态与强反馈面，竖向一小段位移叠缩放 ──
     位移与缩放写独立属性，互不覆盖，手势期间写 translate 也不会把 scale 抹掉。Dialog、Notification */
  @keyframes xh-sheet-in {
    from {
      opacity: 0;
      translate: 0 var(--xh-motion-distance-md);
      scale: var(--xh-motion-scale-enter);
    }

    to {
      opacity: 1;
      translate: 0 0;
      scale: 1;
    }
  }

  @keyframes xh-sheet-out {
    from {
      opacity: 1;
      translate: 0 0;
      scale: 1;
    }

    to {
      opacity: 0;
      translate: 0 var(--xh-motion-distance-md);
      scale: var(--xh-motion-scale-exit);
    }
  }

  /* ── 整幅滑入（slide）：面板从所在边整条推入推出 ──
     方向由皮肤在元素上写进 --xh-_slide-from-x / --xh-_slide-from-y（取正负整幅位移令牌或 0），
     两个都没写时位移退回 0。整幅位移令牌在减弱动效下归零，进出场只剩时长。Drawer */
  @keyframes xh-slide-in {
    from {
      translate: var(--xh-_slide-from-x, 0) var(--xh-_slide-from-y, 0);
    }

    to {
      translate: 0 0;
    }
  }

  @keyframes xh-slide-out {
    from {
      translate: 0 0;
    }

    to {
      translate: var(--xh-_slide-from-x, 0) var(--xh-_slide-from-y, 0);
    }
  }

  /* ── 循环：匀速转圈与扫过的流光 ──
     时长取循环令牌，减弱动效下由各皮肤停掉并换成静态替代。
     转圈写独立的 rotate 属性，与元素自身的 transform 叠加而不互相覆盖。
     流光的亮带从右扫到左：消费方把渐变画成自身两倍宽（background-size: 200% 100%），
     只移动背景位置，不动布局也不动 transform。Reasoning、ToolCall 的在跑文字 */
  @keyframes xh-spin {
    to {
      rotate: 1turn;
    }
  }

  @keyframes xh-shimmer {
    from {
      background-position: 150% center;
    }

    to {
      background-position: -50% center;
    }
  }

  /* 呼吸：进行中、给不出进度、需要被察觉的状态点。明暗与缩放一起起伏，峰值落在 42%，
     周期 --xh-motion-loop-breathe、缓动 --xh-motion-ease-breathe。只动 opacity 与 scale。
     光环画在状态点的 ::after 上，同周期从点本身的大小外扩淡尽，只播 3 个周期，状态点本身持续到状态结束。
     减弱动效下两者都停，状态点停在满不透明度。Badge 的 pulse */
  @keyframes xh-breathe {
    0%,
    100% {
      opacity: 0.5;
      scale: var(--xh-motion-scale-breathe);
    }

    42% {
      opacity: 1;
      scale: 1;
    }
  }

  @keyframes xh-breathe-halo {
    from {
      opacity: 0.32;
      scale: 1;
    }

    60%,
    to {
      opacity: 0;
      scale: var(--xh-motion-scale-halo);
    }
  }

  /* ── 数值：倒计时条从占满一整条收到零 ──
     条子自己不改尺寸，靠裁切从行尾往行首收：只重绘、不重排。裁掉哪一侧随书写方向由
     --xh-_countdown-cut-left / -right 给出，缺省按 LTR 收掉右侧；前端的圆角取
     --xh-_countdown-radius。走一遍就到头，时长由连接层写进各组件的时长槽。Toast、Notification */
  @keyframes xh-countdown {
    from {
      clip-path: inset(0 0 0 0 round var(--xh-_countdown-radius, 0));
    }

    to {
      clip-path: inset(0 var(--xh-_countdown-cut-right, 100%) 0 var(--xh-_countdown-cut-left, 0) round var(--xh-_countdown-radius, 0));
    }
  }
}

/* 其余按层归属排列。 */

/* styles/affix.css */
/* 定义 affix 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='affix'] {
    --xh-affix-skin: 1;
  }

  /* 占位盒就是 content 在常规流里占的那块地方。
     这里不声明 display，也不写高度：吸住时冻结的高度由连接层量好写进内联样式（它量得到，样式表量不到），
     没吸住时高度就该跟着内容走。不给 display，UA 的 [hidden]{display:none} 也仍然压得住 */
  [data-scope='affix'][data-part='root'] {
    /* 脱流后 content 不再撑开占位盒，宽度改从父级取 */
    inline-size: 100%;
  }

  /* 没吸住时是常规流里普通的一块，不做任何定位 */
  [data-scope='affix'][data-part='content'] {
    inline-size: 100%;
  }

  /*
   * 吸住：脱离常规流钉在视口上。
   * 四个落位数（top / bottom / left / width）由连接层写成内联样式——它们是照占位盒的矩形实测出来的
   * 物理量，换成逻辑属性会在 RTL 下贴反。这里只管「用哪种定位、压在第几层」。
   * 另一件必须提防的事：fixed 认的是视口，祖先上一旦出现
   * transform / filter / backdrop-filter / contain，包含块就被抢走，钉住的内容立刻贴错位置——
   * 所以别往覆盖钩子里加这几个属性。
   */
  [data-scope='affix'][data-part='content'][data-fixed] {
    position: fixed;
    z-index: var(--xh-affix-layer, var(--xh-layer-sticky));
  }

  @media print {
    /* 打印：钉住的是作者自己的内容，不能收起；但保持 fixed 会让部分打印引擎每页重复一次，
       所以只把它放回正常流。 */
    [data-scope='affix'][data-part='content'][data-fixed] {
      position: static;
    }
  }
}

/* styles/avatar-group.css */
/* 定义 avatar group 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='avatar-group'] {
    --xh-avatar-group-skin: 1;
  }

  /* 一排叠放的头像：后一枚压在前一枚上。
     组内共用的直径与字号在容器上写一次，沿继承流给每一枚——包括自己写了档位的那一枚，
     它的档位取值也读这两个槽，整排因此始终齐平。单独摆的头像取不到这两个槽，仍按自己的档走 */
  [data-scope='avatar-group'][data-part='root'] {
    /* 组件内那几档层号只在自己人之间排序：建一个层叠上下文把它们关起来，
       既不让页面上的层号插进来，也不让它们漏出去压住别人 */
    isolation: isolate;

    /* 私有槽位：整组共用的直径、字号与叠放量，换档只改这三个 */
    --xh-_avatar-group-size: var(--xh-avatar-group-size, var(--xh-control-h-md));
    --xh-_avatar-group-font-size: var(--xh-avatar-group-font-size, var(--xh-control-caption-md));
    --xh-_avatar-group-overlap: var(--xh-avatar-group-overlap, var(--xh-space-2_5));

    /* 流给组内每一枚 */
    --xh-avatar-size: var(--xh-_avatar-group-size);
    --xh-avatar-font-size: var(--xh-_avatar-group-font-size);

    display: inline-flex;
    align-items: center;
  }

  /* 给了 display 的角色节点必须补这条：display 声明会盖掉 UA 的 [hidden]{display:none}，
     不补的话作者给节点加 hidden 后它照样显示 */
  [data-scope='avatar-group'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 尺寸 —— */
  /* 三档对齐控件档位，缺省档写在上面的基础规则里；
     字号与叠放量跟着直径一起缩放，小头像里回退字放得下、大头像里压住的那段也按比例长 */
  [data-scope='avatar-group'][data-part='root'][data-size='sm'] {
    --xh-_avatar-group-size: var(--xh-avatar-group-size, var(--xh-control-h-sm));
    --xh-_avatar-group-font-size: var(--xh-avatar-group-font-size, var(--xh-control-caption-sm));
    --xh-_avatar-group-overlap: var(--xh-avatar-group-overlap, var(--xh-space-2));
  }

  [data-scope='avatar-group'][data-part='root'][data-size='lg'] {
    --xh-_avatar-group-size: var(--xh-avatar-group-size, var(--xh-control-h-lg));
    --xh-_avatar-group-font-size: var(--xh-avatar-group-font-size, var(--xh-control-caption-lg));
    --xh-_avatar-group-overlap: var(--xh-avatar-group-overlap, var(--xh-space-3));
  }

  /* —— 叠放 —— */
  /* 谁压在谁上面得能指定，所以每一枚都是定位元素；
     再描一圈底色，被压住的那条边才与上一枚分得开 */
  [data-scope='avatar-group'][data-part='root'] > * {
    position: relative;
  }

  [data-scope='avatar-group'][data-part='root'] > *,
  [data-scope='avatar-group'][data-part='root'] > * [data-scope='avatar'][data-part='root'] {
    box-shadow: 0 0 0 var(--xh-stroke-thick) var(--xh-avatar-group-ring, var(--xh-bg-surface));
  }

  /* 后一枚往回挪一段，压在前一枚上 */
  [data-scope='avatar-group'][data-part='root'] > * + * {
    margin-inline-start: calc(-1 * var(--xh-_avatar-group-overlap));
  }

  /* 指到哪一枚，哪一枚整个露出来 */
  [data-scope='avatar-group'][data-part='root'] > *:hover {
    z-index: 1;
  }

  /* —— 溢出计数 —— */
  /* 「+N」是这一排里的又一枚：直径、形状与字号跟着组走，里面写什么由作者定 */
  [data-scope='avatar-group'][data-part='overflow-item'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-_avatar-group-size);
    block-size: var(--xh-_avatar-group-size);
    border-radius: var(--xh-avatar-group-radius, var(--xh-shape-circle));
    background: var(--xh-avatar-group-overflow-item-bg, var(--xh-bg-muted));
    color: var(--xh-avatar-group-overflow-item-fg, var(--xh-fg-muted));
    font-size: var(--xh-_avatar-group-font-size);
    font-weight: var(--xh-avatar-group-font-weight, var(--xh-font-weight-medium));
    line-height: var(--xh-leading-none);
    user-select: none;
  }

  [data-scope='avatar-group'][data-part='overflow-item'][hidden] {
    display: none;
  }
}

/* styles/back-top.css */
/* 定义 back top 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='back-top'] {
    --xh-back-top-skin: 1;
  }

  /* 定位壳：钉在视口的尾下角，用逻辑属性，RTL 下自动换到另一侧。
     不声明 display —— 收起态由连接层写 hidden，UA 的 [hidden]{display:none} 得压得住 */
  [data-scope='back-top'][data-part='root'] {
    position: fixed;
    /* 贴边与安全区取大的一头：底部横条与圆角压住的那一段由系统给出，贴边比它窄时钮会被切掉一角。
       桌面上 env() 恒为 0，取值与贴边槽完全一致。安全区只有物理方向的名字，
       行内轴上两侧同取较宽的那一段，RTL 下不会翻错边。 */
    inset-block-end: max(var(--xh-back-top-inset-block, var(--xh-space-8)), env(safe-area-inset-bottom));
    inset-inline-end: max(
      var(--xh-back-top-inset-inline, var(--xh-space-8)),
      env(safe-area-inset-left),
      env(safe-area-inset-right)
    );
    z-index: var(--xh-back-top-layer, var(--xh-layer-sticky));
  }

  /* —— 形态：缺省 outline 的磨砂面 ——
     触发器接 Action Control floating 档，solid / subtle / ghost 的面由形态矩阵按 data-xh-action-variant 给；
     缺省 outline（连接层不传 variant 时显式落）与悬浮动作钮同属 M2 磨砂面：背景、边缘、顶光、投影与磨砂
     从一份配方取，高对比、减少透明度、打印和强制色才能沿同一令牌通道降级。钮浮在正文之上，透空的面在
     任何内容上都读不出边界，所以 outline 这一档面留着。三支私有槽写在壳上：check-elevation-role 按赋值点
     认海拔角色，float-button 同款 */
  [data-scope='back-top'][data-part='root'][data-variant='outline'] {
    --xh-_back-top-bg: var(--xh-material-frosted-bg);
    --xh-_back-top-fg: var(--xh-material-frosted-fg);
    --xh-_back-top-border: var(--xh-material-frosted-border);
    --xh-_back-top-shadow: var(--xh-material-frosted-shadow);
  }

  /* —— 触发器 ——
     浮在内容之上的单图标圆钮，接 Action Control floating 档：盒型（md = box-lg 48px，圆形）、
     四态面、0.97 按压与 44px 命中区由家族配方按 data-xh-action-variant / -size 给出。
     这里只把公开槽桥接到矩阵之前（使用者槽 → 形态矩阵 → 家族缺省）与几何槽映射。
     整件只有这一颗按钮，槽名与其余一样不带部件段（照 float-button 的 --xh-float-button-size） */
  [data-scope='back-top'][data-part='trigger'] {
    --xh-action-bg-rest: var(--xh-back-top-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-back-top-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-back-top-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-bg-focus-visible: var(--xh-back-top-bg, var(--xh-_action-variant-bg-focus-visible));
    --xh-action-bg-disabled: var(--xh-back-top-bg, var(--xh-_action-variant-bg-disabled));
    --xh-action-fg-rest: var(--xh-back-top-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-back-top-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-back-top-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-fg-focus-visible: var(--xh-back-top-fg, var(--xh-_action-variant-fg-focus-visible));
    --xh-action-border-rest: var(--xh-back-top-border, var(--xh-_action-variant-border-rest));
    --xh-action-border-hover: var(--xh-back-top-border-hover, var(--xh-_action-variant-border-hover));
    --xh-action-border-pressed: var(--xh-back-top-border-hover, var(--xh-_action-variant-border-pressed));
    --xh-action-border-focus-visible: var(--xh-back-top-border, var(--xh-_action-variant-border-focus-visible));
    --xh-action-border-disabled: var(--xh-back-top-border, var(--xh-_action-variant-border-disabled));
    /* 矩阵各态无影（淡底与阴影互斥）；outline 那一档的磨砂投影在下面另桥接 */
    --xh-action-shadow-rest: var(--xh-back-top-shadow, none);
    --xh-action-shadow-hover: var(--xh-back-top-shadow, none);
    --xh-action-shadow-pressed: var(--xh-back-top-shadow, none);
    --xh-action-shadow-focus-visible: var(--xh-back-top-shadow, none);
    --xh-action-shadow-disabled: var(--xh-back-top-shadow, none);
    --xh-action-radius: var(--xh-back-top-radius, var(--xh-_action-profile-radius));
    --xh-action-visual-size: var(--xh-back-top-size, var(--xh-_action-profile-visual-size));
    /* 作者塞进来的图标跟着 floating 档走（md 24px），与皮肤画的兜底字形同一把尺 */
    --xh-icon-size: var(--xh-back-top-icon-size, var(--xh-_action-profile-glyph-size));
  }

  /* 缺省 outline 是 M2 磨砂面：背景、边缘、顶光、投影与磨砂从同一份配方取。
     悬停 / 按下的底走矩阵 outline 列的画布阶梯（100 → 200），边缘与投影不动；
     键盘聚焦时铺配方的实体 focus surface——透明面上的内收环不能依赖页面底色；
     置灰只换字色（矩阵 disabled 列的前景），面仍留着 */
  [data-scope='back-top'][data-part='root'][data-variant='outline']
    [data-scope='back-top'][data-part='trigger'] {
    --xh-action-bg-rest: var(--xh-back-top-bg, var(--xh-_back-top-bg));
    --xh-action-bg-focus-visible: var(--xh-back-top-bg, var(--xh-material-frosted-focus-surface));
    --xh-action-bg-disabled: var(--xh-back-top-bg, var(--xh-_back-top-bg));
    --xh-action-fg-rest: var(--xh-back-top-fg, var(--xh-_back-top-fg));
    --xh-action-fg-hover: var(--xh-back-top-fg, var(--xh-_back-top-fg));
    --xh-action-fg-pressed: var(--xh-back-top-fg, var(--xh-_back-top-fg));
    --xh-action-fg-focus-visible: var(--xh-back-top-fg, var(--xh-_back-top-fg));
    --xh-action-border-rest: var(--xh-back-top-border, var(--xh-_back-top-border));
    --xh-action-border-hover: var(--xh-back-top-border-hover, var(--xh-_back-top-border));
    --xh-action-border-pressed: var(--xh-back-top-border-hover, var(--xh-_back-top-border));
    --xh-action-border-focus-visible: var(--xh-back-top-border, var(--xh-_back-top-border));
    --xh-action-border-disabled: var(--xh-back-top-border, var(--xh-_back-top-border));
    --xh-action-shadow-rest: var(--xh-back-top-shadow, var(--xh-_back-top-shadow));
    --xh-action-shadow-hover: var(--xh-back-top-shadow, var(--xh-_back-top-shadow));
    --xh-action-shadow-pressed: var(--xh-back-top-shadow, var(--xh-_back-top-shadow));
    --xh-action-shadow-focus-visible: var(--xh-back-top-shadow, var(--xh-_back-top-shadow));
    --xh-action-shadow-disabled: var(--xh-back-top-shadow, var(--xh-_back-top-shadow));
    /* M2 顶光走配方的高光通道：实心、淡色与透空形态各有自身表面，不能把磨砂高光误铺上去 */
    --xh-action-highlight-rest: var(--xh-material-frosted-highlight);
    --xh-action-highlight-hover: var(--xh-material-frosted-highlight);
    --xh-action-highlight-pressed: var(--xh-material-frosted-highlight);
    --xh-action-highlight-focus-visible: var(--xh-material-frosted-highlight);
    --xh-action-highlight-disabled: var(--xh-material-frosted-highlight);

    -webkit-backdrop-filter: var(--xh-material-frosted-backdrop);
    backdrop-filter: var(--xh-material-frosted-backdrop);
  }

  /* liquid 档：data-material="liquid" 下缺省 outline 换成液态面，面、墨色细线、1px 亮边与投影都从液态层取；
     悬停 / 按下往前景色兑，键盘聚焦铺配方的实体 focus surface。面内不加顶光，亮边已画在朝光源的一侧 */
  :where([data-material='liquid']) [data-scope='back-top'][data-part='root'][data-variant='outline']
    [data-scope='back-top'][data-part='trigger'][data-xh-liquid] {
    --xh-action-bg-rest: var(--xh-back-top-bg, var(--xh-_liquid-bg));
    --xh-action-bg-hover: var(--xh-back-top-bg-hover, var(--xh-_liquid-bg-hover));
    --xh-action-bg-pressed: var(--xh-back-top-bg-active, var(--xh-_liquid-bg-pressed));
    --xh-action-bg-focus-visible: var(--xh-back-top-bg, var(--xh-material-liquid-focus-surface));
    --xh-action-bg-disabled: var(--xh-back-top-bg, var(--xh-_liquid-bg));
    --xh-action-fg-rest: var(--xh-back-top-fg, var(--xh-material-liquid-fg));
    --xh-action-fg-hover: var(--xh-back-top-fg, var(--xh-material-liquid-fg));
    --xh-action-fg-pressed: var(--xh-back-top-fg, var(--xh-material-liquid-fg));
    --xh-action-fg-focus-visible: var(--xh-back-top-fg, var(--xh-material-liquid-fg));
    --xh-action-border-rest: var(--xh-back-top-border, var(--xh-material-liquid-border));
    --xh-action-border-hover: var(--xh-back-top-border-hover, var(--xh-material-liquid-border));
    --xh-action-border-pressed: var(--xh-back-top-border-hover, var(--xh-material-liquid-border));
    --xh-action-border-focus-visible: var(--xh-back-top-border, var(--xh-material-liquid-border));
    --xh-action-border-disabled: var(--xh-back-top-border, var(--xh-material-liquid-border));
    --xh-action-shadow-rest: var(--xh-back-top-shadow, var(--xh-_liquid-shadow));
    --xh-action-shadow-hover: var(--xh-back-top-shadow, var(--xh-_liquid-shadow));
    --xh-action-shadow-pressed: var(--xh-back-top-shadow, var(--xh-_liquid-shadow));
    --xh-action-shadow-focus-visible: var(--xh-back-top-shadow, var(--xh-_liquid-shadow));
    --xh-action-shadow-disabled: var(--xh-back-top-shadow, var(--xh-_liquid-shadow));
    --xh-action-highlight-rest: transparent;
    --xh-action-highlight-hover: transparent;
    --xh-action-highlight-pressed: transparent;
    --xh-action-highlight-focus-visible: transparent;
    --xh-action-highlight-disabled: transparent;

    -webkit-backdrop-filter: var(--xh-material-liquid-backdrop);
    backdrop-filter: var(--xh-material-liquid-backdrop);
  }

  /* 面是实心的，环色与面同族，画在面里就看不出来；环改取面自己的前景色——
     那一族色本来就要在这块面上把字读清楚，与面的对比是按可读性定的 */
  [data-scope='back-top'][data-part='trigger'][data-xh-action-variant='solid']:focus-visible {
    --xh-action-ring-color-focus-visible: currentColor;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中。
     粗指针的 44px 命中区由配方的 ::after 给，字形占的是 ::before */
  [data-scope='back-top'][data-part='trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-up) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-up) center / contain no-repeat;
  }

  /* 配方声明过 display，会盖掉 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='back-top'][data-part='trigger'][hidden] {
    display: none;
  }

  @media print {
    /* 打印：回到顶部这颗钮只有在能滚的地方才成立，落到纸上是一颗按不动的按钮。 */
    [data-scope='back-top'][data-part='root'] {
      display: none;
    }
  }
}

/* styles/button-group.css */
/* 定义 button group 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='button-group'] {
    --xh-button-group-skin: 1;
  }

  /* 一组按钮连成一条：段与段之间不留缝，靠共边接上，所以不设 gap。
     排布只能读 data-orientation——role=group 不收 aria-orientation，连接层根本不输出它。
     圆角在容器上先收成 0，组内每段都取得到，两端的圆角再逐段补回来。

     排不下时这里不折行、也不自己翻成竖排，两条都是有意的：
     折行会把两端的圆角切在行末与行首——圆角只补在 :first-child 与 :last-child 上，
     中间那两个角是直角，一条焊死的按钮条断在半路。
     皮肤自己翻成竖排则会与 data-orientation 脱钩：合边的负外边距收哪个轴、
     两端圆角补哪一对角、连接层给分隔线派的朝向，三处全部由 data-orientation 决定，
     只有排布偷偷换了轴，线会横竖不对、角会补在错的两端。
     朝向由使用者显式给 orientation="vertical"，三处才一起换过去。 */
  [data-scope='button-group'][data-part='root'] {
    /* 组件内那几档层号只在自己人之间排序：建一个层叠上下文把它们关起来，
       既不让页面上的层号插进来，也不让它们漏出去压住别人 */
    isolation: isolate;

    /* 与下面几档同理，写私有槽而非 --xh-button-radius：
       后者是使用者的入口，写死它，进了组的胶囊按钮就再也圆不起来 */
    --xh-_button-group-radius: 0;

    /* 段与段共边焊成一条，solid 段静息不落贴地软影、悬停那一档不抬：抬起其中一段，投影会压到
       左右两段的面上。两档都只留实心面顶边那条高光；其余形态的影本来就是 none，这两支只被
       button.css 的 solid 块消费。颜色不在这里灌：段自带 data-xh-action-variant，底 / 前景 / 描边由
       家族形态矩阵按段自己的形态给出 */
    --xh-_button-group-shadow-rest: var(--xh-_highlight-tone);
    --xh-_button-group-shadow-hover: var(--xh-_highlight-tone);
    --xh-_group-separator-size: calc(var(--xh-_button-group-h, var(--xh-control-h-md)) / 2);

    display: inline-flex;
    align-items: stretch;
  }

  [data-scope='button-group'][data-part='root'][data-orientation='horizontal'] {
    flex-direction: row;
  }

  [data-scope='button-group'][data-part='root'][data-orientation='vertical'] {
    flex-direction: column;
  }

  /* 撑满行宽：整组占满可用宽度，每段等分剩余空间。inline-flex 改成 flex：行内盒撑不满一行 */
  [data-scope='button-group'][data-part='root'][data-full-width] {
    display: flex;
    inline-size: 100%;
  }

  /* 分隔线不参与等分：它有自己的厚度，跟着拉伸就成了一条粗带 */
  [data-scope='button-group'][data-part='root'][data-full-width] > *:not([data-xh-button-group-separator]) {
    flex: 1;
  }

  /* 给了 display 的角色节点必须补这条：display 声明会盖掉 UA 的 [hidden]{display:none}，
     不补的话作者给节点加 hidden 后它照样显示 */
  [data-scope='button-group'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 段间的线 —— */
  /* 装饰性的一条线，读屏不念。段本来靠共边连成一体，插了它就是把一排按钮分成几组。
     朝向是这条线自己的（横排里是竖线），与 root 的排布相反 */
  [data-scope='button-group'][data-part='root'] > [data-xh-button-group-separator] {
    flex: none;
    align-self: center;
    z-index: 1;
    border-radius: var(--xh-button-group-separator-radius, var(--xh-shape-pill));
    background: var(--xh-button-group-separator-color, var(--xh-fg-default));
    opacity: var(--xh-button-group-separator-opacity, var(--xh-control-separator-opacity));
    pointer-events: none;
    transition:
      background-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      opacity var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='button-group'][data-part='root'] > [data-xh-button-group-separator][data-orientation='vertical'] {
    inline-size: var(--xh-button-group-separator-thickness, var(--xh-stroke-thin));
    block-size: var(
      --xh-button-group-separator-size,
      var(--xh-_group-separator-size)
    );
    margin-inline-start: calc(-1 * var(--xh-button-group-separator-thickness, var(--xh-stroke-thin)));
  }

  [data-scope='button-group'][data-part='root'] > [data-xh-button-group-separator][data-orientation='horizontal'] {
    block-size: var(--xh-button-group-separator-thickness, var(--xh-stroke-thin));
    inline-size: var(
      --xh-button-group-separator-size,
      var(--xh-_group-separator-size)
    );
    margin-block-start: calc(-1 * var(--xh-button-group-separator-thickness, var(--xh-stroke-thin)));
  }

  /* 整组禁用：段真正的禁用由适配器落到每一段的原生 disabled 上，
     置灰的原生按钮不收指针事件，指针形状只能由这一层给 */
  [data-scope='button-group'][data-part='root'][data-disabled] {
    cursor: not-allowed;
  }

  /* 段都按不动了，段间那条线跟着退到弱边一档；换色按 micro 走一遍，
     与两侧那几段自己的禁用过渡同拍 */
  [data-scope='button-group'][data-part='root'] > [data-xh-button-group-separator][data-disabled] {
    background: var(--xh-button-group-separator-color-disabled, var(--xh-border-subtle));
    opacity: var(--xh-button-group-separator-opacity-disabled, var(--xh-control-separator-disabled-opacity));
  }

  @media (forced-colors: active) {
    /* 段间那条线画的是一块纯底色，这一档里底色被统一换成 Canvas，线整条消失，
       几组按钮就连成了一长串。换成前景色画回来 */
    [data-scope='button-group'][data-part='root'] > [data-xh-button-group-separator] {
      background: CanvasText;
    }

    [data-scope='button-group'][data-part='root'][data-variant='outline']::after {
      border-color: ButtonText;
    }
  }

  /* —— 尺寸 —— */
  /* 高度、内边距、间距、字号在容器上写一次，沿继承流给组内每一段。
     三档都写出来：自定义属性会一路继承，组里再套一组时内层不写就会沿用外层的档。
     写私有槽而非 --xh-button-*：后者是使用者的入口，组内某一枚自己写了档位时要压得住容器 */
  [data-scope='button-group'][data-part='root'][data-size='sm'] {
    --xh-_button-group-h: var(--xh-control-h-sm);
    --xh-_button-group-px: var(--xh-control-px-sm);
    --xh-_button-group-gap: var(--xh-control-gap-sm);
    --xh-_button-group-font-size: var(--xh-control-font-sm);
  }

  [data-scope='button-group'][data-part='root'][data-size='md'] {
    --xh-_button-group-h: var(--xh-control-h-md);
    --xh-_button-group-px: var(--xh-control-px-md);
    --xh-_button-group-gap: var(--xh-control-gap-md);
    --xh-_button-group-font-size: var(--xh-control-font-md);
  }

  [data-scope='button-group'][data-part='root'][data-size='lg'] {
    --xh-_button-group-h: var(--xh-control-h-lg);
    --xh-_button-group-px: var(--xh-control-px-lg);
    --xh-_button-group-gap: var(--xh-control-gap-lg);
    --xh-_button-group-font-size: var(--xh-control-font-lg);
  }

  /* —— 形态 —— */
  /* 组的形态由适配器下发到每一段（段自己写了的优先），段的颜色由家族形态矩阵给出；
     这里只定段间那条线在各档面上的颜色与浓淡，用哪族颜色由根上的 data-tone 决定 */
  [data-scope='button-group'][data-part='root'][data-variant='solid'] {
    --xh-button-group-separator-color: var(--xh-_tone-on, var(--xh-fg-on-brand));
    --xh-button-group-separator-opacity: 0.24;
  }

  [data-scope='button-group'][data-part='root'][data-variant='subtle'] {
    --xh-button-group-separator-color: var(--xh-_tone-fg, var(--xh-fg-default));
    --xh-button-group-separator-opacity: 0.16;
  }

  [data-scope='button-group'][data-part='root'][data-variant='outline'] {
    --xh-button-group-separator-color: var(--xh-_tone-border-control, var(--xh-border-control));
    --xh-button-group-separator-opacity: 1;

    position: relative;
    border-radius: var(--xh-button-group-radius, var(--xh-shape-control));
  }

  [data-scope='button-group'][data-part='root'][data-variant='outline']::after {
    content: '';
    position: absolute;
    z-index: 2;
    inset: 0;
    border: var(--xh-stroke-thin) solid
      var(--xh-button-group-outline-color, var(--xh-_tone-border-control, var(--xh-border-control)));
    border-radius: inherit;
    pointer-events: none;
  }

  [data-scope='button-group'][data-part='root'][data-variant='ghost'] {
    --xh-button-group-separator-color: var(--xh-_tone-fg, var(--xh-fg-default));
    --xh-button-group-separator-opacity: 0.16;
  }

  /* outline 的外框由组根统一绘制，组内每一段都不再各画一圈边框（段的形态矩阵描边被这一条压平）。 */
  [data-scope='button-group'][data-part='root'][data-variant='outline']
    > [data-scope='button'][data-part='root'],
  [data-scope='button-group'][data-part='root'][data-variant='outline']
    > * > [data-scope='button'][data-part='root'] {
    border-color: transparent;
  }

  /* —— 合边 —— */
  /* 相邻两段的边重合在同一像素上，谁的描边浮在上面必须能指定，
     因此每一段都是定位元素——静态元素的 z-index 不生效 */
  [data-scope='button-group'][data-part='root'] > * {
    position: relative;
  }

  /* 后一段往回挪一个描边宽度，相邻的两条边重合成一条。
     方向跟着 data-orientation 走，横排收 inline 轴、竖排收 block 轴。
     分隔线两侧不合边：那两段本来就是被这条线分开的，再压一次会把线盖掉一半 */
  [data-scope='button-group'][data-part='root'][data-orientation='horizontal']
    > *:not([data-xh-button-group-separator]) + *:not([data-xh-button-group-separator]) {
    margin-inline-start: calc(-1 * var(--xh-stroke-thin));
  }

  [data-scope='button-group'][data-part='root'][data-orientation='vertical']
    > *:not([data-xh-button-group-separator]) + *:not([data-xh-button-group-separator]) {
    margin-block-start: calc(-1 * var(--xh-stroke-thin));
  }

  /* 悬停或拿到焦点的那一段抬到最上层：焦点环画在元素外侧，
     不抬层就会被后一段的底色与描边盖掉一半 */
  [data-scope='button-group'][data-part='root'] > *:hover,
  [data-scope='button-group'][data-part='root'] > *:focus-within {
    z-index: 1;
  }

  /* 独立 Button 按下时缩一档；组内段却靠共边重叠一像素，单段缩放会同时撕开两侧接缝。
     组内仍保留 active 换底与撤高光，只把会改变外轮廓几何的 scale 收掉（允许的只换面）；
     键盘与触屏的按压由 Headless 投影 data-pressed，与指针 :active 同一档。 */
  [data-scope='button-group'][data-part='root']
    > [data-scope='button'][data-part='root']:not([data-disabled]):not([data-loading]):is(:active, [data-pressed]),
  [data-scope='button-group'][data-part='root']
    > * > [data-scope='button'][data-part='root']:not([data-disabled]):not([data-loading]):is(:active, [data-pressed]) {
    scale: none;
  }

  /* —— 两端圆角 —— */
  /* 逻辑角属性写，rtl 与竖排都跟着换边，不必另写一套。
     只认直接子节点：段之间插了别的节点时宁可退化成直角，也不要圆错位置 */
  [data-scope='button-group'][data-part='root'][data-orientation='horizontal'] > *:first-child,
  [data-scope='button-group'][data-part='root'][data-orientation='horizontal'] > *:first-child [data-scope='button'][data-part='root'] {
    border-start-start-radius: var(--xh-button-group-radius, var(--xh-shape-control));
    border-end-start-radius: var(--xh-button-group-radius, var(--xh-shape-control));
  }

  [data-scope='button-group'][data-part='root'][data-orientation='horizontal'] > *:last-child,
  [data-scope='button-group'][data-part='root'][data-orientation='horizontal'] > *:last-child [data-scope='button'][data-part='root'] {
    border-start-end-radius: var(--xh-button-group-radius, var(--xh-shape-control));
    border-end-end-radius: var(--xh-button-group-radius, var(--xh-shape-control));
  }

  [data-scope='button-group'][data-part='root'][data-orientation='vertical'] > *:first-child,
  [data-scope='button-group'][data-part='root'][data-orientation='vertical'] > *:first-child [data-scope='button'][data-part='root'] {
    border-start-start-radius: var(--xh-button-group-radius, var(--xh-shape-control));
    border-start-end-radius: var(--xh-button-group-radius, var(--xh-shape-control));
  }

  [data-scope='button-group'][data-part='root'][data-orientation='vertical'] > *:last-child,
  [data-scope='button-group'][data-part='root'][data-orientation='vertical'] > *:last-child [data-scope='button'][data-part='root'] {
    border-end-start-radius: var(--xh-button-group-radius, var(--xh-shape-control));
    border-end-end-radius: var(--xh-button-group-radius, var(--xh-shape-control));
  }
}

/* styles/descriptions.css */
/* 定义 descriptions 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='descriptions'] {
    --xh-descriptions-skin: 1;
  }

  [data-scope='descriptions'][data-part='root'] {
    /* 一个尺寸档只换这几个私有槽，每一格与格内两段都从根上继承它们，
       换档不必给每个部件各写一条选择器 */
    --xh-_descriptions-gap: var(--xh-space-3);
    /* 标签是每一格的集合标题：叠着排时与取值隔 space-2（集合标题与集合的间距） */
    --xh-_descriptions-pair-gap: var(--xh-space-2);
    --xh-_descriptions-label-gap: var(--xh-space-2);
    --xh-_descriptions-py: var(--xh-space-2);
    --xh-_descriptions-px: var(--xh-space-3);
    --xh-_descriptions-font-size: var(--xh-control-font-md);
    /* 标签在左时那一列的宽度：收到最长的那个标签 */
    --xh-_descriptions-label-w: max-content;

    display: grid;
    /* 不写 columns 即每行一组；二到六列各有一条规则 */
    grid-template-columns: minmax(0, 1fr);
    gap: var(--xh-descriptions-gap, var(--xh-_descriptions-gap));
    /* 根可能写成 dl，UA 的上下外边距在这里清掉 */
    margin: 0;
    color: var(--xh-descriptions-fg, var(--xh-fg-default));
    font-size: var(--xh-descriptions-font-size, var(--xh-_descriptions-font-size));
    line-height: var(--xh-text-body-leading);
  }

  /* 上面声明了 display，会盖掉 UA 的 [hidden] 规则，收起态要在这里接回来 */
  [data-scope='descriptions'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 列数 —— */
  [data-scope='descriptions'][data-part='root'][data-columns='2'] {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  [data-scope='descriptions'][data-part='root'][data-columns='3'] {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  [data-scope='descriptions'][data-part='root'][data-columns='4'] {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  [data-scope='descriptions'][data-part='root'][data-columns='5'] {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }

  [data-scope='descriptions'][data-part='root'][data-columns='6'] {
    grid-template-columns: repeat(6, minmax(0, 1fr));
  }

  /* —— 尺寸 —— */
  [data-scope='descriptions'][data-part='root'][data-size='sm'] {
    --xh-_descriptions-gap: var(--xh-space-2);
    --xh-_descriptions-py: var(--xh-space-1);
    --xh-_descriptions-px: var(--xh-space-2);
    --xh-_descriptions-font-size: var(--xh-control-font-sm);
  }

  [data-scope='descriptions'][data-part='root'][data-size='lg'] {
    --xh-_descriptions-gap: var(--xh-space-4);
    --xh-_descriptions-pair-gap: var(--xh-space-2);
    --xh-_descriptions-label-gap: var(--xh-space-3);
    --xh-_descriptions-py: var(--xh-space-3);
    --xh-_descriptions-px: var(--xh-space-4);
    --xh-_descriptions-font-size: var(--xh-control-font-lg);
  }

  /* —— 每一格 —— */
  /* 一格自己也是网格：不写 placement 即标签一行、取值一行叠着排。
     窄档每格横跨根上排定的所有列，一行只摆一组，作者写在格上的 span 这一档不认 */
  [data-scope='descriptions'][data-part='item'] {
    /* 作者写在这一格上的跨列数，由连接层落成这个槽；没写即一列 */
    --xh-_descriptions-item-span: 1;

    display: grid;
    grid-template-columns: minmax(0, 1fr);
    grid-column: 1 / -1;
    align-content: start;
    gap: var(--xh-descriptions-pair-gap, var(--xh-_descriptions-pair-gap));
  }

  [data-scope='descriptions'][data-part='label'] {
    color: var(--xh-descriptions-label-fg, var(--xh-fg-muted));
    font-weight: var(--xh-descriptions-label-font-weight, var(--xh-text-label-weight));
  }

  [data-scope='descriptions'][data-part='value'] {
    /* 取值可能写成 dd，UA 的左缩进在这里清掉 */
    margin: 0;
    /* 网格项默认不肯收到内容以下，这行让长文本能被压窄 */
    min-inline-size: 0;
    color: var(--xh-descriptions-value-fg, var(--xh-fg-default));
  }

  /* —— 形态：ghost 即基础规则，不画壳；outline 画外框与网格线 —— */
  [data-scope='descriptions'][data-part='root'][data-variant='outline'] {
    /* 网格线由每格自己的边线拼出来，格与格之间不能再留缝 */
    gap: 0;
    border: var(--xh-stroke-thin) solid var(--xh-descriptions-border, var(--xh-border-default));
    border-radius: var(--xh-descriptions-radius, var(--xh-shape-surface));
    background: var(--xh-descriptions-bg, var(--xh-bg-surface));
    /* 四角的格子要被圆角裁住 */
    overflow: hidden;
  }

  /* 每格自带上边线与左边线，行首与首行那几格再各自抹掉，相邻两格之间就只剩一条 */
  [data-scope='descriptions'][data-part='root'][data-variant='outline']
    > [data-scope='descriptions'][data-part='item'] {
    padding-block: var(--xh-descriptions-item-py, var(--xh-_descriptions-py));
    padding-inline: var(--xh-descriptions-item-px, var(--xh-_descriptions-px));
    border-block-start: var(--xh-stroke-thin) solid var(--xh-descriptions-divider, var(--xh-border-subtle));
    /* 每行一组时左边没有邻居，宽度按列数补回来 */
    border-inline-start: 0 solid var(--xh-descriptions-divider, var(--xh-border-subtle));
  }

  [data-scope='descriptions'][data-part='root'][data-variant='outline']
    > [data-scope='descriptions'][data-part='item']:first-child {
    border-block-start-width: 0;
  }

  /* 淡底档：不补网格线，surface 圆角 + subtle 底；描边留一圈透明边位，与 outline 同一几何 */
  [data-scope='descriptions'][data-part='root'][data-variant='subtle'] {
    border: var(--xh-stroke-thin) solid transparent;
    border-radius: var(--xh-descriptions-radius, var(--xh-shape-surface));
    background: var(--xh-descriptions-bg, var(--xh-bg-subtle));
    overflow: hidden;
  }

  /* —— 逐档的列数与边线 ——
     窄档一行只摆一组：每格的上边线就是行与行之间那条线，左边线用不上——
     上面那两条默认规则就是这一档的写法。
     宽起来以后逐档恢复：每一档写两件事，一是这一档一行摆几格（跨列数），
     二是这一档的边线：不在行首的格补上左边线，首行那几格抹掉上边线。
     两组集合逐档只增不减，宽档不必回收窄档写下的边线。 */
  @media (min-width: 768px) {
    /* 标签左置从这一档起生效：窄档一律标签在上，取值拿满整格的宽。
       只认自己的直接子格，套在取值里的另一份描述由它自己的根管 */
    [data-scope='descriptions'][data-part='root'][data-placement='left']
      > [data-scope='descriptions'][data-part='item'] {
      grid-template-columns: var(--xh-descriptions-label-w, var(--xh-_descriptions-label-w)) minmax(0, 1fr);
      align-items: baseline;
      column-gap: var(--xh-descriptions-label-gap, var(--xh-_descriptions-label-gap));
    }

    /* 二列与三列在这一档按作者写的列数摆，作者写在格上的 span 从这一档起认 */
    [data-scope='descriptions'][data-part='root'][data-columns='2']
      > [data-scope='descriptions'][data-part='item'],
    [data-scope='descriptions'][data-part='root'][data-columns='3']
      > [data-scope='descriptions'][data-part='item'] {
      grid-column: span var(--xh-_descriptions-item-span);
    }

    /* 四列与六列在这一档摆两列：一格横跨一半的轨道，作者写的 span 这一档同样不认——
       一行只有两格时，认了 span 的那格反而比邻居窄。
       五列没有能摆成两列等宽的跨列数，留在一列，到宽档再按作者的五列摆 */
    [data-scope='descriptions'][data-part='root'][data-columns='4']
      > [data-scope='descriptions'][data-part='item'] {
      grid-column: span 2;
    }

    [data-scope='descriptions'][data-part='root'][data-columns='6']
      > [data-scope='descriptions'][data-part='item'] {
      grid-column: span 3;
    }

    /* 一行两格：二、四、六列在这一档共用这套边线 */
    [data-scope='descriptions'][data-part='root'][data-variant='outline'][data-columns='2']
      > [data-scope='descriptions'][data-part='item']:not(:nth-child(2n + 1)),
    [data-scope='descriptions'][data-part='root'][data-variant='outline'][data-columns='4']
      > [data-scope='descriptions'][data-part='item']:not(:nth-child(2n + 1)),
    [data-scope='descriptions'][data-part='root'][data-variant='outline'][data-columns='6']
      > [data-scope='descriptions'][data-part='item']:not(:nth-child(2n + 1)) {
      border-inline-start-width: var(--xh-stroke-thin);
    }

    [data-scope='descriptions'][data-part='root'][data-variant='outline'][data-columns='2']
      > [data-scope='descriptions'][data-part='item']:nth-child(-n + 2),
    [data-scope='descriptions'][data-part='root'][data-variant='outline'][data-columns='4']
      > [data-scope='descriptions'][data-part='item']:nth-child(-n + 2),
    [data-scope='descriptions'][data-part='root'][data-variant='outline'][data-columns='6']
      > [data-scope='descriptions'][data-part='item']:nth-child(-n + 2) {
      border-block-start-width: 0;
    }

    /* 一行三格 */
    [data-scope='descriptions'][data-part='root'][data-variant='outline'][data-columns='3']
      > [data-scope='descriptions'][data-part='item']:not(:nth-child(3n + 1)) {
      border-inline-start-width: var(--xh-stroke-thin);
    }

    [data-scope='descriptions'][data-part='root'][data-variant='outline'][data-columns='3']
      > [data-scope='descriptions'][data-part='item']:nth-child(-n + 3) {
      border-block-start-width: 0;
    }
  }

  @media (min-width: 1024px) {
    /* 四、五、六列到这一档按作者写的列数摆，作者写在格上的 span 从这一档起认 */
    [data-scope='descriptions'][data-part='root'][data-columns='4']
      > [data-scope='descriptions'][data-part='item'],
    [data-scope='descriptions'][data-part='root'][data-columns='5']
      > [data-scope='descriptions'][data-part='item'],
    [data-scope='descriptions'][data-part='root'][data-columns='6']
      > [data-scope='descriptions'][data-part='item'] {
      grid-column: span var(--xh-_descriptions-item-span);
    }

    [data-scope='descriptions'][data-part='root'][data-variant='outline'][data-columns='4']
      > [data-scope='descriptions'][data-part='item']:not(:nth-child(4n + 1)) {
      border-inline-start-width: var(--xh-stroke-thin);
    }

    [data-scope='descriptions'][data-part='root'][data-variant='outline'][data-columns='4']
      > [data-scope='descriptions'][data-part='item']:nth-child(-n + 4) {
      border-block-start-width: 0;
    }

    [data-scope='descriptions'][data-part='root'][data-variant='outline'][data-columns='5']
      > [data-scope='descriptions'][data-part='item']:not(:nth-child(5n + 1)) {
      border-inline-start-width: var(--xh-stroke-thin);
    }

    [data-scope='descriptions'][data-part='root'][data-variant='outline'][data-columns='5']
      > [data-scope='descriptions'][data-part='item']:nth-child(-n + 5) {
      border-block-start-width: 0;
    }

    [data-scope='descriptions'][data-part='root'][data-variant='outline'][data-columns='6']
      > [data-scope='descriptions'][data-part='item']:not(:nth-child(6n + 1)) {
      border-inline-start-width: var(--xh-stroke-thin);
    }

    [data-scope='descriptions'][data-part='root'][data-variant='outline'][data-columns='6']
      > [data-scope='descriptions'][data-part='item']:nth-child(-n + 6) {
      border-block-start-width: 0;
    }
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='descriptions'][data-part='item'][hidden] {
    display: none;
  }
}

/* styles/diff-view.css */
/* 定义 diff view 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */
/* 独立皮肤同时传递引入折叠格按钮的动作控件配方；full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='diff-view'] {
    --xh-diff-view-skin: 1;
  }

  /* 一张静态内容面：--xh-border-default 描边 + surface 底 + 无影（边界只由描边承担）；
     头部、行号列与并排接缝的内部分隔线走另一支 --xh-diff-view-divider（subtle） */
  [data-scope='diff-view'][data-part='root'] {
    /* 作者塞进部件里的图标与皮肤画的兜底字形同一把尺：md 档，随 data-size 换档 */
    --xh-icon-size: var(--xh-diff-view-icon-size, var(--xh-glyph-size-md));

    /* 尺寸缺省档：不写 data-size 时的取值。三档都只写这三个私有槽，
       公开槽留在读处当首选，作者在祖先上设的覆盖才赢得过档位声明 */
    --xh-_diff-view-font-size: var(--xh-control-font-sm);
    --xh-_diff-view-px: var(--xh-space-3);
    --xh-_diff-view-py: var(--xh-space-2);

    display: block;
    overflow: hidden;
    border: var(--xh-stroke-thin) solid var(--xh-diff-view-border, var(--xh-border-default));
    border-radius: var(--xh-diff-view-radius, var(--xh-shape-surface));
    background: var(--xh-diff-view-bg, var(--xh-bg-surface));
    box-shadow: var(--xh-diff-view-shadow, none);
  }

  /* 上面声明的 display 会盖掉 UA 的 [hidden]{display:none}，这里补回 */
  [data-scope='diff-view'][data-part='root'][hidden] {
    display: none;
  }

  [data-scope='diff-view'][data-part='header'] {
    display: flex;
    align-items: center;
    gap: var(--xh-diff-view-header-gap, var(--xh-space-2));
    padding-inline: var(--xh-diff-view-px, var(--xh-_diff-view-px));
    padding-block: var(--xh-diff-view-py, var(--xh-_diff-view-py));
    border-block-end: var(--xh-stroke-thin) solid var(--xh-diff-view-divider, var(--xh-border-subtle));
    color: var(--xh-diff-view-header-fg, var(--xh-fg-muted));
    font-family: var(--xh-diff-view-font, var(--xh-font-family-mono));
    font-size: var(--xh-diff-view-header-font-size, var(--xh-text-secondary-size));
  }

  [data-scope='diff-view'][data-part='header'][hidden] {
    display: none;
  }

  /* 增删统计整组顶到右侧：头部是 flex，自动外边距吃掉中间的空当。
     第二个之后的不再顶，与前一个之间只留头部本来的间隙 */
  [data-scope='diff-view'][data-part='summary'] {
    margin-inline-start: auto;
  }

  [data-scope='diff-view'][data-part='summary'] ~ [data-scope='diff-view'][data-part='summary'] {
    margin-inline-start: 0;
  }

  [data-scope='diff-view'][data-part='summary'][data-change='added'] {
    color: var(--xh-diff-view-added-fg, var(--xh-diff-added-fg));
  }

  [data-scope='diff-view'][data-part='summary'][data-change='removed'] {
    color: var(--xh-diff-view-removed-fg, var(--xh-diff-removed-fg));
  }

  /* 唯一的 Tab 停靠点；两轴都可能溢出 */
  [data-scope='diff-view'][data-part='viewport'] {
    overflow: auto;
    max-block-size: var(--xh-diff-view-max-h, var(--xh-viewport-max-h));
  }

  [data-scope='diff-view'][data-part='body'] {
    display: block;
    font-family: var(--xh-diff-view-font, var(--xh-font-family-mono));
    font-size: var(--xh-diff-view-font-size, var(--xh-_diff-view-font-size));
    line-height: var(--xh-diff-view-line-height, var(--xh-text-code-leading));
    min-inline-size: max-content;
  }

  [data-scope='diff-view'][data-part='body'][hidden] {
    display: none;
  }

  /* 一行：行号与内容并排 */
  [data-scope='diff-view'][data-part='row'],
  [data-scope='diff-view'][data-part='gap'] {
    display: flex;
    min-block-size: var(--xh-diff-view-line-height, var(--xh-text-code-leading));
  }

  [data-scope='diff-view'][data-part='row'][hidden],
  [data-scope='diff-view'][data-part='gap'][hidden] {
    display: none;
  }

  /* 变更类型不只靠颜色：新增行画一条实心色条 */
  [data-scope='diff-view'][data-part='row'][data-change='added'] {
    background: var(--xh-diff-view-added-bg, var(--xh-diff-added-bg));
    box-shadow: inset var(--xh-diff-view-change-bar, var(--xh-stroke-thick)) 0 0 0 var(--xh-diff-view-added-fg, var(--xh-diff-added-fg));
  }

  /* 删除行的色条改画斜纹：与新增行的实心条在灰度与高对比度下也分得开。
     45 度、1.5px 实 1.5px 空是纹理几何，不是设计尺度上的档位 */
  [data-scope='diff-view'][data-part='row'][data-change='removed'] {
    background:
      repeating-linear-gradient(
          45deg,
          var(--xh-diff-view-removed-fg, var(--xh-diff-removed-fg)) 0,
          var(--xh-diff-view-removed-fg, var(--xh-diff-removed-fg)) 1.5px,
          transparent 1.5px,
          transparent 3px
        )
        left / var(--xh-diff-view-change-bar, var(--xh-stroke-thick)) 100% no-repeat,
      var(--xh-diff-view-removed-bg, var(--xh-diff-removed-bg));
  }

  /* 点开折叠格才露出来的那几行播一次入场；收起是硬切，不占一段退场窗口 */
  [data-scope='diff-view'][data-part='row'][data-revealed] {
    animation: xh-drop-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 行号是画上去的不是写上去的：复制差异不带它，读屏也不逐行念数字 */
  [data-scope='diff-view'][data-part='line-number'] {
    display: block;
    box-sizing: content-box;
    flex: 0 0 auto;
    padding-inline: var(--xh-diff-view-px, var(--xh-_diff-view-px));
    border-inline-end: var(--xh-stroke-thin) solid var(--xh-diff-view-divider, var(--xh-border-subtle));
    color: var(--xh-diff-view-number-fg, var(--xh-fg-subtle));
    inline-size: var(--xh-diff-view-gutter, 4ch);
    text-align: end;
    user-select: none;
  }

  [data-scope='diff-view'][data-part='line-number']::before {
    content: attr(data-line-number);
  }

  [data-scope='diff-view'][data-part='line-number'][hidden] {
    display: none;
  }

  /* 行号跟着行的变更类型走：一眼扫下来数字本身就分出了增删 */
  [data-scope='diff-view'][data-part='line-number'][data-change='added'] {
    color: var(--xh-diff-view-added-fg, var(--xh-diff-added-fg));
  }

  [data-scope='diff-view'][data-part='line-number'][data-change='removed'] {
    color: var(--xh-diff-view-removed-fg, var(--xh-diff-removed-fg));
  }

  /* 窄档的并排视图：一行的两侧改成上下两段，旧行在上、新行在下。
     行由横排 flex 换成两列栅格——行号一列、正文一列，一行里的四个格按 DOM 次序
     自然落成两行，正文列因此只按单侧的最长行撑宽，不再是两侧之和 */
  [data-scope='diff-view'][data-part='root'][data-view='split'] [data-part='row']:not([hidden]) {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
  }

  /* white-space: pre 保留缩进；每一侧各占一半宽 */
  [data-scope='diff-view'][data-part='line-content'] {
    display: block;
    flex: 1 1 0;
    min-inline-size: 0;
    padding-inline-end: var(--xh-diff-view-px, var(--xh-_diff-view-px));
    white-space: pre;
  }

  [data-scope='diff-view'][data-part='line-content'][hidden] {
    display: none;
  }

  [data-scope='diff-view'][data-part='line-content'][data-change='added'] {
    color: var(--xh-diff-view-added-fg, var(--xh-diff-added-fg));
  }

  [data-scope='diff-view'][data-part='line-content'][data-change='removed'] {
    color: var(--xh-diff-view-removed-fg, var(--xh-diff-removed-fg));
  }

  /* 并排视图里空的那一侧只有底色，没有内容 */
  [data-scope='diff-view'][data-part='line-content'][data-empty] {
    background: var(--xh-diff-view-empty-bg, var(--xh-bg-subtle));
  }

  /* 开了换行：pre-wrap 仍保留缩进与连续空白，只是允许行尾折下来；
     anywhere 让没有空格的长串（url、base64）也能断 */
  [data-scope='diff-view'][data-part='root'][data-wrap] [data-part='line-content'] {
    white-space: pre-wrap;
    overflow-wrap: anywhere;
  }

  /* 正文原本按最长行撑宽，不解除就折不下来 */
  [data-scope='diff-view'][data-part='root'][data-wrap] [data-part='body'] {
    min-inline-size: 0;
  }

  /* 变更类型的读屏文字：视觉隐藏，不能 display:none——那样读屏就取不到它了。
     变更不该只靠颜色传达 */
  [data-scope='diff-view'][data-part='change-label'] {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    border: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* 词级片段：只有真正动过的那几段上底色，其余段落是纯包裹。
     不给内衬——等宽列要逐字对齐，多一像素整份差异就错位 */
  [data-scope='diff-view'][data-part='inline-change'][data-change] {
    border-radius: var(--xh-diff-view-inline-change-radius, var(--xh-shape-inset));
    /* 片段跨行时两半各自收边，否则圆角只画在整段的首尾。两条都写：WebKit 只认带前缀那条 */
    -webkit-box-decoration-break: clone;
    box-decoration-break: clone;
  }

  [data-scope='diff-view'][data-part='inline-change'][data-change='added'] {
    background: color-mix(in oklab, var(--xh-diff-view-added-fg, var(--xh-diff-added-fg)) 18%, transparent);
  }

  [data-scope='diff-view'][data-part='inline-change'][data-change='removed'] {
    background: color-mix(in oklab, var(--xh-diff-view-removed-fg, var(--xh-diff-removed-fg)) 18%, transparent);
  }

  [data-scope='diff-view'][data-part='token'][data-kind='comment'] {
    color: var(--xh-diff-view-comment-fg, var(--xh-fg-muted));
    font-style: italic;
  }

  [data-scope='diff-view'][data-part='token'][data-kind='string'] {
    color: var(--xh-diff-view-string-fg, var(--xh-syntax-string));
  }

  [data-scope='diff-view'][data-part='token'][data-kind='number'] {
    color: var(--xh-diff-view-number-token-fg, var(--xh-syntax-number));
  }

  [data-scope='diff-view'][data-part='token'][data-kind='keyword'] {
    color: var(--xh-diff-view-keyword-fg, var(--xh-syntax-keyword));
    font-weight: var(--xh-diff-view-keyword-weight, var(--xh-font-weight-semibold));
  }

  [data-scope='diff-view'][data-part='token'][data-kind='punctuation'] {
    color: var(--xh-diff-view-punctuation-fg, var(--xh-fg-subtle));
  }

  /* 折起来的那一行：整行都是展开按钮。行是淡底承载面，向按钮下发 hover 200 → pressed 300 */
  [data-scope='diff-view'][data-part='gap'] {
    --xh-action-host-bg-hover: var(--xh-bg-subtle-hover);
    --xh-action-host-bg-pressed: var(--xh-bg-subtle-active);

    background: var(--xh-diff-view-gap-bg, var(--xh-bg-subtle));
  }

  [data-scope='diff-view'][data-part='gap-cell'] {
    display: block;
    flex: 1 1 auto;
  }

  [data-scope='diff-view'][data-part='gap-cell'][hidden] {
    display: none;
  }

  /* 展开按钮铺满折叠格，盒型、悬停与按下面由 Action Control 的 disclosure-trigger 档给（ghost 形态，
     按下只换面不缩放）；这里只把使用者槽映射到桥接槽：圆角归零贴住格边、纵向内衬归零、
     高度锚在代码行高上让折叠格与相邻代码行同高，字号跟着正文走 */
  [data-scope='diff-view'][data-part='gap-trigger'] {
    --xh-action-radius: 0;
    --xh-action-visual-size: var(--xh-diff-view-line-height, var(--xh-text-code-leading));
    --xh-action-padding-inline: var(--xh-diff-view-px, var(--xh-_diff-view-px));
    --xh-action-padding-block: 0;
    --xh-action-font-size: var(--xh-diff-view-font-size, var(--xh-_diff-view-font-size));
    --xh-action-fg-rest: var(--xh-diff-view-gap-fg, var(--xh-fg-muted));
    --xh-action-bg-hover: var(--xh-diff-view-gap-bg-hover, var(--xh-_action-variant-bg-hover));

    border-width: 0;
  }

  [data-scope='diff-view'][data-part='gap-trigger'][hidden] {
    display: none;
  }

  [data-scope='diff-view'][data-part='empty'] {
    display: block;
    padding-inline: var(--xh-diff-view-px, var(--xh-_diff-view-px));
    padding-block: var(--xh-diff-view-py, var(--xh-_diff-view-py));
    color: var(--xh-diff-view-empty-fg, var(--xh-fg-muted));
    font-size: var(--xh-diff-view-header-font-size, var(--xh-text-secondary-size));
  }

  [data-scope='diff-view'][data-part='empty'][hidden] {
    display: none;
  }

  /* 截断提示条：这份差异不完整。它比 empty 显眼一档——空差异只是没东西可看，
     被砍过的差异看着像完整的，读的人不主动往这儿看就不会知道 */
  [data-scope='diff-view'][data-part='truncation'] {
    display: flex;
    align-items: center;
    gap: var(--xh-diff-view-truncation-gap, var(--xh-space-2));
    padding-inline: var(--xh-diff-view-px, var(--xh-_diff-view-px));
    padding-block: var(--xh-diff-view-py, var(--xh-_diff-view-py));
    border-block-start: var(--xh-stroke-thin) solid
      var(--xh-diff-view-truncation-border, var(--xh-border-subtle));
    background: var(--xh-diff-view-truncation-bg,
      color-mix(in oklab, var(--xh-fg-warning) 12%, var(--xh-bg-surface)));
    color: var(--xh-diff-view-truncation-fg,
      color-mix(in oklab, var(--xh-fg-warning) 60%, var(--xh-fg-default)));
    font-size: var(--xh-diff-view-header-font-size, var(--xh-text-secondary-size));
  }

  [data-scope='diff-view'][data-part='truncation'][hidden] {
    display: none;
  }

  /* 提示条的文字由适配器填，所以字形不走 :empty 那条兜底路径，恒画一枚；
     不要它就把 --xh-glyph-mark-warning 在子树上置 none */
  [data-scope='diff-view'][data-part='truncation']::before {
    content: '';
    flex: none;
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-warning) center / contain no-repeat;
    mask: var(--xh-glyph-mark-warning) center / contain no-repeat;
  }

  /* 尺寸档改字号、内衬与图标档 */
  [data-scope='diff-view'][data-part='root'][data-size='sm'] {
    --xh-icon-size: var(--xh-diff-view-icon-size, var(--xh-glyph-size-sm));
    --xh-_diff-view-font-size: var(--xh-control-font-sm);
    --xh-_diff-view-px: var(--xh-space-2);
    --xh-_diff-view-py: var(--xh-space-1);
  }

  [data-scope='diff-view'][data-part='root'][data-size='md'] {
    --xh-_diff-view-font-size: var(--xh-control-font-md);
    --xh-_diff-view-px: var(--xh-space-3);
    --xh-_diff-view-py: var(--xh-space-2);
  }

  [data-scope='diff-view'][data-part='root'][data-size='lg'] {
    --xh-icon-size: var(--xh-diff-view-icon-size, var(--xh-glyph-size-lg));
    --xh-_diff-view-font-size: var(--xh-control-font-lg);
    --xh-_diff-view-px: var(--xh-space-4);
    --xh-_diff-view-py: var(--xh-space-3);
  }

  /* 宽档：视口放得下两列，并排视图回到一行两侧 */
  @media (min-width: 1024px) {
    [data-scope='diff-view'][data-part='root'][data-view='split'] [data-part='row']:not([hidden]) {
      display: flex;
    }

    /* 两列之间的接缝：新侧的行号槽再补一条左边线。只在并排时是接缝，
       堆叠时它落在段首，成了一条与任何东西都不相接的竖线 */
    [data-scope='diff-view'][data-part='root'][data-view='split'] [data-part='line-number'][data-side='new'] {
      border-inline-start: var(--xh-stroke-thin) solid var(--xh-diff-view-divider, var(--xh-border-subtle));
    }
  }

  /*
   * 高对比档：新增行那条实心色条写在 box-shadow 上、删除行那条斜纹写在渐变上，
   * 这一档里两者一起被丢弃，只剩两个被系统换成同色的底。
   * 改画两圈内收的环，实线对新增、虚线对删除，两档在纯系统色下仍分得开。
   * 用 outline 不用 border：行是横排 flex，加边会把行号与内容一起往里推，
   * 没有变更的行不加边，同一屏上的行首就对不齐了。
   */
  @media (forced-colors: active) {
    [data-scope='diff-view'][data-part='row'][data-change='added'] {
      outline: var(--xh-stroke-thick) solid CanvasText;
      outline-offset: calc(-1 * var(--xh-stroke-thick));
    }

    [data-scope='diff-view'][data-part='row'][data-change='removed'] {
      outline: var(--xh-stroke-thick) dashed CanvasText;
      outline-offset: calc(-1 * var(--xh-stroke-thick));
    }
  }

  /*
   * 打印：底色与背景图一起被丢掉，新增行那条实心色条写在 box-shadow 上、
   * 删除行那条斜纹写在渐变上，两者在纸上都不出现，两种变更就此糊成一样。
   * 与高对比档同一套办法：实线环对新增、虚线环对删除，都是印得出来的通道。
   */
  @media print {
    [data-scope='diff-view'][data-part='row'][data-change='added'] {
      outline: var(--xh-stroke-thick) solid currentColor;
      outline-offset: calc(-1 * var(--xh-stroke-thick));
    }

    [data-scope='diff-view'][data-part='row'][data-change='removed'] {
      outline: var(--xh-stroke-thick) dashed currentColor;
      outline-offset: calc(-1 * var(--xh-stroke-thick));
    }
  }
}

/* styles/download-trigger.css */
/* 定义 download trigger 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.motion {
  /* 取数在途时文字原位隐去，只换前景色，不动布局 */
  @keyframes xh-download-trigger-content-hide {
    to {
      color: transparent;
    }
  }
}

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='download-trigger'] {
    --xh-download-trigger-skin: 1;
  }

  /*
   * 触发器就是这一个原生按钮，是定尺的独立动作按钮：盒型、三档几何、四态面、0.97 按压与粗指针
   * 命中区由家族配方按 data-xh-action-variant / -size 给出（缺省 subtle 由连接层显式投影，只有 solid 才品牌实心）。
   * 这里只把公开槽桥接到矩阵之前（使用者槽 → 形态矩阵 → 家族缺省）与几何槽映射；
   * 要换成品牌样式的作者改 --xh-download-trigger-* 这一族槽位，或直接写自己的类名。
   */
  [data-scope='download-trigger'][data-part='root'] {
    --xh-action-bg-rest: var(--xh-download-trigger-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-download-trigger-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-download-trigger-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-bg-focus-visible: var(--xh-download-trigger-bg, var(--xh-_action-variant-bg-focus-visible));
    --xh-action-bg-loading: var(--xh-download-trigger-bg, var(--xh-_action-variant-bg-loading));
    --xh-action-bg-disabled: var(--xh-download-trigger-bg-disabled, var(--xh-_action-variant-bg-disabled));
    --xh-action-fg-rest: var(--xh-download-trigger-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-download-trigger-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-download-trigger-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-fg-focus-visible: var(--xh-download-trigger-fg, var(--xh-_action-variant-fg-focus-visible));
    --xh-action-fg-loading: var(--xh-download-trigger-fg, var(--xh-_action-variant-fg-loading));
    --xh-action-border-rest: var(--xh-download-trigger-border, var(--xh-_action-variant-border-rest));
    --xh-action-border-hover: var(--xh-download-trigger-border-hover, var(--xh-_action-variant-border-hover));
    --xh-action-border-pressed: var(--xh-download-trigger-border-hover, var(--xh-_action-variant-border-pressed));
    --xh-action-border-focus-visible: var(--xh-download-trigger-border, var(--xh-_action-variant-border-focus-visible));
    --xh-action-border-disabled: var(--xh-download-trigger-border-disabled, var(--xh-_action-variant-border-disabled));
    /* 矩阵各态无影（淡底与阴影互斥）：solid 也不再悬停抬影，使用者槽仍可自行加 */
    --xh-action-shadow-hover: var(--xh-download-trigger-shadow-hover, none);
    --xh-action-radius: var(--xh-download-trigger-radius, var(--xh-shape-control));
    --xh-action-visual-size: var(--xh-download-trigger-h, var(--xh-_action-profile-visual-size));
    --xh-action-padding-inline: var(--xh-download-trigger-px, var(--xh-_action-profile-padding-inline));
    --xh-action-gap: var(--xh-download-trigger-gap, var(--xh-_action-profile-gap));
    --xh-action-font-size: var(--xh-download-trigger-font-size, var(--xh-_action-profile-font-size));
    /* 作者塞进来的图标跟着尺寸档走，与皮肤画的兜底字形同一把尺 */
    --xh-icon-size: var(--xh-download-trigger-icon-size, var(--xh-_action-profile-glyph-size));
    /* 取数在途那枚圆环的颜色：字被 content-hide 关键帧压成透明，环不能跟着 currentColor 走，取加载态的前景 */
    --xh-_download-trigger-loading-fg: var(--xh-download-trigger-loading-fg, var(--xh-download-trigger-fg, var(--xh-_action-variant-fg-loading)));

    /* safe：文案放不下时居中改成靠行首排，裁掉的是末尾那截，开头仍然读得到 */
    justify-content: safe center;
    font-weight: var(--xh-download-trigger-font-weight, var(--xh-text-label-weight));
    /* 文案比所在那一栏还长时，按钮的盒收到栏宽为止，多出来的字在行内一轴裁掉，
       整颗按钮不再撑破侧栏。块轴留 visible：粗指针那一档的命中区是往块轴外扩的伪元素 */
    max-inline-size: 100%;
    overflow-x: clip;
    /* 导出键常被连点，触屏上默认会当成双击缩放 */
    touch-action: manipulation;
  }

  /* 上面声明了 display，会盖掉 UA 的 [hidden] 规则，收起态要在这里接回来 */
  [data-scope='download-trigger'][data-part='root'][hidden] {
    display: none;
  }

  /* 面是实心的，环色与面同族，画在面里就看不出来；环改取面自己的前景色——
     那一族色本来就要在这块面上把字读清楚，与面的对比是按可读性定的 */
  [data-scope='download-trigger'][data-part='root'][data-xh-action-variant='solid']:focus-visible {
    --xh-action-ring-color-focus-visible: currentColor;
  }

  /* 没写内容就由皮肤画兜底字形；作者往按钮里塞了文字或自己的图形，这几条即不命中。
     字形另起一颗 ::after：::before 是转圈那枚圆环的方框，mask 会把描边裁成字形轮廓、圆环就此消失。
     取数在途那一档不画字形，那一格让给圆环 */
  [data-scope='download-trigger'][data-part='root']:empty:not([aria-busy='true'])::after {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-download) center / contain no-repeat;
    mask: var(--xh-glyph-mark-download) center / contain no-repeat;
  }

  /* 快速取数不显示瞬时圆环；超过一个 micro 周期后才在原位换成加载状态。 */
  [data-scope='download-trigger'][data-part='root'][data-state='preparing'][aria-busy='true'] {
    cursor: progress;
    animation: xh-download-trigger-content-hide var(--xh-motion-duration-micro) var(--xh-motion-ease-enter)
      var(--xh-motion-duration-micro) forwards;
  }

  [data-scope='download-trigger'][data-part='root'][aria-busy='true']::before {
    content: '';
    position: absolute;
    inset: 0;
    inline-size: 1em;
    block-size: 1em;
    margin: auto;
    border: var(--xh-stroke-thin) solid transparent;
    border-block-start-color: var(--xh-_download-trigger-loading-fg);
    /* 正圆的加载环：正方盒取 circle */
    border-radius: var(--xh-shape-circle);
    opacity: 0;
    animation:
      xh-spin var(--xh-download-trigger-loading-duration, var(--xh-spin-duration)) var(--xh-motion-ease-loop) infinite,
      xh-fade-in var(--xh-motion-duration-micro) var(--xh-motion-ease-enter) var(--xh-motion-duration-micro) forwards;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-scope='download-trigger'][data-part='root'][aria-busy='true'] {
      color: transparent;
      animation: none;
    }

    [data-scope='download-trigger'][data-part='root'][aria-busy='true']::before {
      border-style: dotted;
      border-color: var(--xh-_download-trigger-loading-fg);
      opacity: 1;
      animation: none;
    }
  }

  :where([data-motion='reduce']) [data-scope='download-trigger'][data-part='root'][aria-busy='true'] {
    color: transparent;
    animation: none;
  }

  :where([data-motion='reduce']) [data-scope='download-trigger'][data-part='root'][aria-busy='true']::before {
    border-style: dotted;
    border-color: var(--xh-_download-trigger-loading-fg);
    opacity: 1;
    animation: none;
  }

  /* 手指落点：配方 text 档用 ::after 把块轴命中区扩到 44px；没写内容的按钮 ::after 已被兜底字形占着，
     这一档改用当时空着的 ::before 扩——取数在途时字形不画、::before 是圆环，配方的 ::after 又能落下来，
     两颗伪元素轮着用。字形那条只写了尺寸与 mask，配方的定位、44px 下限与 -50% 平移会从同一个
     ::after 漏进来：字形被拎出行内流、盒撑到 44px 高，按钮随之收窄一格字形——这里逐项钉回 */
  @media (pointer: coarse) {
    [data-scope='download-trigger'][data-part='root']:empty:not([aria-busy='true'])::after {
      position: static;
      min-block-size: 0;
      translate: none;
    }

    [data-scope='download-trigger'][data-part='root']:empty:not([aria-busy='true'])::before {
      content: '';
      position: absolute;
      inset-block-start: 50%;
      inset-inline-start: 50%;
      min-block-size: 44px;
      inline-size: 100%;
      block-size: 100%;
      translate: -50% -50%;
    }

    /* 与家族同一笔：起点是逻辑属性、平移是物理通道，rtl 下行内分量掉头，热区才落回按钮中心 */
    [data-scope='download-trigger'][data-part='root']:empty:not([aria-busy='true']):dir(rtl)::before {
      translate: 50% -50%;
    }
  }
}

/* styles/field-array.css */
/* 定义 field array 样式。 */

/* FieldArray 独立皮肤同时传递引入把手的动作控件配方；full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='field-array'] {
    --xh-field-array-skin: 1;
  }

  /* 一行一条，纵向堆叠；新增把手跟在最后一行下面 */
  [data-scope='field-array'][data-part='root'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-field-array-gap, var(--xh-space-2));
  }

  /* 声明了 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='field-array'][data-part='root'][hidden] {
    display: none;
  }

  /* 内容在左、把手在右，把手那一列不随内容伸缩 */
  [data-scope='field-array'][data-part='item'] {
    display: flex;
    align-items: center;
    gap: var(--xh-field-array-item-gap, var(--xh-space-2));
    padding: var(--xh-field-array-item-padding, var(--xh-space-0));
    border-radius: var(--xh-field-array-item-radius, var(--xh-shape-surface));
  }

  [data-scope='field-array'][data-part='item'][hidden] {
    display: none;
  }

  /* 行前的行号或名目：不参与分宽，弱一档前景把它与行里的内容分开 */
  [data-scope='field-array'][data-part='item-label'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    color: var(--xh-field-array-item-label-fg, var(--xh-fg-muted));
    font-size: var(--xh-field-array-item-label-font-size, var(--xh-text-secondary-size));
    line-height: var(--xh-leading-none);
    white-space: nowrap;
  }

  [data-scope='field-array'][data-part='item-label'][hidden] {
    display: none;
  }

  /* 行里放什么控件归作者，这里只给它一条能撑开也能收窄的轨道。
     min-inline-size 归零：不写的话里面的输入框按 UA 默认宽度顶住，长内容会把整行撑破 */
  [data-scope='field-array'][data-part='item-content'] {
    display: flex;
    flex: 1 1 auto;
    align-items: center;
    gap: var(--xh-field-array-content-gap, var(--xh-space-2));
    min-inline-size: 0;
  }

  [data-scope='field-array'][data-part='item-action'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    gap: var(--xh-field-array-action-gap, var(--xh-space-1));
  }

  /* —— 行内三个把手 ——
     只有字形的离散动作钮：盒几何、悬停 / 按下与 0.97 按压、粗指针热区、焦点环、禁用面全由 Action Control 的
     icon ghost 档给（连接层投 xs：24px 正方盒，行级把手贴着一个控件高的行，取行内动作钮那一档），
     组件只映射既有使用者槽。静息透明，白底承载 hover 100 → pressed 200。
     按不动的把手由连接层同时打 aria-disabled 与 data-disabled，家族按后者收掉悬停与按下反馈 */
  [data-scope='field-array'][data-part='item-delete-trigger'],
  [data-scope='field-array'][data-part='move-up-trigger'],
  [data-scope='field-array'][data-part='move-down-trigger'] {
    --xh-action-visual-size: var(--xh-field-array-trigger-size, var(--xh-_action-profile-visual-size));
    --xh-action-min-inline-size: var(--xh-field-array-trigger-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-field-array-trigger-radius, var(--xh-shape-control));
    --xh-action-bg-rest: var(--xh-field-array-trigger-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-field-array-trigger-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-field-array-trigger-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-field-array-trigger-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-field-array-trigger-fg-hover, var(--xh-fg-default));
    --xh-action-fg-pressed: var(--xh-field-array-trigger-fg-hover, var(--xh-fg-default));
    --xh-action-border-rest: transparent;
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    --xh-action-font-size: var(--xh-field-array-trigger-font-size, var(--xh-text-secondary-size));
    /* 作者塞进把手的图标与皮肤画的兜底字形同一把尺：按档取字形尺寸。
       配方尚未把 profile 字形档灌进 --xh-icon-size，钮内字形先按 icon 档逐钮取值 */
    --xh-icon-size: var(--xh-field-array-icon-size, var(--xh-_action-profile-glyph-size));

    border-width: 0;
  }

  /* 不换序时连接层给换序把手写 hidden；家族那条 display 会把 UA 的 [hidden]{display:none}
     盖掉，少了这条把手还留在原地。删除把手同样声明了 display，作者自己收起它时要的是同一条 */
  [data-scope='field-array'][data-part='item-delete-trigger'][hidden],
  [data-scope='field-array'][data-part='move-up-trigger'][hidden],
  [data-scope='field-array'][data-part='move-down-trigger'][hidden] {
    display: none;
  }

  /* 删除把手悬停转危险色：它是这一行里唯一不可撤销的动作 */
  [data-scope='field-array'][data-part='item-delete-trigger'] {
    --xh-action-fg-hover: var(--xh-field-array-item-delete-fg-hover, var(--xh-fg-danger-hover));
    --xh-action-fg-pressed: var(--xh-field-array-item-delete-fg-hover, var(--xh-fg-danger-hover));
  }

  /* —— 新增把手 ——
     带文案的离散动作钮，走 text outline 档（中性描边、透明底，hover 100 → pressed 200），高一个控件；
     虚线描边把它和行里的实心控件区分开：它加的是行，不是行里的值——家族只写 border-color，线型由这里给 */
  [data-scope='field-array'][data-part='add-trigger'] {
    --xh-action-visual-size: var(--xh-field-array-add-height, var(--xh-_action-profile-visual-size));
    --xh-action-padding-inline: var(--xh-field-array-add-px, var(--xh-_action-profile-padding-inline));
    --xh-action-gap: var(--xh-field-array-action-gap, var(--xh-space-1));
    --xh-action-radius: var(--xh-field-array-add-radius, var(--xh-shape-control));
    --xh-action-bg-rest: var(--xh-field-array-add-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-field-array-add-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-field-array-add-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-field-array-add-fg, var(--xh-fg-brand));
    --xh-action-fg-hover: var(--xh-field-array-add-fg, var(--xh-fg-brand));
    --xh-action-fg-pressed: var(--xh-field-array-add-fg, var(--xh-fg-brand));
    --xh-action-border-rest: var(--xh-field-array-add-border, var(--xh-_action-variant-border-rest));
    --xh-action-border-hover: var(--xh-field-array-add-border-hover, var(--xh-_action-variant-border-hover));
    --xh-action-border-disabled: var(--xh-field-array-add-border-disabled, var(--xh-_action-variant-border-disabled));
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    --xh-action-font-size: var(--xh-field-array-add-font-size, var(--xh-text-label-size));
    --xh-icon-size: var(--xh-field-array-icon-size, var(--xh-_action-profile-glyph-size));

    align-self: flex-start;
    border-style: dashed;
  }

  [data-scope='field-array'][data-part='add-trigger'][hidden] {
    display: none;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中 */
  [data-scope='field-array'][data-part='move-up-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-up) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-up) center / contain no-repeat;
  }

  [data-scope='field-array'][data-part='move-down-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
  }

  [data-scope='field-array'][data-part='item-delete-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='field-array'][data-part='item-content'][hidden],
  [data-scope='field-array'][data-part='item-action'][hidden] {
    display: none;
  }
}

/* styles/fieldset.css */
/* 定义 fieldset 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='fieldset'] {
    --xh-fieldset-skin: 1;
  }

  /* 抹掉 UA 给 <fieldset> 的边框、内外边距与 min-content 下限，间距全部改由令牌给。
     display 落在 fieldset 的匿名内容盒上：首个 <legend> 不在这个盒子里，
     所以 gap 只作用于组内各块，legend 与内容之间的留白由 legend 自己的下外边距给。 */
  [data-scope='fieldset'][data-part='root'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-fieldset-gap, var(--xh-space-4));
    margin: 0;
    border: 0;
    padding: 0;
    min-inline-size: 0;
  }

  [data-scope='fieldset'][data-part='root'][hidden] {
    display: none;
  }

  [data-scope='fieldset'][data-part='legend'] {
    padding: 0;
    margin-block-end: var(--xh-fieldset-legend-gap, var(--xh-space-2));
    /* 组标题是「一组字段的标题」，归集合标题角色：fg-muted，与组 --xh-space-2，字号字重同字段标签 */
    color: var(--xh-fieldset-legend-fg, var(--xh-fg-muted));
    font-size: var(--xh-fieldset-legend-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-fieldset-legend-font-weight, var(--xh-text-label-weight));
    line-height: var(--xh-leading-tight);
    /* 整组转无效或转禁用时组标题换色，两档之间接一段过渡 */
    transition: color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 整组无效时组标题转警示色：没渲染错误文案的字段集上，这是屏幕上唯一变化的东西。
     默认色在 label.css 公共层，这里只把颜色接到本组件的覆盖槽上 */
  [data-scope='fieldset'][data-part='legend'][data-invalid] {
    color: var(--xh-fieldset-legend-fg-invalid, var(--xh-fg-danger));
  }

  /* 整组禁用时组标题跟着变淡；组内控件由原生 fieldset[disabled] 各自呈现禁用态。
     选择器权重高于上一条且排在后面，禁用与无效同时为真时以禁用为准。 */
  [data-scope='fieldset'][data-part='root'] > [data-scope='fieldset'][data-part='legend'][data-disabled] {
    color: var(--xh-fieldset-legend-fg-disabled, var(--xh-fg-subtle));
  }

  /* 必填星号的字形、间距与默认色在 label.css 公共层；这里只把颜色接到本组件的覆盖槽上 */
  [data-scope='fieldset'][data-part='legend'][data-required]::after {
    color: var(--xh-fieldset-legend-star, var(--xh-fg-danger));
  }

  /* 说明与错误文案的角色（外边距、行距、默认字号与字色）在 description.css 公共层；
     这里只把字色与字号接到本组件的覆盖槽上 */
  [data-scope='fieldset'][data-part='description'] {
    color: var(--xh-fieldset-description-fg, var(--xh-fg-muted));
    font-size: var(--xh-fieldset-description-font-size, var(--xh-text-secondary-size));
    /* 与组标题同一档过渡：整组转禁用时两处一起变淡 */
    transition: color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='fieldset'][data-part='description'][data-disabled] {
    color: var(--xh-fieldset-description-fg-disabled, var(--xh-fg-subtle));
  }

  /* 并排字段的一段：窄屏一列，够宽了按列宽自动分栏。列宽下限由槽给，作者按字段类型改 */
  [data-scope='fieldset'][data-part='field-group'] {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(var(--xh-fieldset-field-group-col-w, var(--xh-layout-col-min-sm)), 1fr));
    gap: var(--xh-fieldset-field-group-gap, var(--xh-space-3));
    align-items: start;
  }

  [data-scope='fieldset'][data-part='field-group'][hidden] {
    display: none;
  }

  /* 组末尾那一行按钮：靠尾端排，窄屏换行 */
  [data-scope='fieldset'][data-part='actions'] {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-end;
    gap: var(--xh-fieldset-actions-gap, var(--xh-space-2));
  }

  [data-scope='fieldset'][data-part='actions'][hidden] {
    display: none;
  }

  [data-scope='fieldset'][data-part='error-text'] {
    color: var(--xh-fieldset-error-fg, var(--xh-fg-danger));
    font-size: var(--xh-fieldset-error-font-size, var(--xh-text-secondary-size));
  }
}

/* styles/flex.css */
/* 定义 flex 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='flex'] {
    --xh-flex-skin: 1;
  }

  [data-scope='flex'][data-part='root'] {
    display: flex;
    flex-wrap: nowrap;
    /* 不写 gap 档位就不留间距；使用者槽位排在档位之前，写死一个值即盖过所有档 */
    gap: var(--xh-flex-gap, var(--xh-space-0));
  }

  /* 行内盒：宽度收到内容，能和文字排在同一行 */
  [data-scope='flex'][data-part='root'][data-inline] {
    display: inline-flex;
  }

  /* 分隔符：夹在两个子项之间的装饰件，样子由放进去的内容决定。
     这里只兜住两件事——不被主轴挤扁（一条 1px 的竖线会被弹性收缩吃没），
     交叉轴上不单独发话，跟着容器的对齐走：横排随中线、竖排随拉伸 */
  [data-scope='flex'][data-part='split'] {
    flex: none;
  }

  /* —— 方向与缺省对齐 —— */
  /* 横排时按中线对齐：一排里混着文字、按钮、标签，高度本就不齐，居中最不容易看出错位 */
  [data-scope='flex'][data-part='root'][data-orientation='horizontal'] {
    flex-direction: row;
    align-items: center;
  }

  /* 竖排时拉伸：一列里的块级子项该占满容器宽度 */
  [data-scope='flex'][data-part='root'][data-orientation='vertical'] {
    flex-direction: column;
    align-items: stretch;
  }

  /* —— 折行 —— */
  [data-scope='flex'][data-part='root'][data-wrap] {
    flex-wrap: wrap;
  }

  /* —— 交叉轴对齐 —— */
  /* 排在方向之后：两者特指度相同，写了 align 就该压过随方向来的那份缺省 */
  [data-scope='flex'][data-part='root'][data-align='start'] {
    align-items: flex-start;
  }

  [data-scope='flex'][data-part='root'][data-align='center'] {
    align-items: center;
  }

  [data-scope='flex'][data-part='root'][data-align='end'] {
    align-items: flex-end;
  }

  [data-scope='flex'][data-part='root'][data-align='stretch'] {
    align-items: stretch;
  }

  [data-scope='flex'][data-part='root'][data-align='baseline'] {
    align-items: baseline;
  }

  /* —— 主轴分布 —— */
  [data-scope='flex'][data-part='root'][data-justify='start'] {
    justify-content: flex-start;
  }

  [data-scope='flex'][data-part='root'][data-justify='center'] {
    justify-content: center;
  }

  [data-scope='flex'][data-part='root'][data-justify='end'] {
    justify-content: flex-end;
  }

  [data-scope='flex'][data-part='root'][data-justify='between'] {
    justify-content: space-between;
  }

  [data-scope='flex'][data-part='root'][data-justify='around'] {
    justify-content: space-around;
  }

  [data-scope='flex'][data-part='root'][data-justify='evenly'] {
    justify-content: space-evenly;
  }

  /* —— 间距档位 —— */
  /* 每一档指向一个间距令牌，折行时行与行之间也吃这份间距 */
  [data-scope='flex'][data-part='root'][data-gap='xs'] {
    gap: var(--xh-flex-gap, var(--xh-layout-gap-xs));
  }

  [data-scope='flex'][data-part='root'][data-gap='sm'] {
    gap: var(--xh-flex-gap, var(--xh-layout-gap-sm));
  }

  [data-scope='flex'][data-part='root'][data-gap='md'] {
    gap: var(--xh-flex-gap, var(--xh-layout-gap-md));
  }

  [data-scope='flex'][data-part='root'][data-gap='lg'] {
    gap: var(--xh-flex-gap, var(--xh-layout-gap-lg));
  }

  [data-scope='flex'][data-part='root'][data-gap='xl'] {
    gap: var(--xh-flex-gap, var(--xh-layout-gap-xl));
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='flex'][data-part='root'][hidden] {
    display: none;
  }
}

/* styles/float-button.css */
/* 定义 float button 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='float-button'] {
    --xh-float-button-skin: 1;
  }

  /* 定位壳：钉在视口一角。贴边距离由连接层写进这个盒子的内联 style，
     样式表这一行只是它缺席时的落点；贴的是哪两条边看 data-placement。
     另一件必须提防的事：fixed 认的是视口，祖先上一旦出现
     transform / filter / backdrop-filter / contain，包含块就被抢走，整组立刻贴错位置——
     所以别往覆盖钩子里加这几个属性。 */
  [data-scope='float-button'][data-part='root'] {
    --xh-_float-button-offset: var(--xh-space-6);
    /* 展开列表里原生动作项的身量与字形尺：触发器自己走 Action Control floating 档
       （sm = box-md / md = box-lg / lg = box-lg + space-2，字形 md / lg / xl），
       原生动作项不是 Headless 部件、配方打不到它，这两支私有槽按同一张表镜像，换档只改这里 */
    --xh-_float-button-size: var(--xh-control-box-lg);
    --xh-_float-button-glyph-size: var(--xh-glyph-size-lg);
    /* 作者塞进指示符槽的图标跟着尺寸档走，与皮肤画的兜底字形同一把尺 */
    --xh-icon-size: var(--xh-float-button-icon-size, var(--xh-_float-button-glyph-size));

    position: fixed;
    /* 展开时消费 LayerRegistry 的实时层序；收起后没有逻辑层，仍回到普通 sticky 槽。 */
    z-index: var(--xh-float-button-layer, var(--xh-_layer, var(--xh-layer-sticky)));
    display: flex;
    /* 摞的方向由落位定，下面四条各自覆盖；这里给的是没写落位时的落点 */
    flex-direction: column;
    align-items: center;
    gap: var(--xh-float-button-gap, var(--xh-space-2));
  }

  /* —— 四角 ——
     start / end 用逻辑属性，RTL 下自动换到另一侧。
     摞的方向按贴的是上沿还是下沿定：离屏幕边最近的恒是触发器，展开的那一组往页面中间长。
     四条贴边都与安全区取大的一头：刘海、圆角与底部横条压住的那一段由系统给出，
     贴边比它窄时钮会被切掉一角；桌面上 env() 恒为 0，取值与贴边槽完全一致。
     安全区只有物理方向的四个名字，行内轴上两侧同取较宽的那一段，RTL 下不会翻错边。 */
  [data-scope='float-button'][data-part='root'][data-placement^='top'] {
    inset-block-start: max(var(--xh-_float-button-offset), env(safe-area-inset-top));
    flex-direction: column;
  }

  [data-scope='float-button'][data-part='root'][data-placement^='bottom'] {
    inset-block-end: max(var(--xh-_float-button-offset), env(safe-area-inset-bottom));
    flex-direction: column-reverse;
  }

  [data-scope='float-button'][data-part='root'][data-placement$='-start'] {
    inset-inline-start: max(var(--xh-_float-button-offset), env(safe-area-inset-left), env(safe-area-inset-right));
  }

  [data-scope='float-button'][data-part='root'][data-placement$='-end'] {
    inset-inline-end: max(var(--xh-_float-button-offset), env(safe-area-inset-left), env(safe-area-inset-right));
  }

  /* —— 尺寸：原生动作项与触发器的 floating 档逐档同表 —— */
  [data-scope='float-button'][data-part='root'][data-size='sm'] {
    --xh-_float-button-size: var(--xh-control-box-md);
    --xh-_float-button-glyph-size: var(--xh-glyph-size-md);
  }

  [data-scope='float-button'][data-part='root'][data-size='md'] {
    --xh-_float-button-size: var(--xh-control-box-lg);
    --xh-_float-button-glyph-size: var(--xh-glyph-size-lg);
  }

  [data-scope='float-button'][data-part='root'][data-size='lg'] {
    --xh-_float-button-size: calc(var(--xh-control-box-lg) + var(--xh-space-2));
    --xh-_float-button-glyph-size: var(--xh-glyph-size-xl);
  }

  /* —— 形态：给展开列表里原生动作项用的面 ——
     触发器的面由 Action Control 形态矩阵按 data-xh-action-variant 给（solid / subtle / ghost），
     原生动作项读不到矩阵，这几块私有槽按矩阵同一张表镜像；ghost 与 outline 的悬停 / 按下走画布承载的
     阶梯（100 → 200）。缺省 outline（连接层不传 variant 时显式落）是磨砂面：背景、边缘、
     顶光、投影与磨砂从同一份 M2 配方取，高对比、减少透明度、打印和强制色便能一起降级——钮浮在正文
     之上，透空的面在任何内容上都读不出边界，所以 outline 这一档面留着 */
  [data-scope='float-button'][data-part='root'][data-variant='solid'] {
    --xh-_float-button-bg: var(--xh-_tone, var(--xh-bg-brand));
    --xh-_float-button-bg-hover: var(--xh-_tone-hover, var(--xh-bg-brand-hover));
    --xh-_float-button-bg-active: var(--xh-_tone-active, var(--xh-bg-brand-active));
    --xh-_float-button-fg: var(--xh-_tone-on, var(--xh-fg-on-brand));
    --xh-_float-button-border: transparent;
    --xh-_float-button-border-hover: transparent;
    --xh-_float-button-shadow: none;
  }

  [data-scope='float-button'][data-part='root'][data-variant='subtle'] {
    --xh-_float-button-bg: var(--xh-_tone-subtle, var(--xh-bg-subtle));
    --xh-_float-button-bg-hover: var(--xh-_tone-subtle-hover, var(--xh-bg-subtle-hover));
    --xh-_float-button-bg-active: var(--xh-_tone-subtle-active, var(--xh-bg-subtle-active));
    --xh-_float-button-fg: var(--xh-_tone-fg, var(--xh-fg-default));
    --xh-_float-button-border: transparent;
    --xh-_float-button-border-hover: transparent;
    --xh-_float-button-shadow: none;
  }

  [data-scope='float-button'][data-part='root'][data-variant='outline'] {
    --xh-_float-button-bg: var(--xh-material-frosted-bg);
    --xh-_float-button-bg-hover: var(--xh-_tone-subtle, var(--xh-bg-subtle));
    --xh-_float-button-bg-active: var(--xh-_tone-subtle-hover, var(--xh-bg-subtle-hover));
    --xh-_float-button-fg: var(--xh-material-frosted-fg);
    --xh-_float-button-border: var(--xh-material-frosted-border);
    --xh-_float-button-border-hover: var(--xh-material-frosted-border);
    --xh-_float-button-shadow: var(--xh-material-frosted-shadow);
  }

  [data-scope='float-button'][data-part='root'][data-variant='ghost'] {
    --xh-_float-button-bg: transparent;
    --xh-_float-button-bg-hover: var(--xh-_tone-subtle, var(--xh-bg-subtle));
    --xh-_float-button-bg-active: var(--xh-_tone-subtle-hover, var(--xh-bg-subtle-hover));
    --xh-_float-button-fg: var(--xh-_tone-fg, var(--xh-fg-default));
    --xh-_float-button-border: transparent;
    --xh-_float-button-border-hover: transparent;
    --xh-_float-button-shadow: none;
  }

  /* —— 触发器 ——
     浮在内容之上的单图标圆钮，接 Action Control floating 档：盒型（md = box-lg 48px，圆形）、
     四态面、0.97 按压与 44px 命中区由家族配方按 data-xh-action-variant / -size 给出。
     这里只把公开槽桥接到矩阵之前（使用者槽 → 形态矩阵 → 家族缺省）与几何槽映射 */
  [data-scope='float-button'][data-part='trigger'] {
    --xh-action-bg-rest: var(--xh-float-button-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-float-button-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-float-button-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-bg-focus-visible: var(--xh-float-button-bg, var(--xh-_action-variant-bg-focus-visible));
    --xh-action-bg-disabled: var(--xh-float-button-bg, var(--xh-_action-variant-bg-disabled));
    --xh-action-fg-rest: var(--xh-float-button-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-float-button-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-float-button-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-fg-focus-visible: var(--xh-float-button-fg, var(--xh-_action-variant-fg-focus-visible));
    --xh-action-border-rest: var(--xh-float-button-border, var(--xh-_action-variant-border-rest));
    --xh-action-border-hover: var(--xh-float-button-border-hover, var(--xh-_action-variant-border-hover));
    --xh-action-border-pressed: var(--xh-float-button-border-hover, var(--xh-_action-variant-border-pressed));
    --xh-action-border-focus-visible: var(--xh-float-button-border, var(--xh-_action-variant-border-focus-visible));
    --xh-action-border-disabled: var(--xh-float-button-border, var(--xh-_action-variant-border-disabled));
    /* 矩阵各态无影（淡底与阴影互斥）；outline 那一档的磨砂投影在下面另桥接 */
    --xh-action-shadow-rest: var(--xh-float-button-shadow, none);
    --xh-action-shadow-hover: var(--xh-float-button-shadow, none);
    --xh-action-shadow-pressed: var(--xh-float-button-shadow, none);
    --xh-action-shadow-focus-visible: var(--xh-float-button-shadow, none);
    --xh-action-shadow-disabled: var(--xh-float-button-shadow, none);
    --xh-action-radius: var(--xh-float-button-radius, var(--xh-_action-profile-radius));
    --xh-action-visual-size: var(--xh-float-button-size, var(--xh-_action-profile-visual-size));
    /* 作者塞进来的图标跟着 floating 档走（md 24px），与皮肤画的兜底字形同一把尺 */
    --xh-icon-size: var(--xh-float-button-icon-size, var(--xh-_action-profile-glyph-size));
  }

  /* 缺省 outline 是 M2 磨砂面：背景、边缘、顶光、投影与磨砂从同一份配方取。
     悬停 / 按下的底走矩阵 outline 列的画布阶梯（100 → 200），边缘与投影不动；
     键盘聚焦时铺配方的实体 focus surface——透明面上的内收环没有稳定的底可量对比；
     置灰只换字色（矩阵 disabled 列的前景），面仍留着，透空的面在任何内容上都读不出边界 */
  [data-scope='float-button'][data-part='root'][data-variant='outline']
    [data-scope='float-button'][data-part='trigger'] {
    --xh-action-bg-rest: var(--xh-float-button-bg, var(--xh-_float-button-bg));
    --xh-action-bg-focus-visible: var(--xh-float-button-bg, var(--xh-material-frosted-focus-surface));
    --xh-action-bg-disabled: var(--xh-float-button-bg, var(--xh-_float-button-bg));
    --xh-action-fg-rest: var(--xh-float-button-fg, var(--xh-_float-button-fg));
    --xh-action-fg-hover: var(--xh-float-button-fg, var(--xh-_float-button-fg));
    --xh-action-fg-pressed: var(--xh-float-button-fg, var(--xh-_float-button-fg));
    --xh-action-fg-focus-visible: var(--xh-float-button-fg, var(--xh-_float-button-fg));
    --xh-action-border-rest: var(--xh-float-button-border, var(--xh-_float-button-border));
    --xh-action-border-hover: var(--xh-float-button-border-hover, var(--xh-_float-button-border-hover));
    --xh-action-border-pressed: var(--xh-float-button-border-hover, var(--xh-_float-button-border-hover));
    --xh-action-border-focus-visible: var(--xh-float-button-border, var(--xh-_float-button-border));
    --xh-action-border-disabled: var(--xh-float-button-border, var(--xh-_float-button-border));
    --xh-action-shadow-rest: var(--xh-float-button-shadow, var(--xh-_float-button-shadow));
    --xh-action-shadow-hover: var(--xh-float-button-shadow, var(--xh-_float-button-shadow));
    --xh-action-shadow-pressed: var(--xh-float-button-shadow, var(--xh-_float-button-shadow));
    --xh-action-shadow-focus-visible: var(--xh-float-button-shadow, var(--xh-_float-button-shadow));
    --xh-action-shadow-disabled: var(--xh-float-button-shadow, var(--xh-_float-button-shadow));
    /* M2 顶光走配方的高光通道：实心、淡色与透空形态各有自身表面，不能把磨砂高光误铺上去 */
    --xh-action-highlight-rest: var(--xh-material-frosted-highlight);
    --xh-action-highlight-hover: var(--xh-material-frosted-highlight);
    --xh-action-highlight-pressed: var(--xh-material-frosted-highlight);
    --xh-action-highlight-focus-visible: var(--xh-material-frosted-highlight);
    --xh-action-highlight-disabled: var(--xh-material-frosted-highlight);

    -webkit-backdrop-filter: var(--xh-material-frosted-backdrop);
    backdrop-filter: var(--xh-material-frosted-backdrop);
  }

  /* liquid 档：data-material="liquid" 下缺省 outline 换成液态面，面、墨色细线、1px 亮边与投影都从液态层取；
     悬停 / 按下往前景色兑，键盘聚焦铺配方的实体 focus surface。面内不加顶光，亮边已画在朝光源的一侧 */
  :where([data-material='liquid']) [data-scope='float-button'][data-part='root'][data-variant='outline']
    [data-scope='float-button'][data-part='trigger'][data-xh-liquid] {
    --xh-action-bg-rest: var(--xh-float-button-bg, var(--xh-_liquid-bg));
    --xh-action-bg-hover: var(--xh-float-button-bg-hover, var(--xh-_liquid-bg-hover));
    --xh-action-bg-pressed: var(--xh-float-button-bg-active, var(--xh-_liquid-bg-pressed));
    --xh-action-bg-focus-visible: var(--xh-float-button-bg, var(--xh-material-liquid-focus-surface));
    --xh-action-bg-disabled: var(--xh-float-button-bg, var(--xh-_liquid-bg));
    --xh-action-fg-rest: var(--xh-float-button-fg, var(--xh-material-liquid-fg));
    --xh-action-fg-hover: var(--xh-float-button-fg, var(--xh-material-liquid-fg));
    --xh-action-fg-pressed: var(--xh-float-button-fg, var(--xh-material-liquid-fg));
    --xh-action-fg-focus-visible: var(--xh-float-button-fg, var(--xh-material-liquid-fg));
    --xh-action-border-rest: var(--xh-float-button-border, var(--xh-material-liquid-border));
    --xh-action-border-hover: var(--xh-float-button-border-hover, var(--xh-material-liquid-border));
    --xh-action-border-pressed: var(--xh-float-button-border-hover, var(--xh-material-liquid-border));
    --xh-action-border-focus-visible: var(--xh-float-button-border, var(--xh-material-liquid-border));
    --xh-action-border-disabled: var(--xh-float-button-border, var(--xh-material-liquid-border));
    --xh-action-shadow-rest: var(--xh-float-button-shadow, var(--xh-_liquid-shadow));
    --xh-action-shadow-hover: var(--xh-float-button-shadow, var(--xh-_liquid-shadow));
    --xh-action-shadow-pressed: var(--xh-float-button-shadow, var(--xh-_liquid-shadow));
    --xh-action-shadow-focus-visible: var(--xh-float-button-shadow, var(--xh-_liquid-shadow));
    --xh-action-shadow-disabled: var(--xh-float-button-shadow, var(--xh-_liquid-shadow));
    --xh-action-highlight-rest: transparent;
    --xh-action-highlight-hover: transparent;
    --xh-action-highlight-pressed: transparent;
    --xh-action-highlight-focus-visible: transparent;
    --xh-action-highlight-disabled: transparent;

    -webkit-backdrop-filter: var(--xh-material-liquid-backdrop);
    backdrop-filter: var(--xh-material-liquid-backdrop);
  }

  /* 面是实心的，环色与面同族，画在面里就看不出来；环改取面自己的前景色——
     那一族色本来就要在这块面上把字读清楚，与面的对比是按可读性定的。
     置灰后矩阵把面换成中性淡底，公共环压上去足够对比，不再另灌 */
  [data-scope='float-button'][data-part='trigger'][data-xh-action-variant='solid']:not([data-disabled]):focus-visible {
    --xh-action-ring-color-focus-visible: currentColor;
  }

  /* —— 展开的那一组 —— */
  [data-scope='float-button'][data-part='list'] {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--xh-float-button-gap, var(--xh-space-2));
  }

  /* 贴下沿时整组往上长，翻过来摆，第一条动作离触发器最近 */
  [data-scope='float-button'][data-part='list'][data-placement^='bottom'] {
    flex-direction: column-reverse;
  }

  /* 声明过 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己补回来 */
  [data-scope='float-button'][data-part='list'][hidden] {
    display: none;
  }

  /* 展开的每一条动作与触发器同一副身量：它们是一排里的同类，作者只管往里放按钮 */
  [data-scope='float-button'][data-part='list'] > * {
    flex: none;
    inline-size: var(--xh-float-button-size, var(--xh-_float-button-size));
    block-size: var(--xh-float-button-size, var(--xh-_float-button-size));
    border-radius: var(--xh-float-button-radius, var(--xh-shape-circle));
    /* 逐条依次冒出来，离触发器最近的那条先到。backwards 让每条在自己那份延迟里保持起始帧 */
    animation: xh-pop-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong) backwards;
  }

  /* 原生按钮直接作为动作项时，沿用触发器的视觉面（同一组公开槽、同一张形态表）；XhButton 保留自己的皮肤。 */
  [data-scope='float-button'][data-part='list'] > button:not([data-scope]) {
    padding: 0;
    border: var(--xh-stroke-thin) solid var(--xh-float-button-border, var(--xh-_float-button-border));
    background-color: var(--xh-float-button-bg, var(--xh-_float-button-bg));
    color: var(--xh-float-button-fg, var(--xh-_float-button-fg));
    box-shadow: var(--xh-float-button-shadow, var(--xh-_float-button-shadow));
    font: inherit;
    cursor: pointer;
    transition:
      background-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      border-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      scale var(--xh-motion-duration-release) var(--xh-motion-ease-release);
  }

  [data-scope='float-button'][data-part='root'][data-variant='outline']
    [data-scope='float-button'][data-part='list']
    > button:not([data-scope]) {
    background-image: linear-gradient(
      to bottom,
      var(--xh-material-frosted-highlight) 0 var(--xh-stroke-thin),
      transparent var(--xh-stroke-thin)
    );
    -webkit-backdrop-filter: var(--xh-material-frosted-backdrop);
    backdrop-filter: var(--xh-material-frosted-backdrop);
  }

  [data-scope='float-button'][data-part='list'] > button:not([data-scope]):focus-visible {
    outline: var(--xh-ring-width) solid var(--xh-ring-focus);
    outline-offset: var(--xh-ring-offset);
  }

  @media (hover: hover) {
    [data-scope='float-button'][data-part='list'] > button:not([data-scope]):not(:disabled):hover {
      border-color: var(--xh-float-button-border-hover, var(--xh-_float-button-border-hover));
      background-color: var(--xh-float-button-bg-hover, var(--xh-_float-button-bg-hover));
    }
  }

  [data-scope='float-button'][data-part='list'] > button:not([data-scope]):not(:disabled):active {
    background-color: var(--xh-float-button-bg-active, var(--xh-_float-button-bg-active));
    scale: var(--xh-motion-scale-press);
    transition-duration: var(--xh-motion-duration-press);
    transition-timing-function: var(--xh-motion-ease-press);
  }

  [data-scope='float-button'][data-part='list'] > button:not([data-scope]):disabled {
    color: var(--xh-fg-disabled);
    cursor: not-allowed;
  }

  /* 交错的间隔：第二条起逐级往后推，第六条起统一钉在第五级，
     动作再多也不会拖出一条越来越慢的尾巴 */
  [data-scope='float-button'][data-part='list'] > *:nth-child(2) {
    animation-delay: var(--xh-motion-stagger-step);
  }

  [data-scope='float-button'][data-part='list'] > *:nth-child(3) {
    animation-delay: calc(2 * var(--xh-motion-stagger-step));
  }

  [data-scope='float-button'][data-part='list'] > *:nth-child(4) {
    animation-delay: calc(3 * var(--xh-motion-stagger-step));
  }

  [data-scope='float-button'][data-part='list'] > *:nth-child(5) {
    animation-delay: calc(4 * var(--xh-motion-stagger-step));
  }

  [data-scope='float-button'][data-part='list'] > *:nth-child(n + 6) {
    animation-delay: calc(5 * var(--xh-motion-stagger-step));
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中。
     粗指针的 44px 命中区由配方的 ::after 给，字形占的是 ::before */
  [data-scope='float-button'][data-part='trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-plus) center / contain no-repeat;
    mask: var(--xh-glyph-mark-plus) center / contain no-repeat;
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='float-button'][data-part='root'][hidden],
  [data-scope='float-button'][data-part='trigger'][hidden] {
    display: none;
  }

  @media print {
    /* 打印：悬浮动作钮固定在视口上，纸上没有视口——它会印在页面某处盖住正文，而且按不动。 */
    [data-scope='float-button'][data-part='root'] {
      display: none;
    }
  }
}

/* styles/floating-panel.css */
/* 定义 floating panel 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='floating-panel'] {
    --xh-floating-panel-skin: 1;
  }

  /* 分工：**面板的落位与尺寸**由连接层每帧写进 positioner 的内联样式
     （position / left / top / width / height）。这份皮肤一条都不碰那五个属性——
     内联优先级高于样式表，写了不但是死声明，还会在切换形态的那一帧跟连接层抢位置。
     皮肤只管层级、配色、圆角、阴影、把手的摆放与状态表现。 */

  [data-scope='floating-panel'][data-part='root'] {
    /* 作者塞进面板里的图标按控件档取；标题栏上的按钮另由家族配方按各自的档下发字形尺 */
    --xh-icon-size: var(--xh-floating-panel-icon-size, var(--xh-glyph-size-md));

    /* 面板本身是 fixed 定位，root 只是作者那棵树里的容器，不参与排布 */
    display: contents;
  }

  /* 浮层被搬到 portal 落点，继承不到 root 上的槽：这把尺在被搬走的那一侧再声明一次，
     关闭钮与条目里作者塞的图标才和皮肤画的兜底字形一样大 */
  [data-scope='floating-panel'][data-part='content'] {
    --xh-icon-size: var(--xh-floating-panel-icon-size, var(--xh-glyph-size-md));
  }

  [data-scope='floating-panel'][data-part='root'][hidden] {
    display: none;
  }

  /*
   * 开合触发器是页面上的独立文字按钮：盒型、md 档几何、outline 四态面、0.97 按压并换底与粗指针命中区
   * 由家族配方按连接层投影的 data-xh-action-variant / -size 给出（此前只缩放不换底）。这里只把公开槽桥接到
   * 矩阵之前（使用者槽 → 形态矩阵 → 家族缺省）与几何槽映射。
   */
  [data-scope='floating-panel'][data-part='trigger'] {
    --xh-action-bg-rest: var(--xh-floating-panel-trigger-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-focus-visible: var(--xh-floating-panel-trigger-bg, var(--xh-_action-variant-bg-focus-visible));
    --xh-action-fg-rest: var(--xh-floating-panel-trigger-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-floating-panel-trigger-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-floating-panel-trigger-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-fg-focus-visible: var(--xh-floating-panel-trigger-fg, var(--xh-_action-variant-fg-focus-visible));
    --xh-action-border-rest: var(--xh-floating-panel-trigger-border, var(--xh-_action-variant-border-rest));
    --xh-action-border-focus-visible: var(--xh-floating-panel-trigger-border, var(--xh-_action-variant-border-focus-visible));
    --xh-action-radius: var(--xh-floating-panel-trigger-radius, var(--xh-shape-control));
    --xh-action-visual-size: var(--xh-floating-panel-trigger-h, var(--xh-_action-profile-visual-size));
    --xh-action-padding-inline: var(--xh-floating-panel-trigger-px, var(--xh-_action-profile-padding-inline));
    /* 作者塞进按钮的图标随档取字形尺（md = 20px） */
    --xh-icon-size: var(--xh-floating-panel-icon-size, var(--xh-_action-profile-glyph-size));
  }

  [data-scope='floating-panel'][data-part='trigger'][hidden] {
    display: none;
  }

  /* 面是实心的，环色与面同族，画在面里就看不出来；环改取面自己的前景色 */
  [data-scope='floating-panel'][data-part='trigger'][data-xh-action-variant='solid']:focus-visible {
    --xh-action-ring-color-focus-visible: currentColor;
  }

  /* 把手的粗细：八个把手共用这两档，声明在这里往下继承。 */
  [data-scope='floating-panel'][data-part='positioner'] {
    --xh-_floating-panel-handle: var(--xh-floating-panel-handle-size, var(--xh-space-2));
    --xh-_floating-panel-corner: var(--xh-floating-panel-corner-size, var(--xh-space-4));

    position: fixed;
    /* 与抽屉同一档：面板要盖住吸顶栏，又该被随后打开的弹窗与浮层压住 */
    z-index: var(--xh-floating-panel-layer, var(--xh-layer-drawer));
    display: block;
  }

  /* 这里刻意没有 [data-part='positioner'][hidden] { display: none }：收起态连接层会给
     positioner 打 hidden，而上面那条 display 正是要盖掉 UA 的 [hidden]{display:none}——
     面板整棵子树都在 positioner 底下，它一收就不生成盒子，退场动画一帧都播不出来。
     真正的收起由宿主在退场结束后落成内联 display:none。 */

  [data-scope='floating-panel'][data-part='positioner'][data-state='open'] {
    animation: xh-pop-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 退场：收起那一帧由退场闸门押后，这里才播得出来。forwards 把末态钉住，
     免得动画结束到真收起之间闪一下原样 */
  [data-scope='floating-panel'][data-part='positioner'][data-state='closed'] {
    animation: xh-pop-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  [data-scope='floating-panel'][data-part='content'] {
    position: relative;
    block-size: 100%;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    /* 默认态是 M2 磨砂面：背景、边缘、高光、投影与光学采样同出一张配方。
       作者既有的面板槽仍排在外层；没有覆写时才落进这套磨砂令牌。 */
    border: var(--xh-stroke-thin) solid var(--xh-floating-panel-border, var(--xh-material-frosted-border));
    border-radius: var(--xh-floating-panel-radius, var(--xh-shape-overlay));
    background:
      linear-gradient(
        to bottom,
        var(--xh-material-frosted-highlight) 0 var(--xh-stroke-thin),
        transparent var(--xh-stroke-thin)
      ),
      var(--xh-floating-panel-bg, var(--xh-material-frosted-bg));
    color: var(--xh-floating-panel-fg, var(--xh-material-frosted-fg));
    box-shadow: var(--xh-floating-panel-shadow, var(--xh-material-frosted-shadow));
    -webkit-backdrop-filter: var(--xh-material-frosted-backdrop);
    backdrop-filter: var(--xh-material-frosted-backdrop);
    /* 铺满那一档要把投影整个撤掉，海拔的这一跳跟着过渡走 */
    transition: box-shadow var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 最大化时几何层把面板写成铺满视口（left/top 归零、宽高 100%），四条边全贴着视口：
     圆角会在四角把底下的页面露出来，描边缩成一圈贴边的多余框线，投影整块落在视口之外。
     三样一起撤，与抽屉贴住视口的那条边不圆角是同一回事。 */
  [data-scope='floating-panel'][data-part='content'][data-window-state='maximized'] {
    border: 0;
    border-radius: 0;
    box-shadow: none;
  }

  [data-scope='floating-panel'][data-part='content'][hidden] {
    display: none;
  }

  /* 面板本体不接收焦点，只是键盘事件的收口点，画环反而像是选中了整块 */
  [data-scope='floating-panel'][data-part='content']:focus-visible {
    outline: none;
  }

  /* 跟手期间整块不许选中文字：手在标题栏上来回蹭时会顺带把正文刷成高亮 */
  [data-scope='floating-panel'][data-part='content'][data-dragging],
  [data-scope='floating-panel'][data-part='content'][data-resizing] {
    user-select: none;
  }

  [data-scope='floating-panel'][data-part='header'] {
    display: flex;
    align-items: center;
    gap: var(--xh-floating-panel-header-gap, var(--xh-control-gap-sm));
    padding-block: var(--xh-floating-panel-header-py, var(--xh-space-2));
    padding-inline: var(--xh-floating-panel-header-px, var(--xh-space-3));
    border-block-end: var(--xh-stroke-thin) solid var(--xh-floating-panel-header-border, var(--xh-material-frosted-separator));
    background: var(--xh-floating-panel-header-bg, var(--xh-material-frosted-bg));
  }

  [data-scope='floating-panel'][data-part='header'][hidden] {
    display: none;
  }

  /* 浮层内标题：14 / 600 */
  [data-scope='floating-panel'][data-part='title'] {
    margin: 0;
    flex: 1 1 auto;
    overflow: hidden;
    font-size: var(--xh-floating-panel-title-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-floating-panel-title-font-weight, var(--xh-font-weight-semibold));
    line-height: var(--xh-leading-tight);
    white-space: nowrap;
    text-overflow: ellipsis;
    color: var(--xh-floating-panel-title-fg, var(--xh-material-frosted-fg));
  }

  /* 拖拽把手铺满标题栏剩下的横向空间：只给一小块纹理的话很难抓住 */
  [data-scope='floating-panel'][data-part='drag-trigger'] {
    flex: 1 1 auto;
    align-self: stretch;
    min-inline-size: var(--xh-space-6);
    border: 0;
    padding: 0;
    background: transparent;
    cursor: grab;
  }

  [data-scope='floating-panel'][data-part='drag-trigger'][data-dragging] {
    cursor: grabbing;
  }

  [data-scope='floating-panel'][data-part='drag-trigger'][data-disabled] {
    cursor: default;
  }

  /* —— 改尺把手 ——
     这一段刻意用物理的 inset / width / height：面板的坐标是屏幕坐标（连接层写的是
     left/top），指针位移与方向键推动的也是屏幕方向。改成逻辑属性后，RTL 下 inset-inline-start
     会翻到另一侧，守着「西边」的把手会长在东边，手往右拖却从左边收——把手与它推的那条边脱钩。 */
  [data-scope='floating-panel'][data-part='resize-trigger'] {
    position: absolute;
    border: 0;
    padding: 0;
    /* 把手是透明的命中区：看不见但要摸得着，嫌小就调 --xh-floating-panel-handle-size */
    background: transparent;
  }

  /* 只换指针形状，不摘 pointer-events：点击守卫在连接层，摘掉会让"键盘还在、指针没了"
     这两套禁用语义对不上 */
  [data-scope='floating-panel'][data-part='resize-trigger'][data-disabled] {
    cursor: default;
  }

  [data-scope='floating-panel'][data-part='resize-trigger'][data-edge='n'] {
    inset: 0 0 auto 0;
    /* stylelint-disable-next-line property-disallowed-list -- 面板的落位与尺寸由连接层写成物理 left / top / width / height，data-edge 的 n/s/e/w 是屏幕方向，把手的厚度沿同一根物理轴 */
    height: var(--xh-_floating-panel-handle);
    cursor: ns-resize;
  }

  [data-scope='floating-panel'][data-part='resize-trigger'][data-edge='s'] {
    inset: auto 0 0 0;
    /* stylelint-disable-next-line property-disallowed-list -- 同上 */
    height: var(--xh-_floating-panel-handle);
    cursor: ns-resize;
  }

  [data-scope='floating-panel'][data-part='resize-trigger'][data-edge='w'] {
    inset: 0 auto 0 0;
    /* stylelint-disable-next-line property-disallowed-list -- 同上 */
    width: var(--xh-_floating-panel-handle);
    cursor: ew-resize;
  }

  [data-scope='floating-panel'][data-part='resize-trigger'][data-edge='e'] {
    inset: 0 0 0 auto;
    /* stylelint-disable-next-line property-disallowed-list -- 同上 */
    width: var(--xh-_floating-panel-handle);
    cursor: ew-resize;
  }

  /* 四个角排在四条边之后，命中区大一圈：角上要同时抓住两条边 */
  [data-scope='floating-panel'][data-part='resize-trigger'][data-edge='nw'] {
    inset: 0 auto auto 0;
    /* stylelint-disable-next-line property-disallowed-list -- 同上 */
    width: var(--xh-_floating-panel-corner);
    /* stylelint-disable-next-line property-disallowed-list -- 同上 */
    height: var(--xh-_floating-panel-corner);
    cursor: nwse-resize;
  }

  [data-scope='floating-panel'][data-part='resize-trigger'][data-edge='ne'] {
    inset: 0 0 auto auto;
    /* stylelint-disable-next-line property-disallowed-list -- 同上 */
    width: var(--xh-_floating-panel-corner);
    /* stylelint-disable-next-line property-disallowed-list -- 同上 */
    height: var(--xh-_floating-panel-corner);
    cursor: nesw-resize;
  }

  [data-scope='floating-panel'][data-part='resize-trigger'][data-edge='se'] {
    inset: auto 0 0 auto;
    /* stylelint-disable-next-line property-disallowed-list -- 同上 */
    width: var(--xh-_floating-panel-corner);
    /* stylelint-disable-next-line property-disallowed-list -- 同上 */
    height: var(--xh-_floating-panel-corner);
    cursor: nwse-resize;
  }

  [data-scope='floating-panel'][data-part='resize-trigger'][data-edge='sw'] {
    inset: auto auto 0 0;
    /* stylelint-disable-next-line property-disallowed-list -- 同上 */
    width: var(--xh-_floating-panel-corner);
    /* stylelint-disable-next-line property-disallowed-list -- 同上 */
    height: var(--xh-_floating-panel-corner);
    cursor: nesw-resize;
  }

  /*
   * —— 标题栏上的按钮 ——
   * 形态钮与关闭钮是标题栏上的单图标钮：正方盒、sm 档几何、ghost 四态面、0.97 按压并换底与粗指针
   * 命中区由家族配方给出——磨砂白面上走画布承载阶梯悬停 --xh-bg-subtle（100）→ 按下 --xh-bg-subtle-hover（200），
   * 焦点面透明吃库环。这里只把公开槽桥接到矩阵之前（使用者槽 → 形态矩阵 → 家族缺省）；
   * 静息前景取磨砂面的 muted 字色，悬停 / 按下回到 fg-default。
   */
  [data-scope='floating-panel'][data-part='window-state-trigger'],
  [data-scope='floating-panel'][data-part='close-trigger'] {
    --xh-action-bg-hover: var(--xh-floating-panel-action-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-floating-panel-action-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-floating-panel-action-fg, var(--xh-material-frosted-fg-muted));
    --xh-action-fg-hover: var(--xh-floating-panel-action-fg-hover, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-floating-panel-action-fg-active, var(--xh-_action-variant-fg-pressed));
    --xh-action-fg-focus-visible: var(--xh-floating-panel-action-fg-hover, var(--xh-_action-variant-fg-focus-visible));
    /* 作者塞进按钮的图标随档取字形尺（sm = 16px），与皮肤画的兜底字形同一把尺 */
    --xh-icon-size: var(--xh-floating-panel-icon-size, var(--xh-_action-profile-glyph-size));
  }

  /* 两颗钮同高同圆角，尺寸与圆角槽按各自角色命名，映到家族正方盒 */
  [data-scope='floating-panel'][data-part='window-state-trigger'] {
    --xh-action-visual-size: var(--xh-floating-panel-action-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-floating-panel-action-radius, var(--xh-shape-control));
  }

  [data-scope='floating-panel'][data-part='close-trigger'] {
    --xh-action-visual-size: var(--xh-floating-panel-close-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-floating-panel-close-radius, var(--xh-shape-control));
  }

  [data-scope='floating-panel'][data-part='window-state-trigger'][hidden],
  [data-scope='floating-panel'][data-part='close-trigger'][hidden] {
    display: none;
  }

  /* 当前形态的那颗钮是按下的开关（aria-pressed），无滑块开关的 on 态取品牌淡底：
     rest 12% → hover 20% → pressed 28%，前景一律 --xh-fg-on-brand-subtle（对比度由该令牌承担）；
     淡底不是实心面，焦点吃库环 */
  [data-scope='floating-panel'][data-part='window-state-trigger'][data-state='on'] {
    --xh-action-bg-rest: var(--xh-floating-panel-action-bg-on, var(--xh-bg-brand-subtle));
    --xh-action-bg-hover: var(--xh-floating-panel-action-bg-on-hover, var(--xh-bg-brand-subtle-hover));
    --xh-action-bg-pressed: var(--xh-floating-panel-action-bg-on-active, var(--xh-bg-brand-subtle-active));
    --xh-action-bg-focus-visible: var(--xh-floating-panel-action-bg-on, var(--xh-bg-brand-subtle));
    --xh-action-fg-rest: var(--xh-floating-panel-action-fg-on, var(--xh-fg-on-brand-subtle));
    --xh-action-fg-hover: var(--xh-floating-panel-action-fg-on, var(--xh-fg-on-brand-subtle));
    --xh-action-fg-pressed: var(--xh-floating-panel-action-fg-on, var(--xh-fg-on-brand-subtle));
    --xh-action-fg-focus-visible: var(--xh-floating-panel-action-fg-on, var(--xh-fg-on-brand-subtle));
  }

  @media (forced-colors: active) {
    /* 强制色不会绘制背景图层；直接撤掉顶边装饰，边界与文字改由 frosted 的系统色令牌接手。 */
    [data-scope='floating-panel'][data-part='content'] {
      background-image: none;
    }
  }

  /* 正文是浮在页面之上的 Overlay 滚动面：原生细条由 reset 层统一给，滚到头不把页面一起带走；
     内容高度不动态变化，不写 scrollbar-gutter */
  [data-scope='floating-panel'][data-part='body'] {
    flex: 1 1 auto;
    display: block;
    overflow: auto;
    overscroll-behavior: contain;
    padding-block: var(--xh-floating-panel-body-py, var(--xh-surface-py-sm));
    padding-inline: var(--xh-floating-panel-body-px, var(--xh-surface-px-sm));
  }

  /* 收拢时连接层给正文打 hidden，这里把 UA 的 [hidden] 还回来（上面那条 display 盖掉了它） */
  [data-scope='floating-panel'][data-part='body'][hidden] {
    display: none;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中 */
  [data-scope='floating-panel'][data-part='close-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }

  /* 形态钮是同一个部件的三副面孔，字形按它「按下去切到哪一档」分：
     还原是四角朝内、铺满是四角朝外、收拢是一条横线。不分档的话标题栏上排着的
     两三颗钮长得一模一样，按哪颗全靠猜。
     这条打底画「还原」，另两档在下面换掉 mask-image。
     选的是 data-target-window-state 而不是面板身上的 data-window-state：后者说的是面板此刻在哪一档，
     用它会让排在一起的几颗钮同时换成同一枚字形。
     字形也不随 data-state='on' 翻面：可访问名由连接层按 target 定死（按下的仍念「铺满面板」），
     字形跟着按下态改就与念出来的名字对不上了 */
  [data-scope='floating-panel'][data-part='window-state-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-restore) center / contain no-repeat;
    mask: var(--xh-glyph-mark-restore) center / contain no-repeat;
  }

  [data-scope='floating-panel'][data-part='window-state-trigger'][data-target-window-state='maximized']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-maximize);
    mask-image: var(--xh-glyph-mark-maximize);
  }

  [data-scope='floating-panel'][data-part='window-state-trigger'][data-target-window-state='minimized']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-minus);
    mask-image: var(--xh-glyph-mark-minus);
  }

  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。 */
    [data-scope='floating-panel'][data-part='positioner'] {
      display: none;
    }
  }
}

/* styles/gradient-text.css */
/* 定义 gradient text 样式。 */

@layer xihan.components {
  /* 轴边界只路由简单前景值，渐变本身仍在组件根用本地 direction/from/to 计算。
     这样内层 default/more 能双向重置，也不会把未解析的组件变量冻结在祖先上。 */
  :where(:root, [data-contrast='default']) {
    --xh-_gradient-text-fg: transparent;
  }

  :where([data-contrast='more']) {
    --xh-_gradient-text-fg: var(--xh-fg-default);
  }

  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='gradient-text'] {
    --xh-gradient-text-skin: 1;
  }

  /* 渐变画在背景上，再用 background-clip 把背景裁进字形里；前景必须透明才透得出底下的渐变。
     两条 background-clip 都写：WebKit 只认带前缀那条。
     -webkit-text-fill-color 在 WebKit 里决定字形填充色并盖过 color，也要一并透明。 */
  [data-scope='gradient-text'][data-part='root'] {
    /* 走向由 data-direction 换掉这一个槽，背景那条声明只写一遍 */
    --xh-_gradient-text-dir: to right;
    /* 两端颜色各收一个私有槽：语气档换的是这两支，使用者槽仍排在它们前面 */
    --xh-_gradient-text-from: var(--xh-gradient-brand-from);
    --xh-_gradient-text-to: var(--xh-gradient-brand-to);

    background-image: linear-gradient(
      var(--xh-_gradient-text-dir),
      var(--xh-gradient-text-from, var(--xh-_gradient-text-from)),
      var(--xh-gradient-text-to, var(--xh-_gradient-text-to))
    );
    -webkit-background-clip: text;
    background-clip: text;
    color: var(--xh-_gradient-text-fg);
    -webkit-text-fill-color: currentColor;
  }

  /* —— 走向 —— */
  /* 逐档换算成 CSS 的 to <边或角>，四条边加四个角 */
  [data-scope='gradient-text'][data-part='root'][data-direction='to-left'] {
    --xh-_gradient-text-dir: to left;
  }

  [data-scope='gradient-text'][data-part='root'][data-direction='to-bottom'] {
    --xh-_gradient-text-dir: to bottom;
  }

  [data-scope='gradient-text'][data-part='root'][data-direction='to-top'] {
    --xh-_gradient-text-dir: to top;
  }

  [data-scope='gradient-text'][data-part='root'][data-direction='to-bottom-right'] {
    --xh-_gradient-text-dir: to bottom right;
  }

  [data-scope='gradient-text'][data-part='root'][data-direction='to-bottom-left'] {
    --xh-_gradient-text-dir: to bottom left;
  }

  [data-scope='gradient-text'][data-part='root'][data-direction='to-top-right'] {
    --xh-_gradient-text-dir: to top right;
  }

  [data-scope='gradient-text'][data-part='root'][data-direction='to-top-left'] {
    --xh-_gradient-text-dir: to top left;
  }

  /* —— 语气 —— */
  /* 两端取该族主色与它压深一档的取值，深浅两态自动跟随。
     排在使用者槽之后：作者写了 from / to，六族语气一并让位 */
  [data-scope='gradient-text'][data-part='root'][data-tone] {
    --xh-_gradient-text-from: var(--xh-_tone);
    --xh-_gradient-text-to: var(--xh-_tone-active);
  }

  /* 无 JS 时的系统高对比、强制色与打印统一退回单色；显式局部轴由上面的最近作用域标记负责。 */
  @media (prefers-contrast: more), (forced-colors: active), print {
    [data-scope='gradient-text'][data-part='root'] {
      background-image: none;
      color: inherit;
      -webkit-text-fill-color: currentColor;
    }
  }
}

/* styles/grid.css */
/* 定义 grid 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='grid'] {
    --xh-grid-skin: 1;
  }

  [data-scope='grid'][data-part='root'] {
    display: grid;
    /* 各列等宽；下限写 0 而不是 auto，一段长文本才不会把自己那列撑宽 */
    /* 使用者槽位排在档位之前，写死一份轨道表即盖过所有列数档 */
    grid-template-columns: var(--xh-grid-columns, repeat(var(--xh-_grid-cols), minmax(0, 1fr)));
    /* 不写 gap 档位就不留间距 */
    gap: var(--xh-grid-gap, var(--xh-space-0));
    /* 列数、行数与自适应列宽下限都收在根上这几个槽位里，换档只改这里；
       每一层都声明一遍，嵌套时内层不吃外层的值 */
    --xh-_grid-cols: 1;
    --xh-_grid-rows: 1;
    --xh-_grid-col-min: var(--xh-layout-col-min-md);
  }

  /* —— 列数 —— */
  /* 一列是上面的缺省，这里从两列起逐档写 */
