/* styles/heatmap.css */
/* 定义 heatmap 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='heatmap'] {
    --xh-heatmap-skin: 1;
  }

  /* 缺省的 calendar 形态：上下两条横排，月份行在网格之外（它只是一条对齐用的坐标轴），
     网格里是七行星期。格子一律是固定尺寸的方块，列与列之间靠尺寸对齐，不必另立网格轨道。
     另外两种形态只在下面的 [data-variant] 段里改摆法，这里的取值一概不动。 */
  [data-scope='heatmap'][data-part='root'] {
    /* 尺寸档只换这里的私有槽，各部件从 root 继承它们，换档不必给每个部件各写一条选择器。
       格宽在这一处就把使用者令牌解析掉：错列与月份名的宽度都按它算，
       各处分头读会让作者改宽格子后错列与月份名对不上 */
    --xh-_heatmap-cell-size: var(--xh-heatmap-cell-size, var(--xh-space-2_5));
    /* 矩阵形态的行高。格宽那把尺是给「一天一个小方块」定的，矩阵一行左边还挂着行名，
       格子照那把尺定高就矮过行名，行高由行名的字定、格子在行里摊成一条。
       这里取格宽尺的两倍：三档一起走，且每一档都高过行名那行字。
       不接控件高度那把尺——它是给可点可输的控件在一行里排齐用的，矩阵格子不可交互，
       接上去密度档一换矩阵就跟着变形 */
    --xh-_heatmap-row-h: var(--xh-heatmap-row-h, var(--xh-space-5));
    /* 格与格之间的空当：格子按天铺满一年，靠这道缝把一格与相邻格分开 */
    --xh-_heatmap-gap: var(--xh-space-1);
    --xh-_heatmap-gutter: var(--xh-heatmap-gutter, var(--xh-space-8));
    --xh-_heatmap-font-size: var(--xh-text-caption-size);
    /* 星期名隔行画：第 0/2/4/6 行那个字的颜色。缺省透明——只是字不上色，
       盒子、底色与命中区都还在，钉住那一列的实色底不缺一块，七行的悬停行为也一致。
       改写这个槽为一个看得见的颜色（`var(--xh-heatmap-label-fg, var(--xh-fg-subtle))`）即七行全画。
       周首日是星期一时留下的是二 / 四 / 六，是星期日时留下的是一 / 三 / 五 */
    --xh-_heatmap-week-day-skip: var(--xh-heatmap-week-day-skip, transparent);
    /* 色阶的两端：0 档的空格底与满档的实心底。没写 data-tone 也没写 data-palette 时就是这里的取值 */
    --xh-_heatmap-empty: var(--xh-heatmap-empty, var(--xh-bg-subtle));
    --xh-_heatmap-ink: var(--xh-heatmap-ink, var(--xh-bg-brand));
    /* 钉住的行首那一列自带的底色：格子从它下面滚过去时不能透出来。
       整块摆在别的底色上（卡片、分区）时改写 --xh-heatmap-bg，否则那一列会是一块补丁 */
    --xh-_heatmap-surface: var(--xh-heatmap-bg, var(--xh-bg-surface));

    /* 详情条按内边距盒绝对定位，参照系就是它 */
    position: relative;
    /* 自建层叠上下文：钉住那一列与详情条的层号只跟组件里的兄弟比，
       不写这条它们是拿去跟页面同层的元素比，热力图会压住页面上后来的定位元素 */
    isolation: isolate;
    display: flex;
    flex-direction: column;
    gap: var(--xh-heatmap-gap, var(--xh-space-2));
    /* 一整年五十几列，一屏放不下就自己横着滚。上下各留一道与格间距同宽的空当，
       最上一行与最下一行不贴着滚动容器的边 */
    padding-block: var(--xh-heatmap-py, var(--xh-_heatmap-gap));
    overflow-x: auto;
    /* 键盘走到视口外的格子时 scrollIntoView 会把它滚进来，落点要让开钉住的那一列，
       否则往回走的那一格正好停在行首星期名底下 */
    scroll-padding-inline-start: calc(var(--xh-_heatmap-gutter) + var(--xh-_heatmap-gap));
    color: var(--xh-heatmap-fg, var(--xh-fg-muted));
    font-size: var(--xh-heatmap-font-size, var(--xh-_heatmap-font-size));
    line-height: var(--xh-leading-none);
  }

  /* —— 语气 —— */
  /* 选择器带 [data-tone] 限定：不限定的话，放在语气容器里的热力图会跟着改色 */
  [data-scope='heatmap'][data-part='root'][data-tone] {
    --xh-_heatmap-ink: var(--xh-heatmap-ink, var(--xh-_tone, var(--xh-bg-brand)));
  }

  /* —— 色板 —— */
  /* 直接按颜色点名，定的是满档那一端的实心底；0 档的空格底与中间各档的兑法一概不动。
     六条规则与上面那条语气规则同特指度，排在它之后：两个都写时色板赢——
     色板指名了一个具体颜色，语气只是推得出一个颜色，指名的那个更具体。
     取值一律逐值写死原语、不经 --xh-_tone：那一族槽位是语气层的派生结果，
     色板借道它就会连带把语气的悬停 / 淡底 / 前景一起绑进来，也会被祖先的 data-tone 染色。
     色板拼错取值时六条都不命中，落回上面两条，与没写一样 */
  [data-scope='heatmap'][data-part='root'][data-palette='green'] {
    --xh-_heatmap-ink: var(--xh-heatmap-ink, var(--xh-color-success-600));
  }

  [data-scope='heatmap'][data-part='root'][data-palette='blue'] {
    --xh-_heatmap-ink: var(--xh-heatmap-ink, var(--xh-color-info-600));
  }

  [data-scope='heatmap'][data-part='root'][data-palette='orange'] {
    --xh-_heatmap-ink: var(--xh-heatmap-ink, var(--xh-color-warning-600));
  }

  [data-scope='heatmap'][data-part='root'][data-palette='purple'] {
    --xh-_heatmap-ink: var(--xh-heatmap-ink, var(--xh-color-purple-600));
  }

  [data-scope='heatmap'][data-part='root'][data-palette='red'] {
    --xh-_heatmap-ink: var(--xh-heatmap-ink, var(--xh-color-danger-600));
  }

  /* 灰是唯一按主题换档的一族：五个彩色族的 600 档明度在 0.577–0.705，
     深色态的空格底（neutral-800，明度 0.269）离得够远；中性 600 档只有 0.439，
     五档摊下来每档只差 0.0425、相邻两档对比度 1.16–1.20，等于看不出分档。
     深色态改取 neutral-450（明度 0.65），步长回到 0.095、相邻两档 1.42–1.50，与彩色族齐平。
     不取更亮的 neutral-400：高对比档的 border-default 正是那一档，满档格子的描边会与底色同色。
     data-theme 写在自己身上还是写在祖先上都算，两种用法都成立 */
  [data-scope='heatmap'][data-part='root'][data-palette='gray'] {
    --xh-_heatmap-ink: var(--xh-heatmap-ink, var(--xh-color-neutral-600));
  }

  :is([data-theme='dark'] *, [data-theme='dark'])[data-scope='heatmap'][data-part='root'][data-palette='gray'] {
    --xh-_heatmap-ink: var(--xh-heatmap-ink, var(--xh-color-neutral-450));
  }

  /* —— 尺寸 —— */
  /* 缺省的 md 档写在上面的基础规则里 */
  [data-scope='heatmap'][data-part='root'][data-size='sm'] {
    --xh-_heatmap-cell-size: var(--xh-heatmap-cell-size, var(--xh-space-2));
    --xh-_heatmap-row-h: var(--xh-heatmap-row-h, var(--xh-space-4));
    --xh-_heatmap-gutter: var(--xh-heatmap-gutter, var(--xh-space-6));
  }

  [data-scope='heatmap'][data-part='root'][data-size='lg'] {
    --xh-_heatmap-cell-size: var(--xh-heatmap-cell-size, var(--xh-space-3));
    --xh-_heatmap-row-h: var(--xh-heatmap-row-h, var(--xh-space-6));
  }

  [data-scope='heatmap'][data-part='grid'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-heatmap-grid-gap, var(--xh-_heatmap-gap));
  }

  [data-scope='heatmap'][data-part='row'] {
    /* 行首空出的列数由连接层写进这个槽：日历形态是区间起点不在周首日时的错列，
       月历形态是这一周里 1 号之前的那几个星期几 */
    --xh-_heatmap-row-offset: 0;

    display: flex;
    /* 行至少要有内容那么宽。行是列方向 flex 的子项，缺省会被拉成容器的宽（一屏那么宽），
       行首钉住的那一列只能在自己这一行的盒子里钉——盒子只有一屏宽，滚过一屏它就跟着走了 */
    min-inline-size: max-content;
    align-items: center;
    gap: var(--xh-heatmap-row-gap, var(--xh-_heatmap-gap));
  }

  /* 数据行的高度只由格子定。行首那一列星期名的字（12px）比格子（10px）高，让它撑开行
     会在纵向多挤出两像素，同一张图的横向格距与纵向格距就不一样宽。
     钉死成格高之后星期名的字仍照常画，只是溢出到行外——那几行隔行留白，撞不到东西 */
  [data-scope='heatmap'][data-part='row'][data-week-day],
  [data-scope='heatmap'][data-part='row'][data-week] {
    block-size: var(--xh-_heatmap-cell-size);
  }

  /* 行首的星期名。月份行行首那个占位也是它，宽度一样，月份才对得上列。
     一整年放不下时网格横着滚，这一列钉在滚动容器的起始缘：跟着滚走的话，
     滚过头一屏就再也认不出哪一行是星期几。底色必须实色，格子从它下面滚过去不能透出来 */
  [data-scope='heatmap'][data-part='week-day'] {
    position: sticky;
    /* 层号收在 root 建的层叠上下文里，只跟组件内的兄弟比 */
    z-index: var(--xh-heatmap-sticky-layer, 1);
    inset-inline-start: 0;
    display: block;
    flex: 0 0 auto;
    inline-size: var(--xh-_heatmap-gutter);
    overflow: hidden;
    background: var(--xh-_heatmap-surface);
    color: var(--xh-heatmap-label-fg, var(--xh-fg-subtle));
    white-space: nowrap;
    text-align: end;
  }

  /* 隔行画：这几行只是字不上色，节点、文字、盒子与底色都还在。
     不能用 visibility 关：那会连盒子一起不画，钉住那一列的实色底跟着缺四行，
     格子从行首透出来，且这四行不再参与命中测试——鼠标划过行首会弹出看不见那一格的详情条。
     一行只有 10px 高，七个 12px 的字挨着写会上下叠在一起；隔一行之后每个留下来的字
     有两行的高度（2 × 格高 + 格距）可用。哪一行是星期几由行自己的可及名字念出来，
     可见文字与可及名字是两件事，读屏这边一行都没少 */
  [data-scope='heatmap'][data-part='week-day'][data-week-day='0'],
  [data-scope='heatmap'][data-part='week-day'][data-week-day='2'],
  [data-scope='heatmap'][data-part='week-day'][data-week-day='4'],
  [data-scope='heatmap'][data-part='week-day'][data-week-day='6'] {
    color: var(--xh-_heatmap-week-day-skip);
  }

  /* 月份名横跨这个月占的那几列：列宽加列间距，末尾少算一个间距（它由行的 gap 补上） */
  [data-scope='heatmap'][data-part='month-label'] {
    --xh-_heatmap-month-weeks: 1;

    display: block;
    flex: 0 0 auto;
    inline-size: calc(
      var(--xh-_heatmap-month-weeks) * (var(--xh-_heatmap-cell-size) + var(--xh-_heatmap-gap))
      - var(--xh-_heatmap-gap)
    );
    overflow: hidden;
    color: var(--xh-heatmap-label-fg, var(--xh-fg-subtle));
    white-space: nowrap;
  }

  /* 一天一格。档位是连着的百分比，档数随便改都不必再写一条选择器 */
  [data-scope='heatmap'][data-part='cell'] {
    --xh-_heatmap-level: 0%;

    flex: 0 0 auto;
    inline-size: var(--xh-_heatmap-cell-size);
    block-size: var(--xh-_heatmap-cell-size);
    border-radius: var(--xh-heatmap-cell-radius, var(--xh-shape-inset));
    background: var(
      --xh-heatmap-cell-bg,
      color-mix(in oklab, var(--xh-_heatmap-ink) var(--xh-_heatmap-level), var(--xh-_heatmap-empty))
    );
    /* 空格与浅档在浅色底上几乎没有边界，描一圈极淡的线把方格勾出来。
       这一档不能取 border-subtle：它与空格底色 bg-subtle 是同一个原色，描了等于没描 */
    box-shadow: inset 0 0 0 var(--xh-stroke-thin) var(--xh-heatmap-cell-border, var(--xh-border-default));
    transition: background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 错列打在本行第一个格子上：打在行上会连行首的星期名一起往后推，
     左侧那一列星期名就变成锯齿。两条选择器合起来正好是「本行第一个格子」，
     行里写不写星期名都成立 */
  [data-scope='heatmap'][data-part='row'] > [data-scope='heatmap'][data-part='cell']:first-child,
  [data-scope='heatmap'][data-part='week-day'] + [data-scope='heatmap'][data-part='cell'] {
    margin-inline-start: calc(
      var(--xh-_heatmap-row-offset) * (var(--xh-_heatmap-cell-size) + var(--xh-_heatmap-gap))
    );
  }

  /* —— 月历形态：一个自然月一块，块内一行是一周、一列是一个星期几 —— */
  [data-scope='heatmap'][data-part='root'][data-variant='month'] [data-scope='heatmap'][data-part='grid'] {
    flex-flow: row wrap;
    gap: var(--xh-heatmap-block-gap, var(--xh-_heatmap-gutter));
  }

  [data-scope='heatmap'][data-part='month-block'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-heatmap-block-inner-gap, var(--xh-_heatmap-gap));
  }

  /* 月历形态的月块是换行排开的，没有钉住的那一列，滚动落点也不必让开 */
  [data-scope='heatmap'][data-part='root'][data-variant='month'] {
    /* 这里的星期名是一排列头，七个一个都不能少：隔行不上色就有四列认不出是星期几 */
    --xh-_heatmap-week-day-skip: var(--xh-heatmap-label-fg, var(--xh-fg-subtle));

    /* 月块换行排开，宽度永不超过容器，这一档不当滚动容器：留着 overflow-x: auto 的话，
       下面那排列头（12px 的字装在 10px 的列里）往外溢的那点行盒会算进可滚动宽度，
       2px 的溢出就换来一条常驻的横向滚动条，白吃掉十几像素高。
       clip 只裁不滚，再放出一个格距的余量让列头两端那点溢出照常画出来 */
    overflow-x: clip;
    overflow-clip-margin: var(--xh-_heatmap-gap);
    scroll-padding-inline-start: 0;
  }

  /* 块里的星期名是一排列头，宽度改成格宽才对得上下面的格子，也不再钉住。
     字比一格宽，不裁：裁掉就是七个缺角的字，让它往两边的列间距里溢出去，
     相邻两个各溢出一点也还差着一段空白 */
  [data-scope='heatmap'][data-part='root'][data-variant='month'] [data-scope='heatmap'][data-part='week-day'] {
    position: static;
    inline-size: var(--xh-_heatmap-cell-size);
    overflow: visible;
    background: none;
    text-align: center;
  }

  /* 块的标题占整块宽，不再横跨若干列 */
  [data-scope='heatmap'][data-part='root'][data-variant='month'] [data-scope='heatmap'][data-part='month-label'] {
    inline-size: auto;
    color: var(--xh-heatmap-title-fg, var(--xh-fg-default));
  }

  /* —— 矩阵形态：行列都由作者给，行名与列名是两条真表头 —— */
  /* 行名与日历的星期名同一个位置、同一件事：列多到放不下时钉在起始缘 */
  [data-scope='heatmap'][data-part='row-label'] {
    position: sticky;
    z-index: var(--xh-heatmap-sticky-layer, 1);
    inset-inline-start: 0;
    display: block;
    flex: 0 0 auto;
    inline-size: var(--xh-_heatmap-gutter);
    overflow: hidden;
    background: var(--xh-_heatmap-surface);
    color: var(--xh-heatmap-label-fg, var(--xh-fg-subtle));
    white-space: nowrap;
    text-align: end;
  }

  /* 列名与它下面那一列的格子同宽：标签长就把列宽整体调大，别只调标签。
     两处的兜底都是行高，不写列宽时矩阵格子就是正方块 */
  [data-scope='heatmap'][data-part='column-label'] {
    display: block;
    flex: 0 0 auto;
    inline-size: var(--xh-heatmap-column-w, var(--xh-_heatmap-row-h));
    overflow: hidden;
    color: var(--xh-heatmap-label-fg, var(--xh-fg-subtle));
    white-space: nowrap;
    text-align: center;
  }

  /* 矩阵的格子两向都不走日方块那把尺：宽跟列走，高跟行走 */
  [data-scope='heatmap'][data-part='root'][data-variant='matrix'] [data-scope='heatmap'][data-part='cell'] {
    inline-size: var(--xh-heatmap-column-w, var(--xh-_heatmap-row-h));
    block-size: var(--xh-_heatmap-row-h);
  }

  /* —— 详情条 —— */
  /* 位置由连接层在事件那一刻量好写成内联样式（它量得到，样式表量不到）；
     这四个是还没量到时的落点，量到即被内联样式盖过。四个都带长度单位：
     下面 block-start 那一档要把它们放进 calc(100% - …)，无单位的 0 会让整条声明作废。
     不引浮层引擎：它按 root 的内边距盒绝对定位，跟着 root 一起横向滚动，
     摆上边还是摆下边由连接层按行序给出，因此始终压在网格自己身上，不会被 root 的滚动裁掉 */
  [data-scope='heatmap'][data-part='tooltip'] {
    --xh-_heatmap-tip-x: 0px;
    --xh-_heatmap-tip-y: 0px;
    --xh-_heatmap-tip-w: 0px;
    --xh-_heatmap-tip-h: 0px;

    position: absolute;
    /* 排在钉住的行首那一列之上：条从末缘往回长时会盖到那一列上，它不该把条切掉 */
    z-index: var(--xh-heatmap-tooltip-layer, 2);
    display: block;
    inset-inline-start: var(--xh-_heatmap-tip-x);
    inset-block-start: var(--xh-_heatmap-tip-y);
    /* 至少与格子同宽，一两个字的详情也不会瘦成一条 */
    min-inline-size: var(--xh-_heatmap-tip-w);
    max-inline-size: var(--xh-heatmap-tooltip-max-w, var(--xh-overlay-max-w));
    padding-block: var(--xh-heatmap-tooltip-py, var(--xh-space-1));
    padding-inline: var(--xh-heatmap-tooltip-px, var(--xh-space-2));
    border-radius: var(--xh-heatmap-tooltip-radius, var(--xh-shape-control));
    /* 与 Tooltip 同一副反白气泡：任何浮层都得有一圈非透明描边，描边从字色里兑两成，
       深浅主题与语气换色时跟着字色走；影走 frosted 紧凑档，与 Tooltip 的 content 同深 */
    border: var(--xh-stroke-thin) solid var(--xh-heatmap-tooltip-border, color-mix(in oklab, var(--xh-heatmap-tooltip-fg, var(--xh-bg-surface)) 20%, transparent));
    background: var(--xh-heatmap-tooltip-bg, var(--xh-fg-default));
    color: var(--xh-heatmap-tooltip-fg, var(--xh-bg-surface));
    /* 字号与 Tooltip 缺省档同一把尺（次级标注档 13px） */
    font-size: var(--xh-heatmap-tooltip-font-size, var(--xh-control-caption-md));
    line-height: var(--xh-leading-normal);
    white-space: nowrap;
    box-shadow: var(--xh-heatmap-tooltip-shadow, var(--xh-material-frosted-compact-shadow));
    /* 详情条不接指针：压在格子上时指针要能穿过去，否则一进条里就算离开了格子，
       详情自己把自己收起来，来回闪 */
    pointer-events: none;
  }

  /* 从格子的末缘往回长：条比一格宽得多，格子后面的地方比前面少时往后长会伸出滚动容器被裁掉，
     还会把横向滚动条撑长。按末缘定位，条自己多宽都贴着格子的末沿。
     百分比是内边距盒的宽，在这条 calc 里前后抵消，横向滚到哪里都成立 */
  [data-scope='heatmap'][data-part='tooltip'][data-inline-anchor='end'] {
    inset-inline-start: auto;
    inset-inline-end: calc(100% - var(--xh-_heatmap-tip-x) - var(--xh-_heatmap-tip-w));
  }

  /* 摆在格子下边：从格子的下沿再让开一个格间距 */
  [data-scope='heatmap'][data-part='tooltip'][data-placement='block-end'] {
    inset-block-start: calc(
      var(--xh-_heatmap-tip-y) + var(--xh-_heatmap-tip-h) + var(--xh-_heatmap-gap)
    );
  }

  /* 摆在格子上边：按末缘定位，条自己多高都贴着格子的上沿。
     两头都写就是过约束，起始缘要先让开 */
  [data-scope='heatmap'][data-part='tooltip'][data-placement='block-start'] {
    inset-block-start: auto;
    inset-block-end: calc(100% - var(--xh-_heatmap-tip-y) + var(--xh-_heatmap-gap));
  }

  [data-scope='heatmap'][data-part='legend'] {
    display: flex;
    align-items: center;
    gap: var(--xh-heatmap-legend-gap, var(--xh-_heatmap-gap));
    color: var(--xh-heatmap-label-fg, var(--xh-fg-subtle));
  }

  /* 对照条两端的那两个字。与色块同一行、同一档颜色，不换行：
     「少」「多」断成两行就跟色块对不上了 */
  [data-scope='heatmap'][data-part='legend-label'] {
    flex: 0 0 auto;
    white-space: nowrap;
  }

  /* 对照条里的一格与网格里同档的格子同色，两处共用同一条色阶 */
  [data-scope='heatmap'][data-part='legend-item'] {
    --xh-_heatmap-level: 0%;

    display: block;
    flex: 0 0 auto;
    inline-size: var(--xh-_heatmap-cell-size);
    block-size: var(--xh-_heatmap-cell-size);
    border-radius: var(--xh-heatmap-cell-radius, var(--xh-shape-inset));
    background: var(
      --xh-heatmap-cell-bg,
      color-mix(in oklab, var(--xh-_heatmap-ink) var(--xh-_heatmap-level), var(--xh-_heatmap-empty))
    );
    box-shadow: inset 0 0 0 var(--xh-stroke-thin) var(--xh-heatmap-cell-border, var(--xh-border-default));
  }

  /* 详情条的收起态：没有哪一格是活的时候整条藏起来 */
  [data-scope='heatmap'][data-part='tooltip'][data-state='hidden'] {
    display: none;
  }

  /* 给了 display 的角色节点必须补这条：display 声明会盖掉 UA 的 [hidden]{display:none}，
     不补的话作者给节点加 hidden 后它照样显示。
     格子没有声明 display，UA 那条兜得住，不必列在这里 */
  [data-scope='heatmap'][data-part='root'][hidden],
  [data-scope='heatmap'][data-part='grid'][hidden],
  [data-scope='heatmap'][data-part='month-block'][hidden],
  [data-scope='heatmap'][data-part='row'][hidden],
  [data-scope='heatmap'][data-part='week-day'][hidden],
  [data-scope='heatmap'][data-part='month-label'][hidden],
  [data-scope='heatmap'][data-part='row-label'][hidden],
  [data-scope='heatmap'][data-part='column-label'][hidden],
  [data-scope='heatmap'][data-part='tooltip'][hidden],
  [data-scope='heatmap'][data-part='legend'][hidden],
  [data-scope='heatmap'][data-part='legend-item'][hidden] {
    display: none;
  }

  /*
   * 打印：格子的深浅只写在底色上，纸上多数丢背景，整张图印成一片空白。
   * 这一档把档位改画成边框的粗细——0 档只有一圈发丝线，档位越高边越厚，
   * 顶到一半格宽时整格填满。边算在尺寸里（reset 兜了 border-box），格子大小一点不变。
   *
   * 比例取 0.2 / 0.3 / 0.4 / 0.5：缺省格宽 10px 下正好落在 2 / 3 / 4 / 5 像素，
   * 与 0 档那一像素合成五档整数宽——边宽在屏幕与纸上都取整，分数宽会有两档并到一起。
   *
   * 第一条给的是高档那一身，下面四条按档位逐个改薄：档数由作者定，
   * 超出缺省五档的那些落在第一条上，一律按最高档画。
   * 图例里那几个方块与格子同源，跟着走同一套。
   */
  @media print {
    [data-scope='heatmap'][data-part='cell'],
    [data-scope='heatmap'][data-part='legend-item'] {
      --xh-_heatmap-ink-ring: calc(var(--xh-_heatmap-cell-size) * 0.5);

      border: var(--xh-_heatmap-ink-ring) solid currentColor;
    }

    [data-scope='heatmap'][data-part='cell'][data-level='0'],
    [data-scope='heatmap'][data-part='legend-item'][data-level='0'] {
      --xh-_heatmap-ink-ring: var(--xh-stroke-thin);
    }

    [data-scope='heatmap'][data-part='cell'][data-level='1'],
    [data-scope='heatmap'][data-part='legend-item'][data-level='1'] {
      --xh-_heatmap-ink-ring: calc(var(--xh-_heatmap-cell-size) * 0.2);
    }

    [data-scope='heatmap'][data-part='cell'][data-level='2'],
    [data-scope='heatmap'][data-part='legend-item'][data-level='2'] {
      --xh-_heatmap-ink-ring: calc(var(--xh-_heatmap-cell-size) * 0.3);
    }

    [data-scope='heatmap'][data-part='cell'][data-level='3'],
    [data-scope='heatmap'][data-part='legend-item'][data-level='3'] {
      --xh-_heatmap-ink-ring: calc(var(--xh-_heatmap-cell-size) * 0.4);
    }
  }

  /*
   * 高对比档：格子画的就是色阶本身，被系统换成同一个底色之后整张图没有任何深浅。
   * 这几处退出强制着色，自己保住色阶；退出之后不再跟系统底色走，
   * 各补一圈系统描边把方格从背景里框出来（原来那圈发丝线写在 inset 阴影上，这一档里被丢弃）。
   */
  @media (forced-colors: active) {
    [data-scope='heatmap'][data-part='cell'],
    [data-scope='heatmap'][data-part='legend-item'] {
      forced-color-adjust: none;
      outline: var(--xh-stroke-thin) solid CanvasText;
      outline-offset: calc(-1 * var(--xh-stroke-thin));
    }
  }
}

/* styles/highlight.css */
/* 定义 highlight 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='highlight'] {
    --xh-highlight-skin: 1;
  }

  /* 文本按原样显示：命中位置是按原串逐字符算的，折叠掉连续空格与换行会让看到的
     与算出来的对不上。pre-wrap 保留空白但仍在容器边界换行 */
  [data-scope='highlight'][data-part='root'] {
    white-space: pre-wrap;
  }

  /* 浏览器给 mark 的默认底色是一个固定的亮黄，暗色主题下压在深底上刺眼、
     配的黑字也不随主题走；这里整份换成随主题走的品牌淡底。
     槽名带 mark 段与部件对上 */
  [data-scope='highlight'][data-part='mark'] {
    padding-inline: var(--xh-highlight-mark-px, var(--xh-space-0_5));
    border-radius: var(--xh-highlight-mark-radius, var(--xh-shape-inset));
    background: var(--xh-highlight-mark-bg, var(--xh-bg-brand-subtle));
    color: var(--xh-highlight-mark-fg, var(--xh-fg-brand-strong));
    font-weight: var(--xh-highlight-mark-font-weight, var(--xh-font-weight-medium));
    /* 命中片段跨行时两半各自收边，否则圆角与内边距只画在整段的首尾。
       两条都写：WebKit 只认带前缀那条 */
    -webkit-box-decoration-break: clone;
    box-decoration-break: clone;
  }

  /* 语气落在根上而不是每个 mark 上：命中片段有好几个，用哪族颜色是整段的属性。
     使用者槽排在语气之前：写死了 mark 的底与字色，六族语气一并让位 */
  [data-scope='highlight'][data-part='root'][data-tone] [data-part='mark'] {
    background: var(--xh-highlight-mark-bg, var(--xh-_tone-subtle));
    color: var(--xh-highlight-mark-fg, var(--xh-_tone-fg));
  }
}

/* styles/icon-wrapper.css */
/* 定义 icon wrapper 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='icon-wrapper'] {
    --xh-icon-wrapper-skin: 1;
  }

  /* 定直径的图标底座：图元在正中，底色、描边与形状由三轴决定。
     直径与图元直径分两个槽位，底座换档时里面的图元跟着一起换 */
  [data-scope='icon-wrapper'][data-part='root'] {
    /* 私有槽位：底座直径与图元直径，换档只改这两个 */
    --xh-_icon-wrapper-size: var(--xh-icon-wrapper-size, var(--xh-control-h-md));

    /* 流给里面的图元——包括自己写了档位的那一枚，它的档位取值也读这个槽，
       图元直径因此始终跟着底座换档 */
    --xh-icon-size: var(--xh-icon-wrapper-glyph-size, var(--xh-glyph-size-md));

    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-_icon-wrapper-size);
    block-size: var(--xh-_icon-wrapper-size);
    border: var(--xh-stroke-thin) solid transparent;
    border-radius: var(--xh-icon-wrapper-radius, var(--xh-shape-circle));
    background: var(--xh-icon-wrapper-bg, var(--xh-bg-subtle));
    color: var(--xh-icon-wrapper-fg, var(--xh-fg-default));
    line-height: var(--xh-leading-none);
  }

  /* 给了 display 的角色节点必须补这条：display 声明会盖掉 UA 的 [hidden]{display:none}，
     不补的话作者给节点加 hidden 后它照样显示 */
  [data-scope='icon-wrapper'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 形态 —— */
  /* 形态只决定颜色怎么用；用哪族颜色由 data-tone 决定，没写 tone 就沿用原来的品牌/中性配色。
     实心档还在顶边画一条极浅的内高光，把这块底座衬出厚度；另外三档面上没有实心底，不画 */
  [data-scope='icon-wrapper'][data-part='root'][data-variant='solid'] {
    --xh-_icon-wrapper-highlight: var(--xh-_highlight-tone);

    background: var(--xh-_tone, var(--xh-bg-brand));
    color: var(--xh-_tone-on, var(--xh-fg-on-brand));
    box-shadow: var(--xh-icon-wrapper-shadow, var(--xh-_icon-wrapper-highlight));
  }

  [data-scope='icon-wrapper'][data-part='root'][data-variant='subtle'] {
    background: var(--xh-_tone-subtle, var(--xh-bg-subtle));
    color: var(--xh-_tone-fg, var(--xh-fg-default));
  }

  [data-scope='icon-wrapper'][data-part='root'][data-variant='outline'] {
    border-color: var(--xh-_tone-border, var(--xh-border-default));
    background: transparent;
    color: var(--xh-_tone-fg, var(--xh-fg-default));
  }

  [data-scope='icon-wrapper'][data-part='root'][data-variant='ghost'] {
    background: transparent;
    color: var(--xh-_tone-fg, var(--xh-fg-default));
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里 */
  [data-scope='icon-wrapper'][data-part='root'][data-size='sm'] {
    --xh-_icon-wrapper-size: var(--xh-icon-wrapper-size, var(--xh-control-h-sm));
    --xh-icon-size: var(--xh-icon-wrapper-glyph-size, var(--xh-glyph-size-sm));
  }

  [data-scope='icon-wrapper'][data-part='root'][data-size='lg'] {
    --xh-_icon-wrapper-size: var(--xh-icon-wrapper-size, var(--xh-control-h-lg));
    --xh-icon-size: var(--xh-icon-wrapper-glyph-size, var(--xh-glyph-size-lg));
  }
}

/* styles/kbd.css */
/* 定义 kbd 样式。 */

@layer xihan.components {
  [data-scope='kbd'] {
    --xh-kbd-skin: 1;
  }

  /* 单键和组合键共用一个整体表面，不模拟按钮按下状态。 */
  [data-scope='kbd'][data-part='root'] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--xh-kbd-gap, var(--xh-space-1));
    box-sizing: border-box;
    block-size: var(--xh-kbd-h, var(--xh-space-6));
    min-inline-size: var(--xh-kbd-min-w, var(--xh-space-6));
    padding-inline: var(--xh-kbd-px, var(--xh-space-2));
    border: var(--xh-stroke-thin) solid var(--xh-kbd-border, transparent);
    border-radius: var(--xh-kbd-radius, var(--xh-shape-control));
    background: var(--xh-kbd-bg, var(--xh-bg-subtle));
    color: var(--xh-kbd-fg, var(--xh-fg-muted));
    font-family: var(--xh-kbd-font, inherit);
    /* 快捷键是次级标注，字号取 caption 档 */
    font-size: var(--xh-kbd-font-size, var(--xh-text-caption-size));
    font-weight: var(--xh-kbd-font-weight, var(--xh-font-weight-medium));
    line-height: var(--xh-leading-none);
    text-align: center;
    text-decoration: none;
    white-space: nowrap;
    direction: ltr;
    unicode-bidi: isolate;
  }

  [data-scope='kbd'][data-part='root'][data-variant='light'] {
    background: transparent;
  }

  [data-scope='kbd'][data-part='key'] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-inline-size: 0;
    padding: 0;
    border: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    line-height: inherit;
  }

  [data-scope='kbd'][data-part='root'][data-disabled] {
    color: var(--xh-kbd-fg-disabled, var(--xh-fg-disabled));
  }

  [data-scope='kbd'][data-part='root'][hidden],
  [data-scope='kbd'][data-part='key'][hidden] {
    display: none;
  }

  @media (forced-colors: active) {
    [data-scope='kbd'][data-part='root']:not([data-variant='light']) {
      border-color: ButtonText;
      background: Canvas;
      color: CanvasText;
    }
  }
}

/* styles/image-cropper.css */
/* 定义 image cropper 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='image-cropper'] {
    --xh-image-cropper-skin: 1;
  }

  /* 定位分工：裁切框在视口里的 left / top / width / height，以及图片与裁切框的
     transform，由连接层每帧写进内联样式——那四个数是图片像素换算出来的百分比，
     只有连接层算得出来。这份皮肤一个都不碰，写了不但是死声明，还会跟内联值抢位置。

     私有槽两个，都挂在 root 上靠继承发下去：
     handle-size 是把手的边长，zoom 是当前缩放倍率——裁切框整体被 scale 放大，
     把手与描边要按倍率反向缩回去，否则放到 3 倍时把手也变成三倍大、描边变成三像素粗。 */
  [data-scope='image-cropper'][data-part='root'] {
    --xh-_image-cropper-handle-size: var(--xh-image-cropper-handle-size, var(--xh-control-indicator-size));
    --xh-_image-cropper-zoom: 1;

    position: relative;
    display: block;
    inline-size: var(--xh-image-cropper-w, 100%);
  }

  /* 量坐标的那个盒子。里面装的是图片像素坐标，不是文字：裁切框与把手的落点一律写物理属性，
     不依赖这里的文字方向。overflow 收口：放大后的图片与遮罩都靠它裁掉。 */
  [data-scope='image-cropper'][data-part='viewport'] {
    position: relative;
    display: block;
    overflow: hidden;
    border-radius: var(--xh-image-cropper-viewport-radius, var(--xh-shape-surface));
    background: var(--xh-image-cropper-bg, var(--xh-bg-muted));
    user-select: none;
  }

  /* 图片铺满视口、高度自适应：视口的高度因此由图片撑出来，
     裁切框的百分比坐标才与图片的像素一一对应。 */
  [data-scope='image-cropper'][data-part='image'] {
    display: block;
    inline-size: 100%;
    block-size: auto;
  }

  /* 裁切框。遮罩用一圈超大的实心投影把框外压暗——不必再摆四块遮罩节点，
     圆形裁切时投影也自动跟着圆角走。描边按倍率缩回去，放大时仍是一根细线。 */
  [data-scope='image-cropper'][data-part='crop-area'] {
    --xh-_image-cropper-corner-radius: var(--xh-shape-control);

    position: absolute;
    box-sizing: border-box;
    border-style: solid;
    border-width: calc(var(--xh-stroke-thin) / var(--xh-_image-cropper-zoom));
    border-color: var(--xh-image-cropper-crop-border, var(--xh-bg-surface));
    box-shadow: 0 0 0 9999px var(--xh-image-cropper-mask, var(--xh-bg-overlay));
    cursor: move;
  }

  /* 圆形裁切取 circle 档（50%）：shape 的固定长度档画出来是胶囊不是椭圆，
     裁切框的宽高由数据决定、两边通常不等长，只有百分比才随框变成椭圆；圆角只能来自语义形状令牌 */
  [data-scope='image-cropper'][data-part='crop-area'][data-shape='round'] {
    --xh-_image-cropper-corner-radius: var(--xh-shape-circle);

    border-radius: var(--xh-image-cropper-crop-area-radius, var(--xh-shape-circle));
  }

  [data-scope='image-cropper'][data-part='crop-area'][data-dragging] {
    cursor: grabbing;
  }

  [data-scope='image-cropper'][data-part='crop-area'][data-readonly]:not([data-disabled]) {
    cursor: default;
  }

  /* 三分构图参考线：两条竖线、两条横线，落点写死在三分处，不占节点、不吃指针。
     停靠点逐条写全而不用 repeating-：重复单元从 0 起算会在框的两条边缘上各多画一根，
     那两根与裁切框的描边叠在一起，看着像描边加粗了一倍。
     线宽跟着裁切框的倍率缩回去，与描边同一口径。
     圆形裁切时参考线没有意义，收起来。 */
  [data-scope='image-cropper'][data-part='grid'] {
    --xh-_image-cropper-grid-w: calc(var(--xh-stroke-thin) / var(--xh-_image-cropper-zoom));

    position: absolute;
    inset: 0;
    background-image:
      linear-gradient(
        to right,
        transparent 0 33.3333%,
        var(--xh-image-cropper-grid-line, var(--xh-border-subtle)) 33.3333% calc(33.3333% + var(--xh-_image-cropper-grid-w)),
        transparent calc(33.3333% + var(--xh-_image-cropper-grid-w)) 66.6667%,
        var(--xh-image-cropper-grid-line, var(--xh-border-subtle)) 66.6667% calc(66.6667% + var(--xh-_image-cropper-grid-w)),
        transparent calc(66.6667% + var(--xh-_image-cropper-grid-w)) 100%
      ),
      linear-gradient(
        to bottom,
        transparent 0 33.3333%,
        var(--xh-image-cropper-grid-line, var(--xh-border-subtle)) 33.3333% calc(33.3333% + var(--xh-_image-cropper-grid-w)),
        transparent calc(33.3333% + var(--xh-_image-cropper-grid-w)) 66.6667%,
        var(--xh-image-cropper-grid-line, var(--xh-border-subtle)) 66.6667% calc(66.6667% + var(--xh-_image-cropper-grid-w)),
        transparent calc(66.6667% + var(--xh-_image-cropper-grid-w)) 100%
      );
    pointer-events: none;
  }

  [data-scope='image-cropper'][data-part='grid'][data-shape='round'] {
    background-image: none;
  }

  /* 把手的命中区仍以裁切框边界为中心，视觉短条与折角贴住边框并向框内绘制。 */
  [data-scope='image-cropper'][data-part='crop-handle'] {
    --xh-_image-cropper-handle-color: var(--xh-image-cropper-handle-bg, var(--xh-bg-surface));

    position: absolute;
    display: block;
    box-sizing: border-box;
    border: 0;
    background: transparent;
    inline-size: var(--xh-_image-cropper-handle-size);
    block-size: var(--xh-_image-cropper-handle-size);
    translate: -50% -50%;
    scale: calc(1 / var(--xh-_image-cropper-zoom));
  }

  [data-scope='image-cropper'][data-part='crop-handle']::after {
    content: '';
    position: absolute;
    box-sizing: border-box;
    border-radius: var(--xh-image-cropper-handle-radius, var(--xh-shape-pill));
    background: var(--xh-_image-cropper-handle-color);
    pointer-events: none;
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      border-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 看得见的方块比手指小：另铺一层不可见的命中区，把它撑到最小可点尺寸。
     inset 取负值即向四面外扩，方块本身更大时这个值转正、命中区仍是方块那么大。 */
  [data-scope='image-cropper'][data-part='crop-handle']::before {
    position: absolute;
    inset: calc((var(--xh-_image-cropper-handle-size) - var(--xh-control-action-size)) / 2);
    content: '';
  }

  /* 把手静息是白面（bg-surface），悬停从同一语义面派生一档，不切到品牌淡底；拖动中才是品牌实心 */
  [data-scope='image-cropper'][data-part='crop-handle']:hover:not([data-disabled], [data-readonly]) {
    --xh-_image-cropper-handle-color: var(--xh-image-cropper-handle-bg-hover, var(--xh-bg-subtle));
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-resizing] {
    --xh-_image-cropper-handle-color: var(--xh-image-cropper-handle-bg-resizing, var(--xh-bg-brand));
  }

  [data-scope='image-cropper'][data-part='crop-handle']:focus-visible {
    --xh-_image-cropper-handle-color: var(--xh-ring-focus);

    outline: none;
  }

  /* —— 八个方位：落点 + 光标 —— */
  [data-scope='image-cropper'][data-part='crop-handle'][data-position='nw'] {
    top: 0;
    /* stylelint-disable-next-line property-disallowed-list -- 裁切框的坐标是图片像素，落点跟着物理方向走 */
    left: 0;
    cursor: nwse-resize;
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='n'] {
    top: 0;
    /* stylelint-disable-next-line property-disallowed-list -- 同上 */
    left: 50%;
    cursor: ns-resize;
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='ne'] {
    top: 0;
    /* stylelint-disable-next-line property-disallowed-list -- 同上 */
    left: 100%;
    cursor: nesw-resize;
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='e'] {
    top: 50%;
    /* stylelint-disable-next-line property-disallowed-list -- 同上 */
    left: 100%;
    cursor: ew-resize;
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='se'] {
    top: 100%;
    /* stylelint-disable-next-line property-disallowed-list -- 同上 */
    left: 100%;
    cursor: nwse-resize;
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='s'] {
    top: 100%;
    /* stylelint-disable-next-line property-disallowed-list -- 同上 */
    left: 50%;
    cursor: ns-resize;
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='sw'] {
    top: 100%;
    /* stylelint-disable-next-line property-disallowed-list -- 同上 */
    left: 0;
    cursor: nesw-resize;
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='w'] {
    top: 50%;
    /* stylelint-disable-next-line property-disallowed-list -- 同上 */
    left: 0;
    cursor: ew-resize;
  }

  /* stylelint-disable property-disallowed-list -- 裁切框的八向位置使用图片物理坐标，内部标记必须朝对应物理方向内收 */
  [data-scope='image-cropper'][data-part='crop-handle']:is([data-position='n'], [data-position='s'])::after {
    left: 50%;
    inline-size: var(--xh-image-cropper-handle-length, var(--xh-space-8));
    block-size: var(--xh-image-cropper-handle-thickness, var(--xh-stroke-strong));
    translate: -50% 0;
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='n']::after {
    top: 50%;
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='s']::after {
    bottom: 50%;
  }

  [data-scope='image-cropper'][data-part='crop-handle']:is([data-position='e'], [data-position='w'])::after {
    top: 50%;
    inline-size: var(--xh-image-cropper-handle-thickness, var(--xh-stroke-strong));
    block-size: var(--xh-image-cropper-handle-length, var(--xh-space-8));
    translate: 0 -50%;
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='e']::after {
    right: 50%;
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='w']::after {
    left: 50%;
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='nw'] {
    border-start-start-radius: var(--xh-_image-cropper-corner-radius);
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='ne'] {
    border-start-end-radius: var(--xh-_image-cropper-corner-radius);
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='sw'] {
    border-end-start-radius: var(--xh-_image-cropper-corner-radius);
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='se'] {
    border-end-end-radius: var(--xh-_image-cropper-corner-radius);
  }

  [data-scope='image-cropper'][data-part='crop-handle']:is(
    [data-position='nw'],
    [data-position='ne'],
    [data-position='sw'],
    [data-position='se']
  )::after {
    inline-size: calc(var(--xh-_image-cropper-handle-size) / 2);
    block-size: calc(var(--xh-_image-cropper-handle-size) / 2);
    border: 0 solid var(--xh-image-cropper-handle-border, var(--xh-_image-cropper-handle-color));
    border-radius: inherit;
    background: transparent;
    outline: none;
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='nw']::after {
    right: 0;
    bottom: 0;
    border-block-start-width: var(--xh-image-cropper-handle-thickness, var(--xh-stroke-strong));
    border-inline-start-width: var(--xh-image-cropper-handle-thickness, var(--xh-stroke-strong));
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='ne']::after {
    bottom: 0;
    left: 0;
    border-block-start-width: var(--xh-image-cropper-handle-thickness, var(--xh-stroke-strong));
    border-inline-end-width: var(--xh-image-cropper-handle-thickness, var(--xh-stroke-strong));
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='sw']::after {
    top: 0;
    right: 0;
    border-block-end-width: var(--xh-image-cropper-handle-thickness, var(--xh-stroke-strong));
    border-inline-start-width: var(--xh-image-cropper-handle-thickness, var(--xh-stroke-strong));
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-position='se']::after {
    top: 0;
    left: 0;
    border-block-end-width: var(--xh-image-cropper-handle-thickness, var(--xh-stroke-strong));
    border-inline-end-width: var(--xh-image-cropper-handle-thickness, var(--xh-stroke-strong));
  }
  /* stylelint-enable property-disallowed-list */

  /* 只读与禁用的光标排在八个方位之后：那八条每条都写了 cursor，特异性又完全相同，
     排在前面会被逐条盖掉，整条规则等于没写。 */
  [data-scope='image-cropper'][data-part='crop-handle'][data-readonly] {
    cursor: default;
  }

  [data-scope='image-cropper'][data-part='crop-handle'][data-disabled] {
    cursor: not-allowed;
  }

  /* 两条控制轴用原生 range：拇指与轨道交给平台画，这里只给横向铺满与品牌色。
     不写 block-size：原生 range 的高度由 UA 与拇指尺寸定，写死会把拇指切掉一截。 */
  [data-scope='image-cropper'][data-part='zoom-slider'],
  [data-scope='image-cropper'][data-part='rotate-slider'] {
    inline-size: var(--xh-image-cropper-slider-w, 100%);
    /* 原生 range 自带左右各一段外边距，与铺满的宽度叠在一起就把这两条轴顶出容器 */
    margin-inline: 0;
    accent-color: var(--xh-image-cropper-slider-accent, var(--xh-bg-brand));
  }

  /* 禁用的整体压暗只做一次，落在最外层：视口、裁切框、把手各自再叠一层会越叠越黑。
     这里只用 opacity、不换前景色：框里是图像，没有文字可换。 */
  [data-scope='image-cropper'][data-part='root'][data-disabled] {
    opacity: var(--xh-state-disabled-opacity);
  }

  /* hidden-input 是 type=hidden 的原生输入，浏览器本就不渲染它，
     这里一条声明都不给：给了 display / 尺寸反而会把它拽回布局里撑出一块空白。 */

  /* display 会盖掉 UA 的 [hidden]{display:none}，凡是被赋了 display 的角色节点都要显式让位。
     这条必须排在全部 display 声明之后。 */
  [data-scope='image-cropper'][data-part='root'][hidden],
  [data-scope='image-cropper'][data-part='viewport'][hidden],
  [data-scope='image-cropper'][data-part='image'][hidden],
  [data-scope='image-cropper'][data-part='crop-handle'][hidden] {
    display: none;
  }
}

/* styles/infinite-scroll.css */
/* 定义 infinite scroll 样式。 */

/* 独立皮肤同时传递引入取下一页按钮的动作控件配方，full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='infinite-scroll'] {
    --xh-infinite-scroll-skin: 1;
  }

  /* 这里的 data-disabled 关掉的是「还取不取下一页」，列表本身照常可读可点：
     光标交回给作者，不摆共享层那个「不可用」的样子 */
  [data-scope='infinite-scroll'][data-part='root'][data-disabled] {
    cursor: inherit;
  }

  /*
   * 列表外壳这一层刻意不给盒模型：滚的是页面还是作者自己的 overflow 容器、列表长什么样，
   * 都归作者的布局管，组件只往它身上挂 data-loading / data-disabled 供作者取用。
   * 一旦声明 display，UA 的 [hidden]{display:none} 就压不住了，故连 display 也不写。
   *
   * 哨兵是纯机制，不是可见元素：给它一条最细的高度让它有个能被观察到的盒子，
   * 高度为 0 的元素在部分实现里交叠比恒为 0，永远等不到进入。
   * 不吃指针：它紧贴在列表末尾，吃了指针就会挡住最后一条的点击。
   */
  [data-scope='infinite-scroll'][data-part='sentinel'] {
    display: block;
    inline-size: 100%;
    block-size: var(--xh-infinite-scroll-sentinel-size, var(--xh-stroke-thin));
    pointer-events: none;
  }

  /*
   * 取下一页的按钮：与哨兵同一条通路的键盘入口，摆在列表末尾自成一行——铺满一行的独立动作条目，
   * 接 Action Control 的 row 档、outline 形态：宽度由容器给、高度随内容、按下只换面不缩放；
   * 盒几何、中性描边与透明底、悬停 / 按下 / 禁用面、焦点环与粗指针热区全由家族给，
   * 白底承载 hover 100 → pressed 200。这里只把使用者槽映射到桥接槽，并把文案居中：
   * 它是一行里唯一的东西，靠起始缘会像一条没对齐的列表项。
   * 行高不吃家族的单行档：row 档允许换行、高度随内容，折行的文案走正文行高
   */
  [data-scope='infinite-scroll'][data-part='load-more-trigger'] {
    --xh-action-gap: var(--xh-infinite-scroll-load-more-gap, var(--xh-_action-profile-gap));
    --xh-action-visual-size: var(--xh-infinite-scroll-load-more-h, var(--xh-_action-profile-visual-size));
    --xh-action-padding-inline: var(--xh-infinite-scroll-load-more-px, var(--xh-_action-profile-padding-inline));
    --xh-action-radius: var(--xh-infinite-scroll-load-more-radius, var(--xh-_action-profile-radius));
    --xh-action-border-rest: var(--xh-infinite-scroll-load-more-border, var(--xh-_action-variant-border-rest));
    --xh-action-border-hover: var(--xh-infinite-scroll-load-more-border-hover, var(--xh-_action-variant-border-hover));
    --xh-action-border-pressed: var(--xh-infinite-scroll-load-more-border-hover, var(--xh-_action-variant-border-pressed));
    --xh-action-bg-rest: var(--xh-infinite-scroll-load-more-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-infinite-scroll-load-more-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-infinite-scroll-load-more-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-infinite-scroll-load-more-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-infinite-scroll-load-more-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-infinite-scroll-load-more-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-font-size: var(--xh-infinite-scroll-load-more-font-size, var(--xh-text-body-size));
    /* 作者塞进钮里的图标按档取字形尺寸，与文案同一把尺 */
    --xh-icon-size: var(--xh-infinite-scroll-load-more-icon-size, var(--xh-_action-profile-glyph-size));

    justify-content: center;
    text-align: center;
    line-height: var(--xh-leading-normal);
    /* 到底了连点是常态，触屏上默认会当成双击缩放 */
    touch-action: manipulation;
  }

  /* 声明过 display 就盖掉了 UA 的 [hidden]{display:none}，作者要藏哨兵时得自己补回来 */
  [data-scope='infinite-scroll'][data-part='sentinel'][hidden],
  [data-scope='infinite-scroll'][data-part='load-more-trigger'][hidden] {
    display: none;
  }
}

/* styles/input-group.css */
/* 定义 input group 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='input-group'] {
    --xh-input-group-skin: 1;
  }

  /* 输入框、前后缀和动作共用一个输入表面。组只统一材质与外轮廓，语义仍归各子控件。 */
  [data-scope='input-group'][data-part='root'] {
    /* 段之间那几档层号只在自己人之间排序：建一个层叠上下文把它们关起来，
       既不让页面上的层号插进来，也不让它们漏出去压住别人 */
    isolation: isolate;

    /* 缺省档。item 的高度、内衬与字号从这三个槽取，换档只改这里 */
    --xh-_input-group-h: var(--xh-control-h-md);
    --xh-_input-group-px: var(--xh-control-px-md);
    --xh-_input-group-font-size: var(--xh-control-font-md);
    --xh-_input-group-bg: transparent;
    --xh-_input-group-bg-hover: color-mix(in oklab, var(--xh-bg-subtle) 45%, transparent);
    /* 组壳按字段外壳画 outline 描边：静息 --xh-border-control、悬停升 -hover、聚焦换 -focus，无影 */
    --xh-_input-group-border: var(--xh-border-control);
    --xh-_input-group-border-hover: var(--xh-border-control-hover);
    --xh-_input-group-border-focus: var(--xh-border-control-focus);
    --xh-_input-group-shadow: none;

    position: relative;
    display: inline-flex;
    box-sizing: border-box;
    align-items: stretch;
    border-radius: var(--xh-input-group-radius, var(--xh-shape-control));
    background: var(--xh-input-group-bg, var(--xh-_input-group-bg));
    box-shadow: var(--xh-input-group-shadow, var(--xh-_input-group-shadow));

    /* 父容器给不出这么宽时整组跟着收，不越出父容器 */
    max-inline-size: 100%;
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      box-shadow var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 外轮廓不占盒尺寸，组内控件仍保持与独立使用时相同的高度。 */
  [data-scope='input-group'][data-part='root']::before {
    content: '';
    position: absolute;
    z-index: 2;
    inset: 0;
    border: var(--xh-stroke-thin) solid var(--xh-input-group-border, var(--xh-_input-group-border));
    border-radius: inherit;
    pointer-events: none;
    transition: border-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* subtle：淡底顶替描边表达边界，描边只退成透明而不去掉；悬停浮出 --xh-border-control */
  [data-scope='input-group'][data-part='root'][data-variant='subtle'] {
    --xh-_input-group-bg: var(--xh-bg-subtle);
    --xh-_input-group-bg-hover: var(--xh-bg-subtle-hover);
    --xh-_input-group-border: transparent;
    --xh-_input-group-border-hover: var(--xh-border-control);
    --xh-_input-group-shadow: none;
  }

  /* ghost：静息不画壳，悬停与聚焦沿用下面的 hover / focus 规则浮出 --xh-border-control 与底 */
  [data-scope='input-group'][data-part='root'][data-variant='ghost'] {
    --xh-_input-group-bg: transparent;
    --xh-_input-group-border: transparent;
    --xh-_input-group-border-hover: var(--xh-border-control);
    --xh-_input-group-shadow: none;
  }

  [data-scope='input-group'][data-part='root']:not(:has([data-disabled])):hover {
    background: var(--xh-input-group-bg-hover, var(--xh-_input-group-bg-hover));
  }

  [data-scope='input-group'][data-part='root']:not(:has([data-disabled])):hover::before {
    border-color: var(--xh-input-group-border-hover, var(--xh-_input-group-border-hover));
  }

  [data-scope='input-group'][data-part='root']:focus-within {
    outline: var(--xh-ring-width) solid var(--xh-input-group-ring-focus, var(--xh-ring-focus));
    outline-offset: var(--xh-ring-offset);
  }

  [data-scope='input-group'][data-part='root']:focus-within::before {
    border-color: var(--xh-input-group-border-focus, var(--xh-_input-group-border-focus));
  }

  [data-scope='input-group'][data-part='root']:has([data-invalid], [aria-invalid='true'])::before {
    border-color: var(--xh-input-group-border-invalid, var(--xh-border-invalid));
  }

  [data-scope='input-group'][data-part='root']:has([data-invalid], [aria-invalid='true']):focus-within {
    outline-color: var(--xh-input-group-ring-invalid, var(--xh-ring-invalid));
  }

  /* 给了 display 的角色节点必须补这条：display 声明会盖掉 UA 的 [hidden]{display:none}，
     不补的话作者给节点加 hidden 后它照样显示 */
  [data-scope='input-group'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 尺寸 —— */
  /* 档位跟着组内控件走：控件的档位就写在它自己的根上，组读得到，
     于是前后缀块与邻座同高，作者不必把同一档在组上再写一遍。
     缺省档写在上面的基础规则里 */
  [data-scope='input-group'][data-part='root']:has([data-size='sm']) {
    --xh-_input-group-h: var(--xh-control-h-sm);
    --xh-_input-group-px: var(--xh-control-px-sm);
    --xh-_input-group-font-size: var(--xh-control-font-sm);
  }

  [data-scope='input-group'][data-part='root']:has([data-size='lg']) {
    --xh-_input-group-h: var(--xh-control-h-lg);
    --xh-_input-group-px: var(--xh-control-px-lg);
    --xh-_input-group-font-size: var(--xh-control-font-lg);
  }

  /* 组上写了档位时以它为准：排在自动档后面，同特指度下压得住 */
  [data-scope='input-group'][data-part='root'][data-size='sm'] {
    --xh-_input-group-h: var(--xh-control-h-sm);
    --xh-_input-group-px: var(--xh-control-px-sm);
    --xh-_input-group-font-size: var(--xh-control-font-sm);
  }

  [data-scope='input-group'][data-part='root'][data-size='md'] {
    --xh-_input-group-h: var(--xh-control-h-md);
    --xh-_input-group-px: var(--xh-control-px-md);
    --xh-_input-group-font-size: var(--xh-control-font-md);
  }

  [data-scope='input-group'][data-part='root'][data-size='lg'] {
    --xh-_input-group-h: var(--xh-control-h-lg);
    --xh-_input-group-px: var(--xh-control-px-lg);
    --xh-_input-group-font-size: var(--xh-control-font-lg);
  }

  /* 子控件不再各画一层输入表面，悬停与聚焦统一落在组的外轮廓。 */
  [data-scope='input-group'][data-part='root'] [data-xh-field-chrome] {
    --xh-field-bg-rest: transparent;
    --xh-field-bg-hover: transparent;
    --xh-field-bg-read-only: transparent;
    --xh-field-bg-disabled: transparent;
    --xh-field-border-rest: transparent;
    --xh-field-border-hover: transparent;
    --xh-field-border-focus: transparent;
    --xh-field-border-invalid: transparent;
    --xh-field-shadow-rest: none;
    --xh-field-shadow-read-only: none;
    --xh-field-shadow-disabled: none;

    border-color: transparent;
    background-color: transparent;
    box-shadow: none;
    /* 内层表面始终透明，不播放字段自身的边框/背景过渡，避免失焦时短暂闪回。 */
    transition: none;
  }

  /* 焦点环由组的外表面绘制，子输入保留焦点语义但不再重复画第二圈。 */
  [data-scope='input-group'][data-part='root'] [data-xh-field-chrome]:focus-within {
    outline: none;
  }

  [data-scope='input-group'][data-part='root'] [data-xh-field-chrome]:hover,
  [data-scope='input-group'][data-part='root'] [data-xh-field-chrome]:focus-within,
  [data-scope='input-group'][data-part='root'] [data-xh-field-chrome][data-invalid],
  [data-scope='input-group'][data-part='root'] [data-xh-field-chrome][data-readonly],
  [data-scope='input-group'][data-part='root'] [data-xh-field-chrome][data-disabled] {
    border-color: transparent;
    background-color: transparent;
    box-shadow: none;
  }

  /* 每一段都是定位元素，动作控件的悬停面可以浮到外轮廓之上。 */
  [data-scope='input-group'][data-part='root'] > * {
    position: relative;
  }

  /* 悬停或拿到焦点的动作段抬到外轮廓同层，自己的反馈不会被邻座覆盖。 */
  [data-scope='input-group'][data-part='root'] > *:hover,
  [data-scope='input-group'][data-part='root'] > *:focus-within {
    z-index: 2;
  }

  /* —— 两端圆角 —— */
  /* 画着描边的那个盒子有三种落点：段本身、段就是控件盒、控件盒在段里一层。
     :is() 取其中最特指的一支算特指度，三种落点因此都压得住控件自己那条圆角规则。
     只认直接子节点与它下面那一层：更深的节点是控件的内部结构，圆错了位置比直角更糟 */
  [data-scope='input-group'][data-part='root'] > :is(*, [data-part='control'], [data-part='root']),
  [data-scope='input-group'][data-part='root'] > * :is([data-part='control'], [data-part='root']) {
    border-start-start-radius: 0;
    border-start-end-radius: 0;
    border-end-start-radius: 0;
    border-end-end-radius: 0;
  }

  /* 逻辑角属性写，rtl 跟着换边，不必另写一套 */
  [data-scope='input-group'][data-part='root'] > :is(*, [data-part='control'], [data-part='root']):first-child,
  [data-scope='input-group'][data-part='root'] > *:first-child :is([data-part='control'], [data-part='root']) {
    border-start-start-radius: var(--xh-input-group-radius, var(--xh-shape-control));
    border-end-start-radius: var(--xh-input-group-radius, var(--xh-shape-control));
  }

  [data-scope='input-group'][data-part='root'] > :is(*, [data-part='control'], [data-part='root']):last-child,
  [data-scope='input-group'][data-part='root'] > *:last-child :is([data-part='control'], [data-part='root']) {
    border-start-end-radius: var(--xh-input-group-radius, var(--xh-shape-control));
    border-end-end-radius: var(--xh-input-group-radius, var(--xh-shape-control));
  }

  /* —— 前后缀块 —— */
  /* 前后缀是输入表面里的静态内容，不单独绘制底色、描边或焦点状态。 */
  [data-scope='input-group'][data-part='item'] {
    display: inline-flex;
    box-sizing: border-box;
    flex: none;
    align-items: center;
    block-size: var(--xh-input-group-item-h, var(--xh-_input-group-h));
    padding-inline: var(--xh-input-group-item-px, var(--xh-_input-group-px));
    color: var(--xh-input-group-item-fg, var(--xh-fg-muted));
    font-size: var(--xh-input-group-item-font-size, var(--xh-_input-group-font-size));
    line-height: var(--xh-leading-none);
    white-space: nowrap;
  }

  /* 与输入控件相邻的一侧由控件自己的内距留白，避免前后缀之间出现双份间距。 */
  [data-scope='input-group'][data-part='root'] > [data-scope='input-group'][data-part='item']:first-child {
    padding-inline-end: 0;
  }

  [data-scope='input-group'][data-part='root'] > [data-scope='input-group'][data-part='item']:last-child {
    padding-inline-start: 0;
  }

  [data-scope='input-group'][data-part='item'][hidden] {
    display: none;
  }

  @media (forced-colors: active) {
    [data-scope='input-group'][data-part='root'] {
      background: Canvas;
      box-shadow: none;
    }

    [data-scope='input-group'][data-part='root']::before {
      border-color: ButtonText;
    }

    [data-scope='input-group'][data-part='root']:focus-within {
      outline-color: Highlight;
    }

    [data-scope='input-group'][data-part='root']:focus-within::before,
    [data-scope='input-group'][data-part='root']:has([data-invalid], [aria-invalid='true'])::before {
      border-color: Highlight;
    }

    [data-scope='input-group'][data-part='item'] {
      color: CanvasText;
    }
  }
}

/* styles/json-viewer.css */
/* 定义 json viewer 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='json-viewer'] {
    --xh-json-viewer-skin: 1;
  }

  /* 缺省态（md 档）。等宽字体让层级缩进与值的长度对得齐。
     逐类型配色走 --xh-syntax-* 语法令牌，与代码块的记号色同源、随主题明暗切换。 */
  [data-scope='json-viewer'][data-part='root'] {
    /* 作者放进空态格里的图标按档取尺，缺省 md，随 data-size 换档。
       查看器自绘的状态字形（分支行首的展开方向 chevron）不读这支：它是指示符，与所在的把手盒同走
       --xh-control-indicator-* 一族——branch-trigger 在自己身上把 --xh-icon-size 改接到盒的尺 */
    --xh-icon-size: var(--xh-json-viewer-icon-size, var(--xh-glyph-size-md));

    --xh-_json-viewer-font-size: var(--xh-control-caption-md);
    --xh-_json-viewer-row-py: var(--xh-space-0_5);
    --xh-_json-viewer-indent: var(--xh-space-4);

    display: block;
    color: var(--xh-json-viewer-fg, var(--xh-fg-default));
    font-family: var(--xh-json-viewer-font, var(--xh-font-family-mono));
    font-size: var(--xh-json-viewer-font-size, var(--xh-_json-viewer-font-size));
    line-height: var(--xh-leading-normal);
  }

  /* 写了 display 就会盖掉 UA 的 [hidden]{display:none}，这里补回 */
  [data-scope='json-viewer'][data-part='root'][hidden] {
    display: none;
  }

  /* 面画在两档容器与空态格上，root 只是壳。三档按边界三选一：outline 即基础规则
     （--xh-border-default 描边 + surface 底 + 无影）；淡底档描边透明、底换 subtle；
     无框档边框留着但透明——去掉外框不会让行的位置跳一格 */
  [data-scope='json-viewer'][data-part='root'][data-variant='subtle']
    :is([data-scope='json-viewer'][data-part='tree'], [data-scope='json-viewer'][data-part='text'], [data-scope='json-viewer'][data-part='empty']) {
    border-color: transparent;
    background: var(--xh-json-viewer-bg, var(--xh-bg-subtle));
  }

  [data-scope='json-viewer'][data-part='root'][data-variant='ghost']
    :is([data-scope='json-viewer'][data-part='tree'], [data-scope='json-viewer'][data-part='text'], [data-scope='json-viewer'][data-part='empty']) {
    border-color: transparent;
    background: transparent;
  }

  /* 尺寸轴只换私有槽，部件从 root 继承 */
  [data-scope='json-viewer'][data-part='root'][data-size='sm'] {
    --xh-icon-size: var(--xh-json-viewer-icon-size, var(--xh-glyph-size-sm));
    --xh-_json-viewer-font-size: var(--xh-control-caption-sm);
    --xh-_json-viewer-row-py: var(--xh-space-0);
    --xh-_json-viewer-indent: var(--xh-space-3);
  }

  [data-scope='json-viewer'][data-part='root'][data-size='lg'] {
    --xh-icon-size: var(--xh-json-viewer-icon-size, var(--xh-glyph-size-lg));
    --xh-_json-viewer-font-size: var(--xh-control-caption-lg);
    --xh-_json-viewer-row-py: var(--xh-space-1);
    --xh-_json-viewer-indent: var(--xh-space-5);
  }

  /* 常驻容器不是浮层：两轴都可能溢出——深层缩进往行首方向推、长字符串往行尾伸；
     页内结构容器走 reset 层的原生细条，不写 overscroll */
  [data-scope='json-viewer'][data-part='tree'] {
    display: flex;
    flex-direction: column;
    max-block-size: var(--xh-json-viewer-max-h, var(--xh-viewport-max-h));
    padding-block: var(--xh-json-viewer-py, var(--xh-space-2));
    padding-inline: var(--xh-json-viewer-px, var(--xh-space-2));
    border: var(--xh-stroke-thin) solid var(--xh-json-viewer-border, var(--xh-border-default));
    border-radius: var(--xh-json-viewer-radius, var(--xh-shape-surface));
    background: var(--xh-json-viewer-bg, var(--xh-bg-surface));
    box-shadow: var(--xh-json-viewer-shadow, none);
    overflow: auto;
  }

  /* 原文档：与树档共用同一套边框、内衬与高度令牌，两档切过去盒子不跳。
     整块可框选——这一档存在的理由就是把与后端一字不差的那份原文交到手上 */
  [data-scope='json-viewer'][data-part='text'] {
    margin: 0;
    max-block-size: var(--xh-json-viewer-max-h, var(--xh-viewport-max-h));
    padding-block: var(--xh-json-viewer-py, var(--xh-space-2));
    padding-inline: var(--xh-json-viewer-px, var(--xh-space-2));
    border: var(--xh-stroke-thin) solid var(--xh-json-viewer-border, var(--xh-border-default));
    border-radius: var(--xh-json-viewer-radius, var(--xh-shape-surface));
    background: var(--xh-json-viewer-bg, var(--xh-bg-surface));
    box-shadow: var(--xh-json-viewer-shadow, none);
    color: var(--xh-json-viewer-text-fg, var(--xh-fg-default));
    font-family: var(--xh-json-viewer-font, var(--xh-font-family-mono));
    /* 缩进靠空格，行不折：折行会把层级读乱，横向给滚动条 */
    white-space: pre;
    tab-size: 2;
    overflow: auto;
    user-select: text;
  }

  [data-scope='json-viewer'][data-part='text'][hidden] {
    display: none;
  }
  [data-scope='json-viewer'][data-part='tree'][hidden] {
    display: none;
  }

  /* 焦点在树外时容器自己进 Tab 序列兜底，落焦不画环：环永远长在行上 */
  [data-scope='json-viewer'][data-part='tree']:focus-visible {
    outline: none;
  }

  /* 焦点落在 branch 上（它才是 treeitem），但环画在它自己那一行上：
     整棵子层套一圈描边会把展开的层级全框进去 */
  [data-scope='json-viewer'][data-part='branch']:focus-visible {
    outline: none;
  }

  [data-scope='json-viewer'][data-part='branch']:focus-visible > [data-scope='json-viewer'][data-part='branch-control'] {
    outline: var(--xh-ring-width) solid var(--xh-ring-focus);
    outline-offset: var(--xh-ring-offset);
  }

  /* 行：标量与分支共用同一套盒子，两种行在视觉上必须齐平 */
  [data-scope='json-viewer'][data-part='item'],
  [data-scope='json-viewer'][data-part='branch-control'] {
    display: flex;
    align-items: baseline;
    gap: var(--xh-json-viewer-row-gap, var(--xh-space-1));
    padding-block: var(--xh-json-viewer-row-py, var(--xh-_json-viewer-row-py));
    padding-inline: var(--xh-json-viewer-row-px, var(--xh-space-1));
    border-radius: var(--xh-json-viewer-row-radius, var(--xh-shape-inset));
    white-space: nowrap;
    transition: background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='json-viewer'][data-part='item'][hidden],
  [data-scope='json-viewer'][data-part='branch-control'][hidden] {
    display: none;
  }

  /* 悬停与键盘锚点共用中性灰轻档：data-highlighted 跟的是连接层记的焦点行，
     键盘落焦另有聚焦环标记位置 */
  [data-scope='json-viewer'][data-part='item']:is(:hover, [data-highlighted]),
  [data-scope='json-viewer'][data-part='branch-control']:is(:hover, [data-highlighted]) {
    background: var(--xh-json-viewer-row-bg-hover, var(--xh-bg-subtle));
  }

  /* 分支那一行是唯一的点击目标：点它切换展开态 */
  [data-scope='json-viewer'][data-part='branch-control'] {
    cursor: pointer;
    user-select: none;
  }

  /* 按下只换面不缩放：白底承载 hover 100 → pressed 200（集合行不允许零反馈）；
     指针按住由 :active 表出，Space / Enter 与触屏按住由 Headless 投影 data-pressed，三种输入同一副面 */
  [data-scope='json-viewer'][data-part='branch-control']:not([data-disabled]):is(:active, [data-pressed]) {
    background: var(--xh-json-viewer-row-bg-active, var(--xh-bg-subtle-hover));
  }

  /* 键名不参与压缩：它短且必须完整可读，被挤掉的应该是值 */
  [data-scope='json-viewer'][data-part='item-key'],
  [data-scope='json-viewer'][data-part='branch-text'] {
    flex: none;
    color: var(--xh-json-viewer-key-fg, var(--xh-fg-brand-strong));
    font-weight: var(--xh-json-viewer-key-font-weight, var(--xh-font-weight-medium));
  }

  /* 键名与值之间的冒号由皮肤画：它是排版符号，进不了可及名字反而更清爽 */
  [data-scope='json-viewer'][data-part='item-key']::after,
  [data-scope='json-viewer'][data-part='branch-text']::after {
    content: ':';
    color: var(--xh-json-viewer-punctuation-fg, var(--xh-fg-subtle));
  }

  /* 弹性子项默认最小尺寸是内容尺寸，不归零则长字符串把行撑破、省略号轮不上 */
  [data-scope='json-viewer'][data-part='item-value'] {
    flex: 1 1 auto;
    min-inline-size: 0;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  [data-scope='json-viewer'][data-part='item-value'][data-value-type='string'] {
    color: var(--xh-json-viewer-string-fg, var(--xh-syntax-string));
  }

  [data-scope='json-viewer'][data-part='item-value'][data-value-type='number'] {
    color: var(--xh-json-viewer-number-fg, var(--xh-syntax-number));
  }

  [data-scope='json-viewer'][data-part='item-value'][data-value-type='boolean'] {
    color: var(--xh-json-viewer-boolean-fg, var(--xh-syntax-keyword));
  }

  [data-scope='json-viewer'][data-part='item-value'][data-value-type='null'] {
    color: var(--xh-json-viewer-null-fg, var(--xh-fg-subtle));
  }

  /* 空对象与空数组只剩一对括号，跟标点同色 */
  [data-scope='json-viewer'][data-part='item-value'][data-value-type='array'],
  [data-scope='json-viewer'][data-part='item-value'][data-value-type='object'] {
    color: var(--xh-json-viewer-punctuation-fg, var(--xh-fg-subtle));
  }

  /* 循环引用与截断占位不是真数据，排在语气之外用弱化字重表达 */
  [data-scope='json-viewer'][data-part='item-value'][data-circular],
  [data-scope='json-viewer'][data-part='item-value'][data-truncated] {
    color: var(--xh-fg-muted);
    font-style: italic;
  }

  /* 展开箭头与勾选标记同宽，两种行的文字起点才对得齐。
     盒里的 chevron 是指示符：与盒同边长，--xh-icon-size 在自己身上改接到盒的尺——
     root 那支只管作者图标的 --xh-json-viewer-icon-size 不流进来，按图标档取的 20px 会比 16px 的盒还大；
     branch-indicator 由适配器固定渲染在这颗把手里，继承即可 */
  [data-scope='json-viewer'][data-part='branch-trigger'] {
    --xh-icon-size: var(--xh-json-viewer-indicator-size, var(--xh-control-indicator-size));

    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-json-viewer-indicator-size, var(--xh-control-indicator-size));
    color: var(--xh-json-viewer-indicator-fg, var(--xh-fg-subtle));
  }

  [data-scope='json-viewer'][data-part='branch-trigger'][hidden] {
    display: none;
  }

  [data-scope='json-viewer'][data-part='branch-indicator'] {
    display: inline-block;
    line-height: var(--xh-leading-none);
    transition: rotate var(--xh-motion-duration-nudge) var(--xh-motion-ease-enter-strong);
  }

  [data-scope='json-viewer'][data-part='branch-indicator'][hidden] {
    display: none;
  }

  /* 没写内容就由皮肤画；作者往部件里塞了自己的图形，这条规则即不命中。
     尺寸读把手改接过的 --xh-icon-size：chevron 与盒同边长（见 branch-trigger 块） */
  [data-scope='json-viewer'][data-part='branch-indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
  }

  /* 收起时朝向行首、展开时转向下方，与逻辑书写方向一致：
     rtl 下 inline-start 在右侧，箭头因此要反着转 */
  [data-scope='json-viewer'][data-part='branch-indicator'][data-state='open'] {
    rotate: 90deg;
  }

  [dir='rtl'] [data-scope='json-viewer'][data-part='branch-indicator'] {
    rotate: 180deg;
  }

  [dir='rtl'] [data-scope='json-viewer'][data-part='branch-indicator'][data-state='open'] {
    rotate: 90deg;
  }

  /* 收起摘要不参与选中：框选整块 JSON 时不该把它一起复制走 */
  [data-scope='json-viewer'][data-part='preview'] {
    flex: none;
    color: var(--xh-json-viewer-preview-fg, var(--xh-fg-muted));
    font-size: var(--xh-json-viewer-preview-font-size, var(--xh-text-caption-size));
    user-select: none;
  }

  /* 层级缩进靠子层容器自己顶：分支物理嵌套着子层，每深一层就多缩一格，
     无需把层级号写进内联样式，也就不必在两个适配器里各写一遍 */
  [data-scope='json-viewer'][data-part='branch-content'] {
    display: flex;
    flex-direction: column;
    padding-inline-start: var(--xh-json-viewer-indent, var(--xh-_json-viewer-indent));
  }

  [data-scope='json-viewer'][data-part='branch-content'][hidden] {
    display: none;
  }

  /* —— 空态 —— */
  /* 一行也摊不出来时占位的那一格：与两档容器共用同一套边框与高度令牌，空与不空盒子不跳 */
  [data-scope='json-viewer'][data-part='empty'] {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--xh-json-viewer-empty-gap, var(--xh-space-2));
    padding-block: var(--xh-json-viewer-empty-py, var(--xh-space-6));
    padding-inline: var(--xh-json-viewer-empty-px, var(--xh-space-4));
    border: var(--xh-stroke-thin) solid var(--xh-json-viewer-border, var(--xh-border-default));
    border-radius: var(--xh-json-viewer-radius, var(--xh-shape-surface));
    background: var(--xh-json-viewer-bg, var(--xh-bg-surface));
    box-shadow: var(--xh-json-viewer-shadow, none);
    color: var(--xh-json-viewer-empty-fg, var(--xh-fg-muted));
    text-align: center;
  }

  [data-scope='json-viewer'][data-part='empty'][hidden] {
    display: none;
  }

  /*
   * 高对比档：分支行的按压面常态靠底色深一档表出，这一档里底色被统一换成 Canvas，
   * 按住那一下与静息塌成同一个样子；用系统高亮反色画回来，行里的键名、摘要与箭头跟着换成反色前景
   */
  @media (forced-colors: active) {
    [data-scope='json-viewer'][data-part='branch-control']:not([data-disabled]):is(:active, [data-pressed]) {
      background: Highlight;
      color: HighlightText;
    }

    [data-scope='json-viewer'][data-part='branch-control']:not([data-disabled]):is(:active, [data-pressed]) [data-scope='json-viewer'][data-part='branch-text'],
    [data-scope='json-viewer'][data-part='branch-control']:not([data-disabled]):is(:active, [data-pressed]) [data-scope='json-viewer'][data-part='branch-text']::after,
    [data-scope='json-viewer'][data-part='branch-control']:not([data-disabled]):is(:active, [data-pressed]) [data-scope='json-viewer'][data-part='preview'],
    [data-scope='json-viewer'][data-part='branch-control']:not([data-disabled]):is(:active, [data-pressed]) [data-scope='json-viewer'][data-part='branch-indicator'] {
      color: HighlightText;
    }
  }
}

/* styles/layout.css */
/* 定义 layout 样式。 */

/* 独立皮肤传递引入折叠把手的动作控件配方，full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='layout'] {
    --xh-layout-skin: 1;
  }

  /* 页面骨架排成三行两列：头与脚各横贯一整行，侧栏与内容并排占中间那一行。
     缺哪一段，对应的行/列就没有条目，宽高自动收成 0，不必为"少写一段"另立规则。

     侧栏两档宽度与头的高度声明在根上：各段自己读这些槽，换档只改这里。
     宽度槽用 -w 缩写，与同处的 --xh-layout-header-h 一致。
     头的高度之所以也归到根上：头吸顶时头这一行的轨道要按同一个值定高，两处必须同源。 */
  [data-scope='layout'][data-part='root'] {
    display: grid;
    grid-template-areas:
      'header header'
      'sider content'
      'footer footer';
    grid-template-columns: auto minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr) auto;
    background: var(--xh-layout-bg, var(--xh-bg-page));
    color: var(--xh-layout-fg, var(--xh-fg-default));
    --xh-_layout-sider-expanded-w: var(--xh-layout-sider-w, 15rem);
    --xh-_layout-sider-w: var(--xh-_layout-sider-expanded-w);
    --xh-_layout-sider-collapsed-w: var(--xh-layout-sider-collapsed-w, 4rem);
    --xh-_layout-header-h: var(--xh-layout-header-h, 3.5rem);
    /* 侧栏吸附时钉在哪条线上：缺省贴滚动容器上沿，头也吸顶时改成让开头的高度 */
    --xh-_layout-sider-offset: 0px;
  }

  /* —— 侧栏断点 —— */
  /* 写了断点档就先按窄屏排（折叠宽），视口宽到那一档再还原成展开宽。
     移动优先、四档只用 min-width：媒体查询不改选择器权重，同时命中好几档时由源码序决定谁生效。
     宽度写字面量：自定义属性在 @media 条件里不参与求值，令牌变量写在这里等于没写条件。
     换的只是宽度，折叠态不动——那条通道归 siderCollapsed。 */
  [data-scope='layout'][data-part='root'][data-sider-breakpoint] {
    --xh-_layout-sider-w: var(--xh-_layout-sider-collapsed-w);
  }

  @media (min-width: 640px) {
    [data-scope='layout'][data-part='root'][data-sider-breakpoint='sm'] {
      --xh-_layout-sider-w: var(--xh-_layout-sider-expanded-w);
    }
  }

  @media (min-width: 768px) {
    [data-scope='layout'][data-part='root'][data-sider-breakpoint='md'] {
      --xh-_layout-sider-w: var(--xh-_layout-sider-expanded-w);
    }
  }

  @media (min-width: 1024px) {
    [data-scope='layout'][data-part='root'][data-sider-breakpoint='lg'] {
      --xh-_layout-sider-w: var(--xh-_layout-sider-expanded-w);
    }
  }

  @media (min-width: 1280px) {
    [data-scope='layout'][data-part='root'][data-sider-breakpoint='xl'] {
      --xh-_layout-sider-w: var(--xh-_layout-sider-expanded-w);
    }
  }

  /* 侧栏挂到行尾：两列对调，内容在前 */
  [data-scope='layout'][data-part='root'][data-sider-placement='end'] {
    grid-template-areas:
      'header header'
      'content sider'
      'footer footer';
    grid-template-columns: minmax(0, 1fr) auto;
  }

  /* —— 各段 —— */
  [data-scope='layout'][data-part='header'] {
    display: flex;
    grid-area: header;
    align-items: center;
    gap: var(--xh-layout-header-gap, var(--xh-space-3));
    block-size: var(--xh-_layout-header-h);
    padding-inline: var(--xh-layout-header-px, var(--xh-space-4));
    background: var(--xh-layout-header-bg, var(--xh-bg-surface));
  }

  /* 宽度过渡在这里声明一次，展开与折叠两档、以及 props 直接写进内联的宽度，走的都是这一条。
     占位档的侧栏是淡底承载面：把手摆进来时由它下发 hover 200 → pressed 300；
     覆盖档换成 elevated 白底，那一档的规则把阶梯写回 100 → 200 */
  [data-scope='layout'][data-part='sider'] {
    --xh-action-host-bg-hover: var(--xh-bg-subtle-hover);
    --xh-action-host-bg-pressed: var(--xh-bg-subtle-active);

    grid-area: sider;
    inline-size: var(--xh-_layout-sider-w);
    overflow: hidden;
    padding: var(--xh-layout-sider-padding, var(--xh-space-3));
    background: var(--xh-layout-sider-bg, var(--xh-bg-subtle));
    transition: inline-size var(--xh-motion-duration-move) var(--xh-motion-ease-continuous);
  }

  /* 折起来时不换行：窄到放不下的那几个字直接被 overflow 裁掉，不会挤成一列竖排 */
  [data-scope='layout'][data-part='sider'][data-collapsed] {
    inline-size: var(--xh-_layout-sider-collapsed-w);
    white-space: nowrap;
  }

  [data-scope='layout'][data-part='content'] {
    grid-area: content;
    /* 内容列已是 minmax(0, 1fr)，这里再声明一次，宽表格与长串文本才撑不破列 */
    min-inline-size: 0;
    padding: var(--xh-layout-content-padding, var(--xh-space-4));
  }

  [data-scope='layout'][data-part='footer'] {
    grid-area: footer;
    padding: var(--xh-layout-footer-padding, var(--xh-space-3) var(--xh-space-4));
    background: var(--xh-layout-footer-bg, var(--xh-bg-surface));
    color: var(--xh-fg-muted);
    font-size: var(--xh-text-secondary-size);
  }

  /* —— 折叠把手 —— */
  /* 一枚小档文字按钮：盒型、悬停 / 按下面与按压缩放由 Action Control 的 text 档给（ghost 形态，sm 档：
     摆在顶栏等白底上按画布承载 hover 100 → pressed 200，摆进占位档侧栏时由侧栏下发 host 槽 200 → 300，
     覆盖档侧栏是 elevated 白底、仍是 100 → 200）；
     这里只把使用者槽映射到桥接槽（-gap / -px / -radius / -bg / -bg-hover / -bg-active / -fg 保留为第一参数） */
  [data-scope='layout'][data-part='sider-trigger'] {
    --xh-action-gap: var(--xh-layout-sider-trigger-gap, var(--xh-_action-profile-gap));
    --xh-action-padding-inline: var(--xh-layout-sider-trigger-px, var(--xh-_action-profile-padding-inline));
    --xh-action-radius: var(--xh-layout-sider-trigger-radius, var(--xh-_action-profile-radius));
    --xh-action-bg-rest: var(--xh-layout-sider-trigger-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-layout-sider-trigger-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-layout-sider-trigger-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-layout-sider-trigger-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-layout-sider-trigger-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-layout-sider-trigger-fg, var(--xh-_action-variant-fg-pressed));
  }

  /* —— 分隔线 —— */
  /* 后代选择器带上 data-scope：骨架里装着整页内容，光凭 data-part 会连里面别的组件同名段一起画上线 */
  [data-scope='layout'][data-part='root'][data-split] [data-scope='layout'][data-part='header'] {
    border-block-end: var(--xh-stroke-thin) solid var(--xh-layout-border, var(--xh-border-default));
  }

  [data-scope='layout'][data-part='root'][data-split] [data-scope='layout'][data-part='footer'] {
    border-block-start: var(--xh-stroke-thin) solid var(--xh-layout-border, var(--xh-border-default));
  }

  /* 侧栏只在挨着内容的那一边画线，另一边贴着骨架外沿，画了就是一条多出来的边框 */
  [data-scope='layout'][data-part='root'][data-split] [data-scope='layout'][data-part='sider'][data-placement='start'] {
    border-inline-end: var(--xh-stroke-thin) solid var(--xh-layout-border, var(--xh-border-default));
  }

  [data-scope='layout'][data-part='root'][data-split] [data-scope='layout'][data-part='sider'][data-placement='end'] {
    border-inline-start: var(--xh-stroke-thin) solid var(--xh-layout-border, var(--xh-border-default));
  }

  /* —— 固定定位 —— */
  /* 滚动容器的分工：滚动发生在骨架外面——root 的高度跟着内容长，页面（或作者套在外层的
     那个定高盒子）才是滚动容器；content 不改成滚动容器。
     两条理由：一是 content 自己滚的话头与侧栏本来就不会动，两个开关也就没有区别了；
     二是 sticky 的行程被自己的包含块框住，root 一旦定高，行里的轨道就不再跟着内容长，
     钉住的那一段滚过一屏后会被包含块拽走。
     由此还有一条：给 root 写 overflow（比如为了圆角裁剪）会让它自己变成一个永远滚不动的
     滚动容器，里面的 sticky 随之成为空操作——要固定就把 overflow 挪到 root 外面那层。 */

  /* 头这一行改成定高：下面那条让头跨满所有行，行 1 就没有条目撑着它了 */
  [data-scope='layout'][data-part='root'][data-header-fixed] {
    grid-template-rows: var(--xh-_layout-header-h) minmax(0, 1fr) auto;
  }

  /* 跨满所有行只为把包含块撑到整副骨架那么高：头若只占行 1，包含块与它自己一样高，
     sticky 的行程就是 0，钉住与不钉住看不出区别。
     起始缘对齐把它按回行 1 的位置，视觉上与不固定时一样；高度被作者改成 auto 时也不会被拉满整块区域。
     头的背景（--xh-layout-header-bg）要留实色，否则滚过去的正文会从头底下透出来。 */
  [data-scope='layout'][data-part='header'][data-fixed] {
    position: sticky;
    z-index: var(--xh-layout-header-layer, var(--xh-layer-sticky));
    grid-row: 1 / -1;
    align-self: start;
    inset-block-start: 0;
  }

  /* 头也吸顶时侧栏钉在头的下沿，两段不叠在一起 */
  [data-scope='layout'][data-part='root'][data-header-fixed][data-sider-fixed] {
    --xh-_layout-sider-offset: var(--xh-_layout-header-h);
  }

  /* 侧栏保持默认的拉伸对齐，只加一道高度上限：内容短时它照旧填满整列，内容长过一屏时它收成
     可视区那么高，短出来的那一段就是 sticky 的行程。
     上限量的是滚动容器可视区的高度，缺省按视口算；滚动容器不是视口时由作者把那个高度写进
     --xh-layout-scrollport-h。视口取 dvh：移动端地址栏收放会改变可视高度，dvh 跟着变；
     不认 dvh 的引擎由级联回落到前一条的 vh。
     侧栏自己的条目多到装不下时在内部滚，横轴仍归上面那条 overflow: hidden 裁，
     折叠态靠它把放不下的字裁掉；逻辑属性 overflow-block 尚无可用实现，写物理轴。 */
  [data-scope='layout'][data-part='sider'][data-fixed] {
    position: sticky;
    inset-block-start: var(--xh-_layout-sider-offset);
    max-block-size: calc(var(--xh-layout-scrollport-h, 100vh) - var(--xh-_layout-sider-offset));
    max-block-size: calc(var(--xh-layout-scrollport-h, 100dvh) - var(--xh-_layout-sider-offset));
    overflow-y: auto;
  }

  /* —— 侧栏覆盖档 —— */
  /* 侧栏移出画外、盖在内容之上：面板脱离网格，侧栏那一列于是收成零宽，内容占满整行。
     排在固定定位那一节之后：两处特指度相同，覆盖档要盖住 sticky 那一档。
     参照的是视口，与上面 sticky 那条同一个注意事项：整副骨架装进带 transform / filter 的祖先里时，
     固定定位的包含块会换成那个祖先，面板跟着一起滚。 */
  [data-scope='layout'][data-part='sider'][data-presentation='sheet'] {
    /* 位移方向的私有槽位：默认按行首 + LTR，行尾与 RTL 在下面翻符号。
       写成槽位而不是写死 ±100%：贴边用的是逻辑 inset，RTL 下行首落在物理右边，
       位移若写死物理方向就会出现「贴在右边、却从左边滑进来」 */
    --xh-_layout-sheet-shift: -100%;
    /* 这一档的底是 elevated 白底：交互阶梯按承载面走，把上面占位档下发的 200 → 300 写回
       白底的 hover 100 → pressed 200 */
    --xh-action-host-bg-hover: var(--xh-bg-subtle);
    --xh-action-host-bg-pressed: var(--xh-bg-subtle-hover);

    position: fixed;
    z-index: var(--xh-layout-sider-layer, var(--xh-layer-drawer));
    inset-block: 0;
    inset-inline-start: 0;
    inset-inline-end: auto;
    inline-size: var(--xh-_layout-sider-expanded-w);
    /* 面板贴死上下两条边，高度上限就是滚动容器可视区那么高——上面 sticky 那一档的
       「减去顶栏偏移」在这一档不作数：覆盖档从视口顶铺到底。
       不认 dvh 的引擎由级联回落到前一条的 vh */
    max-block-size: var(--xh-layout-scrollport-h, 100vh);
    max-block-size: var(--xh-layout-scrollport-h, 100dvh);
    /* 贴死视口的那一档，内衬与安全区取大的一头：刘海、圆角与底部横条压住的那一段由系统给出。
       桌面上 env() 恒为 0，取值与内衬槽完全一致。安全区只有物理方向的四个名字，
       行内轴上两侧同取较宽的那一段，RTL 下不会翻错边 */
    padding-block-start: max(var(--xh-layout-sider-padding, var(--xh-space-3)), env(safe-area-inset-top));
    padding-block-end: max(var(--xh-layout-sider-padding, var(--xh-space-3)), env(safe-area-inset-bottom));
    padding-inline: max(
      var(--xh-layout-sider-padding, var(--xh-space-3)),
      env(safe-area-inset-left),
      env(safe-area-inset-right)
    );
    /* 盖在内容之上、带遮罩的一面走 sheet 三件套（--xh-material-elevated-bg / -border / -shadow），
       贴着内容那一侧描一条边；占位档的侧栏不画投影 */
    border-inline-end: var(--xh-stroke-thin) solid var(--xh-layout-border, var(--xh-material-elevated-border));
    background: var(--xh-layout-sider-bg, var(--xh-material-elevated-bg));
    box-shadow: var(--xh-layout-sider-shadow, var(--xh-material-elevated-shadow));
    translate: 0 0;
    visibility: visible;
    /* 条目多到装不下时在面板内部滚：这一档的高度就是视口那么高。
       overscroll 不在这里写 contain：这一面与占位档共用同一个部件，scroll-surface-registry 把侧栏整体登记为
       页内结构容器（overscroll=false），门禁按整个部件核，不按档分 */
    overflow-y: auto;
    /* 推出来与收进去是同一段行程，视口尺度的位移走 slide 档。
       visibility 与它同拍：收起那一路等位移播完才真正藏起来，展开那一路立刻露出来 */
    transition:
      translate var(--xh-motion-duration-slide) var(--xh-motion-ease-slide),
      visibility var(--xh-motion-duration-slide) var(--xh-motion-ease-slide);
  }

  /* 挂在行尾：贴另一条边，位移随之反向，描边也换到贴着内容的那一侧 */
  [data-scope='layout'][data-part='sider'][data-presentation='sheet'][data-placement='end'] {
    --xh-_layout-sheet-shift: 100%;

    inset-inline-start: auto;
    inset-inline-end: 0;
    border-inline-end: 0;
    border-inline-start: var(--xh-stroke-thin) solid var(--xh-layout-border, var(--xh-material-elevated-border));
  }

  [data-scope='layout'][data-part='sider'][data-presentation='sheet']:dir(rtl) {
    --xh-_layout-sheet-shift: 100%;
  }

  [data-scope='layout'][data-part='sider'][data-presentation='sheet'][data-placement='end']:dir(rtl) {
    --xh-_layout-sheet-shift: -100%;
  }

  /* 收起：推出画外并让出无障碍树与 Tab 序列。位移量按面板自身宽度的百分比算，
     宽度换成任何一档都正好推到画外 */
  [data-scope='layout'][data-part='sider'][data-presentation='sheet'][data-collapsed] {
    translate: var(--xh-_layout-sheet-shift) 0;
    visibility: hidden;
  }

  /* 覆盖档的遮罩：与面板同一个层号，谁盖谁看文档序——遮罩写在侧栏之前。
     占位档下连接层给它打 hidden，这里不必再管 */
  [data-scope='layout'][data-part='sider-backdrop'] {
    position: fixed;
    z-index: var(--xh-layout-sider-backdrop-layer, var(--xh-layer-drawer));
    inset: 0;
    background: var(--xh-layout-sider-backdrop-bg, var(--xh-bg-overlay));
    opacity: 1;
    transition: opacity var(--xh-motion-duration-enter) var(--xh-motion-ease-enter);
  }

  /* 收起态：淡出并让开指针，底下的内容照常点得到 */
  [data-scope='layout'][data-part='sider-backdrop'][data-collapsed] {
    opacity: 0;
    pointer-events: none;
  }

  /* 纸上没有覆盖这回事：遮罩印出来就是盖住正文的一片灰 */
  @media print {
    [data-scope='layout'][data-part='sider-backdrop'] {
      display: none;
    }
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='layout'][data-part='root'][hidden],
  [data-scope='layout'][data-part='header'][hidden],
  [data-scope='layout'][data-part='sider-trigger'][hidden] {
    display: none;
  }
}

/* styles/list.css */
/* 定义 list 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='list'] {
    --xh-list-skin: 1;
  }

  [data-scope='list'][data-part='root'] {
    /* 一个尺寸档只换这几个私有槽，条目与两行文字都从根上继承它们，
       换档不必给每个部件各写一条选择器 */
    --xh-_list-item-py: var(--xh-list-item-py-md);
    --xh-_list-item-px: var(--xh-list-item-px-md);
    --xh-_list-item-gap: var(--xh-space-3);
    --xh-_list-title-size: var(--xh-control-font-md);
    --xh-_list-description-size: var(--xh-control-caption-md);
    /* 条目悬停换到的面：坐在白底上是 100，淡底档的根把它抬到 200（按承载面的阶梯） */
    --xh-_list-item-bg-hover: var(--xh-bg-subtle);

    display: flex;
    flex-direction: column;
    /* 根可能写成 ul/ol，UA 的项目符号与左缩进在这里清掉：换哪个标签都排成同一个样子 */
    margin: 0;
    padding: 0;
    list-style: none;
    color: var(--xh-list-fg, var(--xh-fg-default));
  }

  /* 上面声明了 display，会盖掉 UA 的 [hidden] 规则，收起态要在这里接回来 */
  [data-scope='list'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 尺寸 —— */
  [data-scope='list'][data-part='root'][data-size='sm'] {
    --xh-_list-item-py: var(--xh-list-item-py-sm);
    --xh-_list-item-px: var(--xh-list-item-px-sm);
    --xh-_list-item-gap: var(--xh-space-2);
    --xh-_list-title-size: var(--xh-control-font-sm);
    --xh-_list-description-size: var(--xh-control-caption-sm);
  }

  [data-scope='list'][data-part='root'][data-size='lg'] {
    --xh-_list-item-py: var(--xh-list-item-py-lg);
    --xh-_list-item-px: var(--xh-list-item-px-lg);
    --xh-_list-item-gap: var(--xh-space-4);
    --xh-_list-title-size: var(--xh-control-font-lg);
    --xh-_list-description-size: var(--xh-control-caption-lg);
  }

  /* —— 形态：ghost 即基础规则，不画壳 —— */
  [data-scope='list'][data-part='root'][data-variant='outline'] {
    border: var(--xh-stroke-thin) solid var(--xh-list-border, var(--xh-border-default));
    border-radius: var(--xh-list-radius, var(--xh-shape-surface));
    background: var(--xh-list-bg, var(--xh-bg-surface));
    /* 首尾条目的悬停底色要被圆角裁住 */
    overflow: hidden;
  }

  /* 淡底档：底换成 subtle，描边留一圈透明边位，与 outline 同一几何；
     条目坐在淡底上，悬停面抬一档 */
  [data-scope='list'][data-part='root'][data-variant='subtle'] {
    --xh-_list-item-bg-hover: var(--xh-bg-subtle-hover);

    border: var(--xh-stroke-thin) solid transparent;
    border-radius: var(--xh-list-radius, var(--xh-shape-surface));
    background: var(--xh-list-bg, var(--xh-bg-subtle));
    overflow: hidden;
  }

  /* —— 条目 —— */
  [data-scope='list'][data-part='item'] {
    display: flex;
    align-items: center;
    gap: var(--xh-list-item-gap, var(--xh-_list-item-gap));
    padding-block: var(--xh-list-item-py, var(--xh-_list-item-py));
    padding-inline: var(--xh-list-item-px, var(--xh-_list-item-px));
  }

  /* 分隔线画在后一条的上边，条与条之间才只有一条；第一条没有上邻居。
     只认自己的直接子条目，套在条目里的另一份列表由它自己的根管 */
  [data-scope='list'][data-part='root'][data-split]
    > [data-scope='list'][data-part='item']
    + [data-scope='list'][data-part='item'] {
    border-block-start: var(--xh-stroke-thin) solid var(--xh-list-divider, var(--xh-border-subtle));
  }

  [data-scope='list'][data-part='root'][data-hoverable] > [data-scope='list'][data-part='item'] {
    transition: background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 悬停换底色：只在能用指针的设备上生效，触摸端不留一个按不掉的悬停态 */
  @media (hover: hover) {
    [data-scope='list'][data-part='root'][data-hoverable] > [data-scope='list'][data-part='item']:hover {
      background: var(--xh-list-item-bg-hover, var(--xh-_list-item-bg-hover));
    }
  }

  /* —— 条目内的四个位 —— */
  /* 媒体位不参与伸缩，宽度收到内容 */
  [data-scope='list'][data-part='item-media'] {
    display: flex;
    flex: none;
    align-items: center;
    justify-content: center;
  }

  [data-scope='list'][data-part='item-content'] {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    gap: var(--xh-list-content-gap, var(--xh-space-1));
    /* flex 项默认不肯收到内容以下，这行让长文本能被压窄 */
    min-inline-size: 0;
  }

  [data-scope='list'][data-part='item-title'] {
    color: var(--xh-list-title-fg, var(--xh-fg-default));
    font-size: var(--xh-list-title-font-size, var(--xh-_list-title-size));
    font-weight: var(--xh-list-title-font-weight, var(--xh-font-weight-medium));
    line-height: var(--xh-leading-tight);
  }

  [data-scope='list'][data-part='item-description'] {
    color: var(--xh-list-description-fg, var(--xh-fg-muted));
    font-size: var(--xh-list-description-font-size, var(--xh-_list-description-size));
    line-height: var(--xh-leading-normal);
  }

  /* 操作位推到条目末尾，宽度收到内容 */
  [data-scope='list'][data-part='item-action'] {
    display: flex;
    flex: none;
    align-items: center;
    gap: var(--xh-list-action-gap, var(--xh-space-2));
    margin-inline-start: auto;
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='list'][data-part='item'][hidden],
  [data-scope='list'][data-part='item-media'][hidden],
  [data-scope='list'][data-part='item-content'][hidden],
  [data-scope='list'][data-part='item-action'][hidden] {
    display: none;
  }
}

/* styles/log.css */
/* 定义 log 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */
/* 独立皮肤同时传递引入回底钮的动作控件配方；full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='log'] {
    --xh-log-skin: 1;
  }

  /* 行高是本组件的定尺基准：视口按行数定高、每行排版，都从这一个槽位来。
     它的兜底值须与连接层内联高度里用的那份逐字一致，否则 rows 算出来的高度对不上行。 */
  [data-scope='log'][data-part='root'] {
    --xh-_log-line-h: var(--xh-log-line-height, 1.25rem);

    /* 尺寸缺省档：不写 data-size 时的取值。三档只改这两个私有槽，
       公开槽留在读处当首选，作者在祖先上设的覆盖才赢得过档位声明。
       行高不在档内：视口按 rows 定高读的是同一个基准，三档同值才对得上整数行 */
    --xh-_log-font-size: var(--xh-text-secondary-size);
    --xh-_log-content-px: var(--xh-space-3);

    /* 一张静态内容面：--xh-border-default 描边 + surface 底 + 无影（描边与淡底互斥），
       与 code-view / diff-view / json-viewer 同走 solid */
    position: relative;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border: var(--xh-stroke-thin) solid var(--xh-log-border, var(--xh-border-default));
    border-radius: var(--xh-log-radius, var(--xh-shape-surface));
    background: var(--xh-log-bg, var(--xh-bg-surface));
    box-shadow: var(--xh-log-shadow, none);
    color: var(--xh-log-fg, var(--xh-fg-default));
  }

  /* 上面声明的 display 会盖掉 UA 的 [hidden]{display:none}，这里补回 */
  [data-scope='log'][data-part='root'][hidden] {
    display: none;
  }

  /* 滚动容器，粘底读的是它的 scrollTop / clientHeight / scrollHeight。
     flex-basis 取 auto，连接层写的按行数高度才算数，同时外层给了高度时还能撑满；
     min-block-size: 0 让它在弹性父级里能被压缩从而真的溢出；
     两个轴都 auto：长行不折，横向也要能滚；
     overscroll-behavior: contain 阻止滚动量传给页面。 */
  [data-scope='log'][data-part='viewport'] {
    flex: 1 1 auto;
    min-block-size: 0;
    block-size: calc(var(--xh-_log-line-h) * var(--xh-log-rows, 16));
    overflow: auto;
    overscroll-behavior: contain;
  }

  /* 还在用原生滚动条的视口留一条空道，滚动条出现与消失时不推动文字。
     带 data-xh-scrollbar 的容器已经把原生条藏成零宽，这条空道对它没有布局作用，排除掉 */
  [data-scope='log'][data-part='viewport']:not([data-xh-scrollbar]) {
    scrollbar-gutter: stable;
  }

  /* 取行期间指针给出忙的反馈 */
  [data-scope='log'][data-part='root'][data-loading] [data-scope='log'][data-part='viewport'] {
    cursor: progress;
  }

  /* 等宽排版落在包裹层上，各行继承；行与行之间不留空隙，视口高度才等于整数行 */
  [data-scope='log'][data-part='content'] {
    display: block;
    padding-inline: var(--xh-log-content-px, var(--xh-_log-content-px));
    font-family: var(--xh-log-font, var(--xh-font-family-mono));
    font-size: var(--xh-log-font-size, var(--xh-_log-font-size));
  }

  [data-scope='log'][data-part='content'][hidden] {
    display: none;
  }

  /* 一行不折行，超出的部分由视口横向滚动；行高与定高基准同源 */
  [data-scope='log'][data-part='line'] {
    line-height: var(--xh-_log-line-h);
    white-space: pre;
    tab-size: var(--xh-log-tab-size, 4);
  }

  /* 级别只染行文颜色，不动排版：一行的高度是定高基准，四档必须等高。
     没写级别的行走内容层的前景色 */
  [data-scope='log'][data-part='line'][data-level='debug'] {
    color: var(--xh-log-level-debug-fg, var(--xh-fg-subtle));
  }

  [data-scope='log'][data-part='line'][data-level='info'] {
    color: var(--xh-log-level-info-fg, var(--xh-fg-default));
  }

  [data-scope='log'][data-part='line'][data-level='warn'] {
    color: var(--xh-log-level-warn-fg, var(--xh-fg-warning));
  }

  [data-scope='log'][data-part='line'][data-level='error'] {
    color: var(--xh-log-level-error-fg, var(--xh-fg-danger));
  }

  /* 回到底部：浮在视口右下角，收起时不卸载只隐藏。盒型、悬停 / 按下面与缩放由 Action Control 的
     floating 档给（circle 正方盒、ghost 形态：白底承载 hover 100 → pressed 200）；材质随角落浮钮族走
     frosted 四件套（底 + 边 + 影 + 磨砂），这里只把使用者槽映射到桥接槽：
     字形按 xs 档取 --xh-_action-profile-glyph-size（16px），与 back-top 同一把尺 */
  [data-scope='log'][data-part='scroll-to-end-trigger'] {
    --xh-_log-scroll-to-end-trigger-shadow: var(--xh-log-scroll-to-end-trigger-shadow, var(--xh-material-frosted-shadow));
    --xh-action-visual-size: var(--xh-log-scroll-to-end-trigger-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-log-scroll-to-end-trigger-radius, var(--xh-shape-circle));
    --xh-action-bg-rest: var(--xh-log-scroll-to-end-trigger-bg, var(--xh-material-frosted-bg));
    --xh-action-bg-hover: var(--xh-log-scroll-to-end-trigger-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-border-rest: var(--xh-log-scroll-to-end-trigger-border, var(--xh-material-frosted-border));
    --xh-action-border-hover: var(--xh-log-scroll-to-end-trigger-border, var(--xh-material-frosted-border));
    --xh-action-border-pressed: var(--xh-log-scroll-to-end-trigger-border, var(--xh-material-frosted-border));
    --xh-action-border-focus-visible: var(--xh-log-scroll-to-end-trigger-border, var(--xh-material-frosted-border));
    --xh-action-shadow-rest: var(--xh-_log-scroll-to-end-trigger-shadow);
    --xh-action-shadow-hover: var(--xh-_log-scroll-to-end-trigger-shadow);
    --xh-action-shadow-pressed: var(--xh-_log-scroll-to-end-trigger-shadow);
    --xh-action-fg-rest: var(--xh-log-scroll-to-end-trigger-fg, var(--xh-material-frosted-fg));
    --xh-icon-size: var(--xh-log-icon-size, var(--xh-_action-profile-glyph-size));

    position: absolute;
    inset-block-end: var(--xh-log-scroll-to-end-trigger-inset, var(--xh-space-3));
    inset-inline-end: var(--xh-log-scroll-to-end-trigger-inset, var(--xh-space-3));
    -webkit-backdrop-filter: var(--xh-material-frosted-backdrop);
    backdrop-filter: var(--xh-material-frosted-backdrop);
  }

  /* 连接层收起按钮时写 hidden 属性，上面的 display 会盖掉 UA 规则，这里补回 */
  [data-scope='log'][data-part='scroll-to-end-trigger'][hidden] {
    display: none;
  }

  /* 收起不卸载，冒出来时靠这条进场动画；不写 display，可见性归上面那条 [hidden] 管 */
  [data-scope='log'][data-part='scroll-to-end-trigger'][data-state='visible'] {
    animation: xh-pop-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 没写内容就由皮肤画一枚向下的字形；作者往按钮里塞了自己的图形，这条规则即不命中。
     不画的话这颗按钮就是一枚空盒，看不出它是干什么的——名字只在 aria-label 上 */
  [data-scope='log'][data-part='scroll-to-end-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-sm));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-sm));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
  }

  /* 尺寸档只改行文字号与内衬 */
  [data-scope='log'][data-part='root'][data-size='sm'] {
    --xh-_log-font-size: var(--xh-text-caption-size);
    --xh-_log-content-px: var(--xh-space-2);
  }

  [data-scope='log'][data-part='root'][data-size='md'] {
    --xh-_log-font-size: var(--xh-text-secondary-size);
    --xh-_log-content-px: var(--xh-space-3);
  }

  [data-scope='log'][data-part='root'][data-size='lg'] {
    --xh-_log-font-size: var(--xh-text-body-size);
    --xh-_log-content-px: var(--xh-space-4);
  }

  /* 视觉隐藏但仍参与播报：用 clip-path 裁到不可见，不能用 display:none 或 visibility:hidden；
     white-space: nowrap 防止 1px 宽把文本挤成竖排。 */
  [data-scope='log'][data-part='live-region'] {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }

  @media print {
    /* 打印：回到底部这颗钮只有在能滚的地方才成立，落到纸上是一颗按不动的按钮。 */
    [data-scope='log'][data-part='scroll-to-end-trigger'] {
      display: none;
    }
  }
}

/* styles/markdown-stream.css */
/* 定义 markdown stream 样式。 */

@layer xihan.motion {
  /* 光标的两段动效都定义在本文件里。皮肤可以按需单独引入，
     引用别处文件里的动画名时那份文件不一定在场，动画会静默地整个不跑 */
  @keyframes xh-markdown-stream-caret {
    50% {
      opacity: 0;
    }
  }

  @keyframes xh-markdown-stream-caret-in {
    from {
      opacity: 0;
    }
  }
}

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='markdown-stream'] {
    --xh-markdown-stream-skin: 1;
  }

  [data-scope='markdown-stream'][data-part='root'] {
    /* 尺寸缺省档：不写 data-size 时的取值。三档都只写这两个私有槽，
       公开槽留在读处当首选，作者在祖先上设的覆盖才赢得过档位声明 */
    --xh-_markdown-stream-font-size: var(--xh-text-body-size);
    --xh-_markdown-stream-gap: var(--xh-space-3);

    color: var(--xh-markdown-stream-fg, var(--xh-fg-default));
    font-size: var(--xh-markdown-stream-font-size, var(--xh-_markdown-stream-font-size));
    line-height: var(--xh-markdown-stream-leading, var(--xh-text-prose-leading));
  }

  /* 块之间的距离由这一层给，块内部的排版归作者的正文样式 */
  [data-scope='markdown-stream'][data-part='content'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-markdown-stream-gap, var(--xh-_markdown-stream-gap));
  }

  [data-scope='markdown-stream'][data-part='content'][hidden] {
    display: none;
  }

  [data-scope='markdown-stream'][data-part='block'] {
    display: block;
    min-inline-size: 0;
    /* 块里铺的是渲染好的 Markdown，宽表格与不断行的长串由内容自己带；
       行内一轴可横滚，这类块自己滚，不把整篇正文顶宽 */
    overflow-x: auto;
  }

  [data-scope='markdown-stream'][data-part='block'][hidden] {
    display: none;
  }

  /* 代码块与公式块没人接管时铺的是原文，保住换行与缩进 */
  [data-scope='markdown-stream'][data-part='block'][data-kind='code'],
  [data-scope='markdown-stream'][data-part='block'][data-kind='math'] {
    font-family: var(--xh-markdown-stream-mono, var(--xh-font-family-mono));
    white-space: pre-wrap;
    overflow-wrap: anywhere;
  }

  /* 流式光标落在带 data-caret 的那一格上：正文在长的时候是生长块的末尾，
     一个字都还没到的时候是外壳，所以「请求已经发出去」这件事第一帧就看得见。
     它落在块的最后一个顶层元素之后，不是最后一句话的末尾——要贴进段落里就得往已消毒的
     html 注入节点，那会打穿「原生 HTML 一律不透传」这条约束 */
  [data-scope='markdown-stream'][data-part='root'][data-caret]::after,
  [data-scope='markdown-stream'][data-part='block'][data-caret]::after {
    display: inline-block;
    background: var(--xh-markdown-stream-caret-bg, var(--xh-fg-default));
    border-radius: var(--xh-markdown-stream-caret-radius, var(--xh-shape-inset));
    content: '';
    inline-size: var(--xh-markdown-stream-caret-w, var(--xh-stroke-thick));
    block-size: var(--xh-markdown-stream-caret-h, 1.05em);
    margin-inline-start: var(--xh-markdown-stream-caret-gap, 0.1em);
    vertical-align: text-bottom;
    translate: 0 var(--xh-markdown-stream-caret-shift, -0.5px);
  }

  /* 正文在长的时候光标只淡入一次然后停在实心：旁边的字每帧都在变，再闪一下只是噪声 */
  [data-scope='markdown-stream'][data-part='block'][data-caret]::after {
    animation: xh-markdown-stream-caret-in var(--xh-markdown-stream-caret-enter-duration, var(--xh-motion-duration-enter)) var(--xh-motion-ease-enter-strong) both;
  }

  /* 还没出字的那一段页面上只有这一竖，让它闪着，等的人才分得清是在等还是卡住了 */
  [data-scope='markdown-stream'][data-part='root'][data-caret]::after {
    animation: xh-markdown-stream-caret var(--xh-markdown-stream-caret-duration, var(--xh-caret-duration)) steps(1, end) infinite;
  }

  /* 减少动效：等待时的光标停在实心不闪，「还在等」这件事仍然看得出来。
     两组规则是同一件事的两个触发条件：系统偏好与作者打的 data-motion */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='markdown-stream'][data-part='root'][data-caret]::after {
      animation: none;
    }
  }

  :where([data-motion='reduce']) [data-scope='markdown-stream'][data-part='root'][data-caret]::after {
    animation: none;
  }

  /* 尺寸档只改正文字号与块间距 */
  [data-scope='markdown-stream'][data-part='root'][data-size='sm'] {
    --xh-_markdown-stream-font-size: var(--xh-control-font-sm);
    --xh-_markdown-stream-gap: var(--xh-space-2);
  }

  [data-scope='markdown-stream'][data-part='root'][data-size='md'] {
    --xh-_markdown-stream-font-size: var(--xh-control-font-md);
    --xh-_markdown-stream-gap: var(--xh-space-3);
  }

  [data-scope='markdown-stream'][data-part='root'][data-size='lg'] {
    --xh-_markdown-stream-font-size: var(--xh-control-font-lg);
    --xh-_markdown-stream-gap: var(--xh-space-4);
  }

  /* 视觉隐藏的原子播报区：不能 display:none，那样读屏就取不到它了 */
  [data-scope='markdown-stream'][data-part='live-region'] {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    border: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  @media print {
    /* 打印：动画会被定格在任意一帧——转了一半的圈、扫到一半的微光。这里换成静止的表达，
       取值与减弱动效那一档相同。两档各写一块、不并进一条媒体查询列表：减弱动效另有一份
       :where([data-motion='reduce']) 的钩子版本与它成对，打印没有对应的钩子可配，
       并成一条之后这层配对关系在文本上就断了。 */
    [data-scope='markdown-stream'][data-part='root'][data-caret]::after {
      animation: none;
    }
  }
}

/* styles/marquee.css */
/* 定义 marquee 样式。 */

@layer xihan.motion {
  /*
   * 横轴一条、纵轴一条。四个方向乘两种铺法共八组起止点，若不外提就要写八份几乎一样的关键帧。
   * 关键帧里的自定义属性取元素上的计算值，一圈跑下来它不变，所以两条就够。
   */
  @keyframes xh-marquee-x {
    from {
      transform: translateX(var(--xh-_marquee-from));
    }

    to {
      transform: translateX(var(--xh-_marquee-to));
    }
  }

  @keyframes xh-marquee-y {
    from {
      transform: translateY(var(--xh-_marquee-from));
    }

    to {
      transform: translateY(var(--xh-_marquee-to));
    }
  }
}

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='marquee'] {
    --xh-marquee-skin: 1;
  }

  /*
   * 窗口：只露出轨道的一段。
   *
   * 方向、轴与铺法全部换成根上的私有槽，轨道与每一份内容各自只有一条规则去取值。
   * 这样写不只是为了短：轨道那条选择器因此能写成 [data-scope][data-part] 的复合式，
   * 而不是从根往下够的后代式——marquee 里嵌一个同样有 content 部件的组件时，
   * 后代式会一路匹配到别人家的节点上去。
   *
   * 一圈的时长 = 一份内容的长度 ÷ 每秒像素数。--xh-_marquee-span 是一份内容在滚动轴上的长度，
   * 单位像素、写成纯数字。CSS 读不到布局尺寸，这里给的是缺省值；内容明显长于或短于它时，
   * 由使用者改写 --xh-marquee-span 对齐真实长度，速度才逐字等于每秒那么多像素。
   */
  [data-scope='marquee'][data-part='root'] {
    --xh-_marquee-span: var(--xh-marquee-span, 600);
    --xh-_marquee-speed: var(--xh-marquee-speed, 60);

    /* 铺一份时一圈走两倍自身长度：从窗口一侧整段进来，再整段出到另一侧 */
    --xh-_marquee-duration: calc(2 * var(--xh-_marquee-span) / var(--xh-_marquee-speed) * 1s);
    --xh-_marquee-play: running;
    --xh-_marquee-flow: row;
    --xh-_marquee-name: xh-marquee-x;
    --xh-_marquee-track-inline: max-content;
    --xh-_marquee-track-block: auto;

    /* 轨道自身至少铺满窗口，起点那一跳才真的落在窗口外面 */
    --xh-_marquee-fill-inline: 100%;
    --xh-_marquee-fill-block: auto;
    --xh-_marquee-copy-inline: auto;
    --xh-_marquee-copy-block: auto;
    --xh-_marquee-gap-inline: var(--xh-marquee-gap, var(--xh-space-6));
    --xh-_marquee-gap-block: 0;
    --xh-_marquee-from: 100%;
    --xh-_marquee-to: -100%;

    display: flex;
    overflow: hidden;
    max-inline-size: 100%;
  }

  /* 声明了 display 就盖掉了 UA 的 [hidden]{display:none}，补这条兜住收起态 */
  [data-scope='marquee'][data-part='root'][hidden] {
    display: none;
  }

  /* 竖着滚要有一个定高的窗口，否则内容自己把窗口撑到一样高，一格都走不动 */
  [data-scope='marquee'][data-part='root'][data-orientation='vertical'] {
    --xh-_marquee-flow: column;
    --xh-_marquee-name: xh-marquee-y;
    --xh-_marquee-track-inline: auto;
    --xh-_marquee-track-block: max-content;
    --xh-_marquee-fill-inline: auto;
    --xh-_marquee-fill-block: 100%;
    --xh-_marquee-gap-inline: 0;
    --xh-_marquee-gap-block: var(--xh-marquee-gap, var(--xh-space-6));

    block-size: var(--xh-marquee-block-size, 10rem);
  }

  /* 往右、往下是同一条轨迹倒过来走 */
  [data-scope='marquee'][data-part='root'][data-direction='right'],
  [data-scope='marquee'][data-part='root'][data-direction='down'] {
    --xh-_marquee-from: -100%;
    --xh-_marquee-to: 100%;
  }

  /*
   * 铺两份：一圈只走一份的长度，走完那一刻第二份正好压在起点上，看不出接缝。
   * 这条排在竖轴那条之后：两者同权，铺两份时轨道自己不必铺满窗口，改由每一份各自铺满。
   */
  [data-scope='marquee'][data-part='root'][data-auto-fill] {
    --xh-_marquee-duration: calc(var(--xh-_marquee-span) / var(--xh-_marquee-speed) * 1s);
    --xh-_marquee-fill-inline: auto;
    --xh-_marquee-fill-block: auto;
  }

  /* 内容短于窗口时每份自己先铺满一整窗，两份接起来才不会在接缝处露出空白 */
  [data-scope='marquee'][data-part='root'][data-auto-fill][data-orientation='horizontal'] {
    --xh-_marquee-copy-inline: 100%;
  }

  [data-scope='marquee'][data-part='root'][data-auto-fill][data-orientation='vertical'] {
    --xh-_marquee-copy-block: 100%;
  }

  /* 起止点逐档写全：铺法与方向同权，交叉的四种情形各写一条才不看书写顺序 */
  [data-scope='marquee'][data-part='root'][data-auto-fill][data-direction='left'],
  [data-scope='marquee'][data-part='root'][data-auto-fill][data-direction='up'] {
    --xh-_marquee-from: 0%;
    --xh-_marquee-to: -50%;
  }

  [data-scope='marquee'][data-part='root'][data-auto-fill][data-direction='right'],
  [data-scope='marquee'][data-part='root'][data-auto-fill][data-direction='down'] {
    --xh-_marquee-from: -50%;
    --xh-_marquee-to: 0%;
  }

  /* 悬停暂停：只在能用指针的设备上生效，触摸端不留一个按不掉的悬停态 */
  @media (hover: hover) {
    [data-scope='marquee'][data-part='root'][data-pause-on-hover]:hover {
      --xh-_marquee-play: paused;
    }
  }

  /* 键盘用户没有悬停：焦点落进窗口时同样停住，否则轨道里的链接刚聚焦就被带走了 */
  [data-scope='marquee'][data-part='root'][data-pause-on-hover]:focus-within {
    --xh-_marquee-play: paused;
  }

  /* 受控暂停：作者说了停就停，排在悬停两条之后，指针离开也不会把它带回去走 */
  [data-scope='marquee'][data-part='root'][data-paused] {
    --xh-_marquee-play: paused;
  }

  /* 轨道：走的是这一层，一圈走完立刻回到起点接着走 */
  [data-scope='marquee'][data-part='content'] {
    display: flex;
    flex: none;
    flex-direction: var(--xh-_marquee-flow);
    inline-size: var(--xh-_marquee-track-inline);
    min-inline-size: var(--xh-_marquee-fill-inline);
    block-size: var(--xh-_marquee-track-block);
    min-block-size: var(--xh-_marquee-fill-block);
    animation-name: var(--xh-_marquee-name);
    animation-duration: var(--xh-_marquee-duration);
    animation-timing-function: var(--xh-motion-ease-loop);
    animation-iteration-count: infinite;
    animation-play-state: var(--xh-_marquee-play);
  }

  /*
   * 一份内容。份与份之间的空白做成每份自己的收尾内边距，而不是轨道上的 gap：
   * gap 只加在中间那一道，两份就不等长了，而接缝对不对得上看的正是"走完的距离等于一份的长度"。
   */
  [data-scope='marquee'][data-part='content'] > [data-xh-copy] {
    display: flex;
    flex: none;
    flex-direction: var(--xh-_marquee-flow);
    align-items: center;
    min-inline-size: var(--xh-_marquee-copy-inline);
    min-block-size: var(--xh-_marquee-copy-block);
    padding-inline-end: var(--xh-_marquee-gap-inline);
    padding-block-end: var(--xh-_marquee-gap-block);
  }

  /*
   * 减少动效：轨道停在起点不再走。一段自己动起来、不停到底的横移正是最容易引发不适的那一类，
   * 这里不能只把速度压到很慢——慢速横移仍然是横移。
   * 停下后窗口外那段就够不着了，故窗口同时改成可滚，内容仍然读得全。
   * 两组规则是同一件事的两个触发条件：系统偏好与作者打的 data-motion。
   */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='marquee'][data-part='content'] {
      animation: none;
    }

    [data-scope='marquee'][data-part='root'] {
      overflow: auto;
    }
  }

  :where([data-motion='reduce']) [data-scope='marquee'][data-part='content'] {
    animation: none;
  }

  :where([data-motion='reduce']) [data-scope='marquee'][data-part='root'] {
    overflow: auto;
  }

  @media print {
    /* 打印：动画会被定格在任意一帧——转了一半的圈、扫到一半的微光。这里换成静止的表达，
       取值与减弱动效那一档相同。两档各写一块、不并进一条媒体查询列表：减弱动效另有一份
       :where([data-motion='reduce']) 的钩子版本与它成对，打印没有对应的钩子可配，
       并成一条之后这层配对关系在文本上就断了。 */
    [data-scope='marquee'][data-part='content'] {
      animation: none;
    }

    [data-scope='marquee'][data-part='root'] {
      overflow: auto;
    }
  }
}

/* styles/masonry.css */
/* 定义 masonry 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='masonry'] {
    --xh-masonry-skin: 1;
  }

  [data-scope='masonry'][data-part='root'] {
    display: flex;
    /* 各列按自己的内容收高，不被最高的那列拉平——列不等高正是瀑布流的样子 */
    align-items: flex-start;
    gap: var(--xh-_masonry-gap);

    /* 列间距与列内的项间距共用这一份取值，声明在根上、由列继承下去；
       不写 gap 档位就不留间距。使用者槽位排在档位之前，写死一个值即盖过所有档 */
    --xh-_masonry-gap: var(--xh-masonry-gap, var(--xh-space-0));
  }

  /* 声明了 display 就盖掉了 UA 的 [hidden] 规则，这里还回去 */
  [data-scope='masonry'][data-part='root'][hidden] {
    display: none;
  }

  [data-scope='masonry'][data-part='column'] {
    display: flex;
    flex-direction: column;
    /* 各列等宽；下限写 0 而不是 auto，一段长内容才不会把自己那列撑宽 */
    flex: 1 1 0;
    min-inline-size: 0;
    gap: var(--xh-_masonry-gap);
  }

  /* 当前档位用不上的那几列由适配器收起；这条兜住作者自己写 hidden 的情形 */
  [data-scope='masonry'][data-part='column'][hidden] {
    display: none;
  }

  /* 项不发话，高度由内容定；只兜住一件事——不被列的弹性压缩，压缩了量到的高度就不是它真实的高度 */
  [data-scope='masonry'][data-part='item'] {
    flex: none;
  }

  /* —— 间距档位 —— */
  /* 每一档指向一个间距令牌，列之间与列内项之间吃同一份间距 */
  [data-scope='masonry'][data-part='root'][data-gap='xs'] {
    --xh-_masonry-gap: var(--xh-masonry-gap, var(--xh-layout-gap-xs));
  }

  [data-scope='masonry'][data-part='root'][data-gap='sm'] {
    --xh-_masonry-gap: var(--xh-masonry-gap, var(--xh-layout-gap-sm));
  }

  [data-scope='masonry'][data-part='root'][data-gap='md'] {
    --xh-_masonry-gap: var(--xh-masonry-gap, var(--xh-layout-gap-md));
  }

  [data-scope='masonry'][data-part='root'][data-gap='lg'] {
    --xh-_masonry-gap: var(--xh-masonry-gap, var(--xh-layout-gap-lg));
  }

  [data-scope='masonry'][data-part='root'][data-gap='xl'] {
    --xh-_masonry-gap: var(--xh-masonry-gap, var(--xh-layout-gap-xl));
  }
}

/* styles/matrix-code.css */
/* 定义 matrix code 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='matrix-code'] {
    --xh-matrix-code-skin: 1;
  }

  /*
   * 根 <svg>。深浅两色取固定档而不是语义前景/背景：语义色跟着主题走，深色主题下整张码
   * 会翻成浅底深模块的反相图，一部分读码器不认反相码。要换配色改下面这三个覆盖槽。
   *
   * 换色只有一条硬约束：码点必须比底色深，且两者对比要足。反相（浅码点深底）与
   * 深浅相近都会让一部分读码器扫不出来，而这件事肉眼看不出来。
   *
   *   --xh-matrix-code-fg      码点色，同时经 currentColor 传给码眼
   *   --xh-matrix-code-bg      底色，挖空矩形也用它
   *   --xh-matrix-code-eye-fg  码眼色，缺省跟随码点色
   */
  [data-scope='matrix-code'][data-part='root'] {
    display: block;
    border-radius: var(--xh-matrix-code-radius, var(--xh-shape-control));
    background: var(--xh-matrix-code-bg, var(--xh-color-neutral-0));

    /* 模块那条 path 不带自己的填充色，从这里继承下去 */
    color: var(--xh-matrix-code-fg, var(--xh-color-neutral-950));
    fill: currentColor;

    /* 占位与码面之间来回时，底色与那圈描边淡变 */
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      box-shadow var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 声明了 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='matrix-code'][data-part='root'][hidden] {
    display: none;
  }

  /* 码眼那条 path 恒在（与形状无关），没单独指定就退回 currentColor，跟码点同色 */
  [data-scope='matrix-code'][data-part='root'] > [data-xh-geom='eyes'] {
    fill: var(--xh-matrix-code-eye-fg, currentColor);
  }

  /*
   * logo 底下那块挖空：填的必须与根的背景逐字同一个表达式，两处一起改。
   * 差一点就会在 logo 四周露出一圈色差，读码器会把那圈当成模块边界。
   */
  [data-scope='matrix-code'][data-part='root'] > [data-xh-geom='logo-clear'] {
    fill: var(--xh-matrix-code-bg, var(--xh-color-neutral-0));
  }

  /*
   * 没有可编码的内容、以及内容超出容量：两种情形都一个模块不铺，留一块带描边的占位。
   * 占位用的是语义色——它是界面元素不是码面，跟着主题走才对。
   */
  [data-scope='matrix-code'][data-part='root'][data-state='empty'],
  [data-scope='matrix-code'][data-part='root'][data-state='error'] {
    background: var(--xh-matrix-code-placeholder-bg, var(--xh-bg-subtle));
    box-shadow: inset 0 0 0 var(--xh-stroke-thin) var(--xh-matrix-code-placeholder-border, var(--xh-border-default));
  }
}

/* styles/mention.css */
/* Mention 独立皮肤同时传递引入字段视觉盒与浮层集合行；full bundle 递归去重。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='mention'] {
    --xh-mention-skin: 1;
  }

  /* 坐标由定位引擎写进 style（inset-inline-start / inset-block-start），这里只定位模式与层级 */
  [data-scope='mention'][data-part='positioner'] {
    /* 落定那一侧的可用高度，由定位引擎经内联自定义属性写进来，内容层继承它限高；
       引擎没算（尚未落位 / 无引擎）时不额外限高 */
    --xh-_mention-available-h: 100vh;
    /* 落定那一侧的可用宽度，同样由定位引擎经内联自定义属性写进来，行内轴据此夹取；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时退到视口宽 */
    --xh-_mention-available-w: 100vw;
    /* 本层先清空祖先方向，再使用实际落位方向。 */
    --xh-_overlay-enter-up: 0;
    --xh-_overlay-enter-down: 0;
    --xh-_overlay-enter-left: 0;
    --xh-_overlay-enter-right: 0;

    /* 候选列表的自绘条浮在内容之上：轨道不上底色，实色轨道会在列表右缘糊一条竖灰带 */
    --xh-scrollbar-track-bg: transparent;

    position: fixed;
    /* listbox 与同级状态文字占同一个格；content 始终是唯一拥有材质的表面。 */
    display: grid;
    z-index: var(--xh-mention-layer, var(--xh-_layer, var(--xh-layer-popover)));
    /* 空壳不吃指针，交互只发生在 content 上 */
    pointer-events: none;
  }

  /* 输入框被滚出可视区：整个浮层随之收起 */
  [data-scope='mention'][data-part='positioner'][data-hidden] {
    visibility: hidden;
  }

  [data-scope='mention'][data-part='positioner'][hidden] {
    display: none;
  }

  /* 进退场按实际落位的物理方向移动，不随书写方向翻转。 */
  [data-scope='mention'][data-part='positioner'][data-placement^='top'] {
    --xh-_overlay-enter-down: 1;
  }

  [data-scope='mention'][data-part='positioner'][data-placement^='bottom'] {
    --xh-_overlay-enter-up: 1;
  }

  [data-scope='mention'][data-part='positioner'][data-placement^='left'] {
    --xh-_overlay-enter-right: 1;
  }

  [data-scope='mention'][data-part='positioner'][data-placement^='right'] {
    --xh-_overlay-enter-left: 1;
  }

  /* 私有槽同时声明在根与 positioner 上：浮层被搬到 portal 落点，不是根的后代，继承不过去 */
  [data-scope='mention']:is([data-part='root'], [data-part='positioner']) {
    /* 尺寸档只换这六个私有槽，输入框与候选都从这两处继承它们，换档不必给每个部件各写一条选择器 */
    --xh-_mention-h: var(--xh-control-h-md);
    --xh-_mention-px: var(--xh-control-px-md);
    --xh-_mention-item-py: var(--xh-list-option-py-md);
    --xh-_mention-item-px: var(--xh-control-px-md);
    --xh-_mention-gap: var(--xh-control-gap-md);
    --xh-_mention-font-size: var(--xh-control-font-md);
  }

  [data-scope='mention'][data-part='root'] {
    display: block;

    /* 不传尺寸时一律这么宽，宽度不随内容走；父容器给不出这么宽时整件跟着收，地板同步让步，不越出父容器。
       地板不高过缺省宽：使用者把缺省宽钉到底线以下时不必再放开底线 */
    inline-size: var(--xh-mention-input-w, var(--xh-control-w));
    min-inline-size: min(var(--xh-mention-input-w, var(--xh-control-w)), var(--xh-mention-input-min-w, var(--xh-control-min-w)), 100%);
    max-inline-size: 100%;
  }

  /* 只要声明了 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='mention'][data-part='root'][hidden] {
    display: none;
  }

  /* 标题：与输入框上下排，行距不留额外空白 */
  [data-scope='mention'][data-part='label'] {
    display: block;
    margin-block-end: var(--xh-mention-label-gap, var(--xh-space-1));
    color: var(--xh-mention-label-fg, var(--xh-fg-default));
    font-size: var(--xh-mention-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-mention-label-font-weight, var(--xh-text-label-weight));
    line-height: var(--xh-leading-none);
  }

  [data-scope='mention'][data-part='label'][hidden] {
    display: none;
  }

  [data-scope='mention'][data-part='label'][data-disabled] {
    color: var(--xh-mention-label-fg-disabled, var(--xh-fg-subtle));
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里 */
  [data-scope='mention']:is([data-part='root'], [data-part='positioner'])[data-size='sm'] {
    --xh-_mention-h: var(--xh-control-h-sm);
    --xh-_mention-px: var(--xh-control-px-sm);
    --xh-_mention-item-py: var(--xh-list-option-py-sm);
    --xh-_mention-item-px: var(--xh-control-px-sm);
    --xh-_mention-gap: var(--xh-control-gap-sm);
    --xh-_mention-font-size: var(--xh-control-font-sm);
  }

  [data-scope='mention']:is([data-part='root'], [data-part='positioner'])[data-size='lg'] {
    --xh-_mention-h: var(--xh-control-h-lg);
    --xh-_mention-px: var(--xh-control-px-lg);
    --xh-_mention-item-py: var(--xh-list-option-py-lg);
    --xh-_mention-item-px: var(--xh-control-px-lg);
    --xh-_mention-gap: var(--xh-control-gap-lg);
    --xh-_mention-font-size: var(--xh-control-font-lg);
  }

  /* 框与聚焦环都长在输入框自己身上：这里没有把输入框和别的控件裹成一体的输入行，
     整个组件在视觉上就是这一个可打字的方框。描边、底色、圆角、聚焦环、五态与悬停由 Field Chrome
     家族画在它身上（自身聚焦同样命中家族的 :focus-within）；组件只映射既有公开槽。
     家族 chrome 不设字号，输入框的字号仍由本皮肤给；形态三档由家族按 data-variant 生成 */
  [data-scope='mention'][data-part='input'] {
    --xh-field-control-height: var(--xh-mention-input-h, var(--xh-_mention-h));
    --xh-field-control-padding-inline: var(--xh-mention-input-px, var(--xh-_mention-px));
    --xh-field-control-gap: 0;
    --xh-field-control-min-inline-size: var(--xh-mention-input-min-w, var(--xh-control-min-w));
    --xh-field-control-radius: var(--xh-mention-input-radius, var(--xh-shape-control));
    --xh-field-bg-rest: var(--xh-mention-input-bg, var(--xh-_field-variant-bg-rest));
    --xh-field-bg-hover: var(--xh-mention-input-bg-hover, var(--xh-_field-variant-bg-hover));
    --xh-field-bg-read-only: var(--xh-mention-input-bg-readonly, var(--xh-_field-variant-bg-read-only));
    --xh-field-bg-disabled: var(--xh-mention-input-bg-disabled, var(--xh-_field-variant-bg-disabled));
    --xh-field-fg-rest: var(--xh-mention-input-fg, var(--xh-fg-default));
    --xh-field-border-rest: var(--xh-mention-input-border, var(--xh-_field-variant-border-rest));
    --xh-field-border-hover: var(--xh-mention-input-border-hover, var(--xh-_field-variant-border-hover));
    --xh-field-border-focus: var(--xh-mention-input-border-focus, var(--xh-_field-variant-border-focus));
    --xh-field-border-invalid: var(--xh-mention-input-border-invalid, var(--xh-_field-variant-border-invalid));
    --xh-field-ring-focus: var(--xh-ring-focus);
    --xh-field-ring-invalid: var(--xh-ring-invalid);
    --xh-field-shadow-rest: var(--xh-mention-input-shadow, none);

    inline-size: 100%;
    /* 表单控件不继承页面字体，只给字号会让输入框用 UA 默认字族，与周围文本对不上 */
    font-family: inherit;
    font-size: var(--xh-mention-input-font-size, var(--xh-_mention-font-size));
    line-height: var(--xh-leading-normal);
  }

  [data-scope='mention'][data-part='input'][hidden] {
    display: none;
  }

  /* 输入框自身即 chrome，家族按 data-xh-field-input 给的占位色命不中它，占位色仍由本皮肤给 */
  [data-scope='mention'][data-part='input']::placeholder {
    color: var(--xh-mention-placeholder-fg, var(--xh-fg-subtle));
  }

  /* 自动填充：引擎给填过的框强加一套系统色（多数是黄底黑字），盖得过 background 与 color，
     深色档下就剩一个不跟主题走的黄框。底改用 inset 阴影铺回来，扩散量 100vmax 填满内容盒；
     字改用 -webkit-text-fill-color 接回来，那是这个态下唯一还听样式表的前景通道。
     不去拉长 transition 把系统底推迟显现：那只是把它藏起来，减弱动效通道一关过渡就当场露出。
     两个选择器名分写两条：一条选择器列表里只要有一个名字不被认识，整条规则就被丢弃。
     家族按 data-xh-field-input 给的两条命不中自身即 chrome 的输入框，这里自写；底取不透明的面令牌，
     ghost 档下透明底铺了等于没铺。描边式静息无影，不再叠落影 */
  [data-scope='mention'][data-part='input']:autofill {
    box-shadow: inset 0 0 0 100vmax var(--xh-mention-input-autofill-bg, var(--xh-bg-canvas));
    -webkit-text-fill-color: var(--xh-mention-input-autofill-fg, var(--xh-fg-default));
  }

  [data-scope='mention'][data-part='input']:-webkit-autofill {
    box-shadow: inset 0 0 0 100vmax var(--xh-mention-input-autofill-bg, var(--xh-bg-canvas));
    -webkit-text-fill-color: var(--xh-mention-input-autofill-fg, var(--xh-fg-default));
  }

  [data-scope='mention'][data-part='content'] {
    position: relative;
    display: flex;
    flex-direction: column;
    gap: var(--xh-mention-content-gap, var(--xh-list-option-gap));
    grid-area: 1 / 1;
    min-inline-size: min(var(--xh-mention-content-min-w, var(--xh-overlay-min-w)), var(--xh-_mention-available-w));
    /* 静态档与落位后的可用宽度取小：窄视口下面板伸出去，最右侧的内容就点不到了 */
    max-inline-size: min(var(--xh-mention-content-max-w, var(--xh-overlay-max-w)), var(--xh-_mention-available-w));
    /* 状态文字先隐藏时仍保留完整退场面，不塌回一条空边。 */
    min-block-size: var(--xh-mention-content-min-h, var(--xh-_mention-h));
    max-block-size: min(var(--xh-mention-content-max-h, var(--xh-overlay-max-h)), var(--xh-_mention-available-h));
    padding-block: var(--xh-mention-content-py, var(--xh-space-1));
    padding-inline: var(--xh-mention-content-px, var(--xh-space-1));
    border: var(--xh-stroke-thin) solid var(--xh-mention-content-border, var(--xh-material-frosted-border));
    border-radius: var(--xh-mention-content-radius, var(--xh-shape-overlay));
    background: var(--xh-mention-content-bg, var(--xh-material-frosted-bg));
    color: var(--xh-mention-content-fg, var(--xh-material-frosted-fg));
    box-shadow: var(--xh-mention-content-shadow, var(--xh-material-frosted-shadow));
    -webkit-backdrop-filter: var(--xh-mention-content-backdrop, var(--xh-material-frosted-backdrop));
    backdrop-filter: var(--xh-mention-content-backdrop, var(--xh-material-frosted-backdrop));
    overflow-y: auto;
    /* 浮层滚动面：滚到头不把页面一起带走 */
    overscroll-behavior: contain;
    pointer-events: auto;
  }

  /* 光效仅属于唯一外壳，不拦截候选或同级状态文字。 */
  [data-scope='mention'][data-part='content']::before {
    content: '';
    position: absolute;
    inset-block-start: 0;
    inset-inline: 0;
    block-size: var(--xh-stroke-thin);
    border-radius: inherit;
    background: var(--xh-mention-content-highlight, var(--xh-material-frosted-highlight));
    pointer-events: none;
  }

  /* 这里刻意没有 [data-part='content'][hidden] { display: none }，与 dialog 一致：
     收起态连接层会给 content 打 hidden，而上面那条 display 正是要盖掉 UA 的
     [hidden]{display:none}——退场动画得先能播。presence 读的是 content 的 animationName，
     真正的收起由宿主在退场结束后落成内联 display:none（Vue 那边直接不渲染）。
     其余声明了 display 的角色节点仍补 [hidden]，那几处没有退场动画。 */

  /* 列表从不承载焦点（焦点恒在输入框，高亮走 aria-activedescendant），
     可滚动容器在某些浏览器里会被自动塞进 Tab 序列，落焦时不画环 */
  [data-scope='mention'][data-part='content']:focus-visible {
    outline: none;
  }

  [data-scope='mention'][data-part='content'][data-state='open'] {
    animation: xh-overlay-slide-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 退场：收起那一帧 hidden 由退场闸门押后，这里才播得出来。forwards 把末态钉住，
     免得动画结束到真收起之间闪一下原样 */
  [data-scope='mention'][data-part='content'][data-state='closed'] {
    animation: xh-overlay-slide-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* 候选行：网格、尺寸档、悬停 / 高亮 100、按下 200 与禁用面由 Collection Item 家族按 overlay 语境给，
     公开 Mention 槽只映射到家族合同。提及即选即执行，aria-selected 只标当前高亮那一条：
     overlay 语境的选中面透明，高亮与悬停同走 --xh-bg-subtle，正文保持常规字重 */
  [data-scope='mention'][data-part='item'] {
    --xh-collection-block-padding: var(--xh-mention-item-py, var(--xh-_mention-item-py));
    --xh-collection-inline-padding: var(--xh-mention-item-px, var(--xh-_mention-item-px));
    --xh-collection-gap: var(--xh-mention-item-gap, var(--xh-_mention-gap));
    --xh-collection-font-size: var(--xh-mention-item-font-size, var(--xh-_mention-font-size));
    --xh-collection-radius: var(--xh-mention-item-radius, var(--xh-shape-control));
    --xh-collection-fg-rest: var(--xh-mention-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-hover: var(--xh-mention-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-keyboard-highlight: var(--xh-mention-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-selected: var(--xh-mention-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-selected-highlight: var(--xh-mention-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-selected-hover: var(--xh-mention-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-selected-pressed: var(--xh-mention-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-pressed: var(--xh-mention-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-font-weight-selected: var(--xh-font-weight-regular);
    --xh-collection-font-weight-selected-highlight: var(--xh-font-weight-regular);
    --xh-collection-font-weight-selected-hover: var(--xh-font-weight-regular);
    --xh-collection-font-weight-selected-pressed: var(--xh-font-weight-regular);
    --xh-collection-bg-hover: var(--xh-mention-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-keyboard-highlight: var(--xh-mention-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-selected-highlight: var(--xh-mention-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-selected-hover: var(--xh-mention-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-pressed: var(--xh-mention-item-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-bg-selected-pressed: var(--xh-mention-item-bg-pressed, var(--xh-bg-subtle-hover));
    /* data-highlighted 同时覆盖指针与键盘路径；焦点恒在输入框，候选不接环 */
    --xh-collection-outline-keyboard-highlight: transparent;
    --xh-collection-outline-selected-highlight: transparent;

    /* 行高留出文字的上下伸展空间，行内那层 overflow:hidden 才不会把字削掉 */
    line-height: var(--xh-mention-item-leading, var(--xh-leading-normal));
    white-space: nowrap;
    user-select: none;
  }

  /* 家族给了 display，UA 的 [hidden]{display:none} 已被盖掉，这里补回来 */
  [data-scope='mention'][data-part='item'][hidden] {
    display: none;
  }

  /* 只读时正文插不进东西，候选也就不该再摆出可点的样子。
     标记读定位层那一份：候选被搬到 portal 落点，根上的只读标记够不着它们。
     排掉禁用条目是因为这条选择器权重高过上面那条，不排就会把 not-allowed 覆盖回 default */
  [data-scope='mention'][data-part='positioner'][data-readonly]
    [data-part='item']:not([data-disabled]) {
    cursor: default;
  }

  /* 正文落在家族网格的 text 列；网格项默认最小尺寸是内容尺寸，不归零则长文本把行撑破、省略号轮不上 */
  [data-scope='mention'][data-part='item-text'] {
    min-inline-size: 0;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  [data-scope='mention'][data-part='item-text'][hidden] {
    display: none;
  }

  /* 空态保持为 listbox 的同级 role=status，只把文字叠到 content 的唯一表面。 */
  [data-scope='mention'][data-part='empty'] {
    /* 同级定位保证状态文字绘制在磨砂 content 上方，不需要额外层号。 */
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    grid-area: 1 / 1;
    padding-block: var(--xh-mention-empty-py, var(--xh-space-3));
    padding-inline: var(--xh-mention-empty-px, var(--xh-_mention-item-px));
    color: var(--xh-mention-empty-fg, var(--xh-material-frosted-fg-muted));
    font-size: var(--xh-mention-empty-font-size, var(--xh-_mention-font-size));
    line-height: var(--xh-leading-none);
    text-align: center;
  }

  [data-scope='mention'][data-part='empty'][hidden] {
    display: none;
  }

  /* 在途占位与空态同格、两者不同屏；它同样不重复绘制表面。 */
  [data-scope='mention'][data-part='loading'] {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    grid-area: 1 / 1;
    padding-block: var(--xh-mention-loading-py, var(--xh-space-3));
    padding-inline: var(--xh-mention-loading-px, var(--xh-_mention-item-px));
    color: var(--xh-mention-loading-fg, var(--xh-material-frosted-fg-muted));
    font-size: var(--xh-mention-loading-font-size, var(--xh-_mention-font-size));
    line-height: var(--xh-leading-none);
    text-align: center;
  }

  [data-scope='mention'][data-part='loading'][hidden] {
    display: none;
  }

  [data-scope='mention'][data-part='empty']:empty,
  [data-scope='mention'][data-part='loading']:empty {
    display: none;
  }

  /* 手写结构可以把全部候选留在 DOM 里只加 hidden；没有可见 item 也没有状态文案时，
     打开的空 listbox 不画无意义框。closed 不命中，content 仍能完成 Presence 退场。 */
  [data-scope='mention'][data-part='positioner']:not(:has(
    > [data-scope='mention'][data-part='empty']:not([hidden]):not(:empty),
    > [data-scope='mention'][data-part='loading']:not([hidden]):not(:empty)
  )) > [data-scope='mention'][data-part='content'][data-state='open']:not(:has(
    > [data-scope='mention'][data-part='item']:not([hidden])
  )) {
    visibility: hidden;
  }

  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。 */
    [data-scope='mention'][data-part='positioner'] {
      display: none;
    }
  }
}

/* styles/number-animation.css */
/* 定义 number animation 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='number-animation'] {
    --xh-number-animation-skin: 1;
  }

  [data-scope='number-animation'][data-part='root'] {
    /* 不写尺寸就跟着上下文的字号走：这个数常常摆在别人的标题、卡片标题或统计数值槽里，
       自带一个字号只会跟摆放它的地方打架。三个档位各自换掉这个私有槽 */
    --xh-_number-animation-size: inherit;

    display: inline-block;
    color: var(--xh-number-animation-fg, var(--xh-_tone-fg, var(--xh-fg-default)));
    font-size: var(--xh-number-animation-font-size, var(--xh-_number-animation-size));
    /* 等宽数字：逐位宽度一致，逐帧换数时后面的字符不会左右挪动，整块也不会一跳一跳地变宽 */
    font-variant-numeric: tabular-nums;
    line-height: var(--xh-leading-tight);
  }

  /* 上面声明了 display，会盖掉 UA 的 [hidden] 规则，收起态要在这里接回来 */
  [data-scope='number-animation'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 尺寸 —— */
  [data-scope='number-animation'][data-part='root'][data-size='sm'] {
    --xh-_number-animation-size: var(--xh-control-font-lg);
  }

  [data-scope='number-animation'][data-part='root'][data-size='md'] {
    --xh-_number-animation-size: var(--xh-text-heading-2-size);
  }

  [data-scope='number-animation'][data-part='root'][data-size='lg'] {
    --xh-_number-animation-size: var(--xh-text-heading-1-size);
  }
}

/* styles/page-header.css */
/* 定义 page header 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='page-header'] {
    --xh-page-header-skin: 1;
  }

  [data-scope='page-header'][data-part='root'] {
    /* 尺寸档只换这三个私有槽，各段从根上继承它们，换档不必给每个部件各写一条选择器 */
    --xh-_page-header-py: var(--xh-space-4);
    --xh-_page-header-row-gap: var(--xh-space-2);
    --xh-_page-header-title-size: var(--xh-text-heading-3-size);
    /* 形态档只换这两个：不画面的那一档左右不留内衬、也不切圆角 */
    --xh-_page-header-px: 0;
    --xh-_page-header-radius: 0;

    /* 返回、媒体、标题区与操作区分列；标题与说明上下排列。 */
    display: grid;
    grid-auto-flow: dense;
    grid-template-columns: auto auto minmax(0, 1fr) auto;
    align-items: center;
    row-gap: var(--xh-page-header-row-gap, var(--xh-_page-header-row-gap));
    padding-block: var(--xh-page-header-py, var(--xh-_page-header-py));
    padding-inline: var(--xh-page-header-px, var(--xh-_page-header-px));
    border-radius: var(--xh-page-header-radius, var(--xh-_page-header-radius));
    color: var(--xh-page-header-fg, var(--xh-fg-default));
  }

  /* 上面声明了 display，会盖掉 UA 的 [hidden] 规则，收起态要在这里接回来 */
  [data-scope='page-header'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 尺寸 —— */
  [data-scope='page-header'][data-part='root'][data-size='sm'] {
    --xh-_page-header-py: var(--xh-space-3);
    --xh-_page-header-row-gap: var(--xh-space-1);
    --xh-_page-header-title-size: var(--xh-control-font-lg);
  }

  [data-scope='page-header'][data-part='root'][data-size='lg'] {
    --xh-_page-header-py: var(--xh-space-6);
    --xh-_page-header-row-gap: var(--xh-space-3);
    --xh-_page-header-title-size: var(--xh-text-heading-2-size);
  }

  /* —— 分隔线 —— */
  /* 只有贴底的 ghost 画这条下边线：一块切了圆角的面底下横一条直线，两头会露在圆角外面，
     有面的两档由自己的边界接手同一件事——把页头与下面的内容分开 */
  [data-scope='page-header'][data-part='root'][data-variant='ghost'][data-split] {
    border-block-end: var(--xh-stroke-thin) solid var(--xh-page-header-border, var(--xh-border-subtle));
  }

  /* —— 形态 —— */
  /* ghost 不在这儿：它就是上面那套基础取值，贴在页面底色上不画面。
     画了面的两档左右补上与上下同档的内衬，否则内容会贴着那块面的边 */
  [data-scope='page-header'][data-part='root']:is([data-variant='outline'], [data-variant='subtle']) {
    --xh-_page-header-px: var(--xh-_page-header-py);
    --xh-_page-header-radius: var(--xh-shape-surface);
  }

  /* outline 是一张静态内容面：--xh-border-default 描边撑住这块面的边界 + surface 底，不叠投影；
     --xh-border-subtle 只作 ghost 贴底那条分隔线用，不当根面外边 */
  [data-scope='page-header'][data-part='root'][data-variant='outline'] {
    border: var(--xh-stroke-thin) solid var(--xh-page-header-border, var(--xh-border-default));
    background: var(--xh-page-header-bg, var(--xh-bg-surface));
  }

  /* subtle 用淡底当边界：描边让位给底色但留住 1px 边位（与 outline 同一几何）、无影 */
  [data-scope='page-header'][data-part='root'][data-variant='subtle'] {
    border: var(--xh-stroke-thin) solid transparent;
    background: var(--xh-page-header-bg, var(--xh-bg-subtle));
  }

  /* —— 各段 —— */
  /* 面包屑占满一整行排在标题之上：它写在标记的最前面，整行铺开就把标题挤到了下一行 */
  [data-scope='page-header'][data-part='breadcrumb'] {
    grid-column: 1 / -1;
    color: var(--xh-page-header-breadcrumb-fg, var(--xh-fg-muted));
    font-size: var(--xh-page-header-breadcrumb-font-size, var(--xh-text-secondary-size));
    line-height: var(--xh-leading-normal);
  }

  /* 头像 / 图标位：不参与伸缩，图形本身多大由作者定 */
  [data-scope='page-header'][data-part='media'] {
    grid-column: 2;
    margin-inline-end: var(--xh-page-header-column-gap, var(--xh-space-3));
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  /* 返回位只摆位置与对齐，外观归作者自己的按钮 */
  [data-scope='page-header'][data-part='back-trigger'] {
    grid-column: 1;
    margin-inline-end: var(--xh-page-header-column-gap, var(--xh-space-3));
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  [data-scope='page-header'][data-part='title'] {
    grid-column: 3;
    margin: 0;
    /* 标题不参与伸缩，长过整行时收到行宽为止，中间没有断点的长串在行尾断开，
       不把整条页头撑出容器 */
    max-inline-size: 100%;
    overflow-wrap: anywhere;
    color: var(--xh-page-header-title-fg, var(--xh-fg-default));
    font-size: var(--xh-page-header-title-font-size, var(--xh-_page-header-title-size));
    /* 页面级标题：字重走标题档令牌，不直接下探字重原语 */
    font-weight: var(--xh-page-header-title-font-weight, var(--xh-text-heading-3-weight));
    line-height: var(--xh-leading-tight);
  }

  /* 副标题吃掉标题与操作之间的剩余宽度，长文本在这里收窄换行 */
  [data-scope='page-header'][data-part='description'] {
    grid-column: 3;
    margin: 0;
    min-inline-size: 0;
    color: var(--xh-page-header-description-fg, var(--xh-fg-muted));
    font-size: var(--xh-page-header-description-font-size, var(--xh-text-secondary-size));
    line-height: var(--xh-leading-normal);
  }

  /* 操作区贴到行尾，没有副标题占位时也一样靠边 */
  [data-scope='page-header'][data-part='extra'] {
    grid-column: 4;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--xh-page-header-extra-gap, var(--xh-space-2));
    margin-inline-start: var(--xh-page-header-column-gap, var(--xh-space-3));
    justify-self: end;
  }

  /* 页脚占满一整行，前面有内容时自然被挤到下一行 */
  [data-scope='page-header'][data-part='footer'] {
    grid-column: 1 / -1;
    color: var(--xh-page-header-footer-fg, var(--xh-fg-muted));
    font-size: var(--xh-page-header-footer-font-size, var(--xh-text-secondary-size));
    line-height: var(--xh-leading-normal);
  }

  [data-scope='page-header'][data-part='root']:has(> [data-part='description'])
    > :is([data-part='back-trigger'], [data-part='media'], [data-part='extra']) {
    grid-row: span 2;
  }

  /* 窄于 sm 断点时标题区占满第二列、操作区换到下一行。写成 min-width 的补集：640px 本身归宽档，
     与其余皮肤在同一宽度切换 */
  @media not all and (min-width: 640px) {
    [data-scope='page-header'][data-part='root'] {
      grid-template-columns: auto minmax(0, 1fr);
    }

    [data-scope='page-header'][data-part='media'],
    [data-scope='page-header'][data-part='title'],
    [data-scope='page-header'][data-part='description'] {
      grid-column: 2;
    }

    [data-scope='page-header'][data-part='root'] > [data-part='extra'] {
      grid-column: 1 / -1;
      grid-row: auto;
      margin-inline-start: 0;
      justify-self: start;
    }
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='page-header'][data-part='back-trigger'][hidden],
  [data-scope='page-header'][data-part='media'][hidden],
  [data-scope='page-header'][data-part='extra'][hidden] {
    display: none;
  }
}

/* styles/password-input.css */
/* PasswordInput 独立皮肤同时传递引入字段视觉盒与字段内动作；full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='password-input'] {
    --xh-password-input-skin: 1;
  }

  /* root 只负责纵向堆叠：标签一行、输入行一行。
     输入框、切换钮与大写锁定提示收进 control 部件即得一体式：视觉盒由 Field Chrome 家族画在 control 上，
     框内三件都退成透明分段，整枚控件从头到尾只有一道描边。
     不写 control 时是独立输入框和按钮，不再绘制独立外壳（与 text-field 同）。
     组件层只把既有公开槽映射到家族合同；形态三档由家族按 control 上的 data-variant 生成，皮肤不再声明。 */
  [data-scope='password-input'][data-part='root'] {
    /* 作者塞进来的图标跟着控件的尺寸档走；它自己写了 size 时仍以作者的为准 */
    --xh-icon-size: var(--xh-password-input-icon-size, var(--xh-glyph-size-md));

    /* 尺寸档只换这几个私有槽，输入框、切换钮与提示都从 root 继承它们，
       换档不必给每个部件各写一条选择器 */
    --xh-_password-input-h: var(--xh-control-h-md);
    --xh-_password-input-px: var(--xh-control-px-md);
    --xh-_password-input-gap: var(--xh-control-gap-md);
    --xh-_password-input-font-size: var(--xh-control-font-md);
    /* 提示与切换钮里的字形都比正文小一档，三个尺寸档各自换过，不是一个恒等的中转 */
    --xh-_password-input-caps-lock-font-size: var(--xh-control-caption-md);
    --xh-_password-input-trigger-font-size: var(--xh-control-caption-md);
    /* 切换钮与输入之间那道线的长度：取钮高的一半，线的上下各留一截空白 */
    --xh-_password-input-divider-h: 50%;

    /* 盒里有两个 Tab 停靠点，切换钮上再画一圈自己的环；环恒用 --xh-ring-focus，校验失败时随盒换红 */
    --xh-_password-input-ring: var(--xh-ring-focus);

    display: inline-flex;
    flex-direction: column;
    gap: var(--xh-password-input-gap, var(--xh-space-1));

    /* 不传尺寸时一律这么宽，宽度不随内容走；父容器给不出这么宽时整件跟着收，地板同步让步，不越出父容器。
       地板不高过缺省宽：使用者把缺省宽钉到底线以下时不必再放开底线 */
    inline-size: var(--xh-password-input-control-w, var(--xh-control-w));
    min-inline-size: min(var(--xh-password-input-control-w, var(--xh-control-w)), var(--xh-password-input-control-min-w, var(--xh-control-min-w)), 100%);
    max-inline-size: 100%;
  }

  /* 只要声明了 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='password-input'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里 */
  [data-scope='password-input'][data-part='root'][data-size='sm'] {
    --xh-icon-size: var(--xh-password-input-icon-size, var(--xh-glyph-size-sm));
    --xh-_password-input-h: var(--xh-control-h-sm);
    --xh-_password-input-px: var(--xh-control-px-sm);
    --xh-_password-input-gap: var(--xh-control-gap-sm);
    --xh-_password-input-font-size: var(--xh-control-font-sm);
    --xh-_password-input-caps-lock-font-size: var(--xh-control-caption-sm);
    --xh-_password-input-trigger-font-size: var(--xh-control-caption-sm);
  }

  [data-scope='password-input'][data-part='root'][data-size='lg'] {
    --xh-icon-size: var(--xh-password-input-icon-size, var(--xh-glyph-size-lg));
    --xh-_password-input-h: var(--xh-control-h-lg);
    --xh-_password-input-px: var(--xh-control-px-lg);
    --xh-_password-input-gap: var(--xh-control-gap-lg);
    --xh-_password-input-font-size: var(--xh-control-font-lg);
    --xh-_password-input-caps-lock-font-size: var(--xh-control-caption-lg);
    --xh-_password-input-trigger-font-size: var(--xh-control-caption-lg);
  }

  /* —— 标题 —— */
  [data-scope='password-input'][data-part='label'] {
    color: var(--xh-password-input-label-fg, var(--xh-fg-default));
    font-size: var(--xh-password-input-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-password-input-label-font-weight, var(--xh-text-label-weight));
  }

  [data-scope='password-input'][data-part='label'][data-disabled] {
    color: var(--xh-password-input-label-fg-disabled, var(--xh-fg-subtle));
  }

  /* —— 一体式 control：输入框、切换钮与提示同框 —— */
  /* control 是唯一的视觉盒：描边、底色、圆角、聚焦环、五态与悬停由 Field Chrome 家族画。
     :focus-within 而不是 :focus——盒里有两个 Tab 停靠点，输入框与切换钮各占一个 */
  [data-scope='password-input'][data-part='control'] {
    --xh-field-control-height: var(--xh-password-input-control-h, var(--xh-_password-input-h));
    --xh-field-control-padding-inline: var(--xh-password-input-control-px, var(--xh-_password-input-px));
    --xh-field-control-gap: var(--xh-password-input-control-gap, var(--xh-_password-input-gap));
    --xh-field-control-min-inline-size: var(--xh-password-input-control-min-w, var(--xh-control-min-w));
    --xh-field-control-radius: var(--xh-password-input-control-radius, var(--xh-shape-control));
    --xh-field-bg-rest: var(--xh-password-input-control-bg, var(--xh-_field-variant-bg-rest));
    --xh-field-bg-hover: var(--xh-password-input-control-bg-hover, var(--xh-_field-variant-bg-hover));
    --xh-field-bg-read-only: var(--xh-password-input-control-bg-readonly, var(--xh-_field-variant-bg-read-only));
    --xh-field-bg-disabled: var(--xh-password-input-control-bg-disabled, var(--xh-_field-variant-bg-disabled));
    --xh-field-fg-rest: var(--xh-password-input-control-fg, var(--xh-fg-default));
    --xh-field-border-rest: var(--xh-password-input-control-border, var(--xh-_field-variant-border-rest));
    --xh-field-border-hover: var(--xh-password-input-control-border-hover, var(--xh-_field-variant-border-hover));
    --xh-field-border-focus: var(--xh-password-input-control-border-focus, var(--xh-_field-variant-border-focus));
    --xh-field-border-invalid: var(--xh-password-input-control-border-invalid, var(--xh-_field-variant-border-invalid));
    --xh-field-ring-focus: var(--xh-ring-focus);
    --xh-field-ring-invalid: var(--xh-ring-invalid);
    --xh-field-shadow-rest: var(--xh-password-input-control-shadow, none);
    /* 家族 chrome 会重写 --xh-icon-size，使用者图标槽必须经桥接槽下发才能在盒内生效 */
    --xh-field-glyph-size: var(--xh-password-input-icon-size, var(--xh-_field-size-glyph-size));
  }

  [data-scope='password-input'][data-part='control'][hidden] {
    display: none;
  }

  /* 校验失败时切换钮自己那圈环也跟着变红：两圈等宽相邻却一红一蓝，读的人不知道哪个才是当前状态 */
  [data-scope='password-input'][data-part='control'][data-invalid] {
    --xh-_password-input-ring: var(--xh-ring-invalid);
  }

  /* —— 输入框 —— */
  /* 无边框无底无圆角无落影由家族重置，观感全归 control；自动填充由家族用 canvas 实体底与默认前景重绘 */
  [data-scope='password-input'][data-part='input'] {
    --xh-field-input-fg: var(--xh-password-input-input-fg, var(--xh-fg-default));
    --xh-field-input-font-size: var(--xh-password-input-input-font-size, var(--xh-_password-input-font-size));
    --xh-field-placeholder-fg: var(--xh-password-input-placeholder-fg, var(--xh-fg-subtle));
    --xh-field-autofill-bg: var(--xh-password-input-input-autofill-bg, var(--xh-bg-canvas));
    --xh-field-autofill-fg: var(--xh-password-input-input-autofill-fg, var(--xh-fg-default));
  }

  /* —— 明暗切换钮 —— */
  /* 正方视觉盒、inset 圆角、悬停 100 / 按下 200 与 0.97 按压、粗指针热区全由 Action Control 的
     field-inset ghost 档给，组件只映射既有覆盖槽；常态只剩符号，符号取次级前景 */
  [data-scope='password-input'][data-part='visibility-trigger'] {
    --xh-action-visual-size: var(--xh-password-input-trigger-size, var(--xh-_action-profile-visual-size));
    --xh-action-min-inline-size: var(--xh-password-input-trigger-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-password-input-trigger-radius, var(--xh-shape-inset));
    /* 底色阶梯由 ghost 档给（透明 → 100 → 200），使用者槽只作覆盖入口 */
    --xh-action-bg-rest: var(--xh-password-input-trigger-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-password-input-trigger-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-password-input-trigger-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-password-input-trigger-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-password-input-trigger-fg-hover, var(--xh-fg-default));
    --xh-action-border-rest: transparent;
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    --xh-action-font-size: var(--xh-password-input-trigger-font-size, var(--xh-_password-input-trigger-font-size));
    /* 配方尚未把 profile 字形档灌进 --xh-icon-size，钮内字形先按 field-inset 档逐钮取值 */
    --xh-icon-size: var(--xh-_action-profile-glyph-size);

    border-width: 0;

    --xh-_password-input-mark: var(--xh-glyph-mark-eye);
  }

  [data-scope='password-input'][data-part='visibility-trigger'][hidden] {
    display: none;
  }

  /* 显隐动作与输入/状态区之间留一道半高分隔。::before 是兜底字形、::after 在粗指针下是家族给的
     44px 热区，线只能落在 background-image 上：一条 1px × 半高的渐变贴在靠输入的那一侧，
     不随按钮悬停底或圆角变化。background-position 是物理轴，RTL 另给两条换边。 */
  [data-scope='password-input'][data-part='control']
    > [data-scope='password-input'][data-part='visibility-trigger']:has(~ [data-scope='password-input'][data-part='input']),
  [data-scope='password-input'][data-part='control']
    > [data-scope='password-input'][data-part='input'] ~ [data-scope='password-input'][data-part='visibility-trigger'] {
    background-image: linear-gradient(
      var(--xh-password-input-visibility-trigger-separator-color, var(--xh-border-subtle)),
      var(--xh-password-input-visibility-trigger-separator-color, var(--xh-border-subtle))
    );
    background-repeat: no-repeat;
    background-size: var(--xh-stroke-thin) var(--xh-password-input-visibility-trigger-separator-h, var(--xh-_password-input-divider-h));
  }

  /* 钮排在输入之前：线贴在钮的逻辑末端 */
  [data-scope='password-input'][data-part='control']
    > [data-scope='password-input'][data-part='visibility-trigger']:has(~ [data-scope='password-input'][data-part='input']) {
    background-position: 100% 50%;
  }

  [dir='rtl'] [data-scope='password-input'][data-part='control']
    > [data-scope='password-input'][data-part='visibility-trigger']:has(~ [data-scope='password-input'][data-part='input']) {
    background-position: 0 50%;
  }

  /* 钮排在输入之后：线贴在钮的逻辑起始侧 */
  [data-scope='password-input'][data-part='control']
    > [data-scope='password-input'][data-part='input'] ~ [data-scope='password-input'][data-part='visibility-trigger'] {
    background-position: 0 50%;
  }

  [dir='rtl'] [data-scope='password-input'][data-part='control']
    > [data-scope='password-input'][data-part='input'] ~ [data-scope='password-input'][data-part='visibility-trigger'] {
    background-position: 100% 50%;
  }

  /* 盒里有两个 Tab 停靠点，盒子在 :focus-within 上画的那一圈两者完全一样，
     分不出焦点在框里还是在钮上，所以钮上再画一圈自己的环（家族只对不占 Tab 位的内嵌钮关环）。
     环往内收，压在按钮自己的方框里，不与盒子外面那一圈叠在一起。
     指示焦点只能用环不能用底色：可用的几档底色压在盒底上都到不了 3:1，换了色也等于没画 */
  [data-scope='password-input'][data-part='control'] [data-part='visibility-trigger']:focus-visible {
    outline: var(--xh-ring-width) solid var(--xh-_password-input-ring);
    outline-offset: var(--xh-ring-offset);
  }

  /* 明暗两态各一枚字形：换的是这个槽，兜底盒的量法只写一遍 */
  [data-scope='password-input'][data-part='visibility-trigger'][data-state='visible'] {
    --xh-_password-input-mark: var(--xh-glyph-mark-eye-off);
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这条即不命中 */
  [data-scope='password-input'][data-part='visibility-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-_password-input-mark) center / contain no-repeat;
    mask: var(--xh-_password-input-mark) center / contain no-repeat;
  }

  /* —— 大写锁定提示 —— */
  /* 贴在切换钮之前的一小块提示，字号比正文小一档，颜色取次级前景：
     它是提示不是报错，抢不过框里正在输入的内容。
     槽名按部件取 --xh-password-input-caps-lock-* */
  /* 这一格恒占一个字形的宽，开合都不变：区内那句话有多长，控件就跟着宽多少，
     而这个盒是收缩包裹的（见 control 的 inline-flex），一开大写锁定控件当场宽出一整句话。
     文字留在盒里不动——它是活区域要念的内容——只是被 text-indent 推出可视范围，
     露出来的是 ::before 画的那枚字形。 */
  [data-scope='password-input'][data-part='caps-lock-indicator'] {
    position: relative;
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    overflow: hidden;
    color: var(--xh-password-input-caps-lock-fg, var(--xh-fg-muted));
    font-size: var(--xh-password-input-caps-lock-font-size, var(--xh-_password-input-caps-lock-font-size));
    line-height: var(--xh-leading-none);
    white-space: nowrap;
    text-indent: 100%;
  }

  [data-scope='password-input'][data-part='control'][data-disabled]
    > [data-scope='password-input'][data-part='caps-lock-indicator'] {
    color: var(--xh-password-input-caps-lock-fg-disabled, var(--xh-fg-disabled));
  }

  /* 开着时才画字形：这一格的宽两态一样，画不画只换露不露出记号 */
  [data-scope='password-input'][data-part='caps-lock-indicator'][data-state='visible']::before {
    content: '';
    position: absolute;
    inset: 0;
    margin: auto;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-arrow-up) center / contain no-repeat;
    mask: var(--xh-glyph-mark-arrow-up) center / contain no-repeat;
  }

  /* 作者自己给这个节点写 hidden 时照样收起；上面那条 display 会把 UA 规则盖掉，
     少了这条它就一直杵在那儿 */
  [data-scope='password-input'][data-part='caps-lock-indicator'][hidden] {
    display: none;
  }

  /* 没开大写锁定时只把这块收成零宽，不用 display / visibility 撤掉它：
     播报区一旦从渲染树里消失就不再是活区域，重新出现时读屏当作插入了个新节点，多数不念。
     这一格的宽两态一样，关着时只是不画字形，盒本身照旧在场 */
  [data-scope='password-input'][data-part='caps-lock-indicator'][data-state='hidden']::before {
    content: none;
  }

  /* 强度条：一条底槽，填充按档位加长。档位由调用方打分后经 strength 传进来，
     0 与 1 判弱、2 判中、3 与 4 判强，三段各取一族语义色 */
  [data-scope='password-input'][data-part='strength-meter'] {
    --xh-_password-input-strength-fill: 0%;
    --xh-_password-input-strength-fg: var(--xh-fg-muted);

    display: block;
    overflow: hidden;
    inline-size: 100%;
    block-size: var(--xh-password-input-strength-thickness, var(--xh-track-thickness));
    border-radius: var(--xh-password-input-strength-radius, var(--xh-shape-pill));
    background: var(--xh-password-input-strength-track, var(--xh-bg-subtle-active));
  }

  /* 没给 strength 时连接层给的是 hidden 属性；上面那条 display 会把 UA 规则盖掉 */
  [data-scope='password-input'][data-part='strength-meter'][hidden] {
    display: none;
  }

  /* 没写内容就由皮肤画填充；作者往部件里塞了自己的分段，这几条即不命中 */
  [data-scope='password-input'][data-part='strength-meter']:empty::before {
    content: '';
    display: block;
    inline-size: var(--xh-_password-input-strength-fill);
    block-size: 100%;
    border-radius: inherit;
    background: var(--xh-password-input-strength-fg, var(--xh-_password-input-strength-fg));
  }

  [data-scope='password-input'][data-part='strength-meter'][data-level='1'] {
    --xh-_password-input-strength-fill: 25%;
    --xh-_password-input-strength-fg: var(--xh-fg-danger);
  }

  [data-scope='password-input'][data-part='strength-meter'][data-level='2'] {
    --xh-_password-input-strength-fill: 50%;
    --xh-_password-input-strength-fg: var(--xh-fg-warning);
  }

  [data-scope='password-input'][data-part='strength-meter'][data-level='3'] {
    --xh-_password-input-strength-fill: 75%;
    --xh-_password-input-strength-fg: var(--xh-fg-success);
  }

  [data-scope='password-input'][data-part='strength-meter'][data-level='4'] {
    --xh-_password-input-strength-fill: 100%;
    --xh-_password-input-strength-fg: var(--xh-fg-success);
  }

  [data-scope='password-input'][data-part='strength-meter'][data-disabled] {
    --xh-_password-input-strength-fg: var(--xh-fg-disabled);
  }

  /* 高对比档整层丢弃 background-image，分隔线改用系统色重画，并关掉这一颗钮的强制换色 */
  @media (forced-colors: active) {
    [data-scope='password-input'][data-part='control']
      > [data-scope='password-input'][data-part='visibility-trigger']:has(~ [data-scope='password-input'][data-part='input']),
    [data-scope='password-input'][data-part='control']
      > [data-scope='password-input'][data-part='input'] ~ [data-scope='password-input'][data-part='visibility-trigger'] {
      background-image: linear-gradient(CanvasText, CanvasText);
      forced-color-adjust: none;
    }

    [data-scope='password-input'][data-part='control'][data-disabled]
      > [data-scope='password-input'][data-part='visibility-trigger']:has(~ [data-scope='password-input'][data-part='input']),
    [data-scope='password-input'][data-part='control'][data-disabled]
      > [data-scope='password-input'][data-part='input'] ~ [data-scope='password-input'][data-part='visibility-trigger'] {
      background-image: linear-gradient(GrayText, GrayText);
    }

    /* 关掉强制换色后，上面那圈自留的 :focus-visible 环与家族普通态的焦点底/字都会按作者色落地；
       家族高对比块的特指度压不过它们，这里用同一选择器把环、底、字改回系统色 */
    [data-scope='password-input'][data-part='control'] [data-part='visibility-trigger']:focus-visible {
      outline-color: Highlight;
      background-color: ButtonFace;
      color: ButtonText;
    }
  }
}

/* styles/popconfirm.css */
/* 定义 popconfirm 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='popconfirm'] {
    --xh-popconfirm-skin: 1;
  }

  /* 根只框住触发器：浮层树靠 positioner 的固定定位飞出去，不占根的盒子 */
  [data-scope='popconfirm'][data-part='root'] {
    display: inline-block;
  }

  /*
   * 触发器是页面上的独立文字按钮：盒型、md 档几何、outline 四态面、0.97 按压并换底与粗指针命中区
   * 由家族配方按连接层投影的 data-xh-action-variant / -size 给出。皮肤没有自己的外观规则，
   * 只把作者塞进按钮的图标接到随档字形尺（md = 20px）。
   */
  [data-scope='popconfirm'][data-part='trigger'] {
    --xh-icon-size: var(--xh-popconfirm-icon-size, var(--xh-_action-profile-glyph-size));
  }

  /* 家族配方给了 display，作者手写 hidden 时得把 UA 的 [hidden]{display:none} 还回去 */
  [data-scope='popconfirm'][data-part='trigger'][hidden] {
    display: none;
  }

  /* 坐标由定位引擎写进 style（inset-inline-start / inset-block-start），这里只定位模式与层级 */
  [data-scope='popconfirm'][data-part='positioner'] {
    /* 落定那一侧的可用高度，由定位引擎经内联自定义属性写进来，面板继承它限高；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时不额外限高 */
    --xh-_popconfirm-available-h: 100vh;
    /* 落定那一侧的可用宽度，同一路由定位引擎写进来，行内轴据此夹取；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时退到视口宽 */
    --xh-_popconfirm-available-w: 100vw;

    /* 面板内容的自绘条浮在内容之上：轨道不上底色，实色轨道会在面板右缘糊一条竖灰带 */
    --xh-scrollbar-track-bg: transparent;

    position: fixed;
    z-index: var(--xh-popconfirm-layer, var(--xh-_layer, var(--xh-layer-popover)));
    /* 空壳不吃指针，交互只发生在 content 上 */
    pointer-events: none;
  }

  /* 锚点被滚出可视区：整个浮层随之收起 */
  [data-scope='popconfirm'][data-part='positioner'][data-hidden] {
    visibility: hidden;
  }

  /* 缩放原点与进场位移按落定的那一侧给：面板从贴着锚点的那条边涨开、沿主轴退让一小段。
     两个槽由 content 继承。placement 是物理方向（引擎按 top / right / bottom / left 出值），
     origin 与 translate 也是物理量，两边同轴，不随书写方向翻 */
  [data-scope='popconfirm'][data-part='positioner'][data-placement^='top'] {
    --xh-_overlay-origin-y: 100%;
    --xh-_overlay-enter-down: 1;
  }

  [data-scope='popconfirm'][data-part='positioner'][data-placement^='bottom'] {
    --xh-_overlay-origin-y: 0;
    --xh-_overlay-enter-up: 1;
  }

  [data-scope='popconfirm'][data-part='positioner'][data-placement^='left'] {
    --xh-_overlay-origin-x: 100%;
    --xh-_overlay-enter-right: 1;
  }

  [data-scope='popconfirm'][data-part='positioner'][data-placement^='right'] {
    --xh-_overlay-origin-x: 0;
    --xh-_overlay-enter-left: 1;
  }

  /* 面板排成三列：左列吃掉剩余宽度，右两列各摆一颗按钮。
     标题、说明与作者塞进来的内容各占一整行，两颗按钮因此并排落在最后一行的右侧。 */
  [data-scope='popconfirm'][data-part='content'] {
    /* 作者塞进面板里的图标按控件档取；两颗动作钮另由家族配方按 sm 档下发字形尺 */
    --xh-icon-size: var(--xh-popconfirm-icon-size, var(--xh-glyph-size-md));
    /* 尺寸档只换这两个私有槽 */
    --xh-_popconfirm-pad: var(--xh-surface-pad-md);
    --xh-_popconfirm-max-w: var(--xh-overlay-max-w);

    position: relative;
    display: grid;
    grid-template-columns: 1fr auto auto;
    align-items: center;
    gap: var(--xh-popconfirm-gap, var(--xh-space-2));
    inline-size: max-content;
    /* 静态档与落位后的可用宽度取小：窄视口下面板伸出去，最右侧的两颗钮就点不到了 */
    max-inline-size: min(var(--xh-popconfirm-max-w, var(--xh-_popconfirm-max-w)), var(--xh-_popconfirm-available-w));
    /* 说明文案长度由作者给，矮视口下不限高面板会整块伸出视口且滚不到 */
    max-block-size: min(var(--xh-popconfirm-max-h, var(--xh-overlay-max-h)), var(--xh-_popconfirm-available-h));
    overflow-y: auto;
    /* 浮在页面之上的 Overlay 滚动面：滚到头不把页面一起带走 */
    overscroll-behavior: contain;
    padding-block: var(--xh-popconfirm-py, var(--xh-_popconfirm-pad));
    padding-inline: var(--xh-popconfirm-px, var(--xh-_popconfirm-pad));
    border: var(--xh-stroke-thin) solid var(--xh-popconfirm-border, var(--xh-material-frosted-border));
    border-radius: var(--xh-popconfirm-radius, var(--xh-shape-overlay));
    /* 与 Popover 共用 M2 配方：透明 tint 在底层，内侧一像素顶光只表达材质厚度。 */
    background:
      linear-gradient(
        to bottom,
        var(--xh-material-frosted-highlight) 0 var(--xh-stroke-thin),
        transparent var(--xh-stroke-thin)
      ),
      var(--xh-popconfirm-bg, var(--xh-material-frosted-bg));
    color: var(--xh-popconfirm-fg, var(--xh-material-frosted-fg));
    box-shadow: var(--xh-popconfirm-shadow, var(--xh-material-frosted-shadow));
    -webkit-backdrop-filter: var(--xh-popconfirm-backdrop, var(--xh-material-frosted-backdrop));
    backdrop-filter: var(--xh-popconfirm-backdrop, var(--xh-material-frosted-backdrop));
    pointer-events: auto;
    /* 进退场的缩放锚在贴着锚点的那条边上；两个分量由 positioner 按 placement 写进私有槽 */
    transform-origin: var(--xh-_overlay-origin-x, 50%) var(--xh-_overlay-origin-y, 50%);
  }

  [data-scope='popconfirm'][data-part='content'] > * {
    grid-column: 1 / -1;
  }

  /* 箭头绝对定位挂在 content 上，不占格：吃到栅格位的话它的贴边就从格线起算，被内衬推进面里 */
  [data-scope='popconfirm'][data-part='content'] > [data-part='arrow'] {
    grid-column: auto;
  }

  /* 这里刻意没有 [data-part='content'][hidden] { display: none }，与 dialog 一致：
     收起态连接层会给 content 打 hidden，而上面那条 display 正是要盖掉 UA 的
     [hidden]{display:none}——退场动画得先能播。presence 读的是 content 的 animationName，
     真正的收起由宿主在退场结束后落成内联 display:none（Vue 那边直接不渲染）。
     其余声明了 display 的角色节点仍补 [hidden]，那几处没有退场动画。 */

  [data-scope='popconfirm'][data-part='content']:focus-visible {
    outline: none;
  }

  [data-scope='popconfirm'][data-part='content'][data-state='open'] {
    animation: xh-overlay-pop-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 退场：收起那一帧 hidden 由退场闸门押后，这里才播得出来。forwards 把末态钉住，
     免得动画结束到真收起之间闪一下原样 */
  [data-scope='popconfirm'][data-part='content'][data-state='closed'] {
    animation: xh-pop-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* —— 尺寸 —— */
  /* 缺省档写在 content 的基础规则里；四边等宽的面板内衬三档取 surface-pad 那把尺 */
  [data-scope='popconfirm'][data-part='content'][data-size='sm'] {
    --xh-_popconfirm-pad: var(--xh-surface-pad-sm);
    --xh-_popconfirm-max-w: var(--xh-overlay-max-w-sm);
  }

  [data-scope='popconfirm'][data-part='content'][data-size='lg'] {
    --xh-_popconfirm-pad: var(--xh-surface-pad-lg);
    --xh-_popconfirm-max-w: var(--xh-overlay-max-w-lg);
  }

  [data-scope='popconfirm'][data-part='title'] {
    margin: 0;
    min-inline-size: 0;
    font-size: var(--xh-popconfirm-title-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-popconfirm-title-font-weight, var(--xh-font-weight-semibold));
    line-height: var(--xh-leading-tight);
    overflow-wrap: anywhere;
    color: var(--xh-popconfirm-title-fg, var(--xh-material-frosted-fg));
  }

  /* 说明文字走说明档：13px + fg-muted */
  [data-scope='popconfirm'][data-part='description'] {
    margin: 0;
    min-inline-size: 0;
    font-size: var(--xh-popconfirm-description-font-size, var(--xh-text-secondary-size));
    line-height: var(--xh-leading-normal);
    overflow-wrap: anywhere;
    color: var(--xh-popconfirm-description-fg, var(--xh-fg-muted));
  }

  /* 箭头的底色与描边色，几何在 overlay-arrow.css。
     交叉轴落点由定位引擎经内联自定义属性写进来，没给时退回居中 */
  [data-scope='popconfirm'][data-part='arrow'] {
    --xh-_popconfirm-arrow-x: 50%;
    --xh-_popconfirm-arrow-y: 50%;
    --xh-_overlay-arrow-size: var(--xh-popconfirm-arrow-size, var(--xh-overlay-arrow-size));
    --xh-_overlay-arrow-x: var(--xh-_popconfirm-arrow-x);
    --xh-_overlay-arrow-y: var(--xh-_popconfirm-arrow-y);

    background: var(--xh-popconfirm-bg, var(--xh-material-frosted-bg));
    border: var(--xh-stroke-thin) solid var(--xh-popconfirm-border, var(--xh-material-frosted-border));
  }

  /*
   * —— 两颗按钮 ——
   * 确认与取消都是浮层末行的文字按钮：盒型、sm 档几何、四态面、0.97 按压并换底、粗指针命中区与
   * 强制色由家族配方按连接层投影的 data-xh-action-variant / -size 给出。这里只把公开槽桥接到矩阵之前
   * （使用者槽 → 形态矩阵 → 家族缺省）与几何映射；内衬与圆角槽取两颗共用的 action 段。
   */
  [data-scope='popconfirm'][data-part='confirm-trigger'],
  [data-scope='popconfirm'][data-part='cancel-trigger'] {
    --xh-action-padding-inline: var(--xh-popconfirm-action-px, var(--xh-_action-profile-padding-inline));
    --xh-action-radius: var(--xh-popconfirm-action-radius, var(--xh-shape-control));
    --xh-action-shadow-rest: var(--xh-popconfirm-action-shadow, none);
    /* 作者塞进按钮的图标随档取字形尺（sm = 16px） */
    --xh-icon-size: var(--xh-popconfirm-icon-size, var(--xh-_action-profile-glyph-size));

    /* 动作钮的文字与 Button 同一字重（家族配方不管字重） */
    font-weight: var(--xh-popconfirm-action-font-weight, var(--xh-text-label-weight));
  }

  /* 并排落在最后一行的右侧两格；取消在左、确认在右 */
  [data-scope='popconfirm'][data-part='content'] > [data-part='cancel-trigger'] {
    grid-column: 2;
  }

  [data-scope='popconfirm'][data-part='content'] > [data-part='confirm-trigger'] {
    grid-column: 3;
  }

  /* 确认是实心的主操作。底色走共享语气槽：作者在 content 上写 data-tone="danger"
     就整体换成危险色，不写则用品牌色——配方 solid 列本就读 --xh-_tone，这里只桥接使用者槽 */
  [data-scope='popconfirm'][data-part='confirm-trigger'] {
    --xh-action-bg-rest: var(--xh-popconfirm-confirm-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-focus-visible: var(--xh-popconfirm-confirm-bg, var(--xh-_action-variant-bg-focus-visible));
    --xh-action-bg-loading: var(--xh-popconfirm-confirm-bg, var(--xh-_action-variant-bg-loading));
    --xh-action-fg-rest: var(--xh-popconfirm-confirm-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-popconfirm-confirm-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-popconfirm-confirm-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-fg-focus-visible: var(--xh-popconfirm-confirm-fg, var(--xh-_action-variant-fg-focus-visible));
    --xh-action-fg-loading: var(--xh-popconfirm-confirm-fg, var(--xh-_action-variant-fg-loading));
    --xh-action-shadow-rest: var(--xh-popconfirm-confirm-shadow, var(--xh-popconfirm-action-shadow, none));
  }

  /* 面是实心的，环色与面同族，画在面里就看不出来；环改取面自己的前景色——
     那一族色本来就要在这块面上把字读清楚，与面的对比是按可读性定的 */
  [data-scope='popconfirm'][data-part='confirm-trigger'][data-xh-action-variant='solid']:focus-visible {
    --xh-action-ring-color-focus-visible: currentColor;
  }

  /* 异步确认挂起：确认文案前转一枚圆环；不是禁用，焦点与对比度都保持，在途指针由家族 loading 面给 */
  [data-scope='popconfirm'][data-part='confirm-trigger'][data-loading]::before {
    content: '';
    inline-size: 1em;
    block-size: 1em;
    margin-inline-end: var(--xh-space-1);
    border: var(--xh-stroke-thin) solid transparent;
    border-block-start-color: currentcolor;
    border-radius: var(--xh-shape-circle);
    animation: xh-spin var(--xh-popconfirm-loading-duration, var(--xh-spin-duration)) var(--xh-motion-ease-loop) infinite;
  }

  /* 取消是中性的次要出口，不参与语气：content 上的 data-tone 会把 --xh-_tone-* 一路继承下来，
     配方 outline 列的面、字与边都先读它，这里逐档钉回中性令牌——白底 / 磨砂面上走画布承载阶梯
     悬停 --xh-bg-subtle（100）→ 按下 --xh-bg-subtle-hover（200）；聚焦档 -bg-focus / -fg-focus 两槽
     桥到配方的 focus-visible 面，缺省透明底 + 静息字色吃库环 */
  [data-scope='popconfirm'][data-part='cancel-trigger'] {
    --xh-action-bg-rest: var(--xh-popconfirm-cancel-bg, transparent);
    --xh-action-bg-hover: var(--xh-popconfirm-cancel-bg-hover, var(--xh-bg-subtle));
    --xh-action-bg-pressed: var(--xh-popconfirm-cancel-bg-active, var(--xh-bg-subtle-hover));
    --xh-action-bg-focus-visible: var(--xh-popconfirm-cancel-bg-focus, var(--xh-popconfirm-cancel-bg, transparent));
    --xh-action-fg-rest: var(--xh-popconfirm-cancel-fg, var(--xh-fg-default));
    --xh-action-fg-hover: var(--xh-popconfirm-cancel-fg, var(--xh-fg-default));
    --xh-action-fg-pressed: var(--xh-popconfirm-cancel-fg, var(--xh-fg-default));
    --xh-action-fg-focus-visible: var(--xh-popconfirm-cancel-fg-focus, var(--xh-popconfirm-cancel-fg, var(--xh-fg-default)));
    --xh-action-border-rest: var(--xh-popconfirm-cancel-border, var(--xh-border-control));
    --xh-action-border-hover: var(--xh-popconfirm-cancel-border-hover, var(--xh-border-control-hover));
    --xh-action-border-pressed: var(--xh-popconfirm-cancel-border-hover, var(--xh-border-control-hover));
    --xh-action-border-focus-visible: var(--xh-popconfirm-cancel-border, var(--xh-border-control));
  }

  /* 减少动效：圆环停下并整圈换成虚线，静止的形状仍然读得出"还没好"。
     两条规则是同一件事的两个触发条件：系统偏好与作者打的 data-motion */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='popconfirm'][data-part='confirm-trigger'][data-loading]::before {
      border-style: dotted;
      border-color: currentColor;
      animation: none;
    }
  }

  :where([data-motion='reduce']) [data-scope='popconfirm'][data-part='confirm-trigger'][data-loading]::before {
    border-style: dotted;
    border-color: currentColor;
    animation: none;
  }

  @media (forced-colors: active) {
    /* 系统色接管内容边界；装饰顶光在这一档没有额外信息。两颗按钮的强制色由家族配方给 */
    [data-scope='popconfirm'][data-part='content'] {
      background-image: none;
    }
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='popconfirm'][data-part='root'][hidden],
  [data-scope='popconfirm'][data-part='confirm-trigger'][hidden],
  [data-scope='popconfirm'][data-part='cancel-trigger'][hidden] {
    display: none;
  }

  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。 */
    [data-scope='popconfirm'][data-part='positioner'] {
      display: none;
    }
  }
}

/* styles/prompt-input.css */
/* PromptInput 独立皮肤同时传递引入字段视觉盒与字段内动作；full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='prompt-input'] {
    --xh-prompt-input-skin: 1;
  }

  /* root 就是视觉盒：描边、底色、圆角、聚焦环、悬停与禁用面由 Field Chrome 家族画在它身上（静息描边式：
     canvas 底 + --xh-border-control 描边 + 无影，不用 soft，登记的例外只在 8px surface 圆角），内部 textarea
     无边框；align-items: flex-end 让按钮随输入框长高贴着底边。
     三个视觉轴都落在 root 上：形态三档由家族按 data-variant 生成，语气管用哪族颜色，尺寸管高度与字号 */
  [data-scope='prompt-input'][data-part='root'] {
    /* 圆角可由使用者槽切换，家族只过渡底、描边、影与环 */
    transition: border-radius var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
    /* 尺寸缺省档：不写 data-size 时按中档走 */
    --xh-_prompt-input-h: var(--xh-control-h-md);
    --xh-_prompt-input-gap: var(--xh-control-gap-md);
    --xh-_prompt-input-px: var(--xh-control-px-sm);
    --xh-_prompt-input-font-size: var(--xh-control-font-md);
    --xh-_prompt-input-submit-px: var(--xh-control-px-md);
    /* 皮肤画的兜底字形与作者塞进来的图标读同一把尺，随尺寸档一起换 */
    --xh-icon-size: var(--xh-prompt-input-icon-size, var(--xh-glyph-size-md));

    /* 家族桥接槽：既有使用者槽保留为第一参数，缺省落家族按 data-variant 生成的三档 */
    /* 多行随内容长高，盒不定高 */
    --xh-field-control-height: auto;
    /* 家族的行内内衬与下面 padding 简写同值 */
    --xh-field-control-padding-inline: var(--xh-prompt-input-p, var(--xh-_prompt-input-px));
    --xh-field-control-gap: var(--xh-prompt-input-gap, var(--xh-_prompt-input-gap));
    --xh-field-control-radius: var(--xh-prompt-input-radius, var(--xh-shape-surface));
    --xh-field-bg-rest: var(--xh-prompt-input-bg, var(--xh-_field-variant-bg-rest));
    --xh-field-bg-hover: var(--xh-prompt-input-bg-hover, var(--xh-_field-variant-bg-hover));
    --xh-field-bg-disabled: var(--xh-prompt-input-bg-disabled, var(--xh-_field-variant-bg-disabled));
    --xh-field-border-rest: var(--xh-prompt-input-border, var(--xh-_field-variant-border-rest));
    --xh-field-border-hover: var(--xh-prompt-input-border-hover, var(--xh-_field-variant-border-hover));
    --xh-field-border-focus: var(--xh-prompt-input-border-focus, var(--xh-_field-variant-border-focus));
    --xh-field-shadow-rest: var(--xh-prompt-input-shadow, none);
    /* 家族 chrome 会重写 --xh-icon-size，使用者图标槽必须经桥接槽下发才能在盒内生效 */
    --xh-field-glyph-size: var(--xh-prompt-input-icon-size, var(--xh-_field-size-glyph-size));
    /* 生成中（data-loading）这块框仍可打字：不压前景、不换等待光标，只有按钮换成停止身份 */
    --xh-field-fg-loading: var(--xh-fg-default);
    --xh-field-cursor-loading: text;

    /* 整框内衬的当前值，随尺寸档与 --xh-prompt-input-p 一起变。
       附件条与动作行由作者写在 root 里、不是本组件的部件，它们靠读这一支对齐同一条内衬线 */
    --xh-prompt-input-computed-px: var(--xh-prompt-input-p, var(--xh-_prompt-input-px));

    display: flex;
    align-items: flex-end;
    /* 整框的内衬走控件内边距尺的小档，密度收紧时随之收窄 */
    padding: var(--xh-prompt-input-p, var(--xh-_prompt-input-px));
  }

  /* 上面声明的 display 会盖掉 UA 的 [hidden]{display:none}，这里补回 */
  [data-scope='prompt-input'][data-part='root'][hidden] {
    display: none;
  }

  /* 写了输入行，root 就翻成竖排：输入框与按钮收进那一行，上下两侧腾给附件条与动作行。
     不写就是单行，输入框与按钮并排——两种写法的皮肤是同一份 */
  [data-scope='prompt-input'][data-part='root']:has(> [data-scope='prompt-input'][data-part='control']) {
    flex-direction: column;
    align-items: stretch;
  }

  /* —— 尺寸 —— */
  [data-scope='prompt-input'][data-part='root'][data-size='sm'] {
    --xh-_prompt-input-h: var(--xh-control-h-sm);
    --xh-_prompt-input-gap: var(--xh-control-gap-sm);
    --xh-_prompt-input-px: var(--xh-control-px-sm);
    --xh-_prompt-input-font-size: var(--xh-control-font-sm);
    --xh-_prompt-input-submit-px: var(--xh-control-px-sm);
    --xh-icon-size: var(--xh-prompt-input-icon-size, var(--xh-glyph-size-sm));
  }

  [data-scope='prompt-input'][data-part='root'][data-size='md'] {
    --xh-_prompt-input-h: var(--xh-control-h-md);
    --xh-_prompt-input-gap: var(--xh-control-gap-md);
    --xh-_prompt-input-px: var(--xh-control-px-md);
    --xh-_prompt-input-font-size: var(--xh-control-font-md);
    --xh-_prompt-input-submit-px: var(--xh-control-px-md);
    --xh-icon-size: var(--xh-prompt-input-icon-size, var(--xh-glyph-size-md));
  }

  [data-scope='prompt-input'][data-part='root'][data-size='lg'] {
    --xh-_prompt-input-h: var(--xh-control-h-lg);
    --xh-_prompt-input-gap: var(--xh-control-gap-lg);
    --xh-_prompt-input-px: var(--xh-control-px-lg);
    --xh-_prompt-input-font-size: var(--xh-control-font-lg);
    --xh-_prompt-input-submit-px: var(--xh-control-px-lg);
    --xh-icon-size: var(--xh-prompt-input-icon-size, var(--xh-glyph-size-lg));
  }

  /* 输入行承接单行写法下落在 root 上的那份几何：输入框与按钮并排、按钮贴着底边。
     它自己不画底也不画描边，边界仍由 root 表达 */
  [data-scope='prompt-input'][data-part='control'] {
    display: flex;
    align-items: flex-end;
    gap: var(--xh-prompt-input-row-gap, var(--xh-_prompt-input-gap));
  }

  [data-scope='prompt-input'][data-part='control'][hidden] {
    display: none;
  }

  /* 输入段透明、底由外框承担：重置、字色、占位符与自动填充由 Field Chrome 家族的 [data-xh-field-input] 给，
     组件只映射既有使用者槽。刻意不投影 data-xh-field-layout：家族 textarea 布局的 :has() 变体会压掉
     root 自己的 padding 与 align-items。 */
  [data-scope='prompt-input'][data-part='input'] {
    --xh-field-input-fg: var(--xh-prompt-input-input-fg, var(--xh-fg-default));
    --xh-field-input-font-size: var(--xh-prompt-input-input-font-size, var(--xh-_prompt-input-font-size));
    --xh-field-placeholder-fg: var(--xh-prompt-input-placeholder-fg, var(--xh-fg-subtle));
    /* 框的底画在 root 上，input 本身是透明分段，自动填充铺的是外框缺省那一档的实体底 */
    --xh-field-autofill-bg: var(--xh-prompt-input-input-autofill-bg, var(--xh-bg-canvas));
    --xh-field-autofill-fg: var(--xh-prompt-input-input-autofill-fg, var(--xh-fg-default));

    /* 多行随内容长高，不撑满外框 */
    block-size: auto;
    /* 上下留白把单行文本盒撑到控件高度，文字中线与按钮中线对齐。
       级联兜底：先写一行的高度算式（输入框字号 × 行距），再写 1lh。
       1lh 晚于本库声明的浏览器地板，取不到时旧引擎丢掉后一条、留下前一条。
       两条取的是同一组槽——字号来自家族映射的 --xh-field-input-font-size、行距来自家族的
       line-height，所以算出来是同一个数。 */
    padding-block: calc((var(--xh-_prompt-input-h) - var(--xh-prompt-input-input-font-size, var(--xh-_prompt-input-font-size)) * var(--xh-leading-normal)) / 2);
    padding-block: calc((var(--xh-_prompt-input-h) - 1lh) / 2);
    border-radius: var(--xh-prompt-input-input-radius, var(--xh-shape-inset));
    /* 高度由 field-sizing 随内容变，不支持的引擎退化为 rows 定下的固定行数；
       配套禁用 resize，避免拖拽写死的高度盖掉它。封顶行数由使用者覆盖槽给。 */
    max-block-size: var(--xh-prompt-input-max-h, calc(var(--xh-leading-normal) * 1em * 8));
    field-sizing: content;
    resize: none;
  }

  /* textarea 是单体表单控件，禁用走原生 disabled */
  [data-scope='prompt-input'][data-part='input']:disabled {
    color: var(--xh-fg-disabled);
  }

  /* 发送钮是组件的主要动作，与 Button 缺省同为品牌实心：盒几何、悬停 / 按下与 0.97 按压、焦点环、禁用面
     全由 Action Control 的 text solid 档给（连接层按 loading 切成 subtle 的停止身份），组件只映射既有使用者槽。
     取 text 档而不是 icon 档：icon 档把行内尺寸钉成正方，作者放文案（「发送」）会被挤；发送钮的几何本来就是
     「至少一个控件高的方钮 + 行内内衬」，与 text 档一致 */
  [data-scope='prompt-input'][data-part='submit-trigger'] {
    --xh-action-visual-size: var(--xh-_prompt-input-h);
    --xh-action-min-inline-size: var(--xh-_prompt-input-h);
    --xh-action-padding-inline: var(--xh-prompt-input-submit-px, var(--xh-_prompt-input-submit-px));
    --xh-action-radius: var(--xh-prompt-input-submit-radius, var(--xh-shape-control));
    --xh-action-bg-rest: var(--xh-prompt-input-send-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-prompt-input-send-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-prompt-input-send-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-prompt-input-send-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-prompt-input-send-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-prompt-input-send-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-border-rest: transparent;
    --xh-action-highlight-rest: transparent;
    /* 发送身份是实心底，顶边画一条极浅的内高光把这块面衬出厚度；三态同一支，禁用面由家族收掉 */
    --xh-action-shadow-rest: var(--xh-prompt-input-submit-shadow, var(--xh-_highlight-tone));
    --xh-action-shadow-hover: var(--xh-prompt-input-submit-shadow, var(--xh-_highlight-tone));
    --xh-action-shadow-pressed: var(--xh-prompt-input-submit-shadow, var(--xh-_highlight-tone));
    /* 输入为空时按钮转灰但不收起 */
    --xh-action-bg-disabled: var(--xh-prompt-input-send-bg-off, var(--xh-bg-muted));
    --xh-action-font-size: var(--xh-prompt-input-submit-font-size, var(--xh-text-label-size));
    /* 面是实心的，环色与面同族，画在面里就看不出来；环改取面自己的前景色——
       那一族色本来就要在这块面上把字读清楚，与面的对比是按可读性定的 */
    --xh-action-ring-color-focus-visible: currentColor;

    /* 按钮不参与弹性伸缩 */
    flex: none;
    border-width: 0;
    font-weight: var(--xh-prompt-input-submit-font-weight, var(--xh-text-label-weight));
  }

  /* 家族那条 display 会把 UA 的 [hidden]{display:none} 盖掉 */
  [data-scope='prompt-input'][data-part='submit-trigger'][hidden] {
    display: none;
  }

  /* 停止身份只换配色，从主色降到中性淡底（连接层同时把家族档切成 subtle）；文案与可访问名由连接层切换。
     淡底面上没有厚度可言，内高光收掉；环色回到公共焦点色 */
  [data-scope='prompt-input'][data-part='submit-trigger'][data-mode='stop'] {
    --xh-action-bg-rest: var(--xh-prompt-input-stop-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-prompt-input-stop-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-prompt-input-stop-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-prompt-input-stop-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-prompt-input-stop-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-prompt-input-stop-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    --xh-action-ring-color-focus-visible: var(--xh-ring-focus);
  }

  /* 按钮没写内容就由皮肤画兜底字形，两种身份各画一枚；
     作者往部件里塞了自己的图形或文案，这两条即不命中 */
  [data-scope='prompt-input'][data-part='submit-trigger'][data-mode='send']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-arrow-up) center / contain no-repeat;
    mask: var(--xh-glyph-mark-arrow-up) center / contain no-repeat;
  }

  /* 停止身份画一枚实心圆角方块：它不是「反过来的发送」，用一个不指向任何方向的形状 */
  [data-scope='prompt-input'][data-part='submit-trigger'][data-mode='stop']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-prompt-input-stop-mark-size, calc(var(--xh-icon-size, var(--xh-glyph-size-text)) * 0.6));
    block-size: var(--xh-prompt-input-stop-mark-size, calc(var(--xh-icon-size, var(--xh-glyph-size-text)) * 0.6));
    vertical-align: var(--xh-glyph-baseline-shift);
    border-radius: var(--xh-prompt-input-stop-mark-radius, var(--xh-shape-inset));
    background-color: currentColor;
  }
}

/* styles/reset.css */
/*
 * 库自己的基线，只作用于带 data-scope 的库节点，不碰宿主页面的任何元素。
 *
 * 层序上 xihan.reset 在 xihan.components 之前，所以组件皮肤里的任何显式声明都盖得住这里。
 *
 * 本层全部选择器（剥去伪元素）特指度为 (0,0,0)：一律以 :where() 包住。无层产物
 * index.unlayered.css 里没有层序可依，只按特指度竞争，而 Family Recipe 的根规则
 * （[data-xh-action-control] 一类，(0,1,0)）在产物里排在本文件之前——本层若同为 (0,1,0)，
 * 靠源序就把配方的三档字号压掉。压到 (0,0,0) 后，无层产物里任何皮肤与配方规则都压得住它；
 * 代价是无层模式下宿主的元素选择器 (0,0,1) 也压得过，写在文档站「皮肤与样式分层」。
 */
@layer xihan.reset {
  /* 尺寸一律含边框：皮肤里的宽高都是照可见盒子写的。 */
  :where([data-scope]) {
    box-sizing: border-box;
  }

  /* 伪元素自身带 (0,0,1)，无法再低；:where() 只压掉宿主那一截。 */
  :where([data-scope])::before,
  :where([data-scope])::after {
    box-sizing: border-box;
  }

  /*
   * UA 样式会把表单控件的字体锁成系统默认，不跟随页面。
   * 这几个元素是 UA 唯一强制字体的地方，标题一类不在其中，故不做全局 font: inherit。
   */
  :where([data-scope]):where(button, input, optgroup, select, textarea) {
    font: inherit;
    letter-spacing: inherit;
  }

  /*
   * 浮层定位层的生命周期契约：落位才露。
   *
   * 坐标依赖浮层自己的尺寸，尺寸要等元素进 DOM 参与排版才量得到，所以浮层一定先渲染、
   * 再量、再定位——展开的那几帧坐标还是兜底的 0。默认藏着，连接层算出坐标后打
   * data-positioned 才显示，忘了接线的新浮层只会不显示，不会先在视口左上角闪一帧。
   * 用 visibility 而不是 display：display:none 会让浮层退出排版，引擎量不到它的尺寸。
   * 锚点被滚出可视区时引擎置 hidden，各皮肤另有一条 [data-hidden] 压回去。
   */
  :where([data-scope][data-part='positioner']) {
    visibility: hidden;
  }

  :where([data-scope][data-part='positioner'][data-positioned]) {
    visibility: visible;
  }

  /*
   * 库内原生滚动面与作者容器共用的细条。
   *
   * 两档滚动面里的「原生细条」档：页内结构容器（Table、Tree、Virtualizer viewport、
   * Dialog / Drawer body、Log 视口一类）不接自绘条，靠这里把原生条统一成 thin + 令牌色阶。
   * 三个入口：库节点（[data-scope][data-part]）、作者自建滚动容器与文档示例（[data-xh-scroll]）、
   * Typography prose 里的 <pre>——它是库内唯一不带 data-part 的滚动面，作者只写 <pre> 不写角色。
   * 皮肤不得再手写 scrollbar-width / scrollbar-color（stylelint 判红），要藏条写 none。
   * 这里不写 scrollbar-gutter：auto 是初始值，stable 只给内容高度会变的容器由皮肤显式写。
   * ::-webkit-scrollbar-thumb 的圆角取 pill：原生滑块与自绘 scrollbar:thumb 同为一维对象，
   * 不再按厚度折半凑半圆，三档厚度都是同一身份。
   *
   * 令牌住在 xihan.tokens 层、排在本层之后，但自定义属性的求值不受层序影响：
   * var() 在计算值阶段沿元素树取值，层序只裁决同一属性的两条声明谁赢。
   * [data-xh-scrollbar] 的 scrollbar-width: none 是 (0,1,0)，有层与无层两种产物里都压得住本条；
   * ::-webkit-scrollbar 伪元素自带 (0,0,1)，ScrollArea 那条 display: none 同样压得住。
   */
  :where([data-scope][data-part], [data-xh-scroll], [data-scope='typography'][data-part='prose'] pre) {
    scrollbar-width: thin;
    scrollbar-color: var(--xh-fg-scrollbar-thumb) var(--xh-bg-scrollbar-track);
  }

  :where([data-scope][data-part], [data-xh-scroll], [data-scope='typography'][data-part='prose'] pre)::-webkit-scrollbar {
    width: var(--xh-scrollbar-thickness-md);
    height: var(--xh-scrollbar-thickness-md);
  }

  :where([data-scope][data-part], [data-xh-scroll], [data-scope='typography'][data-part='prose'] pre)::-webkit-scrollbar-track {
    background: var(--xh-bg-scrollbar-track);
  }

  :where([data-scope][data-part], [data-xh-scroll], [data-scope='typography'][data-part='prose'] pre)::-webkit-scrollbar-thumb {
    border-radius: var(--xh-shape-pill);
    background: var(--xh-fg-scrollbar-thumb);
  }

  :where([data-scope][data-part], [data-xh-scroll], [data-scope='typography'][data-part='prose'] pre)::-webkit-scrollbar-thumb:hover {
    background: var(--xh-fg-scrollbar-thumb-hover);
  }

  :where([data-scope][data-part], [data-xh-scroll], [data-scope='typography'][data-part='prose'] pre)::-webkit-scrollbar-thumb:active {
    background: var(--xh-fg-scrollbar-thumb-active);
  }

  /*
   * 选区高亮的底与字。不写这条时用的是 UA 的系统高亮色（多数是系统蓝底白字）：
   * 它不跟主题走，深色档下这块蓝会横在面板上，选中的文字反而比没选中时更难认。
   *
   * 后代那条不是冗余。高亮样式虽然会沿元素树往下继承，但「直接命中该元素的声明」
   * 永远压过继承来的值：宿主页面自己写一条通配的 ::selection，它直接命中我们子树里
   * 的每一个后代元素——只写第一条时，库节点自己的裸文本是我们的色，里面每个 <span>
   * 却回退成宿主的色，一段文字选出两种底。两条一起写，整棵子树才是同一个色。
   * 两条都以 [data-scope] 起手，着色止于库子树，宿主页面自己的选区不受影响。
   *
   * 只写这两个属性：高亮伪元素能吃的属性极窄，box-shadow / border 一类多数引擎
   * 直接丢弃，不报错也不生效，写了只会让人以为已经处理过。
   */
  :where([data-scope])::selection,
  :where([data-scope]) *::selection {
    background: var(--xh-bg-brand-subtle);
    color: var(--xh-fg-default);
  }
}

/* styles/reasoning.css */
/* 定义 reasoning 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立；
   独立皮肤同时传递引入开关的动作控件配方，full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='reasoning'] {
    --xh-reasoning-skin: 1;
  }

  /* 一张淡底面：--xh-bg-subtle 底 + 透明边位 + 无影（subtle 无影），描边留给 outline 档打开。
     缺省淡底承载开关：向它下发 hover 200 → pressed 300 的阶梯，白底档在形态规则里改回 100 → 200 */
  [data-scope='reasoning'][data-part='root'] {
    --xh-action-host-bg-hover: var(--xh-bg-subtle-hover);
    --xh-action-host-bg-pressed: var(--xh-bg-subtle-active);

    /* 作者塞进两个图形位的图标与皮肤画的兜底字形同一把尺：按档取，与开关的家族档同步——
       不写 data-size 时字号是 sm 档，字形随之取 sm */
    --xh-_reasoning-icon-size: var(--xh-glyph-size-sm);
    --xh-icon-size: var(--xh-reasoning-icon-size, var(--xh-_reasoning-icon-size));

    /* 影另落一份进私有槽给语气档：它要把影与左侧色条叠成一条 box-shadow，缺省无影写成零影占位 */
    --xh-_reasoning-shadow: var(--xh-reasoning-shadow, 0 0 0 transparent);

    /* 尺寸缺省档：不写 data-size 时的取值。三档都只写这三个私有槽，
       公开槽留在读处当首选，作者在祖先上设的覆盖才赢得过档位声明 */
    --xh-_reasoning-px: var(--xh-space-3);
    --xh-_reasoning-py: var(--xh-space-2);
    --xh-_reasoning-font-size: var(--xh-control-font-sm);

    display: block;
    overflow: hidden;
    border: var(--xh-stroke-thin) solid transparent;
    border-radius: var(--xh-reasoning-radius, var(--xh-shape-surface));
    background: var(--xh-reasoning-bg, var(--xh-bg-subtle));
    box-shadow: var(--xh-reasoning-shadow, none);
  }

  /* 上面声明的 display 会盖掉 UA 的 [hidden]{display:none}，这里补回 */
  [data-scope='reasoning'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 形态 —— */
  /* 缺省档即 subtle，写在上面那条基础规则里 */
  /* 描边分区：--xh-border-default 描边 + surface 底（静态内容面）；
     白底承载面把开关的阶梯改回 hover 100 → pressed 200 */
  [data-scope='reasoning'][data-part='root'][data-variant='outline'] {
    --xh-action-host-bg-hover: var(--xh-bg-subtle);
    --xh-action-host-bg-pressed: var(--xh-bg-subtle-hover);

    border: var(--xh-stroke-thin) solid var(--xh-reasoning-border, var(--xh-border-default));
    background: var(--xh-reasoning-bg, var(--xh-bg-surface));
  }

  /* 无壳内联：思考过程贴着正文走，不占一块面；开关落在正文的白底上，阶梯同 outline 档 */
  [data-scope='reasoning'][data-part='root'][data-variant='ghost'] {
    --xh-action-host-bg-hover: var(--xh-bg-subtle);
    --xh-action-host-bg-pressed: var(--xh-bg-subtle-hover);

    overflow: visible;
    background: none;
    box-shadow: none;
  }

  /* 无壳档的开关只占文字宽度（盖掉 profile 的铺满一行），自己带圆角，悬停时才浮出一块底 */
  [data-scope='reasoning'][data-part='root'][data-variant='ghost'] [data-scope='reasoning'][data-part='trigger'] {
    --xh-action-radius: var(--xh-reasoning-trigger-radius, var(--xh-shape-control));

    inline-size: auto;
  }

  /* 开关铺满一行，盒型、悬停 / 按下 / 禁用面由 Action Control 的 disclosure-trigger 档给（ghost 形态，
     阶梯由根按承载面经 host 槽下发，按下只换面不缩放）；这里只把使用者槽映射到桥接槽：
     圆角归零贴住面边，内衬与字号沿用本组件的档位（不取 profile 的内衬，几何不变），字色三态都停在
     弱一档的 muted（开关不是正文）；字形尺由根按同一档位给 */
  [data-scope='reasoning'][data-part='trigger'] {
    --xh-action-radius: 0;
    --xh-action-gap: var(--xh-reasoning-trigger-gap, var(--xh-space-2));
    --xh-action-padding-inline: var(--xh-reasoning-px, var(--xh-_reasoning-px));
    --xh-action-padding-block: var(--xh-reasoning-py, var(--xh-_reasoning-py));
    --xh-action-font-size: var(--xh-reasoning-font-size, var(--xh-_reasoning-font-size));
    --xh-action-fg-rest: var(--xh-reasoning-trigger-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-reasoning-trigger-fg, var(--xh-fg-muted));
    --xh-action-fg-pressed: var(--xh-reasoning-trigger-fg, var(--xh-fg-muted));
    --xh-action-bg-hover: var(--xh-reasoning-trigger-bg-hover, var(--xh-_action-variant-bg-hover));

    border-width: 0;
  }

  [data-scope='reasoning'][data-part='trigger'][hidden] {
    display: none;
  }

  /* 状态图形位：在想的时候实一档，想完退回弱一档 */
  [data-scope='reasoning'][data-part='icon'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    color: var(--xh-reasoning-icon-fg, var(--xh-fg-subtle));
    transition: color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='reasoning'][data-part='icon'][data-streaming] {
    color: var(--xh-reasoning-icon-streaming-fg, var(--xh-fg-muted));
  }

  [data-scope='reasoning'][data-part='icon'][hidden] {
    display: none;
  }

  /* 指示随开合转向，纯装饰。转向与正文开合取同一档时长，两件事一起收尾：收起取 collapse 档，展开取 expand 档 */
  [data-scope='reasoning'][data-part='indicator'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    color: var(--xh-reasoning-indicator-fg, var(--xh-fg-subtle));
    transition: rotate var(--xh-motion-duration-collapse) var(--xh-motion-ease-enter-strong);
  }

  /* 没写内容就由皮肤画；作者往部件里塞了自己的图形，这条规则即不命中 */
  [data-scope='reasoning'][data-part='indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
  }

  [data-scope='reasoning'][data-part='indicator'][data-state='open'] {
    rotate: 180deg;
    transition: rotate var(--xh-motion-duration-expand) var(--xh-motion-ease-enter-strong);
  }

  [data-scope='reasoning'][data-part='indicator'][hidden] {
    display: none;
  }

  /* 状态文案排成一行，长了截断：换行会把开关的高度顶开，时长位跟着跳 */
  [data-scope='reasoning'][data-part='label'] {
    display: block;
    flex: 1 1 auto;
    overflow: hidden;
    font-weight: var(--xh-reasoning-label-font-weight, var(--xh-text-label-weight));
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  [data-scope='reasoning'][data-part='label'][hidden] {
    display: none;
  }

  /* 还在想：一道亮带在文字上从右往左扫，字色由这层渐变裁出来 */
  [data-scope='reasoning'][data-part='label'][data-streaming] {
    background-image: linear-gradient(
      90deg,
      var(--xh-reasoning-shimmer-from, var(--xh-fg-subtle)) 35%,
      var(--xh-reasoning-shimmer-to, var(--xh-fg-default)) 50%,
      var(--xh-reasoning-shimmer-from, var(--xh-fg-subtle)) 65%
    );
    background-size: 200% 100%;
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    animation: xh-shimmer var(--xh-reasoning-shimmer-duration, var(--xh-shimmer-duration)) var(--xh-motion-ease-loop) infinite;
  }

  /*
   * 减少动效：撤掉扫光那层，换成一档更实的静态字色。
   * 这里不能只把时长压到接近零——光带会停在某一帧上，在文字上留下一道说不清的渐变；
   * 而撤掉渐变又不还字色的话，被裁成透明的文字会整句消失。
   * 两条规则是同一件事的两个触发条件：系统偏好与作者打的 data-motion。
   */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='reasoning'][data-part='label'][data-streaming] {
      background-image: none;
      -webkit-background-clip: border-box;
      background-clip: border-box;
      color: var(--xh-reasoning-label-streaming-fg, var(--xh-fg-default));
      animation: none;
    }
  }

  :where([data-motion='reduce']) [data-scope='reasoning'][data-part='label'][data-streaming] {
    background-image: none;
    -webkit-background-clip: border-box;
    background-clip: border-box;
    color: var(--xh-reasoning-label-streaming-fg, var(--xh-fg-default));
    animation: none;
  }

  [data-scope='reasoning'][data-part='duration'] {
    display: block;
    flex: none;
    color: var(--xh-reasoning-duration-fg, var(--xh-fg-subtle));
    font-size: var(--xh-reasoning-duration-font-size, var(--xh-text-caption-size));
    font-variant-numeric: tabular-nums;
  }

  [data-scope='reasoning'][data-part='duration'][hidden] {
    display: none;
  }

  /* 想完那一下两句文案整句换掉，淡入接住这次替换 */
  [data-scope='reasoning'][data-part='label']:not([data-streaming]),
  [data-scope='reasoning'][data-part='duration']:not([data-streaming]) {
    animation: xh-fade-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong) both;
  }

  /*
   * 思考正文是散文：段落排版，不用等宽，行距比正文松一档。
   * 左侧一条轨迹线把这一段与开关分开，起点对齐开关里的图形位。
   *
   * 这里刻意没有 [data-part='content'][hidden] { display: none }：补了动画一帧都播不出来。
   * 收起由适配器在退场结束后写内联 display 落成，退场窗口内靠 connect 发的 inert 挡住焦点。
   */
  [data-scope='reasoning'][data-part='content'] {
    /* 行高与内缩同帧动的共享关键帧读这条槽：只有末端有内缩，起端不写、按 0 动 */
    --xh-_disclosure-pb: var(--xh-reasoning-py, var(--xh-_reasoning-py));

    display: grid;
    grid-template-rows: 1fr;
    overflow: clip;
    margin-inline-start: var(--xh-reasoning-rail-inset, var(--xh-reasoning-px, var(--xh-_reasoning-px)));
    border-inline-start: var(--xh-reasoning-rail-width, var(--xh-stroke-thin)) solid var(--xh-reasoning-rail, var(--xh-border-subtle));
    padding-inline-start: var(--xh-reasoning-content-ps, var(--xh-space-3));
    padding-inline-end: var(--xh-reasoning-content-pe, var(--xh-reasoning-px, var(--xh-_reasoning-px)));
    padding-block-end: var(--xh-reasoning-py, var(--xh-_reasoning-py));
    color: var(--xh-reasoning-content-fg, var(--xh-fg-muted));
    font-size: var(--xh-reasoning-content-font-size, var(--xh-text-secondary-size));
    line-height: var(--xh-reasoning-content-leading, var(--xh-text-prose-leading));
  }

  /* 展开那一档才提前备好行高这条通道：属性随 data-state 一起消失，收起后不长期占着 */
  [data-scope='reasoning'][data-part='content'][data-state='open'] {
    will-change: grid-template-rows;
    animation: xh-disclosure-expand var(--xh-motion-duration-expand) var(--xh-motion-ease-enter-strong);
  }

  [data-scope='reasoning'][data-part='content'][data-state='closed'] {
    animation: xh-disclosure-collapse var(--xh-motion-duration-collapse) var(--xh-motion-ease-exit) forwards;
  }

  /* 尺寸档改内衬、字号与图标档 */
  [data-scope='reasoning'][data-part='root'][data-size='sm'] {
    --xh-_reasoning-icon-size: var(--xh-glyph-size-sm);
    --xh-_reasoning-px: var(--xh-space-2);
    --xh-_reasoning-py: var(--xh-space-1);
    --xh-_reasoning-font-size: var(--xh-control-font-sm);
  }

  [data-scope='reasoning'][data-part='root'][data-size='md'] {
    --xh-_reasoning-icon-size: var(--xh-glyph-size-md);
    --xh-_reasoning-px: var(--xh-space-3);
    --xh-_reasoning-py: var(--xh-space-2);
    --xh-_reasoning-font-size: var(--xh-control-font-md);
  }

  [data-scope='reasoning'][data-part='root'][data-size='lg'] {
    --xh-_reasoning-icon-size: var(--xh-glyph-size-lg);
    --xh-_reasoning-px: var(--xh-space-4);
    --xh-_reasoning-py: var(--xh-space-3);
    --xh-_reasoning-font-size: var(--xh-control-font-lg);
  }

  /* 语气只染左侧那一条色条，海拔跟着一起落在同一条 box-shadow 上 */
  [data-scope='reasoning'][data-part='root'][data-tone] {
    box-shadow:
      inset var(--xh-reasoning-tone-bar, var(--xh-stroke-thick)) 0 0 0 var(--xh-reasoning-tone-fg, var(--xh-_tone-soft, var(--xh-bg-brand))),
      var(--xh-_reasoning-shadow);
  }
}

@layer xihan.motion {
  @media print {
    /* 打印：动画会被定格在任意一帧——转了一半的圈、扫到一半的微光。这里换成静止的表达，
       取值与减弱动效那一档相同。两档各写一块、不并进一条媒体查询列表：减弱动效另有一份
       :where([data-motion='reduce']) 的钩子版本与它成对，打印没有对应的钩子可配，
       并成一条之后这层配对关系在文本上就断了。 */
    [data-scope='reasoning'][data-part='label'][data-streaming] {
      background-image: none;
      -webkit-background-clip: border-box;
      background-clip: border-box;
      color: var(--xh-reasoning-label-streaming-fg, var(--xh-fg-default));
      animation: none;
    }
  }

  /*
   * 高对比档：扫光那层渐变被丢弃，只剩被裁成透明的文字，整行标题消失。
   * 把填充还回去，在想这件事仍由标题文字本身与展开钮的状态表出。
   */
  @media (forced-colors: active) {
    [data-scope='reasoning'][data-part='label'][data-streaming] {
      background-image: none;
      -webkit-background-clip: border-box;
      background-clip: border-box;
      color: CanvasText;
      animation: none;
    }
  }
}

/* styles/resizable.css */
/* 定义 resizable 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='resizable'] {
    --xh-resizable-skin: 1;
  }

  /* 分工：**尺寸与位移**由连接层每帧写进内联样式（inline-size / block-size / left / top）。
     这份皮肤一条都不碰那四个——内联优先级更高，写了不但是死声明，
     还会在拖动的每一帧跟连接层抢位置。皮肤只管定位上下文、把手落位与状态表现。 */

  /* 定位上下文，八向可调靠它才成立：
     推西边与北边时容器的起点会动，那段位移写成 left / top。relative 的 left / top
     是视觉位移、元素仍占原位，因此对边钉得住。改成 static 会让这两个方向只变尺寸不移位。 */
  [data-scope='resizable'][data-part='root'] {
    position: relative;
    /* 把层序关在容器里：把手的 1 / 2 只跟彼此比，不跟外面的层号打架 */
    isolation: isolate;
    box-sizing: border-box;
  }

  /* 调整期间关掉选中：把手一按就会把容器里的文字刷成选中态 */
  [data-scope='resizable'][data-part='root'][data-resizing] {
    user-select: none;
  }

  /* 这里的 data-disabled 关掉的是「能不能调尺寸」，容器里作者的内容照常可用：
     光标交回给作者，不摆共享层那个「不可用」的样子 */
  [data-scope='resizable'][data-part='root'][data-disabled] {
    cursor: inherit;
  }

  [data-scope='resizable'][data-part='root'][hidden] {
    display: none;
  }

  /* 把手命中区留在容器内部并覆盖对应边；视觉指示条贴住容器边框，由伪元素绘制。 */
  [data-scope='resizable'][data-part='handle'] {
    --xh-_resizable-indicator-color: var(
      --xh-resizable-handle-bg,
      color-mix(in oklab, var(--xh-fg-default) 18%, transparent)
    );

    position: absolute;
    z-index: 1;
    display: block;
    background: transparent;
    touch-action: none;
  }

  [data-scope='resizable'][data-part='handle']::after {
    content: '';
    position: absolute;
    border-radius: var(--xh-resizable-handle-radius, var(--xh-shape-pill));
    background: var(--xh-_resizable-indicator-color);
    pointer-events: none;
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      border-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='resizable'][data-part='handle']:hover {
    --xh-_resizable-indicator-color: var(
      --xh-resizable-handle-bg-hover,
      color-mix(in oklab, var(--xh-fg-default) 32%, transparent)
    );
  }

  [data-scope='resizable'][data-part='handle'][data-resizing] {
    --xh-_resizable-indicator-color: var(--xh-resizable-handle-bg-active, var(--xh-bg-brand));
  }

  [data-scope='resizable'][data-part='handle']:focus-visible {
    --xh-_resizable-indicator-color: var(--xh-ring-focus);

    outline: none;
  }

  [data-scope='resizable'][data-part='handle'][hidden] {
    display: none;
  }

  /* 四条边：各占一整条，厚度是可抓的余量 */
  [data-scope='resizable'][data-part='handle'][data-edge='n'],
  [data-scope='resizable'][data-part='handle'][data-edge='s'] {
    inset-inline: var(--xh-resizable-grip, var(--xh-space-2));
    block-size: var(--xh-resizable-grip, var(--xh-space-2));
  }

  [data-scope='resizable'][data-part='handle'][data-edge='e'],
  [data-scope='resizable'][data-part='handle'][data-edge='w'] {
    inset-block: var(--xh-resizable-grip, var(--xh-space-2));
    inline-size: var(--xh-resizable-grip, var(--xh-space-2));
  }

  /* 落位用逻辑属性：e 说的是行尾侧，从右往左排版时它就该落在屏幕左边——
     机器那边也是把逻辑边翻成物理边再算几何的，两处同源 */
  [data-scope='resizable'][data-part='handle'][data-edge='n'] {
    inset-block-start: 0;
  }

  [data-scope='resizable'][data-part='handle'][data-edge='s'] {
    inset-block-end: 0;
  }

  [data-scope='resizable'][data-part='handle'][data-edge='e'] {
    inset-inline-end: 0;
  }

  [data-scope='resizable'][data-part='handle'][data-edge='w'] {
    inset-inline-start: 0;
  }

  [data-scope='resizable'][data-part='handle']:is([data-edge='n'], [data-edge='s'])::after {
    inset-inline-start: 50%;
    inline-size: var(--xh-resizable-indicator-length, var(--xh-space-8));
    block-size: var(--xh-resizable-indicator-thickness, var(--xh-stroke-strong));
    translate: -50% 0;
  }

  [data-scope='resizable'][data-part='handle'][data-edge='n']::after {
    inset-block-start: var(--xh-resizable-indicator-inset, 0);
  }

  [data-scope='resizable'][data-part='handle'][data-edge='s']::after {
    inset-block-end: var(--xh-resizable-indicator-inset, 0);
  }

  [data-scope='resizable'][data-part='handle']:is([data-edge='e'], [data-edge='w'])::after {
    inset-block-start: 50%;
    inline-size: var(--xh-resizable-indicator-thickness, var(--xh-stroke-strong));
    block-size: var(--xh-resizable-indicator-length, var(--xh-space-8));
    translate: 0 -50%;
  }

  [data-scope='resizable'][data-part='handle'][data-edge='e']::after {
    inset-inline-end: var(--xh-resizable-indicator-inset, 0);
  }

  [data-scope='resizable'][data-part='handle'][data-edge='w']::after {
    inset-inline-start: var(--xh-resizable-indicator-inset, 0);
  }

  /* 四个角：压在两条边的交点上，盖过相邻两条边（它们同时动两轴） */
  [data-scope='resizable'][data-part='handle'][data-edge='ne'],
  [data-scope='resizable'][data-part='handle'][data-edge='nw'],
  [data-scope='resizable'][data-part='handle'][data-edge='se'],
  [data-scope='resizable'][data-part='handle'][data-edge='sw'] {
    z-index: 2;
    inline-size: var(--xh-resizable-corner, var(--xh-space-4));
    block-size: var(--xh-resizable-corner, var(--xh-space-4));
  }

  [data-scope='resizable'][data-part='handle'][data-edge='nw'] {
    inset-block-start: 0;
    inset-inline-start: 0;
    border-start-start-radius: inherit;
  }

  [data-scope='resizable'][data-part='handle'][data-edge='ne'] {
    inset-block-start: 0;
    inset-inline-end: 0;
    border-start-end-radius: inherit;
  }

  [data-scope='resizable'][data-part='handle'][data-edge='sw'] {
    inset-block-end: 0;
    inset-inline-start: 0;
    border-end-start-radius: inherit;
  }

  [data-scope='resizable'][data-part='handle'][data-edge='se'] {
    inset-block-end: 0;
    inset-inline-end: 0;
    border-end-end-radius: inherit;
  }

  [data-scope='resizable'][data-part='handle']:is(
    [data-edge='ne'],
    [data-edge='nw'],
    [data-edge='se'],
    [data-edge='sw']
  )::after {
    inline-size: 50%;
    block-size: 50%;
    border: 0 solid var(--xh-_resizable-indicator-color);
    border-radius: inherit;
    background: transparent;
  }

  [data-scope='resizable'][data-part='handle'][data-edge='nw']::after {
    inset-block-start: var(--xh-resizable-corner-inset, 0);
    inset-inline-start: var(--xh-resizable-corner-inset, 0);
    border-block-start-width: var(--xh-resizable-indicator-thickness, var(--xh-stroke-strong));
    border-inline-start-width: var(--xh-resizable-indicator-thickness, var(--xh-stroke-strong));
  }

  [data-scope='resizable'][data-part='handle'][data-edge='ne']::after {
    inset-block-start: var(--xh-resizable-corner-inset, 0);
    inset-inline-end: var(--xh-resizable-corner-inset, 0);
    border-block-start-width: var(--xh-resizable-indicator-thickness, var(--xh-stroke-strong));
    border-inline-end-width: var(--xh-resizable-indicator-thickness, var(--xh-stroke-strong));
  }

  [data-scope='resizable'][data-part='handle'][data-edge='sw']::after {
    inset-block-end: var(--xh-resizable-corner-inset, 0);
    inset-inline-start: var(--xh-resizable-corner-inset, 0);
    border-block-end-width: var(--xh-resizable-indicator-thickness, var(--xh-stroke-strong));
    border-inline-start-width: var(--xh-resizable-indicator-thickness, var(--xh-stroke-strong));
  }

  [data-scope='resizable'][data-part='handle'][data-edge='se']::after {
    inset-block-end: var(--xh-resizable-corner-inset, 0);
    inset-inline-end: var(--xh-resizable-corner-inset, 0);
    border-block-end-width: var(--xh-resizable-indicator-thickness, var(--xh-stroke-strong));
    border-inline-end-width: var(--xh-resizable-indicator-thickness, var(--xh-stroke-strong));
  }

  /* 没开放的边不显示把手：留着一个抓不动的区域只会让人反复去试 */
  [data-scope='resizable'][data-part='handle'][data-disabled] {
    display: none;
  }

  @media (forced-colors: active) {
    /* 把手那两档全是底色画出来的，这一档里底色被统一换成系统底色，两档与静息塌成一个样子。
       改由描边把正在拖的那一条画出来 */
    [data-scope='resizable'][data-part='handle'][data-resizing] {
      --xh-_resizable-indicator-color: Highlight;
    }
  }
}

/* styles/segmented.css */
/* 定义 segmented 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='segmented'] {
    --xh-segmented-skin: 1;
  }

  /* 一条轨道装着若干段，指示器在轨道里滑。指示器是绝对定位的，
     root 必须是它的定位参照系；段与段之间不留缝，所以不设 gap */
  [data-scope='segmented'][data-part='root'] {
    /* 尺寸档只换这四个私有槽，段与文字从 root 继承它们，换档不必给每个部件各写一条选择器 */
    --xh-_segmented-h: var(--xh-control-h-md);
    --xh-_segmented-px: var(--xh-control-px-md);
    --xh-_segmented-gap: var(--xh-control-gap-md);
    --xh-_segmented-font-size: var(--xh-control-font-md);
    /* 指示器（有滑块开关的白色抬起面）的底、描边与选中段的文字色；没写 data-tone 时就是这里的取值 */
    --xh-_segmented-indicator-bg: var(--xh-bg-surface-raised);
    --xh-_segmented-fg-selected: var(--xh-fg-default);
    /* 轨道是淡底承载面：段坐在它上面，悬停 200 → 按下 300，host 槽向内下发同一副阶梯 */
    --xh-action-host-bg-hover: var(--xh-bg-subtle-hover);
    --xh-action-host-bg-pressed: var(--xh-bg-subtle-active);

    /* 一行排不下就折行：每个选项都必须看得见、点得到，硬撑一行会把末尾几段顶出容器。
       段各自带圆角，折行不会切角；不改成横向滚动是因为段离轨道内沿只有一格衬距，
       轨道一旦成为滚动容器，段的焦点环（画在段外侧 2px 处）会被裁掉。
       轨道是一块淡底面：--xh-bg-subtle 底 + 同宽透明占位边 + 无影，边界由滑块的描边与轨道底色的落差承担 */
    position: relative;
    display: inline-flex;
    flex-wrap: wrap;
    align-items: stretch;
    padding: var(--xh-segmented-track-padding, var(--xh-space-0_5));
    border: var(--xh-stroke-thin) solid var(--xh-segmented-border, transparent);
    border-radius: var(--xh-segmented-radius, var(--xh-shape-surface));
    background: var(--xh-segmented-bg, var(--xh-bg-subtle));
    font-size: var(--xh-segmented-font-size, var(--xh-_segmented-font-size));
  }

  /* 横排时外盒整体就是一档控件高：段被 align-items: stretch 撑满轨道内侧，与同行控件齐平。
     写下限而非定值：排得下时两者逐值相同，排不下折了行才让轨道往下长 */
  [data-scope='segmented'][data-part='root'][data-orientation='horizontal'] {
    flex-direction: row;
    min-block-size: var(--xh-segmented-h, var(--xh-_segmented-h));
  }

  /* 段的高度交给轨道：一行时被 stretch 撑满轨道内侧。
     下限按「一档控件高减掉轨道上下的衬距与描边」算，折了行每一行仍是这个高度，
     不写的话多行会被 align-content 均分成一叠扁条 */
  [data-scope='segmented'][data-part='root'][data-orientation='horizontal'] [data-scope='segmented'][data-part='item'] {
    block-size: auto;
    min-block-size: calc(
      var(--xh-segmented-h, var(--xh-_segmented-h)) - 2 * var(--xh-segmented-track-padding, var(--xh-space-0_5)) - 2 *
        var(--xh-stroke-thin)
    );
  }

  [data-scope='segmented'][data-part='root'][data-orientation='vertical'] {
    flex-direction: column;
    flex-wrap: nowrap;
  }

  /* 撑满行宽：各段等分剩余空间，长短不一的文字也排得齐 */
  [data-scope='segmented'][data-part='root'][data-block] {
    display: flex;
    inline-size: 100%;
  }

  /* 等分只在横排成立：竖排的主轴是块轴，flex-basis: 0 会顶掉段自己的高度档，
     段高改由「等分容器高度」决定，三档控件高度从此对它没有作用。
     竖排下段本来就靠上面那条 inline-size: 100% 与 align-items: stretch 撑满宽度 */
  [data-scope='segmented'][data-part='root'][data-block][data-orientation='horizontal']
    > [data-scope='segmented'][data-part='item'] {
    flex: 1 1 0;
  }

  /* root 会短暂拿到 tabindex=0，但它的 onFocus 立刻把焦点转投给段，
     在它身上画环只会闪一下就跳走，高亮要长在段上 */
  [data-scope='segmented'][data-part='root']:focus-visible {
    outline: none;
  }

  [data-scope='segmented'][data-part='root'][data-invalid] {
    border-color: var(--xh-segmented-border-invalid, var(--xh-border-invalid));
  }

  [data-scope='segmented'][data-part='root'][data-disabled] {
    background: var(--xh-segmented-bg-disabled, var(--xh-bg-muted));
  }

  /* 整组禁用时指示器落回轨道平面（不再浮起），但底色一点不兑淡：
     它上面压着选中段的文字，往 muted 兑哪怕一成，brand 的对比度就从 5.08 掉到 4.24 */
  [data-scope='segmented'][data-part='root'][data-disabled]
    [data-scope='segmented'][data-part='indicator'] {
    box-shadow: var(--xh-segmented-indicator-shadow-disabled, none);
  }

  /* —— 语气 —— */
  /* 选择器带 [data-tone] 限定：不限定的话，放在语气容器里的分段控件会跟着改色 */
  [data-scope='segmented'][data-part='root'][data-tone] {
    --xh-_segmented-indicator-bg: var(--xh-_tone, var(--xh-bg-surface-raised));
    --xh-_segmented-fg-selected: var(--xh-_tone-on, var(--xh-fg-default));
  }

  /* 语气档的滑块是实心语气面，描边与底同色：raised 面必带描边，这里的描边只是把边位补齐，不另画一圈 */
  [data-scope='segmented'][data-part='root'][data-tone] [data-scope='segmented'][data-part='indicator'] {
    border-color: var(--xh-segmented-indicator-border, var(--xh-_tone, var(--xh-border-default)));
  }

  /* —— 尺寸 —— */
  /* 缺省的 md 档写在上面的基础规则里 */
  [data-scope='segmented'][data-part='root'][data-size='sm'] {
    --xh-_segmented-h: var(--xh-control-h-sm);
    --xh-_segmented-px: var(--xh-control-px-sm);
    --xh-_segmented-gap: var(--xh-control-gap-sm);
    --xh-_segmented-font-size: var(--xh-control-font-sm);
  }

  [data-scope='segmented'][data-part='root'][data-size='lg'] {
    --xh-_segmented-h: var(--xh-control-h-lg);
    --xh-_segmented-px: var(--xh-control-px-lg);
    --xh-_segmented-gap: var(--xh-control-gap-lg);
    --xh-_segmented-font-size: var(--xh-control-font-lg);
  }

  /* 段自己也定位，于是与绝对定位的指示器按文档序比高低：
     指示器写在段之前，段与它的焦点环便压在指示器上面，不必动层号 */
  [data-scope='segmented'][data-part='item'] {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--xh-segmented-item-gap, var(--xh-_segmented-gap));
    block-size: var(--xh-segmented-item-h, var(--xh-_segmented-h));
    padding-inline: var(--xh-segmented-item-px, var(--xh-_segmented-px));
    border: 0;
    border-radius: var(--xh-segmented-item-radius, var(--xh-shape-inset));
    background: transparent;
    color: var(--xh-segmented-item-fg, var(--xh-fg-muted));
    /* 按钮不继承宿主字体，尺寸档在 root 上，两者都要显式接过来 */
    font-family: inherit;
    font-size: inherit;
    font-weight: var(--xh-segmented-item-font-weight, var(--xh-text-label-weight));
    line-height: var(--xh-leading-none);
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
    /* 段是轨道里铺开的一段（Segmented item 归行级），按下只换面不缩放：transition 里没有 scale */
    transition:
      color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      background-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 选中态：单选是 role=radio + aria-checked，样式一律读 data-state，不读 ARIA。
     文字色也要跟着变——指示器是可选部件，作者不渲染它时"当前是哪一段"仍然要看得出来 */
  [data-scope='segmented'][data-part='item'][data-state='checked'] {
    color: var(--xh-segmented-item-fg-checked, var(--xh-_segmented-fg-selected));
  }

  /* 指示器在场时选中段自己透空，环紧挨着的是压在它底下、与它同一块矩形的指示器实心底；
     环色与那块底同族就看不出来，改取选中段自己的前景色——那一支本来就配着这块底定的。
     指示器是可选部件，作者没渲染它时选中段直接坐在轨道底上，那一档的环仍取默认那一支 */
  [data-scope='segmented'][data-part='root']:has([data-scope='segmented'][data-part='indicator']:not([hidden]))
    [data-scope='segmented'][data-part='item'][data-state='checked']:focus-visible {
    --xh-_ring-color: currentColor;
  }

  /* 悬停只提亮未选中的那几段：选中段的底下压着指示器，再变色就成了两套强调。
     底色用中性的悬停档——它是「指哪一段」的轻反馈，不表达选中；段坐在淡底轨道里，悬停取 200 */
  [data-scope='segmented'][data-part='item']:not([data-disabled]):not([data-state='checked']):hover {
    background-color: var(--xh-segmented-item-bg-hover, var(--xh-bg-subtle-hover));
    color: var(--xh-segmented-item-fg-hover, var(--xh-fg-default));
  }

  /* 按下去要有回应：未选中段换到按下面（淡底承载 300），几何不动；只读段不压。
     选中段不叠按下面：它压着的白色滑块本身就是选中身份（有滑块开关无叠加态） */
  [data-scope='segmented'][data-part='item']:not([data-disabled]):not([data-readonly]):not([data-state='checked']):is(:active, [data-pressed]) {
    background-color: var(--xh-segmented-item-bg-pressed, var(--xh-bg-subtle-active));
    transition-duration: var(--xh-motion-duration-press);
    transition-timing-function: var(--xh-motion-ease-press);
  }

  /* 只读：值改不动，但对比度不降，光标也不摆出"禁止"的样子 */
  [data-scope='segmented'][data-part='item'][data-readonly]:not([data-disabled]) {
    cursor: default;
  }

  /* 集合条目一律 aria-disabled 而非原生 disabled（禁用段仍要能当方向键的起点），
     所以这里读 data-disabled，写 :disabled 永远不命中。
     用了 fg-disabled 就不再叠 opacity：半透明会把底下的指示器透出来 */
  [data-scope='segmented'][data-part='item'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 禁用且选中的那一段不换文字色：它压着的是指示器的实心底，换成 fg-disabled 后
     六族语气实测只剩 1.04–3.01 的对比度，「当前选的是哪一段」当场看不见。
     禁用由轨道底色、未选中段的文字色与光标表达，选中段保持可读 */
  [data-scope='segmented'][data-part='item'][data-disabled][data-state='checked'] {
    color: var(--xh-segmented-item-fg-checked-disabled, var(--xh-_segmented-fg-selected));
  }

  [data-scope='segmented'][data-part='item-text'] {
    color: inherit;
    user-select: none;
  }

  [data-scope='segmented'][data-part='indicator'] {
    /* 位置与尺寸由机器量好、连接层写成私有槽（它量得到，样式表量不到）；
       这四个是还没量到时的落点，量到即被内联的私有槽盖过 */
    --xh-_segmented-indicator-x: 0;
    --xh-_segmented-indicator-y: 0;
    --xh-_segmented-indicator-w: 0;
    --xh-_segmented-indicator-h: 0;

    /* 摆在行首块首，位置交给 transform（只走合成），尺寸跟着段宽走 */
    position: absolute;
    display: block;
    inset-inline-start: 0;
    inset-block-start: 0;
    inline-size: var(--xh-_segmented-indicator-w);
    block-size: var(--xh-_segmented-indicator-h);
    transform: translate(var(--xh-_segmented-indicator-x), var(--xh-_segmented-indicator-y));
    /* 白色抬起面三件（有滑块开关）：surface-raised 底 + border-default 描边 + raised 影，描边必须在，影只是加成。
       尺寸由连接层按段的盒量出，描边吃进盒里（border-box），滑块与段仍是同一块矩形 */
    border: var(--xh-stroke-thin) solid var(--xh-segmented-indicator-border, var(--xh-border-default));
    border-radius: var(--xh-segmented-indicator-radius, var(--xh-shape-inset));
    background: var(--xh-segmented-indicator-bg, var(--xh-_segmented-indicator-bg));
    box-shadow: var(--xh-segmented-indicator-shadow, var(--xh-elevation-raised));
    /* 段压在它上面，点击一律交给段；作者把它写在段之后时也不至于吞掉点击 */
    pointer-events: none;
    /* 用连续档而不是进场那条：滑块是被推过去的，起步就该有速度，
       纯减速曲线看着像自己飘过去。四个几何量同时走，段宽不等时才不会先变形再挪位。
       投影单列一项：整组禁用时滑块落回轨道平面，那层投影跟着收 */
    transition:
      transform var(--xh-motion-duration-move) var(--xh-motion-ease-continuous),
      inline-size var(--xh-motion-duration-move) var(--xh-motion-ease-continuous),
      block-size var(--xh-motion-duration-move) var(--xh-motion-ease-continuous),
      box-shadow var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* translate 只认物理方向：RTL 下行首在右边，起始缘量出的距离往左推 */
  [data-scope='segmented'][data-part='indicator']:dir(rtl) {
    transform: translate(calc(-1 * var(--xh-_segmented-indicator-x)), var(--xh-_segmented-indicator-y));
  }

  /* 给了 display 的角色节点必须补这条：display 声明会盖掉 UA 的 [hidden]{display:none}，
     不补的话作者给节点加 hidden 后它照样显示 */
  [data-scope='segmented'][data-part='root'][hidden],
  [data-scope='segmented'][data-part='item'][hidden],
  [data-scope='segmented'][data-part='indicator'][hidden] {
    display: none;
  }

  @media print {
    /* 打印默认丢背景色：滑块那块底与它的落影都不画，「当前选的是哪一段」在纸上没了。
       选中段改画一圈实边、字加粗，两条都不吃底色 */
    [data-scope='segmented'][data-part='item'][data-state='checked'] {
      border: var(--xh-stroke-thin) solid currentColor;
      font-weight: var(--xh-font-weight-bold);
    }
  }

  @media (forced-colors: active) {
    /* 按下：常态靠底色深一档表出，这一档里底色被统一换成 Canvas；按住那一下用系统高亮反色画回来 */
    [data-scope='segmented'][data-part='item']:not([data-disabled]):not([data-readonly]):not([data-state='checked']):is(:active, [data-pressed]) {
      background-color: Highlight;
      color: HighlightText;
    }
  }

  @media (pointer: coarse) {
    /* 手指的落点比一段高：命中区由伪元素向块轴两侧外扩，段的盒与轨道内的分格一点不动。
       只扩块轴——段与段在行内轴上首尾相接，往两侧扩会与相邻段的命中区叠上。
       取 8px 是按最矮的 sm 档算的（28 + 8 × 2 = 44），md 与 lg 档更宽裕 */
    [data-scope='segmented'][data-part='item']::before {
      content: '';
      position: absolute;
      inset-block: -8px;
      inset-inline: 0;
    }
  }
}

/* styles/signature-pad.css */
/* 定义 signature pad 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='signature-pad'] {
    --xh-signature-pad-skin: 1;
  }

  /* position 是给表单影子做定位基准的：那份输入被连接层内联写成绝对定位，
     根上不留基准它就会贴到更外层的定位祖先上，原生校验提示跟着飘到页面别处。 */
  [data-scope='signature-pad'][data-part='root'] {
    position: relative;
    display: flex;
    flex-direction: column;
    /* 画布到清空按钮与状态句的距离；标签到画布另有一档，见 label */
    gap: var(--xh-signature-pad-gap, var(--xh-space-2));
  }

  /* 复合单字段的标签：14 / 500 / fg-default，不随档；贴画布 space-1——
     容器的 gap 归画布之后的部件，标签在它之上补一段差值把距离收成目标值 */
  [data-scope='signature-pad'][data-part='label'] {
    margin-block-end: calc(
      var(--xh-signature-pad-label-gap, var(--xh-space-1))
      - var(--xh-signature-pad-gap, var(--xh-space-2))
    );
    color: var(--xh-signature-pad-label-fg, var(--xh-fg-default));
    font-size: var(--xh-signature-pad-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-signature-pad-label-font-weight, var(--xh-text-label-weight));
  }

  [data-scope='signature-pad'][data-part='label'][data-disabled] {
    color: var(--xh-signature-pad-label-fg-disabled, var(--xh-fg-subtle));
  }

  /* 画布是块状的写字区：宽度铺满外层，高度由宽高比决定。
     控件行高那把尺量的是一行控件，一块要写字的面积用不上它。
     touch-action 由连接层内联写死，触摸落笔才不会被页面滚动抢走。
     外壳按字段规则自绘（登记的画布型字段例外：字段家族配方钉死控件行高，画布按宽高比撑高吃不下它）：
     静息透明底 + border-control 描边 + control 圆角 + 无影 */
  [data-scope='signature-pad'][data-part='control'] {
    display: block;
    inline-size: 100%;
    aspect-ratio: var(--xh-signature-pad-aspect-ratio, 5 / 2);
    border: var(--xh-stroke-thin) solid var(--xh-signature-pad-border, var(--xh-border-control));
    border-radius: var(--xh-signature-pad-radius, var(--xh-shape-control));
    background: var(--xh-signature-pad-bg, transparent);
    cursor: crosshair;
    /* 一划就会把画布连同旁边的文字一起刷成选中态 */
    user-select: none;
    /* 落笔、校验不过与禁用三档各换一次描边或底色，换的过程要看得出来 */
    transition:
      border-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='signature-pad'][data-part='control'][data-invalid] {
    border-color: var(--xh-signature-pad-control-border-invalid, var(--xh-border-invalid));
  }

  /* 落笔期间把描边压深一档。border-strong 是装饰梯度里的一档，比 border-control 更淡，
     用在这儿会让描边在落笔时反而变弱 */
  [data-scope='signature-pad'][data-part='control'][data-drawing] {
    border-color: var(--xh-signature-pad-border-drawing, var(--xh-border-control-hover));
  }

  /* 只读仍看得见签名，只是改不动：收掉手型，别暗示"在这儿能写"；
     面按字段只读规则只换到淡底，描边不动 */
  [data-scope='signature-pad'][data-part='control'][data-readonly]:not([data-disabled]) {
    background: var(--xh-signature-pad-bg-readonly, var(--xh-bg-subtle));
    cursor: default;
  }

  /* 字段禁用面：描边退到 border-default、底换淡底 */
  [data-scope='signature-pad'][data-part='control'][data-disabled] {
    border-color: var(--xh-signature-pad-border-disabled, var(--xh-border-default));
    background: var(--xh-signature-pad-bg-disabled, var(--xh-bg-subtle));
    cursor: not-allowed;
  }

  /* 基准线：位置由连接层按百分比给出，这里只管它长什么样。
     它是"请在这条线上签"的功能性提示，不是装饰，颜色走控件描边那一档才看得见 */
  [data-scope='signature-pad'][data-part='guide'] {
    stroke: var(--xh-signature-pad-guide-stroke, var(--xh-border-control));
    stroke-width: var(--xh-stroke-thin);
    stroke-dasharray: 6 6;
  }

  /* 笔迹是一条填充路径（每一笔是它的一条子路径），不是描边：
     粗细要随压感变，而 stroke-width 全线只有一个值 */
  [data-scope='signature-pad'][data-part='path'] {
    fill: var(--xh-signature-pad-ink, var(--xh-fg-default));
    stroke: none;
  }

  /*
   * 清空按钮是画布旁的独立文字按钮：盒型、sm 档几何、outline 四态面、0.97 按压与粗指针命中区由家族配方
   * 按连接层投影的 data-xh-action-variant / -size 给出（缺省 outline，白底承载阶梯 100 → 200）。这里只把公开槽
   * 桥接到矩阵之前（使用者槽 → 形态矩阵 → 家族缺省）与几何槽映射，矩阵各态无影（淡底与阴影互斥）。
   */
  [data-scope='signature-pad'][data-part='clear-trigger'] {
    --xh-action-bg-rest: var(--xh-signature-pad-clear-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-signature-pad-clear-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-signature-pad-clear-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-bg-focus-visible: var(--xh-signature-pad-clear-bg, var(--xh-_action-variant-bg-focus-visible));
    --xh-action-bg-disabled: var(--xh-signature-pad-clear-bg-disabled, var(--xh-_action-variant-bg-disabled));
    --xh-action-fg-rest: var(--xh-signature-pad-clear-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-signature-pad-clear-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-signature-pad-clear-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-fg-focus-visible: var(--xh-signature-pad-clear-fg, var(--xh-_action-variant-fg-focus-visible));
    --xh-action-border-rest: var(--xh-signature-pad-clear-border, var(--xh-_action-variant-border-rest));
    --xh-action-border-hover: var(--xh-signature-pad-clear-border-hover, var(--xh-_action-variant-border-hover));
    --xh-action-border-pressed: var(--xh-signature-pad-clear-border-hover, var(--xh-_action-variant-border-pressed));
    --xh-action-border-focus-visible: var(--xh-signature-pad-clear-border, var(--xh-_action-variant-border-focus-visible));
    /* 矩阵各态无影：悬停不再抬影（raised 只给 Button），使用者槽仍可自行加 */
    --xh-action-shadow-hover: var(--xh-signature-pad-clear-shadow-hover, none);
    --xh-action-radius: var(--xh-signature-pad-clear-radius, var(--xh-shape-control));
    --xh-action-visual-size: var(--xh-signature-pad-clear-h, var(--xh-_action-profile-visual-size));
    --xh-action-padding-inline: var(--xh-signature-pad-clear-px, var(--xh-_action-profile-padding-inline));
    --xh-action-gap: var(--xh-signature-pad-clear-gap, var(--xh-_action-profile-gap));
    --xh-action-font-size: var(--xh-signature-pad-clear-font-size, var(--xh-_action-profile-font-size));
    /* 作者塞进来的图标随档取字形尺（sm = 16px） */
    --xh-icon-size: var(--xh-signature-pad-clear-icon-size, var(--xh-_action-profile-glyph-size));

    /* 竖排容器里不铺满一行：按钮只占自己的宽 */
    align-self: flex-start;
  }

  /* 空画布时按钮照常可按（收起它会让焦点掉回 body），只把静息前景压淡一档；悬停与按下仍回到默认前景 */
  [data-scope='signature-pad'][data-part='clear-trigger'][data-empty] {
    --xh-action-fg-rest: var(--xh-signature-pad-clear-fg-empty, var(--xh-fg-muted));
  }

  /* 面是实心的，环色与面同族，画在面里就看不出来；环改取面自己的前景色 */
  [data-scope='signature-pad'][data-part='clear-trigger'][data-xh-action-variant='solid']:focus-visible {
    --xh-action-ring-color-focus-visible: currentColor;
  }

  /* 签没签的那句话是说明角色：13 / fg-muted / leading-normal。读屏靠它播报，看得见的人也用得上，因此不做视觉隐藏 */
  [data-scope='signature-pad'][data-part='status'] {
    color: var(--xh-signature-pad-status-fg, var(--xh-fg-muted));
    font-size: var(--xh-signature-pad-status-font-size, var(--xh-text-secondary-size));
    line-height: var(--xh-leading-normal);
  }

  /* 表单影子的视觉隐藏（绝对定位 + 1px + clip-path）连接层内联给全了，这里不重复也不覆盖，
     只掐掉指针命中：那个 1px 的框压在画布上会截走本该落到画布上的落笔。 */
  [data-scope='signature-pad'][data-part='hidden-input'] {
    pointer-events: none;
  }

  /* display 会盖掉 UA 的 [hidden]{display:none}，凡是被赋了 display 的角色节点都要显式让位 */
  [data-scope='signature-pad'][data-part='root'][hidden],
  [data-scope='signature-pad'][data-part='control'][hidden],
  [data-scope='signature-pad'][data-part='clear-trigger'][hidden] {
    display: none;
  }
}

/* styles/statistic.css */
/* 定义 statistic 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='statistic'] {
    --xh-statistic-skin: 1;
  }

  /* 三个尺寸档只换这几个私有槽，各段从 root 继承它们，换档不必给每个部件各写一条选择器 */
  [data-scope='statistic'][data-part='root'] {
    --xh-_statistic-label-size: var(--xh-control-caption-md);
    --xh-_statistic-value-size: var(--xh-text-heading-2-size);
    --xh-_statistic-affix-size: var(--xh-control-font-md);
    --xh-_statistic-row-gap: var(--xh-space-1);
    /* 涨跌箭头与作者塞进来的图标同一把尺：跟着前后缀那一档字（14px）走，取 sm 字形 16px，大档抬到 md */
    --xh-_statistic-icon-size: var(--xh-glyph-size-sm);
    --xh-icon-size: var(--xh-statistic-icon-size, var(--xh-_statistic-icon-size));

    /* 折行排布：标签独占一行，前缀、数值、后缀在下一行按基线对齐排在一起 */
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    /* 前后缀默认贴着数值：货币符号与百分号中间留白就不成一个数了，要间距的写法自己开槽 */
    column-gap: var(--xh-statistic-gap, var(--xh-space-0));
    row-gap: var(--xh-statistic-row-gap, var(--xh-_statistic-row-gap));
    color: var(--xh-statistic-fg, var(--xh-fg-default));
  }

  /* 上面声明了 display，会盖掉 UA 的 [hidden] 规则，收起态要在这里接回来 */
  [data-scope='statistic'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 尺寸 —— */
  [data-scope='statistic'][data-part='root'][data-size='sm'] {
    --xh-_statistic-label-size: var(--xh-control-caption-sm);
    --xh-_statistic-value-size: var(--xh-text-heading-3-size);
    --xh-_statistic-affix-size: var(--xh-control-font-sm);
    --xh-_statistic-row-gap: var(--xh-space-0_5);
  }

  [data-scope='statistic'][data-part='root'][data-size='lg'] {
    --xh-_statistic-label-size: var(--xh-control-caption-lg);
    --xh-_statistic-value-size: var(--xh-text-heading-1-size);
    --xh-_statistic-affix-size: var(--xh-control-font-lg);
    --xh-_statistic-row-gap: var(--xh-space-1_5);
    --xh-_statistic-icon-size: var(--xh-glyph-size-md);
  }

  /* —— 各段 —— */
  /* 占满一整行，把前缀、数值、后缀挤到下一行去 */
  [data-scope='statistic'][data-part='label'] {
    flex: 0 0 100%;
    color: var(--xh-statistic-label-fg, var(--xh-fg-muted));
    font-size: var(--xh-statistic-label-font-size, var(--xh-_statistic-label-size));
    font-weight: var(--xh-font-weight-regular);
    line-height: var(--xh-leading-normal);
  }

  /* 等宽数字：逐位宽度一致，数值刷新时后面的字符不会左右挪动 */
  [data-scope='statistic'][data-part='value'] {
    color: var(--xh-statistic-value-fg, var(--xh-_tone-fg, var(--xh-fg-default)));
    font-size: var(--xh-statistic-value-font-size, var(--xh-_statistic-value-size));
    font-variant-numeric: tabular-nums;
    font-weight: var(--xh-font-weight-semibold);
    line-height: var(--xh-leading-tight);
  }

  /* 前后缀比数值小一档、跟着数值的语气走；没写语气时退成弱前景 */
  [data-scope='statistic'][data-part='prefix'],
  [data-scope='statistic'][data-part='suffix'] {
    color: var(--xh-statistic-affix-fg, var(--xh-_tone-fg, var(--xh-fg-muted)));
    font-size: var(--xh-statistic-affix-font-size, var(--xh-_statistic-affix-size));
    font-variant-numeric: tabular-nums;
    font-weight: var(--xh-font-weight-regular);
    line-height: var(--xh-leading-tight);
  }

  /* —— 涨跌 —— */
  /* 与数值同一行，中间空开一档；比数（同比、环比）由作者写进来 */
  [data-scope='statistic'][data-part='trend'] {
    display: inline-flex;
    align-items: center;
    gap: var(--xh-statistic-trend-gap, var(--xh-space-0_5));
    margin-inline-start: var(--xh-statistic-trend-offset, var(--xh-space-2));
    color: var(--xh-statistic-trend-fg, var(--xh-_tone-fg, var(--xh-fg-muted)));
    font-size: var(--xh-statistic-trend-font-size, var(--xh-_statistic-affix-size));
    font-variant-numeric: tabular-nums;
    font-weight: var(--xh-font-weight-regular);
    line-height: var(--xh-leading-tight);
  }

  /* 方向逐档换字形，箭头由皮肤画，示例里不必手打 */
  [data-scope='statistic'][data-part='trend'][data-direction='up'] {
    --xh-_statistic-trend-mark: var(--xh-glyph-mark-arrow-up);
  }

  [data-scope='statistic'][data-part='trend'][data-direction='down'] {
    --xh-_statistic-trend-mark: var(--xh-glyph-mark-arrow-down);
  }

  [data-scope='statistic'][data-part='trend'][data-direction='flat'] {
    --xh-_statistic-trend-mark: var(--xh-glyph-mark-minus);
  }

  [data-scope='statistic'][data-part='trend'][data-direction]::before {
    content: '';
    display: inline-block;
    flex: none;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-sm));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-sm));
    background-color: currentColor;
    -webkit-mask: var(--xh-_statistic-trend-mark) center / contain no-repeat;
    mask: var(--xh-_statistic-trend-mark) center / contain no-repeat;
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='statistic'][data-part='trend'][hidden] {
    display: none;
  }
}

/* styles/tag.css */
/* 定义 tag 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='tag'] {
    --xh-tag-skin: 1;
  }

  /* 缺省态：md 档、无语气。三轴规则只在它之上叠加，不改这一条 */
  [data-scope='tag'][data-part='root'] {
    /* 作者塞进指示符槽的图标跟着字号走，与皮肤画的兜底字形同一把尺 */
    --xh-icon-size: var(--xh-tag-icon-size, var(--xh-glyph-size-text));

    /* 尺寸档只换这五个私有槽，下面的声明从它们取值；行框是标签里那一行的高，取指示符档 */
    --xh-_tag-gap: var(--xh-space-1);
    --xh-_tag-px: var(--xh-space-2);
    --xh-_tag-py: var(--xh-space-1);
    --xh-_tag-font-size: var(--xh-text-secondary-size);
    --xh-_tag-line-h: var(--xh-control-indicator-md);

    display: inline-flex;
    align-items: center;
    /* 一行放不下时标签自己截断，而不是把整行撑破 */
    max-inline-size: 100%;
    gap: var(--xh-tag-gap, var(--xh-_tag-gap));
    padding-inline: var(--xh-tag-px, var(--xh-_tag-px));
    padding-block: var(--xh-tag-py, var(--xh-_tag-py));
    border: var(--xh-stroke-thin) solid var(--xh-tag-border, var(--xh-material-soft-border));
    /* 状态 chip 的身份是胶囊（pill 只给状态 chip 与一维对象） */
    border-radius: var(--xh-tag-radius, var(--xh-shape-pill));
    background: var(--xh-tag-bg, var(--xh-material-soft-bg));
    box-shadow: var(--xh-tag-shadow, var(--xh-material-soft-shadow));
    color: var(--xh-tag-fg, var(--xh-material-soft-fg));
    font-size: var(--xh-tag-font-size, var(--xh-_tag-font-size));
    font-weight: var(--xh-tag-font-weight, var(--xh-font-weight-medium));
    /* 行框不低于关闭钮，有没有关闭钮同档标签一样高；
       作者把字调得比这一格还大时行框跟着字走，label 的截断不会剪掉字的上下沿 */
    line-height: max(calc(var(--xh-leading-none) * 1em), var(--xh-_tag-line-h));
    /* 随文排时与正文基线对齐 */
    vertical-align: middle;
  }

  /* 收起态连接层给的是 hidden 属性，而上面声明了 display——
     漏掉这条，摘掉的标签还会一直摊在页面上 */
  [data-scope='tag'][data-part='root'][hidden] {
    display: none;
  }

  /* 文字过长时截断，关闭钮才始终留在标签里 */
  [data-scope='tag'][data-part='label'] {
    overflow: hidden;
    min-inline-size: 0;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  [data-scope='tag'][data-part='close-trigger'] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    position: relative;
    flex: none;
    /* 命中区：作者槽 → 不分档的指示符，三档同一个数，与库里其它标签内的移除钮同一把尺；行框比它高的档里钮居中 */
    block-size: var(--xh-tag-close-size, var(--xh-control-indicator-size));
    inline-size: var(--xh-tag-close-size, var(--xh-control-indicator-size));
    /* 命中区比字形大一圈，往内收一格才不会在标签右缘留出一块空白 */
    margin-inline-end: calc(-1 * var(--xh-space-1));
    border: 0;
    /* 随文标记档的叉：16px 正方盒取 inset 4px，与 checkbox 系方框同档，嵌在胶囊里内层圆角不越过外层 */
    border-radius: var(--xh-tag-close-radius, var(--xh-shape-inset));
    background: transparent;
    /* 叉取标签自己的文字色：实心底上是浅字、淡底上是深字，不必逐形态各写一遍 */
    color: var(--xh-tag-close-fg, currentColor);
    /* 按钮不继承字族字号，不接回来的话标签里会突然冒出一段系统 UI 字体 */
    font: inherit;
    line-height: var(--xh-leading-none);
    cursor: pointer;
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      scale var(--xh-motion-duration-release) var(--xh-motion-ease-release);
  }

  /* 视觉盒保持 16px，透明命中层扩到随文动作的 24px，不把整枚标签撑高。 */
  [data-scope='tag'][data-part='close-trigger']::after {
    position: absolute;
    inset: calc(
      (var(--xh-control-action-size) - var(--xh-tag-close-size, var(--xh-control-indicator-size))) / -2
    );
    content: '';
  }

  /* closable=false 时连接层同时给了 hidden 与 disabled，这条是它真正收起的那一半 */
  [data-scope='tag'][data-part='close-trigger'][hidden] {
    display: none;
  }

  [data-scope='tag'][data-part='close-trigger']:hover:not(:disabled) {
    /* 底色从当前前景色调出来：标签的实心 / 淡底 / 描边各形态下都压得住 */
    background: var(--xh-tag-close-bg-hover, color-mix(in oklab, currentColor 14%, transparent));
  }

  /* 指针 :active 与 Headless 投影的 data-pressed（Space / Enter 与触屏按住）看见同一副按压面 */
  [data-scope='tag'][data-part='close-trigger']:not(:disabled):is(:active, [data-pressed]) {
    background: var(--xh-tag-close-bg-active, color-mix(in oklab, currentColor 22%, transparent));
    scale: var(--xh-motion-scale-press);
    transition-duration: var(--xh-motion-duration-press);
    transition-timing-function: var(--xh-motion-ease-press);
  }

  /* 按住的叉落着焦点（focus-visible + pressed 保留焦点环）：按压面是从字色兑出的 22% 底，
     压在淡底 / 选中面上把面往字色那头带了一档，默认环与这块混色面在浅色档上只剩 2.2–2.9。
     环改取叉自己的字色：按压面正是从这支色兑出来的，字色压在它上面的对比与字压在标签面上同源，
     六族语气与深浅两态都过 3:1；实心档本来就取字色，这条与它同一口径 */
  [data-scope='tag'][data-part='close-trigger']:not(:disabled):is(:active, [data-pressed]):focus-visible {
    --xh-_ring-color: currentColor;
  }

  [data-scope='tag'][data-part='close-trigger']:disabled {
    color: var(--xh-fg-disabled);
  }

  /* —— 形态 —— */
  /* 形态只决定颜色怎么用。每个形态拆成两条：先是没写语气时的基线配色，
     再是写了语气时的覆盖。语气槽会沿继承流下来，覆盖那条必须带 [data-tone] 限定，
     否则一枚没写语气的标签只要落在带 data-tone 的容器里（警告提示、吐司、按钮内）
     就会跟着染色。
     实心档还在顶边画一条极浅的内高光，把整块底衬出厚度；语气那条同样从实心底上的前景色兑，
     换语气时高光跟着换 */
  [data-scope='tag'][data-part='root'][data-variant='solid'] {
    --xh-_tag-highlight: var(--xh-_highlight-brand);

    border-color: transparent;
    background: var(--xh-tag-bg, var(--xh-bg-brand));
    color: var(--xh-tag-fg, var(--xh-fg-on-brand));
    box-shadow: var(--xh-tag-shadow, var(--xh-_tag-highlight));
  }

  /* 面是实心的，环色与面同族，画在面里就看不出来；环改取面自己的前景色——
     那一族色本来就要在这块面上把字读清楚，与面的对比是按可读性定的。
     置灰那档的底已换成静默色、字换成置灰色，不在其列：环退回默认那一支 */
  [data-scope='tag'][data-part='root'][data-variant='solid']:not([data-disabled]):focus-visible {
    --xh-_ring-color: currentColor;
  }

  /* 关闭钮自己的面是透空的，环压着的是标签那块实心底；它的字色就是那块底上的前景色，
     环跟着取过来 */
  [data-scope='tag'][data-part='root'][data-variant='solid']:not([data-disabled])
    [data-scope='tag'][data-part='close-trigger']:focus-visible {
    --xh-_ring-color: currentColor;
  }

  [data-scope='tag'][data-part='root'][data-variant='solid'][data-tone] {
    --xh-_tag-highlight: var(--xh-_highlight-tone);

    background: var(--xh-tag-bg, var(--xh-_tone, var(--xh-bg-brand)));
    color: var(--xh-tag-fg, var(--xh-_tone-on, var(--xh-fg-on-brand)));
  }

  [data-scope='tag'][data-part='root'][data-variant='subtle'] {
    border-color: var(--xh-tag-border, var(--xh-material-soft-border));
    background: var(--xh-tag-bg, var(--xh-material-soft-bg));
    color: var(--xh-tag-fg, var(--xh-material-soft-fg));
  }

  [data-scope='tag'][data-part='root'][data-variant='subtle'][data-tone] {
    background: var(--xh-tag-bg, var(--xh-_tone-subtle, var(--xh-bg-subtle)));
    color: var(--xh-tag-fg, var(--xh-_tone-fg, var(--xh-fg-default)));
  }

  [data-scope='tag'][data-part='root'][data-variant='outline'] {
    border-color: var(--xh-tag-border, var(--xh-border-default));
    background: transparent;
    box-shadow: none;
    color: var(--xh-tag-fg, var(--xh-fg-default));
  }

  /* 描边档的边就是这枚标签的全部轮廓，走「可操作区边界」那一支：
     兑了底色的 --xh-_tone-border 六族都在 1.44-2.18，当轮廓看不清 */
  [data-scope='tag'][data-part='root'][data-variant='outline'][data-tone] {
    border-color: var(--xh-tag-border, var(--xh-_tone-border-control, var(--xh-border-default)));
    color: var(--xh-tag-fg, var(--xh-_tone-fg, var(--xh-fg-default)));
  }

  [data-scope='tag'][data-part='root'][data-variant='ghost'] {
    border-color: transparent;
    background: transparent;
    box-shadow: none;
    color: var(--xh-tag-fg, var(--xh-fg-default));
  }

  [data-scope='tag'][data-part='root'][data-variant='ghost'][data-tone] {
    color: var(--xh-tag-fg, var(--xh-_tone-fg, var(--xh-fg-default)));
  }

  /* —— 尺寸 —— */
  /* 标签是随文排的标记，不占控件行高，档位走间距、字号与行框而不是 control-h */
  [data-scope='tag'][data-part='root'][data-size='sm'] {
    --xh-_tag-gap: var(--xh-space-0_5);
    --xh-_tag-px: var(--xh-space-1_5);
    --xh-_tag-py: var(--xh-space-0_5);
    --xh-_tag-font-size: var(--xh-text-caption-size);
  }

  /* 行框上到指示符的大档，竖向内衬沿用中档；关闭钮不换档 */
  [data-scope='tag'][data-part='root'][data-size='lg'] {
    --xh-_tag-gap: var(--xh-space-1_5);
    --xh-_tag-px: var(--xh-space-3);
    --xh-_tag-font-size: var(--xh-text-body-size);
    --xh-_tag-line-h: var(--xh-control-indicator-lg);
  }

  /* —— 禁用 —— */
  /* 排在形态之后，靠源序压过形态给的配色。第二条选择器专为写了语气的标签而设：
     语气覆盖那几条比第一条多一个属性，不把 [data-tone] 一起写上，
     禁用的标签会留着语气实心底、只有文字变灰，底上几乎看不见字。
     用了 fg-disabled 就不再叠 opacity */
  [data-scope='tag'][data-part='root'][data-disabled],
  [data-scope='tag'][data-part='root'][data-tone][data-disabled] {
    border-color: var(--xh-tag-border-disabled, var(--xh-border-default));
    background: var(--xh-tag-bg-disabled, var(--xh-bg-muted));
    color: var(--xh-fg-disabled);
    /* 底已经退成置灰色，实心档那条内高光跟着收掉 */
    box-shadow: none;
  }

  /*
   * 打印：底色被丢掉，实心与淡底两档的底一起没了。实心档配的是实心底上的前景色，
   * 底一没那行字就落在白纸上——白字印在白纸上，整枚标签只剩一块空白。
   * 两档在纸上都退成描边档：字色回到正文色，轮廓由边框接手，内高光跟着收掉。
   * 两条选择器分别压过形态与语气这两层覆盖点；禁用档摘掉，它自己就是灰的。
   */
  @media print {
    [data-scope='tag'][data-part='root']:not([data-disabled]),
    [data-scope='tag'][data-part='root'][data-variant][data-tone]:not([data-disabled]) {
      border-color: currentColor;
      background: none;
      color: var(--xh-fg-default);
      box-shadow: none;
    }
  }

  /*
   * 高对比档：关闭钮的按压面常态靠从 currentColor 兑出来的底色表出，这一档里底色被统一换成 Canvas，
   * 按住那一下与静息塌成同一个样子；用系统高亮反色画回来，兜底字形读 currentColor、自己跟着换
   */
  @media (forced-colors: active) {
    [data-scope='tag'][data-part='close-trigger']:not(:disabled):is(:active, [data-pressed]) {
      background: Highlight;
      color: HighlightText;
    }
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中 */
  [data-scope='tag'][data-part='close-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }
}

/* styles/timeline.css */
/* 定义 timeline 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='timeline'] {
    --xh-timeline-skin: 1;
  }

  [data-scope='timeline'][data-part='root'] {
    /* 尺寸档只换这几个私有槽，条目、圆点与文字都从 root 继承它们，
       换档不必给每个部件各写一条选择器 */
    --xh-_timeline-dot-size: var(--xh-space-2_5);
    --xh-_timeline-gutter: var(--xh-space-3);
    --xh-_timeline-item-gap: var(--xh-space-5);
    --xh-_timeline-title-font-size: var(--xh-control-font-md);
    --xh-_timeline-caption-font-size: var(--xh-text-caption-size);
    /* 标题首行占多高。圆点按它居中下移，圆心才落在标题这一行的中线上 */
    --xh-_timeline-line-h: calc(
      var(--xh-timeline-title-font-size, var(--xh-_timeline-title-font-size)) * var(--xh-leading-tight)
    );

    /* 条目之间不设 gap：留白由 content 自己的边距撑出来，连线才连得到下一条的圆点。
       ol 的项目符号与内外边距是 UA 给的，库里没有全局 preflight，只能在这儿自己抹平 */
    display: flex;
    margin: 0;
    padding: 0;
    color: var(--xh-timeline-fg, var(--xh-fg-default));
    list-style: none;
  }

  [data-scope='timeline'][data-part='root'][hidden] {
    display: none;
  }

  [data-scope='timeline'][data-part='root'][data-orientation='vertical'] {
    flex-direction: column;
  }

  /* 横排排成一行、允许折行：窄档里每条占满整行，于是一条一行地堆下来。
     朝向两档都是 row，换档换的是下面每条的 flex 基准 */
  [data-scope='timeline'][data-part='root'][data-orientation='horizontal'] {
    flex-direction: row;
    flex-wrap: wrap;
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里。圆点直径不在控件高度那把尺上，三档走空间尺相邻的三格 */
  [data-scope='timeline'][data-part='root'][data-size='sm'] {
    --xh-_timeline-dot-size: var(--xh-space-2);
    --xh-_timeline-gutter: var(--xh-space-2);
    --xh-_timeline-item-gap: var(--xh-space-4);
    --xh-_timeline-title-font-size: var(--xh-control-font-sm);
    /* 字号档最小就是 xs，时刻文本不再往下走，故不重声明 caption */
  }

  [data-scope='timeline'][data-part='root'][data-size='lg'] {
    --xh-_timeline-dot-size: var(--xh-space-3);
    --xh-_timeline-gutter: var(--xh-space-4);
    --xh-_timeline-item-gap: var(--xh-space-6);
    --xh-_timeline-title-font-size: var(--xh-control-font-lg);
    --xh-_timeline-caption-font-size: var(--xh-text-secondary-size);
  }

  /* —— 条目 —— */
  /* 圆点与连线占一列，内容占另一列，用 grid 而不是再包一层节点：
     解剖里没有那个包裹层，作者也不该被逼着多写一个 div。
     这份两列的摆法是两个朝向共同的窄档，横排在下面的宽档里改写它 */
  [data-scope='timeline'][data-part='item'] {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
    column-gap: var(--xh-timeline-gutter, var(--xh-_timeline-gutter));
    /* 库里没有全局 preflight，列表项的外边距在这里自己抹平 */
    margin: 0;
    /* 允许被压缩，内容里的省略号才有生效的余地 */
    min-inline-size: 0;
  }

  [data-scope='timeline'][data-part='item'][hidden] {
    display: none;
  }

  /* 横排的窄档：每条占满整行，一条一行地堆下来 */
  [data-scope='timeline'][data-part='item'][data-orientation='horizontal'] {
    flex: 0 0 100%;
  }

  /* —— 圆点 —— */
  [data-scope='timeline'][data-part='indicator'] {
    display: flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-timeline-indicator-size, var(--xh-_timeline-dot-size));
    block-size: var(--xh-timeline-indicator-size, var(--xh-_timeline-dot-size));
    border-radius: var(--xh-timeline-indicator-radius, var(--xh-shape-circle));
    /* 使用者令牌排在语气之前；两者都没有时退回一个中性的实心点 */
    background: var(--xh-timeline-indicator-bg, var(--xh-_tone-soft, var(--xh-fg-muted)));
    color: var(--xh-timeline-indicator-fg, var(--xh-_tone-on, var(--xh-fg-on-brand)));
    font-size: var(--xh-timeline-indicator-font-size, var(--xh-_timeline-caption-font-size));
    line-height: var(--xh-leading-none);
    /* 语气色由每条自己的数据给，同一条的语气改了（事情办成了、出错了）走一遍过渡，
       整列圆点不在数据回来的那一帧集体跳色 */
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='timeline'][data-part='indicator'][hidden] {
    display: none;
  }

  [data-scope='timeline'][data-part='item'] [data-scope='timeline'][data-part='indicator'] {
    grid-column: 1;
    grid-row: 1;
    /* 行高减去直径的一半：calc 里的除法要写成乘 0.5，除号在这儿是无效语法 */
    margin-block-start: calc(
      (var(--xh-_timeline-line-h) - var(--xh-timeline-indicator-size, var(--xh-_timeline-dot-size))) * 0.5
    );
  }

  /* —— 连线 —— */
  [data-scope='timeline'][data-part='connector'] {
    border-radius: var(--xh-timeline-connector-radius, var(--xh-shape-pill));
    background: var(--xh-timeline-connector-bg, var(--xh-border-default));
  }

  [data-scope='timeline'][data-part='connector'][hidden] {
    display: none;
  }

  /* 堆叠时：从圆点下沿一直伸到条目底边，接上下一条的圆点。
     min-block-size 兜住内容极短的条目，那时也还看得见一截线 */
  [data-scope='timeline'][data-part='item'] [data-scope='timeline'][data-part='connector'] {
    grid-column: 1;
    grid-row: 2;
    justify-self: center;
    inline-size: var(--xh-timeline-connector-thickness, var(--xh-stroke-thick));
    min-block-size: var(--xh-timeline-connector-min-length, var(--xh-space-4));
    margin-block-start: var(--xh-space-1);
  }

  /* 末条后面没有下一件事，那截线不该占地方；作者不写它也一样，写了就替他收掉 */
  [data-scope='timeline'][data-part='item']:last-child [data-scope='timeline'][data-part='connector'] {
    display: none;
  }

  /* —— 内容 —— */
  [data-scope='timeline'][data-part='content'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-timeline-content-gap, var(--xh-space-1));
    min-inline-size: 0;
  }

  [data-scope='timeline'][data-part='content'][hidden] {
    display: none;
  }

  /* 条目之间的留白由内容自己的边距撑出来，连线的那一列因此能一路连到下一条 */
  [data-scope='timeline'][data-part='item'] [data-scope='timeline'][data-part='content'] {
    grid-column: 2;
    grid-row: 1 / -1;
    padding-block-end: var(--xh-timeline-item-gap, var(--xh-_timeline-item-gap));
  }

  /* 末条的留白同样收掉：它后面已经没有要隔开的东西 */
  [data-scope='timeline'][data-part='item']:last-child [data-scope='timeline'][data-part='content'] {
    padding-block-end: 0;
  }

  /* —— 侧别 —— */
  /* 不写 placement 时内容落在结束侧，即上面那几条基础规则。
     start 把线挪到结束侧、内容挪到起始侧，文字一并靠向线 */
  [data-scope='timeline'][data-part='item'][data-orientation='vertical'][data-placement='start'] {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  [data-scope='timeline'][data-part='item'][data-orientation='vertical'][data-placement='start'] [data-scope='timeline'][data-part='indicator'],
  [data-scope='timeline'][data-part='item'][data-orientation='vertical'][data-placement='start'] [data-scope='timeline'][data-part='connector'] {
    grid-column: 2;
  }

  [data-scope='timeline'][data-part='item'][data-orientation='vertical'][data-placement='start'] [data-scope='timeline'][data-part='content'] {
    grid-column: 1;
    align-items: flex-end;
    text-align: end;
  }

  /* alternate：线走中间，奇数条在结束侧、偶数条在起始侧 */
  [data-scope='timeline'][data-part='item'][data-orientation='vertical'][data-placement='alternate'] {
    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  }

  [data-scope='timeline'][data-part='item'][data-orientation='vertical'][data-placement='alternate'] [data-scope='timeline'][data-part='indicator'],
  [data-scope='timeline'][data-part='item'][data-orientation='vertical'][data-placement='alternate'] [data-scope='timeline'][data-part='connector'] {
    grid-column: 2;
  }

  [data-scope='timeline'][data-part='item'][data-orientation='vertical'][data-placement='alternate'] [data-scope='timeline'][data-part='content'] {
    grid-column: 3;
  }

  [data-scope='timeline'][data-part='item'][data-orientation='vertical'][data-placement='alternate']:nth-child(even) [data-scope='timeline'][data-part='content'] {
    grid-column: 1;
    align-items: flex-end;
    text-align: end;
  }

  /* —— 坐标 —— */
  /* 与内容对置的那一列。竖排三种侧别各给它一条轨道，横排不单开轨道、按流排在末尾 */
  [data-scope='timeline'][data-part='label'] {
    grid-column: var(--xh-_timeline-label-col, auto);
    grid-row: var(--xh-_timeline-label-row, auto);
    align-self: start;
    min-inline-size: 0;
    color: var(--xh-timeline-label-fg, var(--xh-fg-subtle));
    font-size: var(--xh-timeline-label-font-size, var(--xh-_timeline-caption-font-size));
    /* 等宽数字：日期里的 1 与 7 在比例字体里宽度不同，不定住会让整列坐标左右抖一格 */
    font-variant-numeric: tabular-nums;
    line-height: var(--xh-leading-tight);
    text-align: var(--xh-_timeline-label-align, end);
  }

  /* 内容落在结束侧时坐标占线之前的那一列，圆点与连线让到第二列 */
  [data-scope='timeline'][data-part='item'][data-orientation='vertical']:where(:not([data-placement]), [data-placement='end']):has(> [data-scope='timeline'][data-part='label']) {
    --xh-_timeline-label-col: 1;
    --xh-_timeline-label-row: 1;

    grid-template-columns: auto auto minmax(0, 1fr);
  }

  [data-scope='timeline'][data-part='item'][data-orientation='vertical']:where(:not([data-placement]), [data-placement='end']):has(> [data-scope='timeline'][data-part='label']) > [data-scope='timeline'][data-part='indicator'],
  [data-scope='timeline'][data-part='item'][data-orientation='vertical']:where(:not([data-placement]), [data-placement='end']):has(> [data-scope='timeline'][data-part='label']) > [data-scope='timeline'][data-part='connector'] {
    grid-column: 2;
  }

  [data-scope='timeline'][data-part='item'][data-orientation='vertical']:where(:not([data-placement]), [data-placement='end']):has(> [data-scope='timeline'][data-part='label']) > [data-scope='timeline'][data-part='content'] {
    grid-column: 3;
  }

  /* 横排的窄档摆成上下两格，坐标照竖排那样占线之前的一列。
     不给这条轨道的话坐标会自动落进圆点那一列，把它撑宽，圆点与连线因此错开 */
  [data-scope='timeline'][data-part='item'][data-orientation='horizontal']:has(> [data-scope='timeline'][data-part='label']) {
    --xh-_timeline-label-col: 1;
    --xh-_timeline-label-row: 1;

    grid-template-columns: auto auto minmax(0, 1fr);
  }

  [data-scope='timeline'][data-part='item'][data-orientation='horizontal']:has(> [data-scope='timeline'][data-part='label']) > [data-scope='timeline'][data-part='indicator'],
  [data-scope='timeline'][data-part='item'][data-orientation='horizontal']:has(> [data-scope='timeline'][data-part='label']) > [data-scope='timeline'][data-part='connector'] {
    grid-column: 2;
  }

  [data-scope='timeline'][data-part='item'][data-orientation='horizontal']:has(> [data-scope='timeline'][data-part='label']) > [data-scope='timeline'][data-part='content'] {
    grid-column: 3;
  }

  /* 内容落在起始侧时坐标占线之后的那一列 */
  [data-scope='timeline'][data-part='item'][data-orientation='vertical'][data-placement='start']:has(> [data-scope='timeline'][data-part='label']) {
    --xh-_timeline-label-col: 3;
    --xh-_timeline-label-row: 1;
    --xh-_timeline-label-align: start;

    grid-template-columns: minmax(0, 1fr) auto auto;
  }

  /* 逐条交替时坐标恒在内容的对面，时间戳因此不跟着内容左右横跳 */
  [data-scope='timeline'][data-part='item'][data-orientation='vertical'][data-placement='alternate'] {
    --xh-_timeline-label-col: 1;
    --xh-_timeline-label-row: 1;
  }

  [data-scope='timeline'][data-part='item'][data-orientation='vertical'][data-placement='alternate']:nth-child(even) {
    --xh-_timeline-label-col: 3;
    --xh-_timeline-label-align: start;
  }

  /* —— 横排的宽档 —— */
  /* 上面那份两列的摆法是两个朝向共同的窄档。视口宽到放得下一行事件时，
     横排在这里把圆点与连线转回同一行、内容落到下一行。
     手机档停在窄档：一条一行，事件仍逐条读得完 */
  @media (min-width: 768px) {
    /* 每条等分整行 */
    [data-scope='timeline'][data-part='item'][data-orientation='horizontal'] {
      flex: 1;
    }

    /* 每条规则都带一条 :has(坐标) 的分支：窄档那条坐标轨道的选择器更重，
       不把它写进来的话带坐标的那些条目会停在窄档的摆法上 */
    [data-scope='timeline'][data-part='item'][data-orientation='horizontal'] [data-scope='timeline'][data-part='indicator'],
    [data-scope='timeline'][data-part='item'][data-orientation='horizontal']:has(> [data-scope='timeline'][data-part='label']) > [data-scope='timeline'][data-part='indicator'] {
      grid-column: 1;
      grid-row: 1;
      /* 圆点与内容不再上下对位，窄档那半行的下移收掉 */
      margin-block-start: 0;
    }

    /* 线转成横的一条，与圆点同一行；窄档那几条竖着走的取值一并收掉 */
    [data-scope='timeline'][data-part='item'][data-orientation='horizontal'] [data-scope='timeline'][data-part='connector'],
    [data-scope='timeline'][data-part='item'][data-orientation='horizontal']:has(> [data-scope='timeline'][data-part='label']) > [data-scope='timeline'][data-part='connector'] {
      grid-column: 2;
      grid-row: 1;
      align-self: center;
      justify-self: stretch;
      inline-size: auto;
      min-inline-size: var(--xh-timeline-connector-min-length, var(--xh-space-4));
      block-size: var(--xh-timeline-connector-thickness, var(--xh-stroke-thick));
      min-block-size: 0;
      margin-block-start: 0;
      margin-inline-start: var(--xh-space-1);
    }

    [data-scope='timeline'][data-part='item'][data-orientation='horizontal'] [data-scope='timeline'][data-part='content'],
    [data-scope='timeline'][data-part='item'][data-orientation='horizontal']:has(> [data-scope='timeline'][data-part='label']) > [data-scope='timeline'][data-part='content'] {
      grid-column: 1 / -1;
      grid-row: 2;
      padding-block-start: var(--xh-timeline-content-pt, var(--xh-space-2));
      padding-block-end: 0;
      padding-inline-end: var(--xh-timeline-item-gap, var(--xh-_timeline-item-gap));
    }

    /* 末条的留白同样收掉：它后面已经没有要隔开的东西 */
    [data-scope='timeline'][data-part='item'][data-orientation='horizontal']:last-child [data-scope='timeline'][data-part='content'] {
      padding-inline-end: 0;
    }

    /* 宽档不给坐标单开轨道，它按流排在末尾；窄档那条轨道在这里收掉 */
    [data-scope='timeline'][data-part='item'][data-orientation='horizontal']:has(> [data-scope='timeline'][data-part='label']) {
      --xh-_timeline-label-col: auto;
      --xh-_timeline-label-row: auto;

      grid-template-columns: auto minmax(0, 1fr);
    }

    /* 横排的 start 是把内容挪到线的上方，内容贴着线的那一边对齐 */
    [data-scope='timeline'][data-part='item'][data-orientation='horizontal'][data-placement='start'] {
      grid-template-rows: minmax(0, 1fr) auto;
    }

    [data-scope='timeline'][data-part='item'][data-orientation='horizontal'][data-placement='start'] [data-scope='timeline'][data-part='indicator'],
    [data-scope='timeline'][data-part='item'][data-orientation='horizontal'][data-placement='start'] [data-scope='timeline'][data-part='connector'] {
      grid-row: 2;
    }

    [data-scope='timeline'][data-part='item'][data-orientation='horizontal'][data-placement='start'] [data-scope='timeline'][data-part='content'] {
      grid-row: 1;
      align-self: end;
      padding-block-start: 0;
      padding-block-end: var(--xh-timeline-content-pb, var(--xh-space-2));
    }

    [data-scope='timeline'][data-part='item'][data-orientation='horizontal'][data-placement='alternate'] {
      grid-template-rows: minmax(0, 1fr) auto minmax(0, 1fr);
    }

    [data-scope='timeline'][data-part='item'][data-orientation='horizontal'][data-placement='alternate'] [data-scope='timeline'][data-part='indicator'],
    [data-scope='timeline'][data-part='item'][data-orientation='horizontal'][data-placement='alternate'] [data-scope='timeline'][data-part='connector'] {
      grid-row: 2;
    }

    [data-scope='timeline'][data-part='item'][data-orientation='horizontal'][data-placement='alternate'] [data-scope='timeline'][data-part='content'] {
      grid-row: 3;
      align-self: start;
    }

    [data-scope='timeline'][data-part='item'][data-orientation='horizontal'][data-placement='alternate']:nth-child(even) [data-scope='timeline'][data-part='content'] {
      grid-row: 1;
      align-self: end;
      padding-block-start: 0;
      padding-block-end: var(--xh-timeline-content-pb, var(--xh-space-2));
    }
  }

  /* —— 文字 —— */
  /* 中间没有断点的长串——单号、路径、无空格的标识——在框内断开。
     每条的宽度由内容的最小宽度定，断不开就会把整条轴顶出容器 */
  [data-scope='timeline']:is([data-part='title'], [data-part='description'], [data-part='time'], [data-part='label']) {
    overflow-wrap: anywhere;
  }

  [data-scope='timeline'][data-part='title'] {
    color: var(--xh-timeline-title-fg, var(--xh-fg-default));
    font-size: var(--xh-timeline-title-font-size, var(--xh-_timeline-title-font-size));
    font-weight: var(--xh-timeline-title-font-weight, var(--xh-text-label-weight));
    line-height: var(--xh-leading-tight);
  }

  [data-scope='timeline'][data-part='description'] {
    color: var(--xh-timeline-description-fg, var(--xh-fg-muted));
    font-size: var(--xh-timeline-description-font-size, var(--xh-text-secondary-size));
    line-height: var(--xh-leading-normal);
  }

  [data-scope='timeline'][data-part='time'] {
    color: var(--xh-timeline-time-fg, var(--xh-fg-subtle));
    font-size: var(--xh-timeline-time-font-size, var(--xh-_timeline-caption-font-size));
    /* 等宽数字：时刻里的 1 与 7 在比例字体里宽度不同，不定住会让整列时间左右抖一格 */
    font-variant-numeric: tabular-nums;
    line-height: var(--xh-leading-normal);
  }

  /*
   * 打印：底色被丢掉，圆点与连线整个是底色画出来的，纸上这条轴的骨架就此不见，
   * 只剩几段没有次序的文字。两处都改由描边承载：圆点成一个空心圈，
   * 连线的两条边合起来就是那条线（线本身只有一个描边厚，两边各画一半正好填满）。
   */
  @media print {
    [data-scope='timeline'][data-part='indicator'] {
      border: var(--xh-stroke-thick) solid currentColor;
    }

    [data-scope='timeline'][data-part='connector'] {
      border: var(--xh-stroke-thin) solid currentColor;
    }
  }
}

/* styles/timer.css */
/* 定义 timer 样式。 */

/* Timer 独立皮肤同时传递引入起停钮的动作控件配方；full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='timer'] {
    --xh-timer-skin: 1;
  }

  /* 三个尺寸档只换这两个私有槽，各部件从 root 继承它们，换档不必给每个部件各写一条选择器；
     起停钮的档位由连接层直接投给家族，这里不再中转 */
  [data-scope='timer'][data-part='root'] {
    --xh-_timer-digit-size: var(--xh-text-heading-2-size);
    --xh-_timer-gap: var(--xh-space-3);

    display: inline-flex;
    align-items: center;
    gap: var(--xh-timer-gap, var(--xh-_timer-gap));
    color: var(--xh-timer-fg, var(--xh-fg-default));
  }

  /* 上面声明了 display，会盖掉 UA 的 [hidden] 规则，收起态要在这里接回来 */
  [data-scope='timer'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 尺寸 —— */
  [data-scope='timer'][data-part='root'][data-size='sm'] {
    --xh-_timer-digit-size: var(--xh-text-heading-3-size);
    --xh-_timer-gap: var(--xh-space-2);
  }

  [data-scope='timer'][data-part='root'][data-size='lg'] {
    --xh-_timer-digit-size: var(--xh-text-heading-1-size);
    --xh-_timer-gap: var(--xh-space-4);
  }

  /* —— 时间区 —— */
  /* 等宽数字：逐位宽度一致，秒数换位时分隔符与后面的段都不会左右挪动。
     direction 钉成 ltr：每段是一个独立的 flex 项，主轴方向跟着文字方向走，
     不钉住的话 rtl 页面上时分秒会整体倒过来排——时间串的读序两个方向都一样。 */
  [data-scope='timer'][data-part='display'] {
    display: inline-flex;
    align-items: baseline;
    direction: ltr;
    color: var(--xh-timer-display-fg, var(--xh-fg-default));
    /* 嵌在一句话里或摆在别人的数值槽里时把 --xh-timer-digit-font-size 写成 inherit，
       数字就跟着上下文的字号走，不再自带展示档字号 */
    font-size: var(--xh-timer-digit-font-size, var(--xh-_timer-digit-size));
    font-variant-numeric: tabular-nums;
    font-weight: var(--xh-font-weight-semibold);
    line-height: var(--xh-leading-tight);
    /* 走到点那一刻前景退一档，这里让它淡过去而不是硬跳 */
    transition: color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='timer'][data-part='display'][hidden] {
    display: none;
  }

  /* 走完之后这串数字不再是活的信息，退一档；暂停在半路的仍是要盯着看的数，不退 */
  [data-scope='timer'][data-part='display'][data-state='completed'] {
    color: var(--xh-timer-completed-fg, var(--xh-fg-muted));
  }

  /* 数字段自己一个前景槽，与记号那个成对。
     缺省是 inherit 而不是某个具体前景：时间区走完会整体退一档，
     数字段照着继承下来才跟得上，写死取值就跟不动了 */
  [data-scope='timer'][data-part='item'] {
    color: var(--xh-timer-item-fg, inherit);
  }

  /* 记号只是排版，比数字弱一档、两侧留一点气口 */
  [data-scope='timer'][data-part='separator'] {
    padding-inline: var(--xh-timer-separator-px, var(--xh-space-0_5));
    color: var(--xh-timer-separator-fg, var(--xh-fg-subtle));
    font-weight: var(--xh-font-weight-regular);
  }

  /* —— 起停按钮 ——
     带文案（或图标）的离散动作钮：盒几何、悬停 / 按下与 0.97 按压、粗指针热区、焦点环、禁用面全由
     Action Control 的 text outline 档给（连接层按 size 投档，缺省 md 一个控件高），组件只映射既有使用者槽。
     中性描边、透明底；白底承载 hover 100 → pressed 200，不抬升；焦点边由家族给，不随语气 */
  [data-scope='timer'][data-part='control'] {
    --xh-action-visual-size: var(--xh-timer-control-h, var(--xh-_action-profile-visual-size));
    --xh-action-padding-inline: var(--xh-timer-control-px, var(--xh-_action-profile-padding-inline));
    --xh-action-gap: var(--xh-timer-control-gap, var(--xh-_action-profile-gap));
    --xh-action-radius: var(--xh-timer-control-radius, var(--xh-shape-control));
    --xh-action-bg-rest: var(--xh-timer-control-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-timer-control-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-timer-control-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-bg-disabled: var(--xh-timer-control-bg-disabled, var(--xh-_action-variant-bg-disabled));
    --xh-action-fg-rest: var(--xh-timer-control-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-timer-control-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-timer-control-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-border-rest: var(--xh-timer-control-border, var(--xh-_action-variant-border-rest));
    --xh-action-border-hover: var(--xh-timer-control-border-hover, var(--xh-_action-variant-border-hover));
    --xh-action-border-pressed: var(--xh-timer-control-border-hover, var(--xh-_action-variant-border-pressed));
    --xh-action-border-focus-visible: var(--xh-timer-control-border-focus, var(--xh-_action-variant-border-focus-visible));
    --xh-action-border-disabled: var(--xh-timer-control-border-disabled, var(--xh-_action-variant-border-disabled));
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: var(--xh-timer-control-shadow-hover, none);
    --xh-action-shadow-pressed: var(--xh-timer-control-shadow-active, none);
    --xh-action-font-size: var(--xh-text-label-size);
    /* 作者塞进钮里的图标按档取字形尺寸，与文案同一把尺 */
    --xh-icon-size: var(--xh-timer-icon-size, var(--xh-_action-profile-glyph-size));

    font-weight: var(--xh-text-label-weight);
  }

  /* 家族那条 display 会把 UA 的 [hidden]{display:none} 盖掉，作者收起它时要的是这一条 */
  [data-scope='timer'][data-part='control'][hidden] {
    display: none;
  }
}

/* styles/timestamp.css */
/* 定义 timestamp 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='timestamp'] {
    --xh-timestamp-skin: 1;
  }

  [data-scope='timestamp'][data-part='root'] {
    color: var(--xh-timestamp-fg, var(--xh-fg-default));
    /* 等宽数字：秒数跳动时后面的字符不会左右挪 */
    font-variant-numeric: tabular-nums;
    /* 一个时间戳不该被拆到两行去 */
    white-space: nowrap;
    /* 时刻换成认不出的值时前景要换档，这里让它淡过去而不是硬跳 */
    transition: color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 相对说法是一句话不是一串数字，等宽数字反而把字距拉开 */
  [data-scope='timestamp'][data-part='root'][data-relative] {
    font-variant-numeric: normal;
  }

  /* 没给时刻、或给了认不出的时刻：这时显示的是作者写在节点里的兜底文案，退成弱前景 */
  [data-scope='timestamp'][data-part='root'][data-state='empty'],
  [data-scope='timestamp'][data-part='root'][data-state='invalid'] {
    color: var(--xh-timestamp-placeholder-fg, var(--xh-fg-muted));
  }
}

/* styles/truncate.css */
/* 定义 truncate 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='truncate'] {
    --xh-truncate-skin: 1;
  }

  /* 单行：一行装不下就收成省略号。
     行数由连接层写进这个盒子的内联 style，样式表这一行只是它缺席时的落点 */
  [data-scope='truncate'][data-part='root'] {
    --xh-_truncate-lines: 1;

    display: block;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  /* 多行：按行数裁，裁掉的那一行末尾收省略号 */
  [data-scope='truncate'][data-part='root'][data-multiline] {
    display: -webkit-box;
    overflow: hidden;
    -webkit-box-orient: vertical;
    /* 使用者槽排在前面：连接层把行数写成根上的内联私有槽，
       在外层写一句 --xh-truncate-lines 即可整片改档，不必逐处改标记 */
    -webkit-line-clamp: var(--xh-truncate-lines, var(--xh-_truncate-lines));
    white-space: normal;
    /* 一长串没有断点的字符（网址、编号）也得断开，否则它一路撑出去，裁不住 */
    overflow-wrap: break-word;
  }

  /* 铺开：裁剪整个撤掉。写在两档之后，压得住上面同权重的那两条 */
  [data-scope='truncate'][data-part='root'][data-state='open'] {
    display: block;
    overflow: visible;
    white-space: normal;
  }

  /* 真被裁了才是那颗按钮：装得下的短文本按下去什么都不变，摆出手型等于许一个按不动的按钮。
     铺开态另收一条——那一档量不出"被裁"，但收回去的入口必须留着 */
  [data-scope='truncate'][data-part='root'][data-expandable][data-overflowing],
  [data-scope='truncate'][data-part='root'][data-expandable][data-state='open'] {
    cursor: pointer;
    transition: color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 是按钮的那一档才提亮：指针停在上面时这段文字与正文分开，
     按不动的短文本不给这个反馈 */
  [data-scope='truncate'][data-part='root'][data-expandable][data-overflowing]:hover,
  [data-scope='truncate'][data-part='root'][data-expandable][data-state='open']:hover {
    color: var(--xh-fg-default);
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='truncate'][data-part='root'][hidden] {
    display: none;
  }
}

/* styles/typography.css */
/* 定义 typography 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='typography'] {
    --xh-typography-skin: 1;
  }

  [data-scope='typography'][data-part='root'] {
    /* 尺寸档只换这几个私有槽，各段从根上继承它们，换档不必给每个部件各写一条选择器 */
    --xh-_typography-body-size: var(--xh-text-body-size);
    --xh-_typography-block-gap: var(--xh-space-4);
    --xh-_typography-heading-gap: var(--xh-space-6);
    --xh-_typography-h1: var(--xh-font-size-3xl);
    --xh-_typography-h2: var(--xh-font-size-2xl);
    --xh-_typography-h3: var(--xh-font-size-xl);
    --xh-_typography-h4: var(--xh-font-size-lg);
    --xh-_typography-h5: var(--xh-font-size-md);
    --xh-_typography-h6: var(--xh-font-size-sm);
    /* 读行宽度：整块正文不收窄就会拉成一行行难读的长句 */
    --xh-_typography-measure: 68ch;
    /* 行内代码跟着所在那行的字号缩：以「随文字走」的字形尺寸为基数按比例收一点，不取固定档位 */
    --xh-_typography-code-size: calc(var(--xh-glyph-size-text) * 0.9);

    /* 建块级格式化上下文，段落的外边距不越过根往外塌 */
    display: flow-root;
    max-inline-size: var(--xh-typography-measure, var(--xh-_typography-measure));
    color: var(--xh-typography-fg, var(--xh-fg-default));
    font-size: var(--xh-typography-font-size, var(--xh-_typography-body-size));
    font-weight: var(--xh-typography-font-weight, var(--xh-text-body-weight));
    line-height: var(--xh-typography-leading, var(--xh-text-body-leading));
  }

  /* 上面声明了 display，会盖掉 UA 的 [hidden] 规则，收起态要在这里接回来 */
  [data-scope='typography'][data-part='root'][hidden] {
    display: none;
  }

  /* 中间没有断点的长串——网址、令牌、无空格的标识——排到行尾就断开，不把整块正文顶宽。
     属性由后代继承，这里逐个部件写一遍，是为了任一部件单独用时也盖得到 */
  [data-scope='typography']:is([data-part='root'], [data-part='heading'], [data-part='paragraph'], [data-part='prose']) {
    overflow-wrap: break-word;
  }

  /* —— 尺寸 —— */
  /* 小档整体降一级字号档位 */
  [data-scope='typography'][data-part='root'][data-size='sm'] {
    --xh-_typography-body-size: var(--xh-font-size-sm);
    --xh-_typography-block-gap: var(--xh-space-3);
    --xh-_typography-heading-gap: var(--xh-space-5);
    --xh-_typography-h1: var(--xh-font-size-2xl);
    --xh-_typography-h2: var(--xh-font-size-xl);
    --xh-_typography-h3: var(--xh-font-size-lg);
    --xh-_typography-h4: var(--xh-font-size-md);
    --xh-_typography-h5: var(--xh-font-size-sm);
    --xh-_typography-h6: var(--xh-font-size-xs);
  }

  /* 大档只放大正文与段距：标题档位在 3xl 见顶，六档保持原样 */
  [data-scope='typography'][data-part='root'][data-size='lg'] {
    --xh-_typography-body-size: var(--xh-font-size-lg);
    --xh-_typography-block-gap: var(--xh-space-5);
    --xh-_typography-heading-gap: var(--xh-space-8);
  }

  /* —— 对齐与字重 —— */
  /* 两轴都画在根上，整块正文一起换；各段沿继承拿到 */
  [data-scope='typography'][data-part='root'][data-align='start'] {
    text-align: start;
  }

  [data-scope='typography'][data-part='root'][data-align='center'] {
    text-align: center;
  }

  [data-scope='typography'][data-part='root'][data-align='end'] {
    text-align: end;
  }

  [data-scope='typography'][data-part='root'][data-align='justify'] {
    text-align: justify;
  }

  [data-scope='typography'][data-part='root'][data-weight='regular'] {
    font-weight: var(--xh-typography-font-weight, var(--xh-font-weight-regular));
  }

  [data-scope='typography'][data-part='root'][data-weight='medium'] {
    font-weight: var(--xh-typography-font-weight, var(--xh-font-weight-medium));
  }

  [data-scope='typography'][data-part='root'][data-weight='semibold'] {
    font-weight: var(--xh-typography-font-weight, var(--xh-font-weight-semibold));
  }

  [data-scope='typography'][data-part='root'][data-weight='bold'] {
    font-weight: var(--xh-typography-font-weight, var(--xh-font-weight-bold));
  }

  /* —— 块级段落 —— */
  /* 库里没有全局 preflight，作者写的 hN / p 带着 UA 外边距，在这儿抹平 */
  [data-scope='typography'][data-part='heading'],
  [data-scope='typography'][data-part='paragraph'] {
    margin: 0;
  }

  [data-scope='typography'][data-part='heading'] {
    color: var(--xh-typography-heading-fg, var(--xh-fg-default));
    font-size: var(--xh-typography-heading-font-size, var(--xh-_typography-h3));
    font-weight: var(--xh-typography-heading-font-weight, var(--xh-font-weight-semibold));
    line-height: var(--xh-typography-heading-leading, var(--xh-leading-tight));
    /* 标题折行时把各行拉得一样长 */
    text-wrap: balance;
  }

  /* —— 标题档位 —— */
  /* 使用者槽位排在档位之前：写死一个值即盖过全部六档 */
  [data-scope='typography'][data-part='heading'][data-level='1'] {
    font-size: var(--xh-typography-heading-font-size, var(--xh-_typography-h1));
  }

  [data-scope='typography'][data-part='heading'][data-level='2'] {
    font-size: var(--xh-typography-heading-font-size, var(--xh-_typography-h2));
  }

  [data-scope='typography'][data-part='heading'][data-level='3'] {
    font-size: var(--xh-typography-heading-font-size, var(--xh-_typography-h3));
  }

  [data-scope='typography'][data-part='heading'][data-level='4'] {
    font-size: var(--xh-typography-heading-font-size, var(--xh-_typography-h4));
  }

  [data-scope='typography'][data-part='heading'][data-level='5'] {
    font-size: var(--xh-typography-heading-font-size, var(--xh-_typography-h5));
  }

  [data-scope='typography'][data-part='heading'][data-level='6'] {
    font-size: var(--xh-typography-heading-font-size, var(--xh-_typography-h6));
  }

  /* —— 段间距 —— */
  /* 间距画在后一块的上边，块与块之间只留一份，正文末尾也不多出一截 */
  [data-scope='typography']:is([data-part='heading'], [data-part='paragraph'])
    + [data-scope='typography']:is([data-part='heading'], [data-part='paragraph']) {
    margin-block-start: var(--xh-typography-block-gap, var(--xh-_typography-block-gap));
  }

  /* 标题上面留得更开，它带起的是下面一整段 */
  [data-scope='typography']:is([data-part='heading'], [data-part='paragraph'])
    + [data-scope='typography'][data-part='heading'] {
    margin-block-start: var(--xh-typography-heading-gap, var(--xh-_typography-heading-gap));
  }

  /* —— 行内文字 —— */
  /* 不写形态与语气时就是一段普通正文，这里只声明形态各自加的那一层 */
  /* 次要文字与语气文字各有各的槽：两者同特异度、共用一个槽的话，
     调淡次要文字会把六族语气一并换成同一个灰。 */
  [data-scope='typography'][data-part='text'][data-variant='muted'] {
    color: var(--xh-typography-text-fg-muted, var(--xh-fg-muted));
  }

  [data-scope='typography'][data-part='text'][data-variant='strong'] {
    font-weight: var(--xh-typography-text-font-weight, var(--xh-font-weight-semibold));
  }

  [data-scope='typography'][data-part='text'][data-variant='code'] {
    padding-block: var(--xh-typography-code-py, var(--xh-space-0_5));
    padding-inline: var(--xh-typography-code-px, var(--xh-space-1));
    border-radius: var(--xh-typography-code-radius, var(--xh-shape-inset));
    background: var(--xh-typography-code-bg, var(--xh-bg-subtle));
    font-family: var(--xh-typography-code-font, var(--xh-font-family-mono));
    font-size: var(--xh-typography-code-font-size, var(--xh-_typography-code-size));
  }

  /* 语气排在形态之后：两个轴一起写时，用哪族颜色由语气说了算 */
  [data-scope='typography'][data-part='text'][data-tone] {
    color: var(--xh-typography-text-fg-tone, var(--xh-_tone-fg));
  }

  /* 字重排在形态之后：与 strong 一起写时，粗到哪一档由字重说了算 */
  [data-scope='typography'][data-part='text'][data-weight='regular'] {
    font-weight: var(--xh-font-weight-regular);
  }

  [data-scope='typography'][data-part='text'][data-weight='medium'] {
    font-weight: var(--xh-font-weight-medium);
  }

  [data-scope='typography'][data-part='text'][data-weight='semibold'] {
    font-weight: var(--xh-font-weight-semibold);
  }

  [data-scope='typography'][data-part='text'][data-weight='bold'] {
    font-weight: var(--xh-font-weight-bold);
  }

  /* —— 行内链接 —— */
  [data-scope='typography'][data-part='link'] {
    border-radius: var(--xh-typography-link-radius, var(--xh-shape-inset));
    color: var(--xh-typography-link-fg, var(--xh-fg-brand));
    text-decoration: underline;
    text-underline-offset: var(--xh-typography-link-underline-offset, var(--xh-space-0_5));
    transition: color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 悬停只在能用指针的设备上生效，触摸端不留一个按不掉的悬停态 */
  @media (hover: hover) {
    [data-scope='typography'][data-part='link']:hover {
      color: var(--xh-typography-link-fg-hover, var(--xh-fg-brand-strong));
    }
  }

  /* —— 富文本 —— */
  /*
   * 外来的整段 HTML 铺在这里：Markdown 渲染结果、后端返回的富文本，节点由内容自己带，
   * 作者写不出 data-part，所以样式按标签给。
   *
   * 标签一律包进 :where()，整条规则的特异度只剩 prose 这一层，块里嵌 XiHan 组件时
   * 那份皮肤仍然赢。字号档位与段间距取根上那几支私有槽，跟着 data-size 一起换。
   */
  [data-scope='typography'][data-part='prose'] {
    color: var(--xh-typography-prose-fg, var(--xh-fg-default));
    font-size: var(--xh-typography-prose-font-size, var(--xh-_typography-body-size));
    line-height: var(--xh-typography-prose-leading, var(--xh-text-prose-leading));
  }

  /* 库里没有全局 preflight，外来节点带着 UA 外边距，先在这儿抹平 */
  [data-scope='typography'][data-part='prose']
    :where(h1, h2, h3, h4, h5, h6, p, ul, ol, pre, blockquote, table, hr) {
    margin: 0;
  }

  /* 间距画在后一块的上边，块与块之间只留一份，末块也不多出一截 */
  [data-scope='typography'][data-part='prose']
    :where(h1, h2, h3, h4, h5, h6, p, ul, ol, pre, blockquote, table, hr)
    + :where(h1, h2, h3, h4, h5, h6, p, ul, ol, pre, blockquote, table, hr) {
    margin-block-start: var(--xh-typography-prose-block-gap, var(--xh-_typography-block-gap));
  }

  /* 标题上面留得更开，它带起的是下面一整段 */
  [data-scope='typography'][data-part='prose']
    :where(h1, h2, h3, h4, h5, h6, p, ul, ol, pre, blockquote, table, hr)
    + :where(h1, h2, h3, h4, h5, h6) {
    margin-block-start: var(--xh-typography-prose-heading-gap, var(--xh-_typography-heading-gap));
  }

  [data-scope='typography'][data-part='prose'] :where(h1, h2, h3, h4, h5, h6) {
    color: var(--xh-typography-prose-heading-fg, var(--xh-fg-default));
    font-weight: var(--xh-typography-prose-heading-font-weight, var(--xh-font-weight-semibold));
    line-height: var(--xh-leading-tight);
    text-wrap: balance;
  }

  /* 六档字号与 heading 部件同源：同一块正文里，作者写的标题与外来的标题一样大 */
  [data-scope='typography'][data-part='prose'] :where(h1) {
    font-size: var(--xh-typography-prose-h1, var(--xh-_typography-h1));
  }

  [data-scope='typography'][data-part='prose'] :where(h2) {
    font-size: var(--xh-typography-prose-h2, var(--xh-_typography-h2));
  }

  [data-scope='typography'][data-part='prose'] :where(h3) {
    font-size: var(--xh-typography-prose-h3, var(--xh-_typography-h3));
  }

  [data-scope='typography'][data-part='prose'] :where(h4) {
    font-size: var(--xh-typography-prose-h4, var(--xh-_typography-h4));
  }

  [data-scope='typography'][data-part='prose'] :where(h5) {
    font-size: var(--xh-typography-prose-h5, var(--xh-_typography-h5));
  }

  [data-scope='typography'][data-part='prose'] :where(h6) {
    font-size: var(--xh-typography-prose-h6, var(--xh-_typography-h6));
  }

  /* 列表：项目符号要留在容器里面，缩进画在列表自己的起始内衬上 */
  [data-scope='typography'][data-part='prose'] :where(ul, ol) {
    padding-inline-start: var(--xh-typography-prose-list-ps, var(--xh-space-6));
  }

  [data-scope='typography'][data-part='prose'] :where(li + li) {
    margin-block-start: var(--xh-typography-prose-item-gap, var(--xh-space-1));
  }

  /* 嵌套列表贴着上一项走，不按块与块之间那一档拉开 */
  [data-scope='typography'][data-part='prose'] :where(li) > :where(ul, ol) {
    margin-block-start: var(--xh-typography-prose-item-gap, var(--xh-space-1));
  }

  /* 富文本里的链接缺省跟着 link 部件走：同一块正文里两处不同源就会有两种链接样式 */
  [data-scope='typography'][data-part='prose'] :where(a) {
    border-radius: var(--xh-typography-prose-link-radius, var(--xh-typography-link-radius, var(--xh-shape-inset)));
    color: var(--xh-typography-prose-link-fg, var(--xh-typography-link-fg, var(--xh-fg-brand)));
    text-decoration: underline;
    text-underline-offset: var(
      --xh-typography-prose-link-underline-offset,
      var(--xh-typography-link-underline-offset, var(--xh-space-0_5))
    );
  }

  [data-scope='typography'][data-part='prose'] :where(strong) {
    font-weight: var(--xh-typography-prose-strong-font-weight, var(--xh-font-weight-semibold));
  }

  /* 行内代码与 text 部件的 code 形态同源，同一块正文里两条路写出来一个样 */
  [data-scope='typography'][data-part='prose'] :where(code) {
    padding-block: var(--xh-typography-code-py, var(--xh-space-0_5));
    padding-inline: var(--xh-typography-code-px, var(--xh-space-1));
    border-radius: var(--xh-typography-code-radius, var(--xh-shape-inset));
    background: var(--xh-typography-code-bg, var(--xh-bg-subtle));
    font-family: var(--xh-typography-code-font, var(--xh-font-family-mono));
    font-size: var(--xh-typography-code-font-size, var(--xh-_typography-code-size));
  }

  /* 代码块自己成一片面，长行横向滚动而不是把整块正文撑宽 */
  [data-scope='typography'][data-part='prose'] :where(pre) {
    overflow-x: auto;
    padding: var(--xh-typography-prose-pre-padding, var(--xh-space-4));
    border-radius: var(--xh-typography-prose-pre-radius, var(--xh-shape-surface));
    background: var(--xh-typography-prose-pre-bg, var(--xh-bg-subtle));
    font-family: var(--xh-typography-code-font, var(--xh-font-family-mono));
    font-size: var(--xh-typography-code-font-size, var(--xh-_typography-code-size));
  }

  /* 代码块里的 code 已经在 pre 那片面里，不再各自套一层内衬与底色 */
  [data-scope='typography'][data-part='prose'] :where(pre) :where(code) {
    padding: 0;
    border-radius: 0;
    background: none;
    font-size: inherit;
  }

  [data-scope='typography'][data-part='prose'] :where(blockquote) {
    padding-inline-start: var(--xh-typography-prose-quote-ps, var(--xh-space-4));
    border-inline-start: var(--xh-stroke-thick) solid
      var(--xh-typography-prose-quote-border, var(--xh-border-subtle));
    color: var(--xh-typography-prose-quote-fg, var(--xh-fg-muted));
  }

  [data-scope='typography'][data-part='prose'] :where(hr) {
    border: none;
    border-block-start: var(--xh-stroke-thin) solid
      var(--xh-typography-prose-rule-border, var(--xh-border-subtle));
  }

  /* 图片不许把整块正文撑宽，高度跟着缩才不变形 */
  [data-scope='typography'][data-part='prose'] :where(img) {
    max-inline-size: 100%;
    block-size: auto;
  }

  [data-scope='typography'][data-part='prose'] :where(table) {
    inline-size: 100%;
    border-collapse: collapse;
  }

  [data-scope='typography'][data-part='prose'] :where(th, td) {
    padding-block: var(--xh-typography-prose-cell-py, var(--xh-space-2));
    padding-inline: var(--xh-typography-prose-cell-px, var(--xh-space-3));
    border-block-end: var(--xh-stroke-thin) solid
      var(--xh-typography-prose-cell-border, var(--xh-border-subtle));
    text-align: start;
    /* 表格的宽度由各格的最小宽度撑出来，格里的长串断得开，整张表才收得进正文的宽度 */
    overflow-wrap: anywhere;
  }

  [data-scope='typography'][data-part='prose'] :where(th) {
    font-weight: var(--xh-typography-prose-th-font-weight, var(--xh-font-weight-semibold));
  }
}

/* styles/undefined.css */
/*
 * 元素升级前的形态。
 *
 * 收起态由元素在 wire() 里用内联 display 做，而 data-scope / data-part 也是那一刻才打上，
 * 所以 JS 到达之前这段子树既没有皮肤也没有收起——内容会以裸文本堆在页面流里，
 * 并被搜索引擎与读屏当作正文。SSR / SSG 直出时这段时间尤其长。
 *
 * 这里按作者写的 data-xh-part 选中，那是升级前唯一存在的标记。
 * 名单与元素的对应由 check-undefined-guard.mjs 双向守着。
 */
@layer xihan.components {
  :where(
    xh-accordion,
    xh-cascader,
    xh-collapsible,
    xh-color-picker,
    xh-combobox,
    xh-command,
    xh-context-menu,
    xh-date-picker,
    xh-date-range-picker,
    xh-dialog,
    xh-drawer,
    xh-floating-panel,
    xh-hover-card,
    xh-image-viewer,
    xh-mention,
    xh-menu,
    xh-menubar,
    xh-navigation-menu,
    xh-pagination,
    xh-popconfirm,
    xh-popover,
    xh-reasoning,
    xh-select,
    xh-side-nav,
    xh-steps,
    xh-time-picker,
    xh-time-range-picker,
    xh-tool-call,
    xh-tooltip,
    xh-tour,
    xh-tree-select
  ):not(:defined)
    :where(
      [data-xh-part='backdrop'],
      [data-xh-part='content'],
      [data-xh-part='positioner'],
      [data-xh-part='viewport']
    ) {
    display: none;
  }
}

/* styles/visually-hidden.css */
/* 定义 visually hidden 样式。 */

@layer xihan.components {
  .xh-visually-hidden {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }
}

/* styles/tone.css */
/*
 * 语气层：与组件无关，全库共用一份。
 *
 * 三个视觉轴各管一件事，互不干涉：
 *   data-variant  形态  solid / subtle / outline / ghost —— 颜色怎么用
 *   data-tone     语气  brand / neutral / success / warning / danger / info —— 用哪族颜色
 *   data-size     尺寸  sm / md / lg
 *
 * 这里只声明私有槽，各组件的形态规则去消费。所以加一个语气是改这一处 6 条规则，
 * 而不是逐个组件写 6 遍。
 *
 * --xh-_tone-on 是实心底上的前景色，--xh-_tone-shift 是交互态要往哪个方向挪
 * （永远背离前景色走，悬停与按下才不会反过来压低对比度）。两者都由 --xh-_tone 现推：
 * 按 WCAG 的权重算出语气色的相对亮度，低于 0.179 配白字、高于配深字，shift 取反面。
 * 0.179 是白字与黑字对比度相等的那一点，解析解。
 *
 * --xh-_tone-on 还有第二个消费者：实心面上的聚焦环取的是这块面配对的前景色（见 focus.css），
 * 部件没写 color 的那几档直接把这一支写进环色槽。所以它同时管着字与环两件事。
 * 环本身不接语气：语气只决定面是哪一族色，不决定环是什么色。
 *
 * 现推是因为语气色可换肤：写死的分派只对本仓这套 600 档成立，使用者换一套调色板
 * 配对就不再成立，而门禁只验本仓的色，换肤后的失配一路绿灯。
 *
 * 够不到相对颜色语法的引擎退回逐族写死的那一份，取值是本仓这套色的实测结果：
 * 600 档上白字对 brand 5.08、neutral 7.80、danger 4.83 达标，而 success 3.04、
 * warning 2.70、info 3.47 都不到 4.5，这三族配深字。兜底那一份用的是固定原语而不是
 * --xh-fg-default：实心底本身是原语色、不随主题翻，配色若跟着主题翻，暗色下就会变成
 * 白字压在浅黄底上（实测对比度 2.70）。
 *
 * brand 是例外：那一族的色相归使用者，所以它的底与前景走 --xh-bg-brand / --xh-fg-on-brand
 * 这两个语义令牌。缺省主题下它们就解析成 brand-600 与 neutral-0，与其余五族同值；
 * 改写过品牌色的使用者只改这两个令牌，实心底与它上面的字就一起跟着走。
 * 底与前景既然随主题翻，brand 的 shift 也必须随主题翻——现推那一档自动跟着底色走，
 * 文件末尾那条深色覆盖是给兜底那一档用的。
 */
@layer xihan.components {
  [data-tone] {
    /* 先给一份中性缺省：写了 data-tone 却拼错取值时退成中性，
       而不是让 --xh-_tone 悬空——悬空会让下面每条 color-mix 变成计算期无效，
       用它的声明会整条失效，且 var() 兜底也救不回来（槽位是「已声明但无效」）。 */
    --xh-_tone: var(--xh-color-neutral-600);
    --xh-_tone-on: var(--xh-color-neutral-0);
    --xh-_tone-shift: var(--xh-color-neutral-950);

    /* 交互态与淡底都从主色兑出来，兑的对象是主题色，深浅两态自动跟随 */
    --xh-_tone-hover: color-mix(in oklab, var(--xh-_tone) 88%, var(--xh-_tone-shift));
    --xh-_tone-active: color-mix(in oklab, var(--xh-_tone) 78%, var(--xh-_tone-shift));
    --xh-_tone-subtle: color-mix(in oklab, var(--xh-_tone) 12%, var(--xh-bg-surface));
    --xh-_tone-subtle-hover: color-mix(in oklab, var(--xh-_tone) 20%, var(--xh-bg-surface));
    --xh-_tone-subtle-active: color-mix(in oklab, var(--xh-_tone) 28%, var(--xh-bg-surface));
    --xh-_tone-border: color-mix(in oklab, var(--xh-_tone) 40%, var(--xh-bg-surface));
    /* 控件的可操作区边界要 3:1，兑了底色的 --xh-_tone-border 六族全在 1.44–2.18，够不着。
       这一支直接取主色本体；两族在各自的底上仍不够，在下面按主题单独兜 */
    --xh-_tone-border-control: var(--xh-_tone);
    /* 装饰性强调（色条、指示条、锚点高亮这类）是非文字图形，同样要 3:1，
       要求与可操作区边界一模一样，就直接跟着那一支走，连它按主题兜的两族一并继承。
       要读得清的状态文字不在此列，那些走 --xh-_tone-fg */
    --xh-_tone-soft: var(--xh-_tone-border-control);
    /* 在普通背景上表达该语气的文字色：往前景色兑，浅色态变深、深色态变浅。
       兑到 60% 是实测出来的：这一档要同时压得住淡底的静态/悬停/按下三态、面与抬起的面
       共五种底，72% 时六族里有三族够不到 4.5（最低 3.66），60% 全部达标且留有余量 */
    --xh-_tone-fg: color-mix(in oklab, var(--xh-_tone) 60%, var(--xh-fg-default));
  }

  [data-tone='brand'] {
    --xh-_tone: var(--xh-bg-brand);
    --xh-_tone-on: var(--xh-fg-on-brand);
    --xh-_tone-shift: var(--xh-color-neutral-950);
  }

  [data-tone='neutral'] {
    --xh-_tone: var(--xh-color-neutral-600);
    --xh-_tone-on: var(--xh-color-neutral-0);
    --xh-_tone-shift: var(--xh-color-neutral-950);
  }

  [data-tone='danger'] {
    --xh-_tone: var(--xh-color-danger-600);
    --xh-_tone-on: var(--xh-color-neutral-0);
    --xh-_tone-shift: var(--xh-color-neutral-950);
  }

  [data-tone='success'] {
    --xh-_tone: var(--xh-color-success-600);
    --xh-_tone-on: var(--xh-color-neutral-950);
    --xh-_tone-shift: var(--xh-color-neutral-0);
  }

  [data-tone='warning'] {
    --xh-_tone: var(--xh-color-warning-600);
    --xh-_tone-on: var(--xh-color-neutral-950);
    --xh-_tone-shift: var(--xh-color-neutral-0);
  }

  [data-tone='info'] {
    --xh-_tone: var(--xh-color-info-600);
    --xh-_tone-on: var(--xh-color-neutral-950);
    --xh-_tone-shift: var(--xh-color-neutral-0);
  }

  /* 主色本体在各自的底上有两族够不到 3:1：黄在白底上只有 2.70，中性在深色底上只有 2.54。
     语气色是固定原语、不随主题翻，所以这两族只能按主题各兜一次。
     浅色是缺省态（不写 data-theme 也算浅色），深色靠属性选择器压过它。
     data-theme 写在语气容器自己身上还是写在祖先上都算，两种用法都成立 */
  [data-tone='warning'] {
    --xh-_tone-border-control: var(--xh-color-warning-700);
  }

  :is([data-theme='dark'] *, [data-theme='dark'])[data-tone='warning'] {
    --xh-_tone-border-control: var(--xh-color-warning-600);
  }

  [data-tone='neutral'] {
    --xh-_tone-border-control: var(--xh-color-neutral-600);
  }

  :is([data-theme='dark'] *, [data-theme='dark'])[data-tone='neutral'] {
    --xh-_tone-border-control: var(--xh-color-neutral-550);
  }

  /* 把语气色转成线性 sRGB 分量、按 WCAG 的权重算出相对亮度：低于 0.179 前景取白、
     高于取黑，挪动方向取前景的反面。三个通道写同一个式子，算出来的是纯白或纯黑；
     alpha 显式写 1，不然会连语气色的透明度一起继承过来。
     探针按这里实际用到的整个形态测，只测得起 color(from …) 的引擎不会落进半截支持。
     上面各族写死的那一份是兜底：引擎不认这条语法时整块丢弃，退回那一份 */
  @supports (color: color(from red srgb-linear clamp(0, (0.179 - (0.2126 * r + 0.7152 * g + 0.0722 * b)) * infinity, 1) 0 0 / 1)) {
    [data-tone] {
      --xh-_tone-on: color(from var(--xh-_tone) srgb-linear
        clamp(0, (0.179 - (0.2126 * r + 0.7152 * g + 0.0722 * b)) * infinity, 1)
        clamp(0, (0.179 - (0.2126 * r + 0.7152 * g + 0.0722 * b)) * infinity, 1)
        clamp(0, (0.179 - (0.2126 * r + 0.7152 * g + 0.0722 * b)) * infinity, 1) / 1);
      --xh-_tone-shift: color(from var(--xh-_tone) srgb-linear
        clamp(0, ((0.2126 * r + 0.7152 * g + 0.0722 * b) - 0.179) * infinity, 1)
        clamp(0, ((0.2126 * r + 0.7152 * g + 0.0722 * b) - 0.179) * infinity, 1)
        clamp(0, ((0.2126 * r + 0.7152 * g + 0.0722 * b) - 0.179) * infinity, 1) / 1);
    }
  }

  /* brand 的底与前景走语义令牌、随主题翻，所以它的 shift 也必须跟着翻，
     否则深色下前景是深字而 shift 仍往深处挪，悬停与按下反而压低对比度
     （实测 5.29 → 4.25 → 3.49，而不写 tone 的品牌链是 5.29 → 7.33 → 10.85）。
     其余五族的底是固定原语、不随主题翻，shift 也就不必翻 */
  :is([data-theme='dark'] *, [data-theme='dark'])[data-tone='brand'] {
    --xh-_tone-shift: var(--xh-color-neutral-0);
  }

  /* 语气轴对外的那一族：上面每支私有槽一对一指过来，取值恒等。
     使用者在自己的节点上写 data-tone，就能在那个节点里取到整族颜色，
     六族与深浅两态都跟着上面的推导走。
     --xh-_tone-shift 是兑色的方向、不是一档颜色，不出公开令牌。
     声明在 [data-tone] 上而不是 :root 上：值里带 var()，自定义属性的 var()
     在「声明它的那个元素」上就替换掉了，落在 :root 上会把语气冻死在根元素。 */
  [data-tone] {
    --xh-tone-solid: var(--xh-_tone);
    --xh-tone-solid-hover: var(--xh-_tone-hover);
    --xh-tone-solid-active: var(--xh-_tone-active);
    --xh-tone-on: var(--xh-_tone-on);
    --xh-tone-subtle: var(--xh-_tone-subtle);
    --xh-tone-subtle-hover: var(--xh-_tone-subtle-hover);
    --xh-tone-subtle-active: var(--xh-_tone-subtle-active);
    --xh-tone-fg: var(--xh-_tone-fg);
    --xh-tone-border: var(--xh-_tone-border);
    --xh-tone-border-control: var(--xh-_tone-border-control);
    --xh-tone-soft: var(--xh-_tone-soft);
  }

  /* 实心面顶边的内高光：一条极浅的内阴影，把一块实心底衬出厚度。
     全库十六处实心档共用这两条，别再逐个组件把式子抄一遍。

     两条的差别只在取哪个前景色：--xh-_highlight-tone 跟着语气走（实心底上的前景色，
     没写语气时退回品牌那一档），--xh-_highlight-brand 恒取品牌色——底色本身不跟语气走的
     那几处（表单提交、引导主按钮、不带语气的实心标签）用它。

     声明在 :where([data-scope]) 上而不是 :root 上：它俩的值里带 var()，而自定义属性的
     var() 在「声明它的那个元素」上就替换掉了。落在 :root 上，--xh-_tone-on 与
     --xh-fg-on-brand 就都按根元素解析，语气与嵌套主题一并冻死；逐元素声明才是现取。
     同理它也不能收成 tokens 那边的一支令牌。 */
  :where([data-scope]) {
    --xh-_highlight-tone: inset 0 var(--xh-stroke-thin) 0 0
      color-mix(in oklab, var(--xh-_tone-on, var(--xh-fg-on-brand)) 14%, transparent);
    --xh-_highlight-brand: inset 0 var(--xh-stroke-thin) 0 0
      color-mix(in oklab, var(--xh-fg-on-brand) 14%, transparent);
  }
}

/* styles/liquid.css */
/*
 * 液态材质层：与组件无关，全库共用一份。
 *
 * data-material="liquid" 下，连接层投影了 data-xh-liquid 的导航层部件（浮动钮、回到顶部等浮在内容之上的控制面）
 * 换成液态面。这里只声明私有槽，各组件皮肤在自己的部件上把 Action Control 的桥接槽指过来；standard 档下
 * 这些槽没人读，部件保持原材质。
 *
 * 静态形态（服务端、挂载前，或液态面还没判定下层）：色调随主题极性，不透明度取可读下限，这一档对任何
 * 下层都保证标签 4.5:1。组件的状态机把部件挂进 core 的液态面，由它按下层在部件上写：
 *   data-xh-ink              dark / light：部件成为黑墨或白墨域。墨色域本身是浅色 / 深色主题边界，
 *                            按主题取值的液态通道随之落到那一种色调
 *   data-xh-liquid-clarity   clear：下层均匀且色调已知，换通透档
 *   --xh-_liquid-light-x / -y 光源方向的单位向量，决定 1px 亮边落在哪一侧
 */
@layer xihan.components {
  :where([data-material='liquid']) [data-xh-liquid] {
    /* 光源缺省在左上方 */
    --xh-_liquid-light-x: -0.71;
    --xh-_liquid-light-y: -0.71;
    --xh-_liquid-bg: var(--xh-material-liquid-bg);
    /* 1px 亮边是两层零模糊内阴影：阴影形状朝背光方向偏移，露出的一弯落在朝光源的一侧，
       另一层反过来偏移，在背光一侧留一道弱亮边。面内不加高光 */
    --xh-_liquid-rim:
      inset calc(var(--xh-_liquid-light-x) * var(--xh-stroke-thin) * -1) calc(var(--xh-_liquid-light-y) * var(--xh-stroke-thin) * -1) 0 0 var(--xh-material-liquid-highlight),
      inset calc(var(--xh-_liquid-light-x) * var(--xh-stroke-thin)) calc(var(--xh-_liquid-light-y) * var(--xh-stroke-thin)) 0 0 var(--xh-material-liquid-rim-far);
    --xh-_liquid-shadow: var(--xh-_liquid-rim), var(--xh-material-liquid-shadow);
    /* 交互阶梯往部件自己的前景色兑：浅色调变深、深色调变浅 */
    --xh-_liquid-bg-hover: color-mix(in oklab, var(--xh-_liquid-bg), var(--xh-material-liquid-fg) 8%);
    --xh-_liquid-bg-pressed: color-mix(in oklab, var(--xh-_liquid-bg), var(--xh-material-liquid-fg) 14%);
  }

  /* 通透档：下层均匀且色调已知时由液态面写上，着色按主题取值，已随墨色域落到对应色调 */
  :where([data-material='liquid']) [data-xh-liquid][data-xh-liquid-clarity='clear'] {
    --xh-_liquid-bg: color-mix(in oklab, var(--xh-material-liquid-tint) calc(var(--xh-material-liquid-alpha-clear) * 100%), transparent);
  }

  /* 从右往左排版时光源缺省在右上方 */
  :where([dir='rtl']) :where([data-material='liquid']) [data-xh-liquid],
  :where([data-material='liquid']) :where([dir='rtl']) [data-xh-liquid] {
    --xh-_liquid-light-x: 0.71;
  }
}

/* styles/alert.css */
/* 定义 alert 样式。 */

/* Alert 独立皮肤同时传递引入关闭钮的动作控件配方；full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='alert'] {
    --xh-alert-skin: 1;
  }

  /* 提示本体是一层中性 surface：边界由 --xh-border-default 描边承担、无影（静态反馈面），
     语气只落到图标与标题，不会用整块彩底抢走正文层级。 */
  [data-scope='alert'][data-part='root'] {
    /* 作者塞进指示符槽的图标与皮肤画的兜底字形同一把尺：Feedback 指示符统一 md 档 */
    --xh-icon-size: var(--xh-alert-icon-size, var(--xh-glyph-size-md));

    display: flex;
    align-items: flex-start;
    gap: var(--xh-alert-gap, var(--xh-space-4));
    padding-block: var(--xh-alert-py, var(--xh-surface-py-sm));
    padding-inline: var(--xh-alert-px, var(--xh-surface-px-sm));
    border: var(--xh-stroke-thin) solid var(--xh-alert-border, var(--xh-border-default));
    border-radius: var(--xh-alert-radius, var(--xh-shape-surface));
    background: var(--xh-alert-bg, var(--xh-bg-surface));
    box-shadow: var(--xh-alert-shadow, none);
    color: var(--xh-alert-fg, var(--xh-fg-default));
    font-size: var(--xh-alert-font-size, var(--xh-text-body-size));
    line-height: var(--xh-alert-leading, var(--xh-leading-normal));
  }

  /* 收起态连接层给的是 hidden 属性，而上面声明了 display——
     漏掉这条，关掉的提示还会一直摊在页面上 */
  [data-scope='alert'][data-part='root'][hidden] {
    display: none;
  }

  [data-scope='alert'][data-part='indicator'] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    padding: var(--xh-alert-indicator-p, var(--xh-space-1));
    color: var(--xh-alert-indicator-fg, var(--xh-_tone-fg));
  }

  /* 必需的文本列：标题与说明在这里排成一列。 */
  [data-scope='alert'][data-part='content'] {
    display: flex;
    /* 伸缩基准取 0 而不是 auto：取 auto 时基准是这一列的 max-content——
       一段长说明就能把基准撑到比整行还宽，root 那条换行随即把图标、文本列、叉拆成三行 */
    flex: 1 1 0;
    flex-direction: column;
    gap: var(--xh-alert-content-gap, var(--xh-space-1));
    min-inline-size: 0;
  }

  /* 列里的两段文字不再参与 root 那一行的伸缩：宽度由列自己给 */
  [data-scope='alert'][data-part='content'] [data-part='title'],
  [data-scope='alert'][data-part='content'] [data-part='description'] {
    flex: none;
  }

  /* 操作与关闭入口都留在尾端，不把说明挤到下一行。 */
  [data-scope='alert'][data-part='action'] {
    display: flex;
    flex: none;
    align-items: center;
    align-self: center;
    gap: var(--xh-alert-action-gap, var(--xh-space-2));
    margin-inline-start: auto;
  }

  /* 标题与说明摞成一列，占满 root 剩下的横向空间，
     关闭按钮才推得到行尾 */
  [data-scope='alert'][data-part='title'],
  [data-scope='alert'][data-part='description'] {
    margin: 0;
    min-inline-size: 0;
  }

  [data-scope='alert'][data-part='title'] {
    flex: none;
    color: var(--xh-alert-title-fg, var(--xh-_tone-fg));
    font-size: var(--xh-alert-title-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-alert-title-font-weight, var(--xh-font-weight-semibold));
    line-height: var(--xh-alert-title-leading, var(--xh-leading-tight));
  }

  [data-scope='alert'][data-part='description'] {
    flex: none;
    color: var(--xh-alert-description-fg, var(--xh-fg-muted));
    font-size: var(--xh-alert-description-font-size, var(--xh-text-secondary-size));
  }

  /* 没写标题时说明自己占满这一行，否则它会挤在标题旁边 */
  [data-scope='alert'][data-part='title']:empty {
    display: none;
  }

  /* 关闭钮是只有字形的离散动作钮：盒几何、悬停 / 按下与 0.97 按压、粗指针热区、焦点环、禁用面全由
     Action Control 的 icon ghost 档给（连接层投 sm：与此前 --xh-control-h-sm 同尺寸），组件只映射既有使用者槽。
     静息透明；提示本体是白底承载，hover 100 → pressed 200，写了语气时悬停底跟着语气走（--xh-_tone-subtle）。
     closable=false 时连接层同时给 hidden 与 disabled / data-disabled，家族按后者收掉反馈 */
  [data-scope='alert'][data-part='close-trigger'] {
    --xh-action-visual-size: var(--xh-alert-close-size, var(--xh-_action-profile-visual-size));
    --xh-action-min-inline-size: var(--xh-alert-close-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-alert-close-radius, var(--xh-shape-control));
    --xh-action-bg-hover: var(--xh-alert-close-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-alert-close-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-alert-close-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-alert-close-fg-hover, var(--xh-fg-default));
    --xh-action-fg-pressed: var(--xh-alert-close-fg-hover, var(--xh-fg-default));
    --xh-action-border-rest: transparent;
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    /* 叉的字形按钮档取值（sm → 16px），与 root 上给指示符的 md 档分开 */
    --xh-icon-size: var(--xh-alert-icon-size, var(--xh-_action-profile-glyph-size));

    flex: none;
    align-self: center;
    border-width: 0;
  }

  /* closable=false 时连接层同时给了 hidden 与 disabled，这条是它真正收起的那一半；
     家族那条 display 会把 UA 的 [hidden]{display:none} 盖掉 */
  [data-scope='alert'][data-part='close-trigger'][hidden] {
    display: none;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中 */
  [data-scope='alert'][data-part='close-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }

  /*
   * 打印：底色被丢掉，六档语气那层淡底一起没了，剩下的描边兑了 40% 的底色，在纸上几乎印不出。
   * 描边换成正文色把这块提示框出来，标题加重一档——纸上分得出「这是一段提示」，
   * 靠的是框与字重这两条无色通道，不是那层底。
   * 关闭钮在纸上按不动，一并收起。
   */
  @media print {
    [data-scope='alert'][data-part='root'] {
      border-color: currentColor;
    }

    [data-scope='alert'][data-part='title'] {
      font-weight: var(--xh-font-weight-bold);
    }

    [data-scope='alert'][data-part='close-trigger'] {
      display: none;
    }
  }

  @media (forced-colors: active) {
    [data-scope='alert'][data-part='root'] {
      border-color: CanvasText;
    }
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='alert'][data-part='indicator'][hidden] {
    display: none;
  }

  [data-scope='alert'][data-part='content'][hidden] {
    display: none;
  }

  [data-scope='alert'][data-part='action'][hidden] {
    display: none;
  }
}

/* styles/empty-state.css */
/* 定义 empty state 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='empty-state'] {
    --xh-empty-state-skin: 1;
  }

  [data-scope='empty-state'][data-part='root'] {
    /* 三个尺寸档只换这几个私有槽，图标与标题都从 root 继承它们，
       换档不必给每个部件各写一条选择器 */
    --xh-_empty-state-gap: var(--xh-stack-gap-md);
    --xh-_empty-state-py: var(--xh-section-py-md);
    --xh-_empty-state-icon-size: var(--xh-glyph-size-2xl);
    /* 标题走 Surface / Feedback 标题档 14/600；sm 同档只缩图形与留白，lg 升到页面级 heading-3 */
    --xh-_empty-state-title-size: var(--xh-text-label-size);
    /* 图标区的强调色：由 data-status（状态码）或 data-tone（语气）换掉；两样都没写就退成中性 */
    --xh-_empty-state-accent: var(--xh-fg-subtle);

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--xh-empty-state-gap, var(--xh-_empty-state-gap));
    padding-block: var(--xh-empty-state-py, var(--xh-_empty-state-py));
    padding-inline: var(--xh-empty-state-px, var(--xh-space-6));
    color: var(--xh-empty-state-fg, var(--xh-fg-default));
    text-align: center;
  }

  /* 活区节点常挂、靠 hidden 收起，上面声明了 display 会盖掉 UA 的 [hidden] 规则 */
  [data-scope='empty-state'][data-part='root'][hidden] {
    display: none;
  }

  [data-scope='empty-state'][data-part='root'][data-size='sm'] {
    --xh-_empty-state-gap: var(--xh-stack-gap-sm);
    --xh-_empty-state-py: var(--xh-section-py-sm);
    --xh-_empty-state-icon-size: var(--xh-glyph-size-xl);
  }

  [data-scope='empty-state'][data-part='root'][data-size='lg'] {
    --xh-_empty-state-gap: var(--xh-stack-gap-lg);
    --xh-_empty-state-py: var(--xh-section-py-lg);
    --xh-_empty-state-icon-size: var(--xh-glyph-size-3xl);
    --xh-_empty-state-title-size: var(--xh-text-heading-3-size);
  }

  /* —— 状态码 —— */
  /* 三个状态码各并进最接近的一族：找不到=提示，没权限=警示，服务出错=危险。
     用 500 档而不是 600：500 是装饰性强调档，600 是给实心底与文字用的。
     成功 / 警示 / 出错 / 提示这类通用结果不在这儿：那是语气，走下面的 data-tone */
  [data-scope='empty-state'][data-part='root'][data-status='403'] {
    --xh-_empty-state-accent: var(--xh-color-warning-500);
  }

  [data-scope='empty-state'][data-part='root'][data-status='500'] {
    --xh-_empty-state-accent: var(--xh-color-danger-500);
  }

  [data-scope='empty-state'][data-part='root'][data-status='404'] {
    --xh-_empty-state-accent: var(--xh-color-info-500);
  }

  /* 语气轴：写了 tone 就把强调色接到语气层派生好的前景档上。
     排在状态码之后：两者都写时以显式的语气为准；不写 tone 时上面几条一字不变 */
  [data-scope='empty-state'][data-part='root'][data-tone] {
    --xh-_empty-state-accent: var(--xh-_tone-fg);
  }

  /*
   * 插画槽。它与图标槽二选一，尺寸另走一档：插画塞进按字形量的图标槽会被压到 40px 以下，
   * 而空状态的插画通常是这个尺度的两倍。默认由图标档翻一倍派生，跟着三个尺寸档一起走。
   */
  [data-scope='empty-state'][data-part='media'] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    max-inline-size: 100%;
    block-size: var(--xh-empty-state-media-size, calc(var(--xh-_empty-state-icon-size) * 2));
    color: var(--xh-empty-state-media-fg, var(--xh-_empty-state-accent));
  }

  [data-scope='empty-state'][data-part='indicator'] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    /* 作者塞进图标槽的 XhIcon 与皮肤画的字形同一把尺，都按展示档的图标框量 */
    --xh-icon-size: var(--xh-empty-state-icon-size, var(--xh-_empty-state-icon-size));

    block-size: var(--xh-empty-state-icon-size, var(--xh-_empty-state-icon-size));
    inline-size: var(--xh-empty-state-icon-size, var(--xh-_empty-state-icon-size));
    color: var(--xh-empty-state-indicator-fg, var(--xh-_empty-state-accent));
    /* 图标常是一个字形，字号跟着图标框走，line-height 不再另占高度 */
    font-size: var(--xh-empty-state-indicator-font-size, var(--xh-_empty-state-icon-size));
    line-height: var(--xh-leading-none);
  }

  [data-scope='empty-state'][data-part='title'] {
    margin: 0;
    color: var(--xh-empty-state-title-fg, var(--xh-fg-default));
    font-size: var(--xh-empty-state-title-font-size, var(--xh-_empty-state-title-size));
    font-weight: var(--xh-empty-state-title-font-weight, var(--xh-font-weight-semibold));
    line-height: var(--xh-empty-state-title-leading, var(--xh-leading-tight));
  }

  [data-scope='empty-state'][data-part='description'] {
    margin: 0;
    max-inline-size: var(--xh-empty-state-description-max-w, var(--xh-measure-prose));
    color: var(--xh-empty-state-description-fg, var(--xh-fg-muted));
    font-size: var(--xh-empty-state-description-font-size, var(--xh-text-secondary-size));
    line-height: var(--xh-empty-state-description-leading, var(--xh-leading-normal));
  }

  [data-scope='empty-state'][data-part='action'] {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: var(--xh-empty-state-action-gap, var(--xh-space-2));
  }

  /* 图标、标题、说明、动作按次序开幕，间隔由交错步长派生。
     backwards 不能省：等待期间起帧不生效的话，后三段会先露一下再跳回去 */
  [data-scope='empty-state'][data-part='media'],
  [data-scope='empty-state'][data-part='indicator'],
  [data-scope='empty-state'][data-part='title'],
  [data-scope='empty-state'][data-part='description'],
  [data-scope='empty-state'][data-part='action'] {
    animation: xh-rise-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong) backwards;
  }

  [data-scope='empty-state'][data-part='title'] {
    animation-delay: calc(var(--xh-motion-stagger-step) * 1);
  }

  [data-scope='empty-state'][data-part='description'] {
    animation-delay: calc(var(--xh-motion-stagger-step) * 2);
  }

  [data-scope='empty-state'][data-part='action'] {
    animation-delay: calc(var(--xh-motion-stagger-step) * 3);
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='empty-state'][data-part='media'][hidden],
  [data-scope='empty-state'][data-part='indicator'][hidden],
  [data-scope='empty-state'][data-part='action'][hidden] {
    display: none;
  }
}

/* styles/skeleton.css */
/* 定义 skeleton 样式。 */

@layer xihan.motion {
  /* 一条比底色略亮的窄带从头扫到尾。背景图比自身宽一倍，靠移动背景位置扫过去，
     不动 transform 也不动布局，整段动画只在合成层上跑 */
  @keyframes xh-skeleton-shimmer {
    from {
      background-position: 200% 0;
    }

    to {
      background-position: -200% 0;
    }
  }

  /* 呼吸档：整根条子在原色与禁用档之间来回淡。往返由 alternate 给，帧里只写一端 */
  @keyframes xh-skeleton-pulse {
    to {
      opacity: var(--xh-state-disabled-opacity);
    }
  }
}

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='skeleton'] {
    --xh-skeleton-skin: 1;
  }

  /* 骨架容器：竖着码放各根骨架条 */
  [data-scope='skeleton'][data-part='root'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-skeleton-gap, var(--xh-space-3));
  }

  /* 声明了 display 就盖掉了 UA 的 [hidden]{display:none}，补这条兜住加载结束后的收起态 */
  [data-scope='skeleton'][data-part='root'][hidden] {
    display: none;
  }

  /*
   * 单根骨架条。底色与微光两层叠在一起：
   * background-color 是静止时看到的那层，background-image 是扫过去的那道光。
   * 微光取比底亮一档的那支面色：浅色下比 bg-subtle 亮、深色下同样比它亮，
   * 两个主题里扫过去的都是一道亮带，而不是浅色下反倒扫出一道暗带。
   */
  [data-scope='skeleton'][data-part='item'] {
    inline-size: 100%;
    pointer-events: none;
    border-radius: var(--xh-skeleton-radius, var(--xh-shape-control));
    background-color: var(--xh-skeleton-bg, var(--xh-bg-subtle));
    background-image: linear-gradient(
      90deg,
      transparent 20%,
      var(--xh-skeleton-sheen, var(--xh-bg-surface-raised)) 50%,
      transparent 80%
    );
    background-repeat: no-repeat;
    background-size: 200% 100%;
    animation: xh-skeleton-shimmer var(--xh-skeleton-duration, var(--xh-shimmer-duration)) var(--xh-motion-ease-loop) infinite;
  }

  /* 一行文字的高度取正文字号，圆角拉满，看起来就是一行还没排出来的字 */
  [data-scope='skeleton'][data-part='item'][data-shape='text'] {
    block-size: var(--xh-skeleton-text-block-size, var(--xh-text-caption-size));
    border-radius: var(--xh-skeleton-text-radius, var(--xh-shape-pill));
  }

  /* 头像位：正方形加满圆角。宽度定死不跟着容器拉长，高度也不许被主轴压扁 */
  [data-scope='skeleton'][data-part='item'][data-shape='circle'] {
    flex: none;
    inline-size: var(--xh-skeleton-circle-size, var(--xh-control-h-lg));
    aspect-ratio: 1;
    border-radius: var(--xh-skeleton-circle-radius, var(--xh-shape-circle));
  }

  /* 图片、卡片这类成块的占位：给个最小高度，撑开由作者决定 */
  [data-scope='skeleton'][data-part='item'][data-shape='rect'] {
    min-block-size: var(--xh-skeleton-rect-block-size, var(--xh-control-h-lg));
    border-radius: var(--xh-skeleton-rect-radius, var(--xh-shape-surface));
  }

  /*
   * 呼吸档：撤掉微光那层，整根条子在原色与禁用档之间来回淡。
   * 微光扫的是一道亮带，呼吸改的是整根的浓淡——两者都表达"还在等"，
   * 换哪一档由作者定，缺省仍是微光。
   */
  [data-scope='skeleton'][data-part='root'][data-animation='pulse'] [data-part='item'] {
    background-image: none;
    animation: xh-skeleton-pulse var(--xh-skeleton-pulse-duration, var(--xh-shimmer-duration)) var(--xh-motion-ease-sweep) infinite alternate;
  }

  /* 静止档：底色留着，两层动效都撤掉 */
  [data-scope='skeleton'][data-part='root'][data-animation='none'] [data-part='item'] {
    background-image: none;
    animation: none;
  }

  /* 呼吸档自带一条动画，压不住下面基础降级里的 animation: none，这一档各自再写一份。
     两组规则是同一件事的两个触发条件：系统偏好与作者打的 data-motion */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='skeleton'][data-part='root'][data-animation='pulse'] [data-part='item'] {
      animation: none;
    }
  }

  :where([data-motion='reduce']) [data-scope='skeleton'][data-part='root'][data-animation='pulse'] [data-part='item'] {
    animation: none;
  }

  @media print {
    [data-scope='skeleton'][data-part='root'][data-animation='pulse'] [data-part='item'] {
      animation: none;
    }
  }

  /*
   * 减少动效：撤掉微光那层，只留静态底色。
   * 骨架屏是自己冒出来、会一直循环到数据回来为止的动效，正是最容易引发不适的那一类；
   * 这里不能只把时长压到接近零——那样光带会停在某一帧上，留下一道说不清的渐变。
   * 两条规则是同一件事的两个触发条件：系统偏好与作者打的 data-motion。
   */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='skeleton'][data-part='item'] {
      background-image: none;
      animation: none;
    }
  }

  :where([data-motion='reduce']) [data-scope='skeleton'][data-part='item'] {
    background-image: none;
    animation: none;
  }

  @media print {
    /* 打印：动画会被定格在任意一帧——转了一半的圈、扫到一半的微光。这里换成静止的表达，
       取值与减弱动效那一档相同。两档各写一块、不并进一条媒体查询列表：减弱动效另有一份
       :where([data-motion='reduce']) 的钩子版本与它成对，打印没有对应的钩子可配，
       并成一条之后这层配对关系在文本上就断了。 */
    [data-scope='skeleton'][data-part='item'] {
      background-image: none;
      animation: none;
    }
  }

  /*
   * 高对比档：骨架条整根靠底色画出来，这一档里底色与微光一起被系统换掉，
   * 一块什么都没有的空白——正在加载这件事没有了任何表达。改成描一圈边把条子勾出来。
   */
  @media (forced-colors: active) {
    [data-scope='skeleton'][data-part='item'] {
      border: var(--xh-stroke-thin) solid GrayText;
      background-image: none;
    }
  }
}

/* styles/spinner.css */
/* 定义 spinner 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.motion {
  /* 三点档的呼吸：一拍里淡到禁用档再回来 */
  @keyframes xh-spinner-dots {
    50% {
      opacity: var(--xh-state-disabled-opacity);
    }
  }
}

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='spinner'] {
    --xh-spinner-skin: 1;
  }

  /* 圆环画在伪元素上，root 自身不转：转的只是图形，同一行里的文案要留在原地读得动 */
  [data-scope='spinner'][data-part='root'] {
    display: inline-flex;
    align-items: center;
    gap: var(--xh-spinner-gap, var(--xh-control-gap-md));
    line-height: var(--xh-leading-none);
    pointer-events: none;
    vertical-align: middle;
  }

  [data-scope='spinner'][data-part='root']::before {
    content: '';

    /* 边框算进直径，换厚度不会把圆环撑大 */
    box-sizing: border-box;
    flex: none;
    inline-size: var(--xh-spinner-size, var(--xh-glyph-size-lg));
    block-size: var(--xh-spinner-size, var(--xh-glyph-size-lg));
    border: var(--xh-spinner-thickness, var(--xh-stroke-thick)) solid var(--xh-spinner-track, var(--xh-border-default));

    /* 一整圈是轨道色，只有起始边换成前景色，转起来才看得出方向 */
    border-block-start-color: var(--xh-spinner-fg, currentColor);
    border-radius: var(--xh-spinner-radius, var(--xh-shape-circle));
    animation: xh-spin var(--xh-spinner-duration, var(--xh-spin-duration)) var(--xh-motion-ease-loop) infinite;
  }

  /* 三档直径走字形尺寸那把尺：圆环与同一行文字里的图标同级，三档同族才不会在 compact 下错位。
     缺省档写在上面的基础规则里 */
  [data-scope='spinner'][data-part='root'][data-size='sm']::before {
    inline-size: var(--xh-glyph-size-sm);
    block-size: var(--xh-glyph-size-sm);
  }

  [data-scope='spinner'][data-part='root'][data-size='lg']::before {
    inline-size: var(--xh-glyph-size-xl);
    block-size: var(--xh-glyph-size-xl);
  }

  /* 语气只换起始边那一段，轨道留在中性描边上：轨道与起始边的反差就是转向的读法，
     两者同时换成同一族颜色，转到哪儿就看不出来了。
     选择器上带 [data-tone] 是必需的：语气槽会沿继承流下来，不限定在写了语气的
     那个节点上，放在语气容器里的转圈会跟着一起改色 */
  [data-scope='spinner'][data-part='root'][data-tone]::before {
    border-block-start-color: var(--xh-spinner-fg, var(--xh-_tone));
  }

  /*
   * 渐隐弧：一整圈的色相由角度扫过来，再用一圈环形遮罩把中心挖空，剩下的就是一段
   * 由浓到无的弧。转的还是同一条 xh-spin——这一档只换画法，不换节拍。
   * 遮罩只吃 alpha，用 currentColor 当不透明的那一端即可。
   */
  [data-scope='spinner'][data-part='root'][data-variant='arc']::before {
    border: 0;
    background: conic-gradient(transparent, var(--xh-spinner-fg, currentColor));
    -webkit-mask: radial-gradient(
      farthest-side,
      transparent calc(100% - var(--xh-spinner-thickness, var(--xh-stroke-thick))),
      currentColor 0
    );
    mask: radial-gradient(
      farthest-side,
      transparent calc(100% - var(--xh-spinner-thickness, var(--xh-stroke-thick))),
      currentColor 0
    );
  }

  [data-scope='spinner'][data-part='root'][data-variant='arc'][data-tone]::before {
    background: conic-gradient(transparent, var(--xh-spinner-fg, var(--xh-_tone)));
  }

  /*
   * 三点：一行三枚圆点，整组一起呼吸。它不转，因此圆角与描边都撤掉，
   * 图形改由三层径向渐变画；点的颜色走 currentColor，语气档只换这一处。
   */
  [data-scope='spinner'][data-part='root'][data-variant='dots']::before {
    border: 0;
    border-radius: 0;
    background:
      radial-gradient(circle closest-side, var(--xh-spinner-fg, currentColor) 100%, transparent) 0 50% / 25% 25% no-repeat,
      radial-gradient(circle closest-side, var(--xh-spinner-fg, currentColor) 100%, transparent) 50% 50% / 25% 25% no-repeat,
      radial-gradient(circle closest-side, var(--xh-spinner-fg, currentColor) 100%, transparent) 100% 50% / 25% 25% no-repeat;
    animation: xh-spinner-dots var(--xh-spinner-duration, var(--xh-spin-duration)) var(--xh-motion-ease-sweep) infinite;
  }

  [data-scope='spinner'][data-part='root'][data-variant='dots'][data-tone]::before {
    background:
      radial-gradient(circle closest-side, var(--xh-spinner-fg, var(--xh-_tone)) 100%, transparent) 0 50% / 25% 25% no-repeat,
      radial-gradient(circle closest-side, var(--xh-spinner-fg, var(--xh-_tone)) 100%, transparent) 50% 50% / 25% 25% no-repeat,
      radial-gradient(circle closest-side, var(--xh-spinner-fg, var(--xh-_tone)) 100%, transparent) 100% 50% / 25% 25% no-repeat;
  }

  /* 三点档的呼吸自带一条动画，压不住上面那两块基础降级里的 animation: none，
     因此这一档各自再写一份。两组规则是同一件事的两个触发条件 */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='spinner'][data-part='root'][data-variant='dots']::before {
      animation: none;
    }
  }

  :where([data-motion='reduce']) [data-scope='spinner'][data-part='root'][data-variant='dots']::before {
    animation: none;
  }

  @media print {
    [data-scope='spinner'][data-part='root'][data-variant='dots']::before {
      animation: none;
    }
  }

  [data-scope='spinner'][data-part='label'] {
    color: var(--xh-spinner-label-fg, var(--xh-fg-muted));
    font-size: var(--xh-spinner-label-size, var(--xh-text-secondary-size));
    line-height: var(--xh-leading-none);
  }

  /* 减少动效：圆环停下并整圈换成虚线，静止的形状仍然读得出"这里还没好"；
     "在等什么"由 role=status 上的名字与可见文案继续承担。
     两组规则是同一件事的两个触发条件：系统偏好与作者打的 data-motion */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='spinner'][data-part='root']::before {
      border-style: dotted;
      border-color: var(--xh-spinner-fg, currentColor);
      animation: none;
    }

    /* 静止态整圈同色，语气跟着铺满整圈 */
    [data-scope='spinner'][data-part='root'][data-tone]::before {
      border-color: var(--xh-spinner-fg, var(--xh-_tone));
    }
  }

  :where([data-motion='reduce']) [data-scope='spinner'][data-part='root']::before {
    border-style: dotted;
    border-color: var(--xh-spinner-fg, currentColor);
    animation: none;
  }

  :where([data-motion='reduce']) [data-scope='spinner'][data-part='root'][data-tone]::before {
    border-color: var(--xh-spinner-fg, var(--xh-_tone));
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='spinner'][data-part='root'][hidden] {
    display: none;
  }

  @media print {
    /* 打印：动画会被定格在任意一帧——转了一半的圈、扫到一半的微光。这里换成静止的表达，
       取值与减弱动效那一档相同。两档各写一块、不并进一条媒体查询列表：减弱动效另有一份
       :where([data-motion='reduce']) 的钩子版本与它成对，打印没有对应的钩子可配，
       并成一条之后这层配对关系在文本上就断了。 */
    [data-scope='spinner'][data-part='root']::before {
      border-style: dotted;
      border-color: var(--xh-spinner-fg, currentColor);
      animation: none;
    }

    [data-scope='spinner'][data-part='root'][data-tone]::before {
      border-color: var(--xh-spinner-fg, var(--xh-_tone));
    }
  }

  /*
   * 高对比档：这一档把整层背景图丢掉，而渐隐弧与三点都画在背景上——屏幕上会一片空白。
   * 两档一并退回描边画法：一圈系统轨道色加一段高亮的起始边，转的还是同一条动画。
   */
  @media (forced-colors: active) {
    [data-scope='spinner'][data-part='root'][data-variant='arc']::before,
    [data-scope='spinner'][data-part='root'][data-variant='dots']::before {
      border: var(--xh-spinner-thickness, var(--xh-stroke-thick)) solid CanvasText;
      border-block-start-color: Highlight;
      border-radius: var(--xh-spinner-radius, var(--xh-shape-circle));
      background-image: none;
    }
  }
}

/* styles/accordion.css */
/* 定义 accordion 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立；
   独立皮肤同时传递引入标题栏的动作控件配方，full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='accordion'] {
    --xh-accordion-skin: 1;
  }

  [data-scope='accordion'][data-part='root'] {
    /* 作者塞进正文里的图标与皮肤画的兜底字形同一把尺：md 档，标题栏上另按家族档取值 */
    --xh-icon-size: var(--xh-accordion-icon-size, var(--xh-glyph-size-md));

    /* 尺寸档只换正文这两个私有槽，正文从 root 继承它们；标题栏的三档几何由家族 disclosure-trigger 档给 */
    --xh-_accordion-content-px: var(--xh-space-4);
    --xh-_accordion-content-pb: var(--xh-space-4);

    /* 语气落在展开着的标题上，指示器写在标题里、跟着继承这个色，不另立规则。
       没写 data-tone 时 --xh-_tone-fg 没被声明，退回原来的前景色。
       聚焦环不在其列，它恒是 --xh-ring-focus */
    --xh-_accordion-open-fg: var(--xh-_tone-fg, var(--xh-fg-default));

    display: flex;
    flex-direction: column;
    inline-size: 100%;
    contain: layout style;
  }

  [data-scope='accordion'][data-part='root'][data-orientation='horizontal'] {
    flex-direction: row;
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里 */
  [data-scope='accordion'][data-part='root'][data-size='sm'] {
    --xh-_accordion-content-px: var(--xh-space-3);
    --xh-_accordion-content-pb: var(--xh-space-3);
  }

  [data-scope='accordion'][data-part='root'][data-size='lg'] {
    --xh-_accordion-content-px: var(--xh-space-5);
    --xh-_accordion-content-pb: var(--xh-space-5);
  }

  [data-scope='accordion'][data-part='item'] {
    position: relative;
    min-inline-size: 0;
  }

  /* 分隔线画在后一条的起始边，条与条之间才只有一条，末条也不会留一条悬空线
     （根没有外框接住它）。只认自己的直接子条目：套在条目里的另一份手风琴由它自己的根管。
     横排时换成行内轴那一侧 */
  [data-scope='accordion'][data-part='root']
    > [data-scope='accordion'][data-part='item']
    + [data-scope='accordion'][data-part='item'] {
    border-block-start: var(--xh-stroke-thin) solid var(--xh-accordion-item-border, var(--xh-border-subtle));
  }

  [data-scope='accordion'][data-part='root'][data-orientation='horizontal']
    > [data-scope='accordion'][data-part='item']
    + [data-scope='accordion'][data-part='item'] {
    border-block-start: 0;
    border-inline-start: var(--xh-stroke-thin) solid var(--xh-accordion-item-border, var(--xh-border-subtle));
  }

  /* 作者显式渲染的分隔线。渲染了它，上面那条 item + item 的相邻规则就不再命中，
     两条线不会同时出现 */
  [data-scope='accordion'][data-part='item-separator'] {
    flex: none;
    block-size: var(--xh-stroke-thin);
    border: 0;
    margin: 0;
    background: var(--xh-accordion-item-border, var(--xh-border-subtle));
  }

  [data-scope='accordion'][data-part='item-separator'][hidden] {
    display: none;
  }

  [data-scope='accordion'][data-part='root'][data-orientation='horizontal']
    > [data-scope='accordion'][data-part='item-separator'] {
    block-size: auto;
    inline-size: var(--xh-stroke-thin);
  }

  /* —— 形态 —— */
  /* ghost 档不在这儿：它就是上面那套基础取值，写不写 data-variant 都长一个样 */
  /* 整份有了一块面，条与条之间就不再靠那条相邻边分开 */
  [data-scope='accordion'][data-part='root']:is([data-variant='outline'], [data-variant='subtle'])
    > [data-scope='accordion'][data-part='item']
    + [data-scope='accordion'][data-part='item'] {
    border-block-start: 0;
    border-inline-start: 0;
  }

  /* outline：一张静态内容面，--xh-border-default 描边 + surface 底 + 无影（边界只由描边承担）；
     根的外边走 --xh-accordion-border，与条与条之间的分隔线槽 --xh-accordion-item-border 各管各的 */
  [data-scope='accordion'][data-part='root'][data-variant='outline'] {
    border: var(--xh-stroke-thin) solid var(--xh-accordion-border, var(--xh-border-default));
    border-radius: var(--xh-accordion-item-radius, var(--xh-shape-surface));
    background: var(--xh-accordion-item-bg, var(--xh-bg-surface));
    box-shadow: var(--xh-accordion-item-shadow, none);
    overflow: clip;
  }

  /* subtle：同一块连续表面，底换成淡底，描边让位给底色但留住 1px 边位（三档几何一致）；
     淡底承载面向标题栏下发 hover 200 → pressed 300 */
  [data-scope='accordion'][data-part='root'][data-variant='subtle'] {
    --xh-action-host-bg-hover: var(--xh-bg-subtle-hover);
    --xh-action-host-bg-pressed: var(--xh-bg-subtle-active);

    border: var(--xh-stroke-thin) solid transparent;
    border-radius: var(--xh-accordion-item-radius, var(--xh-shape-surface));
    background: var(--xh-accordion-item-bg, var(--xh-bg-subtle));
    box-shadow: var(--xh-accordion-item-shadow, none);
    overflow: clip;
  }

  [data-scope='accordion'][data-part='root']:is([data-variant='outline'], [data-variant='subtle'])
    > [data-scope='accordion'][data-part='item']:not(:last-child)::after {
    content: '';
    position: absolute;
    inset-inline: 3%;
    inset-block-end: 0;
    block-size: var(--xh-stroke-thin);
    background: var(--xh-accordion-item-border, var(--xh-border-subtle));
    pointer-events: none;
  }

  [data-scope='accordion'][data-part='header'] {
    margin: 0;
    font: inherit;
  }

  /* 标题栏铺满一行，盒型、三档几何、悬停 / 按下 / 禁用面由 Action Control 的 disclosure-trigger 档给
     （ghost 形态：白底承载 hover 100 → pressed 200，淡底容器由根下发 host 槽；按下只换面不缩放）；
     这里只把使用者槽映射到桥接槽：字色三态同值（家族的 hover / pressed 字色规则比皮肤更特定，不映射会被换回
     缺省字色），字形按标题栏自己的档位取 --xh-_action-profile-glyph-size；边归零贴住条目，几何与迁移前一致 */
  [data-scope='accordion'][data-part='trigger'] {
    --xh-action-gap: var(--xh-accordion-trigger-gap, var(--xh-_action-profile-gap));
    --xh-action-visual-size: var(--xh-accordion-trigger-h, var(--xh-_action-profile-visual-size));
    --xh-action-padding-block: var(--xh-accordion-trigger-py, var(--xh-_action-profile-padding-block));
    --xh-action-padding-inline: var(--xh-accordion-trigger-px, var(--xh-_action-profile-padding-inline));
    --xh-action-radius: var(--xh-accordion-trigger-radius, var(--xh-_action-profile-radius));
    --xh-action-bg-rest: var(--xh-accordion-trigger-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-accordion-trigger-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-fg-rest: var(--xh-accordion-trigger-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-accordion-trigger-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-accordion-trigger-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-font-size: var(--xh-accordion-trigger-font-size, var(--xh-_action-profile-font-size));
    --xh-icon-size: var(--xh-accordion-icon-size, var(--xh-_action-profile-glyph-size));

    border-width: 0;
    font-weight: var(--xh-accordion-trigger-font-weight, var(--xh-text-label-weight));
  }

  /* 展开态自带一个槽：与常态共用一个的话，作者一改常态字色，
     展开那一档的语气高亮就跟着被抹平，再也分不开。悬停 / 按下的面与收起态同档（open 与家族 hover 同档中性） */
  [data-scope='accordion'][data-part='trigger'][data-state='open'] {
    --xh-action-fg-rest: var(--xh-accordion-trigger-fg-open, var(--xh-_accordion-open-fg));
    --xh-action-fg-hover: var(--xh-accordion-trigger-fg-open, var(--xh-_accordion-open-fg));
    --xh-action-fg-pressed: var(--xh-accordion-trigger-fg-open, var(--xh-_accordion-open-fg));
  }

  /* 禁用条目走 aria-disabled，仍留在 Tab 序里，只是不可操作；前景换成禁用色，不靠 opacity 压暗
     （家族按 data-disabled 给禁用面与指针，字色槽在这里保留优先） */
  [data-scope='accordion'][data-part='trigger'][data-disabled] {
    --xh-action-fg-disabled: var(--xh-accordion-trigger-fg-disabled, var(--xh-_action-variant-fg-disabled));
  }

  [data-scope='accordion'][data-part='indicator'] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    color: var(--xh-accordion-indicator-fg, var(--xh-fg-muted));
    line-height: var(--xh-leading-none);
    /* 指示器与正文同档转向：收起时取 collapse 档，展开时（下面的打开态）取 expand 档 */
    transition: rotate var(--xh-motion-duration-collapse) var(--xh-motion-ease-enter-strong);
  }

  /* 没写内容就由皮肤画；作者往部件里塞了自己的图形，这条规则即不命中 */
  [data-scope='accordion'][data-part='indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
  }

  [data-scope='accordion'][data-part='indicator'][data-state='open'] {
    rotate: 180deg;
    transition: rotate var(--xh-motion-duration-expand) var(--xh-motion-ease-enter-strong);
  }

  /* 这里刻意没有 [data-part='content'][hidden] { display: none }：补了动画一帧都播不出来。
     收起由适配器在退场结束后写内联 display 落成，退场窗口内靠 connect 发的 inert 挡住焦点 */
  [data-scope='accordion'][data-part='content'] {
    /* 行高与内缩同帧动的共享关键帧读这条槽：只有末端有内缩，起端不写、按 0 动 */
    --xh-_disclosure-pb: var(--xh-accordion-content-pb, var(--xh-_accordion-content-pb));

    display: grid;
    grid-template-rows: 1fr;
    overflow: clip;
    padding-block-start: 0;
    padding-block-end: var(--xh-accordion-content-pb, var(--xh-_accordion-content-pb));
    padding-inline: var(--xh-accordion-content-px, var(--xh-_accordion-content-px));
    color: var(--xh-accordion-content-fg, var(--xh-fg-muted));
    font-size: var(--xh-accordion-content-font-size, var(--xh-text-secondary-size));
    line-height: var(--xh-leading-normal);
  }

  /* 展开那一档才提前备好行高这条通道：属性随 data-state 一起消失，收起后不长期占着 */
  [data-scope='accordion'][data-part='content'][data-state='open'] {
    will-change: grid-template-rows;
    animation: xh-disclosure-expand var(--xh-motion-duration-expand) var(--xh-motion-ease-enter-strong);
  }

  [data-scope='accordion'][data-part='content'][data-state='closed'] {
    animation: xh-disclosure-collapse var(--xh-motion-duration-collapse) var(--xh-motion-ease-exit) forwards;
  }
}

@layer xihan.motion {
  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='accordion'][data-part='root'][hidden],
  [data-scope='accordion'][data-part='trigger'][hidden],
  [data-scope='accordion'][data-part='indicator'][hidden] {
    display: none;
  }
}

/* styles/anchor.css */
/* 定义 anchor 样式。 */

/* 链接归 Collection Item 导航当前（nav 语境）：面、字色、字重、光标与按压时间线由家族配方按投影的家族角色给，
   本皮肤只映射桥接槽。2px 指示线由本皮肤画：目录里放了 indicator 部件就由部件在轨道上滑动，
   没放则当前那一节的链接自画一条静态线 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='anchor'] {
    --xh-anchor-skin: 1;
  }

  /* 根节点是 nav 地标，不参与排版：整条目录的布局全在 list 上，
     这里不给 display，UA 的 [hidden]{display:none} 就仍然压得住 */
  [data-scope='anchor'][data-part='root'] {
    /* 尺寸档只换这两个私有槽，链接从 root 继承它们，换档不必给每个部件各写一条选择器 */
    --xh-_anchor-font-size: var(--xh-control-font-md);
    --xh-_anchor-link-px: var(--xh-control-px-md);
    /* 当前那一节的指示条与文字随语气走。没写 data-tone 时这两个槽都没被声明，退回品牌色。
       指示条是装饰性的色条，取柔和档；文字要压在普通背景上读，取语气的文字档——
       导航当前页缺省是 --xh-fg-brand-strong，比指示条深一档。
       聚焦环不在其列，它恒是 --xh-ring-focus */
    --xh-_anchor-accent: var(--xh-_tone-soft, var(--xh-fg-brand));
    --xh-_anchor-accent-text: var(--xh-_tone-fg, var(--xh-fg-brand-strong));

    color: var(--xh-anchor-fg, var(--xh-fg-muted));
    font-size: var(--xh-anchor-font-size, var(--xh-_anchor-font-size));
    line-height: var(--xh-anchor-leading, var(--xh-leading-normal));
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里；链接的内边距三档都走控件内边距那把尺 */
  [data-scope='anchor'][data-part='root'][data-size='sm'] {
    --xh-_anchor-font-size: var(--xh-control-font-sm);
    --xh-_anchor-link-px: var(--xh-control-px-sm);
  }

  [data-scope='anchor'][data-part='root'][data-size='lg'] {
    --xh-_anchor-font-size: var(--xh-control-font-lg);
    --xh-_anchor-link-px: var(--xh-control-px-lg);
  }

  /* 指示条的定位参照系（它是 absolute，量出来的偏移就是相对这里的）。
     ul 的项目符号与内外边距是 UA 给的，库里没有全局 preflight，只能在这儿自己抹平 */
  [data-scope='anchor'][data-part='list'] {
    position: relative;
    display: flex;
    flex-direction: column;
    gap: var(--xh-anchor-gap, var(--xh-space-1));
    margin: 0;
    padding: 0;
    /* 起始缘的那条轨道：指示条就在它上面滑 */
    border-inline-start: var(--xh-stroke-thin) solid var(--xh-anchor-track, var(--xh-border-default));
    list-style: none;
  }

  [data-scope='anchor'][data-part='list'][hidden] {
    display: none;
  }

  /* 横排：轨道从起始缘挪到底边，条目改成一行 */
  [data-scope='anchor'][data-part='list'][data-orientation='horizontal'] {
    flex-direction: row;
    align-items: center;
    gap: var(--xh-anchor-gap-horizontal, var(--xh-space-2));
    border-inline-start: 0;
    border-block-end: var(--xh-stroke-thin) solid var(--xh-anchor-track, var(--xh-border-default));
  }

  [data-scope='anchor'][data-part='item'] {
    display: flex;
    /* 库里没有全局 preflight，列表项的外边距在这里自己抹平 */
    margin: 0;
    /* 允许被压缩，链接内部的省略号才有生效的余地 */
    min-inline-size: 0;
  }

  [data-scope='anchor'][data-part='item'][hidden] {
    display: none;
  }

  /* 链接的几何、字号与面全经家族桥接槽：静息 muted / regular，悬停走白底承载 hover 100 + default 字，
     按下 pressed 200 只换面；当前那一节（导航当前页）brand-strong 字色（随语气的
     --xh-_anchor-accent-text）+ medium 字重都跟着变，2px 指示线放了 indicator 部件由部件滑动、没放则由
     下面的静态线规则画在当前链接自己身上。本条 (0,2,0) 压过家族基础块 (0,1,0)，不能再写 color / background。
     position: relative 是静态线的定位参照 */
  [data-scope='anchor'][data-part='link'] {
    --xh-collection-block-padding: var(--xh-anchor-link-py, var(--xh-space-1));
    --xh-collection-inline-padding: var(--xh-anchor-link-px, var(--xh-_anchor-link-px));
    --xh-collection-radius: var(--xh-anchor-link-radius, var(--xh-shape-control));
    --xh-collection-font-size: var(--xh-anchor-font-size, var(--xh-_anchor-font-size));
    --xh-collection-fg-rest: var(--xh-anchor-fg, var(--xh-fg-muted));
    --xh-collection-bg-hover: var(--xh-anchor-link-bg-hover, var(--xh-bg-subtle));
    --xh-collection-fg-hover: var(--xh-anchor-link-fg-hover, var(--xh-fg-default));
    --xh-collection-bg-pressed: var(--xh-anchor-link-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-fg-current: var(--xh-anchor-link-fg-current, var(--xh-_anchor-accent-text));
    --xh-collection-font-weight-current: var(--xh-anchor-link-font-weight-current, var(--xh-font-weight-medium));

    position: relative;
    display: inline-flex;
    align-items: center;
    /* 一节的标题可能很长，压不住会把整列撑开 */
    max-inline-size: var(--xh-anchor-link-max-w, var(--xh-nav-link-max-w));
    /* 行高随 root 的行距槽：家族基础块给条目写了 leading-normal，这里接回 root 那一支 */
    line-height: var(--xh-anchor-leading, var(--xh-leading-normal));
    white-space: nowrap;
    text-decoration: none;
    text-overflow: ellipsis;
    overflow: hidden;
  }

  [data-scope='anchor'][data-part='link'][hidden] {
    display: none;
  }

  /* 链接里另有图标时，省略号只裁这一段文字 */
  [data-scope='anchor'][data-part='link-text'] {
    min-inline-size: 0;
    white-space: nowrap;
    text-overflow: ellipsis;
    overflow: hidden;
  }

  /* 当前链接的四个几何量由机器量好、连接层写成私有槽 --xh-_anchor-indicator-x / -y / -w / -h
     （它量得到，样式表量不到）；这里按排布取主轴那两支，落点交给 transform（只走合成），
     另管交叉轴的贴边与粗细，以及长什么样。它是可选部件——不渲染它时，
     当前那一节的链接自画一条同规格的静态线（见下） */
  [data-scope='anchor'][data-part='indicator'] {
    /* 还没量到时的落点，量到即被机器写的私有槽盖过 */
    --xh-_anchor-indicator-x: 0;
    --xh-_anchor-indicator-y: 0;
    --xh-_anchor-indicator-w: 0;
    --xh-_anchor-indicator-h: 0;

    position: absolute;
    display: block;
    /* 指示条也是列表项，宿主给 li 的外边距会把绝对定位的它推离条目 */
    margin: 0;
    inset-block-start: 0;
    inset-inline-start: calc(var(--xh-anchor-indicator-thickness, var(--xh-stroke-thick)) * -1);
    inline-size: var(--xh-anchor-indicator-thickness, var(--xh-stroke-thick));
    block-size: var(--xh-_anchor-indicator-h);
    border-radius: var(--xh-anchor-indicator-radius, var(--xh-shape-pill));
    background: var(--xh-anchor-indicator-color, var(--xh-_anchor-accent));
    transform: translate(0, var(--xh-_anchor-indicator-y));
    transition:
      transform var(--xh-motion-duration-move) var(--xh-motion-ease-continuous),
      block-size var(--xh-motion-duration-move) var(--xh-motion-ease-continuous);
  }

  /* display 会盖掉 hidden 属性的 UA 规则，无激活项时显式让位 */
  [data-scope='anchor'][data-part='indicator'][hidden] {
    display: none;
  }

  /* 横排：指示条改躺在底边的轨道上，交叉轴换成块轴 */
  [data-scope='anchor'][data-part='indicator'][data-orientation='horizontal'] {
    inset-block-start: auto;
    inset-inline-start: 0;
    inset-block-end: calc(var(--xh-anchor-indicator-thickness, var(--xh-stroke-thick)) * -1);
    inline-size: var(--xh-_anchor-indicator-w);
    block-size: var(--xh-anchor-indicator-thickness, var(--xh-stroke-thick));
    transform: translate(var(--xh-_anchor-indicator-x), 0);
    transition:
      transform var(--xh-motion-duration-move) var(--xh-motion-ease-continuous),
      inline-size var(--xh-motion-duration-move) var(--xh-motion-ease-continuous);
  }

  /* transform 只认物理方向：RTL 下行首在右边，起始缘量出的距离往左推 */
  [data-scope='anchor'][data-part='indicator'][data-orientation='horizontal']:dir(rtl) {
    transform: translate(calc(-1 * var(--xh-_anchor-indicator-x)), 0);
  }

  /* 目录里没放 indicator 部件时，当前那一节的链接自画一条静态指示线（导航当前页）：
     与 Tabs line 档同一取法，作者不必为了这条线多放一个部件。
     线画在当前链接的 ::after 上，以链接盒为定位参照（上面已给 position: relative），
     厚度 / 颜色 / 圆角与 indicator 部件读同一组槽与缺省——作者改一处，部件与静态线一起改。
     不做动画：它随 data-current 在链接间跳，滑动只有部件做得到。
     线贴在链接盒内的那条缘：链接为了省略号收着 overflow，画不到盒外；部件骑在 list 的轨道上（盒外一线宽），
     两者同侧、差一线宽。主轴两端各退一格 --xh-space-1 避开链接的圆角（overflow 连圆角一起裁，贴满会被
     切掉两个角），与家族 page 语境的起始侧指示条同一取法。嵌套目录里子级链接随自己的缩进走，部件则始终在
     外层轨道上。
     目录里一旦放了 indicator 部件，这条线就收起、位置交给部件滑动，不重复画两条：
     由 list 按 :has 探一次，把私有槽写成 none，线的 content 读它；链接自己不必再各带一段 :has */
  [data-scope='anchor'][data-part='list']:has([data-scope='anchor'][data-part='indicator']) {
    --xh-_anchor-static-line: none;
  }

  [data-scope='anchor'][data-part='link'][data-current]::after {
    content: var(--xh-_anchor-static-line, '');
    position: absolute;
    pointer-events: none;
    border-radius: var(--xh-anchor-indicator-radius, var(--xh-shape-pill));
    background: var(--xh-anchor-indicator-color, var(--xh-_anchor-accent));
  }

  /* 竖排（缺省）：贴链接的行向起始缘（与 indicator 部件同一侧，rtl 随逻辑属性镜像） */
  [data-scope='anchor'][data-part='list'][data-orientation='vertical']
    [data-scope='anchor'][data-part='link'][data-current]::after {
    inset-inline-start: 0;
    inset-block: var(--xh-space-1);
    inline-size: var(--xh-anchor-indicator-thickness, var(--xh-stroke-thick));
  }

  /* 横排：贴链接的块向末端（底边） */
  [data-scope='anchor'][data-part='list'][data-orientation='horizontal']
    [data-scope='anchor'][data-part='link'][data-current]::after {
    inset-block-end: 0;
    inset-inline: var(--xh-space-1);
    block-size: var(--xh-anchor-indicator-thickness, var(--xh-stroke-thick));
  }

  @media (forced-colors: active) {
    /* 指示条画的是一块纯底色，这一档里底色被统一换成 Canvas，条子整根消失，
       "读到哪一节"就只剩链接自己的字重。换成系统高亮色画回来 */
    [data-scope='anchor'][data-part='indicator'] {
      background: Highlight;
    }

    /* 没放部件时当前链接自画的那条静态线同样是一块纯底色，同一档换成系统高亮色 */
    [data-scope='anchor'][data-part='link'][data-current]::after {
      background: Highlight;
    }
  }
}

/* styles/approval.css */
/* 定义 approval 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */
/* 独立皮肤同时传递引入授权行与两颗钮的动作控件配方，full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='approval'] {
    --xh-approval-skin: 1;
  }

  /* 一块要人做决定的静态内容面：--xh-border-default 描边 + surface 底 + 无影（边界只由描边承担），
     作者打了语气时描边染成语气色作强调（下面那条），判定落定后描边退回中性 */
  [data-scope='approval'][data-part='root'] {
    /* 作者塞进标题 / 说明 / 结果条里的图标按档取尺，缺省 md；勾选记号另按盒比例量 */
    --xh-_approval-icon-size: var(--xh-glyph-size-md);
    --xh-icon-size: var(--xh-approval-icon-size, var(--xh-_approval-icon-size));

    /* 尺寸缺省档：不写 data-size 时的取值。三档都只写这批私有槽，
       公开槽留在读处当首选，作者在祖先上设的覆盖才赢得过档位声明 */
    --xh-_approval-gap: var(--xh-space-3);
    --xh-_approval-p: var(--xh-space-4);
    --xh-_approval-action-h: var(--xh-control-h-md);
    --xh-_approval-action-px: var(--xh-control-px-md);
    --xh-_approval-item-font-size: var(--xh-control-font-md);
    --xh-_approval-note-font-size: var(--xh-control-font-md);

    display: flex;
    flex-direction: column;
    gap: var(--xh-approval-gap, var(--xh-_approval-gap));
    padding: var(--xh-approval-p, var(--xh-_approval-p));
    border: var(--xh-stroke-thin) solid var(--xh-approval-border, var(--xh-border-default));
    border-radius: var(--xh-approval-radius, var(--xh-shape-surface));
    background: var(--xh-approval-bg, var(--xh-bg-surface));
    box-shadow: var(--xh-approval-shadow, none);
    transition: border-color var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
    animation: xh-item-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 上面声明的 display 会盖掉 UA 的 [hidden]{display:none}，这里补回 */
  [data-scope='approval'][data-part='root'][hidden] {
    display: none;
  }

  /* 语气只染描边：作者定的强调，待决时把这块面从正文里提出来 */
  [data-scope='approval'][data-part='root'][data-tone] {
    border-color: var(--xh-approval-border, var(--xh-_tone, var(--xh-border-default)));
  }

  /* 判过了就不再抢注意力：语气色边退回中性描边（根面外边不取 subtle）。
     排在语气那条之后：同等特指度，落定要盖得过语气 */
  [data-scope='approval'][data-part='root']:not([data-state='pending']) {
    border-color: var(--xh-approval-border-settled, var(--xh-border-default));
  }

  /* —— 形态 —— */
  /* 缺省档即 outline，写在上面那条基础规则里。
     两档排在落定那条之后：它们把描边整个撤掉，排在前面会被落定那条按同等特指度盖回来 */
  /* 底色分区：描边让位给底色，闸门嵌在别人的面里时不再多一圈线；
     淡底承载面向授权行与拒绝钮下发 hover 200 → pressed 300 */
  [data-scope='approval'][data-part='root'][data-variant='subtle'] {
    --xh-action-host-bg-hover: var(--xh-bg-subtle-hover);
    --xh-action-host-bg-pressed: var(--xh-bg-subtle-active);

    border-color: transparent;
    background: var(--xh-approval-bg, var(--xh-bg-subtle));
  }

  /* 无壳内联：卡中卡时不再自带一张面，跟着外层的底走 */
  [data-scope='approval'][data-part='root'][data-variant='ghost'] {
    border-color: transparent;
    background: none;
    box-shadow: none;
  }

  /* 标题走 Surface 标题档 14/600 */
  [data-scope='approval'][data-part='title'] {
    display: block;
    margin: 0;
    color: var(--xh-approval-title-fg, var(--xh-fg-default));
    font-size: var(--xh-approval-title-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-approval-title-font-weight, var(--xh-font-weight-semibold));
    line-height: var(--xh-leading-tight);
  }

  [data-scope='approval'][data-part='title'][hidden] {
    display: none;
  }

  [data-scope='approval'][data-part='description'] {
    display: block;
    margin: 0;
    color: var(--xh-approval-description-fg, var(--xh-fg-muted));
    font-size: var(--xh-approval-description-font-size, var(--xh-text-secondary-size));
    line-height: var(--xh-leading-normal);
  }

  [data-scope='approval'][data-part='description'][hidden] {
    display: none;
  }

  /* 视觉隐藏的播报区：不能 display:none，那样读屏就取不到它了 */
  [data-scope='approval'][data-part='live-region'] {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    border: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  [data-scope='approval'][data-part='group'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-approval-group-gap, var(--xh-space-1));
  }

  [data-scope='approval'][data-part='group'][hidden] {
    display: none;
  }

  /* 一项授权：整行可点、可聚焦，勾选记号在左。盒型、悬停 / 按下 / 禁用面由 Action Control 的 row 档给
     （ghost 形态：白底承载 hover 100 → pressed 200，按下只换面不缩放；禁用守卫认 data-disabled），
     这里只把使用者槽映射到桥接槽，内衬与间距沿用本组件的档位。
     行高不吃家族的单行档：row 档允许换行、高度随内容，一条会折行的授权文案走正文行高 */
  [data-scope='approval'][data-part='item'] {
    --xh-action-gap: var(--xh-approval-item-gap, var(--xh-space-1_5));
    --xh-action-padding-inline: var(--xh-approval-item-px, var(--xh-space-2));
    --xh-action-padding-block: var(--xh-approval-item-py, var(--xh-space-1));
    --xh-action-radius: var(--xh-approval-item-radius, var(--xh-_action-profile-radius));
    --xh-action-font-size: var(--xh-approval-item-font-size, var(--xh-_approval-item-font-size));
    --xh-action-bg-hover: var(--xh-approval-item-bg-hover, var(--xh-_action-variant-bg-hover));

    line-height: var(--xh-leading-normal);
  }

  [data-scope='approval'][data-part='item'][hidden] {
    display: none;
  }

  /* 勾选记号：方框 + 选中态填色，纯装饰不进可访问名。
     勾按盒比例量（与 Checkbox 同一比例），作者塞进来的图标读同一把尺，不随根上的整档图标放大撑破盒 */
  [data-scope='approval'][data-part='item-indicator'] {
    --xh-_approval-indicator-glyph: calc(var(--xh-approval-indicator-size, var(--xh-control-indicator-size)) * 0.75);
    --xh-icon-size: var(--xh-approval-indicator-icon-size, var(--xh-_approval-indicator-glyph));

    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    border: var(--xh-stroke-thin) solid var(--xh-approval-indicator-border, var(--xh-border-control));
    border-radius: var(--xh-approval-indicator-radius, var(--xh-shape-inset));
    color: var(--xh-approval-indicator-fg, var(--xh-fg-on-brand));
    inline-size: var(--xh-approval-indicator-size, var(--xh-control-indicator-size));
    block-size: var(--xh-approval-indicator-size, var(--xh-control-indicator-size));
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      border-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='approval'][data-part='item-indicator'][hidden] {
    display: none;
  }

  /* 没写内容就由皮肤画勾；作者往部件里塞了自己的图形，这条规则即不命中 */
  [data-scope='approval'][data-part='item-indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    mask: var(--xh-glyph-mark-check) center / contain no-repeat;
  }

  [data-scope='approval'][data-part='item-indicator'][data-state='checked'] {
    border-color: var(--xh-approval-indicator-border-checked, var(--xh-bg-brand));
    background: var(--xh-approval-indicator-bg-checked, var(--xh-bg-brand));
  }

  /* 没勾上时把勾隐去而不是撤掉：盒子留在原位，翻面时整行不跳 */
  [data-scope='approval'][data-part='item-indicator'][data-state='unchecked'] {
    color: transparent;
  }

  /* 勾上的那条读起来更重一档 */
  [data-scope='approval'][data-part='item-text'] {
    display: block;
    flex: 1 1 auto;
    color: var(--xh-approval-item-text-fg, var(--xh-fg-muted));
  }

  [data-scope='approval'][data-part='item'][data-state='checked'] [data-part='item-text'] {
    color: var(--xh-approval-item-text-fg-checked, var(--xh-fg-default));
  }

  /* 排在勾选档之后：禁用项无论勾没勾都是禁用色 */
  [data-scope='approval'][data-part='item'][data-disabled] [data-part='item-text'] {
    color: var(--xh-fg-disabled);
  }

  [data-scope='approval'][data-part='item-text'][hidden] {
    display: none;
  }

  /* 备注：附在判定上的一句自由文本，占满整行 */
  [data-scope='approval'][data-part='note'] {
    display: block;
    inline-size: 100%;
    padding-inline: var(--xh-approval-note-px, var(--xh-space-2));
    padding-block: var(--xh-approval-note-py, var(--xh-space-1_5));
    border: var(--xh-stroke-thin) solid var(--xh-approval-note-border, var(--xh-border-control));
    border-radius: var(--xh-approval-note-radius, var(--xh-shape-control));
    background: var(--xh-approval-note-bg, var(--xh-bg-surface));
    color: var(--xh-approval-note-fg, var(--xh-fg-default));
    font-family: inherit;
    font-size: var(--xh-approval-note-font-size, var(--xh-_approval-note-font-size));
    transition: border-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='approval'][data-part='note'][hidden] {
    display: none;
  }

  [data-scope='approval'][data-part='note']:disabled {
    color: var(--xh-fg-disabled);
  }

  /* 剩余时间：等宽数字，逐秒跳字时不左右晃 */
  [data-scope='approval'][data-part='timer'] {
    display: block;
    color: var(--xh-approval-timer-fg, var(--xh-fg-muted));
    font-size: var(--xh-approval-timer-font-size, var(--xh-text-caption-size));
    font-variant-numeric: tabular-nums;
  }

  [data-scope='approval'][data-part='timer'][hidden] {
    display: none;
  }

  /* 判定结果条：判过了才露出，语气随判定走 */
  [data-scope='approval'][data-part='result'] {
    display: inline-flex;
    align-self: flex-start;
    align-items: center;
    gap: var(--xh-approval-result-gap, var(--xh-space-1_5));
    padding-inline: var(--xh-approval-result-px, var(--xh-space-2));
    padding-block: var(--xh-approval-result-py, var(--xh-space-1));
    border-radius: var(--xh-approval-result-radius, var(--xh-shape-pill));
    background: var(--xh-approval-result-bg, color-mix(in oklab, var(--xh-fg-success) 12%, var(--xh-bg-surface)));
    color: var(--xh-approval-result-fg, var(--xh-fg-success));
    font-size: var(--xh-approval-result-font-size, var(--xh-text-caption-size));
    font-weight: var(--xh-approval-result-font-weight, var(--xh-text-label-weight));
    animation: xh-pop-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  [data-scope='approval'][data-part='result'][hidden] {
    display: none;
  }

  /* 超时按拒绝收口，两者同档：视觉上不该看着像第三种结果 */
  [data-scope='approval'][data-part='result']:is([data-state='denied'], [data-state='expired']) {
    background: var(--xh-approval-result-bg-denied, color-mix(in oklab, var(--xh-fg-danger) 12%, var(--xh-bg-surface)));
    color: var(--xh-approval-result-fg-denied, var(--xh-fg-danger));
  }

  /* 动作行：两颗按钮靠右排，间距归库管。
     一行排不下就折行：两颗钮的文案都不折行，靠右排的行溢出时是往行首那侧漫出去，
     漫出去的那截既不产生横滚也回不来，折行是这一行唯一取得回来的形态。 */
  [data-scope='approval'][data-part='footer'] {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-end;
    gap: var(--xh-approval-footer-gap, var(--xh-space-2));
  }

  [data-scope='approval'][data-part='footer'][hidden] {
    display: none;
  }

  /* 两颗按钮是离散动作控件：盒几何、悬停 / 按下与 0.97 按压、焦点环、禁用与在途面全由 Action Control 的
     text 档给，组件只映射既有使用者槽。批准走 solid 档：判定闸门里的主要动作，与 Button 缺省同为品牌实心；
     拒绝走 outline 档：非 Button 的触发器缺省中性描边。
     三档守卫由连接层投影：判定在途是 data-loading + aria-disabled（保住可聚焦，家族给在途面：底色不置灰、
     指针 progress），必选项没勾满与落定是 data-disabled（家族给禁用面：置灰底、置灰字、not-allowed）。
     两颗共用的几何与字号写在一起 */
  [data-scope='approval'][data-part='approve-trigger'],
  [data-scope='approval'][data-part='deny-trigger'] {
    --xh-action-visual-size: var(--xh-approval-action-h, var(--xh-_approval-action-h));
    --xh-action-padding-inline: var(--xh-approval-action-px, var(--xh-_approval-action-px));
    --xh-action-radius: var(--xh-approval-action-radius, var(--xh-shape-control));
    --xh-action-font-size: var(--xh-approval-action-font-size, var(--xh-text-label-size));

    font-weight: var(--xh-approval-action-font-weight, var(--xh-text-label-weight));
  }

  /* 家族那条 display 会把 UA 的 [hidden]{display:none} 盖掉 */
  [data-scope='approval'][data-part='approve-trigger'][hidden],
  [data-scope='approval'][data-part='deny-trigger'][hidden] {
    display: none;
  }

  /* 批准钮：品牌实心，内顶高光把实心块顶出一道边，与拒绝那颗的描边同一档厚度（三态与在途同一支，
     禁用面由家族收掉）；底 / 字与禁用底映到 solid 档的桥接槽 */
  [data-scope='approval'][data-part='approve-trigger'] {
    --xh-action-bg-rest: var(--xh-approval-approve-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-approval-approve-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-loading: var(--xh-approval-approve-bg, var(--xh-_action-variant-bg-loading));
    --xh-action-bg-disabled: var(--xh-approval-approve-bg-off, var(--xh-_action-variant-bg-disabled));
    --xh-action-fg-rest: var(--xh-approval-approve-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-approval-approve-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-approval-approve-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-fg-loading: var(--xh-approval-approve-fg, var(--xh-_action-variant-fg-loading));
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: var(--xh-approval-approve-shadow, var(--xh-_highlight-tone));
    --xh-action-shadow-hover: var(--xh-approval-approve-shadow, var(--xh-_highlight-tone));
    --xh-action-shadow-pressed: var(--xh-approval-approve-shadow, var(--xh-_highlight-tone));
    --xh-action-shadow-loading: var(--xh-approval-approve-shadow, var(--xh-_highlight-tone));
  }

  /* 面是实心的，环色与面同族，画在面里就看不出来；环改取面自己的前景色——
     那一族色本来就要在这块面上把字读清楚，与面的对比是按可读性定的。
     只对着还铺着实心底的那两档：按得动的常态，与判定在途那一档；
     禁用档的底换成置灰底、字换成置灰色，环取过来就跟底一起糊了，那一档走公共层的环 */
  [data-scope='approval'][data-part='approve-trigger']:not([data-disabled]) {
    --xh-action-ring-color-focus-visible: currentColor;
  }

  /* 拒绝钮：中性描边，底 / 边 / 字与禁用面映到 outline 档的桥接槽（透明底 → 100 → 200；
     落定后描边退回中性，不再像个能按的出口） */
  [data-scope='approval'][data-part='deny-trigger'] {
    --xh-action-bg-rest: var(--xh-approval-deny-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-approval-deny-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-disabled: var(--xh-approval-deny-bg-off, var(--xh-_action-variant-bg-disabled));
    --xh-action-fg-rest: var(--xh-approval-deny-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-approval-deny-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-approval-deny-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-border-rest: var(--xh-approval-deny-border, var(--xh-_action-variant-border-rest));
    --xh-action-border-disabled: var(--xh-approval-deny-border-off, var(--xh-_action-variant-border-disabled));
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
  }

  /* 判定在途：两颗钮那一行里转一枚圆环（指针 progress 由家族的在途面给）。
     两颗钮此刻确实按不动，但按不动的理由是「你按的那一下正在走」，与「必选项没勾满」
     的那档灰不是一回事；只留灰的话两种情形长得一模一样，用户读不出系统正在想。
     所以在途这一档不置灰：颜色与对比度都保持原样，锁住只由圆环与指针说。
     圆环挂在这一行上而不是某一颗钮上：连接层只拿到「有一条判定在途」，
     拿不到是哪一颗按下的，画在两颗钮上会有一颗在说假话 */

  [data-scope='approval'][data-part='root'][data-loading] [data-scope='approval'][data-part='footer']::before {
    content: '';
    flex: none;

    /* 圆环那一枚跟着两颗钮的字号走，不跟页面的：download-trigger 与 clipboard 的圆环
       1em 量的都是它所在那颗钮，这里的宿主是整行，不锁字号就会比按钮上的大一圈 */
    font-size: var(--xh-approval-action-font-size, var(--xh-text-label-size));
    inline-size: 1em;
    block-size: 1em;
    border: var(--xh-stroke-thin) solid transparent;
    border-block-start-color: currentColor;
    border-radius: var(--xh-shape-circle);
    animation: xh-spin var(--xh-approval-loading-duration, var(--xh-spin-duration)) var(--xh-motion-ease-loop) infinite;
  }

  /* 减少动效：圆环停下并整圈换成虚线，静止的形状仍然读得出"还没好"。
     两条规则是同一件事的两个触发条件：系统偏好与作者打的 data-motion */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='approval'][data-part='root'][data-loading] [data-scope='approval'][data-part='footer']::before {
      border-style: dotted;
      border-color: currentColor;
      animation: none;
    }
  }

  :where([data-motion='reduce']) [data-scope='approval'][data-part='root'][data-loading] [data-scope='approval'][data-part='footer']::before {
    border-style: dotted;
    border-color: currentColor;
    animation: none;
  }

  /* 尺寸档改内衬、间距、按钮高度、行内字号与图标档 */
  [data-scope='approval'][data-part='root'][data-size='sm'] {
    --xh-_approval-icon-size: var(--xh-glyph-size-sm);
    --xh-_approval-p: var(--xh-space-3);
    --xh-_approval-gap: var(--xh-space-2);
    --xh-_approval-action-h: var(--xh-control-h-sm);
    --xh-_approval-action-px: var(--xh-control-px-sm);
    --xh-_approval-item-font-size: var(--xh-control-font-sm);
    --xh-_approval-note-font-size: var(--xh-control-font-sm);
  }

  [data-scope='approval'][data-part='root'][data-size='md'] {
    --xh-_approval-icon-size: var(--xh-glyph-size-md);
    --xh-_approval-p: var(--xh-space-4);
    --xh-_approval-gap: var(--xh-space-3);
    --xh-_approval-action-h: var(--xh-control-h-md);
    --xh-_approval-action-px: var(--xh-control-px-md);
    --xh-_approval-item-font-size: var(--xh-control-font-md);
    --xh-_approval-note-font-size: var(--xh-control-font-md);
  }

  [data-scope='approval'][data-part='root'][data-size='lg'] {
    --xh-_approval-icon-size: var(--xh-glyph-size-lg);
    --xh-_approval-p: var(--xh-space-5);
    --xh-_approval-gap: var(--xh-space-4);
    --xh-_approval-action-h: var(--xh-control-h-lg);
    --xh-_approval-action-px: var(--xh-control-px-lg);
    --xh-_approval-item-font-size: var(--xh-control-font-lg);
    --xh-_approval-note-font-size: var(--xh-control-font-lg);
  }
}

/* styles/avatar.css */
/* 定义 avatar 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='avatar'] {
    --xh-avatar-skin: 1;
  }

  [data-scope='avatar'][data-part='root'] {
    position: relative;
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    inline-size: var(--xh-avatar-size, var(--xh-control-h-md));
    block-size: var(--xh-avatar-size, var(--xh-control-h-md));
    border-radius: var(--xh-avatar-radius, var(--xh-shape-circle));
    background: var(--xh-avatar-bg, var(--xh-bg-subtle));
    color: var(--xh-avatar-fg, var(--xh-fg-muted));
    font-size: var(--xh-avatar-font-size, var(--xh-text-secondary-size));
    font-weight: var(--xh-avatar-font-weight, var(--xh-font-weight-medium));
    line-height: var(--xh-leading-none);
    user-select: none;
  }

  /* 三档尺寸对齐控件档位，缺省档写在上面的基础规则里；
     字号跟着一起缩放，回退字才在小头像里放得下、在大头像里不显小。
     每一档都把 --xh-avatar-size / --xh-avatar-font-size 排在自己的档值前面：这两个槽是
     外层统一整排头像的通道，档值直接写终值的话，写了 data-size 的那一枚就脱离外层控制 */
  [data-scope='avatar'][data-part='root'][data-size='sm'] {
    inline-size: var(--xh-avatar-size, var(--xh-control-h-sm));
    block-size: var(--xh-avatar-size, var(--xh-control-h-sm));
    font-size: var(--xh-avatar-font-size, var(--xh-control-caption-sm));
  }

  [data-scope='avatar'][data-part='root'][data-size='lg'] {
    inline-size: var(--xh-avatar-size, var(--xh-control-h-lg));
    block-size: var(--xh-avatar-size, var(--xh-control-h-lg));
    font-size: var(--xh-avatar-font-size, var(--xh-control-caption-lg));
  }

  /* —— 语气 ——
     头像只有「淡底 + 字/图」一种形态，所以语气只换淡底与字色这一档，不开形态轴。
     两条声明都把 --xh-avatar-bg / --xh-avatar-fg 排在语气值前面：使用者槽仍是最外那一层，
     写了 tone 的那一枚照样受外层统一控制。整块带 [data-tone] 限定，没写语气的头像逐值不变 */
  [data-scope='avatar'][data-part='root'][data-tone] {
    background: var(--xh-avatar-bg, var(--xh-_tone-subtle, var(--xh-bg-subtle)));
    color: var(--xh-avatar-fg, var(--xh-_tone-fg, var(--xh-fg-muted)));
  }

  /* 不声明 display，加载完成前的 hidden 直接交给浏览器的 [hidden] 规则收起。
     载完那一刻 hidden 撤掉、这个节点从不显示变为显示，淡入在那一刻起跑，
     图片不是硬切上来盖掉回退字 */
  [data-scope='avatar'][data-part='image'] {
    inline-size: 100%;
    block-size: 100%;
    border-radius: inherit;
    object-fit: cover;
    animation: xh-fade-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter);
  }

  [data-scope='avatar'][data-part='fallback'] {
    display: flex;
    align-items: center;
    justify-content: center;
    inline-size: 100%;
    block-size: 100%;
    text-transform: uppercase;
  }

  /* display 会盖掉 hidden 属性的 UA 规则，加载完成后显式让位给图片 */
  [data-scope='avatar'][data-part='fallback'][hidden] {
    display: none;
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='avatar'][data-part='root'][hidden] {
    display: none;
  }
}

/* styles/badge.css */
/* 定义 badge 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='badge'] {
    --xh-badge-skin: 1;
  }

  /* 锚点：被标记的那个东西（按钮、头像、标签页）放进它里面。
     角标绝对定位在它的角上，所以这一层必须建定位上下文，且不能自己撑出尺寸 */
  [data-scope='badge'][data-part='root'] {
    position: relative;
    display: inline-flex;
    /* 角标探出宿主边界是常态，不能被裁掉 */
    overflow: visible;
    vertical-align: middle;
  }

  /* 锚点也可能被作者整块收起 */
  [data-scope='badge'][data-part='root'][hidden] {
    display: none;
  }

  /* 角标本身。档位换的是圆点直径、两位数时的最小宽度与字号——
     不是药丸那套内衬与行高：那是 tag 的活 */
  [data-scope='badge'][data-part='indicator'] {
    /* 每一档的盒都要大于字号：两位数在等高的盒里会被撑破。
       字号刻度最小就是 12px，所以往上抬盒子而不是往下压字 */
    --xh-_badge-dot: var(--xh-space-2);
    --xh-_badge-min: var(--xh-space-7);
    --xh-_badge-px: var(--xh-space-1);
    --xh-_badge-font: var(--xh-text-secondary-size);

    /* 不设 z-index：角标在 DOM 序里排在宿主之后，本来就压在上面 */
    position: absolute;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    min-inline-size: var(--xh-badge-min-size, var(--xh-_badge-min));
    block-size: var(--xh-badge-min-size, var(--xh-_badge-min));
    padding-inline: var(--xh-badge-px, var(--xh-_badge-px));
    border: var(--xh-stroke-thin) solid var(--xh-badge-ring, var(--xh-bg-surface));
    border-radius: var(--xh-badge-radius, var(--xh-shape-pill));
    /* 角标默认就是实心的：贴在别的东西上，淡底与描边都看不清 */
    background: var(--xh-badge-bg, var(--xh-_tone));
    color: var(--xh-badge-fg, var(--xh-_tone-on));
    font-size: var(--xh-badge-font-size, var(--xh-_badge-font));
    font-weight: var(--xh-badge-font-weight, var(--xh-font-weight-medium));
    line-height: var(--xh-leading-none);
    /* 出的是计数，数字必须等宽：不然 9 跳到 10 时角标的宽度会抖一下 */
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    pointer-events: none;
  }

  /* 声明了 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     计数为 0 且没开 showZero 时连接层会发 hidden */
  [data-scope='badge'][data-part='indicator'][hidden] {
    display: none;
  }

  /* 圆点形态：只表示「有」，不表示「有几个」——收掉内边距与文字盒。
     宽高同槽的正方盒按身份取 circle，不沿用计数档的胶囊冒充圆：
     胶囊那 9999px 在正方盒上虽也画成圆，形状身份却写错了档，作者按圆点覆盖圆角时无处落手。
     圆点直径只有六到十像素，一像素的内高光会占去顶上一大截、读成缺了一圈的描边，这里收掉 */
  [data-scope='badge'][data-part='indicator'][data-dot] {
    min-inline-size: var(--xh-badge-dot-size, var(--xh-_badge-dot));
    inline-size: var(--xh-badge-dot-size, var(--xh-_badge-dot));
    block-size: var(--xh-badge-dot-size, var(--xh-_badge-dot));
    border-radius: var(--xh-badge-dot-radius, var(--xh-shape-circle));
    padding: 0;
    box-shadow: none;
    font-size: 0;
  }

  /* 呼吸：圆点表达正在进行、给不出进度的状态（直播、录制、通话中）。
     明暗与缩放的起伏持续到状态结束；外扩光环画在 ::after 上，同周期播 3 轮后停在不可见。
     数字角标不呼吸：连接层只在圆点档投影 data-pulse，明暗起伏会压低数字的对比度 */
  [data-scope='badge'][data-part='indicator'][data-pulse] {
    animation: xh-breathe var(--xh-motion-loop-breathe) var(--xh-motion-ease-breathe) infinite;
  }

  [data-scope='badge'][data-part='indicator'][data-pulse]::after {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background: inherit;
    opacity: 0;
    pointer-events: none;
    animation: xh-breathe-halo var(--xh-motion-loop-breathe) var(--xh-motion-ease-breathe) 3;
  }

  /* 减弱动效：两者都停，圆点停在满不透明度，光环不出现；状态仍由圆点本身与宿主的文字表达 */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='badge'][data-part='indicator'][data-pulse],
    [data-scope='badge'][data-part='indicator'][data-pulse]::after {
      animation: none;
    }
  }

  :where([data-motion='reduce']) [data-scope='badge'][data-part='indicator'][data-pulse],
  :where([data-motion='reduce']) [data-scope='badge'][data-part='indicator'][data-pulse]::after {
    animation: none;
  }

  /* —— 落点 —— */
  /* 用 inset 的逻辑属性写，rtl 下 end 自动落到左边；translate 让角标压住宿主的角 */
  [data-scope='badge'][data-part='indicator'][data-placement='top-end'] {
    inset-block-start: 0;
    inset-inline-end: 0;
    translate: 25% -25%;
  }

  [data-scope='badge'][data-part='indicator'][data-placement='top-start'] {
    inset-block-start: 0;
    inset-inline-start: 0;
    translate: -25% -25%;
  }

  [data-scope='badge'][data-part='indicator'][data-placement='bottom-end'] {
    inset-block-end: 0;
    inset-inline-end: 0;
    translate: 25% 25%;
  }

  [data-scope='badge'][data-part='indicator'][data-placement='bottom-start'] {
    inset-block-end: 0;
    inset-inline-start: 0;
    translate: -25% 25%;
  }

  /* rtl 下 translate 的行内轴要跟着翻，否则角标会往宿主外面跑 */
  [dir='rtl'] [data-scope='badge'][data-part='indicator'][data-placement='top-end'] {
    translate: -25% -25%;
  }

  [dir='rtl'] [data-scope='badge'][data-part='indicator'][data-placement='top-start'] {
    translate: 25% -25%;
  }

  [dir='rtl'] [data-scope='badge'][data-part='indicator'][data-placement='bottom-end'] {
    translate: -25% 25%;
  }

  [dir='rtl'] [data-scope='badge'][data-part='indicator'][data-placement='bottom-start'] {
    translate: 25% 25%;
  }

  /* —— 尺寸 —— */
  /* 小号是贴在 16px 图标角上的角标：盒取 12 + 2 的半阶补偿 = 14px，字仍是刻度最小的 12px——
     数字的字面只占字号的六成，扣掉两道 1px 描边后的 12px 内高装得下两位数，再小就得压字 */
  [data-scope='badge'][data-part='indicator'][data-size='sm'] {
    --xh-_badge-dot: var(--xh-space-1_5);
    --xh-_badge-min: calc(var(--xh-space-3) + var(--xh-space-0_5));
    --xh-_badge-px: var(--xh-space-0_5);
    --xh-_badge-font: var(--xh-text-caption-size);
  }

  [data-scope='badge'][data-part='indicator'][data-size='lg'] {
    --xh-_badge-dot: var(--xh-space-2_5);
    --xh-_badge-min: var(--xh-space-8);
    --xh-_badge-px: var(--xh-space-1_5);
    --xh-_badge-font: var(--xh-text-body-size);
  }

  /*
   * 打印：底色被丢掉。计数档配的是实心底上的前景色，底一没那串数字就印不出来；
   * 圆点档整个由底色画成，底一没连位置都看不见。
   * 两档都改由描边承载：常态那圈边是衬在宿主上的隔离环，取的是面色，纸上同样是白的，
   * 这里换成正文色——计数成了一枚描边药丸，圆点成了一个小圈。
   */
  @media print {
    [data-scope='badge'][data-part='indicator'] {
      border-color: currentColor;
      color: var(--xh-fg-default);
      box-shadow: none;
    }
  }
}

/* styles/bar-code.css */
/* 定义 bar code 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='bar-code'] {
    --xh-bar-code-skin: 1;
  }

  /*
   * 根 <svg>。深浅两色取固定档而不是语义前景/背景：语义色跟着主题走，深色主题下整张码
   * 会翻成浅底深条的反相图，读码器按"深条浅底"取样，反相码扫不出来。要换配色改下面这两个覆盖槽。
   *
   * 换色只有一条硬约束：条必须比底色深，且两者对比要足。反相与深浅相近都会让读码器扫不出来，
   * 而这件事肉眼看不出来。
   *
   *   --xh-bar-code-fg  条色，同时经 currentColor 传给人读文字
   *   --xh-bar-code-bg  底色
   */
  [data-scope='bar-code'][data-part='root'] {
    display: block;
    border-radius: var(--xh-bar-code-radius, var(--xh-shape-control));
    background: var(--xh-bar-code-bg, var(--xh-color-neutral-0));

    /* 条那条 path 不带自己的填充色，从这里继承下去 */
    color: var(--xh-bar-code-fg, var(--xh-color-neutral-950));
    fill: currentColor;

    /* 占位与码面之间来回时，底色与那圈描边淡变 */
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      box-shadow var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 声明了 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='bar-code'][data-part='root'][hidden] {
    display: none;
  }

  /*
   * 人读文字：字号由 connect 按 X 尺寸写在节点上（规范里数字高约 8X），这里只定字体。
   * 等宽字体让每位数字一样宽，EAN 逐位居中落格才整齐；规范要的 OCR-B 一般机器上没有，退到系统等宽。
   */
  [data-scope='bar-code'][data-part='root'] > [data-xh-geom='text'] {
    font-family: var(--xh-bar-code-font-family, var(--xh-font-family-mono));
    fill: var(--xh-bar-code-text-fg, currentColor);
  }

  /*
   * 没有可编码的内容、以及内容不合规则：两种情形都一根条不铺，留一块带描边的占位。
   * 占位用的是语义色——它是界面元素不是码面，跟着主题走才对。
   */
  [data-scope='bar-code'][data-part='root'][data-state='empty'],
  [data-scope='bar-code'][data-part='root'][data-state='error'] {
    background: var(--xh-bar-code-placeholder-bg, var(--xh-bg-subtle));
    box-shadow: inset 0 0 0 var(--xh-stroke-thin) var(--xh-bar-code-placeholder-border, var(--xh-border-default));
  }
}

/* styles/breadcrumb.css */
/* 定义 breadcrumb 样式。 */

/* 链接归 Collection Item 导航当前（nav 语境）：面、字色、字重、光标与按压时间线由家族配方按投影的家族角色给，
   本皮肤只映射桥接槽；当前页由连接层投影 data-xh-collection-terminal，走家族的 terminal 态 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='breadcrumb'] {
    --xh-breadcrumb-skin: 1;
  }

  /* 根节点是 nav 地标，不参与排版：整条路径的行为全在 list 上，
     这里不给 display，UA 的 [hidden]{display:none} 就仍然压得住 */
  [data-scope='breadcrumb'][data-part='root'] {
    /* 作者塞进指示符槽的图标跟着字号走，与皮肤画的兜底字形同一把尺 */
    --xh-icon-size: var(--xh-breadcrumb-icon-size, var(--xh-glyph-size-text));

    /* 尺寸档只换这两个私有槽，列表与链接都从 root 继承它们，换档不必给每个部件各写一条选择器 */
    --xh-_breadcrumb-font-size: var(--xh-control-font-md);
    --xh-_breadcrumb-gap: var(--xh-space-2);
    /* 当前项与链接悬停的强调色随语气走。没写 data-tone 时 --xh-_tone-fg 没被声明，
       退回原来的前景色。聚焦环不在其列，它恒是 --xh-ring-focus */
    --xh-_breadcrumb-accent-text: var(--xh-_tone-fg, var(--xh-fg-default));

    color: var(--xh-breadcrumb-fg, var(--xh-fg-muted));
    font-size: var(--xh-breadcrumb-font-size, var(--xh-_breadcrumb-font-size));
    line-height: var(--xh-breadcrumb-leading, var(--xh-leading-tight));
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里。间距量的是路径里文字与分隔符之间的距离，
     不在控件间距那把尺上（那把尺的大档与中档同值），三档一律取空间尺 */
  [data-scope='breadcrumb'][data-part='root'][data-size='sm'] {
    --xh-_breadcrumb-font-size: var(--xh-control-font-sm);
    --xh-_breadcrumb-gap: var(--xh-space-1_5);
  }

  [data-scope='breadcrumb'][data-part='root'][data-size='lg'] {
    --xh-_breadcrumb-font-size: var(--xh-control-font-lg);
    --xh-_breadcrumb-gap: var(--xh-space-3);
  }

  /* ol 的项目符号与内外边距是 UA 给的，库里没有全局 preflight，只能在这儿自己抹平 */
  [data-scope='breadcrumb'][data-part='list'] {
    display: flex;
    align-items: center;
    /* 层级多到一行放不下就换行：宁可折行，也不要把路径压扁或撑出横向滚动 */
    flex-wrap: wrap;
    gap: var(--xh-breadcrumb-gap, var(--xh-_breadcrumb-gap));
    margin: 0;
    padding: 0;
    list-style: none;
  }

  [data-scope='breadcrumb'][data-part='list'][hidden] {
    display: none;
  }

  [data-scope='breadcrumb'][data-part='item'] {
    display: inline-flex;
    align-items: center;
    /* 库里没有全局 preflight，列表项的外边距在这里自己抹平 */
    margin: 0;
    /* 允许被压缩，链接内部的省略号才有生效的余地 */
    min-inline-size: 0;
  }

  [data-scope='breadcrumb'][data-part='item'][hidden] {
    display: none;
  }

  /* 链接的几何、字号与面全经家族桥接槽：静息 muted / regular，悬停走白底承载 hover 100 + 随语气的字色，
     按下 pressed 200 只换面；当前页那条不再是"可去的地方"：连接层投影
     data-xh-collection-terminal，家族给透明面 + 随语气的 fg-default + medium + cursor default，不响应悬停与按下，
     并压过它同时带的 aria-disabled 禁用面。本条 (0,2,0) 压过家族基础块 (0,1,0)，不能再写 color / background */
  [data-scope='breadcrumb'][data-part='link'] {
    --xh-collection-block-padding: var(--xh-space-0);
    --xh-collection-inline-padding: var(--xh-breadcrumb-link-px, var(--xh-space-1));
    --xh-collection-radius: var(--xh-breadcrumb-link-radius, var(--xh-shape-control));
    --xh-collection-font-size: var(--xh-breadcrumb-font-size, var(--xh-_breadcrumb-font-size));
    /* 家族会把 --xh-icon-size 写在条目上；不映射，root 上随文字形档的那支会被家族的 md 档盖掉 */
    --xh-collection-glyph-size: var(--xh-breadcrumb-icon-size, var(--xh-glyph-size-text));
    --xh-collection-fg-rest: var(--xh-breadcrumb-fg, var(--xh-fg-muted));
    --xh-collection-bg-hover: var(--xh-breadcrumb-link-bg-hover, var(--xh-bg-subtle));
    --xh-collection-fg-hover: var(--xh-breadcrumb-link-fg-hover, var(--xh-_breadcrumb-accent-text));
    --xh-collection-bg-pressed: var(--xh-breadcrumb-link-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-fg-terminal: var(--xh-breadcrumb-link-fg-current, var(--xh-_breadcrumb-accent-text));
    --xh-collection-font-weight-terminal: var(--xh-breadcrumb-link-font-weight-current, var(--xh-font-weight-medium));

    display: inline-flex;
    align-items: center;
    gap: var(--xh-breadcrumb-link-gap, var(--xh-space-1));
    /* 一层的名字可能很长（文档标题、订单号），压不住会把整条路径撑开 */
    max-inline-size: var(--xh-breadcrumb-link-max-w, var(--xh-nav-link-max-w));
    /* 行高随 root 的行距槽：家族基础块给条目写了 leading-normal，这里接回 root 那一支 */
    line-height: var(--xh-breadcrumb-leading, var(--xh-leading-tight));
    text-decoration: none;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  [data-scope='breadcrumb'][data-part='link'][hidden] {
    display: none;
  }

  /* 图标位跟着字号走，与文字并排；不参与省略，压缩时先压文字 */
  [data-scope='breadcrumb'][data-part='link-icon'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-breadcrumb-link-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-breadcrumb-link-icon-size, var(--xh-glyph-size-text));
  }

  [data-scope='breadcrumb'][data-part='link-icon'][hidden] {
    display: none;
  }

  /* 分隔符与省略号都是纯视觉占位，读屏那边已被 aria-hidden 摘掉 */
  [data-scope='breadcrumb'][data-part='separator'],
  [data-scope='breadcrumb'][data-part='ellipsis'] {
    display: inline-flex;
    flex: none;
    /* 两者也是列表项，宿主给 li 的外边距会把它们顶离同一行 */
    margin: 0;
    align-items: center;
    justify-content: center;
    color: var(--xh-breadcrumb-separator-fg, var(--xh-fg-subtle));
    user-select: none;
  }

  [data-scope='breadcrumb'][data-part='separator'][hidden],
  [data-scope='breadcrumb'][data-part='ellipsis'][hidden] {
    display: none;
  }

  /* 分隔符常常是个图标：给一个跟着字号走的方框，斜杠与图标混用时基线才不跳 */
  [data-scope='breadcrumb'][data-part='separator'] {
    inline-size: var(--xh-breadcrumb-separator-size, var(--xh-glyph-size-text));
  }

  [data-scope='breadcrumb'][data-part='ellipsis'] {
    inline-size: var(--xh-breadcrumb-ellipsis-size, var(--xh-space-5));
    cursor: default;
  }

  /* 没写内容就由皮肤画兜底字形（向前的尖角）；作者写了斜杠或自己的图形，这条即不命中 */
  [data-scope='breadcrumb'][data-part='separator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
  }

  /* 从右往左排版时「向前」在左边 */
  [dir='rtl'] [data-scope='breadcrumb'][data-part='separator']:empty::before {
    rotate: 180deg;
  }
}

/* styles/button.css */
/* 独立 Button 皮肤与 full bundle 都从同一份 Family Recipe 取得布局、状态和命中区。 */

@layer xihan.components {
  [data-scope='button'] {
    --xh-button-skin: 1;
  }

  /* 四种形态的底 / 前景 / 描边由家族形态矩阵按 data-xh-action-variant 给出（缺省 solid 由连接层显式投影，
     只有 Button 缺省品牌实心）；这里只把公开颜色槽桥接到矩阵之前：使用者槽 → 形态矩阵 → 家族缺省，
     再映射几何、海拔与顶光。状态选择器、命中区与尺寸 profile 不在这里复制。 */
  [data-scope='button'][data-part='root'] {
    --xh-action-bg-rest: var(--xh-button-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-button-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-button-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-bg-focus-visible: var(--xh-button-bg, var(--xh-_action-variant-bg-focus-visible));
    --xh-action-bg-loading: var(--xh-button-bg, var(--xh-_action-variant-bg-loading));
    --xh-action-fg-rest: var(--xh-button-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-button-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-button-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-fg-focus-visible: var(--xh-button-fg, var(--xh-_action-variant-fg-focus-visible));
    --xh-action-fg-loading: var(--xh-button-fg, var(--xh-_action-variant-fg-loading));
    --xh-action-highlight-rest: transparent;
    --xh-action-highlight-pressed: transparent;
    /* 海拔只有 solid 一档有：其余形态无影，私有槽在下面的 solid 块里才被赋值 */
    --xh-_button-shadow-rest: var(--xh-button-shadow, none);
    --xh-_button-shadow-hover: var(--xh-button-shadow-hover, none);
    --xh-_button-shadow-pressed: none;
    --xh-action-shadow-rest: var(--xh-_button-shadow-rest);
    --xh-action-shadow-hover: var(--xh-_button-shadow-hover);
    --xh-action-shadow-pressed: var(--xh-_button-shadow-pressed);
    --xh-action-radius: var(--xh-button-radius, var(--xh-_button-radius));
    /* 成组时几何从 ButtonGroup 的私有槽取：高度、内距、间距与字号沿继承流下来 */
    --xh-action-visual-size: var(--xh-button-h, var(--xh-_button-group-h, var(--xh-_action-profile-visual-size)));
    --xh-action-padding-inline: var(--xh-button-px, var(--xh-_button-group-px, var(--xh-_action-profile-padding-inline)));
    --xh-action-gap: var(--xh-button-gap, var(--xh-_button-group-gap, var(--xh-_action-profile-gap)));
    --xh-action-font-size: var(--xh-button-font-size, var(--xh-_button-group-font-size, var(--xh-_action-profile-font-size)));
    /* 圆角只有一个身份：普通 control 的 4px，与 toggle / button-group 一致，按钮没有 shape 轴；
       成组时由按钮组接管相接侧，要换档写 --xh-button-radius */
    --xh-_button-radius: var(--xh-_button-group-radius, var(--xh-shape-control));
    --xh-icon-size: var(--xh-button-icon-size, var(--xh-_action-profile-glyph-size));

    font-weight: var(--xh-button-font-weight, var(--xh-text-label-weight));
  }

  /* Button soft 是登记在册的 raised 消费者：solid 一档静息带顶光与贴地软影，悬停抬到 raised，按下只留顶光。
     成组时段与段共边焊成一条，静息不落软影、悬停不抬起——投影会压到左右两段的面上，
     ButtonGroup 用 --xh-_button-group-shadow-rest / -hover 只留顶光 */
  [data-scope='button'][data-part='root'][data-variant='solid'] {
    --xh-action-highlight-pressed: var(--xh-_highlight-tone);
    --xh-_button-shadow-rest: var(--xh-_button-group-shadow-rest, var(--xh-_highlight-tone), var(--xh-material-soft-shadow));
    --xh-_button-shadow-hover: var(--xh-_button-group-shadow-hover, var(--xh-_highlight-tone), var(--xh-elevation-raised));
    --xh-_button-shadow-pressed: var(--xh-_highlight-tone);
  }

  /* 实心面用对比前景作内环，再加品牌外环；不覆盖表面 box-shadow。 */
  [data-scope='button'][data-part='root'][data-xh-action-variant='solid']:focus-visible {
    --xh-action-ring-color-focus-visible: currentColor;
  }

  [data-scope='button'][data-part='root'][data-xh-action-variant='solid']:focus-visible::before {
    content: '';
    position: absolute;
    inset: calc(-1 * (var(--xh-ring-width) + var(--xh-stroke-thin)));
    border: var(--xh-ring-width) solid var(--xh-ring-focus);
    border-radius: inherit;
    pointer-events: none;
  }

  /* icon profile 已经给出正方视觉盒；Button 的公开 px 槽不能把它重新撑开。 */
  [data-scope='button'][data-part='root'][data-icon-only] {
    --xh-action-padding-inline: 0;
  }

  [data-scope='button'][data-part='root'][data-full-width] {
    inline-size: 100%;
  }

  [data-scope='button'][data-part='label'],
  [data-scope='button'][data-part='prefix'],
  [data-scope='button'][data-part='suffix'],
  [data-scope='button'][data-part='indicator'] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    line-height: inherit;
  }

  [data-scope='button'][data-part='label'] {
    min-inline-size: 0;
  }

  [data-scope='button'][data-part='prefix'],
  [data-scope='button'][data-part='suffix'],
  [data-scope='button'][data-part='indicator'] {
    flex: none;
    line-height: 0;
  }

  [data-scope='button'][data-part='prefix'] > svg,
  [data-scope='button'][data-part='suffix'] > svg,
  [data-scope='button'][data-part='indicator'],
  [data-scope='button'][data-part='indicator'] > svg {
    inline-size: var(--xh-icon-size);
    block-size: var(--xh-icon-size);
  }

  /* indicator 常驻占位；loading 只切换绘制，不靠删节点改变按钮宽度。 */
  [data-scope='button'][data-part='indicator'] {
    visibility: hidden;
  }

  [data-scope='button'][data-part='root'][data-loading] [data-scope='button'][data-part='indicator'] {
    visibility: visible;
    animation: xh-spin var(--xh-button-spin-duration, var(--xh-spin-duration)) var(--xh-motion-ease-loop) infinite;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-scope='button'][data-part='root'][data-loading] [data-scope='button'][data-part='indicator'] {
      animation: none;
    }
  }

  :where([data-motion='reduce'])
    [data-scope='button'][data-part='root'][data-loading]
    [data-scope='button'][data-part='indicator'] {
    animation: none;
  }

  [data-scope='button'][data-part='root'][hidden],
  [data-scope='button'][data-part='label'][hidden],
  [data-scope='button'][data-part='prefix'][hidden],
  [data-scope='button'][data-part='suffix'][hidden],
  [data-scope='button'][data-part='indicator'][hidden] {
    display: none;
  }

  @media (forced-colors: active) {
    [data-scope='button'][data-part='root'][data-xh-action-variant='solid']:focus-visible::before {
      border-color: Highlight;
    }
  }

  @media print {
    [data-scope='button'][data-part='root'] {
      box-shadow: none;
    }

    [data-scope='button'][data-part='root'][data-loading] [data-scope='button'][data-part='indicator'] {
      animation: none;
    }
  }
}

