  }

  [data-scope='date-picker'][data-part='calendar']:has(+ [data-part='time-column']) {
    position: relative;
  }

  [data-scope='date-picker'][data-part='calendar']:has(+ [data-part='time-column'])::after {
    content: '';
    position: absolute;
    inset-block: 0;
    inset-inline-end: calc(-1 * var(--xh-stroke-thin));
    inline-size: var(--xh-stroke-thin);
    background: var(--xh-date-picker-column-divider, var(--xh-material-frosted-separator));
    pointer-events: none;
  }

  [data-scope='date-picker'][data-part='calendar'][hidden] {
    display: none;
  }

