    --xh-collection-fg-hover: var(--xh-fg-default);
    --xh-collection-fg-keyboard-highlight: var(--xh-fg-default);
    --xh-collection-fg-pressed: var(--xh-fg-default);
    --xh-collection-fg-selected: var(--xh-date-picker-preset-fg-selected, var(--xh-fg-default));
    --xh-collection-fg-selected-highlight: var(--xh-date-picker-preset-fg-selected, var(--xh-fg-default));
    --xh-collection-fg-selected-hover: var(--xh-date-picker-preset-fg-selected, var(--xh-fg-default));
    --xh-collection-fg-selected-pressed: var(--xh-date-picker-preset-fg-selected, var(--xh-fg-default));
    --xh-collection-fg-disabled: var(--xh-date-picker-preset-fg-disabled, var(--xh-fg-disabled));
    --xh-collection-bg-hover: var(--xh-date-picker-preset-bg-hover, var(--xh-bg-subtle));
