  [data-scope='date-picker'][data-part='preset'][hidden] {
    display: none;
  }

  [data-scope='date-picker'][data-part='preset']::after {
    content: '';
    position: absolute;
    inset-block-start: 50%;
    inset-inline-end: var(--xh-date-picker-preset-px, var(--xh-space-3));
    inline-size: var(--xh-date-picker-preset-check-size, var(--xh-glyph-size-sm));
    block-size: var(--xh-date-picker-preset-check-size, var(--xh-glyph-size-sm));
    translate: 0 -50%;
    background-color: var(--xh-date-picker-preset-check-fg, var(--xh-_date-picker-check-fg));
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
    -webkit-mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    mask: var(--xh-glyph-mark-check) center / contain no-repeat;
  }

  [data-scope='date-picker'][data-part='preset'][data-state='checked']::after {
    opacity: 1;
  }

  [data-scope='date-picker'][data-part='preset'][data-disabled]::after {
