    );
    --xh-collection-block-padding: var(--xh-date-picker-time-item-py, 0);
    --xh-collection-inline-padding: var(--xh-_date-picker-time-item-rail);
    --xh-collection-font-size: var(--xh-text-secondary-size);
    --xh-collection-radius: var(--xh-date-picker-time-item-radius, var(--xh-shape-control));
    --xh-collection-fg-rest: var(--xh-date-picker-time-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-hover: var(--xh-date-picker-time-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-keyboard-highlight: var(--xh-date-picker-time-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-pressed: var(--xh-date-picker-time-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-selected: var(--xh-date-picker-time-item-fg-selected, var(--xh-date-picker-time-item-fg, var(--xh-material-frosted-fg)));
    --xh-collection-fg-selected-highlight: var(--xh-date-picker-time-item-fg-selected, var(--xh-date-picker-time-item-fg, var(--xh-material-frosted-fg)));
    --xh-collection-fg-selected-hover: var(--xh-date-picker-time-item-fg-selected, var(--xh-date-picker-time-item-fg, var(--xh-material-frosted-fg)));
    --xh-collection-fg-selected-pressed: var(--xh-date-picker-time-item-fg-selected, var(--xh-date-picker-time-item-fg, var(--xh-material-frosted-fg)));
    --xh-collection-font-weight-selected: var(--xh-date-picker-time-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-font-weight-selected-highlight: var(--xh-date-picker-time-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-font-weight-selected-hover: var(--xh-date-picker-time-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-font-weight-selected-pressed: var(--xh-date-picker-time-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-bg-hover: var(--xh-date-picker-time-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-keyboard-highlight: var(--xh-date-picker-time-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-selected-highlight: var(--xh-date-picker-time-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-selected-hover: var(--xh-date-picker-time-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-pressed: var(--xh-date-picker-time-item-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-bg-selected-pressed: var(--xh-date-picker-time-item-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-outline-keyboard-highlight: transparent;
    --xh-collection-outline-selected-highlight: transparent;

    position: relative;
    display: flex;
    flex: none;
    align-items: center;
    justify-content: center;
    block-size: var(--xh-date-picker-time-item-h, calc(var(--xh-control-h-sm) - var(--xh-space-1)));
    font-variant-numeric: tabular-nums;
    text-align: center;
    white-space: nowrap;
    user-select: none;
  }

  [data-scope='date-picker'][data-part='time-item'][hidden] {
    display: none;
  }

  /* 键盘焦点出现时环才接回并立即到位，不压在背景过渡的中间帧上 */
  [data-scope='date-picker'][data-part='time-item']:focus-visible:not(:hover) {
    --xh-collection-outline-keyboard-highlight: var(--xh-ring-focus);
    --xh-collection-outline-selected-highlight: var(--xh-ring-focus);

    transition: none;
  }

