    );
    inline-size: var(--xh-date-picker-time-item-check-size, var(--xh-_date-picker-time-item-check-size));
    block-size: var(--xh-date-picker-time-item-check-size, var(--xh-_date-picker-time-item-check-size));
    translate: 0 -50%;
    background-color: var(--xh-date-picker-time-item-check-fg, var(--xh-_date-picker-check-fg));
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
    -webkit-mask: var(--xh-glyph-mark-check) center / contain no-repeat;
