  [data-scope='date-picker'][data-part='confirm-trigger'] {
    --xh-action-visual-size: var(--xh-date-picker-confirm-trigger-h, var(--xh-_action-profile-visual-size));
    --xh-action-padding-inline: var(--xh-date-picker-confirm-trigger-px, var(--xh-_action-profile-padding-inline));
    --xh-action-radius: var(--xh-date-picker-confirm-trigger-radius, var(--xh-shape-control));
    --xh-action-bg-rest: var(--xh-date-picker-confirm-trigger-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-date-picker-confirm-trigger-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-date-picker-confirm-trigger-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-date-picker-confirm-trigger-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-date-picker-confirm-trigger-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-date-picker-confirm-trigger-fg, var(--xh-_action-variant-fg-pressed));
