    --xh-action-shadow-hover: var(--xh-date-picker-confirm-trigger-shadow, none);
    --xh-action-shadow-pressed: var(--xh-date-picker-confirm-trigger-shadow, none);
    --xh-action-font-size: var(--xh-text-secondary-size);

