    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }

  [data-scope='date-picker'][data-part='trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-calendar) center / contain no-repeat;
    mask: var(--xh-glyph-mark-calendar) center / contain no-repeat;
  }

  @media (forced-colors: active) {
    /* 系统接管底色后仍保住末端对号；禁用标记改用系统失效色。 */
    [data-scope='date-picker'][data-part='preset']::after,
    [data-scope='date-picker'][data-part='time-item']::after {
      forced-color-adjust: none;
      background-color: CanvasText;
    }

    [data-scope='date-picker'][data-part='preset'][data-disabled]::after,
    [data-scope='date-picker'][data-part='time-column'][aria-disabled='true'] [data-part='time-item']::after {
      background-color: GrayText;
    }

    [data-scope='date-picker'][data-part='preset'][data-disabled],
    [data-scope='date-picker'][data-part='time-column'][aria-disabled='true'] [data-part='time-item'] {
      color: GrayText;
    }
  }
}

@layer xihan.motion {
  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。 */
    [data-scope='date-picker'][data-part='positioner'] {
      display: none;
    }
  }
}

/* styles/date-range-picker.css */
/* DateRangePicker 独立皮肤同时传递引入字段视觉盒、字段内动作与浮层集合行；full bundle 递归去重。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='date-range-picker'] {
    --xh-date-range-picker-skin: 1;
  }

  /* 坐标由定位引擎写进 style（inset-inline-start / inset-block-start），这里只定位模式与层级 */
  [data-scope='date-range-picker'][data-part='positioner'] {
    /* 落定那一侧的可用高度，由定位引擎经内联自定义属性写进来，内容层继承它限高；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时不额外限高 */
    --xh-_date-range-picker-available-h: 100vh;
    /* 落定那一侧的可用宽度，同样由定位引擎经内联自定义属性写进来，内容层据此夹住行内轴；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时退到视口宽 */
    --xh-_date-range-picker-available-w: 100vw;

    /* 每个浮层独立声明方向，避免继承祖先浮层的进场位移。 */
    --xh-_overlay-enter-up: 0;
    --xh-_overlay-enter-down: 0;
    --xh-_overlay-enter-left: 0;
    --xh-_overlay-enter-right: 0;

    /* 面板的自绘条浮在内容之上：轨道不上底色，实色轨道会在面板右缘糊出一条竖灰带 */
    --xh-scrollbar-track-bg: transparent;

    position: fixed;
    z-index: var(--xh-date-range-picker-layer, var(--xh-_layer, var(--xh-layer-popover)));
    /* 空壳不吃指针，交互只发生在 content 里 */
    pointer-events: none;
  }

  /* 锚点被滚出可视区：整个浮层随之收起 */
  [data-scope='date-range-picker'][data-part='positioner'][data-hidden] {
    visibility: hidden;
  }

  /* 短位移按实际落位的物理方向给，不随书写方向翻转。 */
  [data-scope='date-range-picker'][data-part='positioner'][data-placement^='top'] {
    --xh-_overlay-enter-down: 1;
  }

  [data-scope='date-range-picker'][data-part='positioner'][data-placement^='bottom'] {
    --xh-_overlay-enter-up: 1;
  }

  [data-scope='date-range-picker'][data-part='positioner'][data-placement^='left'] {
    --xh-_overlay-enter-right: 1;
  }

  [data-scope='date-range-picker'][data-part='positioner'][data-placement^='right'] {
    --xh-_overlay-enter-left: 1;
  }

  /* 私有槽同时声明在根与 positioner 上：浮层被搬到 portal 落点，不是根的后代，继承不过去 */
  [data-scope='date-range-picker']:is([data-part='root'], [data-part='positioner']) {
    /* 尺寸档只换这几个私有槽，标题、输入行与浮层里的部件都从这两处继承它们，
       换档不必给每个部件各写一条选择器；形态三档由家族按 control 上的 data-variant 生成，皮肤不再声明 */
    --xh-_date-range-picker-control-h: var(--xh-control-h-md);
    --xh-_date-range-picker-control-px: var(--xh-control-px-md);
    --xh-_date-range-picker-gap: var(--xh-control-gap-md);
    --xh-_date-range-picker-font-size: var(--xh-control-font-md);

    /* 选中对号随语气走。没写 data-tone 时这几个 --xh-_tone* 没被声明，退回品牌色 */
    /* 内嵌日期段沿用日期输入的轻强调焦点：当前段是「当前项」，淡底 + 淡底前景，不另画一套实心选择态。 */
    --xh-_date-field-segment-bg: var(--xh-_tone-subtle, var(--xh-bg-brand-subtle));
    --xh-_date-field-segment-fg: var(--xh-_tone-fg, var(--xh-fg-on-brand-subtle));
    /* 对号画在普通面上，取语气前景角色，不拿实心强调底色充当前景。 */
    --xh-_date-range-picker-check-fg: var(--xh-_tone, var(--xh-fg-brand));
  }

  /* 与文本框、分段日期同一套堆叠：标签一行、输入行一行 */
  [data-scope='date-range-picker'][data-part='root'] {
    /* 作者塞进指示符槽的图标跟着字号走，与皮肤画的兜底字形同一把尺 */
    --xh-icon-size: var(--xh-date-range-picker-icon-size, var(--xh-glyph-size-md));

    display: inline-flex;
    flex-direction: column;
    gap: var(--xh-date-range-picker-gap, var(--xh-space-1));

    /* 起止两组段位、分隔符与日历钮排在一行，按日的内容本身就比字段缺省宽（--xh-control-w）宽，
       钉成缺省宽会裁掉终点的段位：这一件缺省按内容撑开，使用者要钉宽仍走这条槽。
       地板抬到一族的缺省宽：按年、按月的内容比缺省宽窄，不能比别的字段还窄，底线槽只在高过缺省宽时起作用。
       父容器给不出这么宽时整件跟着收，地板同步让步，不越出父容器 */
    inline-size: var(--xh-date-range-picker-control-w, max-content);
    min-inline-size: min(max(var(--xh-control-w), var(--xh-date-range-picker-control-min-w, var(--xh-control-min-w))), 100%);
    max-inline-size: 100%;
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里 */
  [data-scope='date-range-picker']:is([data-part='root'], [data-part='positioner'])[data-size='sm'] {
    --xh-icon-size: var(--xh-date-range-picker-icon-size, var(--xh-glyph-size-sm));
    --xh-_date-range-picker-control-h: var(--xh-control-h-sm);
    --xh-_date-range-picker-control-px: var(--xh-control-px-sm);
    --xh-_date-range-picker-gap: var(--xh-control-gap-sm);
    --xh-_date-range-picker-font-size: var(--xh-control-font-sm);
  }

  [data-scope='date-range-picker']:is([data-part='root'], [data-part='positioner'])[data-size='lg'] {
    --xh-icon-size: var(--xh-date-range-picker-icon-size, var(--xh-glyph-size-lg));
    --xh-_date-range-picker-control-h: var(--xh-control-h-lg);
    --xh-_date-range-picker-control-px: var(--xh-control-px-lg);
    --xh-_date-range-picker-gap: var(--xh-control-gap-lg);
    --xh-_date-range-picker-font-size: var(--xh-control-font-lg);
  }

  /* 只要声明了 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='date-range-picker'][data-part='root'][hidden] {
    display: none;
  }

  [data-scope='date-range-picker'][data-part='label'] {
    color: var(--xh-date-range-picker-label-fg, var(--xh-fg-default));
    font-size: var(--xh-date-range-picker-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-date-range-picker-label-font-weight, var(--xh-text-label-weight));
    line-height: var(--xh-leading-none);
  }

  [data-scope='date-range-picker'][data-part='label'][hidden] {
    display: none;
  }

  [data-scope='date-range-picker'][data-part='label'][data-disabled] {
    color: var(--xh-date-range-picker-label-fg-disabled, var(--xh-fg-subtle));
  }

  /* 画成一个框的是 control 而不是 input：段位、清空按钮、日历按钮三者要看起来是一体的，
     边框长在里面任何一个身上都会把另外两个割在框外。描边、底色、圆角、聚焦环、五态与悬停由
     Field Chrome 家族画在 control 上（焦点落在段或按钮上，家族 :focus-within 让整框亮起来）；
     组件只映射既有公开槽（shadow 缺省 none：字段静息描边式、无影）。打开中不另画环，由浮层本身承担 */
  [data-scope='date-range-picker'][data-part='control'] {
    --xh-field-control-height: var(--xh-date-range-picker-control-h, var(--xh-_date-range-picker-control-h));
    --xh-field-control-padding-inline: var(--xh-date-range-picker-control-px, var(--xh-_date-range-picker-control-px));
    --xh-field-control-gap: var(--xh-date-range-picker-control-gap, var(--xh-_date-range-picker-gap));
    --xh-field-control-min-inline-size: var(--xh-date-range-picker-control-min-w, var(--xh-control-min-w));
    --xh-field-control-radius: var(--xh-date-range-picker-control-radius, var(--xh-shape-control));
    --xh-field-bg-rest: var(--xh-date-range-picker-control-bg, var(--xh-_field-variant-bg-rest));
    --xh-field-bg-hover: var(--xh-date-range-picker-control-bg-hover, var(--xh-_field-variant-bg-hover));
    --xh-field-bg-read-only: var(--xh-date-range-picker-control-bg-readonly, var(--xh-_field-variant-bg-read-only));
    --xh-field-bg-disabled: var(--xh-date-range-picker-control-bg-disabled, var(--xh-_field-variant-bg-disabled));
    --xh-field-fg-rest: var(--xh-date-range-picker-control-fg, var(--xh-fg-default));
    --xh-field-border-rest: var(--xh-date-range-picker-control-border, var(--xh-_field-variant-border-rest));
    --xh-field-border-hover: var(--xh-date-range-picker-control-border-hover, var(--xh-_field-variant-border-hover));
    --xh-field-border-focus: var(--xh-date-range-picker-control-border-focus, var(--xh-_field-variant-border-focus));
    --xh-field-border-invalid: var(--xh-date-range-picker-control-border-invalid, var(--xh-_field-variant-border-invalid));
    --xh-field-ring-focus: var(--xh-ring-focus);
    --xh-field-ring-invalid: var(--xh-ring-invalid);
    --xh-field-shadow-rest: var(--xh-date-range-picker-control-shadow, none);
    /* 段位靠键盘编辑，盒上不是文本光标 */
    --xh-field-cursor-rest: default;
    /* 家族 chrome 会重写 --xh-icon-size，使用者图标槽必须经桥接槽下发才能在盒内生效 */
    --xh-field-glyph-size: var(--xh-date-range-picker-icon-size, var(--xh-_field-size-glyph-size));
  }

  [data-scope='date-range-picker'][data-part='control'][hidden] {
    display: none;
  }

  /* 段位与作者写在段间的分隔符都在这一层里：段位自己那身皮由 date-field 那份样式负责
     （它们戴的是那一份解剖的标记），这里只管把一排段位横过来、占满输入行剩下的宽度 */
  [data-scope='date-range-picker'][data-part='segment-group'] {
    display: inline-flex;
    flex: 1 1 auto;
    align-items: center;
    min-inline-size: 0;
    block-size: 100%;
    color: inherit;
    /* 表单控件不继承页面字体，只给字号会让段位用 UA 默认字族，与周围文本对不上 */
    font-family: inherit;
    font-size: var(--xh-date-range-picker-font-size, var(--xh-_date-range-picker-font-size));
    line-height: var(--xh-leading-none);
  }

  [data-scope='date-range-picker'][data-part='segment-group'][hidden] {
    display: none;
  }

  /* 起点那组只占自己的宽度，分隔符紧跟在起点后面；剩下的宽度全给终点那组 */
  [data-scope='date-range-picker'][data-part='segment-group'][data-index='0']:has(+ [data-part='range-separator']) {
    flex: 0 0 auto;
  }

  [data-scope='date-range-picker'][data-part='range-separator'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    /* 两侧各留一个小间距：把输入行的常规间距收回来，再补上自己那一份 */
    --xh-_date-range-picker-range-separator-mx: calc(var(--xh-date-range-picker-range-separator-px, var(--xh-space-1)) - var(--xh-date-range-picker-control-gap, var(--xh-_date-range-picker-gap)));

    margin-inline: var(--xh-date-range-picker-range-separator-mx, var(--xh-_date-range-picker-range-separator-mx));
    padding-inline: var(--xh-date-range-picker-range-separator-px, var(--xh-space-1));
    color: var(--xh-date-range-picker-range-separator-fg, var(--xh-fg-subtle));
    font: inherit;
    line-height: var(--xh-leading-none);
    pointer-events: none;
    user-select: none;
  }

  /* 作者自己给分隔符加 hidden 时也真的收起：上面那条 display 会盖掉 UA 的兜底 */
  [data-scope='date-range-picker'][data-part='range-separator'][hidden] {
    display: none;
  }

  [data-scope='date-range-picker'][data-part='segment-group'] > :not([data-scope]) {
    color: var(--xh-date-range-picker-literal-fg, var(--xh-fg-subtle));
  }

  /* 容器自己不占 Tab 位、也不承载焦点，环由 control 画，这里不再套一圈 */
  [data-scope='date-range-picker'][data-part='segment-group']:focus-visible {
    outline: none;
  }

  /* 两个按钮同一副长相：贴在框内末端的小方钮，不占宽度也不撑高 control。正方视觉盒、inset 圆角、
     悬停 100 / 按下 200 与 0.97 按压、粗指针热区、禁用面与 :focus-visible 关环（盒的 :focus-within
     已画了一圈）全由 Action Control 的 field-inset ghost 档给，组件只映射既有覆盖槽。
     打开中与悬停同档：日历钮不另上底，方向由浮层本身承担 */
  [data-scope='date-range-picker'][data-part='trigger'],
  [data-scope='date-range-picker'][data-part='clear-trigger'] {
    --xh-action-visual-size: var(--xh-date-range-picker-action-size, var(--xh-_action-profile-visual-size));
    --xh-action-min-inline-size: var(--xh-date-range-picker-action-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-date-range-picker-action-radius, var(--xh-shape-inset));
    /* 底色阶梯由 ghost 档给（透明 → 100 → 200），使用者槽只作覆盖入口 */
    --xh-action-bg-rest: var(--xh-date-range-picker-action-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-date-range-picker-action-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-date-range-picker-action-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-date-range-picker-action-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-date-range-picker-action-fg-hover, var(--xh-fg-default));
    --xh-action-border-rest: transparent;
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    --xh-action-font-size: var(--xh-date-range-picker-action-font-size, var(--xh-text-secondary-size));
    /* 配方尚未把 profile 字形档灌进 --xh-icon-size，钮内字形先按 field-inset 档逐钮取值 */
    --xh-icon-size: var(--xh-_action-profile-glyph-size);

    border-width: 0;
  }

  /* 没值时连接层给的是 hidden 属性；家族那条 display 会把 UA 规则盖掉 */
  [data-scope='date-range-picker'][data-part='trigger'][hidden],
  [data-scope='date-range-picker'][data-part='clear-trigger'][hidden] {
    display: none;
  }

  /* 打开中与悬停同档：日历钮的静息底换到悬停那一支中性面，不用品牌色、不另画环；方向由浮层本身承担 */
  [data-scope='date-range-picker'][data-part='trigger'][data-state='open'] {
    --xh-action-bg-rest: var(--xh-date-range-picker-action-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-fg-rest: var(--xh-date-range-picker-action-fg-hover, var(--xh-fg-default));
  }

  /* 有值时清空钮顶上来，日历钮让位：两颗并排堆着用户分不清点哪个 */
  [data-scope='date-range-picker'][data-part='control']:has(
      > [data-scope='date-range-picker'][data-part='clear-trigger']:not([hidden])
    )
    > [data-scope='date-range-picker'][data-part='trigger'] {
    display: none;
  }

  /* 浮层：含两张日历网格的锚定面板，走 floating 材质——实体底 + --xh-border-default 描边 +
     --xh-elevation-floating 落影，不透景、不画顶光 */
  [data-scope='date-range-picker'][data-part='content'] {
    position: relative;
    display: block;
    /* 行内轴只有落位后的可用宽度这一个上限：不夹住，浮层就会被定位层的包含块压窄，
       网格轨道跟着缩到比日期钮还窄，相邻两颗日期钮互相盖住 */
    max-inline-size: var(--xh-_date-range-picker-available-w);
    padding-block: var(--xh-date-range-picker-content-py, var(--xh-space-2));
    padding-inline: var(--xh-date-range-picker-content-px, var(--xh-space-2));
    border: var(--xh-stroke-thin) solid var(--xh-date-range-picker-content-border, var(--xh-border-default));
    border-radius: var(--xh-date-range-picker-content-radius, var(--xh-shape-overlay));
    background: var(--xh-date-range-picker-content-bg, var(--xh-bg-surface));
    color: var(--xh-date-range-picker-content-fg, var(--xh-fg-default));
    /* 日历是定高结构：六行日期加表头本来就有固定高度，上限走页内滚动面那一档；
       可用高度是定位引擎算出的视口余量，视口真放不下时再收一截 */
    max-block-size: min(var(--xh-date-range-picker-max-h, var(--xh-viewport-h-lg)), var(--xh-_date-range-picker-available-h));
    /* 两轴都滚：块轴放不下时面板内自己竖滚，行内轴放不下时面板内自己横滚，
       日历那几块保持各自的天然宽度，不被压 */
    overflow: auto;
    /* 浮层滚动面：滚到头不把页面一起带走 */
    overscroll-behavior: contain;
    box-shadow: var(--xh-date-range-picker-content-shadow, var(--xh-elevation-floating));
    pointer-events: auto;
    /* 快捷选项列的条子贴在它的盒子上、挂在这一层里（它已是定位盒）：轨道不画底 */
    --xh-scrollbar-track-bg: transparent;
  }

  /* 这里刻意没有 [data-part='content'][hidden] { display: none }，与 dialog 一致：
     收起态连接层会给 content 打 hidden，而上面那条 display 正是要盖掉 UA 的
     [hidden]{display:none}——退场动画得先能播。presence 读的是 content 的 animationName，
     真正的收起由宿主在退场结束后落成内联 display:none（Vue 那边直接不渲染）。
     其余声明了 display 的角色节点仍补 [hidden]，那几处没有退场动画。 */

  /* 浮层壳不承载焦点（焦点直接落到聚焦日那一格），但它写着 tabindex=-1，
     程序化落焦时不该再画一圈环 */
  [data-scope='date-range-picker'][data-part='content']:focus-visible {
    outline: none;
  }

  [data-scope='date-range-picker'][data-part='content'][data-state='open'] {
    animation: xh-overlay-slide-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 退场：收起那一帧 hidden 由退场闸门押后，这里才播得出来。forwards 把末态钉住，
     免得动画结束到真收起之间闪一下原样 */
  [data-scope='date-range-picker'][data-part='content'][data-state='closed'] {
    animation: xh-overlay-slide-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* 内嵌日历的挂载点同时充当日历的根节点：日历那份样式的 root 规则落在
     [data-scope='calendar-range-picker'][data-part='root'] 上，而这里没有那个节点，
     所以网格外层该有的排布得在这儿补齐（网格内部的皮仍归 calendar-range-picker 那一份） */
  /* 真的摆了两张日历才横过来。写成 :has 而不是无条件 flex 行：
     作者可能在 content 里再包一层自己的块，无条件横排会把它并到日历旁边去。
     不加 :not([hidden])：content 收起态带 hidden 但仍在播退场动画，
     排除掉会让它在那几帧退回 block、两张日历竖着堆一下。
     并排放不下就折行，第二张月历落到第一张下面：视口窄与面板被夹窄都命中这一条 */
  [data-scope='date-range-picker'][data-part='content']:has(> [data-part='calendar'] + [data-part='calendar']) {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
  }

  /* 快捷选项列摆在日历的行内起始一侧，同样只在它真在场时才横过来。
     与上一条同理：不加 :not([hidden])，退场那几帧塌回 block 会让两块竖着堆一下。
     一并折行：选项条在手机档占满一行，日历落到它下面 */
  [data-scope='date-range-picker'][data-part='content']:has(> [data-part='preset-group']) {
    display: flex;
    flex-wrap: wrap;
    align-items: stretch;
  }

  /* 第二个起的面板画一道分隔线：两张网格挨着排时要有条界，
     否则 8 月末与 9 月初那两列看着像同一张表。
     手机档两张月历折行堆叠，线画在块起始边 */
  [data-scope='date-range-picker'][data-part='calendar'] + [data-scope='date-range-picker'][data-part='calendar'] {
    padding-block-start: var(--xh-date-range-picker-panel-gap, var(--xh-space-3));
    border-block-start: var(--xh-stroke-thin) solid var(--xh-date-range-picker-panel-divider, var(--xh-material-frosted-separator));
  }

  /* 平板起两张月历并排放得下，线改画在行内起始边 */
  @media (min-width: 768px) {
    [data-scope='date-range-picker'][data-part='calendar'] + [data-scope='date-range-picker'][data-part='calendar'] {
      padding-block-start: 0;
      padding-inline-start: var(--xh-date-range-picker-panel-gap, var(--xh-space-3));
      border-block-start: none;
      border-inline-start: var(--xh-stroke-thin) solid var(--xh-date-range-picker-panel-divider, var(--xh-material-frosted-separator));
    }
  }

  /* 快捷选项与它旁边那张日历之间留出同样的空当。
     手机档选项条在上、日历在下，空当留在块轴。
     选项列后面紧跟着它自己的两条条子节点，相邻选择器接不到日历，按「前面有过选项列」取日历 */
  [data-scope='date-range-picker'][data-part='preset-group'] ~ [data-scope='date-range-picker'][data-part='calendar'] {
    padding-block-start: var(--xh-date-range-picker-panel-gap, var(--xh-space-3));
  }

  /* 平板起选项列回到日历一侧，空当跟着回到行内轴，两道分隔线左右对称 */
  @media (min-width: 768px) {
    [data-scope='date-range-picker'][data-part='preset-group'] ~ [data-scope='date-range-picker'][data-part='calendar'] {
      padding-block-start: 0;
      padding-inline-start: var(--xh-date-range-picker-panel-gap, var(--xh-space-3));
    }
  }

  [data-scope='date-range-picker'][data-part='calendar'] {
    display: flex;
    /* 面板被夹窄时不跟着缩：日期钮的宽度是定死的，网格轨道再窄下去就会与右邻的钮叠在一起。
       撑出去的那截交给面板自己横滚 */
    min-inline-size: max-content;
    flex-direction: column;
    gap: var(--xh-date-range-picker-calendar-gap, var(--xh-space-2));
    /* 数字等宽：1 与 7 的字形宽度在比例字体里并不相同，不定住会让整张网格随月份抖动 */
    font-variant-numeric: tabular-nums;
  }

  [data-scope='date-range-picker'][data-part='calendar'][hidden] {
    display: none;
  }

  /* —— 快捷选项：一条按钮式条目 —— */
  /* 手机档：整条压在面板顶部占满一行，条目横着排，放不下就这一条自己横滚 */
  [data-scope='date-range-picker'][data-part='preset-group'] {
    display: flex;
    /* 独占面板的一整行，后面的日历折到它下面 */
    flex: 0 0 100%;
    /* 这一条的另一轴由并排的那块给：不写就按内容收，分隔线只画到最后一条选项 */
    align-self: stretch;
    flex-direction: row;
    gap: var(--xh-date-range-picker-preset-group-gap, var(--xh-list-option-gap));
    /* 选项多起来时这一条自己滚，不把整张面板撑大 */
    max-block-size: var(--xh-date-range-picker-preset-group-h, var(--xh-viewport-h-lg));
    padding: var(--xh-date-range-picker-preset-group-padding, var(--xh-space-1));
    overflow-x: auto;
    overflow-y: hidden;
    /* 浮层滚动面：滚到头不把页面一起带走 */
    overscroll-behavior: contain;
    border-block-end: var(--xh-stroke-thin) solid var(--xh-date-range-picker-column-divider, var(--xh-material-frosted-separator));
  }

  /* 平板起：换成贴在日历行内起始一侧的竖列，滚动轴与分隔线一起转过来 */
  @media (min-width: 768px) {
    [data-scope='date-range-picker'][data-part='preset-group'] {
      flex: none;
      flex-direction: column;
      overflow: auto;
      border-block-end: none;
      border-inline-end: var(--xh-stroke-thin) solid var(--xh-date-range-picker-column-divider, var(--xh-material-frosted-separator));
    }
  }

  [data-scope='date-range-picker'][data-part='preset-group'][hidden] {
    display: none;
  }

  /* 快捷选项：悬停 / 高亮 100、按下 200、禁用面由 Collection Item 家族按 overlay 语境给（选中 = 透明底 +
     行尾对号，正文保持 rest 色与常规字重）。选项没有正文部件，匿名文本进不了家族网格的 text 列，
     行保持块级排版，末端为对号预留固定轨 */
  [data-scope='date-range-picker'][data-part='preset'] {
    --xh-collection-block-padding: var(--xh-date-range-picker-preset-py, var(--xh-space-1));
    --xh-collection-inline-padding: var(--xh-date-range-picker-preset-px, var(--xh-space-3));
    --xh-collection-font-size: var(--xh-text-secondary-size);
    --xh-collection-radius: var(--xh-date-range-picker-preset-radius, var(--xh-shape-control));
    /* 面板是实体面（floating），正文取页面前景 */
    --xh-collection-fg-rest: var(--xh-fg-default);
    --xh-collection-fg-hover: var(--xh-fg-default);
    --xh-collection-fg-keyboard-highlight: var(--xh-fg-default);
    --xh-collection-fg-pressed: var(--xh-fg-default);
    --xh-collection-fg-selected: var(--xh-date-range-picker-preset-fg-selected, var(--xh-fg-default));
    --xh-collection-fg-selected-highlight: var(--xh-date-range-picker-preset-fg-selected, var(--xh-fg-default));
    --xh-collection-fg-selected-hover: var(--xh-date-range-picker-preset-fg-selected, var(--xh-fg-default));
    --xh-collection-fg-selected-pressed: var(--xh-date-range-picker-preset-fg-selected, var(--xh-fg-default));
    --xh-collection-fg-disabled: var(--xh-date-range-picker-preset-fg-disabled, var(--xh-fg-disabled));
    --xh-collection-bg-hover: var(--xh-date-range-picker-preset-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-keyboard-highlight: var(--xh-date-range-picker-preset-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-selected-highlight: var(--xh-date-range-picker-preset-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-selected-hover: var(--xh-date-range-picker-preset-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-pressed: var(--xh-date-range-picker-preset-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-bg-selected-pressed: var(--xh-date-range-picker-preset-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-outline-keyboard-highlight: transparent;
    --xh-collection-outline-selected-highlight: transparent;

    /* 横着排那一档不许被压扁：条目文本本来就不折行 */
    position: relative;
    display: block;
    flex: none;
    /* 对号的末端轨始终留着，切换选中时文字与整列宽度都不移动。 */
    padding-inline-end: calc(
      var(--xh-date-range-picker-preset-px, var(--xh-space-3)) +
        var(--xh-date-range-picker-preset-check-size, var(--xh-glyph-size-sm)) +
        var(--xh-space-1)
    );
    white-space: nowrap;
    user-select: none;
  }

  /* 键盘焦点出现时环才接回并立即到位，不压在背景过渡的中间帧上 */
  [data-scope='date-range-picker'][data-part='preset']:focus-visible:not(:hover) {
    --xh-collection-outline-keyboard-highlight: var(--xh-ring-focus);
    --xh-collection-outline-selected-highlight: var(--xh-ring-focus);

    transition: none;
  }

  /* 上面给了 display，UA 的 [hidden]{display:none} 已被盖掉，这里补回来 */
  [data-scope='date-range-picker'][data-part='preset'][hidden] {
    display: none;
  }

  [data-scope='date-range-picker'][data-part='preset']::after {
    content: '';
    position: absolute;
    inset-block-start: 50%;
    inset-inline-end: var(--xh-date-range-picker-preset-px, var(--xh-space-3));
    inline-size: var(--xh-date-range-picker-preset-check-size, var(--xh-glyph-size-sm));
    block-size: var(--xh-date-range-picker-preset-check-size, var(--xh-glyph-size-sm));
    translate: 0 -50%;
    background-color: var(--xh-date-range-picker-preset-check-fg, var(--xh-_date-range-picker-check-fg));
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
    -webkit-mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    mask: var(--xh-glyph-mark-check) center / contain no-repeat;
  }

  [data-scope='date-range-picker'][data-part='preset'][data-state='checked']::after {
    opacity: 1;
  }

  [data-scope='date-range-picker'][data-part='preset'][data-disabled]::after {
    background-color: var(--xh-date-range-picker-preset-fg-disabled, var(--xh-fg-disabled));
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中 */
  [data-scope='date-range-picker'][data-part='clear-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }

  [data-scope='date-range-picker'][data-part='trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-calendar) center / contain no-repeat;
    mask: var(--xh-glyph-mark-calendar) center / contain no-repeat;
  }

  @media (forced-colors: active) {
    /* 系统接管底色后仍保住末端对号；禁用标记改用系统失效色。 */
    [data-scope='date-range-picker'][data-part='preset']::after {
      forced-color-adjust: none;
      background-color: CanvasText;
    }

    [data-scope='date-range-picker'][data-part='preset'][data-disabled]::after {
      background-color: GrayText;
    }

    [data-scope='date-range-picker'][data-part='preset'][data-disabled] {
      color: GrayText;
    }
  }
}

@layer xihan.motion {
  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。 */
    [data-scope='date-range-picker'][data-part='positioner'] {
      display: none;
    }
  }
}

/* styles/dialog.css */
/* 定义 dialog 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='dialog'] {
    --xh-dialog-skin: 1;
  }

  /*
   * 触发器是页面上的独立文字按钮：盒型、md 档几何、outline 四态面、0.97 按压并换底与粗指针命中区
   * 由家族配方按连接层投影的 data-xh-action-variant / -size 给出。皮肤没有自己的外观规则，
   * 只把作者塞进按钮的图标接到随档字形尺（md = 20px）。
   */
  [data-scope='dialog'][data-part='trigger'] {
    --xh-icon-size: var(--xh-dialog-icon-size, var(--xh-_action-profile-glyph-size));
  }

  /* 家族配方给了 display，作者手写 hidden 时得把 UA 的 [hidden]{display:none} 还回去 */
  [data-scope='dialog'][data-part='trigger'][hidden] {
    display: none;
  }

  [data-scope='dialog'][data-part='backdrop'] {
    position: fixed;
    inset: 0;
    z-index: var(--xh-dialog-backdrop-layer, var(--xh-_layer, var(--xh-layer-modal)));
    background: var(--xh-dialog-backdrop-bg, var(--xh-bg-overlay));
  }

  /* 同一层 dim 之上再做一层短半径采样。默认 opaque 的语义不变；只有作者显式选 blur
     才会启用。保留既有 blur 槽，新的完整 filter 槽可覆盖整个表达。 */
  [data-scope='dialog'][data-part='backdrop'][data-variant='blur'] {
    -webkit-backdrop-filter: var(--xh-dialog-backdrop-filter, blur(var(--xh-dialog-backdrop-blur, var(--xh-overlay-backdrop-blur))));
    backdrop-filter: var(--xh-dialog-backdrop-filter, blur(var(--xh-dialog-backdrop-blur, var(--xh-overlay-backdrop-blur))));
  }

  /* 去掉底色，只留下这一层吃指针：交互外关闭与滚动锁定照旧 */
  [data-scope='dialog'][data-part='backdrop'][data-variant='transparent'] {
    background: transparent;
  }

  [data-scope='dialog'][data-part='backdrop'][data-state='open'] {
    animation: xh-fade-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter);
  }

  /* 退场补 forwards：动画播完到宿主真正卸载之间还有一帧，不定住终态遮罩会闪回全黑 */
  [data-scope='dialog'][data-part='backdrop'][data-state='closed'] {
    animation: xh-fade-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  [data-scope='dialog'][data-part='positioner'] {
    position: fixed;
    inset: 0;
    z-index: var(--xh-dialog-layer, var(--xh-_layer, var(--xh-layer-modal)));
    display: flex;
    align-items: center;
    justify-content: center;
    /* 全屏定位层只负责排版，不截获页面指针；模态拦截由 backdrop 承担。 */
    pointer-events: none;
    /* 这段内衬是面板与视口边之间的全部距离，与安全区取大的一头：
       刘海、圆角与底部横条压住的那一段由系统给出，内衬比它窄时面板的一角会被切掉。
       桌面上 env() 恒为 0，取值与内衬槽完全一致。安全区只有物理方向的四个名字，
       行内轴上两侧同取较宽的那一段，RTL 下不会翻错边。 */
    padding-block-start: max(var(--xh-dialog-positioner-padding, var(--xh-space-4)), env(safe-area-inset-top));
    padding-block-end: max(var(--xh-dialog-positioner-padding, var(--xh-space-4)), env(safe-area-inset-bottom));
    padding-inline: max(
      var(--xh-dialog-positioner-padding, var(--xh-space-4)),
      env(safe-area-inset-left),
      env(safe-area-inset-right)
    );
  }

  [data-scope='dialog'][data-part='content'] {
    /* 作者塞进面板里的图标按控件档取；语气徽记与关闭钮另有各自的尺 */
    --xh-icon-size: var(--xh-dialog-icon-size, var(--xh-glyph-size-md));

    /* 尺寸档只换这一个私有槽。它声明在 content 而不是别处：dialog 的解剖里没有 root，
       positioner 又不是必需部件，content 才是这层浮层恒在的最外层，且它会被 portal 到 body，
       选择器只认得它自己身上那一份 data-size。 */
    --xh-_dialog-max-w: var(--xh-overlay-sheet-w-md);

    /* positioner 不吃指针，面板自身恢复交互。 */
    pointer-events: auto;

    position: relative;
    inline-size: 100%;
    max-inline-size: var(--xh-dialog-max-w, var(--xh-_dialog-max-w));
    display: flex;
    flex-direction: column;
    gap: var(--xh-dialog-gap, var(--xh-stack-gap-md));
    padding-block: var(--xh-dialog-py, var(--xh-surface-py-md));
    padding-inline: var(--xh-dialog-px, var(--xh-surface-px-md));
    border: var(--xh-stroke-thin) solid var(--xh-dialog-border, var(--xh-material-elevated-border));
    border-radius: var(--xh-dialog-radius, var(--xh-shape-overlay));
    /* M4 是不透明的 sheet 实体面；顶部 lens 与正文同一实体面，作者可用 --xh-dialog-header-bg 单独换头部底色，
       让标题保留空间感而不把长正文也放进透明区。两层都先留组件公开槽。 */
    background:
      linear-gradient(
        to bottom,
        var(--xh-dialog-highlight, var(--xh-material-elevated-highlight)) 0 var(--xh-stroke-thin),
        transparent var(--xh-stroke-thin)
      ),
      linear-gradient(
        to bottom,
        var(--xh-dialog-content-lens-bg, var(--xh-dialog-header-bg, var(--xh-material-elevated-bg))),
        var(
          --xh-dialog-bg,
          var(--xh-material-elevated-bg)
        ) var(--xh-dialog-content-lens-depth, var(--xh-dialog-header-lens-depth, calc(var(--xh-dialog-py, var(--xh-surface-py-md)) + var(--xh-control-h-md))))
      );
    color: var(--xh-dialog-fg, var(--xh-material-elevated-fg));
    box-shadow: var(--xh-dialog-shadow, var(--xh-material-elevated-shadow));
    -webkit-backdrop-filter: var(--xh-dialog-content-backdrop-filter, var(--xh-dialog-backdrop-filter, var(--xh-material-elevated-backdrop)));
    backdrop-filter: var(--xh-dialog-content-backdrop-filter, var(--xh-dialog-backdrop-filter, var(--xh-material-elevated-backdrop)));
  }

  /* 这里刻意没有 [data-part='content'][hidden] { display: none }，与 drawer 一致：
     收起态连接层会给 content 打 hidden，而上面那条 display: flex 正是要盖掉 UA 的
     [hidden]{display:none}——退场动画得先能播。presence 读的是 content 的 animationName，
     读到才申领租约、等 animationend 才卸载；一旦 display: none，元素不生成盒子、
     动画根本不启动，探测器直接放弃租约，退场动画一帧都播不出来。
     真正的收起由适配器兜住：Vue 卸载整棵，WC 写内联 style.display。
     其余声明了 display 的角色节点仍补 [hidden]，那几处没有退场动画。 */

  /* —— 尺寸 —— */
  /* 只有最大宽度分档；中间档不写规则，缺省即中档。
     宽度上限之外的一切（内边距、字号、圆角）都不随档位动：弹层的语气归里面的内容表达。 */
  [data-scope='dialog'][data-part='content'][data-size='sm'] {
    --xh-_dialog-max-w: var(--xh-overlay-sheet-w-sm);
  }

  [data-scope='dialog'][data-part='content'][data-size='lg'] {
    --xh-_dialog-max-w: var(--xh-overlay-sheet-w-lg);
  }

  [data-scope='dialog'][data-part='content']:focus-visible {
    outline: none;
  }

  [data-scope='dialog'][data-part='content'][data-state='open'] {
    animation: xh-sheet-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  [data-scope='dialog'][data-part='content'][data-state='closed'] {
    animation: xh-sheet-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* —— 面板三段 —— */
  /* header / body / footer 把面板切成「头尾定在原处、正文自己滚」三段，
     与抽屉、浮动面板同一套角色划分：头尾不参与压缩，正文吃掉剩下的高度并自己滚。
     面板的内衬仍由 content 一层给出，三段只接手段与段之间那道缝——
     内衬换成三段各留一份，安全区与局部容器两档就要在三处各算一遍。
     写了正文段的这一档同时封顶：不封顶正文永远没有可滚的余量，滚动条出不来。 */
  [data-scope='dialog'][data-part='content']:has([data-scope='dialog'][data-part='body']) {
    max-block-size: 100%;
    gap: 0;
    overflow: hidden;
  }

  /* 头段：标题与说明纵向堆叠；不参与压缩，正文再长也压不扁它 */
  [data-scope='dialog'][data-part='header'] {
    flex: none;
    display: flex;
    flex-direction: column;
    gap: var(--xh-dialog-header-gap, var(--xh-stack-gap-sm));
    padding-block-end: var(--xh-dialog-header-pb, var(--xh-space-2));
  }

  /* 三段结构出现时，分隔线走 M4 令牌；无 body / footer 的轻量对话框不会凭空多一条线。 */
  [data-scope='dialog'][data-part='content']:has([data-scope='dialog'][data-part='body'])
    [data-scope='dialog'][data-part='header'] {
    border-block-end: var(--xh-stroke-thin) solid var(--xh-dialog-separator, var(--xh-material-elevated-separator));
  }

  /* 语气徽记：圆底与字形两层。圆底是这个节点自己（底色、直径、圆角），字形走下面那条
     :empty::before；作者往里塞了节点，兜底那几条即不命中，整枚换成他的图形。
     底与前景取语气层派生好的槽，不在这儿另兑一遍——兑法差一档，字形压上去的对比度
     就跟着差一档。节点自己带 data-tone 时那一族的槽就声明在它身上。 */
  [data-scope='dialog'][data-part='indicator'] {
    /* 圆底里的图形四边各收一个 space-1，不顶到圆边上；
       这把尺同时给作者塞进来的图标，换成 XhIcon 也不会撑破圆底 */
    --xh-icon-size: var(--xh-dialog-indicator-mark-size, calc(var(--xh-dialog-indicator-size, var(--xh-glyph-size-md)) - 2 * var(--xh-space-1)));

    flex: none;
    display: grid;
    place-items: center;
    inline-size: var(--xh-dialog-indicator-size, var(--xh-glyph-size-md));
    block-size: var(--xh-dialog-indicator-size, var(--xh-glyph-size-md));
    border-radius: var(--xh-dialog-indicator-radius, var(--xh-shape-circle));
    background: var(--xh-dialog-indicator-bg, var(--xh-_tone-subtle, var(--xh-bg-muted)));
    color: var(--xh-dialog-indicator-fg, var(--xh-_tone-fg, var(--xh-fg-default)));
  }

  [data-scope='dialog'][data-part='indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-info) center / contain no-repeat;
    mask: var(--xh-glyph-mark-info) center / contain no-repeat;
  }

  /* 画哪枚字形跟着语气走，与命令式服务弹出来的那一枚同一套映射 */
  [data-scope='dialog'][data-part='indicator'][data-tone='success']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-check);
    mask-image: var(--xh-glyph-mark-check);
  }

  [data-scope='dialog'][data-part='indicator'][data-tone='warning']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-warning);
    mask-image: var(--xh-glyph-mark-warning);
  }

  [data-scope='dialog'][data-part='indicator'][data-tone='danger']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-close);
    mask-image: var(--xh-glyph-mark-close);
  }

  /* 正文段：面板里唯一会滚的一段。最小高度归零，
     否则弹性项按内容撑高，容器再矮也不产生溢出，滚动条永远出不来。
     模态 body 是原生细条滚动面：细条由 reset 层统一给，滚到头不把页面一起带走 */
  [data-scope='dialog'][data-part='body'] {
    flex: 1 1 auto;
    min-block-size: 0;
    overflow: auto;
    overscroll-behavior: contain;
  }

  /* 正文高度随交互变化（表单校验、展开段落）：还在用原生滚动条的正文留一条稳定空道，
     滚动条出现与消失时不推动文字。带 data-xh-scrollbar 的容器已经把原生条藏成零宽，排除掉 */
  [data-scope='dialog'][data-part='body']:not([data-xh-scrollbar]) {
    scrollbar-gutter: stable;
  }

  /* 尾段：动作按钮排一行靠尾；同样不参与压缩 */
  [data-scope='dialog'][data-part='footer'] {
    flex: none;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: var(--xh-dialog-footer-gap, var(--xh-control-gap-md));
    padding-block-start: var(--xh-dialog-footer-pt, var(--xh-space-2));
  }

  [data-scope='dialog'][data-part='content']:has([data-scope='dialog'][data-part='footer'])
    [data-scope='dialog'][data-part='footer'] {
    border-block-start: var(--xh-stroke-thin) solid var(--xh-dialog-separator, var(--xh-material-elevated-separator));
  }

  /* 声明过 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='dialog'][data-part='header'][hidden],
  [data-scope='dialog'][data-part='body'][hidden],
  [data-scope='dialog'][data-part='footer'][hidden] {
    display: none;
  }

  [data-scope='dialog'][data-part='title'] {
    margin: 0;
    font-size: var(--xh-dialog-title-font-size, var(--xh-text-heading-3-size));
    font-weight: var(--xh-dialog-title-font-weight, var(--xh-text-heading-3-weight));
    color: var(--xh-dialog-title-fg, var(--xh-fg-default));
  }

  /* 说明文字走说明档：13px + fg-muted */
  [data-scope='dialog'][data-part='description'] {
    margin: 0;
    font-size: var(--xh-dialog-description-font-size, var(--xh-text-secondary-size));
    color: var(--xh-dialog-description-fg, var(--xh-fg-muted));
  }

  /* 关闭按钮是绝对定位的，不占流内宽度：标题得自己让出右上角那块，
     否则长标题会直接钻到按钮底下。只在真有关闭按钮时让位。 */
  [data-scope='dialog'][data-part='content']:has([data-scope='dialog'][data-part='close-trigger'])
    [data-scope='dialog'][data-part='title'] {
    padding-inline-end: calc(var(--xh-dialog-close-size, var(--xh-control-h-sm)) + var(--xh-surface-action-inset));
  }

  /*
   * 关闭钮是面板角落的单图标钮：正方盒、sm 档几何、ghost 四态面、0.97 按压并换底与粗指针命中区
   * 由家族配方给出——白面上走画布承载阶梯悬停 --xh-bg-subtle（100）→ 按下 --xh-bg-subtle-hover（200），
   * 焦点面透明吃库环。这里只把公开槽桥接到矩阵之前（使用者槽 → 形态矩阵 → 家族缺省）与摆放，
   * 聚焦档的 -bg-focus / -fg-focus 两槽同样桥到配方的 focus-visible 面，缺省仍是透明底与悬停字色；
   * 静息前景取 muted 字色，悬停 / 按下回到 fg-default。
   */
  [data-scope='dialog'][data-part='close-trigger'] {
    --xh-action-visual-size: var(--xh-dialog-close-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-dialog-close-radius, var(--xh-shape-control));
    --xh-action-bg-hover: var(--xh-dialog-close-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-dialog-close-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-bg-focus-visible: var(--xh-dialog-close-bg-focus, var(--xh-_action-variant-bg-focus-visible));
    --xh-action-fg-rest: var(--xh-dialog-close-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-dialog-close-fg-hover, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-dialog-close-fg-hover, var(--xh-_action-variant-fg-pressed));
    --xh-action-fg-focus-visible: var(--xh-dialog-close-fg-focus, var(--xh-dialog-close-fg-hover, var(--xh-_action-variant-fg-focus-visible)));
    /* 作者塞进按钮的图标随档取字形尺（sm = 16px），与皮肤画的兜底字形同一把尺 */
    --xh-icon-size: var(--xh-dialog-icon-size, var(--xh-_action-profile-glyph-size));

    position: absolute;
    inset-block-start: var(--xh-surface-action-inset);
    inset-inline-end: var(--xh-surface-action-inset);
  }

  [data-scope='dialog'][data-part='close-trigger'][hidden] {
    display: none;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中 */
  [data-scope='dialog'][data-part='close-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='dialog'][data-part='positioner'][hidden],
  [data-scope='dialog'][data-part='indicator'][hidden] {
    display: none;
  }

  /* 光学效果只在常规档存在：高对比、显式/系统减少透明度与强制色均把 blur 的遮罩原位实体化。 */
  :where([data-contrast='more']) [data-scope='dialog'][data-part='backdrop'][data-variant='blur'],
  :where([data-transparency='reduce']) [data-scope='dialog'][data-part='backdrop'][data-variant='blur'] {
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  @media (prefers-contrast: more), (prefers-reduced-transparency: reduce), (forced-colors: active) {
    [data-scope='dialog'][data-part='backdrop'][data-variant='blur'] {
      -webkit-backdrop-filter: none;
      backdrop-filter: none;
    }
  }

  @media (forced-colors: active) {
    /* 强制色会接管渐变；改回同名实体 M4 底，保留 Canvas / CanvasText 的轮廓与正文。 */
    [data-scope='dialog'][data-part='content'] {
      background: var(--xh-dialog-bg, var(--xh-material-elevated-bg));
    }
  }

  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。 */
    [data-scope='dialog'][data-part='backdrop'],
    [data-scope='dialog'][data-part='positioner'] {
      display: none;
    }
  }
}

/* styles/drawer.css */
/* 定义 drawer 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='drawer'] {
    --xh-drawer-skin: 1;
  }

  /* root 留在页面原地，只是 data-side / data-state 的落点，不该凭空多出一层盒子把
     trigger 从作者的 flex / grid 行里挤出去，故 display: contents。 */
  [data-scope='drawer'][data-part='root'] {
    /* 作者塞进面板里的图标按控件档取；触发器与关闭钮另由家族配方按各自的档下发字形尺 */
    --xh-icon-size: var(--xh-drawer-icon-size, var(--xh-glyph-size-md));

    display: contents;
  }

  /* 浮层被搬到 portal 落点，继承不到 root 上的槽：这把尺在被搬走的那一侧再声明一次，
     作者塞进面板里的图标才和皮肤画的兜底字形一样大 */
  [data-scope='drawer'][data-part='content'] {
    --xh-icon-size: var(--xh-drawer-icon-size, var(--xh-glyph-size-md));
  }

  /* 声明了 display 就盖掉了 UA 的 [hidden]{display:none}，作者手写 hidden 时得还回去 */
  [data-scope='drawer'][data-part='root'][hidden] {
    display: none;
  }

  /*
   * 触发器是页面上的独立文字按钮：盒型、md 档几何、outline 四态面、0.97 按压并换底与粗指针命中区
   * 由家族配方按连接层投影的 data-xh-action-variant / -size 给出（此前自写描边盒型，hover 落 200 / active 落 300）。
   * 这里只把公开槽桥接到矩阵之前（使用者槽 → 形态矩阵 → 家族缺省）与几何槽映射。
   */
  [data-scope='drawer'][data-part='trigger'] {
    --xh-action-gap: var(--xh-drawer-trigger-gap, var(--xh-_action-profile-gap));
    --xh-action-visual-size: var(--xh-drawer-trigger-h, var(--xh-_action-profile-visual-size));
    --xh-action-padding-inline: var(--xh-drawer-trigger-px, var(--xh-_action-profile-padding-inline));
    --xh-action-radius: var(--xh-drawer-trigger-radius, var(--xh-shape-control));
    --xh-action-font-size: var(--xh-drawer-trigger-font-size, var(--xh-_action-profile-font-size));
    --xh-action-bg-rest: var(--xh-drawer-trigger-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-drawer-trigger-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-drawer-trigger-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-bg-focus-visible: var(--xh-drawer-trigger-bg, var(--xh-_action-variant-bg-focus-visible));
    --xh-action-fg-rest: var(--xh-drawer-trigger-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-drawer-trigger-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-drawer-trigger-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-fg-focus-visible: var(--xh-drawer-trigger-fg, var(--xh-_action-variant-fg-focus-visible));
    --xh-action-border-rest: var(--xh-drawer-trigger-border, var(--xh-_action-variant-border-rest));
    --xh-action-border-hover: var(--xh-drawer-trigger-border-hover, var(--xh-_action-variant-border-hover));
    --xh-action-border-pressed: var(--xh-drawer-trigger-border-hover, var(--xh-_action-variant-border-pressed));
    --xh-action-border-focus-visible: var(--xh-drawer-trigger-border, var(--xh-_action-variant-border-focus-visible));
    /* 作者塞进按钮的图标随档取字形尺（md = 20px） */
    --xh-icon-size: var(--xh-drawer-icon-size, var(--xh-_action-profile-glyph-size));

    /* 触发器的文字与 Button 同一字重（家族配方不管字重） */
    font-weight: var(--xh-drawer-trigger-font-weight, var(--xh-text-label-weight));
  }

  [data-scope='drawer'][data-part='trigger'][hidden] {
    display: none;
  }

  /* 抽屉展开期间触发按钮压住不弹起：面板贴在视口边上，它和按钮往往离得很远，
     按钮自己得说明"这一扇是我开的"。open 与家族 hover 同档中性：
     白底承载的 --xh-bg-subtle（100）+ 悬停描边，聚焦时这块面留着 */
  [data-scope='drawer'][data-part='trigger'][data-state='open'] {
    --xh-action-bg-rest: var(--xh-drawer-trigger-bg-open, var(--xh-bg-subtle));
    --xh-action-bg-focus-visible: var(--xh-drawer-trigger-bg-open, var(--xh-bg-subtle));
    --xh-action-border-rest: var(--xh-drawer-trigger-border-open, var(--xh-border-control-hover));
    --xh-action-border-focus-visible: var(--xh-drawer-trigger-border-open, var(--xh-border-control-hover));
  }

  /* 面是实心的，环色与面同族，画在面里就看不出来；环改取面自己的前景色 */
  [data-scope='drawer'][data-part='trigger'][data-xh-action-variant='solid']:focus-visible {
    --xh-action-ring-color-focus-visible: currentColor;
  }

  [data-scope='drawer'][data-part='backdrop'] {
    position: fixed;
    inset: 0;
    z-index: var(--xh-drawer-backdrop-layer, var(--xh-_layer, var(--xh-layer-drawer)));
    background: var(--xh-drawer-backdrop-bg, var(--xh-bg-overlay));
  }

  /* 挂在局部容器里：遮罩、定位层与面板一起从视口坐标换成容器坐标，只罩住那个容器。
     作者要给那个容器加 position（relative 之类），否则 absolute 会往上找到别的定位祖先——
     这一条写进了示例与 props 说明。
     content 必须一起换：它的贴边是 inset-block/inline 参照包含块算的，留在 fixed 上就会
     照旧贴视口边，遮罩缩进容器、面板却跑到屏幕边上——与 contained 的承诺正好相反 */
  [data-scope='drawer'][data-part='backdrop'][data-contained],
  [data-scope='drawer'][data-part='positioner'][data-contained],
  [data-scope='drawer'][data-part='content'][data-contained] {
    position: absolute;
  }

  /* 挂在局部容器里的面板碰不到屏幕边，安全区那一段让位收回去：留着会在容器内白让出一条。 */
  [data-scope='drawer'][data-part='content'][data-contained] {
    padding-block-start: var(--xh-drawer-py, var(--xh-surface-py-md));
    padding-block-end: var(--xh-drawer-py, var(--xh-surface-py-md));
    padding-inline: var(--xh-drawer-px, var(--xh-surface-px-md));
  }

  /* 同一层底色之上再糊背后的页面；与 dialog 同写法，两个前缀都写 */
  [data-scope='drawer'][data-part='backdrop'][data-variant='blur'] {
    -webkit-backdrop-filter: blur(var(--xh-drawer-backdrop-blur, var(--xh-overlay-backdrop-blur)));
    backdrop-filter: blur(var(--xh-drawer-backdrop-blur, var(--xh-overlay-backdrop-blur)));
  }

  /* 去掉底色，只留下这一层吃指针：交互外关闭与滚动锁定照旧 */
  [data-scope='drawer'][data-part='backdrop'][data-variant='transparent'] {
    background: transparent;
  }

  [data-scope='drawer'][data-part='backdrop'][data-state='open'] {
    animation: xh-fade-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter);
  }

  /* 退场补 forwards：动画播完到宿主真正卸载之间还有一帧，不定住终态遮罩会闪回全黑 */
  [data-scope='drawer'][data-part='backdrop'][data-state='closed'] {
    animation: xh-fade-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* positioner 只负责把浮层抬到抽屉层，贴边一概不管（原因见 content）。
     铺满视口是为了在自己这层里罩住 content，但不吃指针：非模态抽屉展开时
     页面其余部分还要能点，模态的拦截由 backdrop 负责。 */
  [data-scope='drawer'][data-part='positioner'] {
    position: fixed;
    inset: 0;
    z-index: var(--xh-drawer-layer, var(--xh-_layer, var(--xh-layer-drawer)));
    pointer-events: none;
  }

  /* 贴边写在 content 自己身上，而不是交给 positioner：
     positioner 在抽屉里不是必需部件，最小合规结构只有 root + content，
     贴边若挂在 positioner 上，那种结构下面板会直接塌回文档流。
     非 contained 时 content 是 fixed，包住它的 positioner 没有 transform / filter，
     不构成固定定位的包含块，两种结构下参照的都是视口，位置一致；
     contained 时上面那条把它一并换成 absolute，参照的就是作者那个容器。 */
  [data-scope='drawer'][data-part='content'] {
    /* 位移方向的私有槽位：默认按 LTR，RTL 在下面整体翻符号。幅度取整幅位移令牌，减弱动效下归零 */
    --xh-_drawer-shift-inline: var(--xh-motion-travel);
    --xh-_drawer-shift-block: var(--xh-motion-travel);
    /* 尺寸档只换这一个私有槽：左右放置时它是面板宽度、上下放置时是面板高度，
       两种取法都在下面「四条边」那两条规则里。声明在 content 而不是 root：
       content 会被 portal 到 body，root 上的槽位继承不过来（data-side 也是同一个道理） */
    --xh-_drawer-size: var(--xh-overlay-drawer-w-md);

    position: fixed;
    z-index: var(--xh-drawer-layer, var(--xh-_layer, var(--xh-layer-drawer)));
    display: flex;
    flex-direction: column;
    gap: var(--xh-drawer-gap, var(--xh-stack-gap-md));
    /* 面板贴死视口的某一条边、另一向满铺，内衬与安全区取大的一头：
       刘海、圆角与底部横条压住的那一段由系统给出，内衬比它窄时首尾两行会被切掉。
       桌面上 env() 恒为 0，取值与内衬槽完全一致。安全区只有物理方向的四个名字，
       行内轴上两侧同取较宽的那一段，RTL 下不会翻错边。 */
    padding-block-start: max(var(--xh-drawer-py, var(--xh-surface-py-md)), env(safe-area-inset-top));
    padding-block-end: max(var(--xh-drawer-py, var(--xh-surface-py-md)), env(safe-area-inset-bottom));
    padding-inline: max(
      var(--xh-drawer-px, var(--xh-surface-px-md)),
      env(safe-area-inset-left),
      env(safe-area-inset-right)
    );
    /* M4 sheet 三件套：任何浮层不得只靠 box-shadow 分层，亮色下面板与页面同色，
       1px 描边才是它的边界；影只是加成 */
    border: var(--xh-stroke-thin) solid var(--xh-drawer-border, var(--xh-material-elevated-border));
    background: var(--xh-drawer-bg, var(--xh-material-elevated-bg));
    color: var(--xh-drawer-fg, var(--xh-material-elevated-fg));
    box-shadow: var(--xh-drawer-shadow, var(--xh-material-elevated-shadow));
    /* 作者不用 header / body / footer 三段时它是唯一的滚动层：模态面滚到头不把页面一起带走 */
    overflow: auto;
    overscroll-behavior: contain;
    /* 尺寸是照视口那条边算出来的，padding 再往外顶就会把面板挤出屏幕、
       逼出一条横向滚动条。reset 层已有同款兜底，这里显式写一遍表明尺寸算法依赖它 */
    box-sizing: border-box;
    /* positioner 整层不吃指针，面板得自己收回来 */
    pointer-events: auto;
  }

  [data-scope='drawer'][data-part='content']:dir(rtl) {
    --xh-_drawer-shift-inline: calc(-1 * var(--xh-motion-travel));
  }

  /* 这里刻意没有 [data-part='content'][hidden] { display: none }，与 dialog 一致。
     收起态连接层会给 content 打 hidden，而上面这条 display: flex 正是要盖掉
     UA 的 [hidden]{display:none}——退场动画得先能播：
     presence 读的是 content 的 animationName，读到就申领租约、等 animationend 才卸载；
     一旦 display: none，元素不生成盒子、动画根本不启动，退场探测器会直接放弃申领
     （否则就要等一个永不到来的 animationend），面板不播动画就地卸载。
     真正的收起两个适配器各自兜住了：Vue 卸载整棵，WC 写内联 style.display。
     其余声明了 display 的角色节点仍补了 [hidden]，那几处没有退场动画，作者手写 hidden 要生效。 */

  /* 面板是焦点陷阱的兜底落点（tabindex="-1"），落焦不画环：环长在里面的可聚焦控件上 */
  [data-scope='drawer'][data-part='content']:focus-visible {
    outline: none;
  }

  /* —— 尺寸 —— */
  /* 只有面板厚度分档；中间档不写规则，缺省即中档。
     data-size 与 data-side 一样同时打在 root 与 content 上，这里只认 content 自己那一份。 */
  [data-scope='drawer'][data-part='content'][data-size='sm'] {
    --xh-_drawer-size: var(--xh-overlay-drawer-w-sm);
  }

  [data-scope='drawer'][data-part='content'][data-size='lg'] {
    --xh-_drawer-size: var(--xh-overlay-drawer-w-lg);
  }

  /* —— 四条边 ——
     data-side 同时打在 root 与 content 上；content 会被 portal 到 body，
     选择器只认得 content 自己身上这一份。 */

  /* 左右：满高、定宽 */
  [data-scope='drawer'][data-part='content'][data-side='left'],
  [data-scope='drawer'][data-part='content'][data-side='right'] {
    inset-block: 0;
    inline-size: var(--xh-drawer-size, var(--xh-_drawer-size));
    /* 视口比抽屉还窄时让位，否则面板会顶出一条横向滚动条 */
    max-inline-size: 100%;
  }

  /* 只圆朝向页面那两个角：贴住视口的那条边圆角是看不见的，圆了反而露出底下的页面 */
  [data-scope='drawer'][data-part='content'][data-side='left'] {
    inset-inline-start: 0;
    border-start-end-radius: var(--xh-drawer-radius, var(--xh-shape-overlay));
    border-end-end-radius: var(--xh-drawer-radius, var(--xh-shape-overlay));
  }

  [data-scope='drawer'][data-part='content'][data-side='right'] {
    inset-inline-end: 0;
    border-start-start-radius: var(--xh-drawer-radius, var(--xh-shape-overlay));
    border-end-start-radius: var(--xh-drawer-radius, var(--xh-shape-overlay));
  }

  /* 上下：满宽、定高 */
  [data-scope='drawer'][data-part='content'][data-side='top'],
  [data-scope='drawer'][data-part='content'][data-side='bottom'] {
    inset-inline: 0;
    block-size: var(--xh-drawer-size, var(--xh-_drawer-size));
    max-block-size: 100%;
  }

  [data-scope='drawer'][data-part='content'][data-side='top'] {
    inset-block-start: 0;
    border-end-start-radius: var(--xh-drawer-radius, var(--xh-shape-overlay));
    border-end-end-radius: var(--xh-drawer-radius, var(--xh-shape-overlay));
  }

  [data-scope='drawer'][data-part='content'][data-side='bottom'] {
    inset-block-end: 0;
    border-start-start-radius: var(--xh-drawer-radius, var(--xh-shape-overlay));
    border-start-end-radius: var(--xh-drawer-radius, var(--xh-shape-overlay));
  }

  /* 滑入/滑出共用整幅滑入关键帧，四条边只在两个方向槽里写起点。位移取整幅位移令牌，
     translate 的百分比参照面板自己的边框盒，所以不管 --xh-drawer-size 被改成多少，
     "正好推到视口外"这件事都成立。

     方向槽由上面的 --xh-_drawer-shift-* 换算而不是写死物理方向：贴边用的是逻辑 inset
     （inset-inline-start 等），RTL 下 inline-end 落在物理左边；translate 没有逻辑等价物，
     若这里写死物理方向，就会出现"面板贴在左边、却从右边滑进来"。shift 槽在 RTL 下翻符号，
     两者才始终同向。竖排书写模式下 block 轴不再是 Y 轴，位移会退化为纵向，但贴边本身仍由逻辑 inset 保证。 */
  [data-scope='drawer'][data-part='content'][data-side='right'] {
    --xh-_slide-from-x: var(--xh-_drawer-shift-inline);
  }

  [data-scope='drawer'][data-part='content'][data-side='left'] {
    --xh-_slide-from-x: calc(-1 * var(--xh-_drawer-shift-inline));
  }

  [data-scope='drawer'][data-part='content'][data-side='top'] {
    --xh-_slide-from-y: calc(-1 * var(--xh-_drawer-shift-block));
  }

  [data-scope='drawer'][data-part='content'][data-side='bottom'] {
    --xh-_slide-from-y: var(--xh-_drawer-shift-block);
  }

  /* 入场是整面板从画外推入的大尺度位移：走 --xh-motion-duration-slide 与 --xh-motion-ease-slide；
     退场仍走 exit 档。退场一律 forwards：presence 要等 animationend 才卸载，
     不定住终态，面板会在最后一帧弹回原位再消失。 */
  [data-scope='drawer'][data-part='content'][data-state='open'] {
    animation: xh-slide-in var(--xh-motion-duration-slide) var(--xh-motion-ease-slide);
  }

  [data-scope='drawer'][data-part='content'][data-state='closed'] {
    animation: xh-slide-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* —— 面板三段 —— */
  /* header / body / footer 把面板切成「头尾定在原处、正文自己滚」三段，
     与弹窗、浮动面板同一套角色划分：头尾不参与压缩，正文吃掉剩下的高度并自己滚。
     面板的内衬与安全区让位仍由 content 一层给出，三段只接手段与段之间那道缝；
     整块的滚动交还给正文段——两层都能滚时滚轮落在哪一层要看指针停在哪，
     贴边的头尾会跟着一起走。 */
  [data-scope='drawer'][data-part='content']:has([data-scope='drawer'][data-part='body']) {
    gap: 0;
    overflow: hidden;
  }

  /* 头段：标题与说明纵向堆叠；不参与压缩，正文再长也压不扁它 */
  [data-scope='drawer'][data-part='header'] {
    flex: none;
    display: flex;
    flex-direction: column;
    gap: var(--xh-drawer-header-gap, var(--xh-stack-gap-sm));
    padding-block-end: var(--xh-drawer-header-pb, var(--xh-space-2));
  }

  /* 正文段：面板里唯一会滚的一段。最小高度归零，
     否则弹性项按内容撑高，容器再矮也不产生溢出，滚动条永远出不来。
     模态 body 是原生细条滚动面：细条由 reset 层统一给，滚到头不把页面一起带走 */
  [data-scope='drawer'][data-part='body'] {
    flex: 1 1 auto;
    min-block-size: 0;
    overflow: auto;
    overscroll-behavior: contain;
  }

  /* 正文高度随交互变化（表单校验、展开段落）：还在用原生滚动条的正文留一条稳定空道，
     滚动条出现与消失时不推动文字。带 data-xh-scrollbar 的容器已经把原生条藏成零宽，排除掉 */
  [data-scope='drawer'][data-part='body']:not([data-xh-scrollbar]) {
    scrollbar-gutter: stable;
  }

  /* 尾段：动作按钮排一行靠尾；同样不参与压缩 */
  [data-scope='drawer'][data-part='footer'] {
    flex: none;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: var(--xh-drawer-footer-gap, var(--xh-control-gap-md));
    padding-block-start: var(--xh-drawer-footer-pt, var(--xh-space-2));
  }

  /* 声明过 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='drawer'][data-part='header'][hidden],
  [data-scope='drawer'][data-part='body'][hidden],
  [data-scope='drawer'][data-part='footer'][hidden] {
    display: none;
  }

  [data-scope='drawer'][data-part='title'] {
    margin: 0;
    font-size: var(--xh-drawer-title-font-size, var(--xh-text-heading-3-size));
    font-weight: var(--xh-drawer-title-font-weight, var(--xh-text-heading-3-weight));
    color: var(--xh-drawer-title-fg, var(--xh-fg-default));
  }

  /* 说明文字走说明档：13px + fg-muted */
  [data-scope='drawer'][data-part='description'] {
    margin: 0;
    font-size: var(--xh-drawer-description-font-size, var(--xh-text-secondary-size));
    color: var(--xh-drawer-description-fg, var(--xh-fg-muted));
  }

  /* 关闭按钮是绝对定位的，不占流内宽度：标题得自己让出那块角，
     否则长标题会直接钻到按钮底下。只在真有关闭按钮时让位。 */
  [data-scope='drawer'][data-part='content']:has([data-scope='drawer'][data-part='close-trigger'])
    [data-scope='drawer'][data-part='title'] {
    padding-inline-end: calc(var(--xh-drawer-close-size, var(--xh-control-h-sm)) + var(--xh-surface-action-inset));
  }

  /*
   * 关闭钮是面板角落的单图标钮：正方盒、sm 档几何、ghost 四态面、0.97 按压并换底与粗指针命中区
   * 由家族配方给出——白面上走画布承载阶梯悬停 --xh-bg-subtle（100）→ 按下 --xh-bg-subtle-hover（200），
   * 焦点面透明吃库环。这里只把公开槽桥接到矩阵之前（使用者槽 → 形态矩阵 → 家族缺省）与摆放，
   * 聚焦档的 -bg-focus / -fg-focus 两槽同样桥到配方的 focus-visible 面（与 dialog 一致），缺省仍是透明底与悬停字色；
   * 静息前景取 muted 字色，悬停 / 按下回到 fg-default。
   */
  [data-scope='drawer'][data-part='close-trigger'] {
    --xh-action-visual-size: var(--xh-drawer-close-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-drawer-close-radius, var(--xh-shape-control));
    --xh-action-bg-hover: var(--xh-drawer-close-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-drawer-close-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-bg-focus-visible: var(--xh-drawer-close-bg-focus, var(--xh-_action-variant-bg-focus-visible));
    --xh-action-fg-rest: var(--xh-drawer-close-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-drawer-close-fg-hover, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-drawer-close-fg-hover, var(--xh-_action-variant-fg-pressed));
    --xh-action-fg-focus-visible: var(--xh-drawer-close-fg-focus, var(--xh-drawer-close-fg-hover, var(--xh-_action-variant-fg-focus-visible)));
    /* 作者塞进按钮的图标随档取字形尺（sm = 16px），与皮肤画的兜底字形同一把尺 */
    --xh-icon-size: var(--xh-drawer-icon-size, var(--xh-_action-profile-glyph-size));

    position: absolute;
    inset-block-start: var(--xh-surface-action-inset);
    inset-inline-end: var(--xh-surface-action-inset);
  }

  [data-scope='drawer'][data-part='close-trigger'][hidden] {
    display: none;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中 */
  [data-scope='drawer'][data-part='close-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }

  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。 */
    [data-scope='drawer'][data-part='backdrop'],
    [data-scope='drawer'][data-part='positioner'] {
      display: none;
    }
  }
}

/* styles/editable.css */
/* Editable 独立皮肤同时传递引入字段视觉盒与字段内动作；full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='editable'] {
    --xh-editable-skin: 1;
  }

  /* 与 NumberField 同构：标题独占一行，control 是下面唯一的视觉盒；
     预览/输入占据盒内左侧，编辑或确认/取消动作收在同一盒的逻辑末端。
     组件层只把既有公开槽映射到家族合同；形态三档由家族按 control 上的 data-variant 生成，皮肤不再声明。 */
  [data-scope='editable'][data-part='root'] {
    --xh-icon-size: var(--xh-editable-icon-size, var(--xh-glyph-size-md));

    /* 尺寸档只换这三个私有槽，预览区、输入框与动作钮都从 root 继承它们，
       换档不必给每个部件各写一条选择器。 */
    --xh-_editable-h: var(--xh-control-h-md);
    --xh-_editable-px: var(--xh-control-px-md);
    --xh-_editable-font-size: var(--xh-control-font-md);
    --xh-_editable-control-gap: 0;

    /* 盒内那道分隔线的长度：取钮高的一半，线的上下各留一截空白，不与钮等高 */
    --xh-_editable-divider-h: 50%;

    display: inline-flex;
    flex-direction: column;
    gap: var(--xh-editable-gap, var(--xh-space-1));
    /* 不传尺寸时一律这么宽，宽度不随内容走；父容器给不出这么宽时整件跟着收，地板同步让步，不越出父容器。
       地板不高过缺省宽：使用者把缺省宽钉到底线以下时不必再放开底线 */
    inline-size: var(--xh-editable-control-w, var(--xh-control-w));
    min-inline-size: min(var(--xh-editable-control-w, var(--xh-control-w)), var(--xh-editable-control-min-w, var(--xh-control-min-w)), 100%);
    max-inline-size: 100%;
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里 */
  [data-scope='editable'][data-part='root'][data-size='sm'] {
    --xh-icon-size: var(--xh-editable-icon-size, var(--xh-glyph-size-sm));
    --xh-_editable-h: var(--xh-control-h-sm);
    --xh-_editable-px: var(--xh-control-px-sm);
    --xh-_editable-font-size: var(--xh-control-font-sm);
  }

  [data-scope='editable'][data-part='root'][data-size='lg'] {
    --xh-icon-size: var(--xh-editable-icon-size, var(--xh-glyph-size-lg));
    --xh-_editable-h: var(--xh-control-h-lg);
    --xh-_editable-px: var(--xh-control-px-lg);
    --xh-_editable-font-size: var(--xh-control-font-lg);
  }

  /* 只要声明了 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='editable'][data-part='root'][hidden] {
    display: none;
  }

  [data-scope='editable'][data-part='label'] {
    color: var(--xh-editable-label-fg, var(--xh-fg-default));
    font-size: var(--xh-editable-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-editable-label-font-weight, var(--xh-text-label-weight));
    /* 点标题会把人送进编辑态（预览态下 for 指着的输入框是收起的，点了没反应），
       所以光标要说明它可点 */
    cursor: pointer;
  }

  [data-scope='editable'][data-part='label'][data-disabled] {
    color: var(--xh-editable-label-fg-disabled, var(--xh-fg-subtle));
  }

  /* 预览区只是 control 里的内容段，不再自成一只带圆角的盒子。 */
  [data-scope='editable'][data-part='preview'] {
    display: inline-flex;
    flex: 1 1 auto;
    align-items: center;
    inline-size: auto;
    min-inline-size: 0;
    min-block-size: var(--xh-editable-preview-min-h, var(--xh-_editable-h));
    padding-inline: var(--xh-editable-preview-px, var(--xh-_editable-px));
    padding-block: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
    color: var(--xh-editable-preview-fg, var(--xh-fg-default));
    font-size: var(--xh-editable-preview-font-size, var(--xh-_editable-font-size));
    line-height: var(--xh-leading-normal);
    /* 值里的换行与连续空格照原样显示，过长的行断开而不撑破弹性行 */
    white-space: pre-wrap;
    overflow-wrap: anywhere;
  }

  /* 编辑态由连接层给 hidden；上面那条 display 会盖掉 UA 规则，少了这条就收不起来 */
  [data-scope='editable'][data-part='preview'][hidden] {
    display: none;
  }

  /* 认交互的预览区才给文字光标与悬停底色：
     activation-mode=none 或整块不可编辑时，它就只是一段文字，别装成能点 */
  [data-scope='editable'][data-part='preview']:not(
    [data-activation-mode='none'],
    [data-disabled],
    [data-readonly]
  ) {
    cursor: text;
  }

  /* 显示的是占位文字而不是真值，压淡以示区别 */
  [data-scope='editable'][data-part='preview'][data-placeholder] {
    color: var(--xh-editable-placeholder-fg, var(--xh-fg-subtle));
  }

  [data-scope='editable'][data-part='preview'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 盒内 input：无边框无底无圆角无落影由家族重置，hover、focus 与 invalid 全交给 control；
     行内内衬留给它自己（control 不给内衬），占位与自动填充的颜色经桥接槽下发 */
  [data-scope='editable'][data-part='input'] {
    --xh-field-input-fg: var(--xh-editable-input-fg, var(--xh-fg-default));
    --xh-field-input-font-size: var(--xh-editable-input-font-size, var(--xh-_editable-font-size));
    --xh-field-placeholder-fg: var(--xh-editable-placeholder-fg, var(--xh-fg-subtle));
    --xh-field-autofill-bg: var(--xh-editable-input-autofill-bg, var(--xh-bg-canvas));
    --xh-field-autofill-fg: var(--xh-editable-input-autofill-fg, var(--xh-fg-default));

    flex: 1 1 auto;
    inline-size: auto;
    min-inline-size: 0;
    padding-inline: var(--xh-editable-input-px, var(--xh-_editable-px));
  }

  /* 预览态由连接层给 hidden；家族给了 display 以外的盒声明但没给 display，
     UA 的 [hidden]{display:none} 仍然管用——这里补一条是防作者层另给 display */
  [data-scope='editable'][data-part='input'][hidden] {
    display: none;
  }

  /* 宽度跟着内容走时交给原生 size 说了算，别再用 100% 把它撑满 */
  [data-scope='editable'][data-part='input'][data-auto-resize] {
    flex: 0 1 auto;
    inline-size: auto;
  }

  /* 唯一视觉盒：描边、底色、圆角、聚焦环、五态与悬停由 Field Chrome 家族画在 control 上；
     预览/输入和右侧动作只是盒内分段。控件不给内衬：内衬走预览区、input 与钮各自的盒。
     不写 overflow: hidden——家族的粗指针热区伪元素会被它裁掉，且钮已不贴控件边 */
  [data-scope='editable'][data-part='control'] {
    --xh-field-control-height: var(--xh-editable-control-h, var(--xh-_editable-h));
    --xh-field-control-padding-inline: var(--xh-editable-control-px, 0);
    --xh-field-control-gap: var(--xh-editable-control-gap, var(--xh-_editable-control-gap));
    --xh-field-control-min-inline-size: var(--xh-editable-control-min-w, var(--xh-control-min-w));
    --xh-field-control-radius: var(--xh-editable-control-radius, var(--xh-shape-control));
    --xh-field-bg-rest: var(--xh-editable-control-bg, var(--xh-_field-variant-bg-rest));
    --xh-field-bg-hover: var(--xh-editable-control-bg-hover, var(--xh-_field-variant-bg-hover));
    --xh-field-bg-read-only: var(--xh-editable-control-bg-readonly, var(--xh-_field-variant-bg-read-only));
    --xh-field-bg-disabled: var(--xh-editable-control-bg-disabled, var(--xh-_field-variant-bg-disabled));
    --xh-field-fg-rest: var(--xh-editable-control-fg, var(--xh-fg-default));
    --xh-field-border-rest: var(--xh-editable-control-border, var(--xh-_field-variant-border-rest));
    --xh-field-border-hover: var(--xh-editable-control-border-hover, var(--xh-_field-variant-border-hover));
    --xh-field-border-focus: var(--xh-editable-control-border-focus, var(--xh-_field-variant-border-focus));
    --xh-field-border-invalid: var(--xh-editable-control-border-invalid, var(--xh-_field-variant-border-invalid));
    --xh-field-border-disabled: var(--xh-editable-control-border-disabled, var(--xh-_field-variant-border-disabled));
    --xh-field-ring-focus: var(--xh-ring-focus);
    --xh-field-ring-invalid: var(--xh-ring-invalid);
    --xh-field-shadow-rest: var(--xh-editable-control-shadow, none);
    /* 家族 chrome 会重写 --xh-icon-size，使用者图标槽必须经桥接槽下发才能在盒内生效 */
    --xh-field-glyph-size: var(--xh-editable-icon-size, var(--xh-_field-size-glyph-size));

    position: relative;
    inline-size: 100%;
  }

  [data-scope='editable'][data-part='control'][hidden] {
    display: none;
  }

  /* 三颗动作与 NumberField 的加减钮一样是 control 内部的分段：正方视觉盒、inset 圆角、
     悬停 100 / 按下 200 与 0.97 按压、粗指针热区、:focus-visible 关环与禁用面全由 Action Control 的
     field-inset ghost 档给，组件只映射既有覆盖槽。常态只剩符号，悬停与按下才浮出底色 */
  [data-scope='editable'][data-part='edit-trigger'],
  [data-scope='editable'][data-part='submit-trigger'],
  [data-scope='editable'][data-part='cancel-trigger'] {
    --xh-action-visual-size: var(--xh-editable-trigger-size, var(--xh-_action-profile-visual-size));
    --xh-action-min-inline-size: var(--xh-editable-trigger-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-editable-trigger-radius, var(--xh-shape-inset));
    /* 底色阶梯由 ghost 档给（透明 → 100 → 200），使用者槽只作覆盖入口 */
    --xh-action-bg-rest: var(--xh-editable-trigger-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-editable-trigger-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-editable-trigger-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-bg-disabled: var(--xh-editable-trigger-bg-disabled, var(--xh-_action-variant-bg-disabled));
    --xh-action-fg-rest: var(--xh-editable-trigger-fg, var(--xh-fg-default));
    --xh-action-fg-hover: var(--xh-editable-trigger-fg-hover, var(--xh-fg-default));
    --xh-action-border-rest: transparent;
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    --xh-action-font-size: var(--xh-editable-trigger-font-size, var(--xh-text-secondary-size));
    /* 配方尚未把 profile 字形档灌进 --xh-icon-size，钮内字形先按 field-inset 档逐钮取值 */
    --xh-icon-size: var(--xh-_action-profile-glyph-size);

    border-width: 0;
  }

  /* 每个状态的第一颗动作把整组推到逻辑末端；取消钮紧跟确认钮。 */
  [data-scope='editable'][data-part='edit-trigger'],
  [data-scope='editable'][data-part='submit-trigger'] {
    margin-inline-start: auto;
  }

  /* 三颗动作默认是纯图标按钮；作者放了自己的图标后 :empty 不命中，不会叠两层。 */
  [data-scope='editable']:is([data-part='edit-trigger'], [data-part='submit-trigger'], [data-part='cancel-trigger']):empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    background-color: currentColor;
    -webkit-mask: var(--xh-_editable-trigger-glyph) center / contain no-repeat;
    mask: var(--xh-_editable-trigger-glyph) center / contain no-repeat;
  }

  [data-scope='editable'][data-part='edit-trigger'] {
    --xh-_editable-trigger-glyph: var(--xh-glyph-mark-edit);
  }

  [data-scope='editable'][data-part='submit-trigger'] {
    --xh-_editable-trigger-glyph: var(--xh-glyph-mark-check);
  }

  [data-scope='editable'][data-part='cancel-trigger'] {
    --xh-_editable-trigger-glyph: var(--xh-glyph-mark-close);
  }

  /* 动作组第一颗与内容段之间只有一道短分隔线；确认与取消之间不再拼第二个按钮框。
     线不画在钮的边框上：边框会跟着钮的圆角与悬停底走，而这道线要独立于钮的各态，长度也短于钮自己。
     ::before 已被兜底字形占着，::after 在粗指针下是家族给的 44px 热区，几何只能落在
     background-image 上：一条 1px × 半高的渐变贴在逻辑起始侧，底色换态时它仍叠在上层。
     background-position 是物理轴，RTL 另给一条换边 */
  [data-scope='editable'][data-part='edit-trigger'],
  [data-scope='editable'][data-part='submit-trigger'] {
    background-image: linear-gradient(
      var(--xh-editable-trigger-divider, var(--xh-material-soft-separator)),
      var(--xh-editable-trigger-divider, var(--xh-material-soft-separator))
    );
    background-repeat: no-repeat;
    background-position: 0 50%;
    background-size: var(--xh-stroke-thin) var(--xh-editable-trigger-divider-h, var(--xh-_editable-divider-h));
  }

  [dir='rtl'] [data-scope='editable'][data-part='edit-trigger'],
  [dir='rtl'] [data-scope='editable'][data-part='submit-trigger'] {
    background-position: 100% 50%;
  }

  /* 三颗按钮按形态轮流收起，连接层给的是 hidden 属性；
     家族那条 display 已把 UA 规则盖掉，少了这里三条按钮就一直杵着 */
  [data-scope='editable'][data-part='edit-trigger'][hidden],
  [data-scope='editable'][data-part='submit-trigger'][hidden],
  [data-scope='editable'][data-part='cancel-trigger'][hidden] {
    display: none;
  }

  /* 高对比档整层丢弃 background-image，分隔线改用系统色重画，并关掉这两颗钮的强制换色 */
  @media (forced-colors: active) {
    [data-scope='editable'][data-part='edit-trigger'],
    [data-scope='editable'][data-part='submit-trigger'] {
      background-image: linear-gradient(ButtonText, ButtonText);
      forced-color-adjust: none;
    }
  }
}

/* styles/field.css */
/* 定义 field 样式。 */

/* Field 独立皮肤同时传递引入字段视觉盒；full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='field'] {
    --xh-field-skin: 1;
  }

  [data-scope='field'][data-part='root'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-field-gap, var(--xh-space-1));
  }

  /* 表单横排（标签左置）：字段转两列网格，标签列宽由表单的 --xh-form-label-w 统一给，
     整表据此对齐；描述与错误文案跟着控件走第二列 */
  [data-scope='form'][data-part='root'][data-layout='horizontal'] [data-scope='field'][data-part='root'] {
    display: grid;
    grid-template-columns: var(--xh-form-label-w, 30%) minmax(0, 1fr);
    column-gap: var(--xh-field-label-gap, var(--xh-space-3));
    align-items: start;
  }

  [data-scope='form'][data-part='root'][data-layout='horizontal'] [data-scope='field'][data-part='label'] {
    grid-column: 1;
    justify-self: end;
    /* 横排下标签与控件是左右两列，间距归 --xh-field-label-gap 管，竖排那段补白在这儿清零 */
    margin-block-end: 0;
    /* 与控件的首行文字对齐：行高保持正文行距（标签折行时每行不会撑成一个控件高），
       上下留白把单行文本盒撑到控件高度；配的是哪一档控件由 --xh-field-control-h 告诉它 */
    line-height: var(--xh-field-label-leading, var(--xh-leading-normal));
    /* 级联兜底：先写一行的高度算式（标签字号 × 标签行距），再写 1lh。
       1lh 晚于本库声明的浏览器地板，取不到时旧引擎丢掉后一条、留下前一条。
       两条取的是同一组槽——字号来自本文件里标签那条 font-size、行距来自紧邻上一行，
       所以算出来是同一个数，使用者覆盖任一槽两条一起跟着走。 */
    padding-block: calc((var(--xh-field-control-h, var(--xh-control-h-md)) - var(--xh-field-label-font-size, var(--xh-text-label-size)) * var(--xh-field-label-leading, var(--xh-leading-normal))) / 2);
    padding-block: calc((var(--xh-field-control-h, var(--xh-control-h-md)) - 1lh) / 2);
  }

  [data-scope='form'][data-part='root'][data-layout='horizontal'][data-label-align='start'] [data-scope='field'][data-part='label'] {
    justify-self: start;
  }

  [data-scope='form'][data-part='root'][data-layout='horizontal'] [data-scope='field'][data-part='root'] > :not([data-part='label']) {
    grid-column: 2;
  }

  /* 横排下这一列是网格的自动流，占位块跟着控件走第二列（选择器不匹配伪元素，单列一条） */
  [data-scope='form'][data-part='root'][data-layout='horizontal'] [data-scope='field'][data-part='root']::after {
    grid-column: 2;
  }

  [data-scope='field'][data-part='label'] {
    /* 一段不带空格的长标识（字段名、英文标识符）在窄处从词内断开：
       横排表单里标签列是一段比例宽度，这行让标签在那一列里折行，而不是从列的左边顶出去 */
    overflow-wrap: anywhere;
    /* 竖排时标签与控件之间的距离：容器的 gap 之上补一段差值，
       --xh-field-label-gap-block 给多少最终就是多少；不给时差值算成 0，
       这段距离仍由 --xh-field-gap 与描述、错误文案那两段同宽。 */
    margin-block-end: calc(
      var(--xh-field-label-gap-block, var(--xh-field-gap, var(--xh-space-1))) - var(--xh-field-gap, var(--xh-space-1))
    );
    color: var(--xh-field-label-fg, var(--xh-fg-default));
    font-size: var(--xh-field-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-field-label-font-weight, var(--xh-text-label-weight));
  }

  [data-scope='field'][data-part='label'][data-disabled] {
    color: var(--xh-field-label-fg-disabled, var(--xh-fg-subtle));
  }

  /* 必填星号的字形、间距与默认色在 label.css 公共层；这里只把颜色接到本组件的覆盖槽上 */
  [data-scope='field'][data-part='label'][data-required]::after {
    color: var(--xh-field-label-star, var(--xh-fg-danger));
  }

  /* control 是作者自己的输入控件，它自身就是视觉盒：描边、底、影、圆角与悬停 / 聚焦 / 无效 /
     只读 / 禁用各态由 Field Chrome 家族配方按连接层投影的 data-xh-field-chrome 画，
     这里只把既有使用者槽映射到家族桥接槽。Field 没有 size 轴，尺寸私有槽按连接层固定投的 md 档取值。
     使用者槽与桥接槽同在 --xh-field- 前缀下：圆角那一位（--xh-field-control-radius）与家族读的桥接槽同名，
     使用者写它即被家族直接读到，无法再经映射中转，圆角在这里按同一槽同一缺省直接声明（与家族算出的值一致，
     只为把这一位使用者槽留在皮肤的消费位上）；其余各位逐条对齐，不与桥接槽撞名 */
  [data-scope='field'][data-part='control'] {
    --xh-field-control-height: var(--xh-field-control-h, var(--xh-_field-size-control-height));
    --xh-field-control-padding-inline: var(--xh-field-control-px, var(--xh-_field-size-padding-inline));
    --xh-field-bg-rest: var(--xh-field-control-bg, var(--xh-_field-variant-bg-rest));
    --xh-field-bg-hover: var(--xh-field-control-bg-hover, var(--xh-_field-variant-bg-hover));
    --xh-field-bg-read-only: var(--xh-field-control-bg-readonly, var(--xh-_field-variant-bg-read-only));
    --xh-field-bg-disabled: var(--xh-field-control-bg-disabled, var(--xh-_field-variant-bg-disabled));
    --xh-field-fg-rest: var(--xh-field-control-fg, var(--xh-fg-default));
    --xh-field-border-rest: var(--xh-field-control-border, var(--xh-_field-variant-border-rest));
    --xh-field-border-hover: var(--xh-field-control-border-hover, var(--xh-_field-variant-border-hover));
    --xh-field-border-focus: var(--xh-field-control-border-focus, var(--xh-_field-variant-border-focus));
    --xh-field-border-invalid: var(--xh-field-control-border-invalid, var(--xh-_field-variant-border-invalid));
    /* 焦点环与家族同一支公共环，不再留逐组件的环色槽（焦点边与环一律公共） */
    --xh-field-ring-focus: var(--xh-ring-focus);
    --xh-field-ring-invalid: var(--xh-ring-invalid);
    --xh-field-shadow-rest: var(--xh-field-control-shadow, none);

    inline-size: 100%;
    border-radius: var(--xh-field-control-radius, var(--xh-shape-control));
    /* 家族 chrome 不设字号：控件自身就是盒，正文字号由这里给 */
    font-size: var(--xh-field-control-font-size, var(--xh-text-body-size));
  }

  /* 无效标签色的默认在 label.css 公共层；这里只把颜色接到本组件的覆盖槽上 */
  [data-scope='field'][data-part='label'][data-invalid] {
    color: var(--xh-field-label-fg-invalid, var(--xh-fg-danger));
  }

  /* 说明与错误文案的角色（外边距、行距、默认字号与字色）在 description.css 公共层；
     这里只把字色与字号接到本组件的覆盖槽上 */
  [data-scope='field'][data-part='description'] {
    color: var(--xh-field-description-fg, var(--xh-fg-muted));
    font-size: var(--xh-field-description-font-size, var(--xh-text-secondary-size));
  }

  [data-scope='field'][data-part='description'][data-disabled] {
    color: var(--xh-field-description-fg-disabled, var(--xh-fg-subtle));
  }

  [data-scope='field'][data-part='error-text'] {
    color: var(--xh-field-error-fg, var(--xh-fg-danger));
    font-size: var(--xh-field-error-font-size, var(--xh-text-secondary-size));
  }

  /* 辅助文字那一行的占位：字段渲染了错误文案、当前又没在报错时，补一个与错误文案等高的空块。
     报错时这个空块让位给错误文案，字段的外框高度前后一样，表单不会因为一段错误文字重新排版，
     定高或限高的父级里也不会把控件挤出去。

     两个条件缺一不可：
     渲染了 error-text 且它带 hidden——没有错误文案可显示的字段不占这一行；
     没有在场的 description——描述已经占着这一行了，报错时由描述让位给错误文案（见 description.css）。

     高度按错误文案那一档的字号乘行距算，得到的正是它一行的高度。
     不写 1lh：那个单位晚于本库声明的浏览器地板，取不到时整条声明被丢弃、占位高退回 0，
     字段又会随报错撑高一次，而这种失效不报错。
     与前一块的距离由根的 gap 给，和错误文案顶上来时是同一段。 */
  [data-scope='field'][data-part='root']:has(> [data-scope='field'][data-part='error-text'][hidden]):not(
      :has(> [data-scope='field'][data-part='description']:not([hidden]))
    )::after {
    content: '';
    block-size: calc(
      var(--xh-field-error-font-size, var(--xh-text-secondary-size)) * var(--xh-leading-normal)
    );
    font-size: var(--xh-field-error-font-size, var(--xh-text-secondary-size));
    line-height: var(--xh-leading-normal);
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='field'][data-part='root'][hidden],
  [data-scope='form'][data-part='root'][hidden] {
    display: none;
  }
}

/* styles/file-upload.css */
/* 定义 file upload 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='file-upload'] {
    --xh-file-upload-skin: 1;
  }

  [data-scope='file-upload'][data-part='root'] {
    /* 作者放进缩略图槽、删除钮与清空钮里的图标跟着字号走，与皮肤画的兜底叉同一把尺。
       条目行首自绘的状态标记（传完的勾、失败的警示）不读这支：它们是指示符，与同一行里 icon 档的
       删除钮并排、走 --xh-control-indicator-* 一族，尺寸由 --xh-file-upload-item-mark-size 单独控 */
    --xh-icon-size: var(--xh-file-upload-icon-size, var(--xh-glyph-size-text));

    display: flex;
    flex-direction: column;
    gap: var(--xh-file-upload-gap, var(--xh-space-3));
  }

  /* 声明了 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='file-upload'][data-part='root'][hidden] {
    display: none;
  }

  [data-scope='file-upload'][data-part='label'] {
    color: var(--xh-file-upload-label-fg, var(--xh-fg-default));
    font-size: var(--xh-file-upload-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-file-upload-label-font-weight, var(--xh-text-label-weight));
  }

  [data-scope='file-upload'][data-part='label'][data-disabled] {
    color: var(--xh-file-upload-label-fg-disabled, var(--xh-fg-subtle));
  }

  /* 虚线框是"这里能放东西"的通用说法，实线框看起来只是一个普通面板。
     整块可点、可聚焦（连接层给了 role=button 与 tabindex），所以指针形状用 pointer */
  [data-scope='file-upload'][data-part='dropzone'] {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--xh-file-upload-dropzone-gap, var(--xh-space-2));
    min-block-size: var(--xh-file-upload-dropzone-min-h, 8rem);
    padding-block: var(--xh-file-upload-dropzone-py, var(--xh-space-5));
    padding-inline: var(--xh-file-upload-dropzone-px, var(--xh-space-4));
    border: var(--xh-stroke-thick) dashed var(--xh-file-upload-dropzone-border, var(--xh-border-control));
    border-radius: var(--xh-file-upload-dropzone-radius, var(--xh-shape-surface));
    background: var(--xh-file-upload-dropzone-bg, transparent);
    color: var(--xh-file-upload-dropzone-fg, var(--xh-fg-muted));
    font-size: var(--xh-file-upload-dropzone-font-size, var(--xh-text-body-size));
    text-align: center;
    cursor: pointer;
    /* 拖着文件经过时颜色要立刻跟上：这是"松手就能放下"的唯一提示 */
    transition:
      border-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      background-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='file-upload'][data-part='dropzone'][hidden] {
    display: none;
  }

  /* hover 只在中性态命中：invalid 与 dragging 正拿边框颜色说事，被 hover 盖掉那条信息就没了。
     描边与底一起换：这块面有整整八行高，只挪一圈 1px 的描边在这个面积上几乎读不出来 */
  [data-scope='file-upload'][data-part='dropzone']:hover:not([data-disabled], [data-invalid], [data-dragging]) {
    border-color: var(--xh-file-upload-dropzone-border-hover, var(--xh-border-control-hover));
    background: var(--xh-file-upload-dropzone-bg-hover, var(--xh-bg-subtle));
  }

  /* 键盘落焦时描边跟着语气走，与聚焦环同族；环由 focus.css 统一画。
     摘掉的三档与 hover 那条一致：它们各自正拿边框颜色说事 */
  [data-scope='file-upload'][data-part='dropzone']:focus-visible:not([data-disabled], [data-invalid], [data-dragging]) {
    border-color: var(--xh-file-upload-dropzone-border-focus, var(--xh-_tone, var(--xh-border-control-focus)));
  }

  /* 悬停在上方：整块换成品牌色描边加浅底，比只换边框显眼得多 */
  [data-scope='file-upload'][data-part='dropzone'][data-dragging] {
    border-color: var(--xh-file-upload-dropzone-border-dragging, var(--xh-bg-brand));
    background: var(--xh-file-upload-dropzone-bg-dragging, var(--xh-bg-subtle));
  }

  [data-scope='file-upload'][data-part='dropzone'][data-invalid] {
    border-color: var(--xh-file-upload-dropzone-border-invalid, var(--xh-border-invalid));
  }

  /* 投放区是 div，没有原生 disabled 可用，禁用态只能靠 data-disabled 表达，写 :disabled 永远不命中 */
  [data-scope='file-upload'][data-part='dropzone'][data-disabled] {
    border-color: var(--xh-border-default);
    background: var(--xh-file-upload-dropzone-bg-disabled, var(--xh-bg-subtle));
    color: var(--xh-fg-disabled);
  }

  [data-scope='file-upload'][data-part='trigger'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    gap: var(--xh-file-upload-trigger-gap, var(--xh-control-gap-md));
    block-size: var(--xh-file-upload-trigger-h, var(--xh-control-h-md));
    padding-inline: var(--xh-file-upload-trigger-px, var(--xh-control-px-md));
    border: var(--xh-stroke-thin) solid var(--xh-file-upload-trigger-border, var(--xh-border-control));
    border-radius: var(--xh-file-upload-trigger-radius, var(--xh-shape-control));
    background: var(--xh-file-upload-trigger-bg, var(--xh-bg-surface));
    color: var(--xh-file-upload-trigger-fg, var(--xh-fg-default));
    /* 表单控件不继承页面字体，只给字号会让按钮用 UA 默认字族 */
    font-family: inherit;
    font-size: var(--xh-file-upload-trigger-font-size, var(--xh-text-body-size));
    line-height: var(--xh-leading-none);
    cursor: pointer;
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      box-shadow var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      scale var(--xh-motion-duration-release) var(--xh-motion-ease-release);
  }

  [data-scope='file-upload'][data-part='trigger'][hidden] {
    display: none;
  }

  /* 悬停换底色的同时把这块面抬起一档：只换底色的回执在一颗按钮上太轻 */
  [data-scope='file-upload'][data-part='trigger']:hover:not(:disabled) {
    background: var(--xh-file-upload-trigger-bg-hover, var(--xh-bg-subtle-hover));
    box-shadow: var(--xh-file-upload-trigger-shadow-hover, var(--xh-elevation-raised));
  }

  /* 按下：换到按压档底色并轻微下压，抬起的那一档同时落回，松手弹回；禁用钮不压 */
  [data-scope='file-upload'][data-part='trigger']:not(:disabled):is(:active, [data-pressed]) {
    background: var(--xh-file-upload-trigger-bg-active, var(--xh-bg-subtle-active));
    box-shadow: none;
    scale: var(--xh-motion-scale-press);
    transition-duration: var(--xh-motion-duration-press);
    transition-timing-function: var(--xh-motion-ease-press);
  }

  /* 单体控件走原生 disabled（与集合条目的 aria-disabled 相反），因此用 :disabled */
  [data-scope='file-upload'][data-part='trigger']:disabled {
    background: var(--xh-bg-subtle);
    color: var(--xh-fg-disabled);
  }

  /* 连接层已经把这一套视觉隐藏写进了内联 style，这里是给元素升级前那一瞬兜底
     （作者手写的是一个普通 file input，接线完成前它是可见的）。
     刻意不写 display：藏起来的输入仍要留在布局里，原生表单校验的气泡才有可指的锚点 */
  [data-scope='file-upload'][data-part='hidden-input'] {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    border: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* 文件条数由用户一次选进来多少给，行数没有尽头：
     列表到这个高度就不再长，剩下的行在列表内滚出来，投放区与触发钮不会被推出视野 */
  [data-scope='file-upload'][data-part='list'] {
    display: flex;
    max-block-size: var(--xh-file-upload-list-max-h, var(--xh-viewport-h-md));
    overflow-y: auto;
    flex-direction: column;
    gap: var(--xh-file-upload-item-gap, var(--xh-space-2));
  }

  [data-scope='file-upload'][data-part='list'][hidden] {
    display: none;
  }

  /* 私有槽一个：传输进度的 0..1 比例，由连接层写进进度条的内联样式，
     这里给个 0 的缺省——没接上传器时进度条根本不露面，也就没有宽度可算。 */
  [data-scope='file-upload'][data-part='item'] {
    --xh-_file-upload-progress: 0;

    display: flex;
    /* 一行排不下就换行：文件名有自己的下限，挤到那个下限之后由后面的部件另起一行，
       而不是把文件名继续压到零宽 */
    flex-wrap: wrap;
    align-items: center;
    gap: var(--xh-file-upload-item-inner-gap, var(--xh-control-gap-md));
    padding-block: var(--xh-file-upload-item-py, var(--xh-space-2));
    padding-inline: var(--xh-file-upload-item-px, var(--xh-space-3));
    border: var(--xh-stroke-thin) solid var(--xh-file-upload-item-border, var(--xh-border-default));
    border-radius: var(--xh-file-upload-item-radius, var(--xh-shape-control));
    background: var(--xh-file-upload-item-bg, var(--xh-bg-surface));
    color: var(--xh-file-upload-item-fg, var(--xh-fg-default));
    font-size: var(--xh-file-upload-item-font-size, var(--xh-text-body-size));
  }

  [data-scope='file-upload'][data-part='item'][hidden] {
    display: none;
  }

  [data-scope='file-upload'][data-part='item'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 上传失败的那一行必须一眼认出来：不标出来的话它跟传完的行渲染完全一致，
     用户不知道该按哪一条的重试。红边之外再补一枚警示字形——只靠颜色的话，
     色觉障碍用户与灰度打印下这一档等于没有。
     警示与下面的勾都是固定状态标记（不是 :empty 兜底，作者塞进条目的部件顶不掉）：按指示符档取尺
     （comfortable 16 / compact 14，随密度换档），不读只管作者图标的 --xh-icon-size——随文 1em 落在
     14 上下，comfortable 下比同一行里的指示符档小一圈、compact 下又不换档 */
  [data-scope='file-upload'][data-part='item'][data-state='error'] {
    border-color: var(--xh-file-upload-item-border-error, var(--xh-border-invalid));
    color: var(--xh-file-upload-item-fg-error, var(--xh-fg-danger));
  }

  [data-scope='file-upload'][data-part='item'][data-state='error']::before {
    content: '';
    flex: none;
    inline-size: var(--xh-file-upload-item-mark-size, var(--xh-control-indicator-size));
    block-size: var(--xh-file-upload-item-mark-size, var(--xh-control-indicator-size));
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-warning) center / contain no-repeat;
    mask: var(--xh-glyph-mark-warning) center / contain no-repeat;
  }

  /* 传完的那一行补一枚对勾，与失败那一枚警示字形对称：
     不标出来的话「传完了」与「还没开始」在这一行上看不出分别 */
  [data-scope='file-upload'][data-part='item'][data-state='done']::before {
    content: '';
    flex: none;
    inline-size: var(--xh-file-upload-item-mark-size, var(--xh-control-indicator-size));
    block-size: var(--xh-file-upload-item-mark-size, var(--xh-control-indicator-size));
    background-color: var(--xh-file-upload-item-fg-done, var(--xh-fg-success));
    -webkit-mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    mask: var(--xh-glyph-mark-check) center / contain no-repeat;
  }

  /* 传输进度条：只在传输中露面，填充按连接层写下的比例平移到位。
     进度是连续量，走 continuous 曲线，不是入场曲线 */
  [data-scope='file-upload'][data-part='item-progress'] {
    display: none;
    overflow: hidden;
    flex: none;
    inline-size: var(--xh-file-upload-item-progress-w, calc(var(--xh-control-h-md) * 2));
    block-size: var(--xh-file-upload-item-progress-h, var(--xh-stroke-thick));
    border-radius: var(--xh-file-upload-item-progress-radius, var(--xh-shape-pill));
    background: var(--xh-file-upload-item-progress-track, var(--xh-bg-subtle));
  }

  [data-scope='file-upload'][data-part='item-progress'][data-state='uploading'] {
    display: block;
  }

  [data-scope='file-upload'][data-part='item-progress'][data-state='uploading']::before {
    content: '';
    display: block;
    block-size: 100%;
    border-radius: inherit;
    background: var(--xh-file-upload-item-progress-fill, var(--xh-bg-brand));
    /* 铺满轨道，往行首平移藏起未完成的那一截、由轨道裁掉：推进只走合成，不重排也不重绘 */
    inline-size: 100%;
    translate: calc((var(--xh-_file-upload-progress, 0) - 1) * 100%) 0;
    transition: translate var(--xh-motion-duration-move) var(--xh-motion-ease-continuous);
  }

  /* translate 只认物理方向：RTL 下行首在右边，平移方向翻转 */
  [data-scope='file-upload'][data-part='item-progress'][data-state='uploading']:dir(rtl)::before {
    translate: calc((1 - var(--xh-_file-upload-progress, 0)) * 100%) 0;
  }

  [data-scope='file-upload'][data-part='item-progress'][hidden] {
    display: none;
  }

  /* 缩略图占位：作者往里塞图标或真缩略图，尺寸由这里定死，一行行的图标才对得齐 */
  [data-scope='file-upload'][data-part='item-preview'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-file-upload-preview-size, var(--xh-control-h-md));
    block-size: var(--xh-file-upload-preview-size, var(--xh-control-h-md));
    border-radius: var(--xh-file-upload-preview-radius, var(--xh-shape-control));
    background: var(--xh-file-upload-preview-bg, var(--xh-bg-subtle));
    color: var(--xh-file-upload-preview-fg, var(--xh-fg-muted));
    overflow: hidden;
  }

  [data-scope='file-upload'][data-part='item-preview'][hidden] {
    display: none;
  }

  /* data-file-type 是完整 MIME，按前缀分档即可；系统给不出类型时是 unknown，落回上面的中性底。
     只挑图标色不换底色：底色一换，一列文件里图片那几行会跳出来抢戏。
     取语义 token 而不是品牌色阶原值，深色主题才跟着走 */
  [data-scope='file-upload'][data-part='item-preview'][data-file-type^='image/'] {
    color: var(--xh-file-upload-preview-fg-image, var(--xh-fg-brand));
  }

  /* 塞进来的真缩略图撑满这个方框，长宽比不对就裁掉，不许把格子顶变形 */
  [data-scope='file-upload'][data-part='item-preview'] img {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  /* 文件名占满中间那段并用省略号收口。
     下限是这一行的换行点：名字缩到这个宽度还不够，后面的部件就被推去下一行；
     再用 100% 收一次口——容器比这个下限还窄时，名字只占满容器，不把整行顶宽 */
  [data-scope='file-upload'][data-part='item-name'] {
    flex: 1;
    min-inline-size: min(var(--xh-file-upload-item-name-min-w, var(--xh-control-min-w)), 100%);
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  /* 大小是次要信息：画淡、缩小，并用等宽数字——各位字宽不一时，
     一列文件的大小读起来会左右参差 */
  [data-scope='file-upload'][data-part='item-size-text'] {
    flex: none;
    color: var(--xh-file-upload-size-fg, var(--xh-fg-subtle));
    font-size: var(--xh-file-upload-size-font-size, var(--xh-text-caption-size));
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  [data-scope='file-upload'][data-part='item-size-text'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 删除是一行里的小图标按钮：正方形、无边框，靠底色表达 hover */
  [data-scope='file-upload'][data-part='item-delete-trigger'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-file-upload-delete-size, var(--xh-control-action-size));
    block-size: var(--xh-file-upload-delete-size, var(--xh-control-action-size));
    padding: 0;
    border: 0;
    border-radius: var(--xh-file-upload-delete-radius, var(--xh-shape-control));
    background: transparent;
    color: var(--xh-file-upload-delete-fg, var(--xh-fg-muted));
    font-family: inherit;
    line-height: var(--xh-leading-none);
    cursor: pointer;
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      scale var(--xh-motion-duration-release) var(--xh-motion-ease-release);
  }

  [data-scope='file-upload'][data-part='item-delete-trigger'][hidden] {
    display: none;
  }

  [data-scope='file-upload'][data-part='item-delete-trigger']:hover:not(:disabled) {
    background: var(--xh-file-upload-delete-bg-hover, var(--xh-bg-subtle-hover));
    color: var(--xh-file-upload-delete-fg-hover, var(--xh-fg-danger-hover));
  }

  /* 按下：换到按压档底色并轻微下压，松手弹回；禁用钮不压 */
  [data-scope='file-upload'][data-part='item-delete-trigger']:not(:disabled):is(:active, [data-pressed]) {
    background: var(--xh-file-upload-delete-bg-active, var(--xh-bg-subtle-active));
    scale: var(--xh-motion-scale-press);
    transition-duration: var(--xh-motion-duration-press);
    transition-timing-function: var(--xh-motion-ease-press);
  }

  [data-scope='file-upload'][data-part='item-delete-trigger']:disabled {
    color: var(--xh-fg-disabled);
  }

  /* 清空是收尾动作，画成不带底色的文字按钮：它比"选择文件"次要 */
  [data-scope='file-upload'][data-part='clear-trigger'] {
    display: inline-flex;
    flex: none;
    align-self: flex-start;
    align-items: center;
    justify-content: center;
    gap: var(--xh-file-upload-clear-gap, var(--xh-control-gap-sm));
    block-size: var(--xh-file-upload-clear-h, var(--xh-control-h-sm));
    padding-inline: var(--xh-file-upload-clear-px, var(--xh-control-px-sm));
    border: 0;
    border-radius: var(--xh-file-upload-clear-radius, var(--xh-shape-control));
    background: transparent;
    color: var(--xh-file-upload-clear-fg, var(--xh-fg-muted));
    font-family: inherit;
    font-size: var(--xh-file-upload-clear-font-size, var(--xh-text-caption-size));
    line-height: var(--xh-leading-none);
    cursor: pointer;
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      scale var(--xh-motion-duration-release) var(--xh-motion-ease-release);
  }

  [data-scope='file-upload'][data-part='clear-trigger'][hidden] {
    display: none;
  }

  [data-scope='file-upload'][data-part='clear-trigger']:hover:not(:disabled) {
    background: var(--xh-file-upload-clear-bg-hover, var(--xh-bg-subtle-hover));
    color: var(--xh-file-upload-clear-fg-hover, var(--xh-fg-default));
  }

  /* 按下：换到按压档底色并轻微下压，松手弹回；禁用钮不压 */
  [data-scope='file-upload'][data-part='clear-trigger']:not(:disabled):is(:active, [data-pressed]) {
    background: var(--xh-file-upload-clear-bg-active, var(--xh-bg-subtle-active));
    scale: var(--xh-motion-scale-press);
    transition-duration: var(--xh-motion-duration-press);
    transition-timing-function: var(--xh-motion-ease-press);
  }

  /* 空列表时按钮照常可按（收起它会让焦点掉回 body），只把前景压淡一档 */
  [data-scope='file-upload'][data-part='clear-trigger'][data-empty] {
    color: var(--xh-fg-subtle);
  }

  [data-scope='file-upload'][data-part='clear-trigger']:disabled {
    color: var(--xh-fg-disabled);
  }

  /*
   * 高对比档：三颗钮的按压面常态靠换底表出，这一档里底色被统一换成 Canvas，按住那一下与静息塌成同一个样子；
   * 用系统高亮反色画回来，兜底字形读 currentColor、自己跟着换
   */
  @media (forced-colors: active) {
    [data-scope='file-upload'][data-part='trigger']:not(:disabled):is(:active, [data-pressed]),
    [data-scope='file-upload'][data-part='item-delete-trigger']:not(:disabled):is(:active, [data-pressed]),
    [data-scope='file-upload'][data-part='clear-trigger']:not(:disabled):is(:active, [data-pressed]) {
      background: Highlight;
      color: HighlightText;
    }
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中 */
  [data-scope='file-upload'][data-part='item-delete-trigger']:empty::before,
  [data-scope='file-upload'][data-part='clear-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }
}

/* styles/form.css */
/* 定义 form 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */
/* Form 独立皮肤同时传递引入提交 / 重置钮的动作控件配方；full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='form'] {
    --xh-form-skin: 1;
  }

  /* 表单是一列字段：竖排、字段之间留一档间距。root 就是那个原生 <form> */
  [data-scope='form'][data-part='root'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-form-gap, var(--xh-stack-gap-md));
    margin: 0;
  }

  /* 网格：字段排进等宽列，各列下限写 0，一段长文本不会把自己那列撑宽。
     列数由 data-columns 逐档给，换档只改 --xh-_form-cols 这一个槽 */
  [data-scope='form'][data-part='root'][data-layout='grid'] {
    display: grid;
    grid-template-columns: repeat(var(--xh-_form-cols), minmax(0, 1fr));

    --xh-_form-cols: 1;
  }

  /* 只要声明了 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='form'][data-part='root'][hidden] {
    display: none;
  }

  /* 横排一行流：字段并肩排，放不下自动折行 */
  [data-scope='form'][data-part='root'][data-layout='inline'] {
    flex-flow: row wrap;
    align-items: start;
    column-gap: var(--xh-form-inline-gap, var(--xh-space-4));
  }

  /* 一列是网格档的缺省，这里从两列起逐档写 */
  [data-scope='form'][data-part='root'][data-columns='2'] {
    --xh-_form-cols: 2;
  }

  [data-scope='form'][data-part='root'][data-columns='3'] {
    --xh-_form-cols: 3;
  }

  [data-scope='form'][data-part='root'][data-columns='4'] {
    --xh-_form-cols: 4;
  }

  /* 逐档列数：移动优先，先按 data-columns 排定，视口每宽到一档就换成那一档的列数，
     没写的档沿用比它窄的那一档。四档自窄到宽依次写，只用 min-width：媒体查询不改选择器权重，
     宽视口上同时命中好几档时由源码序决定谁生效。
     宽度写字面量：自定义属性在 @media 条件里不参与求值。
     每档都从一列写起：base 分多列、某一档收回一列同样是合法的一档 */
  @media (min-width: 640px) {
    [data-scope='form'][data-part='root'][data-columns-sm='1'] {
      --xh-_form-cols: 1;
    }

    [data-scope='form'][data-part='root'][data-columns-sm='2'] {
      --xh-_form-cols: 2;
    }

    [data-scope='form'][data-part='root'][data-columns-sm='3'] {
      --xh-_form-cols: 3;
    }

    [data-scope='form'][data-part='root'][data-columns-sm='4'] {
      --xh-_form-cols: 4;
    }
  }

  @media (min-width: 768px) {
    [data-scope='form'][data-part='root'][data-columns-md='1'] {
      --xh-_form-cols: 1;
    }

    [data-scope='form'][data-part='root'][data-columns-md='2'] {
      --xh-_form-cols: 2;
    }

    [data-scope='form'][data-part='root'][data-columns-md='3'] {
      --xh-_form-cols: 3;
    }

    [data-scope='form'][data-part='root'][data-columns-md='4'] {
      --xh-_form-cols: 4;
    }
  }

  @media (min-width: 1024px) {
    [data-scope='form'][data-part='root'][data-columns-lg='1'] {
      --xh-_form-cols: 1;
    }

    [data-scope='form'][data-part='root'][data-columns-lg='2'] {
      --xh-_form-cols: 2;
    }

    [data-scope='form'][data-part='root'][data-columns-lg='3'] {
      --xh-_form-cols: 3;
    }

    [data-scope='form'][data-part='root'][data-columns-lg='4'] {
      --xh-_form-cols: 4;
    }
  }

  @media (min-width: 1280px) {
    [data-scope='form'][data-part='root'][data-columns-xl='1'] {
      --xh-_form-cols: 1;
    }

    [data-scope='form'][data-part='root'][data-columns-xl='2'] {
      --xh-_form-cols: 2;
    }

    [data-scope='form'][data-part='root'][data-columns-xl='3'] {
      --xh-_form-cols: 3;
    }

    [data-scope='form'][data-part='root'][data-columns-xl='4'] {
      --xh-_form-cols: 4;
    }
  }

  /* 字段容器只管排版与状态标记：标题、控件、描述、错误文案都是里面那个 Field 的活儿 */
  [data-scope='form'][data-part='field-group'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-form-field-gap, var(--xh-space-1));
  }

  [data-scope='form'][data-part='field-group'][hidden] {
    display: none;
  }

  /* 网格排布下这一格占多宽，不写就占一列 */
  [data-scope='form'][data-part='root'][data-layout='grid'] [data-scope='form'][data-part='field-group'] {
    grid-column: var(--xh-_form-span, auto);
  }

  /* 占一列是上面的缺省，这里从跨两列起逐档写 */
  [data-scope='form'][data-part='field-group'][data-span='2'] {
    --xh-_form-span: auto / span 2;
  }

  [data-scope='form'][data-part='field-group'][data-span='3'] {
    --xh-_form-span: auto / span 3;
  }

  [data-scope='form'][data-part='field-group'][data-span='4'] {
    --xh-_form-span: auto / span 4;
  }

  /* 占满整行：从第一条列线排到最后一条，列数换档时不必跟着改跨度 */
  [data-scope='form'][data-part='field-group'][data-span='full'] {
    --xh-_form-span: 1 / -1;
  }

  /* 出错的字段在起始缘竖一条色带：读屏之外还得有一眼看得见的定位标记。
     用逻辑属性，RTL 下自动换到右侧 */
  [data-scope='form'][data-part='field-group'][data-invalid] {
    padding-inline-start: var(--xh-form-field-invalid-px, var(--xh-space-2));
    border-inline-start: var(--xh-stroke-thick) solid var(--xh-form-field-invalid-border, var(--xh-border-invalid));
  }

  /* 提交失败后的错误汇总。role=alert 常挂，靠 hidden 显隐 */
  [data-scope='form'][data-part='error-summary'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-form-summary-gap, var(--xh-space-1_5));
    padding-block: var(--xh-form-summary-py, var(--xh-space-3));
    padding-inline: var(--xh-form-summary-px, var(--xh-control-px-md));
    border: var(--xh-stroke-thin) solid var(--xh-form-summary-border, var(--xh-border-invalid));
    border-radius: var(--xh-form-summary-radius, var(--xh-shape-surface));
    background: var(--xh-form-summary-bg, var(--xh-bg-surface));
    color: var(--xh-form-summary-fg, var(--xh-fg-danger));
    font-size: var(--xh-form-summary-font-size, var(--xh-text-body-size));
    line-height: var(--xh-leading-normal);
    /* 静态反馈面：边界由描边承担，不带落影（solid 无影） */
    box-shadow: var(--xh-form-summary-shadow, none);
  }

  /* 漏了这条，摘要一旦出现过就再也撤不下去（上面那条 display 盖掉了 UA 的 [hidden] 规则） */
  [data-scope='form'][data-part='error-summary'][hidden] {
    display: none;
  }

  /* 摘要不承载焦点（焦点直接送去出错的字段），它只是一段播报，落焦时不画环 */
  [data-scope='form'][data-part='error-summary']:focus-visible {
    outline: none;
  }

  /* 从收起翻成显出的那一下给一小段入场：读屏靠 role=alert 播报，
     视觉这边也得有个"它是刚冒出来的"的交代，否则像一直杵在那儿 */
  [data-scope='form'][data-part='error-summary'][data-state='invalid'] {
    animation: xh-drop-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 摘要里的每一条是一个真链接，指向对应字段容器。铺满一行的集合行：悬停 / 按下只换面不缩放，
     底面坐在摘要的 surface 白底上，走白底承载阶梯 100 → 200；换面走按压时间线，释放回 release 档 */
  [data-scope='form'][data-part='error-summary-item'] {
    display: block;
    padding-inline: var(--xh-form-summary-item-px, var(--xh-space-1));
    border-radius: var(--xh-form-summary-item-radius, var(--xh-shape-control));
    background: var(--xh-form-summary-item-bg, transparent);
    color: inherit;
    font-size: var(--xh-form-summary-item-font-size, var(--xh-text-secondary-size));
    text-decoration: underline;
    text-underline-offset: var(--xh-form-summary-item-underline-offset, var(--xh-space-0_5));
    cursor: pointer;
    transition:
      background-color var(--xh-motion-duration-release) var(--xh-motion-ease-release),
      color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 没有对应错误的条目由连接层给 hidden；上面那条 display 已把 UA 规则盖掉 */
  [data-scope='form'][data-part='error-summary-item'][hidden] {
    display: none;
  }

  /* 摘要显出时条目逐条入场，越靠后起步越晚。
     backwards 让还没轮到的条目停在首帧，不是先显出再重播 */
  [data-scope='form'][data-part='error-summary'][data-state='invalid'] [data-part='error-summary-item'] {
    animation: xh-drop-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong) backwards;
  }

  /* 排序按"前面有几条露面的"数，不按 nth-child：作者一次把所有字段的条目都写上，
     没出错的那些带着 hidden 留在 DOM 里，按位置数会把空号也算进去。
     每多一节 ~ 就多要求前面多一条露面的条目，链越长的规则排得越后、赢过短链 */
  [data-scope='form'][data-part='error-summary'][data-state='invalid']
    [data-part='error-summary-item']:not([hidden])
    ~ [data-part='error-summary-item']:not([hidden]) {
    animation-delay: var(--xh-motion-stagger-step);
  }

  [data-scope='form'][data-part='error-summary'][data-state='invalid']
    [data-part='error-summary-item']:not([hidden])
    ~ [data-part='error-summary-item']:not([hidden])
    ~ [data-part='error-summary-item']:not([hidden]) {
    animation-delay: calc(var(--xh-motion-stagger-step) * 2);
  }

  [data-scope='form'][data-part='error-summary'][data-state='invalid']
    [data-part='error-summary-item']:not([hidden])
    ~ [data-part='error-summary-item']:not([hidden])
    ~ [data-part='error-summary-item']:not([hidden])
    ~ [data-part='error-summary-item']:not([hidden]) {
    animation-delay: calc(var(--xh-motion-stagger-step) * 3);
  }

  [data-scope='form'][data-part='error-summary'][data-state='invalid']
    [data-part='error-summary-item']:not([hidden])
    ~ [data-part='error-summary-item']:not([hidden])
    ~ [data-part='error-summary-item']:not([hidden])
    ~ [data-part='error-summary-item']:not([hidden])
    ~ [data-part='error-summary-item']:not([hidden]) {
    animation-delay: calc(var(--xh-motion-stagger-step) * 4);
  }

  /* 第 6 条起共用同一档延迟：这条要求前面有五条露面的，第七条往后同样命中，
     错误多时整批的等待时间不再随条数增长 */
  [data-scope='form'][data-part='error-summary'][data-state='invalid']
    [data-part='error-summary-item']:not([hidden])
    ~ [data-part='error-summary-item']:not([hidden])
    ~ [data-part='error-summary-item']:not([hidden])
    ~ [data-part='error-summary-item']:not([hidden])
    ~ [data-part='error-summary-item']:not([hidden])
    ~ [data-part='error-summary-item']:not([hidden]) {
    animation-delay: calc(var(--xh-motion-stagger-step) * 5);
  }

  [data-scope='form'][data-part='error-summary-item']:hover {
    background: var(--xh-form-summary-item-bg-hover, var(--xh-bg-subtle));
    color: var(--xh-form-summary-item-fg-hover, var(--xh-fg-danger-hover));
  }

  /* 指针 :active 与 Headless 投影的 data-pressed（Space / Enter 与触屏按住）看见同一副按压面 */
  [data-scope='form'][data-part='error-summary-item']:is(:active, [data-pressed]) {
    background: var(--xh-form-summary-item-bg-pressed, var(--xh-bg-subtle-hover));
    color: var(--xh-form-summary-item-fg-hover, var(--xh-fg-danger-hover));
    transition-duration: var(--xh-motion-duration-press);
    transition-timing-function: var(--xh-motion-ease-press);
  }

  /* 高对比档里底色被系统换掉，按下那一档用系统高亮反色画回 */
  @media (forced-colors: active) {
    [data-scope='form'][data-part='error-summary-item']:is(:active, [data-pressed]) {
      background: Highlight;
      color: HighlightText;
    }
  }

  /* 两颗按钮是离散动作控件：盒几何、悬停 / 按下与 0.97 按压、焦点环、禁用面全由 Action Control 的 text 档给，
     组件只映射既有使用者槽。提交走 solid 档：表单提交是这一组里的主要动作，与 Button 缺省同为品牌实心；
     重置走 outline 档：非 Button 的触发器缺省中性描边。两颗共用的几何与字号写在一起 */
  [data-scope='form'][data-part='submit-trigger'],
  [data-scope='form'][data-part='reset-trigger'] {
    --xh-action-visual-size: var(--xh-form-trigger-h, var(--xh-_action-profile-visual-size));
    --xh-action-padding-inline: var(--xh-form-trigger-px, var(--xh-_action-profile-padding-inline));
    --xh-action-radius: var(--xh-form-trigger-radius, var(--xh-shape-control));
    --xh-action-font-size: var(--xh-form-trigger-font-size, var(--xh-text-body-size));

    /* 按钮不参与弹性伸缩 */
    flex: none;
  }

  /* 家族那条 display 会把 UA 的 [hidden]{display:none} 盖掉 */
  [data-scope='form'][data-part='submit-trigger'][hidden],
  [data-scope='form'][data-part='reset-trigger'][hidden] {
    display: none;
  }

  /* 重置钮：中性描边，底 / 边 / 字与禁用面映到 outline 档的桥接槽（透明底 → 100 → 200） */
  [data-scope='form'][data-part='reset-trigger'] {
    --xh-action-bg-rest: var(--xh-form-trigger-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-form-trigger-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-form-trigger-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-bg-disabled: var(--xh-form-trigger-bg-disabled, var(--xh-_action-variant-bg-disabled));
    --xh-action-fg-rest: var(--xh-form-trigger-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-form-trigger-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-form-trigger-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-border-rest: var(--xh-form-trigger-border, var(--xh-_action-variant-border-rest));
    --xh-action-border-hover: var(--xh-form-trigger-border-hover, var(--xh-_action-variant-border-hover));
    --xh-action-border-disabled: var(--xh-form-trigger-border-disabled, var(--xh-_action-variant-border-disabled));
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
  }

  /* 提交钮：品牌实心，顶边一条极浅的内高光把这块面衬出厚度（三态同一支，禁用面由家族收掉）。
     面是实心的，环色与面同族，画在面里就看不出来；环改取面自己的前景色——
     那一族色本来就要在这块面上把字读清楚，与面的对比是按可读性定的 */
  [data-scope='form'][data-part='submit-trigger'] {
    --xh-action-bg-rest: var(--xh-form-submit-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-form-submit-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-form-submit-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-bg-disabled: var(--xh-form-trigger-bg-disabled, var(--xh-_action-variant-bg-disabled));
    --xh-action-fg-rest: var(--xh-form-submit-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-form-submit-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-form-submit-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-border-rest: var(--xh-form-submit-border, var(--xh-_action-variant-border-rest));
    --xh-action-border-hover: var(--xh-form-submit-border-hover, var(--xh-_action-variant-border-hover));
    --xh-action-border-pressed: var(--xh-form-submit-border-active, var(--xh-_action-variant-border-pressed));
    --xh-action-border-disabled: var(--xh-form-trigger-border-disabled, var(--xh-_action-variant-border-disabled));
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: var(--xh-form-submit-shadow, var(--xh-_highlight-brand));
    --xh-action-shadow-hover: var(--xh-form-submit-shadow, var(--xh-_highlight-brand));
    --xh-action-shadow-pressed: var(--xh-form-submit-shadow, var(--xh-_highlight-brand));
    --xh-action-ring-color-focus-visible: currentColor;
  }
}

/* styles/hover-card.css */
/* 定义 hover card 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='hover-card'] {
    --xh-hover-card-skin: 1;
  }

  /* 根节点只把 trigger 与浮层收在一处，不参与定位（坐标系仍由祖先的定位上下文决定） */
  [data-scope='hover-card'][data-part='root'] {
    display: inline-block;
  }

  [data-scope='hover-card'][data-part='root'][hidden] {
    display: none;
  }

  [data-scope='hover-card'][data-part='trigger'] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--xh-hover-card-trigger-gap, var(--xh-control-gap-sm));
    border: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    cursor: inherit;
  }

  [data-scope='hover-card'][data-part='trigger'][hidden] {
    display: none;
  }

  /* 这里的 data-disabled 关掉的是卡片，不是宿主控件：光标仍旧交给宿主 */
  [data-scope='hover-card'][data-part='root'][data-disabled],
  [data-scope='hover-card'][data-part='trigger'][data-disabled] {
    cursor: inherit;
  }

  /* 坐标由定位引擎写进 style（inset-inline-start / inset-block-start），这里只定位模式与层级 */
  [data-scope='hover-card'][data-part='positioner'] {
    /* 落定那一侧的可用高度，由定位引擎经内联自定义属性写进来，内容层继承它限高；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时不额外限高 */
    --xh-_hover-card-available-h: 100vh;
    /* 落定那一侧的可用宽度，同样由定位引擎经内联自定义属性写进来，行内轴据此夹取；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时退到视口宽 */
    --xh-_hover-card-available-w: 100vw;

    /* 卡片内容的自绘条浮在内容之上：轨道不上底色，实色轨道会在卡片右缘糊一条竖灰带 */
    --xh-scrollbar-track-bg: transparent;

    position: fixed;
    z-index: var(--xh-hover-card-layer, var(--xh-_layer, var(--xh-layer-popover)));
    /* 空壳不吃指针：trigger 与 content 之间那段间隙要能点得穿，
       指针穿行的判定全靠 content 自己的进出事件 */
    pointer-events: none;
  }

  /* 锚点被滚出可视区：整个浮层随之收起 */
  [data-scope='hover-card'][data-part='positioner'][data-hidden] {
    visibility: hidden;
  }

  /* 缩放原点与进场位移按落定的那一侧给：卡片从贴着锚点的那条边涨开、沿主轴退让一小段。
     两个槽由 content 继承。placement 是物理方向（引擎按 top / right / bottom / left 出值），
     origin 与 translate 也是物理量，两边同轴，不随书写方向翻 */
  [data-scope='hover-card'][data-part='positioner'][data-placement^='top'] {
    --xh-_overlay-origin-y: 100%;
    --xh-_overlay-enter-down: 1;
  }

  [data-scope='hover-card'][data-part='positioner'][data-placement^='bottom'] {
    --xh-_overlay-origin-y: 0;
    --xh-_overlay-enter-up: 1;
  }

  [data-scope='hover-card'][data-part='positioner'][data-placement^='left'] {
    --xh-_overlay-origin-x: 100%;
    --xh-_overlay-enter-right: 1;
  }

  [data-scope='hover-card'][data-part='positioner'][data-placement^='right'] {
    --xh-_overlay-origin-x: 0;
    --xh-_overlay-enter-left: 1;
  }

  /* 与 tooltip 不同：卡片本体承载交互，必须吃指针——
     指针停在卡片上就不该收起，里面的链接与按钮也要点得到 */
  [data-scope='hover-card'][data-part='content'] {
    /* 尺寸档只换这两个私有槽。size 落在 content 上而非 root：root 是可选部件，
       面板几何也长在 content 上。语气不接：卡片是内容容器，语气该由里面的内容表达 */
    --xh-_hover-card-pad: var(--xh-surface-pad-md);
    --xh-_hover-card-max-w: var(--xh-overlay-max-w);

    position: relative;
    display: flex;
    flex-direction: column;
    gap: var(--xh-hover-card-gap, var(--xh-space-2));
    inline-size: max-content;
    /* 静态档与落位后的可用宽度取小：窄视口下面板伸出去，最右侧的内容就点不到了 */
    max-inline-size: min(var(--xh-hover-card-max-w, var(--xh-_hover-card-max-w)), var(--xh-_hover-card-available-w));
    /* 内容由作者给，长度不可预知：不限高就整块伸出视口且滚不到 */
    max-block-size: min(var(--xh-hover-card-max-h, var(--xh-overlay-max-h)), var(--xh-_hover-card-available-h));
    overflow-y: auto;
    /* 浮在页面之上的 Overlay 滚动面：滚到头不把页面一起带走 */
    overscroll-behavior: contain;
    padding-block: var(--xh-hover-card-py, var(--xh-_hover-card-pad));
    padding-inline: var(--xh-hover-card-px, var(--xh-_hover-card-pad));
    border: var(--xh-stroke-thin) solid var(--xh-hover-card-border, var(--xh-material-frosted-border));
    border-radius: var(--xh-hover-card-radius, var(--xh-shape-overlay));
    /* 与气泡族共用 M2：顶光只占一像素，正文保持实体，只在内容层采样一次背景。 */
    background:
      linear-gradient(
        to bottom,
        var(--xh-material-frosted-highlight) 0 var(--xh-stroke-thin),
        transparent var(--xh-stroke-thin)
      ),
      var(--xh-hover-card-bg, var(--xh-material-frosted-bg));
    color: var(--xh-hover-card-fg, var(--xh-material-frosted-fg));
    box-shadow: var(--xh-hover-card-shadow, var(--xh-material-frosted-shadow));
    -webkit-backdrop-filter: var(--xh-hover-card-backdrop, var(--xh-material-frosted-backdrop));
    backdrop-filter: var(--xh-hover-card-backdrop, var(--xh-material-frosted-backdrop));
    pointer-events: auto;
    /* 进退场的缩放锚在贴着锚点的那条边上；两个分量由 positioner 按 placement 写进私有槽 */
    transform-origin: var(--xh-_overlay-origin-x, 50%) var(--xh-_overlay-origin-y, 50%);
  }

  /* 这里刻意没有 [data-part='content'][hidden] { display: none }，与 dialog 一致：
     收起态连接层会给 content 打 hidden，而上面那条 display 正是要盖掉 UA 的
     [hidden]{display:none}——退场动画得先能播。presence 读的是 content 的 animationName，
     真正的收起由宿主在退场结束后落成内联 display:none（Vue 那边直接不渲染）。
     其余声明了 display 的角色节点仍补 [hidden]，那几处没有退场动画。 */

  /* 卡片是可编程聚焦的容器（tabindex=-1），焦点环留给里面真正的可聚焦元素 */
  [data-scope='hover-card'][data-part='content']:focus-visible {
    outline: none;
  }

  [data-scope='hover-card'][data-part='content'][data-state='open'] {
    animation: xh-overlay-pop-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 退场：收起那一帧 hidden 由退场闸门押后，这里才播得出来。forwards 把末态钉住，
     免得动画结束到真收起之间闪一下原样 */
  [data-scope='hover-card'][data-part='content'][data-state='closed'] {
    animation: xh-pop-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* —— 尺寸 —— */
  /* 缺省档写在 content 的基础规则里；四边等宽的面板内衬三档取 surface-pad 那把尺 */
  [data-scope='hover-card'][data-part='content'][data-size='sm'] {
    --xh-_hover-card-pad: var(--xh-surface-pad-sm);
    --xh-_hover-card-max-w: var(--xh-overlay-max-w-sm);
  }

  [data-scope='hover-card'][data-part='content'][data-size='lg'] {
    --xh-_hover-card-pad: var(--xh-surface-pad-lg);
    --xh-_hover-card-max-w: var(--xh-overlay-max-w-lg);
  }

  [data-scope='hover-card'][data-part='title'] {
    margin: 0;
    font-size: var(--xh-hover-card-title-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-hover-card-title-font-weight, var(--xh-font-weight-semibold));
    color: var(--xh-hover-card-title-fg, var(--xh-fg-default));
  }

  /* 说明文字走说明档：13px + fg-muted */
  [data-scope='hover-card'][data-part='description'] {
    margin: 0;
    font-size: var(--xh-hover-card-description-font-size, var(--xh-text-secondary-size));
    color: var(--xh-hover-card-description-fg, var(--xh-fg-muted));
  }

  /* 箭头的底色与描边色，几何在 overlay-arrow.css。
     交叉轴落点由定位引擎经内联自定义属性写进来，没给时退回居中 */
  [data-scope='hover-card'][data-part='arrow'] {
    --xh-_hover-card-arrow-x: 50%;
    --xh-_hover-card-arrow-y: 50%;
    --xh-_overlay-arrow-size: var(--xh-hover-card-arrow-size, var(--xh-overlay-arrow-size));
    --xh-_overlay-arrow-x: var(--xh-_hover-card-arrow-x);
    --xh-_overlay-arrow-y: var(--xh-_hover-card-arrow-y);

    background: var(--xh-hover-card-bg, var(--xh-material-frosted-bg));
    border: var(--xh-stroke-thin) solid var(--xh-hover-card-border, var(--xh-material-frosted-border));
  }

  @media (forced-colors: active) {
    [data-scope='hover-card'][data-part='content'] {
      background-image: none;
    }
  }

  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。 */
    [data-scope='hover-card'][data-part='positioner'] {
      display: none;
    }
  }
}

/* styles/icon.css */
/* 定义 icon 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='icon'] {
    --xh-icon-skin: 1;
  }

  /*
   * 根 <svg>。直径、描边粗细、行内位置都由这里给，记录只带几何。
   * 不写 fill / stroke：记录里那两条呈现属性取 currentColor，改这里会把
   * 描边图标与实心图标一起改掉；皮肤只给 color，配色随上下文流下来。
   */
  [data-scope='icon'][data-part='root'] {
    display: inline-block;
    flex: none;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-md));

    /* 替换元素的基线就是自身下边缘，落在文字基线上时整块图形都在基线以上、看着偏高。
       往下挪一小段，单位是 em，跟着相邻文字的字号一起缩放 */
    vertical-align: var(--xh-icon-shift, var(--xh-glyph-baseline-shift));
    color: var(--xh-icon-fg, currentColor);

    /* 记录把 stroke-width 写成根上的呈现属性，呈现属性的层叠优先级低于任何 CSS 规则，
       这条与下面两档因此能接管粗细，再沿继承落到每个图元上 */
    stroke-width: var(--xh-icon-stroke, var(--xh-glyph-stroke-regular));
  }

  /* 声明了 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='icon'][data-part='root'][hidden] {
    display: none;
  }

  /* 八档直径，缺省档 md 写在上面的基础规则里。
     每一档都把 --xh-icon-size 排在自己的档值前面：这个槽是外层统一图元直径的通道，
     档值直接写终值的话，写了 data-size 的那一枚就脱离外层控制，作者在祖先上的覆盖也改不动它 */
  [data-scope='icon'][data-part='root'][data-size='text'] {
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
  }

  [data-scope='icon'][data-part='root'][data-size='sm'] {
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-sm));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-sm));
  }

  [data-scope='icon'][data-part='root'][data-size='md'] {
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-md));
  }

  [data-scope='icon'][data-part='root'][data-size='lg'] {
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-lg));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-lg));
  }

  [data-scope='icon'][data-part='root'][data-size='xl'] {
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-xl));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-xl));
  }

  [data-scope='icon'][data-part='root'][data-size='2xl'] {
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-2xl));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-2xl));
  }

  [data-scope='icon'][data-part='root'][data-size='3xl'] {
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-3xl));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-3xl));
  }

  [data-scope='icon'][data-part='root'][data-size='4xl'] {
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-4xl));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-4xl));
  }

  /* 三档描边，缺省档同样写在基础规则里；--xh-icon-stroke 同样排在档值前面 */
  [data-scope='icon'][data-part='root'][data-weight='light'] {
    stroke-width: var(--xh-icon-stroke, var(--xh-glyph-stroke-light));
  }

  [data-scope='icon'][data-part='root'][data-weight='bold'] {
    stroke-width: var(--xh-icon-stroke, var(--xh-glyph-stroke-bold));
  }

  /* 语气：图标没有底色，语气只落在前景上，取普通背景上表达该语气的那档文字色。
     选择器上带 [data-tone] 是必需的：语气槽会沿继承流下来，不限定在写了语气的
     那个节点上，放在语气容器里的装饰图标会跟着一起改色 */
  [data-scope='icon'][data-part='root'][data-tone] {
    color: var(--xh-icon-fg, var(--xh-_tone-fg, currentColor));
  }

  /* 旋转：四分之一圈的整数倍，是把箭头指向别处的结构性角度，不是可调幅度。
     没有过渡也没有动画——转到位就停在那儿，减弱动效那一档碰不到它 */
  [data-scope='icon'][data-part='root'][data-rotate='90'] {
    rotate: 90deg;
  }

  [data-scope='icon'][data-part='root'][data-rotate='180'] {
    rotate: 180deg;
  }

  [data-scope='icon'][data-part='root'][data-rotate='270'] {
    rotate: 270deg;
  }

  /* 翻转：沿轴取反，同样是静态几何。与旋转是两个独立属性，同写时自然叠加 */
  [data-scope='icon'][data-part='root'][data-flip='horizontal'] {
    scale: -1 1;
  }

  [data-scope='icon'][data-part='root'][data-flip='vertical'] {
    scale: 1 -1;
  }

  [data-scope='icon'][data-part='root'][data-flip='both'] {
    scale: -1 -1;
  }
}

/* styles/image.css */
/* 定义 image 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='image'] {
    --xh-image-skin: 1;
  }

  /* 尺寸交给三个变量而不是写死：这个组件既要能当封面图，也要能当头图与缩略图。
     给了 --xh-image-ratio 才有确定高度，回退内容与图片在同一个盒子里换人时不会跳。 */
  [data-scope='image'][data-part='root'] {
    position: relative;
    display: block;
    overflow: hidden;
    inline-size: var(--xh-image-w, 100%);
    block-size: var(--xh-image-h, auto);
    aspect-ratio: var(--xh-image-ratio, auto);
    border-radius: var(--xh-image-radius, var(--xh-shape-control));
    background: var(--xh-image-bg, var(--xh-bg-subtle));
  }

  /* 声明了 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='image'][data-part='root'][hidden] {
    display: none;
  }

  /* 不声明 display：加载完成前的 hidden 直接交给浏览器的 [hidden] 规则收起。
     载完那一刻 hidden 撤掉、这个节点从不显示变为显示，淡入在那一刻起跑，
     图片不是硬切上来盖掉占位层 */
  [data-scope='image'][data-part='image'] {
    inline-size: 100%;
    block-size: 100%;
    object-fit: var(--xh-image-fit, cover);
    animation: xh-fade-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter);
  }

  /* 铺满图位的占位层：加载期间占住画面，作者往里放骨架屏或模糊小图 */
  [data-scope='image'][data-part='placeholder'] {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--xh-image-placeholder-bg, var(--xh-bg-subtle-hover));
    color: var(--xh-image-placeholder-fg, var(--xh-fg-subtle));
  }

  /* display 会盖掉 hidden 属性的 UA 规则：图片落位与失败后都靠这条收起 */
  [data-scope='image'][data-part='placeholder'][hidden] {
    display: none;
  }

  [data-scope='image'][data-part='fallback'] {
    display: flex;
    align-items: center;
    justify-content: center;
    inline-size: 100%;
    block-size: 100%;
    /* 没给 ratio 时根盒子高度是 auto，回退内容自己撑出一个不塌的高度 */
    min-block-size: var(--xh-image-fallback-min-h, var(--xh-control-h-lg));
    color: var(--xh-image-fallback-fg, var(--xh-fg-muted));
    font-size: var(--xh-image-fallback-font-size, var(--xh-text-secondary-size));
    line-height: var(--xh-leading-none);
    user-select: none;
  }

  /* display 会盖掉 hidden 属性的 UA 规则：延迟窗口内与加载完成后都靠这条收起 */
  [data-scope='image'][data-part='fallback'][hidden] {
    display: none;
  }
}

/* styles/image-viewer.css */
/* 定义 image viewer 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='image-viewer'] {
    --xh-image-viewer-skin: 1;
  }

  [data-scope='image-viewer'][data-part='backdrop'] {
    position: fixed;
    inset: 0;
    z-index: var(--xh-image-viewer-backdrop-layer, var(--xh-_layer, var(--xh-layer-modal)));
    /* 看片要压住页面底色，遮罩比普通对话框更深 */
    background: var(--xh-image-viewer-backdrop-bg, color-mix(in oklab, var(--xh-color-neutral-950) 78%, transparent));
  }

  /* 同一层底色之上再糊背后的页面 */
  [data-scope='image-viewer'][data-part='backdrop'][data-variant='blur'] {
    -webkit-backdrop-filter: blur(var(--xh-image-viewer-backdrop-blur, var(--xh-overlay-backdrop-blur)));
    backdrop-filter: blur(var(--xh-image-viewer-backdrop-blur, var(--xh-overlay-backdrop-blur)));
  }

  /* 去掉底色，只留下这一层吃指针：交互外关闭与滚动锁定照旧 */
  [data-scope='image-viewer'][data-part='backdrop'][data-variant='transparent'] {
    background: transparent;
  }

  [data-scope='image-viewer'][data-part='backdrop'][data-state='open'] {
    animation: xh-fade-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter);
  }

  [data-scope='image-viewer'][data-part='backdrop'][data-state='closed'] {
    animation: xh-fade-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  [data-scope='image-viewer'][data-part='positioner'] {
    position: fixed;
    inset: 0;
    z-index: var(--xh-image-viewer-layer, var(--xh-_layer, var(--xh-layer-modal)));
    display: flex;
    align-items: center;
    justify-content: center;
  }

  [data-scope='image-viewer'][data-part='content'] {
    /* 组件内那几档层号只在自己人之间排序：建一个层叠上下文把它们关起来，
       既不让页面上的层号插进来，也不让它们漏出去压住别人 */
    isolation: isolate;

    /* 作者塞进浮层的图标：内容层给一档 md 的尺，十颗钮各自再按 Action Control 档位覆盖 */
    --xh-icon-size: var(--xh-image-viewer-icon-size, var(--xh-glyph-size-md));
    /* 十颗钮共用的深色 chrome：压在使用者的图片上的半透明深底，是这一层自己的面，不取页面语义面 */
    --xh-_image-viewer-chrome-bg: var(--xh-image-viewer-chrome-bg, color-mix(in oklab, var(--xh-color-neutral-950) 55%, transparent));
    --xh-_image-viewer-chrome-bg-hover: var(--xh-image-viewer-action-bg-hover, color-mix(in oklab, var(--xh-color-neutral-950) 70%, transparent));
    --xh-_image-viewer-chrome-bg-active: var(--xh-image-viewer-action-bg-active, color-mix(in oklab, var(--xh-color-neutral-950) 80%, transparent));

    position: relative;
    inline-size: 100%;
    block-size: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    outline: none;
    /* 深色底上的工具条与计数固定用浅字，不随主题翻 */
    color: var(--xh-image-viewer-fg, var(--xh-color-neutral-0));
  }

  [data-scope='image-viewer'][data-part='content'][data-state='open'] {
    animation: xh-fade-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter);
  }

  [data-scope='image-viewer'][data-part='content'][data-state='closed'] {
    animation: xh-fade-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  [data-scope='image-viewer'][data-part='viewport'] {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    cursor: grab;
    /* 平移与滚轮都归指针会话，浏览器手势不抢 */
    touch-action: none;
  }

  [data-scope='image-viewer'][data-part='viewport'][data-dragging] {
    cursor: grabbing;
  }

  /* 原图还在路上：指针先报出来，此刻拖也没有东西可拖 */
  [data-scope='image-viewer'][data-part='viewport'][data-loading] {
    cursor: progress;
  }

  /* 取图期间在画面正中垫一块占位面：不垫的话打开一张几 MB 的原图，
     台前是一整块什么都没有的暗底，用户分不清是在加载还是这张图坏了 */
  [data-scope='image-viewer'][data-part='viewport'][data-loading]::after {
    content: '';
    position: absolute;
    inline-size: var(--xh-image-viewer-loading-size, calc(var(--xh-control-h-lg) * 3));
    block-size: var(--xh-image-viewer-loading-size, calc(var(--xh-control-h-lg) * 3));
    border-radius: var(--xh-image-viewer-loading-radius, var(--xh-shape-surface));
    background: var(--xh-image-viewer-loading-bg, var(--xh-bg-surface-raised));
  }

  [data-scope='image-viewer'][data-part='image'] {
    max-inline-size: 90%;
    max-block-size: 85%;
    user-select: none;
    /* 变换是内联 style 写的，只给缩放旋转一点缓动；拖拽平移要跟手，不缓 */
    transition: transform var(--xh-motion-duration-nudge) var(--xh-motion-ease-continuous);
  }

  /* 拖拽期间变换每帧都在改：只在这一档备好合成层，松手后随 data-dragging 一起撤掉 */
  [data-scope='image-viewer'][data-part='image'][data-dragging] {
    transition: none;
    will-change: transform;
  }

  /* —— 悬浮件共用：半透明深底加浅字 ——
     四件都钉在铺满视口的那一层的边上，贴边一律与安全区取大的一头：刘海、圆角与
     底部横条压住的那一段由系统给出，贴边比它窄时钮会被切掉一角；桌面上 env() 恒为 0。
     安全区只有物理方向的四个名字，行内轴上两侧同取较宽的那一段，RTL 下不会翻错边。
     工具条是容器、计数是一行字的气泡，各按身份取圆角（surface / control），
     --xh-image-viewer-overlay-radius 仍是两者共用的使用者入口；翻页钮的面走下面的桥接槽 */
  [data-scope='image-viewer'][data-part='toolbar'],
  [data-scope='image-viewer'][data-part='counter'] {
    position: absolute;
    z-index: 1;
    background: var(--xh-_image-viewer-chrome-bg);
    color: inherit;
    border: none;
  }

  [data-scope='image-viewer'][data-part='toolbar'] {
    inset-block-end: max(var(--xh-space-6), env(safe-area-inset-bottom));
    inset-inline-start: 50%;
    translate: -50% 0;
    display: flex;
    align-items: center;
    gap: var(--xh-image-viewer-toolbar-gap, var(--xh-space-1));
    padding: var(--xh-image-viewer-toolbar-padding, var(--xh-space-1_5) var(--xh-space-3));
    border-radius: var(--xh-image-viewer-toolbar-radius-outer, var(--xh-image-viewer-overlay-radius, var(--xh-shape-surface)));
  }

  /* 工具条里的七颗钮：接 Action Control icon 档 xs（24px 视觉盒），底色交给工具条，本体只管命中区与按压。
     悬停 / 按下的底从 chrome 那层深底派生，不取页面的 --xh-bg-subtle-* 阶梯。
     position 交给配方的 relative：粗指针下 44px 命中区 ::after 以钮自身为包含块；
     这里若写 static，七块命中区会一起以工具条为包含块、彼此盖住，触屏上只剩最后一颗可点 */
  [data-scope='image-viewer'][data-part='toolbar'] > [data-part] {
    --xh-action-bg-rest: transparent;
    --xh-action-bg-hover: var(--xh-_image-viewer-chrome-bg-hover);
    --xh-action-bg-pressed: var(--xh-_image-viewer-chrome-bg-active);
    --xh-action-bg-focus-visible: transparent;
    --xh-action-bg-disabled: transparent;
    --xh-action-fg-rest: currentColor;
    --xh-action-fg-hover: currentColor;
    --xh-action-fg-pressed: currentColor;
    --xh-action-fg-focus-visible: currentColor;
    --xh-action-fg-disabled: currentColor;
    --xh-action-border-rest: transparent;
    --xh-action-border-hover: transparent;
    --xh-action-border-pressed: transparent;
    --xh-action-border-focus-visible: transparent;
    --xh-action-border-disabled: transparent;
    --xh-action-radius: var(--xh-image-viewer-toolbar-radius, var(--xh-_action-profile-radius));
    --xh-icon-size: var(--xh-image-viewer-icon-size, var(--xh-_action-profile-glyph-size));
  }

  [data-scope='image-viewer'][data-part='counter'] {
    inset-block-start: max(var(--xh-space-6), env(safe-area-inset-top));
    inset-inline-start: 50%;
    translate: -50% 0;
    padding: var(--xh-image-viewer-counter-padding, var(--xh-space-1) var(--xh-space-3));
    border-radius: var(--xh-image-viewer-counter-radius, var(--xh-image-viewer-overlay-radius, var(--xh-shape-control)));
    font-size: var(--xh-text-secondary-size);
  }

  /* 两颗翻页钮：浮在图上的单图标圆钮，接 Action Control floating 档 md（48px，正方盒取 circle）。
     面桥接到自家深色 chrome：跟的是图上那层半透明深底不是页面底色，所以不取 frosted 缺省面，
     也不取语义档的 --xh-bg-subtle-*；到头时是原生 disabled，压不动的东西不给回应 */
  [data-scope='image-viewer'][data-part='prev-trigger'],
  [data-scope='image-viewer'][data-part='next-trigger'] {
    --xh-action-bg-rest: var(--xh-_image-viewer-chrome-bg);
    --xh-action-bg-hover: var(--xh-_image-viewer-chrome-bg-hover);
    --xh-action-bg-pressed: var(--xh-_image-viewer-chrome-bg-active);
    --xh-action-bg-focus-visible: var(--xh-_image-viewer-chrome-bg);
    --xh-action-bg-disabled: var(--xh-_image-viewer-chrome-bg);
    --xh-action-fg-rest: currentColor;
    --xh-action-fg-hover: currentColor;
    --xh-action-fg-pressed: currentColor;
    --xh-action-fg-focus-visible: currentColor;
    --xh-action-fg-disabled: currentColor;
    --xh-action-border-rest: transparent;
    --xh-action-border-hover: transparent;
    --xh-action-border-pressed: transparent;
    --xh-action-border-focus-visible: transparent;
    --xh-action-border-disabled: transparent;
    --xh-action-radius: var(--xh-image-viewer-overlay-radius, var(--xh-_action-profile-radius));
    --xh-icon-size: var(--xh-image-viewer-icon-size, var(--xh-_action-profile-glyph-size));

    position: absolute;
    z-index: 1;
  }

  [data-scope='image-viewer'][data-part='prev-trigger'] {
    inset-inline-start: max(var(--xh-space-6), env(safe-area-inset-left), env(safe-area-inset-right));
    inset-block-start: 50%;
    translate: 0 -50%;
  }

  [data-scope='image-viewer'][data-part='next-trigger'] {
    inset-inline-end: max(var(--xh-space-6), env(safe-area-inset-left), env(safe-area-inset-right));
    inset-block-start: 50%;
    translate: 0 -50%;
  }

  /* 右上角的关闭钮：接 Action Control icon 档 lg（40px，触控靶走 lg），圆角走控件档；面与翻页钮同一层深色 chrome */
  [data-scope='image-viewer'][data-part='close-trigger'] {
    --xh-action-bg-rest: var(--xh-_image-viewer-chrome-bg);
    --xh-action-bg-hover: var(--xh-image-viewer-close-bg-hover, var(--xh-_image-viewer-chrome-bg-hover));
    --xh-action-bg-pressed: var(--xh-image-viewer-close-bg-active, var(--xh-_image-viewer-chrome-bg-active));
    --xh-action-bg-focus-visible: var(--xh-_image-viewer-chrome-bg);
    --xh-action-bg-disabled: var(--xh-_image-viewer-chrome-bg);
    /* 看图时整块 chrome 盖住页面，叉的颜色随那层继承；使用者要单独换叉的颜色走这支槽 */
    --xh-action-fg-rest: var(--xh-image-viewer-close-fg, currentColor);
    --xh-action-fg-hover: var(--xh-image-viewer-close-fg, currentColor);
    --xh-action-fg-pressed: var(--xh-image-viewer-close-fg, currentColor);
    --xh-action-fg-focus-visible: var(--xh-image-viewer-close-fg, currentColor);
    --xh-action-fg-disabled: var(--xh-image-viewer-close-fg, currentColor);
    --xh-action-border-rest: transparent;
    --xh-action-border-hover: transparent;
    --xh-action-border-pressed: transparent;
    --xh-action-border-focus-visible: transparent;
    --xh-action-border-disabled: transparent;
    --xh-action-radius: var(--xh-image-viewer-close-radius, var(--xh-shape-control));
    --xh-action-visual-size: var(--xh-image-viewer-close-size, var(--xh-_action-profile-visual-size));
    --xh-icon-size: var(--xh-image-viewer-icon-size, var(--xh-_action-profile-glyph-size));

    position: absolute;
    z-index: 1;
    inset-block-start: max(var(--xh-space-6), env(safe-area-inset-top));
    inset-inline-end: max(var(--xh-space-6), env(safe-area-inset-left), env(safe-area-inset-right));
  }

  /* 三颗钮的面是一层深色纱，纱底下是使用者的图片，环色算不出稳定的取值。
     content 把前景钉死在浅字上、三颗钮的前景随它继承，环取 currentColor 即是那支浅字，
     不随图片内容也不随主题翻 */
  [data-scope='image-viewer'][data-part='close-trigger']:focus-visible,
  [data-scope='image-viewer'][data-part='prev-trigger']:focus-visible,
  [data-scope='image-viewer'][data-part='next-trigger']:focus-visible {
    --xh-action-ring-color-focus-visible: currentColor;
  }

  [data-scope='image-viewer'][data-part='close-trigger'][hidden] {
    display: none;
  }

  [data-scope='image-viewer'] button[data-part]:disabled {
    opacity: var(--xh-state-disabled-opacity);
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中 */
  [data-scope='image-viewer'][data-part='zoom-in-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-zoom-in) center / contain no-repeat;
    mask: var(--xh-glyph-mark-zoom-in) center / contain no-repeat;
  }

  [data-scope='image-viewer'][data-part='zoom-out-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-zoom-out) center / contain no-repeat;
    mask: var(--xh-glyph-mark-zoom-out) center / contain no-repeat;
  }

  [data-scope='image-viewer'][data-part='rotate-left-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-rotate-left) center / contain no-repeat;
    mask: var(--xh-glyph-mark-rotate-left) center / contain no-repeat;
  }

  [data-scope='image-viewer'][data-part='rotate-right-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-rotate-right) center / contain no-repeat;
    mask: var(--xh-glyph-mark-rotate-right) center / contain no-repeat;
  }

  [data-scope='image-viewer'][data-part='flip-horizontal-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-flip-horizontal) center / contain no-repeat;
    mask: var(--xh-glyph-mark-flip-horizontal) center / contain no-repeat;
  }

  [data-scope='image-viewer'][data-part='flip-vertical-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-flip-vertical) center / contain no-repeat;
    mask: var(--xh-glyph-mark-flip-vertical) center / contain no-repeat;
  }

  [data-scope='image-viewer'][data-part='prev-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-left) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-left) center / contain no-repeat;
  }

  [data-scope='image-viewer'][data-part='next-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
  }

  [data-scope='image-viewer'][data-part='close-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='image-viewer'][data-part='positioner'][hidden],
  [data-scope='image-viewer'][data-part='viewport'][hidden],
  [data-scope='image-viewer'][data-part='toolbar'][hidden],
  [data-scope='image-viewer'][data-part='prev-trigger'][hidden],
  [data-scope='image-viewer'][data-part='next-trigger'][hidden] {
    display: none;
  }

  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。 */
    [data-scope='image-viewer'][data-part='backdrop'],
    [data-scope='image-viewer'][data-part='positioner'] {
      display: none;
    }
  }
}

/* styles/listbox.css */
/* 定义 listbox 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='listbox'] {
    --xh-listbox-skin: 1;
  }

  [data-scope='listbox'][data-part='root'] {
    /* 条目外的字形（空态 / 在途占位里作者塞的图标）按档取尺，缺省 md；条目内的字形由家族随
       data-xh-collection-size 下发。列表框自绘的状态字形（行尾对号所在的标记盒与盒里的勾）不读这支：
       它们是指示符，走 --xh-control-indicator-* 一族——标记盒在自己身上把 --xh-icon-size 改接到盒的尺 */
    --xh-icon-size: var(--xh-listbox-icon-size, var(--xh-glyph-size-md));
    /* 定高小列表的自绘条挂在根上：根是条子的定位盒，轨道底色关掉才不会在列表右缘糊出一条灰带 */
    --xh-scrollbar-track-bg: transparent;

    /* 尺寸档只换这四个私有槽，条目、分组标题与空态占位都从 root 继承它们，
       换档不必给每个部件各写一条选择器 */
    --xh-_listbox-item-py: var(--xh-list-option-py-md);
    --xh-_listbox-item-px: var(--xh-control-px-md);
    --xh-_listbox-gap: var(--xh-control-gap-md);
    --xh-_listbox-font-size: var(--xh-control-font-md);

    /* 强调色随语气走，只落在勾选标记上；没写 data-tone 时退回品牌色 */
    --xh-_listbox-accent: var(--xh-_tone, var(--xh-fg-brand));

    position: relative;
    display: flex;
    flex-direction: column;
    gap: var(--xh-listbox-gap, var(--xh-space-2));
  }

  [data-scope='listbox'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里 */
  [data-scope='listbox'][data-part='root'][data-size='sm'] {
    --xh-icon-size: var(--xh-listbox-icon-size, var(--xh-glyph-size-sm));
    --xh-_listbox-item-py: var(--xh-list-option-py-sm);
    --xh-_listbox-item-px: var(--xh-control-px-sm);
    --xh-_listbox-gap: var(--xh-control-gap-sm);
    --xh-_listbox-font-size: var(--xh-control-font-sm);
  }

  [data-scope='listbox'][data-part='root'][data-size='lg'] {
    --xh-icon-size: var(--xh-listbox-icon-size, var(--xh-glyph-size-lg));
    --xh-_listbox-item-py: var(--xh-list-option-py-lg);
    --xh-_listbox-item-px: var(--xh-control-px-lg);
    --xh-_listbox-gap: var(--xh-control-gap-lg);
    --xh-_listbox-font-size: var(--xh-control-font-lg);
  }

  /* 校验失败：整块列表框换成错误描边，与其余表单控件同一套表达 */
  [data-scope='listbox'][data-part='content'][data-invalid] {
    border-color: var(--xh-listbox-content-border-invalid, var(--xh-border-invalid));
  }

  /* 只读改不动选中值，但不是禁用：颜色照常，只把"可点"这个暗示收回来。
     光标由家族按态解算，这里在各态的槽上统一收回；禁用项的 not-allowed 由家族按 aria-disabled 给，不在此列 */
  [data-scope='listbox'][data-part='root'][data-readonly]
    [data-scope='listbox'][data-part='item']:not([data-disabled]) {
    --xh-collection-cursor-rest: default;
    --xh-collection-cursor-hover: default;
    --xh-collection-cursor-keyboard-highlight: default;
    --xh-collection-cursor-pressed: default;
    --xh-collection-cursor-selected: default;
    --xh-collection-cursor-selected-hover: default;
    --xh-collection-cursor-selected-highlight: default;
    --xh-collection-cursor-selected-pressed: default;
  }

  [data-scope='listbox'][data-part='label'] {
    color: var(--xh-listbox-label-fg, var(--xh-fg-muted));
    font-size: var(--xh-listbox-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-listbox-label-font-weight, var(--xh-text-label-weight));
    line-height: var(--xh-leading-none);
  }

  /* 整组禁用会把 data-disabled 一路打到 label / content / group 上，各处观感保持一致 */
  [data-scope='listbox'][data-part='label'][data-disabled] {
    color: var(--xh-fg-subtle);
  }

  /* 常驻列表不是浮层：容器留边框与底色，但不投影、不脱离文档流，
     因此这里既不写 position 也不写 z-index，滚动发生在容器自身 */
  [data-scope='listbox'][data-part='content'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-listbox-content-gap, var(--xh-list-option-gap));
    max-block-size: var(--xh-listbox-content-max-h, var(--xh-viewport-h-md));
    padding-block: var(--xh-listbox-content-py, var(--xh-space-1));
    padding-inline: var(--xh-listbox-content-px, var(--xh-space-1));
    border: var(--xh-stroke-thin) solid var(--xh-listbox-content-border, var(--xh-border-default));
    border-radius: var(--xh-listbox-content-radius, var(--xh-shape-surface));
    background: var(--xh-listbox-content-bg, var(--xh-bg-surface));
    color: var(--xh-listbox-content-fg, var(--xh-fg-default));
    /* 两轴一起给：条目文字用省略号收口，正常不会横向溢出，
       但作者塞进宽内容时至少还够得着，而不是被裁掉 */
    overflow: auto;
  }

  /* display 会盖掉 hidden 属性的 UA 规则，作者手动收起时要显式让位 */
  [data-scope='listbox'][data-part='content'][hidden] {
    display: none;
  }

  /* 手写结构按真正的条目判断，空白文本与分组标题都不算候选。
     只排除 content 内部的 hidden 祖先；外层浮层退场时不改变本列表的几何。
     禁用条目仍是有效内容，不参与此处排除。 */
  [data-scope='listbox'][data-part='content']:not(:has(
    [data-scope='listbox'][data-part='item']:not([hidden]):not([data-scope='listbox'][data-part='content'] [hidden] *)
  )),
  [data-scope='listbox'][data-part='group']:not(:has(
    [data-scope='listbox'][data-part='item']:not([hidden]):not([data-scope='listbox'][data-part='content'] [hidden] *)
  )) {
    display: none;
  }

  /* 横向列表沿主轴排，此时高度由内容决定，再压最大高度只会白留一条滚动条 */
  [data-scope='listbox'][data-part='content'][data-orientation='horizontal'] {
    flex-direction: row;
    align-items: center;
    max-block-size: none;
  }

  /* 焦点在列表外时容器自己进 Tab 序列兜底，落焦不画环：高亮永远长在条目上 */
  [data-scope='listbox'][data-part='content']:focus-visible {
    outline: none;
  }

  [data-scope='listbox'][data-part='group'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-listbox-group-gap, var(--xh-list-option-gap));
  }

  [data-scope='listbox'][data-part='group'][hidden] {
    display: none;
  }

  /* 只在两个有可见条目的分组之间留白；已收起的空组不能把首组额外向下推。 */
  [data-scope='listbox'][data-part='group']:has(
    [data-scope='listbox'][data-part='item']:not([hidden]):not([data-scope='listbox'][data-part='content'] [hidden] *)
  )
    ~ [data-scope='listbox'][data-part='group']:has(
      [data-scope='listbox'][data-part='item']:not([hidden]):not([data-scope='listbox'][data-part='content'] [hidden] *)
    ) {
    margin-block-start: var(--xh-listbox-group-spacing, var(--xh-space-1_5));
  }

  /* 分组标题不是选项、进不了导航，画成小号次要文字，
     内缩与条目对齐（同一个 padding-inline），标题与条目文字才在一条竖线上 */
  [data-scope='listbox'][data-part='group-label'] {
    display: block;
    padding-block: var(--xh-listbox-group-label-py, var(--xh-space-1));
    padding-inline: var(--xh-listbox-group-label-px, var(--xh-_listbox-item-px));
    color: var(--xh-listbox-group-label-fg, var(--xh-fg-subtle));
    font-size: var(--xh-listbox-group-label-font-size, var(--xh-text-caption-size));
    font-weight: var(--xh-listbox-group-label-font-weight, var(--xh-font-weight-medium));
    line-height: var(--xh-leading-none);
    user-select: none;
  }

  [data-scope='listbox'][data-part='group-label'][hidden] {
    display: none;
  }

  [data-scope='listbox'][data-part='group-label'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 空态占位：待在 root 里、content 的兄弟（列表框只许拥有 option 与 group）。
     它只画作者提供的居中文字；零候选的 content 自身收起，不再留下空描边或留白。 */
  [data-scope='listbox'][data-part='empty'] {
    display: block;
    padding-block: var(--xh-listbox-empty-py, var(--xh-space-3));
    padding-inline: var(--xh-listbox-empty-px, var(--xh-_listbox-item-px));
    color: var(--xh-listbox-empty-fg, var(--xh-fg-subtle));
    font-size: var(--xh-listbox-empty-font-size, var(--xh-_listbox-font-size));
    line-height: var(--xh-leading-none);
    text-align: center;
  }

  /* 上面给了 display，UA 的 [hidden]{display:none} 已被盖掉，这里补回来 */
  [data-scope='listbox'][data-part='empty'][hidden] {
    display: none;
  }

  [data-scope='listbox'][data-part='empty'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 在途占位：与空态占位同一个位置、同一副观感，两者不同屏 */
  [data-scope='listbox'][data-part='loading'] {
    display: block;
    padding-block: var(--xh-listbox-loading-py, var(--xh-space-3));
    padding-inline: var(--xh-listbox-loading-px, var(--xh-_listbox-item-px));
    color: var(--xh-listbox-loading-fg, var(--xh-fg-subtle));
    font-size: var(--xh-listbox-loading-font-size, var(--xh-_listbox-font-size));
    line-height: var(--xh-leading-none);
    text-align: center;
  }

  [data-scope='listbox'][data-part='loading'][hidden] {
    display: none;
  }

  /* 取下一页的按钮：铺满一行摆在列表尾——铺满一行的独立动作条目，接 Action Control 的 row 档、
     ghost 形态：宽度由容器给、高度随内容、按下只换面不缩放；盒几何、悬停 / 按下 / 禁用面、
     焦点环与粗指针热区全由家族给，白底承载 hover 100 → pressed 200。
     这里只把使用者槽映射到桥接槽并把文案居中：它是一行里唯一的东西，靠起始缘会像一条没对齐的条目 */
  [data-scope='listbox'][data-part='load-more-trigger'] {
    --xh-action-gap: var(--xh-listbox-load-more-trigger-gap, var(--xh-_listbox-gap));
    --xh-action-padding-block: var(--xh-listbox-load-more-trigger-py, var(--xh-_listbox-item-py));
    --xh-action-padding-inline: var(--xh-listbox-load-more-trigger-px, var(--xh-_listbox-item-px));
    --xh-action-radius: var(--xh-listbox-load-more-trigger-radius, var(--xh-shape-control));
    --xh-action-bg-hover: var(--xh-listbox-load-more-trigger-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-fg-rest: var(--xh-listbox-load-more-trigger-fg, var(--xh-_tone-fg, var(--xh-fg-brand-strong)));
    --xh-action-fg-hover: var(--xh-listbox-load-more-trigger-fg, var(--xh-_tone-fg, var(--xh-fg-brand-strong)));
    --xh-action-fg-pressed: var(--xh-listbox-load-more-trigger-fg, var(--xh-_tone-fg, var(--xh-fg-brand-strong)));
    --xh-action-font-size: var(--xh-listbox-load-more-trigger-font-size, var(--xh-_listbox-font-size));

    justify-content: center;
    text-align: center;
    /* row 档允许换行、高度随内容，折行的文案走正文行高 */
    line-height: var(--xh-leading-normal);
  }

  [data-scope='listbox'][data-part='load-more-trigger'][hidden] {
    display: none;
  }

  /* 条目走 Collection Item 的 overlay 语境，与树选择同一种选中读法：网格、尺寸档、悬停 / 高亮 / 按下面
     （白底承载 hover 100 → pressed 200）由家族给，选中不换面、不换字色，只在行尾亮对号，
     选中叠悬停 / 按下沿用同一条阶梯；禁用面（字色降级、not-allowed、不换面）也归家族。
     这里只把公开槽映射到桥接槽，不复制任何状态选择器。
     列表框坐在 surface 白底上，前景走 fg-default 而不是浮层的 frosted 前景 */
  [data-scope='listbox'][data-part='item'] {
    --xh-collection-block-padding: var(--xh-listbox-item-py, var(--xh-_listbox-item-py));
    --xh-collection-inline-padding: var(--xh-listbox-item-px, var(--xh-_listbox-item-px));
    --xh-collection-gap: var(--xh-listbox-item-gap, var(--xh-_listbox-gap));
    --xh-collection-font-size: var(--xh-listbox-item-font-size, var(--xh-_listbox-font-size));
    --xh-collection-radius: var(--xh-listbox-item-radius, var(--xh-shape-control));
    /* 作者的图标尺槽经桥接槽下发到条目，家族缺省按 data-xh-collection-size 取档 */
    --xh-collection-glyph-size: var(--xh-listbox-icon-size, var(--xh-_collection-glyph-size));
    --xh-collection-fg-rest: var(--xh-listbox-item-fg, var(--xh-fg-default));
    --xh-collection-fg-hover: var(--xh-listbox-item-fg, var(--xh-fg-default));
    --xh-collection-fg-keyboard-highlight: var(--xh-listbox-item-fg, var(--xh-fg-default));
    --xh-collection-fg-pressed: var(--xh-listbox-item-fg, var(--xh-fg-default));
    --xh-collection-fg-selected: var(--xh-listbox-item-fg-selected, var(--xh-listbox-item-fg, var(--xh-fg-default)));
    --xh-collection-fg-selected-hover: var(--xh-listbox-item-fg-selected, var(--xh-listbox-item-fg, var(--xh-fg-default)));
    --xh-collection-fg-selected-highlight: var(--xh-listbox-item-fg-selected, var(--xh-listbox-item-fg, var(--xh-fg-default)));
    --xh-collection-fg-selected-pressed: var(--xh-listbox-item-fg-selected, var(--xh-listbox-item-fg, var(--xh-fg-default)));
    --xh-collection-font-weight-selected: var(--xh-listbox-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-font-weight-selected-hover: var(--xh-listbox-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-font-weight-selected-highlight: var(--xh-listbox-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-font-weight-selected-pressed: var(--xh-listbox-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-bg-hover: var(--xh-listbox-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-keyboard-highlight: var(--xh-listbox-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-pressed: var(--xh-listbox-item-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-bg-selected-hover: var(--xh-listbox-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-selected-highlight: var(--xh-listbox-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-selected-pressed: var(--xh-listbox-item-bg-pressed, var(--xh-bg-subtle-hover));
    /* data-highlighted 跟的是连接层记的焦点条目（指针点选也会落焦）：只换面，焦点环在 :focus-visible 下再接回 */
    --xh-collection-outline-keyboard-highlight: transparent;
    --xh-collection-outline-selected-highlight: transparent;
    /* 对号随语气走：没写 data-tone 时退回品牌色；槽按本部件取名（item-check-fg），标记部件的旧槽留在兜底位 */
    --xh-collection-indicator-fg-rest: var(--xh-listbox-item-check-fg, var(--xh-listbox-item-indicator-fg, var(--xh-_listbox-accent)));
    --xh-collection-indicator-fg-checked: var(--xh-listbox-item-check-fg, var(--xh-listbox-item-indicator-fg, var(--xh-_listbox-accent)));
    --xh-collection-indicator-fg-selected: var(--xh-listbox-item-check-fg, var(--xh-listbox-item-indicator-fg, var(--xh-_listbox-accent)));
    --xh-collection-indicator-fg-selected-hover: var(--xh-listbox-item-check-fg, var(--xh-listbox-item-indicator-fg, var(--xh-_listbox-accent)));
    --xh-collection-indicator-fg-selected-highlight: var(--xh-listbox-item-check-fg, var(--xh-listbox-item-indicator-fg, var(--xh-_listbox-accent)));
    --xh-collection-indicator-fg-selected-pressed: var(--xh-listbox-item-check-fg, var(--xh-listbox-item-indicator-fg, var(--xh-_listbox-accent)));

    /* 行高留出文字的上下伸展空间，行内那层 overflow:hidden 才不会把字削掉 */
    line-height: var(--xh-listbox-item-leading, var(--xh-leading-normal));
    white-space: nowrap;
    user-select: none;
  }

  /* 家族给了 display，UA 的 [hidden]{display:none} 已被盖掉：条目可以按需收起（过滤掉的选项） */
  [data-scope='listbox'][data-part='item'][hidden] {
    display: none;
  }

  /* 键盘焦点出现时环才接回并立即到位，不压在背景过渡的中间帧上 */
  [data-scope='listbox'][data-part='item']:focus-visible:not(:hover) {
    --xh-collection-outline-keyboard-highlight: var(--xh-ring-focus);
    --xh-collection-outline-selected-highlight: var(--xh-ring-focus);

    transition: none;
  }

  [data-scope='listbox'][data-part='item-text'] {
    /* 网格子项默认最小尺寸是内容尺寸，不归零则长文本把行撑破、省略号轮不上 */
    min-inline-size: 0;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  /* 勾选标记落在家族网格行尾的 indicator 列（page 与 overlay 同位）；显隐与颜色由家族按选中态给，
     未选中时占位不塌，切换选中不引起行宽抖动。
     盒与盒里的勾是指示符：盒按指示符档取尺，并在自己身上把 --xh-icon-size 改接到盒的尺，皮肤画的
     兜底勾与作者塞进盒里的 XhIcon 读同一把尺、与盒同边长（对号不是勾选格，不取 × 0.75，与 Menu 族同口径）；
     不读家族按档下发到行的 --xh-icon-size——那支只管作者放进条目里的图标，按图标档取的 20px 比 16 / 14 的指示符档大一圈 */
  [data-scope='listbox'][data-part='item-indicator'] {
    --xh-icon-size: var(--xh-listbox-item-indicator-size, var(--xh-control-indicator-size));

    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-listbox-item-indicator-size, var(--xh-control-indicator-size));
    block-size: var(--xh-listbox-item-indicator-size, var(--xh-control-indicator-size));
  }

  [data-scope='listbox'][data-part='item-indicator'][hidden] {
    display: none;
  }

  /* 没写内容就由皮肤画勾；作者往部件里塞了自己的图形，这条规则即不命中。
     尺寸读标记盒自己改接过的 --xh-icon-size：与盒同边长，随指示符档换档（见上面标记盒那块） */
  [data-scope='listbox'][data-part='item-indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    mask: var(--xh-glyph-mark-check) center / contain no-repeat;
  }

  @media print {
    /* 打印默认丢底色，而对号是遮罩出来的一块底色：行本就不换面，丢了它选中在纸上就没了踪影 */
    [data-scope='listbox'][data-part='item-indicator'] {
      print-color-adjust: exact;
    }
  }
}

/* styles/loading-bar.css */
/* 定义 loading bar 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='loading-bar'] {
    --xh-loading-bar-skin: 1;
  }

  /*
   * 贴在视口顶边的一条细带。厚度那条轴（block-size）由连接层写进内联样式——
   * height 这个 prop 的缺省值在 connect 里收口，这里再声明一次只会被内联盖掉，
   * 还会让人误以为厚度归样式层管。
   *
   * fixed 认的是视口，祖先上一旦出现 transform / filter / backdrop-filter / contain
   * 就会把包含块抢走，条子立刻贴错位置——覆盖钩子里别加这几个属性。
   */
  [data-scope='loading-bar'][data-part='root'] {
    position: fixed;
    /* 顶到视口上沿的那一条：刘海或状态栏压住的那一段由系统给出，不让位就整条藏在下面。
       桌面上 env() 恒为 0，条子照旧贴着上沿。 */
    inset-block-start: env(safe-area-inset-top);
    inset-inline: 0;
    z-index: var(--xh-loading-bar-layer, var(--xh-layer-sticky));

    /* 它只报进度，不吃点击：盖在顶栏上的一条带子若拦住指针，页面顶部就点不动了 */
    pointer-events: none;
    opacity: 1;
    transition: opacity var(--xh-loading-bar-fade, var(--xh-motion-duration-exit)) var(--xh-motion-ease-exit);
  }

  /* 只要声明过任何 display，就盖掉了 UA 的 [hidden]{display:none}；
     这里虽然没声明，作者层随手给一条 display 也会盖掉，所以补齐这条兜住收起态。
     连接层只会给 root 写 hidden，track / range 不需要同样的兜底 */
  [data-scope='loading-bar'][data-part='root'][hidden] {
    display: none;
  }

  /* 冲到 100 之后进入淡出：机器会在淡出窗口走完之前一直停在 finishing，这段过渡才有时间跑完。
     窗口（machine 的 LOADING_BAR_FADE_DURATION，200ms）比过渡本身（motion-duration-exit，120ms）
     宽出一截是有意的余量；两者不是同一个数，改窗口时只要保证它仍不短于过渡 */
  [data-scope='loading-bar'][data-part='root'][data-state='finishing'] {
    opacity: 0;
  }

  /* 背景槽。默认透明：顶部加载条通常直接压在页面顶边上，一条贯穿整屏的浅色底
     在视觉上等于凭空多出一道分隔线 */
  [data-scope='loading-bar'][data-part='track'] {
    overflow: hidden;
    inline-size: 100%;
    block-size: 100%;
    background: var(--xh-loading-bar-track, transparent);
  }

  /*
   * 进度段。铺满轨道，按连接层交出的比例往行首平移、由轨道裁掉：推进只走合成，
   * 不重排也不重绘；末端的亮边跟着它一起走。背景色不走内联：要别的颜色改 --xh-loading-bar-range 这个槽，或者换语气。
   *
   * 语气取装饰档 --xh-_tone-soft：那一档压在画布上够 3:1，细带才看得出来。
   * 槽位由 root 上的 data-tone 声明，继承下来。
   * 没写 data-tone 时该槽没被声明，退回原来的品牌色。
   */
  [data-scope='loading-bar'][data-part='range'] {
    inline-size: 100%;
    block-size: 100%;
    background: var(--xh-loading-bar-range, var(--xh-_tone-soft, var(--xh-bg-brand)));
    translate: calc((var(--xh-_loading-bar-value, 0) - 1) * 100%) 0;
    transition: translate var(--xh-loading-bar-speed, var(--xh-motion-duration-move)) var(--xh-motion-ease-continuous);
  }

  /* translate 只认物理方向：RTL 下行首在右边，平移方向翻转 */
  [data-scope='loading-bar'][data-part='range']:dir(rtl) {
    translate: calc((1 - var(--xh-_loading-bar-value, 0)) * 100%) 0;
  }

  /* 渲染了亮边才把进度段变成定位面：亮边贴在它的末端 */
  [data-scope='loading-bar'][data-part='range']:has([data-part='peg']) {
    position: relative;
  }

  /*
   * 进度段末端那道亮边。它把「条子在往前走」这件事画出来：只有一条渐宽的色带时，
   * 200ms 一跳的推进读起来像卡顿。
   * 颜色接进度段自己的那一支，宽度与厚度各留一个槽。
   */
  [data-scope='loading-bar'][data-part='peg'] {
    position: absolute;
    inset-block: 0;
    inset-inline-end: 0;
    inline-size: var(--xh-loading-bar-peg-w, var(--xh-space-8));
    /* 两端渐隐、中间最亮：亮斑对称，文字方向翻过来也不必再配一次 */
    background: linear-gradient(
      90deg,
      transparent,
      var(--xh-loading-bar-peg-fg, var(--xh-loading-bar-range, var(--xh-_tone-soft, var(--xh-bg-brand)))),
      transparent
    );
  }

  /* 条子还没起步时亮边一起收着：进度为 0 的末端不该先亮出一道边 */
  [data-scope='loading-bar'][data-part='peg'][data-state='idle'] {
    opacity: 0;
  }

  [data-scope='loading-bar'][data-part='peg'][hidden] {
    display: none;
  }

  /* 减少动效：作者写进两个时长槽的值不作数，退回令牌——进度段的平移随几何时长立刻到位，
     收尾的淡出保留减弱档的那一小段。一条按 200ms 一拍持续推进的带子正是最容易引发不适的那种动效。
     两条规则是同一件事的两个触发条件：系统偏好与作者打的 data-motion */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='loading-bar'][data-part='root'] {
      transition-duration: var(--xh-motion-duration-exit);
    }

    [data-scope='loading-bar'][data-part='range'] {
      transition-duration: var(--xh-motion-duration-move);
    }
  }

  :where([data-motion='reduce']) [data-scope='loading-bar'][data-part='root'] {
    transition-duration: var(--xh-motion-duration-exit);
  }

  :where([data-motion='reduce']) [data-scope='loading-bar'][data-part='range'] {
    transition-duration: var(--xh-motion-duration-move);
  }

  @media print {
    /* 打印：加载进度条画的是「正在等」，落到纸上是一条没有含义的色带。 */
    [data-scope='loading-bar'][data-part='root'] {
      display: none;
    }
  }
}

/* styles/menu.css */
/* 定义 menu 样式。 */

/* 共享关键帧由 family/motion.css 提供，条目走 Collection Item 家族；本皮肤 @import 它们，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='menu'] {
    --xh-menu-skin: 1;
  }

  /* 坐标由定位引擎写进 style（inset-inline-start / inset-block-start），这里只定位模式与层级 */
  [data-scope='menu'][data-part='positioner'] {
    /* 落定那一侧的可用高度，由定位引擎经内联自定义属性写进来，content 继承它限高；
       引擎没算（尚未落位 / 无引擎）时不额外限高 */
    --xh-_menu-available-h: 100vh;
    /* 落定那一侧的可用宽度，同样由定位引擎经内联自定义属性写进来，行内轴据此夹取；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时退到视口宽 */
    --xh-_menu-available-w: 100vw;
    /* Web Components 的子菜单仍在父层 DOM 内，先清零以截断父 positioner 的方向继承。 */
    --xh-_overlay-enter-up: 0;
    --xh-_overlay-enter-down: 0;
    --xh-_overlay-enter-left: 0;
    --xh-_overlay-enter-right: 0;

    /* 条目列表的自绘条浮在内容之上：轨道不上底色，实色轨道会在菜单右缘糊一条竖灰带 */
    --xh-scrollbar-track-bg: transparent;

    position: fixed;
    z-index: var(--xh-menu-layer, var(--xh-_layer, var(--xh-layer-popover)));
    /* 空壳不吃指针，交互只发生在 content 上 */
    pointer-events: none;
  }

  /* 锚点被滚出可视区：整个浮层随之收起 */
  [data-scope='menu'][data-part='positioner'][data-hidden] {
    visibility: hidden;
  }

  /* 菜单从锚点一侧短移入；物理 placement 与定位引擎同一套，不随书写方向翻。 */
  [data-scope='menu'][data-part='positioner'][data-placement^='top'] {
    --xh-_overlay-enter-down: 1;
  }

  [data-scope='menu'][data-part='positioner'][data-placement^='bottom'] {
    --xh-_overlay-enter-up: 1;
  }

  [data-scope='menu'][data-part='positioner'][data-placement^='left'] {
    --xh-_overlay-enter-right: 1;
  }

  [data-scope='menu'][data-part='positioner'][data-placement^='right'] {
    --xh-_overlay-enter-left: 1;
  }

  /* 触发器的长相归作者，皮肤只表达展开态：展开着的那一张是打开路径，落与家族 hover 同档的中性面——
     打开中不是选中，不用品牌色、不接语气；哪一张开着由浮层本身说明。不加粗：加粗会推挤相邻内容 */
  [data-scope='menu'][data-part='trigger']:not([data-disabled])[data-state='open'] {
    background: var(--xh-menu-trigger-bg-active, var(--xh-bg-subtle));
  }

  [data-scope='menu'][data-part='content'] {
    /* 条目外的字形（分组标题等）按档取尺，缺省 md，随 data-size 换档；条目里作者放的图标由家族随
       data-xh-collection-size 下发。菜单自绘的状态字形（标记位的盒、子菜单的展开 chevron）不读这支：
       它们是指示符，走 --xh-control-indicator-* 一族——标记位在自己身上把 --xh-icon-size 改接到盒的尺，
       子菜单箭头走 --xh-menu-submenu-indicator-size */
    --xh-icon-size: var(--xh-menu-icon-size, var(--xh-glyph-size-md));

    /* 尺寸档只换这四个私有槽，条目从 content 继承它们，换档不必给每个部件各写一条选择器。
       菜单没有 root 部件（浮层树的最外层就是 content），三轴属性都落在这里 */
    --xh-_menu-item-py: var(--xh-list-option-py-md);
    --xh-_menu-item-px: var(--xh-control-px-md);
    --xh-_menu-item-gap: var(--xh-control-gap-md);
    --xh-_menu-font-size: var(--xh-control-font-md);

    position: relative;
    display: flex;
    flex-direction: column;
    gap: var(--xh-menu-content-gap, var(--xh-list-option-gap));
    min-inline-size: var(--xh-menu-min-w, var(--xh-overlay-menu-min-w));
    /* 静态档与落位后的可用宽度取小：窄视口下面板伸出去，最右侧的内容就点不到了 */
    max-inline-size: min(var(--xh-menu-max-w, var(--xh-overlay-max-w)), var(--xh-_menu-available-w));
    /* 两道上限取更小的那道：自己的高度上限，以及落定那一侧真正剩下的空间。
       列表族的 16rem 对命令菜单偏矮，这里另给一档 */
    max-block-size: min(var(--xh-menu-max-h, var(--xh-overlay-menu-max-h)), var(--xh-_menu-available-h));
    padding-block: var(--xh-menu-content-py, var(--xh-surface-pad-xs));
    padding-inline: var(--xh-menu-content-px, var(--xh-surface-pad-xs));
    border: var(--xh-stroke-thin) solid var(--xh-menu-border, var(--xh-material-frosted-border));
    border-radius: var(--xh-menu-content-radius, var(--xh-shape-overlay));
    background: var(--xh-menu-content-bg, var(--xh-material-frosted-bg));
    color: var(--xh-menu-content-fg, var(--xh-material-frosted-fg));
    box-shadow: var(--xh-menu-content-shadow, var(--xh-material-frosted-shadow));
    -webkit-backdrop-filter: var(--xh-menu-backdrop, var(--xh-material-frosted-backdrop));
    backdrop-filter: var(--xh-menu-backdrop, var(--xh-material-frosted-backdrop));
    /* 条目超过上限就在菜单内部滚。条目的焦点环是内收的，滚动容器裁在内边距缘上，环切不着。
       浮层滚动面：到底后不把滚动链穿透给页面 */
    overflow-y: auto;
    overscroll-behavior: contain;
    pointer-events: auto;
  }

  /* 顶光是独立装饰层，不替换真实边框；高对比/强制色归零后四边轮廓仍完整。 */
  [data-scope='menu'][data-part='content']::before {
    content: '';
    position: absolute;
    inset-block-start: 0;
    inset-inline: 0;
    block-size: var(--xh-stroke-thin);
    border-radius: inherit;
    background: var(--xh-menu-highlight, var(--xh-material-frosted-highlight));
    pointer-events: none;
  }

  /* 这里刻意没有 [data-part='content'][hidden] { display: none }，与 dialog 一致：
     收起态连接层会给 content 打 hidden，而上面那条 display 正是要盖掉 UA 的
     [hidden]{display:none}——退场动画得先能播。presence 读的是 content 的 animationName，
     真正的收起由宿主在退场结束后落成内联 display:none（Vue 那边直接不渲染）。
     其余声明了 display 的角色节点仍补 [hidden]，那几处没有退场动画。 */

  /* 容器只是焦点域兜底落点，落焦不画环：高亮永远长在条目上 */
  [data-scope='menu'][data-part='content']:focus-visible {
    outline: none;
  }

  [data-scope='menu'][data-part='content'][data-state='open'] {
    animation: xh-overlay-slide-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 退场：收起那一帧 hidden 由退场闸门押后，这里才播得出来。forwards 把末态钉住，
     免得动画结束到真收起之间闪一下原样 */
  [data-scope='menu'][data-part='content'][data-state='closed'] {
    will-change: opacity, translate;
    animation: xh-overlay-slide-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* —— 尺寸 —— */
  /* 缺省档写在 content 的基础规则里。条目高度由 padding 撑出来：
     纵向走 space 档、行内内缩走 control-px 档（随密度轴），换档各挪一级 */
  [data-scope='menu'][data-part='content'][data-size='sm'] {
    --xh-icon-size: var(--xh-menu-icon-size, var(--xh-glyph-size-sm));
    --xh-_menu-item-py: var(--xh-list-option-py-sm);
    --xh-_menu-item-px: var(--xh-control-px-sm);
    --xh-_menu-item-gap: var(--xh-control-gap-sm);
    --xh-_menu-font-size: var(--xh-control-font-sm);
  }

  [data-scope='menu'][data-part='content'][data-size='lg'] {
    --xh-icon-size: var(--xh-menu-icon-size, var(--xh-glyph-size-lg));
    --xh-_menu-item-py: var(--xh-list-option-py-lg);
    --xh-_menu-item-px: var(--xh-control-px-lg);
    --xh-_menu-item-gap: var(--xh-control-gap-lg);
    --xh-_menu-font-size: var(--xh-control-font-lg);
  }

  /* 条目走 Collection Item 的 overlay 语境：悬停 / 键盘锚点（data-highlighted，白底承载 100）、按下（200）、
     子层开着的打开路径（data-in-path，与 hover 同档）与禁用面（aria-disabled）都由家族给，这里只把公开槽映射到
     桥接槽。布局保持 flex 而不用家族网格：图标、正文、快捷键按一行排布，说明另起一行靠 flex-wrap 折下去，
     子菜单箭头是行尾的伪元素；间距统一由行的 gap 给，家族按槽下发的外边距归零 */
  [data-scope='menu'][data-part='item'] {
    --xh-collection-block-padding: var(--xh-menu-item-py, var(--xh-_menu-item-py));
    --xh-collection-inline-padding: var(--xh-menu-item-px, var(--xh-_menu-item-px));
    --xh-collection-gap: 0;
    --xh-collection-font-size: var(--xh-menu-item-font-size, var(--xh-_menu-font-size));
    --xh-collection-radius: var(--xh-menu-item-radius, var(--xh-shape-control));
    --xh-collection-fg-rest: var(--xh-menu-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-hover: var(--xh-menu-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-keyboard-highlight: var(--xh-menu-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-pressed: var(--xh-menu-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-open-path: var(--xh-menu-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-bg-hover: var(--xh-menu-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-keyboard-highlight: var(--xh-menu-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-pressed: var(--xh-menu-item-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-bg-open-path: var(--xh-menu-item-bg-active, var(--xh-bg-subtle));
    /* data-highlighted 同时覆盖指针与键盘路径：指针只换面，焦点环在 :focus-visible 下再接回 */
    --xh-collection-outline-keyboard-highlight: transparent;

    display: flex;
    align-items: center;
    gap: var(--xh-menu-item-gap, var(--xh-_menu-item-gap));
    line-height: var(--xh-menu-item-leading, var(--xh-leading-normal));
    white-space: nowrap;
    user-select: none;
  }

  /* 键盘焦点出现时环才接回并立即到位，不压在背景过渡的中间帧上 */
  [data-scope='menu'][data-part='item']:focus-visible:not(:hover) {
    --xh-collection-outline-keyboard-highlight: var(--xh-ring-focus);

    transition: none;
  }

  /* 条目里的文字载体：占满剩余宽度，长文本自己收省略号 */
  [data-scope='menu'][data-part='item-text'] {
    flex: 1;
    min-inline-size: 0;
    white-space: nowrap;
    text-overflow: ellipsis;
    overflow: hidden;
  }

  [data-scope='menu'][data-part='item-text'][hidden] {
    display: none;
  }

  /* 标记位（勾选符号 / 图标）：定宽占位，切换内容不引起行宽抖动。盒是指示符：按指示符档取尺，
     与 Cascader / Select 的标记位同走 --xh-control-indicator-size，不读家族按档下发的 --xh-icon-size——
     按图标档取的 20px 会比同一行 16px 的指示符档大一圈。盒在自己身上把 --xh-icon-size 改接到盒的尺，
     作者塞进标记位的 XhIcon 与盒同尺；条目上那支只管作者直接放进条目里的图标 */
  [data-scope='menu'][data-part='item-indicator'] {
    --xh-icon-size: var(--xh-menu-item-indicator-size, var(--xh-control-indicator-size));

    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-menu-item-indicator-size, var(--xh-control-indicator-size));
    block-size: var(--xh-menu-item-indicator-size, var(--xh-control-indicator-size));
    color: var(--xh-menu-item-indicator-fg, var(--xh-_tone, var(--xh-fg-brand)));
  }

  [data-scope='menu'][data-part='item-indicator'][hidden] {
    display: none;
  }

  [data-scope='menu'][data-part='item-indicator'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 副文本另起一行：整行占满，把条目的一行内容折成两行 */
  [data-scope='menu'][data-part='item-description'] {
    flex: 1 0 100%;
    order: 2;
    min-inline-size: 0;
    color: var(--xh-menu-item-description-fg, var(--xh-material-frosted-fg-muted));
    font-size: var(--xh-menu-item-description-font-size, var(--xh-text-caption-size));
    white-space: nowrap;
    text-overflow: ellipsis;
    overflow: hidden;
  }

  [data-scope='menu'][data-part='item-description'][hidden] {
    display: none;
  }

  [data-scope='menu'][data-part='item-description'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 作者的图标、正文和快捷键按一行排布；只有说明部件另起一行。 */
  [data-scope='menu'][data-part='item']:has(> [data-scope='menu'][data-part='item-description']) {
    flex-wrap: wrap;
  }

  /* 带子菜单的条目行尾画右向小箭头：不点开也看得出还有下一级。
     箭头与作者内容同排，用自动外距推到行尾。箭头是指示符：与标记位的盒同走
     --xh-control-indicator-size，不读 --xh-icon-size——按图标档取的 20px 会比 16px 的标记位盒大一圈 */
  [data-scope='menu'][data-part='item'][aria-haspopup='menu']::after {
    content: '';
    flex: none;
    order: 1;
    margin-inline-start: auto;
    inline-size: var(--xh-menu-submenu-indicator-size, var(--xh-control-indicator-size));
    block-size: var(--xh-menu-submenu-indicator-size, var(--xh-control-indicator-size));
    background-color: var(--xh-menu-submenu-indicator-fg, var(--xh-material-frosted-fg-muted));
    -webkit-mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
  }

  /* rtl 下子菜单开在左侧，箭头跟着指向行进方向 */
  [dir='rtl'] [data-scope='menu'][data-part='item'][aria-haspopup='menu']::after {
    -webkit-mask-image: var(--xh-glyph-mark-chevron-left);
    mask-image: var(--xh-glyph-mark-chevron-left);
  }

  [data-scope='menu'][data-part='group'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-menu-group-gap, var(--xh-list-option-gap));
  }

  [data-scope='menu'][data-part='group'][hidden] {
    display: none;
  }

  /* 分组标题不是条目、进不了导航，画成小号次要文字，
     内缩与条目对齐（同一个 padding-inline），标题与条目文字才在一条竖线上 */
  [data-scope='menu'][data-part='group-label'] {
    display: block;
    padding-block: var(--xh-menu-group-label-py, var(--xh-space-1));
    padding-inline: var(--xh-menu-group-label-px, var(--xh-_menu-item-px));
    color: var(--xh-menu-group-label-fg, var(--xh-material-frosted-fg-muted));
    font-size: var(--xh-menu-group-label-font-size, var(--xh-text-caption-size));
    font-weight: var(--xh-menu-group-label-font-weight, var(--xh-font-weight-medium));
    line-height: var(--xh-leading-none);
    user-select: none;
  }

  [data-scope='menu'][data-part='group-label'][hidden] {
    display: none;
  }

  [data-scope='menu'][data-part='separator'] {
    block-size: var(--xh-menu-separator-thickness, var(--xh-stroke-thin));
    margin-block: var(--xh-menu-separator-my, var(--xh-space-0_5));
    border-radius: var(--xh-menu-separator-radius, var(--xh-shape-pill));
    background: var(--xh-menu-separator-color, var(--xh-material-frosted-separator));
  }

  /* 箭头的底色与描边色，几何在 overlay-arrow.css。
     交叉轴落点由定位引擎经内联自定义属性写进来，没给时退回居中 */
  [data-scope='menu'][data-part='arrow'] {
    --xh-_menu-arrow-x: 50%;
    --xh-_menu-arrow-y: 50%;
    --xh-_overlay-arrow-size: var(--xh-menu-arrow-size, var(--xh-overlay-arrow-size));
    --xh-_overlay-arrow-x: var(--xh-_menu-arrow-x);
    --xh-_overlay-arrow-y: var(--xh-_menu-arrow-y);

    background: var(--xh-menu-content-bg, var(--xh-material-frosted-bg));
    border: var(--xh-stroke-thin) solid var(--xh-menu-border, var(--xh-material-frosted-border));
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='menu'][data-part='item'][hidden] {
    display: none;
  }

  @media (forced-colors: active) {
    /* 分组之间那条线画的是一块纯底色，这一档里底色被统一换成 Canvas，线整条消失，
       几组条目就连成了一长串。换成前景色画回来 */
    [data-scope='menu'][data-part='separator'] {
      background: CanvasText;
    }
  }

  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。 */
    [data-scope='menu'][data-part='positioner'] {
      display: none;
    }
  }
}

/* styles/menubar.css */
/* 定义 menubar 样式。 */

/* 共享关键帧由 family/motion.css 提供，条目走 Collection Item 家族；本皮肤 @import 它们，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='menubar'] {
    --xh-menubar-skin: 1;
  }

  /* 一排 trigger。主轴跟着 data-orientation 走：菜单栏本身可以横排也可以竖排 */
  [data-scope='menubar'][data-part='root'] {
    /* 一行排不下就折行：菜单名宽度由文字决定，硬撑一行会把整条顶出容器，
       末尾几个菜单既看不见也点不到 */
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--xh-menubar-gap, var(--xh-space-1));
    padding-block: var(--xh-menubar-py, var(--xh-space-1));
    padding-inline: var(--xh-menubar-px, var(--xh-space-1));
    border-radius: var(--xh-menubar-radius, var(--xh-shape-control));
    background: var(--xh-menubar-bg, transparent);
    color: var(--xh-menubar-fg, var(--xh-fg-default));
  }

  [data-scope='menubar'][data-part='root'][hidden] {
    display: none;
  }

  [data-scope='menubar'][data-part='root'][data-orientation='vertical'] {
    flex-direction: column;
    align-items: stretch;
    flex-wrap: nowrap;
  }

  /* root 只是 roving tabindex 的兜底落点，焦点转投给 trigger 之后就不再停留，不画环 */
  [data-scope='menubar'][data-part='root']:focus-visible {
    outline: none;
  }

  [data-scope='menubar'][data-part='root'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 入口归 Collection Item 展开路径 / 打开中（nav 语境）：几何、字号与面全经家族桥接槽。静息字色取 default
     （菜单名不是次要文字，不取 nav 缺省的 muted），悬停走白底承载 hover 100，展开着的那一张由连接层投影
     data-in-path，家族给与悬停同档的中性面——打开中不是选中，不用品牌色、不接语气、不加粗；
     按下 pressed 200 只换面不缩放；禁用走 aria-disabled，家族给禁用字色与 not-allowed。
     本条 (0,2,0) 压过家族基础块 (0,1,0)，不能再写 background / color / cursor */
  [data-scope='menubar'][data-part='trigger'] {
    --xh-collection-block-padding: var(--xh-menubar-trigger-py, var(--xh-_menubar-trigger-py));
    --xh-collection-inline-padding: var(--xh-menubar-trigger-px, var(--xh-_menubar-trigger-px));
    --xh-collection-radius: var(--xh-menubar-trigger-radius, var(--xh-shape-control));
    --xh-collection-font-size: var(--xh-menubar-trigger-font-size, var(--xh-_menubar-font-size));
    --xh-collection-fg-rest: var(--xh-menubar-trigger-fg, var(--xh-fg-default));
    --xh-collection-bg-hover: var(--xh-menubar-trigger-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-open-path: var(--xh-menubar-trigger-bg-active, var(--xh-bg-subtle));
    --xh-collection-bg-pressed: var(--xh-menubar-trigger-bg-pressed, var(--xh-bg-subtle-hover));

    display: inline-flex;
    flex: none;
    align-items: center;
    gap: var(--xh-menubar-trigger-gap, var(--xh-control-gap-sm));
    border: none;
    /* 不再写 font: inherit：按钮的 UA 字体由 reset.css 抹平，这里再写一遍会把家族给的字号与字重一并盖掉。
       行高压回 none：家族基础块给条目写了 leading-normal，入口的高度只由内缩定 */
    line-height: var(--xh-leading-none);
    white-space: nowrap;
    user-select: none;
  }

  [data-scope='menubar'][data-part='trigger'][hidden] {
    display: none;
  }

  /* 坐标由定位引擎写进 style（inset-inline-start / inset-block-start），这里只定位模式与层级 */
  [data-scope='menubar'][data-part='positioner'] {
    /* 落定那一侧的可用高度，由定位引擎经内联自定义属性写进来，content 继承它限高；
       引擎没算（尚未落位 / 无引擎）时不额外限高 */
    --xh-_menubar-available-h: 100vh;
    /* 落定那一侧的可用宽度，同样由定位引擎经内联自定义属性写进来，行内轴据此夹取；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时退到视口宽 */
    --xh-_menubar-available-w: 100vw;
    /* WC 子菜单仍可能住在父 positioner 内；先截断父层方向，避免斜向继承。 */
    --xh-_overlay-enter-up: 0;
    --xh-_overlay-enter-down: 0;
    --xh-_overlay-enter-left: 0;
    --xh-_overlay-enter-right: 0;

    /* 条目列表的自绘条浮在内容之上：轨道不上底色，实色轨道会在菜单右缘糊一条竖灰带 */
    --xh-scrollbar-track-bg: transparent;

    position: fixed;
    z-index: var(--xh-menubar-layer, var(--xh-_layer, var(--xh-layer-popover)));
    /* 空壳不吃指针，交互只发生在 content 上 */
    pointer-events: none;
  }

  /* 锚点被滚出可视区：整个浮层随之收起 */
  [data-scope='menubar'][data-part='positioner'][data-hidden] {
    visibility: hidden;
  }

  /* 物理 placement 与定位引擎同口径，不随书写方向翻转。 */
  [data-scope='menubar'][data-part='positioner'][data-placement^='top'] {
    --xh-_overlay-enter-down: 1;
  }

  [data-scope='menubar'][data-part='positioner'][data-placement^='bottom'] {
    --xh-_overlay-enter-up: 1;
  }

  [data-scope='menubar'][data-part='positioner'][data-placement^='left'] {
    --xh-_overlay-enter-right: 1;
  }

  [data-scope='menubar'][data-part='positioner'][data-placement^='right'] {
    --xh-_overlay-enter-left: 1;
  }

  /* —— 尺寸 —— */
  /* 尺寸档只换这六个私有槽，换档不必给每个部件各写一条选择器。
     root 与 positioner 各起一头：trigger 从 root 继承，菜单里的条目从 positioner 继承——
     浮层搬去了 portal 落点，不再是 root 的后代。
     缺省档写在第一条：trigger 与条目的行内内缩都走 control-px 档（随密度轴）、纵向走 space 档，换档各挪一级 */
  [data-scope='menubar']:is([data-part='root'], [data-part='positioner']) {
    /* 条目外的字形（分组标题、入口）按档取尺，缺省 md，随 data-size 换档；同样声明在 positioner 上，被搬走的
       浮层才拿得到；条目里作者放的图标由家族随 data-xh-collection-size 下发。菜单栏自绘的状态字形（标记位的盒、
       盒里兜底的勾、子菜单的展开 chevron）不读这支：它们是指示符，走 --xh-control-indicator-* 一族——标记位在
       自己身上把 --xh-icon-size 改接到盒的尺，子菜单箭头走 --xh-menubar-submenu-indicator-size */
    --xh-icon-size: var(--xh-menubar-icon-size, var(--xh-glyph-size-md));

    --xh-_menubar-trigger-py: var(--xh-space-1);
    --xh-_menubar-trigger-px: var(--xh-control-px-md);
    --xh-_menubar-item-py: var(--xh-list-option-py-md);
    --xh-_menubar-item-px: var(--xh-control-px-md);
    --xh-_menubar-item-gap: var(--xh-control-gap-md);
    --xh-_menubar-font-size: var(--xh-control-font-md);
  }

  [data-scope='menubar'][data-size='sm']:is([data-part='root'], [data-part='positioner']) {
    --xh-icon-size: var(--xh-menubar-icon-size, var(--xh-glyph-size-sm));
    --xh-_menubar-trigger-py: var(--xh-space-0_5);
    --xh-_menubar-trigger-px: var(--xh-control-px-sm);
    --xh-_menubar-item-py: var(--xh-list-option-py-sm);
    --xh-_menubar-item-px: var(--xh-control-px-sm);
    --xh-_menubar-item-gap: var(--xh-control-gap-sm);
    --xh-_menubar-font-size: var(--xh-control-font-sm);
  }

  [data-scope='menubar'][data-size='lg']:is([data-part='root'], [data-part='positioner']) {
    --xh-icon-size: var(--xh-menubar-icon-size, var(--xh-glyph-size-lg));
    --xh-_menubar-trigger-py: var(--xh-space-2);
    --xh-_menubar-trigger-px: var(--xh-control-px-lg);
    --xh-_menubar-item-py: var(--xh-list-option-py-lg);
    --xh-_menubar-item-px: var(--xh-control-px-lg);
    --xh-_menubar-item-gap: var(--xh-control-gap-lg);
    --xh-_menubar-font-size: var(--xh-control-font-lg);
  }

  [data-scope='menubar'][data-part='content'] {
    position: relative;
    display: flex;
    flex-direction: column;
    gap: var(--xh-menubar-content-gap, var(--xh-list-option-gap));
    min-inline-size: var(--xh-menubar-min-w, var(--xh-overlay-menu-min-w));
    /* 静态档与落位后的可用宽度取小：窄视口下面板伸出去，最右侧的内容就点不到了 */
    max-inline-size: min(var(--xh-menubar-max-w, var(--xh-overlay-max-w)), var(--xh-_menubar-available-w));
    /* 两道上限取更小的那道：自己的高度上限，以及落定那一侧真正剩下的空间。
       列表族的 16rem 对命令菜单偏矮，这里另给一档 */
    max-block-size: min(var(--xh-menubar-max-h, var(--xh-overlay-menu-max-h)), var(--xh-_menubar-available-h));
    padding-block: var(--xh-menubar-content-py, var(--xh-surface-pad-xs));
    padding-inline: var(--xh-menubar-content-px, var(--xh-surface-pad-xs));
    border: var(--xh-stroke-thin) solid var(--xh-menubar-border, var(--xh-material-frosted-border));
    border-radius: var(--xh-menubar-content-radius, var(--xh-shape-overlay));
    background: var(--xh-menubar-content-bg, var(--xh-material-frosted-bg));
    color: var(--xh-menubar-content-fg, var(--xh-material-frosted-fg));
    box-shadow: var(--xh-menubar-content-shadow, var(--xh-material-frosted-shadow));
    -webkit-backdrop-filter: var(--xh-menubar-backdrop, var(--xh-material-frosted-backdrop));
    backdrop-filter: var(--xh-menubar-backdrop, var(--xh-material-frosted-backdrop));
    /* 条目超过上限就在菜单内部滚。条目的焦点环是内收的，滚动容器裁在内边距缘上，环切不着。
       浮层滚动面：到底后不把滚动链穿透给页面 */
    overflow-y: auto;
    overscroll-behavior: contain;
    pointer-events: auto;
  }

  /* 顶光叠在真实四边 border 内侧；强制色撤掉装饰后，完整轮廓仍然存在。 */
  [data-scope='menubar'][data-part='content']::before {
    content: '';
    position: absolute;
    inset-block-start: 0;
    inset-inline: 0;
    block-size: var(--xh-stroke-thin);
    border-radius: inherit;
    background: var(--xh-menubar-highlight, var(--xh-material-frosted-highlight));
    pointer-events: none;
  }

  /* display 会盖掉 hidden 属性的 UA 规则，收起态显式让位。
     连接层给 content 发 hidden，这一条漏了整张菜单就永远收不起来 */
  /* 这里刻意没有 [data-part='content'][hidden] { display: none }，与 dialog 一致：
     收起态连接层会给 content 打 hidden，而上面那条 display 正是要盖掉 UA 的
     [hidden]{display:none}——退场动画得先能播。真正的收起由宿主在退场结束后落成内联 display。 */

  /* 容器只是"没有条目锚点时"的 Tab 兜底落点，落焦不画环：高亮永远长在条目上 */
  [data-scope='menubar'][data-part='content']:focus-visible {
    outline: none;
  }

  /* 首开从锚点一侧淡入短移，不缩放整张菜单面。 */
  [data-scope='menubar'][data-part='content'][data-state='open'] {
    animation: xh-overlay-slide-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 末收向锚点一侧淡出；forwards 防止动画完成到真正隐藏之间闪回原样。 */
  [data-scope='menubar'][data-part='content'][data-state='closed'] {
    will-change: opacity, translate;
    animation: xh-overlay-slide-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* 在一排入口间换张时两侧都瞬时：交叉淡变读起来就是闪烁。原生菜单栏的成规——首开有进场、末收有退场、
     换张不播。没有动画时退场闸门当场落定，收起即藏 */
  [data-scope='menubar'][data-part='content'][data-instant] {
    animation: none;
  }

  [data-scope='menubar'][data-part='group'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-menubar-group-gap, var(--xh-list-option-gap));
  }

  [data-scope='menubar'][data-part='group'][hidden] {
    display: none;
  }

  /* 分组标题不是条目、进不了导航，画成小号次要文字，
     内缩与条目对齐（同一个 padding-inline），标题与条目文字才在一条竖线上 */
  [data-scope='menubar'][data-part='group-label'] {
    display: block;
    padding-block: var(--xh-menubar-group-label-py, var(--xh-space-1));
    padding-inline: var(--xh-menubar-group-label-px, var(--xh-_menubar-item-px));
    color: var(--xh-menubar-group-label-fg, var(--xh-material-frosted-fg-muted));
    font-size: var(--xh-menubar-group-label-font-size, var(--xh-text-caption-size));
    font-weight: var(--xh-menubar-group-label-font-weight, var(--xh-font-weight-medium));
    line-height: var(--xh-leading-none);
    user-select: none;
  }

  [data-scope='menubar'][data-part='group-label'][hidden] {
    display: none;
  }

  /* 条目走 Collection Item 的 overlay 语境：悬停 / 键盘锚点（data-highlighted，白底承载 100）、按下（200）、
     子层开着的打开路径（data-in-path，与 hover 同档）与禁用面（aria-disabled）都由家族给，这里只把公开槽映射到
     桥接槽。布局保持 flex 而不用家族网格：图标、正文、快捷键按一行排布，说明另起一行靠 flex-wrap 折下去，
     子菜单箭头是行尾的伪元素；间距统一由行的 gap 给，家族按槽下发的外边距归零 */
  [data-scope='menubar'][data-part='item'] {
    --xh-collection-block-padding: var(--xh-menubar-item-py, var(--xh-_menubar-item-py));
    --xh-collection-inline-padding: var(--xh-menubar-item-px, var(--xh-_menubar-item-px));
    --xh-collection-gap: 0;
    --xh-collection-font-size: var(--xh-menubar-item-font-size, var(--xh-_menubar-font-size));
    --xh-collection-radius: var(--xh-menubar-item-radius, var(--xh-shape-control));
    --xh-collection-fg-rest: var(--xh-menubar-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-hover: var(--xh-menubar-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-keyboard-highlight: var(--xh-menubar-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-pressed: var(--xh-menubar-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-open-path: var(--xh-menubar-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-bg-hover: var(--xh-menubar-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-keyboard-highlight: var(--xh-menubar-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-pressed: var(--xh-menubar-item-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-bg-open-path: var(--xh-menubar-item-bg-active, var(--xh-bg-subtle));
    /* data-highlighted 同时覆盖指针与键盘路径：指针只换面，焦点环在 :focus-visible 下再接回 */
    --xh-collection-outline-keyboard-highlight: transparent;

    display: flex;
    align-items: center;
    gap: var(--xh-menubar-item-gap, var(--xh-_menubar-item-gap));
    line-height: var(--xh-menubar-item-leading, var(--xh-leading-normal));
    white-space: nowrap;
    user-select: none;
  }

  /* 条目可以按需收起（按上下文过滤掉的命令），有 display 就得补这条 */
  [data-scope='menubar'][data-part='item'][hidden] {
    display: none;
  }

  /* 键盘焦点出现时环才接回并立即到位，不压在背景过渡的中间帧上 */
  [data-scope='menubar'][data-part='item']:focus-visible:not(:hover) {
    --xh-collection-outline-keyboard-highlight: var(--xh-ring-focus);

    transition: none;
  }

  /* 带子菜单的条目行尾画右向小箭头：不点开也看得出还有下一级。
     description 按 order 独占下一行，箭头仍留在主行末端。
     箭头是指示符：与标记位的盒同走 --xh-control-indicator-size，不读 --xh-icon-size——
     按图标档取的 20px 会比 16px 的标记位盒大一圈 */
  [data-scope='menubar'][data-part='item'][aria-haspopup='menu']::after {
    content: '';
    flex: none;
    order: 1;
    margin-inline-start: auto;
    inline-size: var(--xh-menubar-submenu-indicator-size, var(--xh-control-indicator-size));
    block-size: var(--xh-menubar-submenu-indicator-size, var(--xh-control-indicator-size));
    background-color: var(--xh-menubar-submenu-indicator-fg, var(--xh-material-frosted-fg-muted));
    -webkit-mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
  }

  /* rtl 下子菜单开在左侧，箭头跟着指向行进方向 */
  [dir='rtl'] [data-scope='menubar'][data-part='item'][aria-haspopup='menu']::after {
    -webkit-mask-image: var(--xh-glyph-mark-chevron-left);
    mask-image: var(--xh-glyph-mark-chevron-left);
  }

  [data-scope='menubar'][data-part='item-text'] {
    flex: 1;
    min-inline-size: 0;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  [data-scope='menubar'][data-part='item-text'][hidden] {
    display: none;
  }

  /* 标记位（勾选符号 / 图标）按作者写入的位置留在主行，不为没写的条目强制占列。盒是指示符：按指示符档
     取尺，与 Menu / ContextMenu 的标记位同走 --xh-control-indicator-size，不读家族按档下发的 --xh-icon-size——
     按图标档取的 20px 会比同一行 16px 的指示符档大一圈。盒在自己身上把 --xh-icon-size 改接到盒的尺，
     皮肤画的兜底勾与作者塞进标记位的 XhIcon 读同一把尺、与盒同边长（行尾标记不是勾选格，不取 × 0.75）；
     条目上那支只管作者直接放进条目里的图标 */
  [data-scope='menubar'][data-part='item-indicator'] {
    --xh-icon-size: var(--xh-menubar-item-indicator-size, var(--xh-control-indicator-size));

    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-menubar-item-indicator-size, var(--xh-control-indicator-size));
    block-size: var(--xh-menubar-item-indicator-size, var(--xh-control-indicator-size));
    color: var(--xh-menubar-item-indicator-fg, var(--xh-_tone, var(--xh-fg-brand)));
  }

  [data-scope='menubar'][data-part='item-indicator'][hidden] {
    display: none;
  }

  [data-scope='menubar'][data-part='item-indicator'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 副文本另起一行：整行占满，把条目的一行内容折成两行 */
  [data-scope='menubar'][data-part='item-description'] {
    flex: 1 0 100%;
    order: 2;
    min-inline-size: 0;
    color: var(--xh-menubar-item-description-fg, var(--xh-material-frosted-fg-muted));
    font-size: var(--xh-menubar-item-description-font-size, var(--xh-text-caption-size));
    white-space: nowrap;
    text-overflow: ellipsis;
    overflow: hidden;
  }

  [data-scope='menubar'][data-part='item-description'][hidden] {
    display: none;
  }

  [data-scope='menubar'][data-part='item-description'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 没有说明时主行不允许无意换行；有说明才开启第二行。任意图标/快捷键仍保留作者的 DOM 顺序。 */
  [data-scope='menubar'][data-part='item']:has(> [data-scope='menubar'][data-part='item-description']) {
    flex-wrap: wrap;
  }

  /* 箭头的底色与描边色，几何在 overlay-arrow.css。
     交叉轴落点由定位引擎经内联自定义属性写进来，没给时退回居中 */
  [data-scope='menubar'][data-part='arrow'] {
    --xh-_menubar-arrow-x: 50%;
    --xh-_menubar-arrow-y: 50%;
    --xh-_overlay-arrow-size: var(--xh-menubar-arrow-size, var(--xh-overlay-arrow-size));
    --xh-_overlay-arrow-x: var(--xh-_menubar-arrow-x);
    --xh-_overlay-arrow-y: var(--xh-_menubar-arrow-y);

    background: var(--xh-menubar-content-bg, var(--xh-material-frosted-bg));
    border: var(--xh-stroke-thin) solid var(--xh-menubar-border, var(--xh-material-frosted-border));
  }

  /* 分隔线横跨菜单，与菜单栏自身的 orientation 无关：菜单永远是一列条目。
     不给 display，因此 UA 的 [hidden]{display:none} 自己就压得住 */
  [data-scope='menubar'][data-part='separator'] {
    block-size: var(--xh-menubar-separator-thickness, var(--xh-stroke-thin));
    margin-block: var(--xh-menubar-separator-my, var(--xh-space-0_5));
    border-radius: var(--xh-menubar-separator-radius, var(--xh-shape-pill));
    background: var(--xh-menubar-separator-color, var(--xh-material-frosted-separator));
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中。
     尺寸读标记位自己改接过的 --xh-icon-size：与盒同边长，随指示符档换档（见上面标记位那块） */
  [data-scope='menubar'][data-part='item-indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    mask: var(--xh-glyph-mark-check) center / contain no-repeat;
  }
}

@layer xihan.components {
  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。 */
    [data-scope='menubar'][data-part='positioner'] {
      display: none;
    }
  }

  @media (forced-colors: active) {
    /* 分组之间那条线画的是一块纯底色，这一档里底色被统一换成 Canvas，线整条消失，
       几组条目就连成了一长串。换成前景色画回来 */
    [data-scope='menubar'][data-part='separator'] {
      background: CanvasText;
    }
  }
}

/* styles/message-feed.css */
/* 定义 message feed 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */
/* 独立皮肤同时传递引入回底钮的动作控件配方，full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='message-feed'] {
    --xh-message-feed-skin: 1;
  }

  /* 根是定位基准：回到底部按钮贴在它的右下角。高度由使用者的版面给，这里不定高 */
  [data-scope='message-feed'][data-part='root'] {
    /* 尺寸缺省档：不写 data-size 时的取值。三档都只写这两个私有槽，
       公开槽留在读处当首选，作者在祖先上设的覆盖才赢得过档位声明 */
    --xh-_message-feed-gap: var(--xh-space-4);
    --xh-_message-feed-p: var(--xh-space-4);

    position: relative;
    display: flex;
    min-block-size: 0;
    flex-direction: column;
  }

  [data-scope='message-feed'][data-part='root'][hidden] {
    display: none;
  }

  /* 滚动容器：粘底视口，走 reset 层的原生细条。overscroll-behavior 挡住滚到头之后把整页一起带走 */
  [data-scope='message-feed'][data-part='viewport'] {
    overflow-y: auto;
    flex: 1 1 auto;
    min-block-size: 0;
    overscroll-behavior: contain;
  }

  /* 流式视口的内容高度一直在变，还在用原生滚动条的视口留一条空道，滚动条出现与消失时不推动文字。
     带 data-xh-scrollbar 的容器已经把原生条藏成零宽，这条空道对它没有布局作用，排除掉 */
  [data-scope='message-feed'][data-part='viewport']:not([data-xh-scrollbar]) {
    scrollbar-gutter: stable;
  }

  [data-scope='message-feed'][data-part='list'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-message-feed-gap, var(--xh-_message-feed-gap));
    padding: var(--xh-message-feed-p, var(--xh-_message-feed-p));
  }

  [data-scope='message-feed'][data-part='list'][hidden] {
    display: none;
  }

  /* 一条消息。默认整行铺开，左右分侧由使用者按 data-role 自己写。
     进场只动 opacity 与 translate：改高度会扰动粘底补偿量到的 scrollHeight */
  [data-scope='message-feed'][data-part='item'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-message-feed-item-gap, var(--xh-space-1));
    border-radius: var(--xh-message-feed-item-radius, var(--xh-shape-surface));
    animation: xh-item-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  [data-scope='message-feed'][data-part='item'][hidden] {
    display: none;
  }

  [data-scope='message-feed'][data-part='item-label'] {
    display: block;
    color: var(--xh-message-feed-label-fg, var(--xh-fg-muted));
    font-size: var(--xh-message-feed-label-font-size, var(--xh-text-caption-size));
    line-height: var(--xh-leading-tight);
  }

  [data-scope='message-feed'][data-part='item-label'][hidden] {
    display: none;
  }

  /* 回到底部：浮在滚动区右下角，收起时不卸载只隐藏。盒型、悬停 / 按下面与缩放由 Action Control 的
     floating 档给（circle 正方盒、ghost 形态：白底承载 hover 100 → pressed 200）；材质随角落浮钮族走
     frosted 四件套（底 + 边 + 影 + 磨砂），这里只把使用者槽映射到桥接槽：
     字形按 xs 档取 --xh-_action-profile-glyph-size（16px），与 log / back-top 同一把尺 */
  [data-scope='message-feed'][data-part='scroll-to-end-trigger'] {
    --xh-_message-feed-scroll-to-end-trigger-shadow: var(--xh-message-feed-scroll-to-end-trigger-shadow, var(--xh-material-frosted-shadow));
    --xh-action-visual-size: var(--xh-message-feed-scroll-to-end-trigger-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-message-feed-scroll-to-end-trigger-radius, var(--xh-shape-circle));
    --xh-action-bg-rest: var(--xh-message-feed-scroll-to-end-trigger-bg, var(--xh-material-frosted-bg));
    --xh-action-bg-hover: var(--xh-message-feed-scroll-to-end-trigger-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-border-rest: var(--xh-message-feed-scroll-to-end-trigger-border, var(--xh-material-frosted-border));
    --xh-action-border-hover: var(--xh-message-feed-scroll-to-end-trigger-border, var(--xh-material-frosted-border));
    --xh-action-border-pressed: var(--xh-message-feed-scroll-to-end-trigger-border, var(--xh-material-frosted-border));
    --xh-action-border-focus-visible: var(--xh-message-feed-scroll-to-end-trigger-border, var(--xh-material-frosted-border));
    --xh-action-shadow-rest: var(--xh-_message-feed-scroll-to-end-trigger-shadow);
    --xh-action-shadow-hover: var(--xh-_message-feed-scroll-to-end-trigger-shadow);
    --xh-action-shadow-pressed: var(--xh-_message-feed-scroll-to-end-trigger-shadow);
    --xh-action-fg-rest: var(--xh-message-feed-scroll-to-end-trigger-fg, var(--xh-material-frosted-fg));
    --xh-icon-size: var(--xh-message-feed-icon-size, var(--xh-_action-profile-glyph-size));

    position: absolute;
    inset-block-end: var(--xh-message-feed-scroll-to-end-trigger-inset, var(--xh-space-4));
    inset-inline-end: var(--xh-message-feed-scroll-to-end-trigger-inset, var(--xh-space-4));
    -webkit-backdrop-filter: var(--xh-material-frosted-backdrop);
    backdrop-filter: var(--xh-material-frosted-backdrop);
  }

  /* 连接层收起按钮时写 hidden 属性，家族那条 display 会盖掉 UA 规则，这里补回 */
  [data-scope='message-feed'][data-part='scroll-to-end-trigger'][hidden] {
    display: none;
  }

  /* 收起不卸载，冒出来时靠这条进场动画；不写 display，可见性归上面那条 [hidden] 管 */
  [data-scope='message-feed'][data-part='scroll-to-end-trigger'][data-state='visible'] {
    animation: xh-pop-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 没写内容就由皮肤画一枚向下的字形；作者往按钮里塞了自己的图形，这条规则即不命中 */
  [data-scope='message-feed'][data-part='scroll-to-end-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-sm));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-sm));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
  }

  /* 尺寸档只改消息之间的距离与内边距；宽松档把消息之间再放开一级，内边距不跟 */
  [data-scope='message-feed'][data-part='root'][data-size='sm'] {
    --xh-_message-feed-gap: var(--xh-space-2);
    --xh-_message-feed-p: var(--xh-space-2);
  }

  [data-scope='message-feed'][data-part='root'][data-size='md'] {
    --xh-_message-feed-gap: var(--xh-space-4);
    --xh-_message-feed-p: var(--xh-space-4);
  }

  [data-scope='message-feed'][data-part='root'][data-size='lg'] {
    --xh-_message-feed-gap: var(--xh-space-8);
    --xh-_message-feed-p: var(--xh-space-6);
  }

  /* 视觉隐藏的原子播报区：不能 display:none，那样读屏就取不到它了 */
  [data-scope='message-feed'][data-part='live-region'] {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    border: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  @media print {
    /* 打印：回到底部这颗钮只有在能滚的地方才成立，落到纸上是一颗按不动的按钮。 */
    [data-scope='message-feed'][data-part='scroll-to-end-trigger'] {
      display: none;
    }
  }
}

/* styles/navigation-menu.css */
/* 定义 navigation menu 样式。 */

/* 共享关键帧由 family/motion.css 提供，入口与面板里的链接都走 Collection Item 家族的 nav 语境；本皮肤 @import 它们，单独引入仍成立。
   2px 指示线由本皮肤画两种：list 上的滑动 indicator 部件指的是「哪张面板开着」，指向当前页面的链接自画一条静态线 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='navigation-menu'] {
    --xh-navigation-menu-skin: 1;
  }

  /* 根节点是 nav 地标，不参与排版；给 relative 是为了让共享外壳（viewport）有个定位参照系。
     这里不给 display，UA 的 [hidden]{display:none} 就仍然压得住 */
  [data-scope='navigation-menu'][data-part='root'] {
    /* 尺寸档只换这五个私有槽，trigger 与面板里的链接都从 root 继承它们，
       换档不必给每个部件各写一条选择器。面板与共享外壳都是 root 的后代，一并继承。
       trigger 的字号经家族桥接槽接回 root 这一档，不另立私有槽 */
    /* 入口里的方向标记按档取尺，缺省 md，随 data-size 换档；面板里链接内的字形由家族随
       data-xh-collection-size 下发 */
    --xh-icon-size: var(--xh-navigation-menu-icon-size, var(--xh-glyph-size-md));

    --xh-_navigation-menu-font-size: var(--xh-control-font-md);
    --xh-_navigation-menu-trigger-h: var(--xh-control-h-md);
    --xh-_navigation-menu-trigger-px: var(--xh-control-px-md);
    --xh-_navigation-menu-trigger-gap: var(--xh-control-gap-md);
    --xh-_navigation-menu-link-py: var(--xh-space-1_5);
    --xh-_navigation-menu-link-px: var(--xh-control-px-md);
    --xh-_navigation-menu-link-font-size: var(--xh-control-font-md);

    /* 悬停、键盘锚点与展开着的入口同走中性灰轻档、不接语气槽：打开中不是选中，不用品牌色 */
    --xh-_navigation-menu-highlight-bg: var(--xh-bg-subtle);

    /* 语气只落在指示条上；没写 data-tone 时 --xh-_tone 没被声明，退回品牌色。
       当前链接的字色不随语气：导航当前页恒取 --xh-fg-brand-strong。聚焦环恒是 --xh-ring-focus */
    --xh-_navigation-menu-accent: var(--xh-_tone, var(--xh-fg-brand));

    position: relative;
    color: var(--xh-navigation-menu-fg, var(--xh-fg-default));
    font-size: var(--xh-navigation-menu-font-size, var(--xh-_navigation-menu-font-size));
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里。链接的内边距不在控件内边距那把尺上（它比控件矮一档），
     三档一律取空间尺，缺省档的取值原样保留 */
  [data-scope='navigation-menu'][data-part='root'][data-size='sm'] {
    --xh-icon-size: var(--xh-navigation-menu-icon-size, var(--xh-glyph-size-sm));
    --xh-_navigation-menu-font-size: var(--xh-control-font-sm);
    --xh-_navigation-menu-trigger-h: var(--xh-control-h-sm);
    --xh-_navigation-menu-trigger-px: var(--xh-control-px-sm);
    --xh-_navigation-menu-trigger-gap: var(--xh-control-gap-sm);
    --xh-_navigation-menu-link-py: var(--xh-space-1);
    --xh-_navigation-menu-link-px: var(--xh-control-px-sm);
    --xh-_navigation-menu-link-font-size: var(--xh-control-font-sm);
  }

  [data-scope='navigation-menu'][data-part='root'][data-size='lg'] {
    --xh-icon-size: var(--xh-navigation-menu-icon-size, var(--xh-glyph-size-lg));
    --xh-_navigation-menu-font-size: var(--xh-control-font-lg);
    --xh-_navigation-menu-trigger-h: var(--xh-control-h-lg);
    --xh-_navigation-menu-trigger-px: var(--xh-control-px-lg);
    --xh-_navigation-menu-trigger-gap: var(--xh-control-gap-lg);
    --xh-_navigation-menu-link-py: var(--xh-space-2);
    --xh-_navigation-menu-link-px: var(--xh-control-px-lg);
    --xh-_navigation-menu-link-font-size: var(--xh-control-font-lg);
  }

  /* 指示条的定位参照系（它是 absolute，量出来的偏移就是相对这里的）。
     ul 的项目符号与内外边距是 UA 给的，库里没有全局 preflight，只能在这儿自己抹平。
     一行排不下就折行：入口宽度由文字决定，硬撑一行会把整条导航顶出容器；
     这里不改成横向滚动——面板是绝对定位在各自那一项里的，列表一旦成为滚动容器就把面板裁掉了 */
  [data-scope='navigation-menu'][data-part='list'] {
    position: relative;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--xh-navigation-menu-gap, var(--xh-space-1));
    margin: 0;
    padding: 0;
    list-style: none;
  }

  [data-scope='navigation-menu'][data-part='list'][hidden] {
    display: none;
  }

  [data-scope='navigation-menu'][data-part='list'][data-orientation='vertical'] {
    flex-direction: column;
    align-items: stretch;
    flex-wrap: nowrap;
  }

  /* 一项一个 li，面板就住在里面：给 relative 让面板贴着自己这一项落位 */
  [data-scope='navigation-menu'][data-part='item'] {
    position: relative;
    display: flex;
    /* 库里没有全局 preflight，列表项的外边距在这里自己抹平 */
    margin: 0;
  }

  [data-scope='navigation-menu'][data-part='item'][hidden] {
    display: none;
  }

  /* 入口归 Collection Item 展开路径 / 打开中（nav 语境）：几何、字号、面与字重全经家族桥接槽。静息 muted /
     regular，悬停走白底承载 hover 100 + default 字；展开着的那一张由连接层投影 data-in-path，家族给与悬停同档的
     中性面——打开中不是选中，不用品牌色、不加粗（横排的栏加粗会推挤相邻触发器），哪一张开着由指示条与转向的
     箭头说明；按下 pressed 200 只换面不缩放；禁用走 aria-disabled，家族给禁用字色与 not-allowed。
     高度由 block-size 定，块向内边距归零。本条 (0,2,0) 压过家族基础块 (0,1,0)，不能再写 background / color /
     font-weight / cursor；也不写 font: inherit（reset.css 已抹平按钮 UA 字体，再写会把家族给的字号字重一并盖掉） */
  [data-scope='navigation-menu'][data-part='trigger'] {
    --xh-collection-block-padding: var(--xh-space-0);
    --xh-collection-inline-padding: var(--xh-navigation-menu-trigger-px, var(--xh-_navigation-menu-trigger-px));
    --xh-collection-radius: var(--xh-navigation-menu-trigger-radius, var(--xh-shape-control));
    --xh-collection-font-size: var(--xh-navigation-menu-font-size, var(--xh-_navigation-menu-font-size));
    --xh-collection-fg-rest: var(--xh-navigation-menu-trigger-fg, var(--xh-fg-muted));
    --xh-collection-font-weight-rest: var(--xh-navigation-menu-trigger-font-weight, var(--xh-font-weight-regular));
    --xh-collection-bg-hover: var(--xh-navigation-menu-trigger-bg-hover, var(--xh-_navigation-menu-highlight-bg));
    --xh-collection-bg-open-path: var(--xh-navigation-menu-trigger-bg-active, var(--xh-_navigation-menu-highlight-bg));
    --xh-collection-bg-pressed: var(--xh-navigation-menu-trigger-bg-pressed, var(--xh-bg-subtle-hover));

    display: inline-flex;
    align-items: center;
    gap: var(--xh-navigation-menu-trigger-gap, var(--xh-_navigation-menu-trigger-gap));
    block-size: var(--xh-navigation-menu-trigger-h, var(--xh-_navigation-menu-trigger-h));
    border: 0;
    /* 行高压回 none：家族基础块给条目写了 leading-normal，入口的高度只由 block-size 定 */
    line-height: var(--xh-leading-none);
    white-space: nowrap;
  }

  [data-scope='navigation-menu'][data-part='trigger'][hidden] {
    display: none;
  }

  /* 竖排：入口占满整项的宽度，面板才从入口右缘长出来 */
  [data-scope='navigation-menu'][data-part='trigger'][data-orientation='vertical'] {
    flex: 1;
  }

  /* 面板贴着自己那一项落位：横排从 trigger 底下长出来 */
  [data-scope='navigation-menu'][data-part='content'] {
    position: absolute;
    z-index: var(--xh-navigation-menu-layer, var(--xh-_layer, var(--xh-layer-popover)));
    inset-block-start: calc(100% + var(--xh-navigation-menu-content-offset, var(--xh-space-1)));
    inset-inline-start: 0;
    display: flex;
    flex-direction: column;
    gap: var(--xh-navigation-menu-content-gap, var(--xh-space-1));
    min-inline-size: var(--xh-navigation-menu-content-min-w, var(--xh-overlay-menu-min-w));
    padding: var(--xh-navigation-menu-content-p, var(--xh-surface-pad-xs));
    border: var(--xh-stroke-thin) solid var(--xh-navigation-menu-content-border, var(--xh-border-default));
    border-radius: var(--xh-navigation-menu-content-radius, var(--xh-shape-overlay));
    background: var(--xh-navigation-menu-content-bg, var(--xh-bg-surface));
    box-shadow: var(--xh-navigation-menu-content-shadow, var(--xh-elevation-floating));
  }

  /* display 会盖掉 hidden 属性的 UA 规则，收起态显式让位 */
  /* 这里刻意没有 [data-part='content'][hidden] { display: none }，与 dialog 一致：
     收起态连接层会给 content 打 hidden，而上面那条 display 正是要盖掉 UA 的
     [hidden]{display:none}——退场动画得先能播。真正的收起由宿主在退场结束后落成内联 display。 */

  /* 竖排导航：面板改从侧边长出来 */
  [data-scope='navigation-menu'][data-part='content'][data-orientation='vertical'] {
    inset-block-start: 0;
    inset-inline-start: calc(100% + var(--xh-navigation-menu-content-offset, var(--xh-space-1)));
  }

  [data-scope='navigation-menu'][data-part='content'][data-state='open'] {
    animation: xh-pop-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 退场：收起那一帧 hidden 由退场闸门押后，这里才播得出来 */
  [data-scope='navigation-menu'][data-part='content'][data-state='closed'] {
    animation: xh-pop-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* 面板整批塞进共享外壳时，落位归外壳管，面板自己回到静态流里——
     不还原的话它会以外壳为参照再往下掉一整个身位 */
  [data-scope='navigation-menu'][data-part='viewport'] [data-scope='navigation-menu'][data-part='content'] {
    position: static;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
  }

  /* 面板里的链接归 Collection Item 导航当前（nav 语境）：悬停 / 键盘高亮（白底承载 100）与按下（200）面由家族
     按 :hover / :focus-visible / :active 给出，指向当前页面的那一条（data-current）取 strong 档品牌字色 +
     medium 字重，字色不随语气、不加下划线（下划线是"可点"的信号，它已经在这儿了）；这里只把公开槽
     映射到桥接槽。面板是实色 floating 面，常态字色取 --xh-fg-default 而非 nav 缺省的 muted。
     布局保持 flex：链接是一行文字，不用家族网格。position: relative 是当前链接静态线的定位参照 */
  [data-scope='navigation-menu'][data-part='link'] {
    --xh-collection-block-padding: var(--xh-navigation-menu-link-py, var(--xh-_navigation-menu-link-py));
    --xh-collection-inline-padding: var(--xh-navigation-menu-link-px, var(--xh-_navigation-menu-link-px));
    --xh-collection-radius: var(--xh-navigation-menu-link-radius, var(--xh-shape-control));
    --xh-collection-font-size: var(--xh-navigation-menu-link-font-size, var(--xh-_navigation-menu-link-font-size));
    --xh-collection-fg-rest: var(--xh-navigation-menu-link-fg, var(--xh-fg-default));
    --xh-collection-fg-hover: var(--xh-navigation-menu-link-fg, var(--xh-fg-default));
    --xh-collection-fg-keyboard-highlight: var(--xh-navigation-menu-link-fg, var(--xh-fg-default));
    --xh-collection-fg-pressed: var(--xh-navigation-menu-link-fg, var(--xh-fg-default));
    --xh-collection-bg-hover: var(--xh-navigation-menu-link-bg-hover, var(--xh-_navigation-menu-highlight-bg));
    --xh-collection-bg-keyboard-highlight: var(--xh-navigation-menu-link-bg-hover, var(--xh-_navigation-menu-highlight-bg));
    --xh-collection-bg-pressed: var(--xh-navigation-menu-link-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-fg-current: var(--xh-navigation-menu-link-fg-current, var(--xh-fg-brand-strong));
    --xh-collection-font-weight-current: var(--xh-navigation-menu-link-font-weight-current, var(--xh-font-weight-medium));

    position: relative;
    display: flex;
    align-items: center;
    text-decoration: none;
  }

  [data-scope='navigation-menu'][data-part='link'][hidden] {
    display: none;
  }

  /* 入口里表示"底下还有一张面板"的标记，排在入口文字之后，展开时转向 */
  [data-scope='navigation-menu'][data-part='trigger-indicator'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    line-height: var(--xh-leading-none);
    transition: rotate var(--xh-motion-duration-nudge) var(--xh-motion-ease-enter-strong);
  }

  [data-scope='navigation-menu'][data-part='trigger-indicator'][hidden] {
    display: none;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这条规则即不命中 */
  [data-scope='navigation-menu'][data-part='trigger-indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
  }

  [data-scope='navigation-menu'][data-part='trigger-indicator'][data-state='open'] {
    rotate: 180deg;
  }

  [data-scope='navigation-menu'][data-part='trigger-indicator'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 指向当前页面的链接自画一条静态指示线（导航当前页）：与 Tabs line / Anchor 同一取法，作者不必为了
     这条线多放一个部件。下面的 indicator 部件表达的是「哪张面板开着」而不是当前页，所以这条线不随部件收起，
     两者各说各的：部件亮着时开着的入口下有一条、当前页链接上另有一条。
     线画在当前链接的 ::after 上，以链接盒为定位参照（上面已给 position: relative），
     厚度 / 颜色 / 圆角与 indicator 部件读同一组槽与缺省——作者改一处，部件与静态线一起改。不做动画。
     缺省贴链接的行向起始缘（竖排的直达链接、面板里的链接都是一列，rtl 随逻辑属性镜像），主轴两端各退一格
     --xh-space-1 避开链接的圆角，与家族 page 语境的起始侧指示条同一取法；横排 list 里的直达链接改贴底边 */
  [data-scope='navigation-menu'][data-part='link'][data-current]::after {
    content: '';
    position: absolute;
    inset-inline-start: 0;
    inset-block: var(--xh-space-1);
    inline-size: var(--xh-navigation-menu-indicator-thickness, var(--xh-stroke-thick));
    border-radius: var(--xh-navigation-menu-indicator-radius, var(--xh-shape-pill));
    background: var(--xh-navigation-menu-indicator-color, var(--xh-_navigation-menu-accent));
    pointer-events: none;
  }

  /* 横排 list 里的直达链接：贴链接的块向末端（底边），与部件同一侧 */
  [data-scope='navigation-menu'][data-part='list'][data-orientation='horizontal']
    > [data-scope='navigation-menu'][data-part='item']
    > [data-scope='navigation-menu'][data-part='link'][data-current]::after {
    inset-inline: var(--xh-space-1);
    inset-block: auto 0;
    inline-size: auto;
    block-size: var(--xh-navigation-menu-indicator-thickness, var(--xh-stroke-thick));
  }

  /* 展开入口的四个几何量由机器量好、连接层写成私有槽 --xh-_navigation-menu-indicator-x / -y / -w / -h
     （它量得到，样式表量不到）；这里按排布取主轴那两支，落点交给 transform（只走合成），
     另管交叉轴的贴边与粗细，以及长什么样。它指的是开着的面板：无面板开着时隐藏，
     当前页由上面链接自画的静态线表达 */
  [data-scope='navigation-menu'][data-part='indicator'] {
    /* 还没量到时的落点，量到即被机器写的私有槽盖过 */
    --xh-_navigation-menu-indicator-x: 0;
    --xh-_navigation-menu-indicator-y: 0;
    --xh-_navigation-menu-indicator-w: 0;
    --xh-_navigation-menu-indicator-h: 0;

    position: absolute;
    display: block;
    /* 指示条也是列表项，宿主给 li 的外边距会把绝对定位的它推离入口 */
    margin: 0;
    inset-inline-start: 0;
    inset-block-end: calc(var(--xh-navigation-menu-indicator-thickness, var(--xh-stroke-thick)) * -1);
    inline-size: var(--xh-_navigation-menu-indicator-w);
    block-size: var(--xh-navigation-menu-indicator-thickness, var(--xh-stroke-thick));
    border-radius: var(--xh-navigation-menu-indicator-radius, var(--xh-shape-pill));
    background: var(--xh-navigation-menu-indicator-color, var(--xh-_navigation-menu-accent));
    transform: translate(var(--xh-_navigation-menu-indicator-x), 0);
    transition:
      transform var(--xh-motion-duration-move) var(--xh-motion-ease-continuous),
      inline-size var(--xh-motion-duration-move) var(--xh-motion-ease-continuous);
  }

  /* transform 只认物理方向：RTL 下行首在右边，起始缘量出的距离往左推 */
  [data-scope='navigation-menu'][data-part='indicator']:dir(rtl) {
    transform: translate(calc(-1 * var(--xh-_navigation-menu-indicator-x)), 0);
  }

  [data-scope='navigation-menu'][data-part='indicator'][hidden] {
    display: none;
  }

  /* 竖排：指示条改贴在起始缘，交叉轴换成内联轴 */
  [data-scope='navigation-menu'][data-part='indicator'][data-orientation='vertical'] {
    inset-block-start: 0;
    inset-block-end: auto;
    inset-inline-start: 0;
    inline-size: var(--xh-navigation-menu-indicator-thickness, var(--xh-stroke-thick));
    block-size: var(--xh-_navigation-menu-indicator-h);
    transform: translate(0, var(--xh-_navigation-menu-indicator-y));
    transition:
      transform var(--xh-motion-duration-move) var(--xh-motion-ease-continuous),
      block-size var(--xh-motion-duration-move) var(--xh-motion-ease-continuous);
  }

  /* 共享面板外壳：只管落位与统一的面板外观，里面装哪一份内容归 content。
     内衬自成一个槽：外壳装的是整份面板，缺省比 content 宽一档，
     两处共用一个槽的话调了一处另一处跟着走，差值就再也调不开 */
  [data-scope='navigation-menu'][data-part='viewport'] {
    position: absolute;
    z-index: var(--xh-navigation-menu-layer, var(--xh-_layer, var(--xh-layer-popover)));
    inset-block-start: calc(100% + var(--xh-navigation-menu-content-offset, var(--xh-space-1)));
    inset-inline-start: 0;
    display: block;
    padding: var(--xh-navigation-menu-viewport-p, var(--xh-space-2));
    border: var(--xh-stroke-thin) solid var(--xh-navigation-menu-content-border, var(--xh-border-default));
    border-radius: var(--xh-navigation-menu-content-radius, var(--xh-shape-overlay));
    background: var(--xh-navigation-menu-content-bg, var(--xh-bg-surface));
    box-shadow: var(--xh-navigation-menu-content-shadow, var(--xh-elevation-floating));
  }

  [data-scope='navigation-menu'][data-part='viewport'][hidden] {
    display: none;
  }

  /* 竖排导航：共享外壳跟着面板改从侧边长出来 */
  [data-scope='navigation-menu'][data-part='viewport'][data-orientation='vertical'] {
    inset-block-start: 0;
    inset-inline-start: calc(100% + var(--xh-navigation-menu-content-offset, var(--xh-space-1)));
  }

  @media (forced-colors: active) {
    /* 两条指示线画的都是一块纯底色，这一档里底色被统一换成 Canvas，线整根消失：
       开着的入口只剩转向的箭头、当前页只剩字重。换成系统高亮色画回来 */
    [data-scope='navigation-menu'][data-part='indicator'],
    [data-scope='navigation-menu'][data-part='link'][data-current]::after {
      background: Highlight;
    }
  }
}

/* styles/notification.css */
/* 定义 notification 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */
/* Notification 独立皮肤同时传递引入操作 / 关闭钮的动作控件配方；full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='notification'] {
    --xh-notification-skin: 1;
  }

  /* 作用域包装不占布局：通知落在哪儿由九个 group 各自的 fixed 说了算，
     root 只是把队列的作用域圈起来（地标挂在那一摞上，不在这里）。
     它若留下一个块盒，写在页面中段的用法（按钮和队列摆在一起）就会凭空多出一行空白。
     另一件必须提防的事：fixed 认的是视口，祖先上一旦出现
     transform / filter / backdrop-filter / contain，包含块就被抢走，整摞通知立刻贴错位置——
     所以这里连 position 都不碰，也别往覆盖钩子里加这几个属性。 */
  [data-scope='notification'][data-part='root'] {
    display: contents;
  }

  /* 只要声明过 display，就盖掉了 UA 的 [hidden]{display:none}，收起态得自己补回来 */
  [data-scope='notification'][data-part='root'][hidden] {
    display: none;
  }

  /*
   * 一摞 = 一整面视口大小的定位面：贴边靠 padding，九个位靠 justify/align 表达。
   * 不用四角 inset 逐个摆，是因为 column flex 的 align-items 走的是行内轴，
   * RTL 下 start/end 自动跟着翻；写死 inset-inline-start 的话居中那三个位
   * 还得再配一次 translate，方向一变就错。
   * 条目次序按队列原样（旧的在前）：贴底那三个位于是新的离屏幕边最近，符合直觉。
   */
  [data-scope='notification'][data-part='group'] {
    position: fixed;
    inset-block: 0;
    inset-inline: 0;
    z-index: var(--xh-notification-layer, var(--xh-layer-toast));
    display: flex;
    flex-direction: column;
    /* 基线按默认落位 bottom-end 写，下面只覆盖跟它不同的那几个位 */
    justify-content: flex-end;
    align-items: center;
    /* 贴边与安全区取大的一头：刘海、圆角与底部横条压住的那一段由系统给出，
       贴边比它窄时卡片会被切掉一角。桌面上 env() 恒为 0，取值与贴边槽完全一致。
       两条内联的 env 一起取大值：安全区只有物理方向的四个名字，
       分左右写在 RTL 下会翻错边，两侧同取较宽的那一段。 */
    padding-block-start: max(var(--xh-notification-inset, var(--xh-space-6)), env(safe-area-inset-top));
    padding-block-end: max(var(--xh-notification-inset, var(--xh-space-6)), env(safe-area-inset-bottom));
    padding-inline: max(
      var(--xh-notification-inset, var(--xh-space-6)),
      env(safe-area-inset-left),
      env(safe-area-inset-right)
    );
    /* 摞内间距由连接层写进内联 style（两个适配器共用同一份），这里绝不重复写：
       写了也会被内联盖掉，只会让人误以为间距归样式层管 */
    /* 整面铺开就等于罩住了整块视口。面本身不吃指针，只有卡片吃（见下），
       否则九个位一叠，底下的页面就再也点不动了 */
    pointer-events: none;
  }

  [data-scope='notification'][data-part='group'][hidden] {
    display: none;
  }

  /* 空摞直接撤掉：九个位同时挂九张全屏定位面，白白多九个合成层 */
  [data-scope='notification'][data-part='group'][data-empty] {
    display: none;
  }

  /* 块轴落位：^= 一次吃掉某一行的三个位（top / top-start / top-end） */
  [data-scope='notification'][data-part='group'][data-placement^='top'] {
    justify-content: flex-start;
  }

  [data-scope='notification'][data-part='group'][data-placement^='middle'] {
    justify-content: center;
  }

  /* 行内轴落位：不带后缀的 top / middle / bottom 用基线的居中 */
  [data-scope='notification'][data-part='group'][data-placement$='-start'] {
    align-items: flex-start;
  }

  [data-scope='notification'][data-part='group'][data-placement$='-end'] {
    align-items: flex-end;
  }

  /*
   * 一张通知卡：左列一枚类型字形，右列「标题 + 说明 + 操作」竖着排，叉钉在右上角。
   * 用网格而不是竖排 flex：叉要脱离文档流钉到角上，正文要在字形右边成一列——
   * 竖排 flex 里这两件事都做不到（叉会变成第三行）。
   * 底与描边一律中性，语气只由左列那枚字形承载：整片兑色是轻提示那条的做法，
   * 一张有标题有正文的卡片全片染色会把两层文字都压在同一片语气色上。
   * 面走 sheet 三件套（--xh-material-elevated-bg / -border / -shadow，与 toast 同一套）。
   *
   * 卡片的槽带 item 段（--xh-notification-item-*），与摞的 --xh-notification-inset 分开。
   */
  [data-scope='notification'][data-part='item'] {
    /* 作者塞进卡片里的图标与皮肤画的兜底字形同一把尺：Feedback 指示符统一 md 档；
       左列那枚类型字形另有自己的尺寸槽，叉与操作钮的字形各按按钮档取值 */
    --xh-icon-size: var(--xh-notification-icon-size, var(--xh-glyph-size-md));

    position: relative;
    display: grid;
    /* 左列宽度由字形自己决定，作者不放指示符时它就是 0，正文自然贴到左内衬 */
    grid-template-columns: auto 1fr;
    align-items: start;
    column-gap: var(--xh-notification-item-gap, var(--xh-space-3));
    row-gap: var(--xh-notification-item-row-gap, var(--xh-space-2));
    inline-size: var(--xh-notification-item-w, var(--xh-overlay-max-w-lg));
    /* 摞是整面视口宽的定位面且带内边距，取 100% 就等于自动让出两侧留白，
       窄屏上不必再算一遍 viewport 减法 */
    max-inline-size: 100%;
    padding-block: var(--xh-notification-item-py, var(--xh-surface-pad-lg));
    padding-inline: var(--xh-notification-item-px, var(--xh-surface-pad-lg));
    border: var(--xh-stroke-thin) solid var(--xh-notification-item-border, var(--xh-material-elevated-border));
    border-radius: var(--xh-notification-item-radius, var(--xh-shape-overlay));
    background: var(--xh-notification-item-bg, var(--xh-material-elevated-bg));
    color: var(--xh-notification-item-fg, var(--xh-material-elevated-fg));
    box-shadow: var(--xh-notification-item-shadow, var(--xh-material-elevated-shadow));
    font-size: var(--xh-notification-item-font-size, var(--xh-text-body-size));
    line-height: var(--xh-notification-item-leading, var(--xh-text-body-leading));
    /* 摞的定位面整面铺开且不吃指针，卡片必须自己吃回来：
       悬停按住计时、按钮可点、焦点进出，全指着这一条 */
    pointer-events: auto;
  }

  /* 除指示符外一律落第二列：作者往卡片里塞的任何东西都跟着正文走 */
  [data-scope='notification'][data-part='item'] > *:not([data-part='item-indicator']) {
    grid-column: 2;
  }

  /* 退场窗口走完连接层给的是 hidden 属性，而上面声明了 display——
     漏掉这条，已经"卸载"的通知会一直杵在屏幕上，且再也没人来收 */
  [data-scope='notification'][data-part='item'][hidden] {
    display: none;
  }

  /* 生命周期只有三段，unmounted 那段由上面的 [hidden] 收走，这里只管前两段。
     九个位共用同一条进出场，位移不跟着落位走：要按位置分方向，就得从 group 的
     data-placement 反向选到卡片上，落位一改名整条动效静默失效。竖向一小段位移在九个位上都说得通 */
  [data-scope='notification'][data-part='item'][data-state='visible'] {
    animation: xh-sheet-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong) backwards;
  }

  /* 一摞里的多条按位次错开开幕。backwards 不能省：等待期间起帧不生效的话，
     卡片会先以全不透明度露一下再跳回起帧。第 6 条起并到同一拍上 */
  [data-scope='notification'][data-part='item'][data-state='visible']:nth-child(2) {
    animation-delay: calc(var(--xh-motion-stagger-step) * 1);
  }

  [data-scope='notification'][data-part='item'][data-state='visible']:nth-child(3) {
    animation-delay: calc(var(--xh-motion-stagger-step) * 2);
  }

  [data-scope='notification'][data-part='item'][data-state='visible']:nth-child(4) {
    animation-delay: calc(var(--xh-motion-stagger-step) * 3);
  }

  [data-scope='notification'][data-part='item'][data-state='visible']:nth-child(5) {
    animation-delay: calc(var(--xh-motion-stagger-step) * 4);
  }

  [data-scope='notification'][data-part='item'][data-state='visible']:nth-child(n + 6) {
    animation-delay: calc(var(--xh-motion-stagger-step) * 5);
  }

  /* forwards 不能省：退场窗口（removeDelay 默认 200ms）比退场动画长，
     不定住末帧的话动画跑完会弹回全不透明，卡片在被收起前先闪一下 */
  [data-scope='notification'][data-part='item'][data-state='dismissing'] {
    animation: xh-sheet-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* 独占第一列第一行，并与标题首行顶对齐：盒高取一行标题的行高，
     字形在盒里居中，标题字号改了也不会错位 */
  [data-scope='notification'][data-part='item-indicator'] {
    --xh-icon-size: var(--xh-notification-indicator-size, var(--xh-glyph-size-md));

    grid-column: 1;
    grid-row: 1;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    block-size: calc(var(--xh-notification-title-font-size, var(--xh-text-label-size)) * var(--xh-leading-tight));
    inline-size: var(--xh-notification-indicator-size, var(--xh-glyph-size-md));
    color: var(--xh-notification-indicator-fg, var(--xh-_tone-fg));
  }

  [data-scope='notification'][data-part='item-indicator'][hidden] {
    display: none;
  }

  /* 作者没往指示符里写内容就由皮肤画兜底字形，按语气各画一枚；
     塞了自己的图形这几条即不命中 */
  [data-scope='notification'][data-part='item-indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-info) center / contain no-repeat;
    mask: var(--xh-glyph-mark-info) center / contain no-repeat;
  }

  [data-scope='notification'][data-part='item'][data-tone='success'] [data-part='item-indicator']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-check);
    mask-image: var(--xh-glyph-mark-check);
  }

  [data-scope='notification'][data-part='item'][data-tone='warning'] [data-part='item-indicator']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-warning);
    mask-image: var(--xh-glyph-mark-warning);
  }

  [data-scope='notification'][data-part='item'][data-tone='danger'] [data-part='item-indicator']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-close);
    mask-image: var(--xh-glyph-mark-close);
  }

  /* 加载中不是语气：只换字形，颜色沿用当前语气的前景档；写在四档语气之后，转圈压过它们 */
  [data-scope='notification'][data-part='item'][data-loading] [data-part='item-indicator']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-rotate-right);
    mask-image: var(--xh-glyph-mark-rotate-right);
    animation: xh-spin var(--xh-spin-duration) var(--xh-motion-ease-loop) infinite;
  }

  /* 减少动效：转圈停下，静止的箭头仍然读得出「还没好」；
     "在等什么"由卡片上的 role=status 与可见文案继续承担。
     两组规则是同一件事的两个触发条件：系统偏好与作者打的 data-motion */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='notification'][data-part='item'][data-loading] [data-part='item-indicator']:empty::before {
      animation: none;
    }
  }

  :where([data-motion='reduce']) [data-scope='notification'][data-part='item'][data-loading] [data-part='item-indicator']:empty::before {
    animation: none;
  }

  [data-scope='notification'][data-part='item-title'] {
    /* 作者可能把它写成 h2/p，外边距得先归零，否则卡片内的行距对不上 */
    margin: 0;
    color: var(--xh-notification-title-fg, var(--xh-fg-default));
    font-size: var(--xh-notification-title-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-notification-title-font-weight, var(--xh-font-weight-semibold));
    line-height: var(--xh-notification-title-leading, var(--xh-leading-tight));
  }

  /* 叉钉在右上角，标题得给它让位；说明与操作在第二行往下，不受影响。
     让位量与叉的贴边取同一个值，作者改了贴边槽，标题让出的那段跟着走 */
  [data-scope='notification'][data-part='item']:has([data-part='item-close-trigger']) [data-part='item-title'] {
    padding-inline-end: calc(
      var(--xh-notification-close-size, var(--xh-control-h-sm)) +
      var(--xh-notification-close-inset, var(--xh-surface-action-inset))
    );
  }

  [data-scope='notification'][data-part='item-description'] {
    margin: 0;
    color: var(--xh-notification-description-fg, var(--xh-fg-muted));
    font-size: var(--xh-notification-description-font-size, var(--xh-text-secondary-size));
  }

  /* 没给文案的那一个仍然要留在 DOM 里（aria-labelledby / aria-describedby 指着它），
     但空盒子会照吃一份 gap，卡片看着就多出一截莫名的留白 */
  [data-scope='notification'][data-part='item-title']:empty,
  [data-scope='notification'][data-part='item-description']:empty {
    display: none;
  }

  [data-scope='notification'][data-part='item-title'][hidden],
  [data-scope='notification'][data-part='item-description'][hidden] {
    display: none;
  }

  /* 倒计时条横跨整张卡片：它不是正文的一部分，不跟着第二列走 */
  [data-scope='notification'][data-part='item'] > [data-part='item-progress'] {
    grid-column: 1 / -1;
  }

  /*
   * 倒计时条。总时长由连接层写进 --xh-notification-progress-duration（不自动消失的那些
   * 整条收起），计时被按住时动画一并停住——停表这件事此前没有任何可画的地方。
   * 取装饰档 --xh-_tone-soft：压在卡片底色上仍看得出来。
   */
  [data-scope='notification'][data-part='item-progress'] {
    --xh-_countdown-radius: var(--xh-notification-progress-radius, var(--xh-shape-pill));

    overflow: hidden;
    inline-size: 100%;
    block-size: var(--xh-notification-progress-thickness, var(--xh-space-0_5));
    border-radius: var(--xh-_countdown-radius);
    background: var(--xh-notification-progress-bg, var(--xh-_tone-soft));
    animation: xh-countdown var(--xh-notification-progress-duration, var(--xh-motion-duration-slide)) var(--xh-motion-ease-loop) forwards;
  }

  /* 裁切只认物理方向：RTL 下行尾在左边，从左往右收 */
  [data-scope='notification'][data-part='item-progress']:dir(rtl) {
    --xh-_countdown-cut-left: 100%;
    --xh-_countdown-cut-right: 0;
  }

  /* 减弱动效：倒计时不连续地缩，按秒一格一格走，段数由连接层随时长交出。
     两条规则是同一件事的两个触发条件：系统偏好与作者打的 data-motion */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='notification'][data-part='item-progress'] {
      animation-timing-function: steps(var(--xh-_notification-progress-steps, 1), end);
    }
  }

  :where([data-motion='reduce']) [data-scope='notification'][data-part='item-progress'] {
    animation-timing-function: steps(var(--xh-_notification-progress-steps, 1), end);
  }

  [data-scope='notification'][data-part='item'][data-paused] [data-part='item-progress'] {
    animation-play-state: paused;
  }

  [data-scope='notification'][data-part='item-progress'][hidden] {
    display: none;
  }

  /* 操作钮是带文案的离散动作钮：盒几何、悬停 / 按下与 0.97 按压、粗指针热区、焦点环、禁用面全由 Action Control
     的 text outline 档给（连接层投 sm；非 Button 的触发器缺省中性描边、透明底），组件只映射既有使用者槽。
     语气只落到左列字形：这颗钮坐在带 data-tone 的卡片里，底 / 边 / 字钉在中性语义面上，不随语气；
     卡片是 sheet 白面承载：hover --xh-bg-subtle（100）→ pressed --xh-bg-subtle-hover（200） */
  [data-scope='notification'][data-part='item-action-trigger'] {
    --xh-action-visual-size: var(--xh-notification-action-h, var(--xh-_action-profile-visual-size));
    --xh-action-padding-inline: var(--xh-notification-action-px, var(--xh-_action-profile-padding-inline));
    --xh-action-radius: var(--xh-notification-action-radius, var(--xh-shape-control));
    --xh-action-bg-rest: var(--xh-notification-action-bg, transparent);
    --xh-action-bg-hover: var(--xh-notification-action-bg-hover, var(--xh-bg-subtle));
    --xh-action-bg-pressed: var(--xh-notification-action-bg-active, var(--xh-bg-subtle-hover));
    --xh-action-fg-rest: var(--xh-notification-action-fg, var(--xh-fg-default));
    --xh-action-fg-hover: var(--xh-notification-action-fg, var(--xh-fg-default));
    --xh-action-fg-pressed: var(--xh-notification-action-fg, var(--xh-fg-default));
    --xh-action-border-rest: var(--xh-notification-action-border, var(--xh-border-control));
    --xh-action-border-hover: var(--xh-notification-action-border, var(--xh-border-control-hover));
    --xh-action-border-pressed: var(--xh-notification-action-border, var(--xh-border-control-hover));
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    /* 作者塞进钮里的图标按按钮档取字形尺寸 */
    --xh-icon-size: var(--xh-notification-icon-size, var(--xh-_action-profile-glyph-size));

    /* 网格列默认拉满，按钮要贴着起始侧收成自己的宽度 */
    justify-self: start;
    font-weight: var(--xh-notification-action-font-weight, var(--xh-font-weight-medium));
  }

  /* 家族那条 display 会把 UA 的 [hidden]{display:none} 盖掉 */
  [data-scope='notification'][data-part='item-action-trigger'][hidden] {
    display: none;
  }

  /* 关闭钮是只有字形的离散动作钮：盒几何、悬停 / 按下与 0.97 按压、粗指针热区、焦点环、禁用面全由 Action Control
     的 icon ghost 档给（连接层投 sm：32px 正方盒，面板角上的叉与此前 --xh-control-h-sm 同尺寸），组件只映射既有
     使用者槽。静息透明，sheet 白面承载 hover 100 → pressed 200，写了语气时悬停底跟着语气走（--xh-_tone-subtle）。
     钉在右上角的内衬处，不参与网格排布——留在流里它会变成正文下面的第三行 */
  [data-scope='notification'][data-part='item-close-trigger'] {
    --xh-action-visual-size: var(--xh-notification-close-size, var(--xh-_action-profile-visual-size));
    --xh-action-min-inline-size: var(--xh-notification-close-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-notification-close-radius, var(--xh-shape-control));
    --xh-action-bg-hover: var(--xh-notification-close-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-notification-close-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-notification-close-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-notification-close-fg-hover, var(--xh-fg-default));
    --xh-action-fg-pressed: var(--xh-notification-close-fg-hover, var(--xh-fg-default));
    --xh-action-border-rest: transparent;
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    /* 叉的字形按钮档取值（sm → 16px），与左列那枚 md 档的类型字形分开 */
    --xh-icon-size: var(--xh-notification-icon-size, var(--xh-_action-profile-glyph-size));

    position: absolute;
    inset-block-start: var(--xh-notification-close-inset, var(--xh-surface-action-inset));
    inset-inline-end: var(--xh-notification-close-inset, var(--xh-surface-action-inset));
    border-width: 0;
  }

  /* closable=false 时连接层同时给了 hidden 与 disabled，这条是它真正收起的那一半：
     家族那条 display 会把 UA 的 [hidden]{display:none} 盖掉，不补回来就会留下一个按不动的叉 */
  [data-scope='notification'][data-part='item-close-trigger'][hidden] {
    display: none;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中 */
  [data-scope='notification'][data-part='item-close-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }

  @media print {
    /* 打印：动画会被定格在任意一帧——转了一半的圈、扫到一半的微光。这里换成静止的表达，
       取值与减弱动效那一档相同。两档各写一块、不并进一条媒体查询列表：减弱动效另有一份
       :where([data-motion='reduce']) 的钩子版本与它成对，打印没有对应的钩子可配，
       并成一条之后这层配对关系在文本上就断了。 */
    /* 通知组固定在视口上，打印那一刻在场就会盖住正文。 */
    [data-scope='notification'][data-part='group'] {
      display: none;
    }

    [data-scope='notification'][data-part='item'][data-loading] [data-part='item-indicator']:empty::before {
      animation: none;
    }
  }
}

/* styles/number-field.css */
/* NumberField 独立皮肤同时传递引入字段视觉盒与字段内动作；full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='number-field'] {
    --xh-number-field-skin: 1;
  }

  /* 与文本框同一套堆叠：标签一行、输入行一行。
     control 是必需的唯一视觉盒，输入框、加减钮与前后缀都放在里面；
     输入与前后缀在左，减、加两颗动作依次收在逻辑末端。
     组件层只把既有公开槽映射到家族合同；形态三档由家族按 control 上的 data-variant 生成，皮肤不再声明。 */
  [data-scope='number-field'][data-part='root'] {
    /* 作者塞进来的图标跟着控件的尺寸档走；它自己写了 size 时仍以作者的为准 */
    --xh-icon-size: var(--xh-number-field-icon-size, var(--xh-glyph-size-md));

    /* 尺寸档只换这几个私有槽，输入框与加减钮都从 root 继承它们，
       换档不必给每个部件各写一条选择器 */
    --xh-_number-field-h: var(--xh-control-h-md);
    --xh-_number-field-px: var(--xh-control-px-md);
    --xh-_number-field-gap: 0;
    --xh-_number-field-font-size: var(--xh-control-font-md);
    --xh-_number-field-trigger-font-size: var(--xh-control-font-md);

    /* 盒内那道分隔线的长度：取钮高的一半，线的上下各留一截空白，不与钮等高 */
    --xh-_number-field-divider-h: 50%;

    display: inline-flex;
    flex-direction: column;
    gap: var(--xh-number-field-gap, var(--xh-space-1));

    /* 不传尺寸时一律这么宽，宽度不随内容走；父容器给不出这么宽时整件跟着收，地板同步让步，不越出父容器。
       地板不高过缺省宽：使用者把缺省宽钉到底线以下时不必再放开底线 */
    inline-size: var(--xh-number-field-control-w, var(--xh-control-w));
    min-inline-size: min(var(--xh-number-field-control-w, var(--xh-control-w)), var(--xh-number-field-control-min-w, var(--xh-control-min-w)), 100%);
    max-inline-size: 100%;
  }

  /* 声明了 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='number-field'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里 */
  [data-scope='number-field'][data-part='root'][data-size='sm'] {
    --xh-icon-size: var(--xh-number-field-icon-size, var(--xh-glyph-size-sm));
    --xh-_number-field-h: var(--xh-control-h-sm);
    --xh-_number-field-px: var(--xh-control-px-sm);
    --xh-_number-field-font-size: var(--xh-control-font-sm);
    --xh-_number-field-trigger-font-size: var(--xh-control-font-sm);
  }

  [data-scope='number-field'][data-part='root'][data-size='lg'] {
    --xh-icon-size: var(--xh-number-field-icon-size, var(--xh-glyph-size-lg));
    --xh-_number-field-h: var(--xh-control-h-lg);
    --xh-_number-field-px: var(--xh-control-px-lg);
    --xh-_number-field-font-size: var(--xh-control-font-lg);
    --xh-_number-field-trigger-font-size: var(--xh-control-font-lg);
  }

  [data-scope='number-field'][data-part='label'] {
    color: var(--xh-number-field-label-fg, var(--xh-fg-default));
    font-size: var(--xh-number-field-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-number-field-label-font-weight, var(--xh-text-label-weight));
  }

  [data-scope='number-field'][data-part='label'][data-disabled] {
    color: var(--xh-number-field-label-fg-disabled, var(--xh-fg-subtle));
  }

  /* —— 一体式 control：输入框与加减钮同框 —— */
  /* control 是唯一的视觉盒：描边、底色、圆角、聚焦环、五态与悬停由 Field Chrome 家族画，
     盒内三件都退成透明分段，整枚控件从头到尾只有这一道描边。
     外观槽按所在部件取名 --xh-number-field-control-*；--xh-number-field-input-* 只管
     input 自己的字色与内衬。控件不给内衬：内衬走 input 与钮各自的盒。 */
  [data-scope='number-field'][data-part='control'] {
    --xh-field-control-height: var(--xh-number-field-control-h, var(--xh-_number-field-h));
    --xh-field-control-padding-inline: var(--xh-number-field-control-px, 0);
    --xh-field-control-gap: var(--xh-number-field-control-gap, var(--xh-_number-field-gap));
    --xh-field-control-min-inline-size: var(--xh-number-field-control-min-w, var(--xh-control-min-w));
    --xh-field-control-radius: var(--xh-number-field-control-radius, var(--xh-shape-control));
    --xh-field-bg-rest: var(--xh-number-field-control-bg, var(--xh-_field-variant-bg-rest));
    --xh-field-bg-hover: var(--xh-number-field-control-bg-hover, var(--xh-_field-variant-bg-hover));
    --xh-field-bg-read-only: var(--xh-number-field-control-bg-readonly, var(--xh-_field-variant-bg-read-only));
    --xh-field-bg-disabled: var(--xh-number-field-control-bg-disabled, var(--xh-_field-variant-bg-disabled));
    --xh-field-fg-rest: var(--xh-number-field-control-fg, var(--xh-fg-default));
    --xh-field-border-rest: var(--xh-number-field-control-border, var(--xh-_field-variant-border-rest));
    --xh-field-border-hover: var(--xh-number-field-control-border-hover, var(--xh-_field-variant-border-hover));
    --xh-field-border-focus: var(--xh-number-field-control-border-focus, var(--xh-_field-variant-border-focus));
    --xh-field-border-invalid: var(--xh-number-field-control-border-invalid, var(--xh-_field-variant-border-invalid));
    --xh-field-ring-focus: var(--xh-ring-focus);
    --xh-field-ring-invalid: var(--xh-ring-invalid);
    --xh-field-shadow-rest: var(--xh-number-field-control-shadow, none);
    /* 家族 chrome 会重写 --xh-icon-size，使用者图标槽必须经桥接槽下发才能在盒内生效 */
    --xh-field-glyph-size: var(--xh-number-field-icon-size, var(--xh-_field-size-glyph-size));

    position: relative;
  }

  /* 装饰段：货币符、单位、图标。与输入框同框，不参与分宽，弱一档前景把它与数字分开 */
  [data-scope='number-field'][data-part='prefix'],
  [data-scope='number-field'][data-part='suffix'] {
    --xh-field-affix-fg: var(--xh-number-field-affix-fg, var(--xh-fg-muted));
    --xh-field-affix-fg-disabled: var(--xh-number-field-affix-fg-disabled, var(--xh-fg-disabled));
    --xh-field-affix-font-size: var(--xh-number-field-affix-font-size, var(--xh-_number-field-font-size));
  }

  [data-scope='number-field'][data-part='prefix'][hidden],
  [data-scope='number-field'][data-part='suffix'][hidden] {
    display: none;
  }

  /* 盒内 input：无边框无底无圆角无落影由家族重置，观感全归 control。
     数字居中排在两个按钮之间，行内内衬留给它自己（control 不给内衬）；
     前后缀图标/文字直接流式排在 input 两侧，不用再绝对定位 */
  [data-scope='number-field'][data-part='control'] [data-part='input'] {
    --xh-field-input-fg: var(--xh-number-field-input-fg, var(--xh-fg-default));
    --xh-field-input-font-size: var(--xh-number-field-input-font-size, var(--xh-_number-field-font-size));
    --xh-field-placeholder-fg: var(--xh-number-field-placeholder-fg, var(--xh-fg-subtle));
    --xh-field-autofill-bg: var(--xh-number-field-input-autofill-bg, var(--xh-bg-canvas));
    --xh-field-autofill-fg: var(--xh-number-field-input-autofill-fg, var(--xh-fg-default));

    inline-size: var(--xh-number-field-input-w, 5em);
    padding-inline: var(--xh-number-field-input-px, var(--xh-_number-field-px));
    font-variant-numeric: tabular-nums;
    text-align: var(--xh-number-field-input-align, center);
  }

  /* 盒内按钮：正方视觉盒、inset 圆角、悬停 100 / 按下 200 与 0.97 按压、粗指针热区与
     :focus-visible 关环全由 Action Control 的 field-inset ghost 档给，组件只映射既有覆盖槽。
     常态只剩符号，符号取默认前景，悬停与按下才浮出底色 */
  [data-scope='number-field'][data-part='control'] [data-part='increment-trigger'],
  [data-scope='number-field'][data-part='control'] [data-part='decrement-trigger'] {
    --xh-action-visual-size: var(--xh-number-field-trigger-size, var(--xh-_action-profile-visual-size));
    --xh-action-min-inline-size: var(--xh-number-field-trigger-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-number-field-trigger-radius, var(--xh-shape-inset));
    /* 底色阶梯由 ghost 档给（透明 → 100 → 200），使用者槽只作覆盖入口 */
    --xh-action-bg-pressed: var(--xh-number-field-trigger-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-number-field-trigger-fg, var(--xh-fg-default));
    --xh-action-fg-hover: var(--xh-number-field-trigger-fg-hover, var(--xh-fg-default));
    --xh-action-border-rest: transparent;
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    --xh-action-font-size: var(--xh-number-field-trigger-font-size, var(--xh-_number-field-trigger-font-size));
    /* 配方尚未把 profile 字形档灌进 --xh-icon-size，钮内字形先按 field-inset 档逐钮取值 */
    --xh-icon-size: var(--xh-_action-profile-glyph-size);

    border-width: 0;
  }

  /* DOM 顺序不承担视觉位置：既有用法即使把减钮写在 input 前面，默认仍统一收进右侧动作组。 */
  [data-scope='number-field'][data-part='control'] [data-part='decrement-trigger'] {
    order: 1;
  }

  [data-scope='number-field'][data-part='control'] [data-part='increment-trigger'] {
    order: 2;
  }

  [data-scope='number-field'][data-part='control'] [data-part='increment-trigger'][hidden],
  [data-scope='number-field'][data-part='control'] [data-part='decrement-trigger'][hidden] {
    display: none;
  }

  /* 右侧动作组与输入之间的细线：把「按的」与「填的」分成两块。
     线不画在钮的边框上：边框会跟着钮的圆角与悬停底走，而这道线要独立于钮的各态，长度也短于钮自己。
     ::before 已被兜底字形占着，::after 在粗指针下是家族给的 44px 热区，几何只能落在
     background-image 上：一条 1px × 半高的渐变贴在逻辑起始侧，底色换态时它仍叠在上层。
     线只画在动作组第一颗减钮的逻辑起始侧；background-position 是物理轴，RTL 另给一条换边。 */
  [data-scope='number-field'][data-part='control']:has([data-part='input']) [data-part='decrement-trigger'] {
    background-image: linear-gradient(
      var(--xh-number-field-trigger-divider, var(--xh-material-soft-separator)),
      var(--xh-number-field-trigger-divider, var(--xh-material-soft-separator))
    );
    background-repeat: no-repeat;
    background-position: 0 50%;
    background-size: var(--xh-stroke-thin) var(--xh-number-field-trigger-divider-h, var(--xh-_number-field-divider-h));
  }

  [dir='rtl'] [data-scope='number-field'][data-part='control']:has([data-part='input']) [data-part='decrement-trigger'] {
    background-position: 100% 50%;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中 */
  [data-scope='number-field'][data-part='control'] [data-part='increment-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-plus) center / contain no-repeat;
    mask: var(--xh-glyph-mark-plus) center / contain no-repeat;
  }

  [data-scope='number-field'][data-part='control'] [data-part='decrement-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-minus) center / contain no-repeat;
    mask: var(--xh-glyph-mark-minus) center / contain no-repeat;
  }

  /* 高对比档整层丢弃 background-image，分隔线改用系统色重画，并关掉这一颗钮的强制换色 */
  @media (forced-colors: active) {
    [data-scope='number-field'][data-part='control']:has([data-part='input']) [data-part='decrement-trigger'] {
      background-image: linear-gradient(ButtonText, ButtonText);
      forced-color-adjust: none;
    }
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='number-field'][data-part='control'][hidden] {
    display: none;
  }
}

/* styles/pagination.css */
/* 定义 pagination 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立；四类格子接 Action Control 配方，同理 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='pagination'] {
    --xh-pagination-skin: 1;
  }

  /* 私有槽同时声明在根与 positioner 上：摊开的页码面板被搬到 portal 落点，
     不是根的后代，继承不过去。面板里的页码格子与主区那排消费的是同一批槽 */
  [data-scope='pagination']:is([data-part='root'], [data-part='positioner']) {
    /* 作者塞进面板或分页行里的图标按档取字形尺；四类格子上另按家族档位取同一把尺 */
    --xh-icon-size: var(--xh-pagination-icon-size, var(--xh-glyph-size-md));

    /* 尺寸档只换这三个私有槽，上一页/下一页、页码与省略号都从这两处继承它们，
       换档不必给每个部件各写一条选择器 */
    --xh-_pagination-item-size: var(--xh-control-h-md);
    --xh-_pagination-item-px: var(--xh-control-px-md);
    --xh-_pagination-font-size: var(--xh-control-font-md);

    /* 当前页的选中态随语气走。没写 data-tone 时这几个 --xh-_tone-* 都没被声明，
       退回原来的品牌底与其配色。聚焦环不在其列，它恒是 --xh-ring-focus */
    --xh-_pagination-selected-bg: var(--xh-_tone, var(--xh-bg-brand));
    --xh-_pagination-selected-bg-hover: var(--xh-_tone-hover, var(--xh-bg-brand-hover));
    --xh-_pagination-selected-bg-active: var(--xh-_tone-active, var(--xh-bg-brand-active));
    --xh-_pagination-selected-fg: var(--xh-_tone-on, var(--xh-fg-on-brand));
    /* 当前页那一格是实心底，顶边画一条极浅的内高光把它衬出厚度（solid 面允许顶高光，经家族的 highlight 槽画） */
    --xh-_pagination-highlight: var(--xh-_highlight-tone);
  }

  /* 根节点是 nav 地标，只负责把上一页 / 页码 / 下一页排成一行。
     页数为 0 时连接层会打 data-empty，这里不拿它做隐藏：作者常把「第 x-y 条」这类
     区间回显也写在 nav 里，整块藏掉会连那行字一起吞了，是否隐藏交给作者决定 */
  [data-scope='pagination'][data-part='root'] {
    display: flex;
    align-items: center;
    /* 页码多到一行放不下就换行，宁可折行也不要把按钮压扁或撑出横向滚动 */
    flex-wrap: wrap;
    gap: var(--xh-pagination-gap, var(--xh-space-1));
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里。格子高度、内边距、字号三者各走控件尺的同一档；
     页码格子靠最小宽度撑等宽，内边距只在页码超出最小宽度时才起作用 */
  [data-scope='pagination']:is([data-part='root'], [data-part='positioner'])[data-size='sm'] {
    --xh-icon-size: var(--xh-pagination-icon-size, var(--xh-glyph-size-sm));
    --xh-_pagination-item-size: var(--xh-control-h-sm);
    --xh-_pagination-item-px: var(--xh-control-px-sm);
    --xh-_pagination-font-size: var(--xh-control-font-sm);
  }

  [data-scope='pagination']:is([data-part='root'], [data-part='positioner'])[data-size='lg'] {
    --xh-icon-size: var(--xh-pagination-icon-size, var(--xh-glyph-size-lg));
    --xh-_pagination-item-size: var(--xh-control-h-lg);
    --xh-_pagination-item-px: var(--xh-control-px-lg);
    --xh-_pagination-font-size: var(--xh-control-font-lg);
  }

  [data-scope='pagination'][data-part='root'][hidden] {
    display: none;
  }

  /* 四类格子接 Action Control 的 text 档，缺省中性的 ghost 形态（只有 Button 品牌实心）：盒型、三档几何、
     透明描边（省略号也占一条，两者内容盒等高，一行里对得齐）、悬停 100 → 按下 200（画布承载）、禁用面、按压缩放与
     过渡都由家族给；这里只把使用者槽映射到桥接槽并保留分页自己的排版。
     等宽的关键：1 与 10 的内容宽度不同，靠最小宽度把它们撑到同一格，行宽才不会随当前页左右抖动 */
  [data-scope='pagination'][data-part='prev-trigger'],
  [data-scope='pagination'][data-part='next-trigger'],
  [data-scope='pagination'][data-part='item'],
  [data-scope='pagination'][data-part='ellipsis-trigger'] {
    --xh-action-min-inline-size: var(--xh-pagination-item-min-size, var(--xh-_pagination-item-size));
    --xh-action-visual-size: var(--xh-pagination-item-h, var(--xh-_pagination-item-size));
    --xh-action-padding-inline: var(--xh-pagination-item-px, var(--xh-_pagination-item-px));
    --xh-action-radius: var(--xh-pagination-item-radius, var(--xh-shape-control));
    --xh-action-font-size: var(--xh-pagination-font-size, var(--xh-_pagination-font-size));
    --xh-action-bg-rest: var(--xh-pagination-item-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-pagination-item-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-pagination-item-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-pagination-item-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-pagination-item-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-pagination-item-fg, var(--xh-_action-variant-fg-pressed));
    /* 作者塞进上一页/下一页的图标按档取字形尺，与皮肤画的兜底字形同一把尺 */
    --xh-icon-size: var(--xh-pagination-icon-size, var(--xh-_action-profile-glyph-size));

    flex: none;
    font-weight: var(--xh-pagination-item-font-weight, var(--xh-text-label-weight));
    /* 等宽数字：1 与 7 的字形宽度在比例字体里并不相同，不定住会让同位数页码抖一格 */
    font-variant-numeric: tabular-nums;
  }

  [data-scope='pagination'][data-part='prev-trigger'][hidden],
  [data-scope='pagination'][data-part='next-trigger'][hidden],
  [data-scope='pagination'][data-part='item'][hidden],
  [data-scope='pagination'][data-part='ellipsis-trigger'][hidden] {
    display: none;
  }

  /* 首末页的上一页 / 下一页是原生 disabled（不可聚焦、进不了 Tab 序列），连接层同时给 data-disabled，
     家族按 data-disabled 画禁用面（透明底 + --xh-fg-disabled）；分页条目从不禁用 */

  /* 当前页（格状当前）：data-current 与 aria-current='page' 由连接层成对给出，样式挂在 data 钩子上，
     无障碍语义留给 aria。实心品牌面 + 配对前景、不加粗——字重一变字形就变宽，页码格子会跟着长一点，
     正是这里要避免的抖动；悬停 / 按下沿 brand → brand-hover → brand-active 走，三态都经桥接槽交给家族画，
     solid 面允许一条顶高光，环色改取面自己的前景 */
  [data-scope='pagination'][data-part='item'][data-current] {
    --xh-action-bg-rest: var(--xh-pagination-item-bg-selected, var(--xh-_pagination-selected-bg));
    --xh-action-bg-hover: var(--xh-pagination-item-bg-selected-hover, var(--xh-_pagination-selected-bg-hover));
    --xh-action-bg-pressed: var(--xh-pagination-item-bg-selected-active, var(--xh-_pagination-selected-bg-active));
    --xh-action-bg-focus-visible: var(--xh-pagination-item-bg-selected, var(--xh-_pagination-selected-bg));
    --xh-action-fg-rest: var(--xh-pagination-item-fg-selected, var(--xh-_pagination-selected-fg));
    --xh-action-fg-hover: var(--xh-pagination-item-fg-selected, var(--xh-_pagination-selected-fg));
    --xh-action-fg-pressed: var(--xh-pagination-item-fg-selected, var(--xh-_pagination-selected-fg));
    --xh-action-fg-focus-visible: var(--xh-pagination-item-fg-selected, var(--xh-_pagination-selected-fg));
    --xh-action-border-rest: var(--xh-pagination-item-border-selected, var(--xh-_pagination-selected-bg));
    --xh-action-border-hover: var(--xh-pagination-item-border-selected-hover, var(--xh-_pagination-selected-bg-hover));
    --xh-action-border-pressed: var(--xh-pagination-item-border-selected-active, var(--xh-_pagination-selected-bg-active));
    --xh-action-border-focus-visible: var(--xh-pagination-item-border-selected, var(--xh-_pagination-selected-bg));
    --xh-action-highlight-rest: var(--xh-_pagination-highlight);
    --xh-action-highlight-hover: var(--xh-_pagination-highlight);
    --xh-action-highlight-pressed: var(--xh-_pagination-highlight);
    --xh-action-highlight-focus-visible: var(--xh-_pagination-highlight);
    --xh-action-shadow-rest: var(--xh-pagination-item-shadow, none);
    --xh-action-shadow-hover: var(--xh-pagination-item-shadow, none);
    --xh-action-shadow-pressed: var(--xh-pagination-item-shadow, none);
    --xh-action-shadow-focus-visible: var(--xh-pagination-item-shadow, none);
    --xh-action-ring-color-focus-visible: currentColor;
  }

  /* 省略位是可展开的按钮：折进去的那几页只有它一个入口，指针与键盘都得点得到，
     所以它与页码同一副骨架、同一条阶梯。这里只把字色压淡一档与页码区分开，三态都压——
     家族的悬停 / 按下规则比基础块特定，只映射静息那一支会在悬停时被换回缺省字色 */
  [data-scope='pagination'][data-part='ellipsis-trigger'] {
    --xh-action-fg-rest: var(--xh-pagination-ellipsis-trigger-fg, var(--xh-fg-subtle));
    --xh-action-fg-hover: var(--xh-pagination-ellipsis-trigger-fg, var(--xh-fg-subtle));
    --xh-action-fg-pressed: var(--xh-pagination-ellipsis-trigger-fg, var(--xh-fg-subtle));
  }
  /* 每页条数控制器的挂载点：里头装的是库里的 select，控件本身的描边、底色、聚焦环与
     浮层都归 select 那份皮肤，这一格只把它摆进分页行 */
  [data-scope='pagination'][data-part='page-size-select'] {
    display: inline-flex;
    flex: none;
    align-items: center;
  }

  [data-scope='pagination'][data-part='page-size-select'][hidden] {
    display: none;
  }

  /* 信息区：一段次要文字，与页码格子同一条基线 */
  [data-scope='pagination'][data-part='summary'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    block-size: var(--xh-pagination-item-h, var(--xh-_pagination-item-size));
    color: var(--xh-pagination-summary-fg, var(--xh-fg-muted));
    font-size: var(--xh-pagination-font-size, var(--xh-_pagination-font-size));
    line-height: var(--xh-leading-none);
    white-space: nowrap;
  }

  [data-scope='pagination'][data-part='summary'][hidden] {
    display: none;
  }

  /* 跳页输入框：与每页条数控制器同一副外观，宽度按页码位数留够 */
  [data-scope='pagination'][data-part='jumper'] {
    flex: none;
    inline-size: var(--xh-pagination-jumper-w, calc(var(--xh-space-8) * 2));
    block-size: var(--xh-pagination-item-h, var(--xh-_pagination-item-size));
    padding-inline: var(--xh-pagination-item-px, var(--xh-_pagination-item-px));
    border: var(--xh-stroke-thin) solid var(--xh-pagination-jumper-border, var(--xh-border-default));
    border-radius: var(--xh-pagination-item-radius, var(--xh-shape-control));
    background: var(--xh-pagination-jumper-bg, var(--xh-bg-surface));
    color: var(--xh-pagination-item-fg, var(--xh-fg-default));
    font-size: var(--xh-pagination-font-size, var(--xh-_pagination-font-size));
    line-height: var(--xh-leading-none);
    appearance: none;
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      border-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='pagination'][data-part='jumper'][hidden] {
    display: none;
  }

  [data-scope='pagination'][data-part='jumper']:hover:not(:disabled) {
    border-color: var(--xh-pagination-jumper-border-hover, var(--xh-border-strong));
    background: var(--xh-pagination-jumper-bg-hover, var(--xh-bg-subtle-hover));
  }

  [data-scope='pagination'][data-part='jumper']:disabled {
    color: var(--xh-fg-disabled);
  }

  /* 摊开省略位的定位层。三处坐标系必须同为 fixed：机器交给引擎的 strategy、
     连接层的内联 position、这里 —— 差一处就会算在错的坐标系里 */
  [data-scope='pagination'][data-part='positioner'] {
    /* 落定那一侧的可用高度，由定位引擎经内联自定义属性写进来，面板继承它限高；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时不额外限高 */
    --xh-_pagination-available-h: 100vh;
    /* 落定那一侧的可用宽度，同样由定位引擎经内联自定义属性写进来，行内轴据此夹取；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时退到视口宽 */
    --xh-_pagination-available-w: 100vw;

    /* 页码面板的自绘条浮在内容之上：轨道不上底色，实色轨道会在面板右缘糊一条竖灰带 */
    --xh-scrollbar-track-bg: transparent;

    position: fixed;
    z-index: var(--xh-pagination-layer, var(--xh-_layer, var(--xh-layer-popover)));
    /* 空壳不吃指针：省略位与面板之间那段间隙要能点得穿 */
    pointer-events: none;
  }

  /* 锚点被滚出可视区：整个浮层随之收起 */
  [data-scope='pagination'][data-part='positioner'][data-hidden] {
    visibility: hidden;
  }

  /* 摊开的页码面板：一串页码格子，横着排、必要时折行 */
  [data-scope='pagination'][data-part='content'] {
    display: flex;
    flex-flow: row wrap;
    gap: var(--xh-pagination-gap, var(--xh-space-1));
    /* 页码不可预知有多少：不限高就整块伸出视口且滚不到 */
    /* 静态档与落位后的可用宽度取小：窄视口下面板伸出去，最右侧的内容就点不到了 */
    max-inline-size: min(var(--xh-pagination-content-max-w, var(--xh-overlay-max-w)), var(--xh-_pagination-available-w));
    max-block-size: min(
      var(--xh-pagination-content-max-h, var(--xh-overlay-max-h)),
      var(--xh-_pagination-available-h)
    );
    overflow-y: auto;
    /* 浮层滚动面：滚到底不把滚动量交给页面（只给 Overlay 家族滚动面） */
    overscroll-behavior: contain;
    padding: var(--xh-pagination-content-p, var(--xh-space-1));
    border: var(--xh-stroke-thin) solid var(--xh-pagination-content-border, var(--xh-border-default));
    border-radius: var(--xh-pagination-content-radius, var(--xh-shape-overlay));
    background: var(--xh-pagination-content-bg, var(--xh-bg-surface));
    box-shadow: var(--xh-pagination-content-shadow, var(--xh-elevation-floating));
    /* 定位层不吃指针，面板本体必须吃：里面的页码要点得到 */
    pointer-events: auto;
  }

  [data-scope='pagination'][data-part='content'][data-state='open'] {
    animation: xh-pop-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 退场：收起那一帧 hidden 由退场闸门押后，这里才播得出来。forwards 把末态钉住，
     免得动画结束到真收起之间闪一下原样 */
  [data-scope='pagination'][data-part='content'][data-state='closed'] {
    animation: xh-pop-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* 这里刻意没有 [data-part='content'][hidden] { display: none }：
     补了退场就一帧都播不出来，真正的收起由适配器落成内联 display */

  /* 没写内容就由皮肤画兜底字形：上一页/下一页默认就是两枚箭头，
     作者往部件里塞了自己的图形或文字，这两条即不命中 */
  [data-scope='pagination'][data-part='prev-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-left) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-left) center / contain no-repeat;
  }

  [data-scope='pagination'][data-part='next-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
  }

  /* 省略位不写内容时画三点：折进去那几页的入口，空着就是一格看不出能点的空白 */
  [data-scope='pagination'][data-part='ellipsis-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-ellipsis) center / contain no-repeat;
    mask: var(--xh-glyph-mark-ellipsis) center / contain no-repeat;
  }

  /* rtl 下页序从右往左走，箭头跟着指向行进方向 */
  [dir='rtl'] [data-scope='pagination'][data-part='prev-trigger']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-chevron-right);
    mask-image: var(--xh-glyph-mark-chevron-right);
  }

  [dir='rtl'] [data-scope='pagination'][data-part='next-trigger']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-chevron-left);
    mask-image: var(--xh-glyph-mark-chevron-left);
  }

  /* 手指落点：命中区由绝对定位的伪元素向块轴两侧外扩，格子的盒一点不动——
     加高格子会把整条 nav 撑高，行宽也会跟着当前页抖。
     只扩块轴：格与格在行内轴上只隔一格间距，往两侧扩会与相邻格的命中区叠上。
     取 8px 是按最矮的 sm 档算的（28 + 8 × 2 = 44），md 与 lg 档更宽裕。
     用 ::after：::before 已经被两枚箭头的兜底字形占着 */
  @media (pointer: coarse) {
    [data-scope='pagination'][data-part='prev-trigger'],
    [data-scope='pagination'][data-part='next-trigger'],
    [data-scope='pagination'][data-part='item'] {
      position: relative;
    }

    [data-scope='pagination'][data-part='prev-trigger']::after,
    [data-scope='pagination'][data-part='next-trigger']::after,
    [data-scope='pagination'][data-part='item']::after {
      content: '';
      position: absolute;
      inset-block: -8px;
      inset-inline: 0;
    }
  }

  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。 */
    [data-scope='pagination'][data-part='positioner'] {
      display: none;
    }

    /* 打印默认丢背景：当前页那格的实心底印不出来，一排页码看上去完全一样。
       改用字重表达同一件事——常态之所以不加粗是怕格子变宽、行宽跟着抖，纸上没有这回事 */
    [data-scope='pagination'][data-part='item'][data-current] {
      font-weight: var(--xh-font-weight-semibold);
    }
  }
}

/* styles/pin-input.css */
/* PinInput 独立皮肤传递引入字段视觉盒：每一格 input 自身就是 Field Chrome 的 chrome 节点；full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='pin-input'] {
    --xh-pin-input-skin: 1;
  }

  /* 与文本框、数字框同一套堆叠：标签一行、格子一行。
     格子的描边、底、圆角、五态与悬停由 Field Chrome 家族按格子上的 data-variant 生成，皮肤不再声明形态三档 */
  [data-scope='pin-input'][data-part='root'] {
    /* 尺寸档只换这三个私有槽，格子与分隔都从 root 继承它们，换档不必给每个部件各写一条选择器 */
    --xh-_pin-input-box-size: var(--xh-control-box-md);
    --xh-_pin-input-box-gap: var(--xh-control-gap-md);
    --xh-_pin-input-box-font-size: var(--xh-text-heading-3-size);
    /* 填满态的强调色随语气走。没写 data-tone 时 --xh-_tone 没被声明，退回品牌色 */
    --xh-_pin-input-accent: var(--xh-_tone, var(--xh-bg-brand));

    display: inline-flex;
    flex-direction: column;
    gap: var(--xh-pin-input-gap, var(--xh-space-1));
    /* 每格都有定宽，一行格子的最小宽度就是这些定宽之和，收缩到边框盒之内不再有余地：
       不封顶的话整块控件按这个和撑开，比容器宽多少就顶出多少。
       封到容器那么宽，格子那条收缩才有得可收 */
    max-inline-size: 100%;
  }

  /* 声明了 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='pin-input'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 尺寸 —— */
  [data-scope='pin-input'][data-part='root'][data-size='sm'] {
    --xh-_pin-input-box-size: var(--xh-control-box-sm);
    --xh-_pin-input-box-gap: var(--xh-control-gap-sm);
    --xh-_pin-input-box-font-size: var(--xh-control-font-lg);
  }

  /* 格子是正方形，缺省档已经占到控件高度表的顶档，lg 档由顶档加一格间距合成，不另立数值 */
  [data-scope='pin-input'][data-part='root'][data-size='lg'] {
    --xh-_pin-input-box-size: var(--xh-control-box-lg);
    --xh-_pin-input-box-gap: var(--xh-control-gap-lg);
    --xh-_pin-input-box-font-size: var(--xh-text-heading-2-size);
  }

  [data-scope='pin-input'][data-part='label'] {
    color: var(--xh-pin-input-label-fg, var(--xh-fg-default));
    font-size: var(--xh-pin-input-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-pin-input-label-font-weight, var(--xh-text-label-weight));
  }

  [data-scope='pin-input'][data-part='label'][data-disabled] {
    color: var(--xh-pin-input-label-fg-disabled, var(--xh-fg-subtle));
  }

  /* 分段：连着的几格圈成一段。它只排版，格间距仍由格子自己的相邻兄弟规则给 */
  [data-scope='pin-input'][data-part='group'] {
    display: inline-flex;
    align-items: center;
  }

  [data-scope='pin-input'][data-part='group'][hidden] {
    display: none;
  }

  /* 段间分隔：两段之间的一道短横或圆点，两侧各留一格间距 */
  [data-scope='pin-input'][data-part='separator'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    margin-inline: var(--xh-pin-input-separator-gap, var(--xh-_pin-input-box-gap));
    color: var(--xh-pin-input-separator-fg, var(--xh-fg-muted));
    font-size: var(--xh-pin-input-separator-font-size, var(--xh-_pin-input-box-font-size));
    line-height: var(--xh-leading-none);
    user-select: none;
  }

  [data-scope='pin-input'][data-part='separator'][hidden] {
    display: none;
  }

  [data-scope='pin-input'][data-part='separator'][data-disabled] {
    color: var(--xh-pin-input-separator-fg-disabled, var(--xh-fg-disabled));
  }

  /* 每格是等宽方框：它自身就是 Field Chrome 的 chrome 节点，宽高同取一个尺寸，内边距归零。
     留了内边距，单字符居中后可用宽度不足，中文与全角字符会被挤出框外。
     组件层只把既有公开槽映射到家族合同；不投影 data-xh-field-input，否则家族会把格子的边框重置掉 */
  [data-scope='pin-input'][data-part='input'] {
    --xh-field-control-height: var(--xh-pin-input-box-size, var(--xh-_pin-input-box-size));
    --xh-field-control-padding-inline: 0;
    --xh-field-control-gap: 0;
    --xh-field-control-min-inline-size: 0;
    --xh-field-control-radius: var(--xh-pin-input-box-radius, var(--xh-shape-control));
    --xh-field-bg-rest: var(--xh-pin-input-box-bg, var(--xh-_field-variant-bg-rest));
    --xh-field-bg-hover: var(--xh-pin-input-box-bg-hover, var(--xh-_field-variant-bg-hover));
    --xh-field-bg-read-only: var(--xh-pin-input-box-bg-readonly, var(--xh-_field-variant-bg-read-only));
    --xh-field-bg-disabled: var(--xh-pin-input-box-bg-disabled, var(--xh-_field-variant-bg-disabled));
    --xh-field-fg-rest: var(--xh-pin-input-box-fg, var(--xh-fg-default));
    --xh-field-border-rest: var(--xh-pin-input-box-border, var(--xh-_field-variant-border-rest));
    --xh-field-border-hover: var(--xh-pin-input-box-border-hover, var(--xh-_field-variant-border-hover));
    --xh-field-border-focus: var(--xh-pin-input-box-border-focus, var(--xh-_field-variant-border-focus));
    --xh-field-border-invalid: var(--xh-pin-input-box-border-invalid, var(--xh-_field-variant-border-invalid));
    --xh-field-ring-focus: var(--xh-ring-focus);
    --xh-field-ring-invalid: var(--xh-ring-invalid);
    --xh-field-shadow-rest: var(--xh-pin-input-box-shadow, none);

    /* 一行放不下时逐格收窄，收不动就整行顶出屏幕。
       min-inline-size 归零解开表单控件那份按字符数算出来的自动最小宽度。
       高度不跟着收：它取自控件高度尺，与同一行里别的控件对齐靠的就是这个数。
       宽度放得下时收窄量为零，格子仍是尺寸档给的那个正方形。 */
    flex: 0 1 auto;
    min-inline-size: 0;
    inline-size: var(--xh-pin-input-box-size, var(--xh-_pin-input-box-size));
    padding: 0;
    /* 表单控件不继承页面字体，只给字号会让格子用 UA 默认字族 */
    font-family: inherit;
    font-size: var(--xh-pin-input-box-font-size, var(--xh-_pin-input-box-font-size));
    /* 等宽数字：各位字宽不一时逐格填入会让每格里的字符左右跳 */
    font-variant-numeric: tabular-nums;
    line-height: var(--xh-leading-none);
    text-align: center;
  }

  /* 格间距只能长在格子自己身上：包住这一行的容器是作者写的，不在角色表里，
     指望它给 gap 就等于把间距交给了皮肤管不着的地方。
     用相邻兄弟而不是给每格加外边距，是为了不在首尾多出两段空白 */
  [data-scope='pin-input'][data-part='input'] + [data-scope='pin-input'][data-part='input'] {
    margin-inline-start: var(--xh-pin-input-box-gap, var(--xh-_pin-input-box-gap));
  }

  [data-scope='pin-input'][data-part='input']::placeholder {
    color: var(--xh-pin-input-placeholder-fg, var(--xh-fg-subtle));
  }

  /* 一行格子长得一模一样，光标那道竖线太细，看不出正在填哪一格：
     当前格必须有明显的环。data-focus 由机器给（它知道谁是当前格），
     家族的 :focus-within 兜住机器状态还没回流的那一帧，两条同时写不冲突。
     焦点边一律家族的 --xh-border-control-focus，不随 tone */
  [data-scope='pin-input'][data-part='input'][data-focus] {
    border-color: var(--xh-pin-input-box-border-focus, var(--xh-_field-variant-border-focus));
    outline: var(--xh-ring-width) solid var(--xh-ring-focus);
    outline-offset: var(--xh-ring-offset);
  }

  /* 校验失败时环也跟着变红：两圈等宽相邻却一红一蓝，读的人不知道哪个才是当前状态 */
  [data-scope='pin-input'][data-part='input'][data-invalid][data-focus] {
    outline-color: var(--xh-ring-invalid);
  }

  /* 填满只代表"格子都有字"，不代表"验证码对"，所以用品牌色而不是成功色收个尾。
     已经标了 invalid 的不在此列——那是明确说了不对 */
  [data-scope='pin-input'][data-part='root'][data-complete]
    [data-scope='pin-input'][data-part='input']:not([data-invalid], :disabled) {
    border-color: var(--xh-pin-input-box-border-complete, var(--xh-_pin-input-accent));
  }

  /* 自动填充：一次性验证码由平台直接灌进这一行格子，引擎顺手给每格强加一套系统色
     （多数是黄底黑字），盖得过 background 与 color，深色档下就剩一行不跟主题走的黄方块。
     格子没投影 data-xh-field-input，家族那两条 autofill 命不中，这里自写一份：
     底改用 inset 阴影铺回来，扩散量 100vmax 填满内容盒；字改用 -webkit-text-fill-color
     接回来，那是这个态下唯一还听样式表的前景通道。
     不去拉长 transition 把系统底推迟显现：那只是把它藏起来，减弱动效通道一关过渡就当场露出。
     两个选择器名分写两条：一条选择器列表里只要有一个名字不被认识，整条规则就被丢弃。
     底取一支不透明的面令牌而不是家族的形态底：后者在 ghost 档下是透明的，铺一层透明等于没铺。 */
  [data-scope='pin-input'][data-part='input']:autofill {
    box-shadow: inset 0 0 0 100vmax var(--xh-pin-input-box-autofill-bg, var(--xh-bg-canvas));
    -webkit-text-fill-color: var(--xh-pin-input-box-autofill-fg, var(--xh-fg-default));
  }

  [data-scope='pin-input'][data-part='input']:-webkit-autofill {
    box-shadow: inset 0 0 0 100vmax var(--xh-pin-input-box-autofill-bg, var(--xh-bg-canvas));
    -webkit-text-fill-color: var(--xh-pin-input-box-autofill-fg, var(--xh-fg-default));
  }

  /* 连接层把它写成 type=hidden，UA 自己就不渲染；这里的视觉隐藏是给元素升级前那一瞬兜底
     （作者手写的是一个普通 input，升级完成前它是可见的文本框）。
     刻意不写 display：写了反而会盖掉 UA 对 type=hidden 的收起，把它显出来 */
  [data-scope='pin-input'][data-part='hidden-input'] {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    border: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    pointer-events: none;
  }
}

/* styles/popover.css */
/* 定义 popover 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='popover'] {
    --xh-popover-skin: 1;
  }

  /* 坐标由定位引擎写进 style（inset-inline-start / inset-block-start），这里只定位模式与层级 */
  [data-scope='popover'][data-part='positioner'] {
    /* 落定那一侧的可用高度，由定位引擎经内联自定义属性写进来，内容层继承它限高；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时不额外限高 */
    --xh-_popover-available-h: 100vh;
    /* 落定那一侧的可用宽度，同样由定位引擎经内联自定义属性写进来，行内轴据此夹取；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时退到视口宽 */
    --xh-_popover-available-w: 100vw;

    /* 面板内容的自绘条浮在内容之上：轨道不上底色，实色轨道会在面板右缘糊一条竖灰带 */
    --xh-scrollbar-track-bg: transparent;

    position: fixed;
    z-index: var(--xh-popover-layer, var(--xh-_layer, var(--xh-layer-popover)));
    /* 空壳不吃指针，交互只发生在 content 上 */
    pointer-events: none;
  }

  /* 锚点被滚出可视区：整个浮层随之收起 */
  [data-scope='popover'][data-part='positioner'][data-hidden] {
    visibility: hidden;
  }

  /* 缩放原点与进场位移按落定的那一侧给：面板从贴着锚点的那条边涨开、沿主轴退让一小段。
     两个槽由 content 继承。placement 是物理方向（引擎按 top / right / bottom / left 出值），
     origin 与 translate 也是物理量，两边同轴，不随书写方向翻 */
  [data-scope='popover'][data-part='positioner'][data-placement^='top'] {
    --xh-_overlay-origin-y: 100%;
    --xh-_overlay-enter-down: 1;
  }

  [data-scope='popover'][data-part='positioner'][data-placement^='bottom'] {
    --xh-_overlay-origin-y: 0;
    --xh-_overlay-enter-up: 1;
  }

  [data-scope='popover'][data-part='positioner'][data-placement^='left'] {
    --xh-_overlay-origin-x: 100%;
    --xh-_overlay-enter-right: 1;
  }

  [data-scope='popover'][data-part='positioner'][data-placement^='right'] {
    --xh-_overlay-origin-x: 0;
    --xh-_overlay-enter-left: 1;
  }

  /*
   * 触发器是页面上的独立文字按钮：盒型、md 档几何、outline 四态面、0.97 按压并换底与粗指针命中区
   * 由家族配方按连接层投影的 data-xh-action-variant / -size 给出。皮肤没有自己的外观规则，
   * 只把作者塞进按钮的图标接到随档字形尺（md = 20px）。
   */
  [data-scope='popover'][data-part='trigger'] {
    --xh-icon-size: var(--xh-popover-icon-size, var(--xh-_action-profile-glyph-size));
  }

  /* 家族配方给了 display，作者手写 hidden 时得把 UA 的 [hidden]{display:none} 还回去 */
  [data-scope='popover'][data-part='trigger'][hidden] {
    display: none;
  }

  [data-scope='popover'][data-part='content'] {
    /* 作者塞进面板里的图标按控件档取；关闭钮另由家族配方按 sm 档下发字形尺 */
    --xh-icon-size: var(--xh-popover-icon-size, var(--xh-glyph-size-md));

    /* 尺寸档只换这两个私有槽。popover 没有 root 部件，size 落在浮层树最外层的 content 上。
       语气不接：面板是内容容器，语气该由里面的内容表达 */
    --xh-_popover-pad: var(--xh-surface-pad-md);
    --xh-_popover-max-w: var(--xh-overlay-max-w);

    position: relative;
    display: flex;
    flex-direction: column;
    gap: var(--xh-popover-gap, var(--xh-space-2));
    inline-size: max-content;
    /* 静态档与落位后的可用宽度取小：窄视口下面板伸出去，最右侧的内容就点不到了 */
    max-inline-size: min(var(--xh-popover-max-w, var(--xh-_popover-max-w)), var(--xh-_popover-available-w));
    /* 内容由作者给，长度不可预知：不限高就整块伸出视口且滚不到 */
    max-block-size: min(var(--xh-popover-max-h, var(--xh-overlay-max-h)), var(--xh-_popover-available-h));
    overflow-y: auto;
    /* 浮在页面之上的 Overlay 滚动面：滚到头不把页面一起带走 */
    overscroll-behavior: contain;
    padding-block: var(--xh-popover-py, var(--xh-_popover-pad));
    padding-inline: var(--xh-popover-px, var(--xh-_popover-pad));
    border: var(--xh-stroke-thin) solid var(--xh-popover-border, var(--xh-material-frosted-border));
    border-radius: var(--xh-popover-radius, var(--xh-shape-overlay));
    /* 顶光只占内侧一像素；透明 tint 是底层，正文自己保持不透明。 */
    background:
      linear-gradient(
        to bottom,
        var(--xh-material-frosted-highlight) 0 var(--xh-stroke-thin),
        transparent var(--xh-stroke-thin)
      ),
      var(--xh-popover-bg, var(--xh-material-frosted-bg));
    color: var(--xh-popover-fg, var(--xh-material-frosted-fg));
    box-shadow: var(--xh-popover-shadow, var(--xh-material-frosted-shadow));
    -webkit-backdrop-filter: var(--xh-popover-backdrop, var(--xh-material-frosted-backdrop));
    backdrop-filter: var(--xh-popover-backdrop, var(--xh-material-frosted-backdrop));
    pointer-events: auto;
    /* 进退场的缩放锚在贴着锚点的那条边上；两个分量由 positioner 按 placement 写进私有槽 */
    transform-origin: var(--xh-_overlay-origin-x, 50%) var(--xh-_overlay-origin-y, 50%);
  }

  /* 这里刻意没有 [data-part='content'][hidden] { display: none }，与 dialog 一致：
     收起态连接层会给 content 打 hidden，而上面那条 display 正是要盖掉 UA 的
     [hidden]{display:none}——退场动画得先能播。presence 读的是 content 的 animationName，
     真正的收起由宿主在退场结束后落成内联 display:none（Vue 那边直接不渲染）。
     其余声明了 display 的角色节点仍补 [hidden]，那几处没有退场动画。 */

  [data-scope='popover'][data-part='content']:focus-visible {
    outline: none;
  }

  [data-scope='popover'][data-part='content'][data-state='open'] {
    animation: xh-overlay-pop-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 退场:收起那一帧 hidden 由退场闸门押后,这里才播得出来。forwards 把末态钉住,
     免得动画结束到 hidden 落下来之间闪一下原样 */
  [data-scope='popover'][data-part='content'][data-state='closed'] {
    animation: xh-pop-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* —— 尺寸 —— */
  /* 缺省档写在 content 的基础规则里；四边等宽的面板内衬三档取 surface-pad 那把尺 */
  [data-scope='popover'][data-part='content'][data-size='sm'] {
    --xh-_popover-pad: var(--xh-surface-pad-sm);
    --xh-_popover-max-w: var(--xh-overlay-max-w-sm);
  }

  [data-scope='popover'][data-part='content'][data-size='lg'] {
    --xh-_popover-pad: var(--xh-surface-pad-lg);
    --xh-_popover-max-w: var(--xh-overlay-max-w-lg);
  }

  [data-scope='popover'][data-part='title'] {
    margin: 0;
    font-size: var(--xh-popover-title-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-popover-title-font-weight, var(--xh-font-weight-semibold));
    color: var(--xh-popover-title-fg, var(--xh-material-frosted-fg));
  }

  /* 说明文字走说明档：13px + fg-muted */
  [data-scope='popover'][data-part='description'] {
    margin: 0;
    font-size: var(--xh-popover-description-font-size, var(--xh-text-secondary-size));
    color: var(--xh-popover-description-fg, var(--xh-fg-muted));
  }

  /* 关闭按钮是绝对定位的，不占流内宽度：标题得自己让出右上角那块，
     否则长标题会直接钻到按钮底下。只在真有关闭按钮时让位。 */
  [data-scope='popover'][data-part='content']:has([data-scope='popover'][data-part='close-trigger'])
    [data-scope='popover'][data-part='title'] {
    padding-inline-end: calc(var(--xh-popover-close-size, var(--xh-control-h-sm)) + var(--xh-space-2));
  }

  /*
   * 关闭钮是浮层角落的单图标钮：正方盒、sm 档几何、ghost 四态面、0.97 按压并换底与粗指针命中区
   * 由家族配方给出——磨砂白面上走画布承载阶梯悬停 --xh-bg-subtle（100）→ 按下 --xh-bg-subtle-hover（200），
   * 焦点面透明吃库环。这里只把公开槽桥接到矩阵之前（使用者槽 → 形态矩阵 → 家族缺省）与摆放，
   * 聚焦档的 -bg-focus / -fg-focus 两槽同样桥到配方的 focus-visible 面，缺省仍是透明底与悬停字色：
   * 贴边比 dialog 一族的面板档（--xh-surface-action-inset）小一档：气泡的面板内衬是 12px，
   * 28px 的钮按 12px 贴边会伸出面板自己的盒子，被 content 的 overflow 裁掉。
   * 静息前景取磨砂面的 muted 字色，悬停 / 按下回到 fg-default。
   */
  [data-scope='popover'][data-part='close-trigger'] {
    --xh-action-visual-size: var(--xh-popover-close-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-popover-close-radius, var(--xh-shape-control));
    --xh-action-bg-hover: var(--xh-popover-close-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-popover-close-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-bg-focus-visible: var(--xh-popover-close-bg-focus, var(--xh-_action-variant-bg-focus-visible));
    --xh-action-fg-rest: var(--xh-popover-close-fg, var(--xh-material-frosted-fg-muted));
    --xh-action-fg-hover: var(--xh-popover-close-fg-hover, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-popover-close-fg-hover, var(--xh-_action-variant-fg-pressed));
    --xh-action-fg-focus-visible: var(--xh-popover-close-fg-focus, var(--xh-popover-close-fg-hover, var(--xh-_action-variant-fg-focus-visible)));
    /* 作者塞进按钮的图标随档取字形尺（sm = 16px），与皮肤画的兜底字形同一把尺 */
    --xh-icon-size: var(--xh-popover-icon-size, var(--xh-_action-profile-glyph-size));

    position: absolute;
    inset-block-start: var(--xh-space-2);
    inset-inline-end: var(--xh-space-2);
  }

  [data-scope='popover'][data-part='close-trigger'][hidden] {
    display: none;
  }

  /* 箭头的底色与描边色，几何在 overlay-arrow.css。
     交叉轴落点由定位引擎经内联自定义属性写进来，没给时退回居中 */
  [data-scope='popover'][data-part='arrow'] {
    --xh-_popover-arrow-x: 50%;
    --xh-_popover-arrow-y: 50%;
    --xh-_overlay-arrow-size: var(--xh-popover-arrow-size, var(--xh-overlay-arrow-size));
    --xh-_overlay-arrow-x: var(--xh-_popover-arrow-x);
    --xh-_overlay-arrow-y: var(--xh-_popover-arrow-y);

    background: var(--xh-popover-bg, var(--xh-material-frosted-bg));
    border: var(--xh-stroke-thin) solid var(--xh-popover-border, var(--xh-material-frosted-border));
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中 */
  [data-scope='popover'][data-part='close-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }

  @media (forced-colors: active) {
    /* 系统色接管边界与正文；装饰顶光在这一档没有信息价值，明确撤掉背景图层。 */
    [data-scope='popover'][data-part='content'] {
      background-image: none;
    }
  }

  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。 */
    [data-scope='popover'][data-part='positioner'] {
      display: none;
    }
  }
}

/* styles/progress.css */
/* 定义 progress 样式。 */

@layer xihan.motion {
  /* 动画名的查找只认「文档里有没有这个名字」：引用别处文件里的名字，那份文件不一定在场，
     动画会静默地整个不跑。每份皮肤都能单独引入，所以它用到的关键帧都写在自己身上。 */
  /* 固定宽度的一段从轨道行首外扫到行尾外：只动 translate，不动布局。
     百分比参照这一段自身的宽度（轨道的 40%），RTL 下两端由私有槽换号 */
  @keyframes xh-progress-indeterminate {
    from {
      translate: var(--xh-_progress-sweep-from, -100%) 0;
    }

    to {
      translate: var(--xh-_progress-sweep-to, 250%) 0;
    }
  }
}

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='progress'] {
    --xh-progress-skin: 1;
  }

  /* 私有槽位：组件令牌 → 中档字面量两级回退。厚度写在 root 上而不是 track 上，
     尺寸档才改得动一处就够，track 靠继承拿到值。 */
  [data-scope='progress'][data-part='root'] {
    --xh-_progress-thickness: var(--xh-progress-thickness, var(--xh-track-thickness));

    display: inline-block;
    inline-size: 100%;
  }

  [data-scope='progress'][data-part='track'] {
    overflow: hidden;
    inline-size: 100%;
    block-size: var(--xh-_progress-thickness);
    border-radius: var(--xh-progress-track-radius, var(--xh-shape-pill));
    background: var(--xh-progress-track, var(--xh-bg-subtle-active));
  }

  /* 语气槽由 root 上的 data-tone 声明、经继承发下来；没写 data-tone 时退回原来的品牌色。
     轨道不跟着换族：只有已完成的那段换色，底槽保持中性才读得出"完成了多少"。 */
  [data-scope='progress'][data-part='range'] {
    /* 填充铺满轨道，按未完成的比例往行首平移、由轨道裁掉：进度变化只走合成，不重排也不重绘。
       露出来的前端保留自己的圆角，行首那一侧由轨道的圆角裁出 */
    inline-size: 100%;
    block-size: 100%;
    border-radius: var(--xh-progress-range-radius, var(--xh-shape-pill));
    background: var(--xh-progress-range, var(--xh-_tone, var(--xh-bg-brand)));
    translate: calc((var(--xh-_progress-value, 0) - 1) * 100%) 0;
    transition: translate var(--xh-motion-duration-move) var(--xh-motion-ease-continuous);
  }

  /* translate 只认物理方向：RTL 下行首在右边，平移与不定进度的扫向一起翻转 */
  [data-scope='progress'][data-part='range']:dir(rtl) {
    --xh-_progress-sweep-from: 100%;
    --xh-_progress-sweep-to: -250%;

    translate: calc((1 - var(--xh-_progress-value, 0)) * 100%) 0;
  }

  /* —— 尺寸 —— */
  /* 线形只有厚度分档；中间档不写规则，缺省即中档 */
  [data-scope='progress'][data-part='root'][data-size='sm'] {
    --xh-_progress-thickness: var(--xh-progress-thickness, var(--xh-space-1));
  }

  [data-scope='progress'][data-part='root'][data-size='lg'] {
    --xh-_progress-thickness: var(--xh-progress-thickness, var(--xh-space-2));
  }

  /* —— 环形 —— */
  /* 环画在固定的 100×100 viewBox 里，直径由这里的尺寸决定；
     画面与环心文字叠在同一格上，文字因此恒在圆心 */
  [data-scope='progress'][data-part='root'][data-variant='circle'],
  [data-scope='progress'][data-part='root'][data-variant='dashboard'] {
    --xh-_progress-diameter: var(--xh-progress-size, 7.5rem);

    display: inline-grid;
    place-items: center;
    inline-size: var(--xh-_progress-diameter);
    block-size: var(--xh-_progress-diameter);
  }

  [data-scope='progress'][data-part='root'][data-variant='circle'][data-size='sm'],
  [data-scope='progress'][data-part='root'][data-variant='dashboard'][data-size='sm'] {
    --xh-_progress-diameter: var(--xh-progress-size, 5rem);
  }

  [data-scope='progress'][data-part='root'][data-variant='circle'][data-size='lg'],
  [data-scope='progress'][data-part='root'][data-variant='dashboard'][data-size='lg'] {
    --xh-_progress-diameter: var(--xh-progress-size, 10rem);
  }

  [data-scope='progress'][data-part='canvas'],
  [data-scope='progress'][data-part='label'] {
    grid-area: 1 / 1;
  }

  [data-scope='progress'][data-part='canvas'] {
    inline-size: 100%;
    block-size: 100%;
  }

  /* 环心文字：占位不撑格子，长内容自己换行由作者定 */
  [data-scope='progress'][data-part='label'] {
    color: var(--xh-progress-label-fg, var(--xh-fg-default));
    font-size: var(--xh-progress-label-font-size, var(--xh-text-body-size));
    line-height: var(--xh-leading-none);
    text-align: center;
  }

  /* 圆心、半径与那两段虚线都由连接层算好写进内联样式，这里只上色。
     底槽不跟着语气换族：只有已完成的那段换色，才读得出"完成了多少" */
  [data-scope='progress'][data-part='track'][data-variant='circle'],
  [data-scope='progress'][data-part='track'][data-variant='dashboard'] {
    stroke: var(--xh-progress-track, var(--xh-bg-subtle-active));
  }

  [data-scope='progress'][data-part='range'][data-variant='circle'],
  [data-scope='progress'][data-part='range'][data-variant='dashboard'] {
    stroke: var(--xh-progress-range, var(--xh-_tone, var(--xh-bg-brand)));
    stroke-linecap: var(--xh-progress-linecap, round);
    transition: stroke-dashoffset var(--xh-motion-duration-move) var(--xh-motion-ease-continuous);
  }

  /* 进度未知：线形条改为固定宽度的一小段来回扫，位移交给动画，按比例的平移与它的过渡让开 */
  [data-scope='progress'][data-part='track'][data-state='indeterminate'] {
    position: relative;
    overflow: hidden;
  }

  [data-scope='progress'][data-part='range'][data-state='indeterminate'] {
    position: absolute;
    inset-inline-start: 0;
    inline-size: 40%;
    transition: none;
    animation: xh-progress-indeterminate var(--xh-progress-indeterminate-duration, var(--xh-shimmer-duration)) var(--xh-motion-ease-loop) infinite;
  }

  /* 减弱动效档：不来回扫，改成一条铺满的静态条——进度仍然未知，只是不再动。
     两条规则是同一件事的两个触发条件：系统偏好与作者打的 data-motion */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='progress'][data-part='range'][data-state='indeterminate'] {
      position: static;
      inline-size: 100%;
      opacity: 0.5;
      translate: none;
      animation: none;
    }
  }

  :where([data-motion='reduce']) [data-scope='progress'][data-part='range'][data-state='indeterminate'] {
    position: static;
    inline-size: 100%;
    opacity: 0.5;
    translate: none;
    animation: none;
  }

  /* 零进度：整段不画，从零起步的那一帧也不留一粒圆点 */
  [data-scope='progress'][data-part='range'][data-empty] {
    visibility: hidden;
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='progress'][data-part='root'][hidden] {
    display: none;
  }

  /*
   * 高对比档：走完的那段与底槽都是底色画的，这一档里两者被换成同一个系统色，
   * 整根条子成了一色，读不出走到哪儿。走完的那段改取系统高亮色，底槽补一圈环把全长框出来。
   * 环用 outline 不用 border：条子的厚度是写死的，加边会把它顶高一档。
   * 环形档画的是描边，stroke 在这一档里照旧生效，两条各自换成系统色即可。
   */
  @media (forced-colors: active) {
    [data-scope='progress'][data-part='track'] {
      outline: var(--xh-stroke-thin) solid CanvasText;
      outline-offset: calc(-1 * var(--xh-stroke-thin));
    }

    [data-scope='progress'][data-part='range'] {
      background: Highlight;
    }

    [data-scope='progress'][data-part='track'][data-variant='circle'],
    [data-scope='progress'][data-part='track'][data-variant='dashboard'] {
      outline: none;
      stroke: CanvasText;
    }

    [data-scope='progress'][data-part='range'][data-variant='circle'],
    [data-scope='progress'][data-part='range'][data-variant='dashboard'] {
      stroke: Highlight;
    }
  }

  @media print {
    /* 打印：动画会被定格在任意一帧——转了一半的圈、扫到一半的微光。这里换成静止的表达，
       取值与减弱动效那一档相同。两档各写一块、不并进一条媒体查询列表：减弱动效另有一份
       :where([data-motion='reduce']) 的钩子版本与它成对，打印没有对应的钩子可配，
       并成一条之后这层配对关系在文本上就断了。 */
    [data-scope='progress'][data-part='range'][data-state='indeterminate'] {
      position: static;
      inline-size: 100%;
      opacity: 0.5;
      translate: none;
      animation: none;
    }
  }
}

/* styles/question-flow.css */
/* 定义 question flow 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立；
   独立皮肤同时传递引入选项行与四颗钮的动作控件配方，full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='question-flow'] {
    --xh-question-flow-skin: 1;
  }

  /* 一张静态内容面：--xh-border-default 描边 + surface 底 + 无影（边界只由描边承担）。
     三个视觉轴都落在 root 上：形态管底与描边怎么画，语气管用哪族颜色，尺寸管内衬、按钮高度与字号 */
  [data-scope='question-flow'][data-part='root'] {
    /* 作者塞进翻页钮的图标按档取尺，与皮肤画的兜底字形同一把尺 */
    --xh-icon-size: var(--xh-question-flow-icon-size, var(--xh-glyph-size-md));
    /* 尺寸缺省档：不写 data-size 时按中档走 */
    --xh-_question-flow-p: var(--xh-space-4);
    --xh-_question-flow-gap: var(--xh-space-3);
    --xh-_question-flow-h: var(--xh-control-h-md);
    --xh-_question-flow-px: var(--xh-control-px-md);
    --xh-_question-flow-font-size: var(--xh-control-font-md);
    --xh-_question-flow-indicator: var(--xh-control-indicator-md);

    display: flex;
    flex-direction: column;
    gap: var(--xh-question-flow-gap, var(--xh-_question-flow-gap));
    padding: var(--xh-question-flow-padding, var(--xh-_question-flow-p));
    border: var(--xh-stroke-thin) solid var(--xh-question-flow-border, var(--xh-border-default));
    border-radius: var(--xh-question-flow-radius, var(--xh-shape-surface));
    background: var(--xh-question-flow-bg, var(--xh-bg-surface));
    box-shadow: var(--xh-question-flow-shadow, none);
    animation: xh-item-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 上面声明的 display 会盖掉 UA 的 [hidden]{display:none}，这里补回 */
  [data-scope='question-flow'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 形态 —— */
  /* 描边式是缺省档，写在上面那条基础规则里 */
  /* 填充式：底色顶替描边表达边界。描边只退成透明而不去掉，
     1px 的位置留着，与 outline 档并排时基线对得上；
     淡底承载面向选项行与几颗中性钮下发 hover 200 → pressed 300 */
  [data-scope='question-flow'][data-part='root'][data-variant='subtle'] {
    --xh-action-host-bg-hover: var(--xh-bg-subtle-hover);
    --xh-action-host-bg-pressed: var(--xh-bg-subtle-active);

    border-color: transparent;
    background: var(--xh-question-flow-bg, var(--xh-_tone-subtle, var(--xh-bg-subtle)));
  }

  /* 无壳：底与描边都透明，影一并收掉——底都不画了，一圈投影就成了没有来处的暗边 */
  [data-scope='question-flow'][data-part='root'][data-variant='ghost'] {
    border-color: transparent;
    background: transparent;
    box-shadow: none;
  }

  /* —— 尺寸 —— */
  [data-scope='question-flow'][data-part='root'][data-size='sm'] {
    --xh-_question-flow-p: var(--xh-space-3);
    --xh-_question-flow-gap: var(--xh-space-2);
    --xh-_question-flow-h: var(--xh-control-h-sm);
    --xh-_question-flow-px: var(--xh-control-px-sm);
    --xh-_question-flow-font-size: var(--xh-control-font-sm);
    --xh-_question-flow-indicator: var(--xh-control-indicator-sm);
    --xh-icon-size: var(--xh-question-flow-icon-size, var(--xh-glyph-size-sm));
  }

  [data-scope='question-flow'][data-part='root'][data-size='md'] {
    --xh-_question-flow-p: var(--xh-space-4);
    --xh-_question-flow-gap: var(--xh-space-3);
    --xh-_question-flow-h: var(--xh-control-h-md);
    --xh-_question-flow-px: var(--xh-control-px-md);
    --xh-_question-flow-font-size: var(--xh-control-font-md);
    --xh-_question-flow-indicator: var(--xh-control-indicator-md);
    --xh-icon-size: var(--xh-question-flow-icon-size, var(--xh-glyph-size-md));
  }

  [data-scope='question-flow'][data-part='root'][data-size='lg'] {
    --xh-_question-flow-p: var(--xh-space-5);
    --xh-_question-flow-gap: var(--xh-space-4);
    --xh-_question-flow-h: var(--xh-control-h-lg);
    --xh-_question-flow-px: var(--xh-control-px-lg);
    --xh-_question-flow-font-size: var(--xh-control-font-lg);
    --xh-_question-flow-indicator: var(--xh-control-indicator-lg);
    --xh-icon-size: var(--xh-question-flow-icon-size, var(--xh-glyph-size-lg));
  }

  /* 视口定高并裁切：高度由机器量出来写进私有槽，量到之前按内容撑开。
     换题时高度过渡到新那一题，卡片跟着长高或收矮 */
  [data-scope='question-flow'][data-part='viewport'] {
    --xh-_question-flow-viewport-h: auto;

    display: block;
    overflow: hidden;
    block-size: var(--xh-question-flow-viewport-h, var(--xh-_question-flow-viewport-h));
    transition: block-size var(--xh-motion-duration-move) var(--xh-motion-ease-continuous);
  }

  [data-scope='question-flow'][data-part='viewport'][hidden] {
    display: none;
  }

  /* 轨道把全部题目纵向排开，靠位移把当前题推进视口 */
  [data-scope='question-flow'][data-part='track'] {
    --xh-_question-flow-track-y: 0;

    display: flex;
    flex-direction: column;
    gap: var(--xh-question-flow-track-gap, var(--xh-_question-flow-gap));
    translate: 0 var(--xh-question-flow-track-y, var(--xh-_question-flow-track-y));
    transition: translate var(--xh-motion-duration-move) var(--xh-motion-ease-continuous);
  }

  [data-scope='question-flow'][data-part='track'][hidden] {
    display: none;
  }

  /* 一题的整块。非当前题淡出并让开指针：它仍留在轨道上，高度才有得可量 */
  [data-scope='question-flow'][data-part='question'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-question-flow-question-gap, var(--xh-space-2));
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  [data-scope='question-flow'][data-part='question'][hidden] {
    display: none;
  }

  [data-scope='question-flow'][data-part='question'][data-current] {
    opacity: 1;
    pointer-events: auto;
  }

  /* 题干就是这一题的标题，也是选项组的可访问名：走 Surface 标题档 14/600 */
  [data-scope='question-flow'][data-part='prompt'] {
    display: block;
    margin: 0;
    color: var(--xh-question-flow-prompt-fg, var(--xh-fg-default));
    font-size: var(--xh-question-flow-prompt-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-question-flow-prompt-font-weight, var(--xh-font-weight-semibold));
    line-height: var(--xh-leading-tight);
  }

  [data-scope='question-flow'][data-part='prompt'][hidden] {
    display: none;
  }

  [data-scope='question-flow'][data-part='group'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-question-flow-group-gap, var(--xh-space-1));
  }

  [data-scope='question-flow'][data-part='group'][hidden] {
    display: none;
  }

  /* 一个选项：整行可点、可聚焦，记号在左。盒型、悬停 / 按下 / 禁用面由 Action Control 的 row 档给
     （ghost 形态：白底承载 hover 100 → pressed 200，按下只换面不缩放；禁用守卫认 data-disabled），
     这里只把使用者槽映射到桥接槽，内衬与间距沿用本组件的档位；字色三态同一支，选中档在下面换一档。
     行高不吃家族的单行档：row 档允许换行、高度随内容，一条会折行的选项文案走正文行高 */
  [data-scope='question-flow'][data-part='item'] {
    --xh-action-gap: var(--xh-question-flow-item-gap, var(--xh-space-1_5));
    --xh-action-padding-inline: var(--xh-question-flow-item-px, var(--xh-space-2));
    --xh-action-padding-block: var(--xh-question-flow-item-py, var(--xh-space-1));
    --xh-action-radius: var(--xh-question-flow-item-radius, var(--xh-_action-profile-radius));
    --xh-action-font-size: var(--xh-question-flow-item-font-size, var(--xh-_question-flow-font-size));
    --xh-action-bg-rest: var(--xh-question-flow-item-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-question-flow-item-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-fg-rest: var(--xh-question-flow-item-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-question-flow-item-fg, var(--xh-fg-muted));
    --xh-action-fg-pressed: var(--xh-question-flow-item-fg, var(--xh-fg-muted));

    line-height: var(--xh-leading-normal);
  }

  [data-scope='question-flow'][data-part='item'][hidden] {
    display: none;
  }

  /* 当前题的选项按位次错开开幕，换题时随 data-current 重跑。
     backwards 不能省：等待期间起帧不生效的话，后面几条会先露一下再跳回去。
     第 6 条起并到同一拍上 */
  [data-scope='question-flow'][data-part='question'][data-current] [data-part='item'] {
    animation: xh-rise-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong) backwards;
  }

  [data-scope='question-flow'][data-part='question'][data-current] [data-part='item']:nth-child(2) {
    animation-delay: calc(var(--xh-motion-stagger-step) * 1);
  }

  [data-scope='question-flow'][data-part='question'][data-current] [data-part='item']:nth-child(3) {
    animation-delay: calc(var(--xh-motion-stagger-step) * 2);
  }

  [data-scope='question-flow'][data-part='question'][data-current] [data-part='item']:nth-child(4) {
    animation-delay: calc(var(--xh-motion-stagger-step) * 3);
  }

  [data-scope='question-flow'][data-part='question'][data-current] [data-part='item']:nth-child(5) {
    animation-delay: calc(var(--xh-motion-stagger-step) * 4);
  }

  [data-scope='question-flow'][data-part='question'][data-current] [data-part='item']:nth-child(n + 6) {
    animation-delay: calc(var(--xh-motion-stagger-step) * 5);
  }

  /* 选中的那条读起来更重一档（禁用项无论选没选都是家族给的禁用色） */
  [data-scope='question-flow'][data-part='item'][data-state='checked'] {
    --xh-action-fg-rest: var(--xh-question-flow-item-fg-checked, var(--xh-fg-default));
    --xh-action-fg-hover: var(--xh-question-flow-item-fg-checked, var(--xh-fg-default));
    --xh-action-fg-pressed: var(--xh-question-flow-item-fg-checked, var(--xh-fg-default));
  }

  /* 记号盒：多选是圆角方格，单选是圆。选中态填色，纯装饰不进可访问名 */
  [data-scope='question-flow'][data-part='item-indicator'] {
    /* 盒里那枚记号按盒比例量（与 Checkbox 同一比例），作者塞进来的图标读同一把尺。
       根上那把是展示型图标档，比指示符盒还大一档，画进这个盒里会溢出四个像素 */
    --xh-_question-flow-indicator-glyph: calc(var(--xh-question-flow-indicator-size, var(--xh-_question-flow-indicator)) * 0.75);
    --xh-icon-size: var(--xh-question-flow-indicator-icon-size, var(--xh-_question-flow-indicator-glyph));

    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    border: var(--xh-stroke-thin) solid var(--xh-question-flow-indicator-border, var(--xh-border-control));
    border-radius: var(--xh-question-flow-indicator-radius, var(--xh-shape-inset));
    background: var(--xh-question-flow-indicator-bg, transparent);
    color: var(--xh-question-flow-indicator-fg, var(--xh-_tone-on, var(--xh-fg-on-brand)));
    inline-size: var(--xh-question-flow-indicator-size, var(--xh-_question-flow-indicator));
    block-size: var(--xh-question-flow-indicator-size, var(--xh-_question-flow-indicator));
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      border-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='question-flow'][data-part='item-indicator'][hidden] {
    display: none;
  }

  /* 单选那一档把方格收成圆：正方盒取 circle */
  [data-scope='question-flow'][data-part='item-indicator'][data-select-mode='single'] {
    border-radius: var(--xh-question-flow-indicator-radius-single, var(--xh-shape-circle));
  }

  /* 没写内容就由皮肤画勾；作者往部件里塞了自己的图形，这条规则即不命中 */
  [data-scope='question-flow'][data-part='item-indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    mask: var(--xh-glyph-mark-check) center / contain no-repeat;
  }

  /* 单选那一档把勾换成实心点：mask 撤掉，圆点由伪元素自己的底色画。
     直径按记号盒的一半量，与其余单选控件的圆点同源——盒换档时点跟着换 */
  [data-scope='question-flow'][data-part='item-indicator'][data-select-mode='single']:empty::before {
    inline-size: var(--xh-question-flow-dot-size, calc(var(--xh-question-flow-indicator-size, var(--xh-_question-flow-indicator)) / 2));
    block-size: var(--xh-question-flow-dot-size, calc(var(--xh-question-flow-indicator-size, var(--xh-_question-flow-indicator)) / 2));
    border-radius: var(--xh-question-flow-dot-radius, var(--xh-shape-circle));
    -webkit-mask: none;
    mask: none;
  }

  [data-scope='question-flow'][data-part='item-indicator'][data-state='checked'] {
    border-color: var(--xh-question-flow-indicator-border-checked, var(--xh-_tone, var(--xh-bg-brand)));
    background: var(--xh-question-flow-indicator-bg-checked, var(--xh-_tone, var(--xh-bg-brand)));
  }

  /* 没选中时把记号隐去而不是撤掉：盒留在原位，翻面时整行不跳 */
  [data-scope='question-flow'][data-part='item-indicator'][data-state='unchecked'] {
    color: transparent;
  }

  [data-scope='question-flow'][data-part='item-text'] {
    display: block;
    flex: 1 1 auto;
  }

  [data-scope='question-flow'][data-part='item-text'][hidden] {
    display: none;
  }

  /* 自由文本：与选项同等算数的一条答案，占满整行 */
  [data-scope='question-flow'][data-part='note'] {
    display: block;
    inline-size: 100%;
    padding-inline: var(--xh-question-flow-note-px, var(--xh-space-2));
    padding-block: var(--xh-question-flow-note-py, var(--xh-space-1_5));
    border: var(--xh-stroke-thin) solid var(--xh-question-flow-note-border, var(--xh-border-control));
    border-radius: var(--xh-question-flow-note-radius, var(--xh-shape-control));
    background: var(--xh-question-flow-note-bg, var(--xh-bg-surface));
    color: var(--xh-question-flow-note-fg, var(--xh-fg-default));
    font-family: inherit;
    font-size: var(--xh-question-flow-note-font-size, var(--xh-_question-flow-font-size));
    transition: border-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='question-flow'][data-part='note'][hidden] {
    display: none;
  }

  [data-scope='question-flow'][data-part='note']::placeholder {
    color: var(--xh-question-flow-placeholder-fg, var(--xh-fg-subtle));
  }

  [data-scope='question-flow'][data-part='note']:disabled {
    color: var(--xh-fg-disabled);
  }

  /* 页脚：左边步进，右边动作。
     两侧的钮都不收缩、文案也不折行，一行摆不下时整条页脚顶出卡片；
     允许换行后摆不下的那一组落到下一行 */
  [data-scope='question-flow'][data-part='footer'] {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--xh-question-flow-footer-gap, var(--xh-space-3));
  }

  [data-scope='question-flow'][data-part='footer'][hidden] {
    display: none;
  }

  /* 两颗翻页钮是方形图标钮，中间夹着计数：盒几何、悬停 / 按下与 0.97 按压、焦点环、禁用面全由
     Action Control 的 icon 档 xs 位给（24px = --xh-control-action-size；ghost 形态，白底 100 → 200），
     组件只映射既有使用者槽：尺寸、内衬、圆角（inset）、底与字色 */
  [data-scope='question-flow'][data-part='prev-trigger'],
  [data-scope='question-flow'][data-part='next-trigger'] {
    --xh-action-visual-size: var(--xh-question-flow-step-size, var(--xh-_action-profile-visual-size));
    --xh-action-padding-inline: var(--xh-question-flow-step-padding, var(--xh-_action-profile-padding-inline));
    --xh-action-radius: var(--xh-question-flow-step-radius, var(--xh-shape-inset));
    --xh-action-bg-rest: var(--xh-question-flow-step-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-question-flow-step-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-fg-rest: var(--xh-question-flow-step-fg, var(--xh-fg-subtle));
    --xh-action-fg-hover: var(--xh-question-flow-step-fg-hover, var(--xh-fg-default));
    --xh-action-fg-pressed: var(--xh-question-flow-step-fg-hover, var(--xh-fg-default));
  }

  /* 家族那条 display 会把 UA 的 [hidden]{display:none} 盖掉 */
  [data-scope='question-flow'][data-part='prev-trigger'][hidden],
  [data-scope='question-flow'][data-part='next-trigger'][hidden] {
    display: none;
  }

  /* 没写内容就由皮肤画箭头；作者往按钮里塞了自己的图形，这两条即不命中 */
  [data-scope='question-flow'][data-part='prev-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-up) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-up) center / contain no-repeat;
  }

  [data-scope='question-flow'][data-part='next-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
  }

  /* 给眼睛看的 N / M：等宽数字，换题时不左右晃 */
  [data-scope='question-flow'][data-part='counter'] {
    display: inline-flex;
    align-items: center;
    color: var(--xh-question-flow-counter-fg, var(--xh-fg-subtle));
    font-size: var(--xh-question-flow-counter-font-size, var(--xh-text-caption-size));
    font-variant-numeric: tabular-nums;
  }

  [data-scope='question-flow'][data-part='counter'][hidden] {
    display: none;
  }

  /* 两颗动作钮是离散动作控件：盒几何、悬停 / 按下与 0.97 按压、焦点环、禁用面全由 Action Control 的 text 档给，
     组件只映射既有使用者槽。跳过走 ghost 档：安静的文字钮（白底 100 → 200）；提交走 solid 档：这一组里的主要动作，
     与 Button 缺省同为品牌实心。两颗共用的几何与字号写在一起 */
  [data-scope='question-flow'][data-part='skip-trigger'],
  [data-scope='question-flow'][data-part='submit-trigger'] {
    --xh-action-gap: var(--xh-question-flow-action-gap, var(--xh-space-1));
    --xh-action-visual-size: var(--xh-question-flow-action-h, var(--xh-_question-flow-h));
    --xh-action-padding-inline: var(--xh-question-flow-action-px, var(--xh-_question-flow-px));
    --xh-action-radius: var(--xh-question-flow-action-radius, var(--xh-shape-control));
    --xh-action-font-size: var(--xh-question-flow-action-font-size, var(--xh-text-label-size));

    font-weight: var(--xh-question-flow-action-font-weight, var(--xh-text-label-weight));
  }

  /* 家族那条 display 会把 UA 的 [hidden]{display:none} 盖掉 */
  [data-scope='question-flow'][data-part='skip-trigger'][hidden],
  [data-scope='question-flow'][data-part='submit-trigger'][hidden] {
    display: none;
  }

  /* 跳过钮：底与字色映到 ghost 档的桥接槽，悬停时字色提到正文档 */
  [data-scope='question-flow'][data-part='skip-trigger'] {
    --xh-action-bg-rest: var(--xh-question-flow-skip-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-question-flow-skip-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-fg-rest: var(--xh-question-flow-skip-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-question-flow-skip-fg-hover, var(--xh-fg-default));
    --xh-action-fg-pressed: var(--xh-question-flow-skip-fg-hover, var(--xh-fg-default));
  }

  /* 提交钮：品牌实心，内顶高光把实心块顶出一道边，与跳过那颗的描边同一档厚度（三态同一支，
     答不动时的置灰面由家族收掉、高光随之撤掉，出口一直在那里只是按不动）；底 / 字与置灰底映到 solid 档的桥接槽 */
  [data-scope='question-flow'][data-part='submit-trigger'] {
    --xh-action-bg-rest: var(--xh-question-flow-submit-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-question-flow-submit-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-question-flow-submit-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-bg-disabled: var(--xh-question-flow-submit-bg-off, var(--xh-_action-variant-bg-disabled));
    --xh-action-fg-rest: var(--xh-question-flow-submit-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-question-flow-submit-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-question-flow-submit-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: var(--xh-question-flow-submit-shadow, var(--xh-_highlight-tone));
    --xh-action-shadow-hover: var(--xh-question-flow-submit-shadow, var(--xh-_highlight-tone));
    --xh-action-shadow-pressed: var(--xh-question-flow-submit-shadow, var(--xh-_highlight-tone));
  }

  /* 面是实心的，环色与面同族，画在面里就看不出来；环改取面自己的前景色——
     那一族色本来就要在这块面上把字读清楚，与面的对比是按可读性定的。
     置灰档的底换成置灰底、字换成置灰色，环取过来就跟底一起糊了，那一档走公共层的环 */
  [data-scope='question-flow'][data-part='submit-trigger']:not([data-disabled]) {
    --xh-action-ring-color-focus-visible: currentColor;
  }

  /* 交卷之后才露出的那一格 */
  [data-scope='question-flow'][data-part='result'] {
    display: inline-flex;
    align-self: flex-start;
    align-items: center;
    gap: var(--xh-question-flow-result-gap, var(--xh-space-1_5));
    padding-inline: var(--xh-question-flow-result-px, var(--xh-space-2));
    padding-block: var(--xh-question-flow-result-py, var(--xh-space-1));
    border-radius: var(--xh-question-flow-result-radius, var(--xh-shape-pill));
    background: var(--xh-question-flow-result-bg, var(--xh-bg-subtle));
    color: var(--xh-question-flow-result-fg, var(--xh-fg-success));
    font-size: var(--xh-question-flow-result-font-size, var(--xh-text-caption-size));
    font-weight: var(--xh-question-flow-result-font-weight, var(--xh-text-label-weight));
    animation: xh-pop-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  [data-scope='question-flow'][data-part='result'][hidden] {
    display: none;
  }

  /* 视觉隐藏的播报区：不能 display:none，那样读屏就取不到它了 */
  [data-scope='question-flow'][data-part='live-region'] {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    border: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}

/* styles/radio-group.css */
/* 定义 radio group 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='radio-group'] {
    --xh-radio-group-skin: 1;
  }

  [data-scope='radio-group'][data-part='root'] {
    /* 尺寸档只换这两个私有槽，标题与条目都从 root 继承它们，换档不必给每个部件各写一条选择器 */
    --xh-_radio-group-item-gap: var(--xh-control-gap-md);
    --xh-_radio-group-font-size: var(--xh-control-font-md);
    --xh-_radio-group-indicator: var(--xh-control-indicator-md);
    /* 选中色随语气走。没写 data-tone 时 --xh-_tone 没被声明，退回原来的品牌色 */
    --xh-_radio-group-accent: var(--xh-_tone, var(--xh-bg-brand));
    /* 条目是圆圈的承载面：行自己坐画布走 100 → 200，行面上的圆圈按淡底容器阶梯再上一档（200 → 300）。
       两支私有槽是这一档的唯一来源——宿主拿它们给 --xh-action-host-bg-* 赋值（桥接槽只写不读），
       圆圈按下读同一支私有槽，即与宿主的 host 槽同源 */
    --xh-_radio-group-host-bg-hover: var(--xh-bg-subtle-hover);
    --xh-_radio-group-host-bg-pressed: var(--xh-bg-subtle-active);

    /* 标题与条目都是根的直接子节点，一支 gap 同时管「标题到集合」与「条目之间」：
       集合标题与集合隔 --xh-space-2，同组条目之间也是同一档紧密关系 */
    display: flex;
    gap: var(--xh-radio-group-gap, var(--xh-space-2));
  }

  [data-scope='radio-group'][data-part='root'][data-orientation='vertical'] {
    flex-direction: column;
  }

  /* 横排一行摆不下时条目落到下一行。不换行的话它们只会被压窄，
     文字逐字折行、每个条目变成一根竖条 */
  [data-scope='radio-group'][data-part='root'][data-orientation='horizontal'] {
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
  }

  /* —— 尺寸 —— */
  [data-scope='radio-group'][data-part='root'][data-size='sm'] {
    --xh-_radio-group-item-gap: var(--xh-control-gap-sm);
    --xh-_radio-group-font-size: var(--xh-control-font-sm);
    --xh-_radio-group-indicator: var(--xh-control-indicator-sm);
  }

  [data-scope='radio-group'][data-part='root'][data-size='lg'] {
    --xh-_radio-group-item-gap: var(--xh-control-gap-lg);
    --xh-_radio-group-font-size: var(--xh-control-font-lg);
    --xh-_radio-group-indicator: var(--xh-control-indicator-lg);
  }

  /* 集合标题：14 / 500 / fg-muted，字号不随 size 档——随档的是条目文字 */
  [data-scope='radio-group'][data-part='label'] {
    color: var(--xh-radio-group-label-fg, var(--xh-fg-muted));
    font-size: var(--xh-radio-group-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-radio-group-label-font-weight, var(--xh-text-label-weight));
    line-height: var(--xh-leading-none);
  }

  /* label 自己不带状态属性，整组禁用只写在 root 上，禁用标签色统一 --xh-fg-subtle */
  [data-scope='radio-group'][data-part='root'][data-disabled] [data-scope='radio-group'][data-part='label'] {
    color: var(--xh-radio-group-label-fg-disabled, var(--xh-fg-subtle));
  }

  /* 条目是「圆圈 + 文案」的整行命中区：接 Action Control row 档、ghost 形态，悬停 / 按下 / 禁用面、手型、
     过渡与焦点环由家族给，按下只换面不缩放（row 档专属按压块 scale: none）；这里只把使用者槽映射到桥接槽。
     行自己坐画布走 100 → 200（--xh-action-bg-* 钉住自己的面），行面上的圆圈按淡底容器阶梯再上一档
     （--xh-action-host-bg-* 向内声明自己是圆圈的承载面，host 槽只对后代生效——自己的面已由 --xh-action-bg-* 钉住；
     也因此 root 带 data-tone 时 --xh-_tone-subtle 不会把整行染色）。
     xs 的 24px 是命中地板，圆圈 12 / 16 / 20px 居中其间；字号与间距按组档位从 root 的私有槽映射。
     条目禁用走 aria-disabled 而非原生 disabled，条目仍可聚焦，家族的禁用块读 data-disabled。
     position 是给条目内那份视觉隐藏的原生输入做定位基准，别去掉 */
  [data-scope='radio-group'][data-part='item'] {
    --xh-action-gap: var(--xh-radio-group-item-gap, var(--xh-_radio-group-item-gap));
    --xh-action-radius: var(--xh-radio-group-item-radius, var(--xh-shape-control));
    --xh-action-font-size: var(--xh-radio-group-item-font-size, var(--xh-_radio-group-font-size));
    --xh-action-padding-inline: 0;
    --xh-action-padding-block: 0;
    --xh-action-fg-rest: var(--xh-radio-group-item-fg, var(--xh-fg-default));
    --xh-action-fg-hover: var(--xh-radio-group-item-fg, var(--xh-fg-default));
    --xh-action-fg-pressed: var(--xh-radio-group-item-fg, var(--xh-fg-default));
    --xh-action-fg-focus-visible: var(--xh-radio-group-item-fg, var(--xh-fg-default));
    --xh-action-fg-disabled: var(--xh-radio-group-item-fg-disabled, var(--xh-fg-disabled));
    --xh-action-bg-hover: var(--xh-radio-group-item-bg-hover, var(--xh-bg-subtle));
    --xh-action-bg-pressed: var(--xh-radio-group-item-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-action-host-bg-hover: var(--xh-_radio-group-host-bg-hover);
    --xh-action-host-bg-pressed: var(--xh-_radio-group-host-bg-pressed);

    position: relative;
    /* row 档铺满容器（inline-size: 100%）会把竖排的命中区拉到整行空白处、横排 wrap 也塌：
       沿用「条目按内容收宽」的既有决定，写法同 checkbox-group 条目 */
    inline-size: auto;
    /* ghost 的 1px 透明边位会把圆圈列相对组标题错开 1px：边归零，几何保持不变 */
    border-width: 0;
  }

  /* 只读整组都改不动，但不是禁用：颜色照常，把整行的悬停 / 按下面与"可点"这个暗示一起收回来。
     家族的 :hover / 按压块不排 readonly，只能从槽上收回；排掉禁用项是因为这条选择器权重高过家族的禁用块，
     不排就会把 not-allowed 覆盖回 default */
  [data-scope='radio-group'][data-part='item'][data-readonly]:not([data-disabled]) {
    --xh-action-bg-hover: transparent;
    --xh-action-bg-pressed: transparent;
    --xh-action-cursor-rest: default;
    --xh-action-cursor-hover: default;
    --xh-action-cursor-pressed: default;
    --xh-action-cursor-focus-visible: default;
  }

  /* 圆圈是字段家族的控制盒（字段静息形态）：透明底 + --xh-border-control 描边 + 无影。
     不缩放（行级只换面），过渡只有底与描边；按下走 press 时间线、释放同走 micro */
  [data-scope='radio-group'][data-part='indicator'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-radio-group-indicator-size, var(--xh-_radio-group-indicator));
    block-size: var(--xh-radio-group-indicator-size, var(--xh-_radio-group-indicator));
    border: var(--xh-stroke-thin) solid var(--xh-radio-group-indicator-border, var(--xh-border-control));
    border-radius: var(--xh-radio-group-indicator-radius, var(--xh-shape-circle));
    background: var(--xh-radio-group-indicator-bg, transparent);
    transition:
      border-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      background-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 悬停整行时未选中的圆圈描边升一档（字段静息 → hover 的同一条阶梯）；
     选中圈与校验失败的圈保住各自的描边——圈内的点 / 警示色本身已经在表达状态 */
  [data-scope='radio-group'][data-part='item']:not([data-disabled]):not([data-readonly]):hover
    > [data-scope='radio-group'][data-part='indicator']:not([data-state='checked']):not([data-invalid]) {
    border-color: var(--xh-radio-group-indicator-border-hover, var(--xh-border-control-hover));
  }

  /* 按下去要有回应。圆圈不是激活宿主：宿主是投影了 row 档的整行条目，圆圈在宿主的
     :hover / :is(:active, [data-pressed]) 下读宿主 host 槽的同一来源换面、不缩放——行按下是 200，
     坐在上面的圆圈到 300（行以 --xh-action-host-bg-pressed 声明自己是圆圈的承载面，桥接槽只写不读，
     圆圈读的是喂给它的那支私有槽），描边不动、几何不动；
     与家族按压块同一时间线（按下 --xh-motion-duration-press，释放同走 micro） */
  [data-scope='radio-group'][data-part='item']:not([data-disabled]):not([data-readonly]):is(:active, [data-pressed])
    > [data-scope='radio-group'][data-part='indicator'] {
    background: var(--xh-radio-group-indicator-bg-pressed, var(--xh-_radio-group-host-bg-pressed));
    transition-duration: var(--xh-motion-duration-press);
    transition-timing-function: var(--xh-motion-ease-press);
  }

  [data-scope='radio-group'][data-part='indicator'][data-state='checked'] {
    border-color: var(--xh-radio-group-indicator-border-checked, var(--xh-_radio-group-accent));
  }

  /* 校验失败：圆圈描边转警示色，压在 checked 规则之后 */
  [data-scope='radio-group'][data-part='indicator'][data-invalid],
  [data-scope='radio-group'][data-part='indicator'][data-state='checked'][data-invalid] {
    border-color: var(--xh-radio-group-indicator-border-invalid, var(--xh-border-invalid));
  }

  /* 圆点用 scale 收放，选中态切换不引起布局抖动。
     直径取指示器的一半：换尺寸档时圈与点一起走，比例不散。
     出现时略微涨过 1 再收回，过冲量落在圈内不碰描边 */
  [data-scope='radio-group'][data-part='indicator']::before {
    content: '';
    inline-size: calc(var(--xh-radio-group-indicator-size, var(--xh-_radio-group-indicator)) / 2);
    block-size: calc(var(--xh-radio-group-indicator-size, var(--xh-_radio-group-indicator)) / 2);
    border-radius: var(--xh-shape-circle);
    background: var(--xh-radio-group-indicator-dot, var(--xh-_radio-group-accent));
    scale: 0;
    transition: scale var(--xh-motion-duration-nudge) var(--xh-motion-ease-settle);
  }

  [data-scope='radio-group'][data-part='indicator'][data-state='checked']::before {
    scale: 1;
  }

  /* 选中的圆点是这颗圈的「填色」：按下随行换到语气的 active 档（与 checkbox-group 勾中方框按下同档），
     选中圈的描边保住不换 */
  [data-scope='radio-group'][data-part='item']:not([data-disabled]):not([data-readonly]):is(:active, [data-pressed])
    > [data-scope='radio-group'][data-part='indicator'][data-state='checked']::before {
    background: var(--xh-radio-group-indicator-dot-pressed, var(--xh-_tone-active, var(--xh-bg-brand-active)));
  }

  /* 禁用：--xh-border-default 描边 + --xh-bg-subtle 底 + --xh-fg-disabled 圆点，不靠 opacity；
     与 checkbox-group 方框、独立 checkbox 逐档一致。条目自己带 data-disabled（组禁用也逐条下放），圆圈读它 */
  [data-scope='radio-group'][data-part='item'][data-disabled] > [data-scope='radio-group'][data-part='indicator'] {
    border-color: var(--xh-radio-group-indicator-border-disabled, var(--xh-border-default));
    background: var(--xh-radio-group-indicator-bg-disabled, var(--xh-bg-subtle));
  }

  [data-scope='radio-group'][data-part='item'][data-disabled] > [data-scope='radio-group'][data-part='indicator']::before {
    background: var(--xh-radio-group-indicator-dot-disabled, var(--xh-fg-disabled));
  }

  [data-scope='radio-group'][data-part='item-text'] {
    color: inherit;
    user-select: none;
  }

  /* 家族 row 档在粗指针下用 ::after 把热区扩到 44px 高：条目按 24px 行 + 8px 间距密排，热区会压进相邻条目、
     指针落错行，A 档 24px 由 xs 地板保住（同 checkbox-group 条目） */
  @media (pointer: coarse) {
    [data-scope='radio-group'][data-part='item']::after {
      min-block-size: 0;
    }
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='radio-group'][data-part='root'][hidden],
  [data-scope='radio-group'][data-part='item'][hidden],
  [data-scope='radio-group'][data-part='indicator'][hidden] {
    display: none;
  }

  @media (forced-colors: active) {
    /* 按下：常态靠圆圈换底表出，这一档里底色被统一换成 Canvas；按住那一下把圈的描边换成系统高亮色 */
    [data-scope='radio-group'][data-part='item']:not([data-disabled]):not([data-readonly]):is(:active, [data-pressed])
      > [data-scope='radio-group'][data-part='indicator'] {
      border-color: Highlight;
    }

    /* 禁用的圆点跟随系统的置灰前景 */
    [data-scope='radio-group'][data-part='item'][data-disabled]
      > [data-scope='radio-group'][data-part='indicator'][data-state='checked']::before {
      background: GrayText;
    }
  }

  @media print {
    /* 打印默认丢底色：选中那颗圆点是一块底，落到纸上整个消失，选中与没选中的圈一模一样。
       圆点改画成一圈实边——边框印得出来，直径与圆心都不动（描边吃进盒里）。 */
    [data-scope='radio-group'][data-part='indicator'][data-state='checked']::before {
      border: var(--xh-stroke-thick) solid currentColor;
    }
  }
}

/* styles/rating.css */
/* 定义 rating 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='rating'] {
    --xh-rating-skin: 1;
  }

  /* position 是给表单影子做定位基准的：那份输入被连接层内联写成绝对定位，
     根上不留基准它就会贴到更外层的定位祖先上，原生校验提示跟着飘到页面别处。 */
  [data-scope='rating'][data-part='root'] {
    /* 尺寸档只换这三个私有槽，星星与分值都从 root 继承它们，换档不必给每个部件各写一条选择器。
       星是控件内的字形，按档取 --xh-glyph-size-sm / md / lg；标签字号不随档 */
    --xh-_rating-item-gap: var(--xh-control-gap-md);
    --xh-_rating-item-size: var(--xh-glyph-size-md);
    --xh-_rating-item-box-size: var(--xh-control-action-size);
    --xh-_rating-font-size: var(--xh-control-font-md);
    --xh-icon-size: var(--xh-rating-item-font-size, var(--xh-_rating-item-size));
    /* 点亮色随语气走。没写 data-tone 时 --xh-_tone 没被声明，退回原来的警示色 */
    --xh-_rating-accent: var(--xh-_tone, var(--xh-color-warning-500));

    position: relative;
    display: inline-flex;
    flex-direction: column;
    /* 字段标签贴控件（复合单字段） */
    gap: var(--xh-rating-gap, var(--xh-space-1));
  }

  /* —— 尺寸 —— */
  [data-scope='rating'][data-part='root'][data-size='sm'] {
    --xh-_rating-item-gap: var(--xh-control-gap-sm);
    --xh-_rating-item-size: var(--xh-glyph-size-sm);
    --xh-_rating-font-size: var(--xh-control-font-sm);
  }

  [data-scope='rating'][data-part='root'][data-size='lg'] {
    --xh-_rating-item-gap: var(--xh-control-gap-lg);
    --xh-_rating-item-size: var(--xh-glyph-size-lg);
    --xh-_rating-font-size: var(--xh-control-font-lg);
  }

  /* 字段标签：14 / 500 / fg-default，禁用换到 --xh-fg-subtle；文字部件不叠 opacity */
  [data-scope='rating'][data-part='label'] {
    color: var(--xh-rating-label-fg, var(--xh-fg-default));
    font-size: var(--xh-rating-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-rating-label-font-weight, var(--xh-text-label-weight));
  }

  [data-scope='rating'][data-part='label'][data-disabled] {
    color: var(--xh-rating-label-fg-disabled, var(--xh-fg-subtle));
  }

  [data-scope='rating'][data-part='control'] {
    display: inline-flex;
    align-items: center;
    gap: var(--xh-rating-item-gap, var(--xh-_rating-item-gap));
  }

  /* 禁用：星带是纯图形，整体压暗只做一次、落在星带上（星星逐颗再叠 opacity 会越叠越黑）；
     标签与分值是文字，各自换到禁用前景，不落在这层 opacity 之下 */
  [data-scope='rating'][data-part='control'][data-disabled] {
    opacity: var(--xh-state-disabled-opacity);
  }

  /* 分值文本在场时根改成两列栅格：星星带与分值并排，标题仍独占一整行。
     没写这个部件的评分不命中这条，还是原来的竖排 */
  [data-scope='rating'][data-part='root']:has(> [data-part='value-text']) {
    display: inline-grid;
    grid-template-columns: auto auto;
    align-items: center;
    justify-content: start;
  }

  [data-scope='rating'][data-part='root']:has(> [data-part='value-text']) > [data-part='label'] {
    grid-column: 1 / -1;
  }

  /* 数字等宽：指针从一颗星划到另一颗时分值在原地变，不带着星星左右挪 */
  [data-scope='rating'][data-part='value-text'] {
    color: var(--xh-rating-value-text-fg, var(--xh-fg-muted));
    font-size: var(--xh-rating-value-text-font-size, var(--xh-_rating-font-size));
    font-variant-numeric: tabular-nums;
    line-height: var(--xh-leading-none);
  }

  [data-scope='rating'][data-part='value-text'][data-disabled] {
    color: var(--xh-rating-value-text-fg-disabled, var(--xh-fg-subtle));
  }

  /* 容器只是焦点域的兜底落点（焦点从带外进来先落在它身上，随即被转投给某颗星），
     落焦不画环：高亮永远长在星星上，容器再画一圈只是重影。 */
  [data-scope='rating'][data-part='control']:focus-visible {
    outline: none;
  }

  [data-scope='rating'][data-part='control'][data-readonly]:not([data-disabled]) {
    cursor: default;
  }

  /* 条目固定成一枚方形图标盒：连接层用 clientWidth 判定指针落在左半还是右半，
     固定盒能让半档分界与图形中心严格重合。
     星接 Action Control icon 档（定尺的星）：盒型、按下 / 禁用面、0.97 缩放与换底、焦点环与过渡由家族配方给，
     这里只把使用者槽映射到桥接槽。静息透明（ghost 形态）；悬停不换底——悬停预览由点亮的星形（data-highlighted）
     表达，再给盒换面是重复的通道；按下换到 200 档中性面（白底承载）。前景五态映射同一个值：点亮时五态一起换到
     点亮色，家族的悬停 / 按下块才不会把点亮色换回静息色；禁用不换前景，星带整体的压暗落在 control 的 opacity 上 */
  [data-scope='rating'][data-part='item'] {
    --xh-_rating-item-bg-pressed: var(--xh-rating-item-bg-pressed, var(--xh-bg-subtle-hover));

    --xh-action-visual-size: var(--xh-_rating-item-box-size);
    --xh-action-min-inline-size: var(--xh-_rating-item-box-size);
    --xh-action-radius: var(--xh-rating-item-radius, var(--xh-shape-control));
    --xh-action-font-size: var(--xh-rating-item-font-size, var(--xh-_rating-item-size));
    --xh-action-bg-hover: transparent;
    --xh-action-bg-pressed: var(--xh-_rating-item-bg-pressed);
    --xh-action-fg-rest: var(--xh-rating-item-fg, var(--xh-fg-subtle));
    --xh-action-fg-hover: var(--xh-rating-item-fg, var(--xh-fg-subtle));
    --xh-action-fg-pressed: var(--xh-rating-item-fg, var(--xh-fg-subtle));
    --xh-action-fg-focus-visible: var(--xh-rating-item-fg, var(--xh-fg-subtle));
    --xh-action-fg-disabled: var(--xh-rating-item-fg, var(--xh-fg-subtle));
    --xh-action-border-rest: transparent;
    --xh-action-border-hover: transparent;
    --xh-action-border-pressed: transparent;
    --xh-action-border-focus-visible: transparent;
    --xh-action-border-disabled: transparent;
  }

  /* 家族 icon 档在粗指针下用 ::after 扩热区到 44px：五颗星密排，44px 热区会压住相邻的星，
     连接层又按 currentTarget 的宽度判半颗，热区串到邻星上半档就判错；星本身仍是 24px 盒，热区不外扩。
     空条目的 ::after 是点亮那层星形，下限归零才不会被撑成 44px */
  @media (pointer: coarse) {
    [data-scope='rating'][data-part='item']::after {
      min-inline-size: 0;
      min-block-size: 0;
    }
  }

  /* 空条目使用两层同源星形：底层保持中性轮廓，上层按完整或半档裁出强调色。 */
  [data-scope='rating'][data-part='item']:empty::before,
  [data-scope='rating'][data-part='item']:empty::after {
    content: '';
    position: absolute;
    inset-block-start: 50%;
    inset-inline-start: 50%;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    translate: -50% -50%;
    background-color: var(--xh-rating-item-fg, var(--xh-fg-subtle));
    -webkit-mask: var(--xh-glyph-mark-star) center / contain no-repeat;
    mask: var(--xh-glyph-mark-star) center / contain no-repeat;
    pointer-events: none;
  }

  [data-scope='rating'][data-part='item']:empty::after {
    background-color: var(--xh-rating-item-fg-highlighted, var(--xh-_rating-accent));
    clip-path: inset(0 100% 0 0);
    transition: clip-path var(--xh-motion-duration-nudge) var(--xh-motion-ease-continuous);
  }

  /* 点亮的判据是 data-highlighted，不是 aria-checked：
     aria-checked 只认落定的值，而悬停预览要求手划过去当场就亮。
     两者共用同一档颜色，预览与选中因此看不出差别——这正是"预览"该有的样子。 */
  [data-scope='rating'][data-part='item'][data-highlighted] {
    --xh-action-fg-rest: var(--xh-rating-item-fg-highlighted, var(--xh-_rating-accent));
    --xh-action-fg-hover: var(--xh-rating-item-fg-highlighted, var(--xh-_rating-accent));
    --xh-action-fg-pressed: var(--xh-rating-item-fg-highlighted, var(--xh-_rating-accent));
    --xh-action-fg-focus-visible: var(--xh-rating-item-fg-highlighted, var(--xh-_rating-accent));
    --xh-action-fg-disabled: var(--xh-rating-item-fg-highlighted, var(--xh-_rating-accent));
  }

  [data-scope='rating'][data-part='item'][data-highlighted]:empty::after {
    clip-path: inset(0);
  }

  /* 半颗：一道 50% 硬边渐变裁到字形上，左半亮右半灰。
     必须排在 data-highlighted 之后：半颗那颗星同时带着 data-highlighted，两条选择器特异度相同，
     顺序一反 color 就把 transparent 覆盖回实色，渐变整个看不见。 */
  [data-scope='rating'][data-part='item'][data-half]:not(:empty) {
    background-image: linear-gradient(
      to right,
      var(--xh-rating-item-fg-highlighted, var(--xh-_rating-accent)) 50%,
      var(--xh-rating-item-fg, var(--xh-fg-subtle)) 50%
    );
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }

  /* rtl 下"半颗"落在星的右半边（连接层按 1 - offsetX/width 判），亮的那半得跟着掉头。
     渐变方向没有逻辑关键字可用，只能靠 :dir() 分流，不能指望逻辑属性自动换向。 */
  [data-scope='rating'][data-part='item'][data-half]:not(:empty):dir(rtl) {
    background-image: linear-gradient(
      to left,
      var(--xh-rating-item-fg-highlighted, var(--xh-_rating-accent)) 50%,
      var(--xh-rating-item-fg, var(--xh-fg-subtle)) 50%
    );
  }

  [data-scope='rating'][data-part='item'][data-half]:empty::after {
    clip-path: inset(0 50% 0 0);
  }

  [data-scope='rating'][data-part='item'][data-half]:empty:dir(rtl)::after {
    clip-path: inset(0 0 0 50%);
  }

  /* 只读仍进得了 Tab 序列、读屏也念得出，只是改不动：收掉手型，别暗示"点这儿能改"；
     家族的按压块由这里的映射钉回静息面——按下不缩放、不换底 */
  [data-scope='rating'][data-part='item'][data-readonly]:not([data-disabled]) {
    --xh-_rating-item-bg-pressed: transparent;
    --xh-action-scale-pressed: none;
    --xh-action-cursor-rest: default;
    --xh-action-cursor-hover: default;
    --xh-action-cursor-pressed: default;
    --xh-action-cursor-focus-visible: default;
  }

  /* 表单影子的视觉隐藏（绝对定位 + 1px + clip-path）连接层内联给全了，这里不重复也不覆盖，
     只掐掉指针命中：那个 1px 的框压在星带上会截走本该落到星星上的点击。 */
  [data-scope='rating'][data-part='hidden-input'] {
    pointer-events: none;
  }

  /* display 会盖掉 UA 的 [hidden]{display:none}，凡是被赋了 display 的角色节点都要显式让位 */
  [data-scope='rating'][data-part='root'][hidden],
  [data-scope='rating'][data-part='control'][hidden],
  [data-scope='rating'][data-part='item'][hidden] {
    display: none;
  }

  /*
   * 高对比档：点亮与没点亮只差一档字色，这一档里两档一起被换成同一个系统前景色，
   * 整条星带看上去全是亮的。改用系统自己的两个角色分开：亮的取高亮色、没亮的取不可用色。
   * 半颗那道裁到字形上的渐变在这一档里被丢弃，留着透明填充整颗星会消失，
   * 把填充还回去并按点亮那一档画。
   */
  @media (forced-colors: active) {
    [data-scope='rating'][data-part='item'] {
      color: GrayText;
    }

    [data-scope='rating'][data-part='item']:empty::before {
      background-color: GrayText;
    }

    [data-scope='rating'][data-part='item']:empty::after {
      background-color: Highlight;
    }

    [data-scope='rating'][data-part='item'][data-highlighted],
    [data-scope='rating'][data-part='item'][data-half]:not(:empty) {
      background-image: none;
      -webkit-background-clip: border-box;
      background-clip: border-box;
      color: Highlight;
      /* 亮档已经由字色表出，公共层那圈锚点虚线在这里只是重影 */
      outline: none;
    }

    /* 家族在这一档把悬停 / 按下的盒填成 Highlight、字换 HighlightText：点亮的那层星形也是 Highlight，
       填了盒就把它吞掉。盒保持 Canvas 底，字色仍按点亮与否取 GrayText / Highlight；
       按住那一下给盒画一圈系统高亮环表出按下 */
    [data-scope='rating'][data-part='item']:not([data-disabled]):not([data-loading]):hover,
    [data-scope='rating'][data-part='item']:not([data-disabled]):not([data-loading]):is(:active, [data-pressed]) {
      background-color: Canvas;
      color: GrayText;
    }

    [data-scope='rating'][data-part='item'][data-highlighted]:not([data-disabled]):not([data-loading]):hover,
    [data-scope='rating'][data-part='item'][data-highlighted]:not([data-disabled]):not([data-loading]):is(:active, [data-pressed]) {
      color: Highlight;
    }

    [data-scope='rating'][data-part='item']:not([data-disabled]):not([data-readonly]):is(:active, [data-pressed]) {
      outline: var(--xh-stroke-thick) solid Highlight;
      outline-offset: calc(-1 * var(--xh-stroke-thick));
    }
  }

  @media print {
    /* 打印默认丢底图：半颗那道裁到字形上的渐变整个消失，星上只剩 color: transparent，
       那颗星在纸上什么都不剩。把填充还回去并按点亮那一档画整颗。 */
    [data-scope='rating'][data-part='item'][data-half]:not(:empty) {
      background-image: none;
      -webkit-background-clip: border-box;
      background-clip: border-box;
      color: var(--xh-rating-item-fg-highlighted, var(--xh-_rating-accent));
    }
  }
}

/* styles/scroll-area.css */
/* 定义 scroll area 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='scroll-area'] {
    --xh-scroll-area-skin: 1;
  }

  /* 滚动区是视口加两条 scrollbar 的组装：轨道、滑块与交叉口戴 data-scope="scrollbar"，
     它们的皮归 scrollbar.css；这里只管视口、内容层，以及充当 scrollbar 根节点的那个挂载点。 */

  /* 滚动条是绝对定位的，以它为参照，因此它必须自己建定位上下文。
     overflow:hidden 管的是溢出边界：作者给 root 定了尺寸后，内容与滚动条都不该漫出这个框。 */
  [data-scope='scroll-area'][data-part='root'] {
    /* 厚度只算一次：尺寸档换的就是它，视口让道、交叉口让位与补丁都按同一个数 */
    --xh-_scrollbar-thickness: var(--xh-scrollbar-thickness-md);

    position: relative;
    overflow: hidden;
  }

  [data-scope='scroll-area'][data-part='root'][data-size='sm'] {
    --xh-_scrollbar-thickness: var(--xh-scrollbar-thickness-sm);
  }

  [data-scope='scroll-area'][data-part='root'][data-size='lg'] {
    --xh-_scrollbar-thickness: var(--xh-scrollbar-thickness-lg);
  }

  /* 真正滚动的那层。原生滚动条藏起来，滚动能力一点不减——
     键盘（PageUp/PageDown、方向键、Home/End）与滚轮走的都还是浏览器原生通路。 */
  [data-scope='scroll-area'][data-part='viewport'] {
    inline-size: 100%;
    block-size: 100%;
    /* 逻辑等价物 overflow-inline / overflow-block 至今只有个别引擎实现，
       这两条是本文件里仅有的物理属性，换成逻辑写法会在多数浏览器上直接失效 */
    overflow-x: auto;
    overflow-y: auto;
  }

  /* 藏原生滚动条的标准写法；下面那条 ::-webkit-scrollbar 兜住还没实现它的引擎。
     只藏外观，滚动能力一点不动：这里刻意不写 overscroll-behavior，
     滚到尽头要不要把滚动传给外层，仍然按浏览器的默认来。
     触屏上自绘滚动条交给了原生（data-native），原生滚动条就留着 */
  [data-scope='scroll-area'][data-part='viewport']:not([data-native]) {
    scrollbar-width: none;
  }

  [data-scope='scroll-area'][data-part='viewport']:not([data-native])::-webkit-scrollbar {
    /* 这里不是角色节点而是伪元素，不涉及 [hidden] 那条规矩 */
    display: none;
  }

  /* orientation 关掉的那条轴不该滚：滚动条已经不显形了，再能滚就成了滚不回来的暗格 */
  [data-scope='scroll-area'][data-part='viewport'][data-orientation='vertical'] {
    overflow-x: hidden;
  }

  [data-scope='scroll-area'][data-part='viewport'][data-orientation='horizontal'] {
    overflow-y: hidden;
  }

  /* 有滚动条要占道时，视口在那条轴上收窄一条道的宽度，末端内容不再被压在滚动条底下。
     缩视口而不是给视口加内边距：滚动容器末端缘的 padding 计不计进 scrollWidth，各引擎不一致。 */
  [data-scope='scroll-area'][data-part='viewport'][data-lane-vertical] {
    inline-size: calc(100% - var(--xh-_scrollbar-thickness));
  }

  [data-scope='scroll-area'][data-part='viewport'][data-lane-horizontal] {
    block-size: calc(100% - var(--xh-_scrollbar-thickness));
  }

  /* —— 边缘渐隐 —— */
  /* 两条轴各铺一层遮罩，取交集：还滚得动的那一侧把内容淡出，滚到头即收成 0。
     渐变没有逻辑方向，只能沿物理方向铺，横轴那一层的两端在 rtl 下对调（见下）。
     遮罩里的黑白画的是 alpha 的两端，不是设计色。
     -webkit-* 那两条排在前面兜住只认前缀写法的引擎。
     画在视口上而不是根上：自绘滚动条是视口的兄弟节点，不会跟着一起淡掉 */
  [data-scope='scroll-area'][data-part='viewport'][data-variant='fade'] {
    /* 渐隐带宽跟着尺寸档走，与滚动条厚度同一个 data-size */
    --xh-_scroll-area-fade-size: var(--xh-scroll-area-fade-size, var(--xh-space-6));
    /* 四条边各自的带宽：到头那一侧收成 0，没到头才铺开 */
    --xh-_scroll-area-fade-block-start: 0px;
    --xh-_scroll-area-fade-block-end: 0px;
    --xh-_scroll-area-fade-inline-start: 0px;
    --xh-_scroll-area-fade-inline-end: 0px;
    --xh-_scroll-area-fade-left: var(--xh-_scroll-area-fade-inline-start);
    --xh-_scroll-area-fade-right: var(--xh-_scroll-area-fade-inline-end);

    -webkit-mask-image:
      linear-gradient(to bottom, transparent 0, black var(--xh-_scroll-area-fade-block-start), black calc(100% - var(--xh-_scroll-area-fade-block-end)), transparent 100%),
      linear-gradient(to right, transparent 0, black var(--xh-_scroll-area-fade-left), black calc(100% - var(--xh-_scroll-area-fade-right)), transparent 100%);
    mask-image:
      linear-gradient(to bottom, transparent 0, black var(--xh-_scroll-area-fade-block-start), black calc(100% - var(--xh-_scroll-area-fade-block-end)), transparent 100%),
      linear-gradient(to right, transparent 0, black var(--xh-_scroll-area-fade-left), black calc(100% - var(--xh-_scroll-area-fade-right)), transparent 100%);
    -webkit-mask-composite: source-in;
    mask-composite: intersect;
  }

  [data-scope='scroll-area'][data-part='viewport'][data-variant='fade'][data-size='sm'] {
    --xh-_scroll-area-fade-size: var(--xh-scroll-area-fade-size, var(--xh-space-4));
  }

  [data-scope='scroll-area'][data-part='viewport'][data-variant='fade'][data-size='lg'] {
    --xh-_scroll-area-fade-size: var(--xh-scroll-area-fade-size, var(--xh-space-8));
  }

  /* 还回得去、还去得了的那一侧才铺带：贴着那一端时属性在场，规则不命中 */
  [data-scope='scroll-area'][data-part='viewport'][data-variant='fade']:not([data-at-min-vertical]) {
    --xh-_scroll-area-fade-block-start: var(--xh-_scroll-area-fade-size);
  }

  [data-scope='scroll-area'][data-part='viewport'][data-variant='fade']:not([data-at-max-vertical]) {
    --xh-_scroll-area-fade-block-end: var(--xh-_scroll-area-fade-size);
  }

  [data-scope='scroll-area'][data-part='viewport'][data-variant='fade']:not([data-at-min-horizontal]) {
    --xh-_scroll-area-fade-inline-start: var(--xh-_scroll-area-fade-size);
  }

  [data-scope='scroll-area'][data-part='viewport'][data-variant='fade']:not([data-at-max-horizontal]) {
    --xh-_scroll-area-fade-inline-end: var(--xh-_scroll-area-fade-size);
  }

  /* 从右往左排版时横轴的起始端在右：两端对调，逻辑那两支槽的取值不动 */
  [dir='rtl'] [data-scope='scroll-area'][data-part='viewport'][data-variant='fade'] {
    --xh-_scroll-area-fade-left: var(--xh-_scroll-area-fade-inline-end);
    --xh-_scroll-area-fade-right: var(--xh-_scroll-area-fade-inline-start);
  }

  /* 横向溢出全靠它撑：内容若跟着视口一起收成 100% 宽，横轴永远量不出溢出，
     横向滚动条也就永远不显形。 */
  [data-scope='scroll-area'][data-part='content'] {
    min-inline-size: fit-content;
  }

  /* 滚动条挂载点同时充当那条 scrollbar 的根节点：scrollbar 那份皮肤的根规则落在
     [data-scope='scrollbar'][data-part='root'] 上，而这里没有那个节点，根该有的排布得在这儿补齐
     （轨道与滑块的皮仍归 scrollbar 那一份）。滑块主轴的起点与长度由连接层写进内联样式，这里不碰。 */
  [data-scope='scroll-area'][data-part='scrollbar'] {
    position: absolute;
    /* 浮层的 positioner 一律 pointer-events: none，条子作为它的子节点会继承到，拖不动也点不着；
       收起态那条规则优先级更高，仍旧穿透 */
    pointer-events: auto;
    /* touch-action 关掉浏览器自己的手势：不关的话手指一按滑块页面就跟着滚，
       指针随即被系统收走（pointercancel），拖到一半的滑块停在原地。
       user-select 同理——拖动时选中页面文字会让滑块"粘"住。 */
    touch-action: none;
    user-select: none;
    /* 露出与收起都淡变；收起态连 visibility 一起收，退场播完才真正摸不到 */
    transition:
      opacity var(--xh-motion-duration-enter) var(--xh-motion-ease-enter),
      visibility 0s linear 0s;
  }

  [data-scope='scroll-area'][data-part='scrollbar'][data-orientation='vertical'] {
    inset-block: 0;
    inset-inline-end: 0;
    inline-size: var(--xh-_scrollbar-thickness);
  }

  [data-scope='scroll-area'][data-part='scrollbar'][data-orientation='horizontal'] {
    inset-inline: 0;
    inset-block-end: 0;
    block-size: var(--xh-_scrollbar-thickness);
  }

  /* 两条都在场：各自在末端让出交叉口那一格，交叉口由竖条里的 corner 补 */
  [data-scope='scroll-area'][data-part='scrollbar'][data-orientation='vertical'][data-gutter] {
    inset-block-end: var(--xh-_scrollbar-thickness);
  }

  [data-scope='scroll-area'][data-part='scrollbar'][data-orientation='horizontal'][data-gutter] {
    inset-inline-end: var(--xh-_scrollbar-thickness);
  }

  [data-scope='scroll-area'][data-part='scrollbar'][data-state='hidden'] {
    visibility: hidden;
    opacity: 0;
    pointer-events: none;
    transition:
      opacity var(--xh-motion-duration-exit) var(--xh-motion-ease-exit),
      visibility 0s linear var(--xh-motion-duration-exit);
  }

  /* 触屏上交给原生滚动：整条不占位也不画 */
  [data-scope='scroll-area'][data-part='scrollbar'][data-native] {
    display: none;
  }

  /* 除视口外全是纯容器：既不进 Tab 序列也不承载焦点，作者若给它们加了 tabindex，
     该显形的也该是视口那圈环，不是这里再多画一圈 */
  [data-scope='scroll-area'][data-part='root']:focus-visible,
  [data-scope='scroll-area'][data-part='content']:focus-visible,
  [data-scope='scroll-area'][data-part='scrollbar']:focus-visible {
    outline: none;
  }

  /* display 会盖掉 UA 的 [hidden]{display:none}，凡是被赋了 display 的角色节点都要显式让位 */
  [data-scope='scroll-area'][data-part='scrollbar'][hidden] {
    display: none;
  }
}

/* styles/scrollbar.css */

/* styles/select.css */
/* Select 独立皮肤同时传递引入字段视觉盒、字段内动作与浮层集合行；full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='select'] {
    --xh-select-skin: 1;
  }

  /* 坐标由定位引擎写进 style（inset-inline-start / inset-block-start），这里只定位模式与层级 */
  [data-scope='select'][data-part='positioner'] {
    /* 落定那一侧的可用高度，由定位引擎经内联自定义属性写进来，内容层继承它限高；
       引擎没算（尚未落位 / 无引擎）时不额外限高 */
    --xh-_select-available-h: 100vh;
    /* 落定那一侧的可用宽度，同样由定位引擎经内联自定义属性写进来，行内轴据此夹取；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时退到视口宽 */
    --xh-_select-available-w: 100vw;
    /* 触发器实测宽度，由定位引擎经内联自定义属性写进来，内容层拿它当最小宽的下界；
       引擎没算（尚未落位 / 无引擎）时为 0，max 取静态档，等于不抬宽 */
    --xh-_select-anchor-w: 0px;
    /* WC 嵌套层仍在父层 DOM 内；先截断父 positioner 的方向，再按本层 placement 开一侧。 */
    --xh-_overlay-enter-up: 0;
    --xh-_overlay-enter-down: 0;
    --xh-_overlay-enter-left: 0;
    --xh-_overlay-enter-right: 0;
    /* 列表的自绘条浮在内容之上：轨道不上底色，实色轨道会在列表右缘糊一条竖灰带 */
    --xh-scrollbar-track-bg: transparent;

    position: fixed;
    z-index: var(--xh-select-layer, var(--xh-_layer, var(--xh-layer-popover)));
    /* 空壳不吃指针，交互只发生在 content 上 */
    pointer-events: none;
  }

  /* 锚点被滚出可视区：整个浮层随之收起 */
  [data-scope='select'][data-part='positioner'][data-hidden] {
    visibility: hidden;
  }

  /* 进场位移按落定的一侧给。placement 与 translate 都是物理量，不随书写方向翻。 */
  [data-scope='select'][data-part='positioner'][data-placement^='top'] {
    --xh-_overlay-enter-down: 1;
  }

  [data-scope='select'][data-part='positioner'][data-placement^='bottom'] {
    --xh-_overlay-enter-up: 1;
  }

  [data-scope='select'][data-part='positioner'][data-placement^='left'] {
    --xh-_overlay-enter-right: 1;
  }

  [data-scope='select'][data-part='positioner'][data-placement^='right'] {
    --xh-_overlay-enter-left: 1;
  }

  /* 私有槽同时声明在根与 positioner 上：浮层被搬到 portal 落点，不是根的后代，继承不过去 */
  [data-scope='select']:is([data-part='root'], [data-part='positioner']) {
    /* 尺寸档只换这几个私有槽，触发器与条目都从这两处继承它们，
       换档不必给每个部件各写一条选择器；形态三档由家族按 control 上的 data-variant 生成，皮肤不再声明 */
    --xh-_select-h: var(--xh-control-h-md);
    --xh-_select-px: var(--xh-control-px-md);
    --xh-_select-item-py: var(--xh-list-option-py-md);
    --xh-_select-item-px: var(--xh-control-px-md);
    --xh-_select-gap: var(--xh-control-gap-md);
    --xh-_select-font-size: var(--xh-control-font-md);

    /* 语气只落在勾选标记上，单选与多选正文使用同一颜色。 */
    --xh-_select-accent: var(--xh-_tone, var(--xh-fg-brand));
  }

  [data-scope='select'][data-part='root'] {
    /* 作者塞进指示符槽的图标跟着控件的尺寸档走；它自己写了 size 时仍以作者的为准。
       浮层条目里自绘的状态字形（勾选标记所在的标记盒与盒里的勾）不读这支：它们是指示符，走
       --xh-control-indicator-* 一族——标记盒在自己身上把 --xh-icon-size 改接到盒的尺 */
    --xh-icon-size: var(--xh-select-icon-size, var(--xh-glyph-size-md));

    display: inline-flex;
    flex-direction: column;
    gap: var(--xh-select-gap, var(--xh-space-1));
    /* 隐藏 select 以此为定位基准：它必须留在布局里，原生校验提示要有处可贴 */
    position: relative;

    /* 不传尺寸时一律这么宽，宽度不随内容走；父容器给不出这么宽时整件跟着收，地板同步让步，不越出父容器。
       地板不高过缺省宽：使用者把缺省宽钉到底线以下时不必再放开底线 */
    inline-size: var(--xh-select-control-w, var(--xh-control-w));
    min-inline-size: min(var(--xh-select-control-w, var(--xh-control-w)), var(--xh-select-control-min-w, var(--xh-control-min-w)), 100%);
    max-inline-size: 100%;
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里 */
  [data-scope='select']:is([data-part='root'], [data-part='positioner'])[data-size='sm'] {
    --xh-_select-h: var(--xh-control-h-sm);
    --xh-_select-px: var(--xh-control-px-sm);
    --xh-_select-item-py: var(--xh-list-option-py-sm);
    --xh-_select-item-px: var(--xh-control-px-sm);
    --xh-_select-gap: var(--xh-control-gap-sm);
    --xh-_select-font-size: var(--xh-control-font-sm);
  }

  /* 图标只跟着盒那一侧换档：浮层里的勾选标记有自己的指示符盒，换成整档图标会撑破它 */
  [data-scope='select'][data-part='root'][data-size='sm'] {
    --xh-icon-size: var(--xh-select-icon-size, var(--xh-glyph-size-sm));
  }

  [data-scope='select'][data-part='root'][data-size='lg'] {
    --xh-icon-size: var(--xh-select-icon-size, var(--xh-glyph-size-lg));
  }

  [data-scope='select']:is([data-part='root'], [data-part='positioner'])[data-size='lg'] {
    --xh-_select-h: var(--xh-control-h-lg);
    --xh-_select-px: var(--xh-control-px-lg);
    --xh-_select-item-py: var(--xh-list-option-py-lg);
    --xh-_select-item-px: var(--xh-control-px-lg);
    --xh-_select-gap: var(--xh-control-gap-lg);
    --xh-_select-font-size: var(--xh-control-font-lg);
  }

  [data-scope='select'][data-part='label'] {
    color: var(--xh-select-label-fg, var(--xh-fg-default));
    font-size: var(--xh-select-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-select-label-font-weight, var(--xh-text-label-weight));
    line-height: var(--xh-leading-none);
  }

  [data-scope='select'][data-part='label'][data-disabled] {
    color: var(--xh-select-label-fg-disabled, var(--xh-fg-subtle));
  }

  /* 盒：描边、底色、圆角、控件高度、行内内衬、聚焦环、五态与悬停由 Field Chrome 家族画在这一层，
     触发器与清空按钮在里面并排；焦点落在哪颗按钮上，看到的都是同一个框亮起来（家族 :focus-within）。
     组件只映射既有公开槽（shadow 缺省 none：字段静息描边式、无影）；盒里是按钮而不是文本光标 */
  [data-scope='select'][data-part='control'] {
    --xh-field-control-height: var(--xh-select-control-h, var(--xh-_select-h));
    --xh-field-control-padding-inline: var(--xh-select-control-px, var(--xh-_select-px));
    --xh-field-control-gap: var(--xh-select-control-gap, var(--xh-_select-gap));
    --xh-field-control-min-inline-size: var(--xh-select-control-min-w, var(--xh-control-min-w));
    --xh-field-control-radius: var(--xh-select-control-radius, var(--xh-shape-control));
    --xh-field-bg-rest: var(--xh-select-control-bg, var(--xh-_field-variant-bg-rest));
    --xh-field-bg-hover: var(--xh-select-control-bg-hover, var(--xh-_field-variant-bg-hover));
    --xh-field-bg-read-only: var(--xh-select-control-bg-readonly, var(--xh-_field-variant-bg-read-only));
    --xh-field-bg-disabled: var(--xh-select-control-bg-disabled, var(--xh-_field-variant-bg-disabled));
    --xh-field-fg-rest: var(--xh-select-control-fg, var(--xh-fg-default));
    --xh-field-border-rest: var(--xh-select-control-border, var(--xh-_field-variant-border-rest));
    --xh-field-border-hover: var(--xh-select-control-border-hover, var(--xh-_field-variant-border-hover));
    --xh-field-border-focus: var(--xh-select-control-border-focus, var(--xh-_field-variant-border-focus));
    --xh-field-border-invalid: var(--xh-select-control-border-invalid, var(--xh-_field-variant-border-invalid));
    --xh-field-ring-focus: var(--xh-ring-focus);
    --xh-field-ring-invalid: var(--xh-ring-invalid);
    --xh-field-shadow-rest: var(--xh-select-control-shadow, none);
    --xh-field-cursor-rest: pointer;
    /* 家族 chrome 会重写 --xh-icon-size，使用者图标槽必须经桥接槽下发才能在盒内生效 */
    --xh-field-glyph-size: var(--xh-select-icon-size, var(--xh-_field-size-glyph-size));
  }

  /* 触发器退化成盒里那颗可聚焦的按钮：描边、底色与内衬归盒，它只占满剩余一行 */
  [data-scope='select'][data-part='trigger'] {
    display: inline-flex;
    flex: 1 1 auto;
    align-items: center;
    justify-content: space-between;
    gap: var(--xh-select-trigger-gap, var(--xh-_select-gap));
    /* 弹性子项默认最小尺寸是内容尺寸，不归零则长值把盒撑破、省略号永远轮不到 */
    min-inline-size: 0;
    padding: 0;
    border: 0;
    background: transparent;
    color: var(--xh-select-trigger-fg, var(--xh-fg-default));
    font-size: var(--xh-select-trigger-font-size, var(--xh-_select-font-size));
    line-height: var(--xh-leading-none);
    text-align: start;
    cursor: pointer;
  }

  /* 清空按钮：盒里 trigger 的兄弟节点，排在触发器之后，与展开箭头一样宽；清不了时连接层给 hidden。
     正方视觉盒、inset 圆角、悬停 100 / 按下 200 与 0.97 按压、粗指针热区与 :focus-visible 关环
     （盒的 :focus-within 已画了一圈）全由 Action Control 的 field-inset ghost 档给，组件只映射既有覆盖槽 */
  [data-scope='select'][data-part='clear-trigger'] {
    --xh-action-visual-size: var(--xh-select-action-size, var(--xh-_action-profile-visual-size));
    --xh-action-min-inline-size: var(--xh-select-action-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-select-action-radius, var(--xh-shape-inset));
    /* 底色阶梯由 ghost 档给（透明 → 100 → 200），使用者槽只作覆盖入口 */
    --xh-action-bg-rest: var(--xh-select-action-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-select-action-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-select-action-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-select-action-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-select-action-fg-hover, var(--xh-fg-default));
    --xh-action-border-rest: transparent;
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    /* 字号钉死：继承页面字号会让行框高过按钮，字形被基线顶离正中 */
    --xh-action-font-size: var(--xh-select-action-font-size, var(--xh-text-secondary-size));
    /* 配方尚未把 profile 字形档灌进 --xh-icon-size，钮内字形先按 field-inset 档逐钮取值 */
    --xh-icon-size: var(--xh-_action-profile-glyph-size);

    border-width: 0;
  }

  /* 没值时连接层给的是 hidden 属性；家族那条 display 会把 UA 规则盖掉 */
  [data-scope='select'][data-part='clear-trigger'][hidden] {
    display: none;
  }

  /* 标签行：触发器里收着可见标签与 +N 那一枚的一行，行里每一枚都是 tag（data-scope="tag"），
     样子归 tag.css，这里只管行怎么排。它是弹性子项，只缩不涨：
     得允许自己被压缩并把溢出裁掉，否则标签会冲出盒的右缘、把展开箭头挤到盒外；
     展开箭头靠触发器的 space-between 留在末端，行本身不必撑开 */
  [data-scope='select'][data-part='tag-list'] {
    display: inline-flex;
    flex: 0 1 auto;
    align-items: center;
    gap: var(--xh-select-tag-list-gap, var(--xh-space-1));
    min-inline-size: 0;
    overflow: hidden;
  }

  /* 无选中时连接层给 hidden，占位文字回来 */
  [data-scope='select'][data-part='tag-list'][hidden] {
    display: none;
  }

  /* 标签行露面时 value-text 让位：两者是触发器里的同一格，占位文字与标签不同屏。
     value-text 留在 DOM 里，trigger 的可及名仍从它取到完整的选中项文本 */
  [data-scope='select'][data-part='trigger']:has([data-part='tag-list']:not([hidden])) [data-part='value-text'] {
    display: none;
  }

  /* 行里的标签：行装不下时各自缩短，截断落在 tag 自己的 label 上；弹性子项默认最小尺寸是内容尺寸，
     不归零则长标签把行撑破、省略号永远轮不到。+N 那一枚（带 data-count）不缩，始终完整可见。
     标签里的删除钮是 tag 的 close-trigger，样子全归 tag.css，这里不画 */
  [data-scope='select'][data-part='tag-list'] > [data-scope='tag'][data-part='root'] {
    flex: 0 1 auto;
    min-inline-size: 0;
  }

  [data-scope='select'][data-part='tag-list'] > [data-scope='tag'][data-part='root'][data-count] {
    flex: none;
  }

  /* 环画在盒上，按钮自己不再画：两圈套着的环读起来像两个控件 */
  [data-scope='select'][data-part='trigger']:focus-visible {
    outline: none;
  }

  /* trigger 是单体控件，用原生 disabled（条目那边一律 aria-disabled） */
  [data-scope='select'][data-part='trigger']:disabled {
    color: var(--xh-fg-disabled);
  }

  /* 盒宽由 control 定，这里得允许自己被压缩：弹性子项默认最小尺寸是内容尺寸，
     不归零则长值把行撑破、省略号永远轮不到 */
  [data-scope='select'][data-part='value-text'] {
    flex: 1;
    min-inline-size: 0;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  /* 无选中：显示的是 placeholder，画淡一档 */
  [data-scope='select'][data-part='value-text'][data-placeholder] {
    color: var(--xh-select-placeholder-fg, var(--xh-fg-subtle));
  }

  /* 有值时清空钮顶上来，箭头让位：两个图标并排堆着，用户分不清点哪个。
     判据查的是盒里此刻真有一颗没收起的清空钮，不是「有没有值」——
     作者没摆清空钮时箭头照常留着，不然让了位没人接，指示符整个消失 */
  [data-scope='select'][data-part='control']:has([data-part='clear-trigger']:not([hidden])) [data-part='indicator'] {
    display: none;
  }

  /* 展开箭头与清空钮同一把尺：两者互斥显示，换来换去不该让盒里的宽度跳一下 */
  [data-scope='select'][data-part='indicator'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-select-action-size, var(--xh-control-action-size));
    block-size: var(--xh-select-action-size, var(--xh-control-action-size));
    color: var(--xh-select-indicator-fg, var(--xh-fg-muted));
    transition: rotate var(--xh-motion-duration-nudge) var(--xh-motion-ease-enter-strong);
  }

  /* 没写内容就由皮肤画箭头；作者往部件里塞了自己的图形，这条规则即不命中 */
  [data-scope='select'][data-part='indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
  }

  [data-scope='select'][data-part='indicator'][data-state='open'] {
    rotate: 180deg;
  }

  /* 浮层外壳：描边、底色、阴影与整体尺寸归它。它自己不滚——滚的是里面的 list，
     底部操作区因此留在视口里，不随条目滚走 */
  [data-scope='select'][data-part='content'] {
    position: relative;
    display: flex;
    flex-direction: column;
    /* 下界跟着触发器走，面板不窄于它；可用宽度的夹取写在这一侧：
       min-inline-size 恒压过 max-inline-size，锚点比可用区还宽时只夹 max 等于没夹 */
    min-inline-size: min(
      max(var(--xh-select-content-min-w, var(--xh-overlay-menu-min-w)), var(--xh-_select-anchor-w)),
      var(--xh-_select-available-w)
    );
    /* 静态档与落位后的可用宽度取小：窄视口下面板伸出去，最右侧的内容就点不到了 */
    max-inline-size: min(var(--xh-select-content-max-w, var(--xh-overlay-max-w)), var(--xh-_select-available-w));
    max-block-size: min(var(--xh-select-content-max-h, var(--xh-overlay-menu-max-h)), var(--xh-_select-available-h));
    padding-block: var(--xh-select-content-py, var(--xh-space-1));
    padding-inline: var(--xh-select-content-px, var(--xh-space-1));
    border: var(--xh-stroke-thin) solid var(--xh-select-content-border, var(--xh-material-frosted-border));
    border-radius: var(--xh-select-content-radius, var(--xh-shape-overlay));
    background: var(--xh-select-content-bg, var(--xh-material-frosted-bg));
    color: var(--xh-select-content-fg, var(--xh-material-frosted-fg));
    box-shadow: var(--xh-select-content-shadow, var(--xh-material-frosted-shadow));
    -webkit-backdrop-filter: var(--xh-select-content-backdrop, var(--xh-material-frosted-backdrop));
    backdrop-filter: var(--xh-select-content-backdrop, var(--xh-material-frosted-backdrop));
    /* 条目的悬停底色是方角，滚到两端时会探出外壳的圆角 */
    overflow: hidden;
    pointer-events: auto;
  }

  /* 顶光单独叠在真实四边 border 内侧；强制色归零后轮廓仍在。 */
  [data-scope='select'][data-part='content']::before {
    content: '';
    position: absolute;
    inset-block-start: 0;
    inset-inline: 0;
    block-size: var(--xh-stroke-thin);
    border-radius: inherit;
    background: var(--xh-select-content-highlight, var(--xh-material-frosted-highlight));
    pointer-events: none;
  }

  /* 列表框本体：只管滚动，留白归外壳。
     min-block-size: 0 是 flex 子项能真正滚动的前提——不给的话它按内容撑高，
     外壳的 max-block-size 就只会把溢出的部分裁掉而不是交给它滚 */
  [data-scope='select'][data-part='list'] {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    gap: var(--xh-select-list-gap, var(--xh-list-option-gap));
    min-block-size: 0;
    overflow-y: auto;
    /* 浮层滚动面：滚到头不把页面一起带走 */
    overscroll-behavior: contain;
  }

  /* 底部操作区：贴在列表下沿，用一道分隔线与条目断开。
     作者往里放什么由作者定，这里只管位置、留白与那条线 */
  [data-scope='select'][data-part='footer'] {
    display: flex;
    flex: none;
    align-items: center;
    gap: var(--xh-select-footer-gap, var(--xh-space-2));
    padding-block: var(--xh-select-footer-py, var(--xh-space-2));
    padding-inline: var(--xh-select-footer-px, var(--xh-space-2));
    border-block-start: var(--xh-stroke-thin) solid var(--xh-select-footer-border, var(--xh-material-frosted-separator));
    color: var(--xh-select-footer-fg, var(--xh-material-frosted-fg-muted));
    font-size: var(--xh-select-footer-font-size, var(--xh-text-secondary-size));
  }

  /* 上面给了 display，UA 的 [hidden]{display:none} 已被盖掉，这里补回来 */
  [data-scope='select'][data-part='footer'][hidden] {
    display: none;
  }

  /* 这里刻意没有 [data-part='content'][hidden] { display: none }，与 dialog 一致：
     收起态连接层会给 content 打 hidden，而上面那条 display 正是要盖掉 UA 的
     [hidden]{display:none}——退场动画得先能播。presence 读的是 content 的 animationName，
     真正的收起由宿主在退场结束后落成内联 display:none（Vue 那边直接不渲染）。
     其余声明了 display 的角色节点仍补 [hidden]，那几处没有退场动画。 */

  [data-scope='select'][data-part='list']:not([tabindex='0']):focus-visible {
    outline: none;
  }

  [data-scope='select'][data-part='content'][data-state='open'] {
    animation: xh-overlay-slide-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 退场：收起那一帧 hidden 由退场闸门押后，这里才播得出来。forwards 把末态钉住，
     免得动画结束到真收起之间闪一下原样 */
  [data-scope='select'][data-part='content'][data-state='closed'] {
    animation: xh-overlay-slide-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
    will-change: opacity, translate;
  }

  /* 空态占位：待在 content 里、list 的兄弟；盒与阴影归 content，这里只画一句居中的次要文字 */
  [data-scope='select'][data-part='empty'] {
    display: block;
    flex: none;
    padding-block: var(--xh-select-empty-py, var(--xh-space-3));
    padding-inline: var(--xh-select-empty-px, var(--xh-_select-item-px));
    color: var(--xh-select-empty-fg, var(--xh-material-frosted-fg-muted));
    font-size: var(--xh-select-empty-font-size, var(--xh-_select-font-size));
    line-height: var(--xh-leading-none);
    text-align: center;
  }

  /* 上面给了 display，UA 的 [hidden]{display:none} 已被盖掉，这里补回来 */
  [data-scope='select'][data-part='empty'][hidden] {
    display: none;
  }

  /* 在途占位：与空态占位同一个位置、同一副观感，两者不同屏 */
  [data-scope='select'][data-part='loading'] {
    display: block;
    flex: none;
    padding-block: var(--xh-select-loading-py, var(--xh-space-3));
    padding-inline: var(--xh-select-loading-px, var(--xh-_select-item-px));
    color: var(--xh-select-loading-fg, var(--xh-material-frosted-fg-muted));
    font-size: var(--xh-select-loading-font-size, var(--xh-_select-font-size));
    line-height: var(--xh-leading-none);
    text-align: center;
  }

  [data-scope='select'][data-part='loading'][hidden] {
    display: none;
  }

  [data-scope='select'][data-part='group'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-select-group-gap, var(--xh-list-option-gap));
  }

  [data-scope='select'][data-part='group'][hidden] {
    display: none;
  }

  /* 后继分组用一条实体细线分段；既有 spacing 槽改管线后的内距，总节奏不另造一套。 */
  [data-scope='select'][data-part='group'] + [data-scope='select'][data-part='group'] {
    padding-block-start: var(--xh-select-group-spacing, var(--xh-space-1_5));
    border-block-start: var(--xh-stroke-thin) solid
      var(--xh-select-group-separator-color, var(--xh-material-frosted-separator));
  }

  /* 分组标题不是选项、进不了导航，画成小号次要文字，
     内缩与条目对齐（同一个 padding-inline），标题与条目文字才在一条竖线上 */
  [data-scope='select'][data-part='group-label'] {
    display: block;
    padding-block: var(--xh-select-group-label-py, var(--xh-space-1));
    padding-inline: var(--xh-select-group-label-px, var(--xh-_select-item-px));
    color: var(--xh-select-group-label-fg, var(--xh-material-frosted-fg-muted));
    font-size: var(--xh-select-group-label-font-size, var(--xh-text-caption-size));
    font-weight: var(--xh-select-group-label-font-weight, var(--xh-font-weight-medium));
    line-height: var(--xh-leading-none);
    user-select: none;
  }

  [data-scope='select'][data-part='group-label'][hidden] {
    display: none;
  }

  [data-scope='select'][data-part='item'] {
    /* 公开 Select 槽只映射到家族合同；网格、尺寸与状态选择器不在组件皮肤复制。pressed 面与 selected 各态由家族按 overlay 上下文给出。 */
    --xh-collection-block-padding: var(--xh-select-item-py, var(--xh-_select-item-py));
    --xh-collection-inline-padding: var(--xh-select-item-px, var(--xh-_select-item-px));
    --xh-collection-gap: var(--xh-select-item-gap, var(--xh-_select-gap));
    --xh-collection-font-size: var(--xh-select-item-font-size, var(--xh-_select-font-size));
    --xh-collection-radius: var(--xh-select-item-radius, var(--xh-shape-control));
    --xh-collection-fg-rest: var(--xh-select-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-hover: var(--xh-select-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-keyboard-highlight: var(--xh-select-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-selected: var(--xh-select-item-fg-selected, var(--xh-select-item-fg, var(--xh-material-frosted-fg)));
    --xh-collection-fg-selected-highlight: var(--xh-select-item-fg-selected, var(--xh-select-item-fg, var(--xh-material-frosted-fg)));
    --xh-collection-fg-selected-hover: var(--xh-select-item-fg-selected, var(--xh-select-item-fg, var(--xh-material-frosted-fg)));
    --xh-collection-fg-selected-pressed: var(--xh-select-item-fg-selected, var(--xh-select-item-fg, var(--xh-material-frosted-fg)));
    --xh-collection-fg-pressed: var(--xh-select-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-font-weight-selected: var(--xh-select-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-font-weight-selected-highlight: var(--xh-select-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-font-weight-selected-hover: var(--xh-select-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-font-weight-selected-pressed: var(--xh-select-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-bg-hover: var(--xh-select-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-keyboard-highlight: var(--xh-select-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-selected-highlight: var(--xh-select-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-selected-hover: var(--xh-select-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-pressed: var(--xh-select-item-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-bg-selected-pressed: var(--xh-select-item-bg-pressed, var(--xh-bg-subtle-hover));
    /* data-highlighted 同时覆盖指针与键盘路径；指针只换面，焦点环在 :focus-visible 下再接回。 */
    --xh-collection-outline-keyboard-highlight: transparent;
    --xh-collection-outline-selected-highlight: transparent;
    --xh-collection-indicator-fg-rest: var(--xh-select-item-check-fg, var(--xh-_select-accent));
    --xh-collection-indicator-fg-checked: var(--xh-select-item-check-fg, var(--xh-_select-accent));
    --xh-collection-indicator-fg-selected: var(--xh-select-item-check-fg, var(--xh-_select-accent));
    --xh-collection-indicator-fg-selected-hover: var(--xh-select-item-check-fg, var(--xh-_select-accent));
    --xh-collection-indicator-fg-selected-highlight: var(--xh-select-item-check-fg, var(--xh-_select-accent));
    --xh-collection-indicator-fg-selected-pressed: var(--xh-select-item-check-fg, var(--xh-_select-accent));

    /* 行高留出文字的上下伸展空间，行内那层 overflow:hidden 才不会把字削掉 */
    line-height: var(--xh-select-item-leading, var(--xh-leading-normal));
    white-space: nowrap;
    user-select: none;
  }

  /* 键盘焦点出现时底色立即到位，环不会压在背景过渡的中间帧上。 */
  [data-scope='select'][data-part='item']:focus-visible:not(:hover) {
    --xh-collection-outline-keyboard-highlight: var(--xh-ring-focus);
    --xh-collection-outline-selected-highlight: var(--xh-ring-focus);

    transition: none;
  }

  [data-scope='select'][data-part='item-text'] {
    /* 弹性子项默认最小尺寸是内容尺寸，不归零则长文本把行撑破、省略号轮不上 */
    min-inline-size: 0;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  /* 勾选标记只在选中项上出现；未选中时占位不塌，切换选中不引起行宽抖动。
     盒与盒里的勾是指示符：盒按指示符档取尺，并在自己身上把 --xh-icon-size 改接到盒的尺，皮肤画的
     兜底勾与作者塞进盒里的 XhIcon 读同一把尺、与盒同边长（勾选标记不是勾选格，不取 × 0.75，与 Listbox / Menu 族
     同口径）；不读家族按档下发到行的 --xh-icon-size——那支只管作者放进条目里的图标，按图标档取的 20px 比
     16 / 14 的指示符档大一圈 */
  [data-scope='select'][data-part='item-indicator'] {
    --xh-icon-size: var(--xh-select-item-indicator-size, var(--xh-control-indicator-size));

    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-select-item-indicator-size, var(--xh-control-indicator-size));
    block-size: var(--xh-select-item-indicator-size, var(--xh-control-indicator-size));
  }

  /* 同上：没写内容就由皮肤画勾。尺寸读标记盒自己改接过的 --xh-icon-size：与盒同边长，随指示符档换档 */
  [data-scope='select'][data-part='item-indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    mask: var(--xh-glyph-mark-check) center / contain no-repeat;
  }

  /* 表单影子：视觉隐藏但留在布局与表单里，原生校验提示需要一个可定位的框 */
  [data-scope='select'][data-part='hidden-select'] {
    pointer-events: none;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中 */
  [data-scope='select'][data-part='clear-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='select'][data-part='root'][hidden],
  [data-scope='select'][data-part='control'][hidden],
  [data-scope='select'][data-part='trigger'][hidden],
  [data-scope='select'][data-part='indicator'][hidden],
  [data-scope='select'][data-part='list'][hidden],
  [data-scope='select'][data-part='item'][hidden],
  [data-scope='select'][data-part='item-indicator'][hidden] {
    display: none;
  }

  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。 */
    [data-scope='select'][data-part='positioner'] {
      display: none;
    }
  }
}

/* styles/separator.css */
/* 定义 separator 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='separator'] {
    --xh-separator-skin: 1;
  }

  /*
   * 线的颜色与线型都先收进两个私有槽，再由 root（只有它一个时）与 line（有分节文字时）
   * 各自取用：换档只改槽，画在哪个节点上互不影响。
   */
  [data-scope='separator'][data-part='root'] {
    --xh-_separator-color: var(--xh-separator-color, var(--xh-material-frosted-separator));
    --xh-_separator-dash: var(--xh-separator-dash-length, var(--xh-space-1_5));
    --xh-_separator-dash-gap: var(--xh-separator-dash-gap, var(--xh-space-1_5));
    --xh-_separator-paint: var(--xh-_separator-color);

    border: 0;
    border-radius: var(--xh-separator-radius, var(--xh-shape-pill));
    background: var(--xh-_separator-paint);
  }

  [data-scope='separator'][data-part='root'][data-orientation='horizontal'] {
    inline-size: 100%;
    block-size: var(--xh-separator-thickness, var(--xh-stroke-thin));
  }

  [data-scope='separator'][data-part='root'][data-orientation='vertical'] {
    align-self: stretch;
    inline-size: var(--xh-separator-thickness, var(--xh-stroke-thin));
    block-size: 100%;
  }

  /* —— 形态 ——
     三档只换线的深浅，缺省档写在上面的基础规则里。使用者槽排在档值前面，
     写了 --xh-separator-color 的那一条仍然压过档值 */
  [data-scope='separator'][data-part='root'][data-variant='subtle'] {
    --xh-_separator-color: var(--xh-separator-color, var(--xh-material-soft-separator));
  }

  [data-scope='separator'][data-part='root'][data-variant='strong'] {
    --xh-_separator-color: var(--xh-separator-color, var(--xh-border-strong));
  }

  /* —— 虚线 ——
     实线段与空白段交替铺；方向由 data-orientation 选，表达式只写这两条 */
  [data-scope='separator'][data-part='root'][data-dashed][data-orientation='horizontal'] {
    --xh-_separator-paint: repeating-linear-gradient(
      to right,
      var(--xh-_separator-color) 0 var(--xh-_separator-dash),
      transparent var(--xh-_separator-dash) calc(var(--xh-_separator-dash) + var(--xh-_separator-dash-gap))
    );
  }

  [data-scope='separator'][data-part='root'][data-dashed][data-orientation='vertical'] {
    --xh-_separator-paint: repeating-linear-gradient(
      to bottom,
      var(--xh-_separator-color) 0 var(--xh-_separator-dash),
      transparent var(--xh-_separator-dash) calc(var(--xh-_separator-dash) + var(--xh-_separator-dash-gap))
    );
  }

  /* —— 带分节文字的三段形态 ——
     渲染了 content 之后 root 改当容器：自己不再画线，线交给两条 line。
     形态由部件在不在决定，没有开关 */
  [data-scope='separator'][data-part='root']:has([data-part='content']) {
    display: flex;
    align-items: center;
    inline-size: 100%;
    block-size: auto;
    gap: var(--xh-separator-gap, var(--xh-space-3));
    background: none;
  }

  [data-scope='separator'][data-part='root'][data-orientation='vertical']:has([data-part='content']) {
    flex-direction: column;
    inline-size: auto;
    block-size: 100%;
  }

  /* 两条线等分剩下的地方；粗细与颜色跟 root 单节点时同源 */
  [data-scope='separator'][data-part='line'] {
    flex: 1 1 0;
    border-radius: var(--xh-separator-radius, var(--xh-shape-pill));
    background: var(--xh-_separator-paint);
  }

  [data-scope='separator'][data-part='line'][data-orientation='horizontal'] {
    block-size: var(--xh-separator-thickness, var(--xh-stroke-thin));
  }

  [data-scope='separator'][data-part='line'][data-orientation='vertical'] {
    inline-size: var(--xh-separator-thickness, var(--xh-stroke-thin));
  }

  /* 分节文字：不参与等分，也不折行 */
  [data-scope='separator'][data-part='content'] {
    flex: none;
    color: var(--xh-separator-content-fg, var(--xh-fg-muted));
    font-size: var(--xh-separator-content-font-size, var(--xh-text-secondary-size));
    line-height: var(--xh-leading-normal);
    white-space: nowrap;
  }

  /* 文字靠边：靠哪边就把那一侧的线收成一小截，另一侧照旧等分 */
  [data-scope='separator'][data-part='root'][data-align='start'] > [data-part='line']:first-child,
  [data-scope='separator'][data-part='root'][data-align='end'] > [data-part='line']:last-child {
    flex: 0 0 var(--xh-separator-align-length, var(--xh-space-6));
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='separator'][data-part='root'][hidden] {
    display: none;
  }
}

/* styles/side-nav.css */
/* 定义 side nav 样式。 */

/* 共享关键帧由 family/motion.css 提供，行走 Collection Item 家族；本皮肤 @import 它们，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='side-nav'] {
    --xh-side-nav-skin: 1;
  }

  /* 私有槽同时声明在根与定位层上：折叠态的弹出面板被搬到 portal 落点，
     不是根的后代，继承不过去。面板里的行与栏内那些消费的是同一批槽 */
  [data-scope='side-nav']:is([data-part='root'], [data-part='positioner']) {
    /* 行外的字形按档取尺，缺省 md，随 data-size 换档并同样声明在定位层上（弹出面板里的行也拿得到）；
       行内的由家族随 data-xh-collection-size 下发。这支只管作者放进行里的图标：
       侧栏自绘的状态字形（分支行尾的展开方向 chevron）是指示符，branch-indicator 在自己身上
       把 --xh-icon-size 改接到 --xh-control-indicator-* 一族的盒尺 */
    --xh-icon-size: var(--xh-side-nav-icon-size, var(--xh-glyph-size-md));

    /* 尺寸档只换这三个私有槽，行从这两处继承它们，换档不必给每个部件各写一条选择器 */
    --xh-_side-nav-row-h: var(--xh-control-h-md);
    --xh-_side-nav-row-px: var(--xh-control-px-md);
    --xh-_side-nav-row-gap: var(--xh-control-gap-md);
    --xh-_side-nav-row-font-size: var(--xh-control-font-md);
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面那条里 */
  [data-scope='side-nav']:is([data-part='root'], [data-part='positioner'])[data-size='sm'] {
    --xh-icon-size: var(--xh-side-nav-icon-size, var(--xh-glyph-size-sm));
    --xh-_side-nav-row-h: var(--xh-control-h-sm);
    --xh-_side-nav-row-px: var(--xh-control-px-sm);
    --xh-_side-nav-row-gap: var(--xh-control-gap-sm);
    --xh-_side-nav-row-font-size: var(--xh-control-font-sm);
  }

  [data-scope='side-nav']:is([data-part='root'], [data-part='positioner'])[data-size='lg'] {
    --xh-icon-size: var(--xh-side-nav-icon-size, var(--xh-glyph-size-lg));
    --xh-_side-nav-row-h: var(--xh-control-h-lg);
    --xh-_side-nav-row-px: var(--xh-control-px-lg);
    --xh-_side-nav-row-gap: var(--xh-control-gap-lg);
    --xh-_side-nav-row-font-size: var(--xh-control-font-lg);
  }

  [data-scope='side-nav'][data-part='root'] {
    inline-size: var(--xh-side-nav-w, 240px);
    display: flex;
    flex-direction: column;
    gap: var(--xh-side-nav-gap, var(--xh-space-1));
    padding: var(--xh-side-nav-p, var(--xh-space-2));
    color: var(--xh-side-nav-fg, var(--xh-fg-default));
  }

  /* 折叠成图标栏：整栏收窄，文字随行宽被裁掉 */
  [data-scope='side-nav'][data-part='root'][data-collapsed] {
    inline-size: var(--xh-side-nav-collapsed-w, 56px);
  }

  [data-scope='side-nav'][data-part='list'],
  [data-scope='side-nav'][data-part='branch-content'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-side-nav-gap, var(--xh-space-1));
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* 子层靠嵌套缩进，层级越深自然越靠里 */
  [data-scope='side-nav'][data-part='branch-content'] {
    padding-inline-start: var(--xh-side-nav-indent, var(--xh-space-4));
  }

  [data-scope='side-nav'][data-part='branch-content'][hidden] {
    display: none;
  }

  [data-scope='side-nav'][data-part='group'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-side-nav-gap, var(--xh-space-1));
    list-style: none;
  }

  [data-scope='side-nav'][data-part='group-label'] {
    padding-block: var(--xh-side-nav-group-label-py, var(--xh-space-1));
    padding-inline: var(--xh-side-nav-group-label-px, var(--xh-_side-nav-row-px));
    font-size: var(--xh-text-caption-size);
    font-weight: var(--xh-text-label-weight);
    color: var(--xh-fg-subtle);
    user-select: none;
  }

  /* 折叠时分组标题没有落点，藏掉 */
  [data-scope='side-nav'][data-part='group-label'][data-collapsed] {
    display: none;
  }

  [data-scope='side-nav'][data-part='branch'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-side-nav-gap, var(--xh-space-1));
    list-style: none;
  }

  /* 叶子行的列表项：链接自己撑满，这一层只负责列表语义 */
  [data-scope='side-nav'][data-part='item'] {
    display: flex;
    flex-direction: column;
    list-style: none;
  }

  /* —— 行：分支按钮与链接同一副长相 ——
     两种行都走 Collection Item 的 page 语境（页内持久集合）：悬停 / 高亮 / 按下面（白底承载 hover 100 →
     pressed 200，只换面不缩放）、当前页（品牌淡底 + 淡底前景 + 起始侧 2px 指示条，current+hover 20% /
     +pressed 28%）、展开路径（与 hover 同档的中性面，不用品牌色、不加粗）与禁用面都由家族按 data-current /
     data-in-path / aria-disabled 给出。这里只把公开槽映射到桥接槽。
     布局保持 flex 而不用家族网格：一行里可以并排作者自己的图标与徽标，间距统一由行的 gap 给，
     家族按槽下发的外边距（--xh-collection-gap）归零；行高由 min-block-size 撑起，家族的块向内衬归零 */
  [data-scope='side-nav'][data-part='branch-trigger'],
  [data-scope='side-nav'][data-part='link'] {
    --xh-collection-block-padding: 0;
    --xh-collection-inline-padding: var(--xh-side-nav-link-px, var(--xh-_side-nav-row-px));
    --xh-collection-gap: 0;
    --xh-collection-font-size: var(--xh-side-nav-link-font-size, var(--xh-_side-nav-row-font-size));
    --xh-collection-radius: var(--xh-side-nav-link-radius, var(--xh-shape-control));
    /* 作者的图标尺槽经桥接槽下发到行，家族缺省按 data-xh-collection-size 取档 */
    --xh-collection-glyph-size: var(--xh-side-nav-icon-size, var(--xh-_collection-glyph-size));
    --xh-collection-fg-rest: var(--xh-side-nav-row-fg, currentColor);
    --xh-collection-fg-hover: var(--xh-side-nav-row-fg, currentColor);
    --xh-collection-fg-keyboard-highlight: var(--xh-side-nav-row-fg, currentColor);
    --xh-collection-fg-pressed: var(--xh-side-nav-row-fg, currentColor);
    --xh-collection-bg-hover: var(--xh-side-nav-row-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-keyboard-highlight: var(--xh-side-nav-row-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-pressed: var(--xh-side-nav-row-bg-pressed, var(--xh-bg-subtle-hover));
    /* 当前页：公开槽名不变，缺省前景由品牌深字改为淡底前景，字重保持 medium；2px 指示条取品牌色 */
    --xh-collection-bg-current: var(--xh-side-nav-row-bg-active, var(--xh-bg-brand-subtle));
    --xh-collection-fg-current: var(--xh-side-nav-row-fg-active, var(--xh-fg-on-brand-subtle));
    --xh-collection-fg-current-hover: var(--xh-side-nav-row-fg-active, var(--xh-fg-on-brand-subtle));
    --xh-collection-fg-current-highlight: var(--xh-side-nav-row-fg-active, var(--xh-fg-on-brand-subtle));
    --xh-collection-fg-current-pressed: var(--xh-side-nav-row-fg-active, var(--xh-fg-on-brand-subtle));
    --xh-collection-font-weight-current: var(--xh-side-nav-row-font-weight-active, var(--xh-font-weight-medium));
    --xh-collection-font-weight-current-hover: var(--xh-side-nav-row-font-weight-active, var(--xh-font-weight-medium));
    --xh-collection-font-weight-current-highlight: var(--xh-side-nav-row-font-weight-active, var(--xh-font-weight-medium));
    --xh-collection-font-weight-current-pressed: var(--xh-side-nav-row-font-weight-active, var(--xh-font-weight-medium));
    --xh-collection-indicator-fg-current: var(--xh-side-nav-indicator-color, var(--xh-fg-brand));
    --xh-collection-indicator-fg-current-hover: var(--xh-side-nav-indicator-color, var(--xh-fg-brand));
    --xh-collection-indicator-fg-current-highlight: var(--xh-side-nav-indicator-color, var(--xh-fg-brand));
    --xh-collection-indicator-fg-current-pressed: var(--xh-side-nav-indicator-color, var(--xh-fg-brand));
    /* 展开路径：中性面，字色缺省由品牌色改回行的常态色 */
    --xh-collection-bg-open-path: var(--xh-side-nav-row-bg-in-path, var(--xh-bg-subtle));
    --xh-collection-fg-open-path: var(--xh-side-nav-row-fg-in-path, var(--xh-side-nav-row-fg, currentColor));
    /* data-highlighted 跟的是连接层记的焦点行（指针点选也会落焦）：只换面，焦点环在 :focus-visible 下再接回 */
    --xh-collection-outline-keyboard-highlight: transparent;
    --xh-collection-outline-current-highlight: transparent;

    display: flex;
    align-items: center;
    gap: var(--xh-side-nav-link-gap, var(--xh-_side-nav-row-gap));
    inline-size: 100%;
    min-block-size: var(--xh-side-nav-link-h, var(--xh-_side-nav-row-h));
    border: none;
    text-align: start;
    text-decoration: none;
  }

  /* 键盘焦点出现时环才接回并立即到位，不压在背景过渡的中间帧上 */
  [data-scope='side-nav'][data-part='branch-trigger']:focus-visible:not(:hover),
  [data-scope='side-nav'][data-part='link']:focus-visible:not(:hover) {
    --xh-collection-outline-keyboard-highlight: var(--xh-ring-focus);
    --xh-collection-outline-current-highlight: var(--xh-ring-focus);

    transition: none;
  }

  [data-scope='side-nav'][data-part='branch-text'],
  [data-scope='side-nav'][data-part='link-text'] {
    flex: 1;
    min-inline-size: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* 折叠成图标栏：行文字裁到看不见但仍参与播报，行内容居中，不裁半个字。
     用 clip-path 而不是 display:none——图标栏里按钮与链接的可及名就是这段文字，
     藏成 display:none 它们就一个名字都没有了。
     white-space: nowrap 防止 1px 宽把文本挤成竖排。
     弹出面板里的行不在此列——面板是正常宽度的浮层，文字照常显示 */
  [data-scope='side-nav'][data-part='root'][data-collapsed] [data-part='branch-text']:not([data-popout] *),
  [data-scope='side-nav'][data-part='root'][data-collapsed] [data-part='link-text']:not([data-popout] *) {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }

  /* 展开指示是纯装饰（aria-hidden），折叠态整个不占位 */
  [data-scope='side-nav'][data-part='root'][data-collapsed] [data-part='branch-indicator']:not([data-popout] *) {
    display: none;
  }

  [data-scope='side-nav'][data-part='root'][data-collapsed] [data-part='branch-trigger']:not([data-popout] *),
  [data-scope='side-nav'][data-part='root'][data-collapsed] [data-part='link']:not([data-popout] *) {
    --xh-collection-inline-padding: 0;

    justify-content: center;
  }

  /* 弹出面板的定位层：坐标由连接层写在行内样式上，这里只管层号与命中区。
     它被搬到浮层落点、不在侧栏子树内，所以卡片外观仍归面板本身；
     这里不设 display，UA 的 [hidden]{display:none} 就仍然压得住收起态 */
  [data-scope='side-nav'][data-part='positioner'] {
    /* 落定那一侧的可用高度，由定位引擎经内联自定义属性写进来，面板继承它限高；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时不额外限高 */
    --xh-_side-nav-available-h: 100vh;
    /* 落定那一侧的可用宽度，同样由定位引擎经内联自定义属性写进来，行内轴据此夹取；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时退到视口宽 */
    --xh-_side-nav-available-w: 100vw;

    position: fixed;
    z-index: var(--xh-side-nav-popout-layer, var(--xh-_layer, var(--xh-layer-popover)));
    pointer-events: auto;
  }

  /* 还没落位就先藏着：visibility 而非 display，display:none 会让引擎量不到面板尺寸 */
  [data-scope='side-nav'][data-part='positioner'][data-hidden] {
    visibility: hidden;
  }

  /* 折叠态的弹出面板：贴着触发按钮旁侧的浮层卡片。
     面板自己不吃子层缩进（padding 整圈盖掉），面板内的嵌套子层照常缩进 */
  [data-scope='side-nav'][data-part='branch-content'][data-popout] {
    min-inline-size: var(--xh-side-nav-popout-min-w, var(--xh-overlay-menu-min-w));
    /* 静态档与落位后的可用宽度取小：窄视口下面板伸出去，最右侧的内容就点不到了 */
    max-inline-size: min(var(--xh-side-nav-popout-max-w, var(--xh-overlay-max-w)), var(--xh-_side-nav-available-w));
    padding: var(--xh-side-nav-popout-p, var(--xh-space-1));
    border: var(--xh-stroke-thin) solid var(--xh-side-nav-popout-border, var(--xh-border-default));
    border-radius: var(--xh-side-nav-popout-radius, var(--xh-shape-overlay));
    background: var(--xh-side-nav-popout-bg, var(--xh-bg-surface));
    box-shadow: var(--xh-side-nav-popout-shadow, var(--xh-elevation-floating));

    /* 子导航条目数没有上限，矮视口下不限高就整块伸出视口且滚不到。
       浮层滚动面：到底后不把滚动链穿透给页面；细条由 reset 层给 */
    max-block-size: min(var(--xh-side-nav-popout-max-h, var(--xh-overlay-menu-max-h)), var(--xh-_side-nav-available-h));
    overflow-y: auto;
    overscroll-behavior: contain;
  }

  [data-scope='side-nav'][data-part='branch-content'][data-popout][data-state='open'] {
    animation: xh-pop-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 退场：收起那一帧 hidden 由退场闸门押后，这里才播得出来。forwards 把末态钉住，
     免得动画结束到收起落下来之间闪一下原样 */
  [data-scope='side-nav'][data-part='branch-content'][data-popout][data-state='closed'] {
    animation: xh-pop-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* 箭头是行尾的后缀：auto 外边距把它顶到行尾，家族按 suffix 槽下发的外边距已在行上归零。
     盒里的 chevron 是指示符：盒按指示符档定尺（comfortable 16 / compact 14，与 Tree / TreeSelect
     的 branch-indicator 同款定尺盒），--xh-icon-size 在自己身上改接到盒的尺，兜底字形与作者塞进盒里的
     XhIcon 读同一把尺、与盒同边长；不读家族按档下发到行的 --xh-icon-size——那支只管作者放进行里的
     图标，按图标档取的 20px 比指示符档大一圈。盒自己定尺而不随字形撑开：转 90° 时才不抖 */
  [data-scope='side-nav'][data-part='branch-indicator'] {
    --xh-icon-size: var(--xh-side-nav-branch-indicator-size, var(--xh-control-indicator-size));

    margin-inline-start: auto;
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-side-nav-branch-indicator-size, var(--xh-control-indicator-size));
    block-size: var(--xh-side-nav-branch-indicator-size, var(--xh-control-indicator-size));
    transition: rotate var(--xh-motion-duration-nudge) var(--xh-motion-ease-enter-strong);
  }

  [data-scope='side-nav'][data-part='branch-indicator'][data-state='open'] {
    rotate: 90deg;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中。
     尺寸读部件自己改接过的 --xh-icon-size：chevron 与盒同边长（见上面那块） */
  [data-scope='side-nav'][data-part='branch-indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='side-nav'][data-part='root'][hidden],
  [data-scope='side-nav'][data-part='list'][hidden],
  [data-scope='side-nav'][data-part='group'][hidden],
  [data-scope='side-nav'][data-part='branch'][hidden],
  [data-scope='side-nav'][data-part='branch-trigger'][hidden],
  [data-scope='side-nav'][data-part='item'][hidden],
  [data-scope='side-nav'][data-part='link'][hidden],
  [data-scope='side-nav'][data-part='branch-indicator'][hidden] {
    display: none;
  }

  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。 */
    [data-scope='side-nav'][data-part='positioner'] {
      display: none;
    }
  }
}

/* styles/slider.css */
/* 定义 slider 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='slider'] {
    --xh-slider-skin: 1;
  }

  /* 定位分工：已选区间与拇指在**主轴**上的起点与长度，由连接层每帧写进内联样式——
     水平是 inset-inline-start / inline-size，竖直是 inset-block-end / block-size。
     这份皮肤一个都不碰：内联优先级高于样式表，写了不但是死声明，
     切换 orientation 的那一帧还会跟连接层清空另一轴的动作抢位置，把拇指钉在两轴都被约束的地方。
     皮肤只管另一条轴（交叉轴）的尺寸、颜色、圆角与状态表现。 */

  /* 私有槽位：组件令牌 → 中档字面量两级回退。轨道厚度与拇指直径同时被 control / track / thumb
     三个角色节点用到，收成两个槽位挂在 root 上，尺寸档只改这两处，靠继承发到子部件。 */
  [data-scope='slider'][data-part='root'] {
    --xh-_thumb-size: var(--xh-slider-thumb-size, var(--xh-track-thumb-size));
    --xh-_track-thickness: var(--xh-slider-track-thickness, var(--xh-track-thickness));

    display: flex;
    flex-direction: column;
    /* 字段标签贴控件（复合单字段） */
    gap: var(--xh-slider-gap, var(--xh-space-1));
  }

  /* 竖排时整条控件收成一块，不再撑满一行：宽度由拇指直径决定 */
  [data-scope='slider'][data-part='root'][data-orientation='vertical'] {
    display: inline-flex;
    align-items: center;
  }

  /* 禁用不整体压暗：前景与表面各自降级——连接层把 data-disabled 发到每个角色节点上，
     轨道、区间、拇指、刻度与标签就近消费，写在各自的规则里 */

  /* 字段标签：14 / 500 / fg-default，禁用换到 --xh-fg-subtle */
  [data-scope='slider'][data-part='label'] {
    color: var(--xh-slider-label-fg, var(--xh-fg-default));
    font-size: var(--xh-slider-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-slider-label-font-weight, var(--xh-text-label-weight));
  }

  [data-scope='slider'][data-part='label'][data-disabled] {
    color: var(--xh-slider-label-fg-disabled, var(--xh-fg-subtle));
  }

  /* 拇指以它为定位上下文（拇指常常浮出轨道，挂在 track 上会被轨道的盒子束住）。
     厚度取拇指直径：轨道只有几个像素，控件若按轨道高，浮出来的拇指会顶到上下相邻的元素。
     touch-action 由连接层内联给（拖动要接管手势），这里不写。 */
  [data-scope='slider'][data-part='control'] {
    position: relative;
    display: flex;
    align-items: center;
    block-size: var(--xh-_thumb-size);
    cursor: pointer;
  }

  /* 刻度文案以刻度为圆心横向摊开，首末两档各有一半落在轨道之外，页面因此恒多出半个文案的宽度。
     排了刻度文案的横轨两侧各让出一段，那半个文案落进让出来的这一段里。
     让在控件上而不是根上：轨道、刻度、拇指的坐标都以控件为基准，一起让开才不会彼此错位。 */
  [data-scope='slider'][data-part='root']:has([data-part='tick-label'])
    [data-part='control'][data-orientation='horizontal'] {
    margin-inline: var(--xh-slider-control-gutter, var(--xh-space-6));
  }

  [data-scope='slider'][data-part='control'][data-orientation='vertical'] {
    flex-direction: column;
    justify-content: center;
    inline-size: var(--xh-_thumb-size);
    block-size: var(--xh-slider-vertical-length, 10rem);
  }

  /* 按下轨道即跳，拖动中光标换成"抓着"的样子，手感与拇指一致 */
  [data-scope='slider'][data-part='control'][data-dragging] {
    cursor: grabbing;
  }

  [data-scope='slider'][data-part='control'][data-readonly]:not([data-disabled]) {
    cursor: default;
  }

  [data-scope='slider'][data-part='control'][data-disabled] {
    cursor: not-allowed;
  }

  /* 已选区间以它为定位上下文。不写 overflow: hidden：作者把拇指写进轨道里也是合法结构，
     一裁就把拇指切掉半个；区间的圆角由它自己那条 border-radius 兜住，本就不靠轨道来裁。 */
  [data-scope='slider'][data-part='track'] {
    position: relative;
    border-radius: var(--xh-slider-track-radius, var(--xh-shape-pill));
    background: var(--xh-slider-track-bg, var(--xh-bg-subtle-active));
  }

  [data-scope='slider'][data-part='track'][data-orientation='horizontal'] {
    inline-size: 100%;
    block-size: var(--xh-_track-thickness);
  }

  [data-scope='slider'][data-part='track'][data-orientation='vertical'] {
    block-size: 100%;
    inline-size: var(--xh-_track-thickness);
  }

  /* 禁用：底槽退到 100 档淡底，已选区间换成禁用前景——两者仍分得开，值还读得出，只是没了品牌色 */
  [data-scope='slider'][data-part='track'][data-disabled] {
    background: var(--xh-slider-track-bg-disabled, var(--xh-bg-subtle));
  }

  /* 主轴（起点 + 长度）来自内联样式，这里只给定位模式与配色。
     绝不给 inset / size 加过渡：拖拽时这两个值每帧都在变，一加过渡区间就永远追在指针后面。
     语气槽由 root 上的 data-tone 声明、经继承发下来；没写 data-tone 时退回原来的品牌色。
     轨道不跟着换族：区间与拇指换色即可读出语气，底槽保持中性才不会盖掉"已选/未选"的对比。 */
  [data-scope='slider'][data-part='range'] {
    position: absolute;
    border-radius: var(--xh-slider-range-radius, var(--xh-shape-pill));
    background: var(--xh-slider-range-bg, var(--xh-_tone, var(--xh-bg-brand)));
  }

  /* 交叉轴铺满轨道。这一侧的 inset 连接层每帧写成空串（即不设），样式表接手才有确定值；
     不写的话绝对定位会退回"静态位置"，作者一给轨道加内边距就对不齐了。 */
  [data-scope='slider'][data-part='range'][data-orientation='horizontal'] {
    inset-block-start: 0;
    block-size: 100%;
  }

  [data-scope='slider'][data-part='range'][data-orientation='vertical'] {
    inset-inline-start: 0;
    inline-size: 100%;
  }

  [data-scope='slider'][data-part='range'][data-invalid] {
    background: var(--xh-slider-range-bg-invalid, var(--xh-border-invalid));
  }

  [data-scope='slider'][data-part='range'][data-disabled] {
    background: var(--xh-slider-range-bg-disabled, var(--xh-fg-disabled));
  }

  /* 圆点浮在轨道之上：轨道是流内的，拇指是绝对定位的，天然后来居上，不必再堆 z-index。
     box-sizing 必须显式写：描边要吃进直径里，否则实际盒子比 --xh-_thumb-size 宽两条边，
     下面按半个直径回拉的负外边距就对不上圆心。
     拇指是可拖起的 raised 面：描边取 --xh-border-default，raised 影只是加成、不作边界 */
  [data-scope='slider'][data-part='thumb'] {
    position: absolute;
    box-sizing: border-box;
    inline-size: var(--xh-_thumb-size);
    block-size: var(--xh-_thumb-size);
    border: var(--xh-stroke-thick) solid var(--xh-slider-thumb-border, var(--xh-border-default));
    border-radius: var(--xh-slider-thumb-radius, var(--xh-shape-circle));
    background: var(--xh-slider-thumb-bg, var(--xh-_tone, var(--xh-bg-brand)));
    /* 圆点上没有字，这一支是给环用的：环灌 currentColor 时取到的是与这块底配对的前景色，
       不写就取到从页面继承下来的正文色 */
    color: var(--xh-_tone-on, var(--xh-fg-on-brand));
    box-shadow: var(--xh-slider-thumb-shadow, var(--xh-elevation-raised));
    cursor: grab;
    transition:
      scale var(--xh-motion-duration-nudge) var(--xh-motion-ease-enter-strong),
      box-shadow var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 面是实心的，环色与面同族，画在面里就看不出来；环改取面自己的前景色——
     那一族色本来就要在这块面上把字读清楚，与面的对比是按可读性定的。
     禁用的拇指退成白面，不在这一档里，吃库环 */
  [data-scope='slider'][data-part='thumb']:not([data-disabled]):focus-visible {
    --xh-_ring-color: currentColor;
  }

  /* 内联样式把 inset-inline-start 定在值所在的比例上，那是拇指的**起始边**不是圆心；
     用负的逻辑外边距回拉半个直径，圆心才落在比例点上。
     这里刻意不用 translate(-50%)：rtl 下 inset-inline-start 映射到 right，
     位移量是物理方向的，会把拇指推向错误的一侧；负的逻辑外边距自己就跟着换向。
     交叉轴同理：inset-block-start 是连接层不写的那条轴，样式表接管即可。 */
  [data-scope='slider'][data-part='thumb'][data-orientation='horizontal'] {
    inset-block-start: 50%;
    margin-block-start: calc(var(--xh-_thumb-size) / -2);
    margin-inline-start: calc(var(--xh-_thumb-size) / -2);
  }

  /* 竖排的主轴是 inset-block-end（值向上增大），回拉也就换到 block-end 那侧 */
  [data-scope='slider'][data-part='thumb'][data-orientation='vertical'] {
    inset-inline-start: 50%;
    margin-inline-start: calc(var(--xh-_thumb-size) / -2);
    margin-block-end: calc(var(--xh-_thumb-size) / -2);
  }

  /* 多拇指时只有手真正推着的那一个带 data-dragging，放大与光标因此不会全组一起变。
     放大用 scale 而不是改尺寸：变换绕自身中心发生，圆心不动，负外边距的算式也不用跟着改。
     海拔从静态的 raised 换到 lifted：跟着手走的东西比贴在页面上的抬得高一档，
     又不到锚定浮层那一层——用 floating 会让拇指和下拉面板一样重。 */
  [data-scope='slider'][data-part='thumb'][data-dragging] {
    scale: var(--xh-slider-thumb-scale-dragging, var(--xh-motion-scale-drag));
    cursor: grabbing;
    box-shadow: var(--xh-slider-thumb-shadow-dragging, var(--xh-elevation-lifted));
  }

  [data-scope='slider'][data-part='thumb'][data-invalid] {
    background: var(--xh-slider-thumb-bg-invalid, var(--xh-border-invalid));
  }

  [data-scope='slider'][data-part='thumb'][data-readonly]:not([data-disabled]) {
    cursor: default;
  }

  /* 禁用：面退到实体白面、描边留着、影收掉——拖不起来的东西不该看着像浮在轨道上。
     不写 color：圆点上没有字，禁用拇指不进 Tab 序列也不会聚焦，环的前景在这里没有消费者 */
  [data-scope='slider'][data-part='thumb'][data-disabled] {
    background: var(--xh-slider-thumb-bg-disabled, var(--xh-bg-surface));
    box-shadow: var(--xh-slider-thumb-shadow-disabled, none);
    cursor: not-allowed;
  }

  /* 值气泡：挂在拇指里，跟着拇指一起走位。
     两侧 inset 都钉在 50% 再靠自动外边距回中：气泡宽度由文字撑出，用 translate 回中的话
     rtl 下 inset-inline-start 映射到 right，位移是物理方向的，会把气泡推向错误的一侧。
     默认只在推动那一刻露面，静止时留在 DOM 里但不占视线 */
  [data-scope='slider'][data-part='value-text'] {
    position: absolute;
    inset-block-end: 100%;
    inset-inline: 50%;
    inline-size: max-content;
    margin-block-end: var(--xh-slider-value-text-offset, var(--xh-space-2));
    margin-inline: auto;
    padding-block: var(--xh-slider-value-text-py, var(--xh-space-0_5));
    padding-inline: var(--xh-slider-value-text-px, var(--xh-space-2));
    border-radius: var(--xh-slider-value-text-radius, var(--xh-shape-control));
    background: var(--xh-slider-value-text-bg, var(--xh-_tone, var(--xh-bg-brand)));
    color: var(--xh-slider-value-text-fg, var(--xh-_tone-on, var(--xh-fg-on-brand)));
    font-size: var(--xh-slider-value-text-font-size, var(--xh-text-caption-size));
    line-height: var(--xh-leading-normal);
    white-space: nowrap;
    /* 气泡贴在拇指上方，指针要落到拇指上，不能被它挡住 */
    pointer-events: none;
    opacity: 0;
    transition: opacity var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='slider'][data-part='value-text'][hidden] {
    display: none;
  }

  /* 只有手真正推着的那一个拇指带 data-dragging，多拇指时气泡不会全组一起冒出来 */
  [data-scope='slider'][data-part='value-text'][data-dragging] {
    opacity: 1;
  }

  /* 竖排轨道的气泡挪到行侧：压在拇指上方会挡住上一档的值 */
  [data-scope='slider'][data-part='value-text'][data-orientation='vertical'] {
    inset-block: 50%;
    inset-inline: 100% auto;
    block-size: max-content;
    margin-block: auto;
    margin-inline: var(--xh-slider-value-text-offset, var(--xh-space-2)) 0;
  }

  /* —— 尺寸 —— */
  /* 尺寸只改 root 上那两个槽位，control / track / thumb 跟着一起走；中间档不写规则，缺省即中档。
     两档都保持"拇指是轨道的三倍厚"这个比例，换档时圆点与底槽的关系看着不变。 */
  [data-scope='slider'][data-part='root'][data-size='sm'] {
    --xh-_thumb-size: var(--xh-slider-thumb-size, var(--xh-space-3));
    --xh-_track-thickness: var(--xh-slider-track-thickness, var(--xh-space-1));
  }

  [data-scope='slider'][data-part='root'][data-size='lg'] {
    --xh-_thumb-size: var(--xh-slider-thumb-size, var(--xh-space-6));
    --xh-_track-thickness: var(--xh-slider-track-thickness, var(--xh-space-2));
  }

  /* —— 刻度：圆点钉在轨道上、文案排在轨道外侧，坐标由连接层按百分比内联给出 —— */
  [data-scope='slider'][data-part='tick-group'] {
    position: absolute;
    inset: 0;
    pointer-events: none;
  }

  /* 刻度点是正方盒，取 circle（正方盒不得用 pill 冒充圆） */
  [data-scope='slider'][data-part='tick'] {
    position: absolute;
    inset-block-start: 50%;
    inline-size: var(--xh-slider-tick-size, var(--xh-space-1));
    block-size: var(--xh-slider-tick-size, var(--xh-space-1));
    border-radius: var(--xh-slider-tick-radius, var(--xh-shape-circle));
    background: var(--xh-slider-tick-bg, var(--xh-border-strong));
    translate: -50% -50%;
  }

  /* 落进已选区间的刻度点跟 range 同色 */
  [data-scope='slider'][data-part='tick'][data-passed] {
    background: var(--xh-slider-tick-bg-active, var(--xh-_tone, var(--xh-bg-brand)));
  }

  [data-scope='slider'][data-part='tick-label'] {
    position: absolute;
    inset-block-start: 100%;
    margin-block-start: var(--xh-slider-tick-label-gap, var(--xh-space-1));
    color: var(--xh-slider-tick-label-fg, var(--xh-fg-subtle));
    font-size: var(--xh-slider-tick-label-font-size, var(--xh-text-caption-size));
    line-height: var(--xh-leading-none);
    white-space: nowrap;
    translate: -50% 0;
    cursor: pointer;
    pointer-events: auto;
    user-select: none;
  }

  [data-scope='slider'][data-part='tick-label'][data-passed] {
    color: var(--xh-slider-tick-label-fg-active, var(--xh-fg-default));
  }

  /* 禁用：刻度点与文案由 tick-group 上的 data-disabled 下发（连接层不给每个刻度单发），
     已过的刻度点与区间同色，文案换禁用前景，点它跳档的手型收掉 */
  [data-scope='slider'][data-part='tick-group'][data-disabled] [data-part='tick'] {
    background: var(--xh-slider-tick-bg-disabled, var(--xh-border-default));
  }

  [data-scope='slider'][data-part='tick-group'][data-disabled] [data-part='tick'][data-passed] {
    background: var(--xh-slider-tick-bg-active-disabled, var(--xh-fg-disabled));
  }

  [data-scope='slider'][data-part='tick-group'][data-disabled] [data-part='tick-label'] {
    color: var(--xh-slider-tick-label-fg-disabled, var(--xh-fg-disabled));
    cursor: not-allowed;
  }

  /* 竖直轨道：点与文案换轴，坐标由连接层写在 block 轴上 */
  [data-scope='slider'][data-part='root'][data-orientation='vertical'] [data-part='tick'] {
    inset-block-start: auto;
    inset-inline-start: 50%;
    translate: -50% 50%;
  }

  [data-scope='slider'][data-part='root'][data-orientation='vertical'] [data-part='tick-label'] {
    inset-block-start: auto;
    inset-inline-start: 100%;
    margin-block-start: 0;
    margin-inline-start: var(--xh-slider-tick-label-gap, var(--xh-space-1));
    translate: 0 50%;
  }

  /* display 会盖掉 UA 的 [hidden]{display:none}，凡是被赋了 display 的角色节点都要显式让位 */
  [data-scope='slider'][data-part='root'][hidden],
  [data-scope='slider'][data-part='control'][hidden] {
    display: none;
  }

  /* hidden-input 是 type=hidden 的原生输入，浏览器本就不渲染它，
     这里一条声明都不给：给了 display / 尺寸反而会把它拽回布局里，在拇指内部撑出一块空白。 */
}

/* styles/sortable.css */
/* 定义 sortable 样式。 */

/* Sortable 独立皮肤同时传递引入把手的动作控件配方；full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='sortable'] {
    --xh-sortable-skin: 1;
  }

  /* 分工：**每一项的位移**由连接层每帧写进内联 transform（让位与跟手都在那儿算）。
     这份皮肤一条都不碰 transform——内联优先级更高，写了不但是死声明，
     还会在拖动的每一帧跟连接层抢位置。皮肤只管排布方向、间距、光标与状态表现。 */

  [data-scope='sortable'][data-part='root'] {
    display: flex;
    gap: var(--xh-sortable-gap, var(--xh-space-2));
  }

  /* 拖动期间关掉选中：整项可拖时按下不 preventDefault，不关这条会一路刷蓝 */
  [data-scope='sortable'][data-part='root'][data-dragging] {
    user-select: none;
  }

  [data-scope='sortable'][data-part='root'][data-orientation='vertical'] {
    flex-direction: column;
  }

  [data-scope='sortable'][data-part='root'][data-orientation='horizontal'] {
    flex-direction: row;
  }

  /* 换行网格：主轴横排、允许折行，落点按最近中心判，与单轴那两档是不同的判据 */
  [data-scope='sortable'][data-part='root'][data-orientation='both'] {
    flex-direction: row;
    flex-wrap: wrap;
  }

  /* 项里面放什么、怎么排全是使用者的事：这里不给 display 也不给间距。
     给了会盖掉使用者自己的单元格布局——网格里的一格被压成 flex 行之后就不再撑满，
     看起来像是尺寸算错了。皮肤只管拖起来那一项的视觉反馈。 */

  /* 让位期间关掉过渡，跟手的那一项才不会慢半拍粘在指针后面。
     其余项反过来要过渡：它们是被让开的，瞬移会看不出发生了什么。 */
  [data-scope='sortable'][data-part='root'][data-dragging] [data-part='item']:not([data-dragging]) {
    transition: transform var(--xh-motion-duration-nudge) var(--xh-motion-ease-continuous);
  }

  /* 抓起与放下时的抬升、压深都淡变。位移不进这条：它由连接层每帧写内联 transform */
  [data-scope='sortable'][data-part='item'] {
    transition:
      box-shadow var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      opacity var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='sortable'][data-part='item'][data-dragging] {
    /* 拖起来的那一项浮在上面。层级由连接层写内联，这里只管观感。
       海拔取 lifted：被指针拎起、正跟着手走的东西比贴在页面上的 raised 高一档，又不到锚定浮层那一层。
       拖起的面是作者自己的内容，皮肤不给它强加描边——描边归作者的项目布局 */
    box-shadow: var(--xh-sortable-item-shadow-dragging, var(--xh-elevation-lifted));
    opacity: var(--xh-sortable-item-opacity-dragging, 0.9);
  }

  /* 把手是只有字形的离散动作钮（定尺把手）：盒几何、悬停 / 按下与 0.97 按压、粗指针热区、焦点环、
     禁用面全由 Action Control 的 icon ghost 档给（连接层投 xs：24px 正方盒，与此前 --xh-control-action-size
     同尺寸），组件只映射既有使用者槽。静息透明，白底承载 hover 100 → pressed 200（此前悬停落 200 是错档）。
     手型不是 pointer：抓起来拖的东西给 grab，按住拖动中给 grabbing；家族的手型槽逐态映射 */
  [data-scope='sortable'][data-part='item-drag-trigger'] {
    --xh-action-visual-size: var(--xh-sortable-drag-size, var(--xh-_action-profile-visual-size));
    --xh-action-min-inline-size: var(--xh-sortable-drag-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-sortable-drag-radius, var(--xh-shape-control));
    --xh-action-bg-hover: var(--xh-sortable-drag-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-sortable-drag-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-sortable-drag-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-sortable-drag-fg-hover, var(--xh-fg-default));
    --xh-action-fg-pressed: var(--xh-sortable-drag-fg-hover, var(--xh-fg-default));
    --xh-action-fg-disabled: var(--xh-sortable-drag-fg-disabled, var(--xh-fg-disabled));
    --xh-action-border-rest: transparent;
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    --xh-action-cursor-rest: grab;
    --xh-action-cursor-hover: grab;
    --xh-action-cursor-focus-visible: grab;
    --xh-action-cursor-pressed: grabbing;
    /* 作者塞进把手的图标按档取字形尺（xs → 16px）；皮肤画的兜底抓手是两条描边线，不走这把尺 */
    --xh-icon-size: var(--xh-sortable-drag-icon-size, var(--xh-_action-profile-glyph-size));

    border-width: 0;
  }

  /* 抓手是两条竖线：盒子取边框盒，两侧描边就是那两条线，宽高与线宽都走令牌。
     :empty 守卫让作者塞进来的图标整个顶掉它，而不是两份叠在一起。
     不画这条的话按钮里空无一物，只剩一块摸不着边的透明命中区 */
  [data-scope='sortable'][data-part='item-drag-trigger']:empty::after {
    content: '';
    display: block;
    inline-size: var(--xh-sortable-drag-grip-w, var(--xh-space-1));
    block-size: var(--xh-sortable-drag-grip-h, var(--xh-space-3));
    border-inline: var(--xh-stroke-thin) solid currentColor;
  }

  /* 手指落点：家族 icon 档用 ::after 把命中区扩到 44×44；没塞图标的把手 ::after 已被抓手占着，
     抓手那条只写了宽高与描边，家族的定位、44px 下限与 -50% 平移会从同一个 ::after 漏进来，
     两条竖线被撑成 44px 高、跨出把手——这里逐项钉回，热区改由空着的 ::before 扩；
     作者塞了图标时 :empty 不成立，家族的 ::after 照常落下 */
  @media (pointer: coarse) {
    [data-scope='sortable'][data-part='item-drag-trigger']:empty::after {
      position: static;
      min-inline-size: 0;
      min-block-size: 0;
      translate: none;
    }

    [data-scope='sortable'][data-part='item-drag-trigger']:empty::before {
      content: '';
      position: absolute;
      inset-block-start: 50%;
      inset-inline-start: 50%;
      min-inline-size: 44px;
      min-block-size: 44px;
      inline-size: 100%;
      block-size: 100%;
      translate: -50% -50%;
    }

    /* 与家族同一笔：起点是逻辑属性、平移是物理通道，rtl 下行内分量掉头，热区才落回把手中心 */
    [data-scope='sortable'][data-part='item-drag-trigger']:empty:dir(rtl)::before {
      translate: 50% -50%;
    }
  }

  /* 拖动中（指针按住或键盘拾起）：光标换成"抓着"的样子，各态的手型槽一并换掉——
     家族的悬停 / 按下块比这条特指度高，直接写 cursor 会被盖回去 */
  [data-scope='sortable'][data-part='item-drag-trigger'][data-dragging] {
    --xh-action-cursor-rest: grabbing;
    --xh-action-cursor-hover: grabbing;
    --xh-action-cursor-focus-visible: grabbing;
    --xh-action-cursor-pressed: grabbing;
  }

  /* 落点线：容器的绝对定位子节点，起点与长度由连接层每帧写内联，这里只给粗细与颜色。
     容器要自建定位上下文，线才落在它自己的坐标系里 */
  [data-scope='sortable'][data-part='root']:has([data-part='drop-indicator']) {
    position: relative;
  }

  /* 不写层号：它是定位子节点，写在末项之后就画在各项之上，组件内不另立层序 */
  [data-scope='sortable'][data-part='drop-indicator'] {
    position: absolute;
    display: block;
    /* 线不接指针：它盖在项上面，接了就挡住落点那一格 */
    pointer-events: none;
    border-radius: var(--xh-sortable-drop-indicator-radius, var(--xh-shape-pill));
    background: var(--xh-sortable-drop-indicator-bg, var(--xh-bg-brand));
    /* 落点一格一格地跳，线跟着滑过去 */
    transition: transform var(--xh-motion-duration-nudge) var(--xh-motion-ease-continuous);
  }

  /* 竖排时是一条横线铺满容器，横排与换行网格时是一条竖线 */
  [data-scope='sortable'][data-part='drop-indicator'][data-orientation='vertical'] {
    inline-size: 100%;
    block-size: var(--xh-sortable-drop-indicator-size, var(--xh-stroke-thick));
  }

  [data-scope='sortable'][data-part='drop-indicator'][data-orientation='horizontal'],
  [data-scope='sortable'][data-part='drop-indicator'][data-orientation='both'] {
    inline-size: var(--xh-sortable-drop-indicator-size, var(--xh-stroke-thick));
    block-size: 100%;
  }

  /* 活动区域只说给读屏听，不占版面。声明与 shared/visually-hidden.ts 逐条同值。 */
  [data-scope='sortable'][data-part='live-region'] {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }
  /* 给了 display 的角色节点必须补这条：display 声明会盖掉 UA 的 [hidden]{display:none}，
     不补的话作者给节点加 hidden 后它照样显示 */
  [data-scope='sortable'][data-part='root'][hidden],
  [data-scope='sortable'][data-part='item-drag-trigger'][hidden],
  [data-scope='sortable'][data-part='drop-indicator'][hidden] {
    display: none;
  }
}

/* styles/splitter.css */
/* 定义 splitter 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='splitter'] {
    --xh-splitter-skin: 1;
  }

  /* 分工：**面板在排布轴上的尺寸**由连接层每帧写进内联样式（flex-basis / flex-grow / flex-shrink）。
     这份皮肤一条都不碰——内联优先级高于样式表，写了不但是死声明，
     还会在切换 orientation 的那一帧跟连接层抢位置。皮肤只管排布方向、跨轴尺寸、
     配色、光标与状态表现。

     三个角色节点上的 data-orientation 说的都是**面板怎么排**（与 root 上那条同源）；
     分隔条自身的横竖与它垂直，那件事写在 aria-orientation 上，样式不去读 ARIA。 */

  [data-scope='splitter'][data-part='root'] {
    display: flex;
    /* 跨轴尺寸由作者给：竖排的分栏必须先有确定的高度，才谈得上把它分成几份 */
    align-items: stretch;
    overflow: hidden;
    border-radius: var(--xh-splitter-radius, var(--xh-shape-surface));
  }

  [data-scope='splitter'][data-part='root'][data-orientation='horizontal'] {
    flex-direction: row;
  }

  [data-scope='splitter'][data-part='root'][data-orientation='vertical'] {
    flex-direction: column;
  }

  /* 纯容器，焦点长在分隔条上，这里画环只会闪一下 */
  [data-scope='splitter'][data-part='root']:focus-visible {
    outline: none;
  }

  /* 禁用的整体压暗只做一次，落在最外层：面板与分隔条各自再叠一层 opacity 会越叠越黑。
     这一档压的是宿主塞进面板里的正文，不是控件自己的图形，所以地板比 --xh-state-disabled-opacity
     高：那一档是 0.5，黑字白底压完只有 3.94:1，读不出字。压暗仍要表达「这块动不了」，
     所以留一个槽让使用者按自己的配色调，而不是直接不压。 */
  [data-scope='splitter'][data-part='root'][data-disabled] {
    opacity: var(--xh-splitter-disabled-opacity, 0.6);
  }

  /* 拖动期间整块不许选中文字：手在分隔条上来回蹭时会顺带把两侧的正文刷成高亮 */
  [data-scope='splitter'][data-part='root'][data-dragging] {
    user-select: none;
  }

  /* 拖动中的光标写在容器上而不是分隔条上：那条线只有几像素宽，
     手一快指针就跑到面板上去了，光标随即变回箭头，看着像拖拽断了 */
  [data-scope='splitter'][data-part='root'][data-orientation='horizontal'][data-dragging] {
    cursor: col-resize;
  }

  [data-scope='splitter'][data-part='root'][data-orientation='vertical'][data-dragging] {
    cursor: row-resize;
  }

  /* 面板自己不许把容器撑破：内容再宽也只能溢出自己这一格，
     否则连接层算好的比例会被一段长文本顶开 */
  [data-scope='splitter'][data-part='panel'] {
    position: relative;
    overflow: hidden;
  }

  /* flex 项目的自动最小尺寸默认是内容宽，比 flex-basis 更硬——
     不把它挪开，连接层内联写的 basis / shrink 在内容超宽时会被静默架空。
     这两条给的不是尺寸，是"允许收到多小"的地板，因此不与内联样式冲突 */
  [data-scope='splitter'][data-part='panel'][data-orientation='horizontal'] {
    min-inline-size: 0;
  }

  [data-scope='splitter'][data-part='panel'][data-orientation='vertical'] {
    min-block-size: 0;
  }

  [data-scope='splitter'][data-part='panel']:focus-visible {
    outline: none;
  }

  /* 折叠到 0 时连边框都不该露出来：留一条缝比留一块面板更像坏了 */
  [data-scope='splitter'][data-part='panel'][data-collapsed] {
    border: none;
  }

  /* 分隔条自己的粗细归皮肤（连接层不碰它这条轴）。
     flex: none 是必须的：它若跟着一起伸缩，面板的百分比就再也对不上了 */
  [data-scope='splitter'][data-part='resize-trigger'] {
    display: flex;
    flex: none;
    align-items: center;
    justify-content: center;
    background: var(--xh-splitter-trigger-bg, var(--xh-border-default));
    transition: background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='splitter'][data-part='resize-trigger'][data-orientation='horizontal'] {
    inline-size: var(--xh-splitter-trigger-thickness, var(--xh-space-1));
    cursor: col-resize;
  }

  [data-scope='splitter'][data-part='resize-trigger'][data-orientation='vertical'] {
    block-size: var(--xh-splitter-trigger-thickness, var(--xh-space-1));
    cursor: row-resize;
  }

  /* 分隔条是一根线不是一块面：悬停不走面阶梯（300 只留给 pressed），
     按线取——与字段描边 rest → hover 同向加深一档 */
  [data-scope='splitter'][data-part='resize-trigger']:hover {
    background: var(--xh-splitter-trigger-bg-hover, var(--xh-border-control));
  }

  /* 只有正被拖的那条带 data-dragging：多条分隔条时全高亮就分不出手在哪一条上 */
  [data-scope='splitter'][data-part='resize-trigger'][data-dragging] {
    background: var(--xh-splitter-trigger-bg-dragging, var(--xh-bg-brand));
  }

  /* 常态灰面与公共品牌环已经过线；拖动态才改用品牌面配对前景，避免同色环。 */
  [data-scope='splitter'][data-part='resize-trigger'][data-dragging]:focus-visible {
    --xh-_ring-color: var(--xh-fg-on-brand);
  }

  /* 分隔条是 div、role=separator，原生 disabled 在它身上不生效，
     禁用只表达成 aria-disabled 与 data-disabled，写 :disabled 永远不命中。
     光标不交给公共层：上面两条按走向给的 col-resize / row-resize 特异性相同又排在后面，
     公共层那条压不过它们 */
  [data-scope='splitter'][data-part='resize-trigger'][data-disabled] {
    background: var(--xh-splitter-trigger-bg-disabled, var(--xh-border-subtle));
    cursor: not-allowed;
  }

  /* 给了 display 的角色节点必须补这条：display 声明会盖掉 UA 的 [hidden]{display:none}，
     不补的话作者给节点加 hidden 后它照样显示 */
  [data-scope='splitter'][data-part='root'][hidden],
  [data-scope='splitter'][data-part='resize-trigger'][hidden] {
    display: none;
  }

  @media (forced-colors: active) {
    /* 分隔条画的是一块纯底色，这一档里底色被统一换成 Canvas，那条线整根消失，
       两侧面板就糊成一块。换成前景色画回来 */
    [data-scope='splitter'][data-part='resize-trigger'] {
      background: CanvasText;
    }
  }
}

/* styles/steps.css */
/* 定义 steps 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='steps'] {
    --xh-steps-skin: 1;
  }

  [data-scope='steps'][data-part='root'] {
    /* 作者放进标题 / 说明里的图标按档取尺，缺省 sm。走过的步里皮肤画的兜底对号不读这支：
       它是指示符，与序号圆点同走 --xh-control-indicator-* 一族——圆点在自己身上把 --xh-icon-size
       改接到 --xh-steps-indicator-mark-size，兜底对号与作者塞进圆点里的 XhIcon 读同一把尺 */
    --xh-icon-size: var(--xh-steps-icon-size, var(--xh-glyph-size-sm));

    /* 尺寸档只换这三个私有槽，序号圆点、标题与圆点里的序号都从 root 继承它们，
       换档不必给每个部件各写一条选择器；说明走说明角色（13px），不随档 */
    --xh-_steps-indicator-size: var(--xh-space-8);
    --xh-_steps-title-font-size: var(--xh-control-font-md);
    --xh-_steps-caption-font-size: var(--xh-text-caption-size);

    /* 语气落在当前步的标记、走过那几步的对号与连接线上：强调色画描边与填充，
       accent-text 是普通底上的强调文字（走过与当前步的标题），on-accent 是实心底上的前景。
       没写 data-tone 时 --xh-_tone 一族没被声明，三个槽都退回原来的品牌配色。
       走过的步不再用品牌淡底（brand-subtle 退出 completed 语义），淡底那两支私有槽随之撤掉 */
    --xh-_steps-accent: var(--xh-_tone, var(--xh-bg-brand));
    --xh-_steps-accent-text: var(--xh-_tone-fg, var(--xh-fg-brand-strong));
    /* 走过的步里那枚对号：中性淡底上的品牌色标记，不用标题那档更深的字色 */
    --xh-_steps-accent-mark: var(--xh-_tone-fg, var(--xh-fg-brand));
    --xh-_steps-on-accent: var(--xh-_tone-on, var(--xh-fg-on-brand));
    /* 触发器是序号圆点的承载面：圆点静息就坐在 --xh-bg-subtle（100）的淡底上，阶梯按淡底容器走
       （hover 200 → pressed 300）。两支私有槽是这一档的唯一来源——触发器拿它们给
       --xh-action-host-bg-* 赋值（桥接槽只写不读），圆点悬停 / 按下读同一支私有槽，即与宿主的 host 槽同源 */
    --xh-_steps-host-bg-hover: var(--xh-bg-subtle-hover);
    --xh-_steps-host-bg-pressed: var(--xh-bg-subtle-active);
    /* 走过的那几步是实心圆，顶边画一条极浅的内高光把它衬出厚度 */
    --xh-_steps-highlight: inset 0 var(--xh-stroke-thin) 0 0
      color-mix(in oklab, var(--xh-_steps-on-accent) 14%, transparent);

    display: flex;
    flex-direction: column;
    gap: var(--xh-steps-gap, var(--xh-stack-gap-md));
  }

  [data-scope='steps'][data-part='root'][hidden] {
    display: none;
  }

  /* 纵向：步骤列与面板并排；两栏一起放不下时面板换到下一行，步骤列因此拿得回整行宽度 */
  [data-scope='steps'][data-part='root'][data-orientation='vertical'] {
    flex-direction: row;
    flex-wrap: wrap;
  }

  /* 面板的换行基准：一行正文的宽度。步骤列的内容宽加上这一格放不下，两者就分成两行 */
  [data-scope='steps'][data-part='root'][data-orientation='vertical'] > [data-scope='steps'][data-part='content'] {
    flex: 1 1 var(--xh-steps-content-min-inline-size, var(--xh-measure-prose));
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里。圆点直径不在 control-h 那把尺上（缺省是 sm 档的 28px），
     两侧改从 space 档取，缺省档才留得住 */
  [data-scope='steps'][data-part='root'][data-size='sm'] {
    --xh-_steps-indicator-size: var(--xh-space-7);
    --xh-_steps-title-font-size: var(--xh-control-font-sm);
    /* 字号档最小就是 xs，序号不再往下走，故不重声明 caption */
  }

  [data-scope='steps'][data-part='root'][data-size='lg'] {
    --xh-_steps-indicator-size: var(--xh-control-h-lg);
    --xh-_steps-title-font-size: var(--xh-control-font-lg);
    --xh-_steps-caption-font-size: var(--xh-text-secondary-size);
  }

  /* 步骤与连接线必须保持在同一条流程轴上，空间不足时由标题省略而不是拆成两行。 */
  [data-scope='steps'][data-part='list'] {
    display: flex;
    flex-wrap: nowrap;
    align-items: flex-start;
    gap: var(--xh-steps-list-gap, var(--xh-space-0));
  }

  [data-scope='steps'][data-part='list'][hidden] {
    display: none;
  }

  /* 竖排时列被拉到与面板同高，那是一个确定的块向尺寸；折行在这里会把步骤摊成两列，
     所以这一档明确关掉 */
  [data-scope='steps'][data-part='list'][data-orientation='vertical'] {
    flex-direction: column;
    flex-wrap: nowrap;
    align-items: stretch;
  }

  /* 每一步与它后面那截连接线一起占一格，等分整行；min-inline-size 允许被压缩，
     标题里的省略号才有生效的余地 */
  [data-scope='steps'][data-part='item'] {
    display: flex;
    flex: 1;
    align-items: center;
    gap: var(--xh-steps-item-gap, var(--xh-space-2));
    min-inline-size: 0;
  }

  [data-scope='steps'][data-part='item'][hidden] {
    display: none;
  }

  /* 末步后面没有"下一步"，那截连接线不该占地方；作者不写它也一样，写了就替他收掉。
     末步按内容宽摆、不参与伸缩，标题长过整行时由 100% 收住，超出的部分走省略号 */
  [data-scope='steps'][data-part='item']:last-child {
    flex: none;
    max-inline-size: 100%;
  }

  [data-scope='steps'][data-part='item']:last-child [data-scope='steps'][data-part='separator'] {
    display: none;
  }

  /* 横排始终留在同一条轴上，标题与说明负责在自己的格内省略。 */
  [data-scope='steps'][data-part='item'][data-orientation='horizontal']:not(:last-child) {
    min-inline-size: var(--xh-steps-item-min-inline-size, var(--xh-space-0));
  }

  [data-scope='steps'][data-part='item'][data-orientation='vertical'] {
    flex-direction: column;
    flex: none;
    align-items: flex-start;
  }

  /* 触发器是「序号 + 标题 + 说明」的整块内容行：接 Action Control row 档、ghost 形态，悬停 / 按下 / 禁用面、
     手型、过渡与焦点环由家族给，按下只换面不缩放（row 档专属按压块 scale: none）；这里只把使用者槽映射到桥接槽。
     触发器既是 Action Control 又是圆点的承载面：自己坐画布走 hover 100 → pressed 200，由 --xh-action-bg-* 钉住；
     --xh-action-host-bg-* 只对圆点生效（圆点自己是 100 的淡底，坐在触发器面上再上一档到 200 / 300）。
     排成两列：序号占左列并跨两行，标题与说明各占右列一行。用 grid 而不是再包一层节点——解剖里没有那个包裹层，
     作者也不该被逼着多写一个 div；只有说明缺席时右列的第二行是零高，不会留白 */
  [data-scope='steps'][data-part='trigger'] {
    /* 纵向留一圈给悬停底色与焦点环，横向走控件内边距尺的小档；一个槽同时盖住两轴 */
    --xh-action-padding-block: var(--xh-steps-trigger-p, var(--xh-space-1));
    --xh-action-padding-inline: var(--xh-steps-trigger-p, var(--xh-control-px-sm));
    --xh-action-radius: var(--xh-steps-trigger-radius, var(--xh-shape-control));
    /* 列距仍由 column-gap 给：家族的 gap 会连 row-gap 一起把标题与说明撑开 */
    --xh-action-gap: 0;
    /* 高度由圆点 + 内距决定，不取 control-h 地板 */
    --xh-action-visual-size: 0;
    --xh-action-font-size: inherit;
    /* 标题 / 说明 / 圆点各自着色，行本身不定字色 */
    --xh-action-fg-rest: currentColor;
    --xh-action-fg-hover: currentColor;
    --xh-action-fg-pressed: currentColor;
    --xh-action-fg-focus-visible: currentColor;
    --xh-action-fg-disabled: currentColor;
    --xh-action-bg-hover: var(--xh-steps-trigger-bg-hover, var(--xh-bg-subtle));
    --xh-action-bg-pressed: var(--xh-steps-trigger-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-action-host-bg-hover: var(--xh-_steps-host-bg-hover);
    --xh-action-host-bg-pressed: var(--xh-_steps-host-bg-pressed);

    /* 皮肤规则排在 @import 之后，同特指度盖过 row 档的 display: flex */
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    align-items: center;
    column-gap: var(--xh-steps-trigger-gap, var(--xh-control-gap-md));
    /* row 档铺满容器（inline-size: 100%）会把横排的连接线压到最小长度 */
    inline-size: auto;
    /* 纵向连接线的 margin-inline-start 按圆点半径 + trigger-p 对齐圆心，ghost 的 1px 透明边位会让它错 1px */
    border-width: 0;
    font: inherit;
    text-align: start;
  }

  [data-scope='steps'][data-part='trigger'][hidden] {
    display: none;
  }

  [data-scope='steps'][data-part='item'][data-disabled] [data-scope='steps'][data-part='title'],
  [data-scope='steps'][data-part='item'][data-disabled] [data-scope='steps'][data-part='description'] {
    color: var(--xh-fg-disabled);
  }

  /* 序号圆点：未开始使用中性面，当前步骤实心强调，已完成步骤中性面上画品牌对号。 */
  [data-scope='steps'][data-part='indicator'] {
    /* 圆点里的字形是指示符：对号按指示符档取尺、随密度换档（comfortable 16 / compact 14），
       不读 root 上只管作者标题 / 说明图标的 --xh-steps-icon-size；作者塞进圆点的 XhIcon 与兜底对号同一把尺。
       圆点自己走 space / control-h 的尺（最小 28px），不随密度，两档字形在三档圆点里都留得出边距 */
    --xh-icon-size: var(--xh-steps-indicator-mark-size, var(--xh-control-indicator-size));

    display: inline-flex;
    grid-row: 1 / span 2;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-steps-indicator-size, var(--xh-_steps-indicator-size));
    block-size: var(--xh-steps-indicator-size, var(--xh-_steps-indicator-size));
    border: var(--xh-stroke-thin) solid var(--xh-steps-indicator-border, transparent);
    border-radius: var(--xh-steps-indicator-radius, var(--xh-shape-circle));
    background: var(--xh-steps-indicator-bg, var(--xh-bg-subtle));
    color: var(--xh-steps-indicator-fg, var(--xh-fg-muted));
    font-size: var(--xh-steps-indicator-font-size, var(--xh-_steps-caption-font-size));
    font-weight: var(--xh-font-weight-medium);
    /* 等宽数字：1 与 7 的字形宽度在比例字体里并不相同，不定住会让序号左右抖一格 */
    font-variant-numeric: tabular-nums;
    line-height: var(--xh-leading-none);
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      border-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      box-shadow var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='steps'][data-part='indicator'][hidden] {
    display: none;
  }

  /* 圆点是格状当前的标记，但不是激活宿主：宿主是投影了 row 档的触发器；圆点在宿主的
     :hover / :is(:active, [data-pressed]) 下读宿主 host 槽的同一来源换面，同一时间线，不缩放——
     圆点自己是 100 的淡底，坐在触发器的 hover 面（100）上，再上一档到 200 才与承载面分得开，按下到 300；
     当前步的实心面按下换语气 active 档 */
  [data-scope='steps'][data-part='trigger']:hover:not([data-disabled])
    [data-scope='steps'][data-part='indicator'][data-state='incomplete'] {
    background: var(--xh-steps-indicator-bg-hover, var(--xh-_steps-host-bg-hover));
    color: var(--xh-steps-indicator-fg-hover, var(--xh-fg-default));
  }

  [data-scope='steps'][data-part='trigger']:hover:not([data-disabled])
    [data-scope='steps'][data-part='indicator'][data-state='completed'] {
    background: var(--xh-steps-indicator-bg-completed-hover, var(--xh-_steps-host-bg-hover));
  }

  [data-scope='steps'][data-part='trigger']:not([data-disabled]):is(:active, [data-pressed])
    [data-scope='steps'][data-part='indicator']:is([data-state='incomplete'], [data-state='completed']) {
    background: var(--xh-steps-indicator-bg-pressed, var(--xh-_steps-host-bg-pressed));
    transition-duration: var(--xh-motion-duration-press);
    transition-timing-function: var(--xh-motion-ease-press);
  }

  [data-scope='steps'][data-part='trigger']:not([data-disabled]):is(:active, [data-pressed])
    [data-scope='steps'][data-part='indicator'][data-state='current'] {
    background: var(--xh-steps-indicator-bg-current-pressed, var(--xh-_tone-active, var(--xh-bg-brand-active)));
    transition-duration: var(--xh-motion-duration-press);
    transition-timing-function: var(--xh-motion-ease-press);
  }

  [data-scope='steps'][data-part='indicator'][data-state='current'] {
    border-color: var(--xh-steps-indicator-border-current, var(--xh-_steps-accent));
    background: var(--xh-steps-indicator-bg-current, var(--xh-_steps-accent));
    color: var(--xh-steps-indicator-fg-current, var(--xh-_steps-on-accent));
    box-shadow: var(--xh-steps-indicator-shadow, var(--xh-_steps-highlight));
  }

  /* 走过的步：中性淡底（透明边位）承一枚品牌色对号；标了语气的步对号跟语气的前景走 */
  [data-scope='steps'][data-part='indicator'][data-state='completed'] {
    border-color: var(--xh-steps-indicator-border-completed, transparent);
    background: var(--xh-steps-indicator-bg-completed, var(--xh-bg-subtle));
    color: var(--xh-steps-indicator-fg-completed, var(--xh-_steps-accent-mark));
  }

  /* 单步语气：tones / collection 给某一步标了 data-tone，四个强调槽在这一步重新从语气层取值，
     它的标记、标题与连接线照旧从祖先继承——只有这一步换色，状态那一档照算 */
  [data-scope='steps'][data-part='item'][data-tone] {
    --xh-_steps-accent: var(--xh-_tone);
    --xh-_steps-accent-text: var(--xh-_tone-fg);
    --xh-_steps-accent-mark: var(--xh-_tone-fg);
    --xh-_steps-on-accent: var(--xh-_tone-on);
  }

  /* 标了语气的那一步还没走到也得被看见：空心描边加同色数字，不动实心那档的内高光 */
  [data-scope='steps'][data-part='item'][data-tone]
    [data-scope='steps'][data-part='indicator'][data-state='incomplete'] {
    border-color: var(--xh-steps-indicator-border-toned, var(--xh-_steps-accent));
    background: var(--xh-steps-indicator-bg-toned, var(--xh-_tone-subtle));
    color: var(--xh-steps-indicator-fg-toned, var(--xh-_steps-accent-text));
  }

  [data-scope='steps'][data-part='item'][data-disabled] [data-scope='steps'][data-part='indicator'] {
    border-color: var(--xh-steps-indicator-border-disabled, var(--xh-border-default));
    background: var(--xh-steps-indicator-bg-disabled, var(--xh-bg-muted));
    color: var(--xh-steps-indicator-fg-disabled, var(--xh-fg-disabled));
    /* 这一步动不了，实心那档的内高光跟着收掉 */
    box-shadow: none;
  }

  /* 标题与说明都在右列：不给 display，网格布局会替它们块级化，
     [hidden] 时 UA 的 display:none 仍然压得住 */
  [data-scope='steps'][data-part='title'] {
    grid-column: 2;
    color: var(--xh-steps-title-fg, var(--xh-fg-muted));
    font-size: var(--xh-steps-title-font-size, var(--xh-_steps-title-font-size));
    font-weight: var(--xh-steps-title-font-weight, var(--xh-text-label-weight));
    line-height: var(--xh-leading-tight);
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  [data-scope='steps'][data-part='title']:is([data-state='current'], [data-state='completed']) {
    color: var(--xh-steps-title-fg-active, var(--xh-_steps-accent-text));
  }

  /* 标了语气的那一步标题跟着换色，不论走到没走到 */
  [data-scope='steps'][data-part='item'][data-tone] [data-scope='steps'][data-part='title'] {
    color: var(--xh-steps-title-fg-toned, var(--xh-_steps-accent-text));
  }

  /* 说明走说明角色：13 / fg-muted / leading-normal，不随 size 档 */
  [data-scope='steps'][data-part='description'] {
    grid-column: 2;
    color: var(--xh-steps-description-fg, var(--xh-fg-muted));
    font-size: var(--xh-steps-description-font-size, var(--xh-text-secondary-size));
    line-height: var(--xh-leading-normal);
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  /* 连接线属于它前面那一步：那一步走过了就整条点亮，进度因此是连续的一条线 */
  [data-scope='steps'][data-part='separator'] {
    flex: 1;
    min-inline-size: var(--xh-steps-separator-min-length, var(--xh-space-4));
    block-size: var(--xh-steps-separator-thickness, var(--xh-stroke-thick));
    border-radius: var(--xh-steps-separator-radius, var(--xh-shape-pill));
    background: var(--xh-steps-separator-bg, var(--xh-border-default));
    transition: background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='steps'][data-part='separator'][hidden] {
    display: none;
  }

  [data-scope='steps'][data-part='separator'][data-state='completed'] {
    background: var(--xh-steps-separator-bg-completed, var(--xh-_steps-accent));
  }

  /* 纵向时连接线转成竖的一条，缩进到与序号圆点同一条竖线上 */
  [data-scope='steps'][data-part='separator'][data-orientation='vertical'] {
    flex: none;
    inline-size: var(--xh-steps-separator-thickness, var(--xh-stroke-thick));
    min-inline-size: var(--xh-steps-separator-thickness, var(--xh-stroke-thick));
    block-size: var(--xh-steps-separator-min-length, var(--xh-space-7));
    /* 圆点半径减去线宽的一半：calc 里的除法要写成乘 0.5，除号在这儿是无效语法 */
    margin-inline-start: calc(
      var(--xh-steps-indicator-size, var(--xh-_steps-indicator-size)) * 0.5
      + var(--xh-steps-trigger-p, var(--xh-control-px-sm))
      - var(--xh-steps-separator-thickness, var(--xh-stroke-thick)) * 0.5
    );
  }

  /* 面板刻意不给 display：连接层用 hidden 收起，UA 的 [hidden]{display:none} 压得住，
     不必再拿内联样式去盖 */
  [data-scope='steps'][data-part='content'] {
    padding-block: var(--xh-steps-content-py, var(--xh-stack-gap-md));
    color: var(--xh-steps-content-fg, var(--xh-fg-default));
  }

  /* 没写内容就由皮肤画兜底对号；作者往部件里塞了自己的图形，这几条即不命中。
     尺寸读圆点自己改接过的 --xh-icon-size：指示符档，随密度换档（见圆点块） */
  [data-scope='steps'][data-part='indicator'][data-state='completed']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-sm));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-sm));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    mask: var(--xh-glyph-mark-check) center / contain no-repeat;
  }

  @media (forced-colors: active) {
    /* 触发器的悬停 / 按下由家族 forced-colors 块涂成 Highlight / HighlightText；标题与说明各自写了颜色，
       这一档里会被换成 CanvasText 压在高亮底上，悬停与按住时一起跟到反色 */
    [data-scope='steps'][data-part='trigger']:not([data-disabled]):is(:hover, :active, [data-pressed])
      :is([data-scope='steps'][data-part='title'], [data-scope='steps'][data-part='description']) {
      color: HighlightText;
    }

    [data-scope='steps'][data-part='trigger']:hover:not([data-disabled])
      [data-scope='steps'][data-part='indicator'][data-state='incomplete'] {
      border-color: Highlight;
    }

    /* 连接线画的是一块纯底色，这一档里底色被统一换成 Canvas，整条进度线消失，
       只剩一排孤立的圆点。走过的那几截换成系统高亮色，其余换成前景色 */
    [data-scope='steps'][data-part='separator'] {
      background: CanvasText;
    }

    [data-scope='steps'][data-part='separator'][data-state='completed'] {
      background: Highlight;
    }
  }

  @media print {
    /* 打印默认丢背景：走过那几步的实心底与里面那枚勾都印不出来，
       当前步与走过的步只剩一模一样的一圈细描边。改用描边的粗细与字重表达同一件事 */
    [data-scope='steps'][data-part='indicator']:is([data-state='current'], [data-state='completed']) {
      border-width: var(--xh-stroke-thick);
    }

    [data-scope='steps'][data-part='title'][data-state='current'] {
      font-weight: var(--xh-font-weight-semibold);
    }
  }
}

/* styles/switch.css */
/* 定义 switch 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='switch'] {
    --xh-switch-skin: 1;
  }

  [data-scope='switch'][data-part='root'] {
    /* 尺寸档只换轨道高度这一个私有槽，其余几何都从它算出来：
       滑块边长 = 轨道高 − 两条留白，轨道宽 = 两倍轨道高 − 两条留白，滑块行程因此正好等于自身边长 */
    --xh-_switch-track-h: var(--xh-switch-track-h-md);
    --xh-_switch-pad: var(--xh-space-0_5);
    --xh-_switch-thumb-size: calc(var(--xh-_switch-track-h) - var(--xh-_switch-pad) * 2);
    --xh-_switch-thumb-press-stretch: var(--xh-switch-thumb-press-stretch, var(--xh-motion-distance-sm));

    /* 选中态轨道色随语气走。没写 data-tone 时 --xh-_tone 没被声明，退回原来的品牌色 */
    --xh-_switch-accent: var(--xh-_tone, var(--xh-bg-brand));
    /* 轨道边界以内描边表达，不吃掉滑块行程；checked / readonly / invalid / disabled 只换这一支色。 */
    --xh-_switch-track-border: var(--xh-switch-border, var(--xh-border-control));
    /* 轨道的面：未选中是 --xh-bg-subtle-active（300）的实体字段控件面；checked / readonly / disabled 换这一支。
       静息已是 300，中性阶梯再无更深一档可换：按下的底缺省仍是轨道静息面（使用者可经 --xh-switch-bg-pressed
       另给），换面的通道由下面滑块的橡皮带拉伸与压平投影承担；选中轨道按下换到语气的 active 档 */
    --xh-_switch-track-bg: var(--xh-switch-bg, var(--xh-bg-subtle-active));
    --xh-_switch-track-bg-pressed: var(--xh-switch-bg-pressed, var(--xh-_switch-track-bg));
    --xh-_switch-fg: var(--xh-switch-fg, var(--xh-fg-default));

    /* 轨道接 Action Control text 档（定尺轨道）：悬停 / 按下 / 禁用面、0.97 缩放与换底、粗指针热区、
       焦点环与过渡由家族配方给，这里只把轨道的私有槽映射到桥接槽。轨道没有实描边（边界以内描边画，不吃行程），
       边位映射 transparent 并把 border 宽度归零；内描边经 shadow 通道各态同一支。悬停不换面（阶梯只给按下） */
    --xh-action-visual-size: var(--xh-_switch-track-h);
    --xh-action-min-inline-size: calc(var(--xh-_switch-track-h) * 2 - var(--xh-_switch-pad) * 2);
    --xh-action-padding-inline: var(--xh-_switch-pad);
    --xh-action-gap: 0;
    --xh-action-radius: var(--xh-switch-radius, var(--xh-shape-pill));
    --xh-action-bg-rest: var(--xh-_switch-track-bg);
    --xh-action-bg-hover: var(--xh-_switch-track-bg);
    --xh-action-bg-pressed: var(--xh-_switch-track-bg-pressed);
    --xh-action-bg-focus-visible: var(--xh-_switch-track-bg);
    --xh-action-bg-disabled: var(--xh-_switch-track-bg);
    --xh-action-border-rest: transparent;
    --xh-action-border-hover: transparent;
    --xh-action-border-pressed: transparent;
    --xh-action-border-focus-visible: transparent;
    --xh-action-border-disabled: transparent;
    --xh-action-fg-rest: var(--xh-_switch-fg);
    --xh-action-fg-hover: var(--xh-_switch-fg);
    --xh-action-fg-pressed: var(--xh-_switch-fg);
    --xh-action-fg-focus-visible: var(--xh-_switch-fg);
    --xh-action-fg-disabled: var(--xh-_switch-fg);
    --xh-action-shadow-rest: inset 0 0 0 var(--xh-stroke-thin) var(--xh-_switch-track-border);
    --xh-action-shadow-hover: inset 0 0 0 var(--xh-stroke-thin) var(--xh-_switch-track-border);
    --xh-action-shadow-pressed: inset 0 0 0 var(--xh-stroke-thin) var(--xh-_switch-track-border);
    --xh-action-shadow-focus-visible: inset 0 0 0 var(--xh-stroke-thin) var(--xh-_switch-track-border);
    --xh-action-shadow-disabled: inset 0 0 0 var(--xh-stroke-thin) var(--xh-_switch-track-border);
    /* 内收环压在实体轨道上，直接取轨道的配对前景：未选中与只读 checked 的中性轨道配 fg-default，
       选中的语气轨道配它的 on 色 */
    --xh-action-ring-color-focus-visible: currentColor;

    /* 滑块贴 inline-start 起步，checked 才位移到另一端；家族的居中排布在轨道上不成立 */
    justify-content: start;
    inline-size: calc(var(--xh-_switch-track-h) * 2 - var(--xh-_switch-pad) * 2);
    padding: var(--xh-_switch-pad);
    border-width: 0;
  }

  [data-scope='switch'][data-part='root'][data-state='checked'] {
    --xh-_switch-track-border: var(--xh-switch-border-checked, var(--xh-_switch-accent));
    --xh-_switch-track-bg: var(--xh-switch-bg-checked, var(--xh-_switch-accent));
    --xh-_switch-track-bg-pressed: var(--xh-switch-bg-checked-pressed, var(--xh-_tone-active, var(--xh-bg-brand-active)));
    --xh-_switch-fg: var(--xh-switch-fg-checked, var(--xh-_tone-on, var(--xh-fg-on-brand)));
  }

  /* 只读：值仍要读得清、也仍会随表单提交，所以不压对比度、也不借禁用那档灰。
     变的是"动不动得了"：指针不摆手型、按下不缩放不换底（家族的按压块由这里的映射钉回静息面），
     选中档的轨道退回未选中那一档的中性底（交互态的底只从语义面派生），
     滑块收掉那层抬起的投影——投影是"这颗按得动"的信号。与文本框只读那一档同口径（压低底色而非置灰）。
     滑块停在哪一端不受影响，值本身仍由位置这条非颜色通道读出。 */
  [data-scope='switch'][data-part='root'][data-readonly]:not([data-disabled]) {
    --xh-_switch-track-bg-pressed: var(--xh-_switch-track-bg);
    --xh-action-scale-pressed: none;
    --xh-action-cursor-rest: default;
    --xh-action-cursor-hover: default;
    --xh-action-cursor-pressed: default;
    --xh-action-cursor-focus-visible: default;
  }

  [data-scope='switch'][data-part='root'][data-readonly][data-state='checked'] {
    --xh-_switch-track-border: var(--xh-switch-border-checked-readonly, var(--xh-border-control));
    --xh-_switch-track-bg: var(--xh-switch-bg-checked-readonly, var(--xh-bg-subtle-active));
    --xh-_switch-fg: var(--xh-switch-fg-checked-readonly, var(--xh-fg-default));
  }

  /* 高对比轴把中性状态的边界提到 strong；实心语气色 checked 仍由自己的色相边界表达。 */
  :where([data-contrast='more']) [data-scope='switch'][data-part='root'][data-state='unchecked'] {
    --xh-_switch-track-border: var(--xh-switch-border, var(--xh-border-strong));
  }

  :where([data-contrast='more'])
    [data-scope='switch'][data-part='root'][data-readonly][data-state='checked'] {
    --xh-_switch-track-border: var(--xh-switch-border-checked-readonly, var(--xh-border-strong));
  }

  /* 校验失败排在状态与对比轴之后：只把轨道内描边换成警示色，不改轨道几何。 */
  [data-scope='switch'][data-part='root'][data-invalid] {
    --xh-_switch-track-border: var(--xh-switch-border-invalid, var(--xh-border-invalid));
  }

  [data-scope='switch'][data-part='root'][data-readonly] [data-scope='switch'][data-part='thumb'] {
    box-shadow: var(--xh-switch-thumb-shadow-readonly, none);
  }

  /* 禁用：不靠 opacity——轨道退回 --xh-bg-subtle 底 + --xh-border-default 内描边，滑块前景置灰；
     选中的禁用轨道同样退回中性面，值由滑块位置读出。面与手型由家族的禁用块按映射给 */
  [data-scope='switch'][data-part='root'][data-disabled] {
    --xh-_switch-track-border: var(--xh-switch-border-disabled, var(--xh-border-default));
    --xh-_switch-track-bg: var(--xh-switch-bg-disabled, var(--xh-bg-subtle));
    --xh-_switch-fg: var(--xh-switch-fg-disabled, var(--xh-fg-disabled));
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里 */
  [data-scope='switch'][data-part='root'][data-size='sm'] {
    --xh-_switch-track-h: var(--xh-switch-track-h-sm);
  }

  [data-scope='switch'][data-part='root'][data-size='lg'] {
    --xh-_switch-track-h: var(--xh-switch-track-h-lg);
  }

  /* 鼠标落点：轨道只有二十来个像素高，命中区靠一枚绝对定位的伪元素往外扩，
     轨道本身一动不动——把轨道加高会改掉整条开关的比例。常态外扩 4px，最矮的 sm 档由 18px 到 26px。 */
  [data-scope='switch'][data-part='root']::after {
    content: '';
    position: absolute;
    inset: calc(-1 * var(--xh-space-1));
  }

  /* 粗指针：家族 text 档的 ::after 把块轴补到 44px、铺满轨道宽并以 -50% 平移居中，行内轴（md 40px）
     这里再补到 44px。起点必须交还家族的 50%：上面那条 inset 负值特指度更高，留着的话盒的左上角
     被钉在 -4px、再被家族的平移拉走半个盒，热区的中心落到轨道左上角外面，右半条开关摸不着 */
  @media (pointer: coarse) {
    [data-scope='switch'][data-part='root']::after {
      inset-block: 50% auto;
      inset-inline: 50% auto;
      min-inline-size: 44px;
    }
  }

  /* 滑块是 raised 抬起面（可拖起部件，逐部件登记）：--xh-bg-surface-raised 底 + --xh-border-default 描边 +
     --xh-elevation-raised 影，无顶光；描边必须在，影只是加成 */
  [data-scope='switch'][data-part='thumb'] {
    position: relative;
    display: grid;
    flex: none;
    place-items: center;
    inline-size: var(--xh-_switch-thumb-size);
    block-size: var(--xh-_switch-thumb-size);
    border: var(--xh-stroke-thin) solid var(--xh-switch-thumb-border, var(--xh-border-default));
    border-radius: var(--xh-switch-thumb-radius, var(--xh-shape-circle));
    background: var(--xh-switch-thumb, var(--xh-bg-surface-raised));
    color: var(--xh-switch-thumb-fg, var(--xh-fg-default));
    box-shadow: var(--xh-switch-thumb-shadow, var(--xh-elevation-raised));
    line-height: 0;
    /* 状态切换只动位移与表面，按压拉伸另走 inline-size；不使用 transition-all。 */
    transition:
      translate var(--xh-motion-duration-nudge) var(--xh-motion-ease-continuous),
      inline-size var(--xh-motion-duration-nudge) var(--xh-motion-ease-continuous),
      box-shadow var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='switch'][data-part='thumb'][data-state='checked'] {
    translate: var(--xh-_switch-thumb-size) 0;
  }

  /* flex 的 inline-start 会随 dir 翻转，物理 translate 也要反向，checked 才始终走到 inline-end。 */
  [dir='rtl'] [data-scope='switch'][data-part='thumb'][data-state='checked'] {
    translate: calc(-1 * var(--xh-_switch-thumb-size)) 0;
  }

  /* Naive 同类的橡皮带回执：按住时向行进方向拉长并压平投影，已选中端同步回退同一段，外缘不越出轨道。 */
  [data-scope='switch'][data-part='root']:not([data-disabled]):not([data-readonly]):not([data-loading]):is(:active, [data-pressed])
    [data-scope='switch'][data-part='thumb'] {
    inline-size: calc(var(--xh-_switch-thumb-size) + var(--xh-_switch-thumb-press-stretch));
    box-shadow: var(--xh-switch-thumb-shadow-pressed, none);
  }

  [data-scope='switch'][data-part='root'][data-state='checked']:not([data-disabled]):not([data-readonly]):not([data-loading]):is(:active, [data-pressed])
    [data-scope='switch'][data-part='thumb'] {
    translate: calc(var(--xh-_switch-thumb-size) - var(--xh-_switch-thumb-press-stretch)) 0;
  }

  [dir='rtl']
    [data-scope='switch'][data-part='root'][data-state='checked']:not([data-disabled]):not([data-readonly]):not([data-loading]):is(:active, [data-pressed])
    [data-scope='switch'][data-part='thumb'] {
    translate: calc(-1 * (var(--xh-_switch-thumb-size) - var(--xh-_switch-thumb-press-stretch))) 0;
  }

  /* 禁用滑块收掉抬起影、前景置灰；描边与底保持，滑块仍是一块读得出位置的实体 */
  [data-scope='switch'][data-part='root'][data-disabled] [data-scope='switch'][data-part='thumb'] {
    color: var(--xh-switch-thumb-fg-disabled, var(--xh-fg-disabled));
    box-shadow: var(--xh-switch-thumb-shadow-disabled, none);
  }

  /* 提交中：指针摆「在途」、滑块里转圈；不是禁用，焦点与对比度都保持。
     家族按压块已排除 data-loading，这里只换各态手型 */
  [data-scope='switch'][data-part='root'][data-loading]:not([data-disabled]) {
    --xh-action-cursor-rest: progress;
    --xh-action-cursor-hover: progress;
    --xh-action-cursor-pressed: progress;
    --xh-action-cursor-focus-visible: progress;
  }

  [data-scope='switch'][data-part='thumb'][data-loading]::after {
    content: '';
    inline-size: 60%;
    block-size: 60%;
    border: var(--xh-stroke-thin) solid transparent;
    border-block-start-color: var(--xh-switch-loading-fg, var(--xh-_switch-accent));
    /* 加载环是等宽高的圆（全部加载环取 circle） */
    border-radius: var(--xh-shape-circle);
    animation: xh-spin var(--xh-switch-loading-duration, var(--xh-spin-duration)) var(--xh-motion-ease-loop) infinite;
  }

  /* —— 带文字的整行：<label> 包住控件与文字，与 checkbox 的标签、checkbox-group 的条目同一副样子 ——
     文字是控件自己的文字，字号随 size 档取 --xh-control-font-*（控件字号随档）；
     行高取正文档，长文字可以自然换行 */
  [data-scope='switch'][data-part='label'] {
    --xh-_switch-label-font-size: var(--xh-control-font-md);

    display: inline-flex;
    align-items: center;
    gap: var(--xh-switch-label-gap, var(--xh-control-gap-md));
    color: var(--xh-switch-label-fg, var(--xh-fg-default));
    font-size: var(--xh-switch-label-font-size, var(--xh-_switch-label-font-size));
    line-height: var(--xh-switch-label-leading, var(--xh-leading-normal));
    cursor: pointer;
  }

  [data-scope='switch'][data-part='label'][data-size='sm'] {
    --xh-_switch-label-font-size: var(--xh-control-font-sm);
  }

  [data-scope='switch'][data-part='label'][data-size='lg'] {
    --xh-_switch-label-font-size: var(--xh-control-font-lg);
  }

  /* 禁用标签色统一 --xh-fg-subtle */
  [data-scope='switch'][data-part='label'][data-disabled] {
    color: var(--xh-switch-label-fg-disabled, var(--xh-fg-subtle));
    cursor: not-allowed;
  }

  /* label 没有独立的 readonly/loading 状态属性，现读里面真实的轨道状态，不复制一套业务状态。 */
  [data-scope='switch'][data-part='label']:has(
    [data-scope='switch'][data-part='root'][data-readonly]:not([data-disabled])
  ) {
    cursor: default;
  }

  [data-scope='switch'][data-part='label']:has(
    [data-scope='switch'][data-part='root'][data-loading]:not([data-disabled])
  ) {
    cursor: progress;
  }

  [data-scope='switch'][data-part='text'] {
    color: inherit;
    user-select: none;
  }

  /* 减少动效：圆环停下并整圈换成虚线，静止的形状仍然读得出"还没好"。
     两条规则是同一件事的两个触发条件：系统偏好与作者打的 data-motion */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='switch'][data-part='root'] {
      --xh-_switch-thumb-press-stretch: var(--xh-motion-distance-sm);
    }

    [data-scope='switch'][data-part='thumb'][data-loading]::after {
      border-style: dotted;
      border-color: var(--xh-switch-loading-fg, var(--xh-_switch-accent));
      animation: none;
    }
  }

  :where([data-motion='reduce']) [data-scope='switch'][data-part='root'] {
    --xh-_switch-thumb-press-stretch: var(--xh-motion-distance-sm);
  }

  :where([data-motion='reduce']) [data-scope='switch'][data-part='thumb'][data-loading]::after {
    border-style: dotted;
    border-color: var(--xh-switch-loading-fg, var(--xh-_switch-accent));
    animation: none;
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='switch'][data-part='root'][hidden],
  [data-scope='switch'][data-part='thumb'][hidden],
  [data-scope='switch'][data-part='label'][hidden] {
    display: none;
  }

  @media (forced-colors: active) {
    /* 系统会丢弃 box-shadow：轨道改用内收 outline，滑块用真实边框保住两层几何。 */
    [data-scope='switch'][data-part='root'] {
      outline: var(--xh-stroke-thin) solid CanvasText;
      outline-offset: calc(-1 * var(--xh-stroke-thin));
    }

    [data-scope='switch'][data-part='root'][data-disabled] {
      outline-color: GrayText;
    }

    /* 按下：家族的 forced-colors 按压块把轨道底换成 Highlight，这里不再另画 */
    [data-scope='switch'][data-part='root'][data-readonly] {
      outline-style: dashed;
    }

    [data-scope='switch'][data-part='root'][data-readonly]:focus-visible {
      outline-width: var(--xh-ring-width);
      outline-style: solid;
      outline-color: Highlight;
      outline-offset: var(--xh-ring-offset);
    }

    [data-scope='switch'][data-part='thumb'] {
      border-color: CanvasText;
      box-shadow: none;
    }
  }

  @media print {
    /* 打印默认丢底色与投影：轨道与滑块都只有一块底，落到纸上整条开关消失，开与关无从读起。
       轨道补一圈实边把形状画出来，滑块补一圈实边把它停在哪一端画出来——
       开与关本来就由滑块的位置读出，位置这条通道在纸上仍然成立。
       轨道走 outline 而不是 border：这条盒子的内衬与滑块行程都从轨道高算出来，
       加一条实边会把行程改掉。 */
    [data-scope='switch'][data-part='root'] {
      outline: var(--xh-stroke-thin) solid currentColor;
      outline-offset: calc(-1 * var(--xh-stroke-thin));
      box-shadow: none;
    }

    [data-scope='switch'][data-part='thumb'] {
      border: var(--xh-stroke-thin) solid currentColor;
      box-shadow: none;
    }

    /* 打印：动画会被定格在任意一帧——转了一半的圈、扫到一半的微光。这里换成静止的表达，
       取值与减弱动效那一档相同。两档各写一块、不并进一条媒体查询列表：减弱动效另有一份
       :where([data-motion='reduce']) 的钩子版本与它成对，打印没有对应的钩子可配，
       并成一条之后这层配对关系在文本上就断了。 */
    [data-scope='switch'][data-part='thumb'][data-loading]::after {
      border-style: dotted;
      border-color: var(--xh-switch-loading-fg, var(--xh-_switch-accent));
      animation: none;
    }
  }
}

/* styles/table.css */
/* 定义 table 样式。 */

@layer xihan.motion {
  /* 加载态自己冒出来，用户没按任何键：一段极轻的呼吸就够，别抢走正在读表的注意力 */
  /* 一次呼吸自带来回：起止两端与中点各写一帧，声明的周期就是一次完整的明暗往返 */
  @keyframes xh-table-loading-pulse {
    0%,
    100% {
      opacity: var(--xh-state-disabled-opacity);
    }

    50% {
      opacity: 1;
    }
  }
}

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='table'] {
    --xh-table-skin: 1;
  }

  /* 表格自己滚动：吸顶表头与横向吸附列都要一个确定的滚动容器才钉得住 */
  [data-scope='table'][data-part='root'] {
    /* 组件内那几档层号只在自己人之间排序：建一个层叠上下文把它们关起来，
       既不让页面上的层号插进来，也不让它们漏出去压住别人 */
    isolation: isolate;

    /* 作者放进单元格、列头与把手里的图标按档取尺，缺省 md；表体行上的由家族随 data-xh-collection-size 下发。
       表格自绘的状态字形（排序方向、勾、半选杠、展开方向）不读这支：它们是指示符，与所在的方盒同走
       --xh-control-indicator-* 一族——五颗把手在自己身上把 --xh-icon-size 改接到方盒的尺，排序钮那支叫 --xh-table-sort-size */
    --xh-icon-size: var(--xh-table-icon-size, var(--xh-glyph-size-md));

    /* 密度档只换这两个私有槽：单元格与列标题从 root 继承前者，字号靠 font-size 本身继承下去，
       换档不必给每个部件各写一条选择器，列宽那套算法也一点不碰 */
    --xh-_table-cell-py: var(--xh-table-cell-py-md);
    --xh-_table-font-size: var(--xh-control-font-md);

    display: flex;
    position: relative;
    flex-direction: column;
    /* 高度上限再由视口收一次：定值比屏幕还高时表格自己滚不动，只能靠页面滚，
       吸顶表头也就钉不住。视口取 dvb：移动端地址栏收放会改变可视高度，dvb 跟着变；
       不认 dvb 的引擎由级联回落到前一条的 vh */
    max-block-size: min(var(--xh-table-max-h, var(--xh-viewport-h-lg)), 100vh);
    max-block-size: min(var(--xh-table-max-h, var(--xh-viewport-h-lg)), 100dvb);
    /* 外框由 [data-variant='outline'] 画；ghost 不画外框，只留行间横线 */
    border: 0;
    background: var(--xh-table-bg, var(--xh-bg-surface));
    color: var(--xh-table-fg, var(--xh-fg-default));
    font-size: var(--xh-table-font-size, var(--xh-_table-font-size));
    /* 两轴一起给：列多了横向溢出是常态，得够得着 */
    overflow: auto;
  }

  [data-scope='table'][data-part='root'][hidden] {
    display: none;
  }

  /* 放进滚动区的表格：滚动交给滚动区的视口，表格自己不再定高、不再滚；
     吸顶表头与吸附列钉的是最近的滚动容器，于是也就钉在视口上。
     自定义元素那条路上 <xh-table> 宿主夹在内容层与表格根之间，两种嵌法都认 */
  [data-scope='scroll-area'][data-part='content'] > [data-scope='table'][data-part='root'],
  [data-scope='scroll-area'][data-part='content'] > xh-table > [data-scope='table'][data-part='root'] {
    max-block-size: none;
    overflow: visible;
  }

  /* 纯容器：焦点落它身上不画环，高亮永远长在行上 */
  [data-scope='table'][data-part='root']:focus-visible {
    outline: none;
  }

  /* —— 密度 —— */
  /* 中间档不写规则，缺省即中档 */
  [data-scope='table'][data-part='root'][data-size='sm'] {
    --xh-icon-size: var(--xh-table-icon-size, var(--xh-glyph-size-sm));
    --xh-_table-cell-py: var(--xh-table-cell-py-sm);
    --xh-_table-font-size: var(--xh-control-font-sm);
  }

  [data-scope='table'][data-part='root'][data-size='lg'] {
    --xh-icon-size: var(--xh-table-icon-size, var(--xh-glyph-size-lg));
    --xh-_table-cell-py: var(--xh-table-cell-py-lg);
    --xh-_table-font-size: var(--xh-control-font-lg);
  }

  [data-scope='table'][data-part='caption'] {
    display: block;
    padding-block: var(--xh-table-caption-py, var(--xh-space-2));
    padding-inline: var(--xh-table-caption-px, var(--xh-space-3));
    color: var(--xh-table-caption-fg, var(--xh-fg-muted));
    font-size: var(--xh-table-caption-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-table-caption-font-weight, var(--xh-text-label-weight));
    text-align: start;
  }

  [data-scope='table'][data-part='caption'][hidden] {
    display: none;
  }

  /* —— 工具条与列设置区 —— */
  /* 两块都摆在 root 之外：root 是 grid 系角色，子节点只能是 row 与 rowgroup。
     工具条只管排布，里头控件的观感归控件自己的皮肤 */
  [data-scope='table'][data-part='toolbar'] {
    /* 尺寸档只换这一个私有槽：控件之间的间距 */
    --xh-_table-toolbar-gap: var(--xh-space-2);

    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--xh-table-toolbar-gap, var(--xh-_table-toolbar-gap));
    padding-block: var(--xh-table-toolbar-py, var(--xh-space-2));
    color: var(--xh-table-toolbar-fg, var(--xh-fg-default));
  }

  [data-scope='table'][data-part='toolbar'][data-size='sm'] {
    --xh-_table-toolbar-gap: var(--xh-space-1);
  }

  [data-scope='table'][data-part='toolbar'][data-size='lg'] {
    --xh-_table-toolbar-gap: var(--xh-space-3);
  }

  [data-scope='table'][data-part='toolbar'][hidden] {
    display: none;
  }

  /* 列设置区：一列一行竖着排。它常摆在浮层里，宽高都交给外面那层容器定 */
  [data-scope='table'][data-part='column-list'] {
    --xh-_table-column-list-gap: var(--xh-space-1);

    display: flex;
    flex-direction: column;
    gap: var(--xh-table-column-list-gap, var(--xh-_table-column-list-gap));
    color: var(--xh-table-column-list-fg, var(--xh-fg-default));
    font-size: var(--xh-table-column-list-font-size, var(--xh-text-secondary-size));
  }

  [data-scope='table'][data-part='column-list'][data-size='sm'] {
    --xh-_table-column-list-gap: var(--xh-space-0_5);
  }

  [data-scope='table'][data-part='column-list'][data-size='lg'] {
    --xh-_table-column-list-gap: var(--xh-space-2);
  }

  [data-scope='table'][data-part='column-list'][hidden] {
    display: none;
  }

  /* 三个区段都是竖着排行的块。min-inline-size: max-content 让它们跟着最宽的一行一起横向溢出，
     否则横向滚动时右半边的行会在容器边缘被切断 */
  [data-scope='table'][data-part='header'],
  [data-scope='table'][data-part='body'],
  [data-scope='table'][data-part='footer'] {
    display: flex;
    flex-direction: column;
    min-inline-size: max-content;
  }

  [data-scope='table'][data-part='header'][hidden],
  [data-scope='table'][data-part='body'][hidden],
  [data-scope='table'][data-part='footer'][hidden] {
    display: none;
  }

  /* 表体是行级 roving 的兜底 Tab 位：落焦不画环，环归行 */
  [data-scope='table'][data-part='body']:focus-visible {
    outline: none;
  }

  /* 表头是淡底承载面：里头的触发器按淡底阶梯走（hover 200 → pressed 300），阶梯由 host 槽向内下发；
     排序钮是 ghost 图标钮，悬停 / 按下面就从这两支 host 槽取 */
  [data-scope='table'][data-part='header'] {
    --xh-action-host-bg-hover: var(--xh-bg-subtle-hover);
    --xh-action-host-bg-pressed: var(--xh-bg-subtle-active);

    border-block-end: var(--xh-stroke-thin) solid var(--xh-table-border, var(--xh-border-default));
    background: var(--xh-table-header-bg, var(--xh-bg-subtle));
  }

  /* 吸顶：滚动容器是 root，表头钉在它的上沿。背景必须是实色——
     透明的表头会让底下滚过的行透出来 */
  [data-scope='table'][data-part='header'][data-fixed] {
    position: sticky;
    z-index: var(--xh-table-sticky-header-layer, var(--xh-layer-sticky));
    inset-block-start: 0;
  }

  [data-scope='table'][data-part='footer'] {
    border-block-start: var(--xh-stroke-thin) solid var(--xh-table-border, var(--xh-border-default));
    background: var(--xh-table-footer-bg, var(--xh-bg-subtle));
    font-weight: var(--xh-table-footer-font-weight, var(--xh-font-weight-medium));
  }

  /* 表体行走 Collection Item 的 page 语境（页内持久集合）：悬停 / 高亮 / 按下面（白底承载 hover 100 →
     pressed 200）与选中面（品牌淡底 + 淡底前景，selected+hover 20% / +pressed 28%）由家族按 aria-selected /
     aria-disabled 给出，标记由行首的勾选把手承担。这里只把公开槽映射到桥接槽，并逐项盖掉家族的行盒几何：
     行是 flex 容器（列宽由单元格的内联尺寸决定，不进家族网格）、不内衬、不圆角、字号与光标随表格本身
     （行不是按钮，selectable 与否都不改光标）。表头 / 脚注行不投影家族，只共用这一副 flex 盒 */
  [data-scope='table'][data-part='row'] {
    /* rest 底要实色：横向吸附的单元格靠 inherit 取它，透明会让滚过的内容透出来 */
    --xh-collection-bg-rest: var(--xh-table-row-bg, var(--xh-bg-surface));
    --xh-collection-bg-hover: var(--xh-table-row-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-keyboard-highlight: var(--xh-table-row-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-pressed: var(--xh-table-row-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-bg-selected: var(--xh-table-row-bg-selected, var(--xh-bg-brand-subtle));
    --xh-collection-fg-rest: currentColor;
    --xh-collection-fg-hover: currentColor;
    --xh-collection-fg-keyboard-highlight: currentColor;
    --xh-collection-fg-pressed: currentColor;
    --xh-collection-fg-selected: var(--xh-table-row-fg-selected, var(--xh-fg-on-brand-subtle));
    --xh-collection-fg-selected-hover: var(--xh-table-row-fg-selected, var(--xh-fg-on-brand-subtle));
    --xh-collection-fg-selected-highlight: var(--xh-table-row-fg-selected, var(--xh-fg-on-brand-subtle));
    --xh-collection-fg-selected-pressed: var(--xh-table-row-fg-selected, var(--xh-fg-on-brand-subtle));
    --xh-collection-font-size: var(--xh-table-font-size, var(--xh-_table-font-size));
    --xh-collection-cursor-rest: var(--xh-table-row-cursor, default);
    --xh-collection-cursor-hover: var(--xh-table-row-cursor, default);
    --xh-collection-cursor-keyboard-highlight: var(--xh-table-row-cursor, default);
    --xh-collection-cursor-pressed: var(--xh-table-row-cursor, default);
    --xh-collection-cursor-selected: var(--xh-table-row-cursor, default);
    --xh-collection-cursor-selected-hover: var(--xh-table-row-cursor, default);
    --xh-collection-cursor-selected-highlight: var(--xh-table-row-cursor, default);
    --xh-collection-cursor-selected-pressed: var(--xh-table-row-cursor, default);
    --xh-collection-cursor-disabled: var(--xh-table-row-cursor, default);
    /* data-highlighted 跟的是连接层记的焦点行（指针点选也会落焦）：只换面，焦点环在 :focus-visible 下再接回 */
    --xh-collection-outline-keyboard-highlight: transparent;
    --xh-collection-outline-selected-highlight: transparent;

    display: flex;
    align-items: stretch;
    padding: 0;
    border-radius: 0;
    /* 文字度量归单元格，行不给行高 */
    line-height: inherit;
  }

  /* 家族给了 display，UA 的 [hidden]{display:none} 已被盖掉 */
  [data-scope='table'][data-part='row'][hidden] {
    display: none;
  }

  /* 表头 / 脚注行透明，露出区段容器的淡底 */
  [data-scope='table'][data-part='header'] > [data-scope='table'][data-part='row'],
  [data-scope='table'][data-part='footer'] > [data-scope='table'][data-part='row'] {
    background: transparent;
  }

  /* 键盘焦点出现时环才接回并立即到位，不压在背景过渡的中间帧上；选中行的淡底不是实心面，环走默认色 */
  [data-scope='table'][data-part='row']:focus-visible:not(:hover) {
    --xh-collection-outline-keyboard-highlight: var(--xh-ring-focus);
    --xh-collection-outline-selected-highlight: var(--xh-ring-focus);

    transition: none;
  }

  /* 行间线画在后一行的上沿，区段里第一个可见行不画：行只负责行与行之间，外边界归 root 与区段容器 */
  [data-scope='table']:is([data-part='header'], [data-part='body'], [data-part='footer']) > :not([hidden]) ~ [data-scope='table']:is([data-part='row'], [data-part='expanded-row']) {
    border-block-start: var(--xh-stroke-thin) solid var(--xh-table-row-border, var(--xh-border-subtle));
  }

  /* 列宽由连接层写进内联 inline-size，因此 flex-basis 取 auto：
     写成 0 会把那条内联值整个盖掉，作者给的列宽就此失效 */
  [data-scope='table'][data-part='column-header'],
  [data-scope='table'][data-part='cell'] {
    display: flex;
    flex: 1 1 auto;
    align-items: center;
    gap: var(--xh-table-cell-gap, var(--xh-control-gap-md));
    min-inline-size: var(--xh-table-cell-min-w, 3rem);
    padding-block: var(--xh-table-cell-py, var(--xh-_table-cell-py));
    padding-inline: var(--xh-table-cell-px, var(--xh-control-px-sm));
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  [data-scope='table'][data-part='column-header'][hidden],
  [data-scope='table'][data-part='cell'][hidden] {
    display: none;
  }

  [data-scope='table'][data-part='column-header'] {
    color: var(--xh-table-column-fg, var(--xh-fg-muted));
    font-weight: var(--xh-table-column-font-weight, var(--xh-text-label-weight));
    text-align: start;
    user-select: none;
  }

  /* 列名是列头里唯一可收窄的一格：flex: 1 吃掉余量、把排序钮 / 列宽把手推到行尾，min-inline-size: 0 让它在
     窄列上收得下去并出省略号。列名不能裸写成文本节点：flex 行里的裸文本是匿名 flex item，min-inline-size 取 auto
     （nowrap 文本的 min-content）缩不下去，96px 的列配一串长列名时定尺的把手连同 auto 外边距一起被挤出列头盒、
     被列头的 overflow: hidden 裁掉——皮肤给不了匿名项 min-inline-size: 0 与 text-overflow，只有真实节点接得住。
     white-space 与行高照旧从列头继承 */
  [data-scope='table'][data-part='column-label'] {
    flex: 1;
    min-inline-size: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* 横向吸附：钉在滚动容器的一侧。背景继承自行，跟着选中/高亮一起变，
     滚过去时不会露出一块与所在行不同色的补丁。
     同侧多列时的偏移由连接层按前面各列的宽度累加好写进 --xh-table-sticky-inset */
  [data-scope='table'][data-part='column-header'][data-frozen],
  [data-scope='table'][data-part='cell'][data-frozen] {
    position: sticky;
    z-index: var(--xh-table-sticky-column-layer, 1);
    background: inherit;
  }

  [data-scope='table'][data-part='column-header'][data-frozen='start'],
  [data-scope='table'][data-part='cell'][data-frozen='start'] {
    inset-inline-start: var(--xh-table-sticky-inset, 0);
  }

  [data-scope='table'][data-part='column-header'][data-frozen='end'],
  [data-scope='table'][data-part='cell'][data-frozen='end'] {
    inset-inline-end: var(--xh-table-sticky-inset, 0);
  }

  /* 表头行本身透明（露出表头底），吸附的列头继承到的就是透明——得自己带表头底，
     否则横向滚动时其它列头从它下面穿过去 */
  [data-scope='table'][data-part='column-header'][data-frozen] {
    background: var(--xh-table-header-bg, var(--xh-bg-subtle));
  }

  /* —— 三个可叠加的外观开关 —— */
  /* 斑马纹：表体偶数行换一层浅底。它是最底下那一档，悬停、选中、落点都要盖得过它，
     所以祖先链与 :nth-of-type 都收进 :where()——特指度落到与基础底同档（0-2-0），
     只靠排在基础底之后压过它一条。照字面写祖先链是 0-8-0，比悬停与选中都高，
     斑马表里偶数行会既不响应悬停也显不出选中 */
  :where([data-scope='table'][data-part='root'][data-striped] [data-scope='table'][data-part='body']) > [data-scope='table'][data-part='row']:where(:nth-of-type(even)) {
    /* 改的是家族的 rest 槽而不是 background 本身：悬停、选中、按下各态由家族在同一支私有槽上解算，
       直接写 background 会把它们全压掉 */
    --xh-collection-bg-rest: var(--xh-table-row-bg-striped, var(--xh-bg-subtle));
  }

  /* 形态：outline 画一圈描边加圆角；ghost 即基础规则，只留行间横线，圆角也随之无意义 */
  [data-scope='table'][data-part='root'][data-variant='outline'] {
    border: var(--xh-stroke-thin) solid var(--xh-table-border, var(--xh-border-default));
    border-radius: var(--xh-table-radius, var(--xh-shape-surface));
    background: var(--xh-table-bg, var(--xh-bg-surface));
  }

  /* 淡底档：不画描边，surface 圆角 + subtle 底 */
  [data-scope='table'][data-part='root'][data-variant='subtle'] {
    border-radius: var(--xh-table-radius, var(--xh-shape-surface));
    background: var(--xh-table-bg, var(--xh-bg-subtle));
  }

  /* 竖分隔线：列与列之间一道细线，末列不画 */
  [data-scope='table'][data-part='root'][data-split] [data-scope='table'][data-part='column-header']:not(:last-child),
  [data-scope='table'][data-part='root'][data-split] [data-scope='table'][data-part='cell']:not(:last-child) {
    border-inline-end: var(--xh-stroke-thin) solid var(--xh-table-row-border, var(--xh-border-subtle));
  }

  [data-scope='table'][data-part='cell'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 五个把手共用一副方形盒子，两种行的文字起点才对得齐；列设置区那颗与表头里的选择框同款，一眼看得出是同一件事。
     五颗都接 Action Control icon 档（定尺方框）：盒型、悬停 / 按下 / 禁用面、0.97 缩放与换底、焦点环与过渡由家族
     配方给，这里只把使用者槽映射到桥接槽；边长仍按 --xh-control-indicator-size 走。三颗勾选框是 outline 形态
     （字段静息形态：透明底 + --xh-border-control 描边），展开箭头与排序钮是 ghost；空框与箭头坐在白底行上，
     按下落 200 档，已勾选的品牌实心面按下派生 active 面；排序钮坐在表头淡底上，阶梯另由 host 槽给（见下） */
  [data-scope='table'][data-part='select-all-trigger'],
  [data-scope='table'][data-part='row-select-trigger'],
  [data-scope='table'][data-part='column-visibility-trigger'],
  [data-scope='table'][data-part='expand-trigger'],
  [data-scope='table'][data-part='sort-trigger'] {
    --xh-_table-trigger-bg: transparent;
    --xh-_table-trigger-bg-pressed: var(--xh-table-trigger-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-_table-trigger-border: transparent;
    /* 方盒边长：四颗把手与盒里的字形都从这一支取 */
    --xh-_table-trigger-size: var(--xh-table-trigger-size, var(--xh-control-indicator-size));

    --xh-action-visual-size: var(--xh-_table-trigger-size);
    --xh-action-min-inline-size: var(--xh-_table-trigger-size);
    --xh-action-bg-rest: var(--xh-_table-trigger-bg);
    --xh-action-bg-hover: var(--xh-_table-trigger-bg);
    --xh-action-bg-pressed: var(--xh-_table-trigger-bg-pressed);
    --xh-action-bg-focus-visible: var(--xh-_table-trigger-bg);
    --xh-action-border-rest: var(--xh-_table-trigger-border);
    --xh-action-border-hover: var(--xh-_table-trigger-border);
    --xh-action-border-pressed: var(--xh-_table-trigger-border);
    --xh-action-border-focus-visible: var(--xh-_table-trigger-border);
  }

  /* 家族 icon 档在粗指针下用 ::after 扩热区到 44px：五颗把手密排在行首与列头里（coarse-target 登记的
     A 档存量），外扩会与相邻把手和上下行叠上；热区不外扩，全选框的 ::after 又是半选那道横杠、
     排序钮的 ::after 是多列排序的序号角标 */
  @media (pointer: coarse) {
    [data-scope='table'][data-part='select-all-trigger']::after,
    [data-scope='table'][data-part='row-select-trigger']::after,
    [data-scope='table'][data-part='column-visibility-trigger']::after,
    [data-scope='table'][data-part='expand-trigger']::after,
    [data-scope='table'][data-part='sort-trigger']::after {
      min-inline-size: 0;
      min-block-size: 0;
    }

    /* 序号角标要保住自己的字盒：家族热区那条把伪元素撑成盒的 100%，这里退回内容尺寸；落点与位移由基础规则给。
       行首起点也要交还：家族热区写了 inset-inline-start: 50%，基础规则只钉了 inset-inline-end: 0，两头都定的
       绝对定位盒被过约束成方盒的一半（16px 盒里只剩 8px），两位数序号会被截断 */
    [data-scope='table'][data-part='sort-trigger'][data-sort-index]::after {
      inline-size: auto;
      block-size: auto;
      inset-inline-start: auto;
    }
  }

  /* 盒里的字形是指示符：这四颗把手各自把 --xh-icon-size 改接到方盒的尺上，兜底字形与作者塞进盒里的
     XhIcon 读同一把尺，root 那支只管作者放进单元格与把手里图标的 --xh-table-icon-size 不流进来。
     三颗勾选框的勾与半选杠按方盒边长 × 0.75，与 Checkbox 的 --xh-_checkbox-glyph、Tree 勾选把手同一比例；
     展开箭头的 chevron 与方盒同边长，同 Tree 的 branch-trigger */
  [data-scope='table'][data-part='select-all-trigger'],
  [data-scope='table'][data-part='row-select-trigger'],
  [data-scope='table'][data-part='column-visibility-trigger'] {
    --xh-icon-size: calc(var(--xh-_table-trigger-size) * 0.75);
  }

  [data-scope='table'][data-part='expand-trigger'] {
    --xh-icon-size: var(--xh-_table-trigger-size);
  }

  /* 排序箭头留一支自己的公开槽，缺省与方盒同边长 */
  [data-scope='table'][data-part='sort-trigger'] {
    --xh-icon-size: var(--xh-table-sort-size, var(--xh-_table-trigger-size));
  }

  /* 勾选方框是嵌在行里的小块：inset 档圆角（身份表登记）；展开箭头与列设置那颗是 control 档 */
  [data-scope='table'][data-part='select-all-trigger'],
  [data-scope='table'][data-part='row-select-trigger'] {
    --xh-action-radius: var(--xh-table-trigger-radius, var(--xh-shape-inset));
  }

  [data-scope='table'][data-part='column-visibility-trigger'],
  [data-scope='table'][data-part='expand-trigger'],
  [data-scope='table'][data-part='sort-trigger'] {
    --xh-action-radius: var(--xh-table-trigger-radius, var(--xh-shape-control));
  }

  [data-scope='table'][data-part='select-all-trigger'][hidden],
  [data-scope='table'][data-part='row-select-trigger'][hidden],
  [data-scope='table'][data-part='column-visibility-trigger'][hidden],
  [data-scope='table'][data-part='expand-trigger'][hidden],
  [data-scope='table'][data-part='sort-trigger'][hidden] {
    display: none;
  }

  /* 三个勾选把手：未选中时只剩一个空框（描边画出的透明底空框），勾选标记靠前景色显隐，
     切换选中不引起行宽抖动 */
  [data-scope='table'][data-part='select-all-trigger'],
  [data-scope='table'][data-part='row-select-trigger'],
  [data-scope='table'][data-part='column-visibility-trigger'] {
    --xh-_table-trigger-bg: transparent;
    --xh-_table-trigger-border: var(--xh-table-trigger-border, var(--xh-border-control));
    --xh-_table-trigger-fg: var(--xh-table-trigger-fg, var(--xh-fg-on-brand));
    --xh-action-fg-rest: var(--xh-_table-trigger-fg);
    --xh-action-fg-hover: var(--xh-_table-trigger-fg);
    --xh-action-fg-pressed: var(--xh-_table-trigger-fg);
    --xh-action-fg-focus-visible: var(--xh-_table-trigger-fg);

    visibility: visible;
  }

  /* 已勾选的方框是品牌实心面，按下在它之上派生 active 面 */
  [data-scope='table'][data-part='select-all-trigger']:is([data-state='checked'], [data-state='indeterminate']),
  [data-scope='table'][data-part='column-visibility-trigger'][data-state='checked'],
  [data-scope='table'][data-part='row-select-trigger'][data-selected] {
    --xh-_table-trigger-bg: var(--xh-table-trigger-bg-checked, var(--xh-bg-brand));
    --xh-_table-trigger-bg-pressed: var(--xh-table-trigger-bg-checked-pressed, var(--xh-bg-brand-active));
    --xh-_table-trigger-border: var(--xh-table-trigger-border-checked, var(--xh-table-trigger-bg-checked, var(--xh-bg-brand)));
  }

  /* 面是实心的，环色与面同族，画在面里就看不出来；环改取面自己的前景色——
     那一族色本来就要在这块面上把字读清楚，与面的对比是按可读性定的。
     置灰那档不在其列：底已换成淡底、勾也藏成透明，currentColor 取到的是透明，环整个消失；
     aria-disabled 的把手仍能落焦，环退回默认那一支 */
  [data-scope='table'][data-part='select-all-trigger']:is([data-state='checked'], [data-state='indeterminate']):not([data-disabled]),
  [data-scope='table'][data-part='column-visibility-trigger'][data-state='checked']:not([data-disabled]),
  [data-scope='table'][data-part='row-select-trigger'][data-selected]:not([data-disabled]) {
    --xh-action-ring-color-focus-visible: currentColor;
  }

  /* 半选档的前景是透明的（勾藏起来、横杠由伪元素画），currentColor 取到的是透明；
     环直接取面配对的那支前景色 */
  [data-scope='table'][data-part='select-all-trigger'][data-state='indeterminate']:not([data-disabled]) {
    --xh-action-ring-color-focus-visible: var(--xh-table-trigger-fg, var(--xh-fg-on-brand));
  }

  /* 未选中时勾不出现，但盒子还在：它是边框画出来的空框 */
  [data-scope='table'][data-part='select-all-trigger'][data-state='unchecked'],
  [data-scope='table'][data-part='column-visibility-trigger'][data-state='unchecked'],
  [data-scope='table'][data-part='row-select-trigger']:not([data-selected]) {
    --xh-_table-trigger-fg: transparent;
  }

  /* 半选换一枚横杠字形盖住勾：aria-checked=mixed 在视觉上也得与"全选"分得开。
     横杠与勾同走字形令牌，作者换掉标记时两态一起换 */
  [data-scope='table'][data-part='select-all-trigger'][data-state='indeterminate'] {
    --xh-_table-trigger-fg: transparent;
  }

  [data-scope='table'][data-part='select-all-trigger'][data-state='indeterminate']::after {
    position: absolute;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    background-color: var(--xh-table-trigger-fg, var(--xh-fg-on-brand));
    content: '';
    -webkit-mask: var(--xh-glyph-mark-minus) center / contain no-repeat;
    mask: var(--xh-glyph-mark-minus) center / contain no-repeat;
  }

  /* 禁用：--xh-border-default 描边 + --xh-bg-subtle 底，勾藏起来；家族的禁用块按映射给 */
  [data-scope='table'][data-part='select-all-trigger'][data-disabled],
  [data-scope='table'][data-part='column-visibility-trigger'][data-disabled],
  [data-scope='table'][data-part='row-select-trigger'][data-disabled] {
    --xh-action-border-disabled: var(--xh-border-default);
    --xh-action-bg-disabled: var(--xh-bg-subtle);
    --xh-action-fg-disabled: transparent;
  }

  /* 行选择把手不占 Tab 位（键盘那一路走 Space），只服务指针 */
  [data-scope='table'][data-part='row-select-trigger']:focus-visible {
    outline: none;
  }

  /* 展开箭头：收起时朝向行首、展开时转向下方，与逻辑书写方向一致 */
  [data-scope='table'][data-part='expand-trigger'] {
    --xh-action-fg-rest: var(--xh-table-expand-fg, var(--xh-fg-subtle));
    --xh-action-fg-hover: var(--xh-table-expand-fg, var(--xh-fg-subtle));
    --xh-action-fg-pressed: var(--xh-table-expand-fg, var(--xh-fg-subtle));
    --xh-action-fg-focus-visible: var(--xh-table-expand-fg, var(--xh-fg-subtle));
    --xh-action-bg-disabled: transparent;
    --xh-action-border-disabled: transparent;

    /* 这条整份改写家族的过渡列表，按压的 scale 与换底要一起带回来 */
    transition:
      rotate var(--xh-motion-duration-nudge) var(--xh-motion-ease-enter-strong),
      background-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      scale var(--xh-motion-duration-release) var(--xh-motion-ease-release);
  }

  [data-scope='table'][data-part='expand-trigger'][data-state='open'] {
    rotate: 90deg;
  }

  /* rtl 下 inline-start 在右侧，箭头因此要反着转 */
  [dir='rtl'] [data-scope='table'][data-part='expand-trigger'] {
    rotate: 180deg;
  }

  [dir='rtl'] [data-scope='table'][data-part='expand-trigger'][data-state='open'] {
    rotate: 90deg;
  }

  [data-scope='table'][data-part='expand-trigger'][data-disabled] {
    --xh-action-fg-disabled: var(--xh-fg-disabled);
  }

  [data-scope='table'][data-part='expand-trigger']:focus-visible {
    outline: none;
  }

  /* 排序钮是列头里独立的定尺图标钮：不包列名，列名留在列头上、它排在列名之后，auto 外边距把它
     推到行尾侧与列宽把手并排。盒型与 0.97 按压由家族 icon 档给（见五颗把手共用块）；坐在表头淡底上，
     悬停 / 按下面按 header 的 host 槽下发的阶梯走（hover 200 → pressed 300），不取白底行那档。
     箭头静息取 subtle 前景，参与排序的列换成默认前景（见字形块） */
  [data-scope='table'][data-part='sort-trigger'] {
    --xh-action-bg-hover: var(--xh-table-sort-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-table-sort-bg-pressed, var(--xh-_action-variant-bg-pressed));
    --xh-action-bg-disabled: transparent;
    --xh-action-border-disabled: transparent;
    --xh-action-fg-rest: var(--xh-table-sort-fg, var(--xh-fg-subtle));
    --xh-action-fg-hover: var(--xh-table-sort-fg, var(--xh-fg-subtle));
    --xh-action-fg-pressed: var(--xh-table-sort-fg, var(--xh-fg-subtle));
    --xh-action-fg-focus-visible: var(--xh-table-sort-fg, var(--xh-fg-subtle));
    --xh-action-fg-disabled: var(--xh-fg-disabled);

    margin-inline-start: auto;
  }

  [data-scope='table'][data-part='sort-trigger'][data-sort] {
    --xh-action-fg-rest: var(--xh-table-sort-fg-active, var(--xh-fg-default));
    --xh-action-fg-hover: var(--xh-table-sort-fg-active, var(--xh-fg-default));
    --xh-action-fg-pressed: var(--xh-table-sort-fg-active, var(--xh-fg-default));
    --xh-action-fg-focus-visible: var(--xh-table-sort-fg-active, var(--xh-fg-default));
  }

  /* 列宽把手贴在表头格的行尾侧。它压在相邻两列的接缝上，因此往外挪半个身位，
     两边各留出一点可抓的余量——贴着边只有一两个像素能按到。 */
  [data-scope='table'][data-part='column-resize-trigger'] {
    display: inline-flex;
    flex: none;
    align-self: stretch;
    inline-size: var(--xh-table-resize-width, var(--xh-space-2));
    /* 推到行尾侧。把手在标记里是表头格的最后一个孩子，auto 外边距把它顶到那一头，
       不必给每个表头格加定位上下文——那条会落到所有既有表格上 */
    margin-inline-start: auto;
    align-items: center;
    justify-content: center;
    cursor: col-resize;
    touch-action: none;
  }

  [data-scope='table'][data-part='column-resize-trigger'][hidden] {
    display: none;
  }

  /* 同一格里前面已有排序钮时，auto 外边距只归第一颗：两条 auto 会把余量平分，排序钮就被推到格中间；
     列宽把手紧贴排序钮之后。藏起来的排序钮不占位，也就不该夺走这条边距 */
  [data-scope='table'][data-part='sort-trigger']:not([hidden]) ~ [data-scope='table'][data-part='column-resize-trigger'] {
    margin-inline-start: 0;
  }

  /* 接缝上那条线。平时借表头的分隔色，按住与聚焦时换成品牌色好认 */
  [data-scope='table'][data-part='column-resize-trigger']::after {
    content: '';
    display: block;
    inline-size: var(--xh-table-resize-line, var(--xh-stroke-thin));
    block-size: var(--xh-table-resize-line-length, 60%);
    border-radius: var(--xh-table-resize-radius, var(--xh-shape-pill));
    background: var(--xh-table-resize-fg, var(--xh-border-default));
  }

  [data-scope='table'][data-part='column-resize-trigger']:hover::after,
  [data-scope='table'][data-part='column-resize-trigger'][data-resizing]::after {
    background: var(--xh-table-resize-fg-active, var(--xh-bg-brand));
    block-size: 100%;
  }

  /* 不可改宽的列不显示把手：留着一条抓不动的线只会让人反复去试 */
  [data-scope='table'][data-part='column-resize-trigger'][data-disabled] {
    display: none;
  }

  /* 列拖拽把手贴在表头格的行首侧，位置由源码顺序定，不写 auto 外边距：
     同一个表头格里的改宽把手已经用 margin-inline-start: auto 把自己顶到行尾侧，
     再添一条 auto，剩余空白会在两条外边距之间平分，两个把手谁都到不了自己那一头。
     待在行首侧还有一层好处：它的位置与这一列有多宽、格里有没有排序把手都无关 */
  [data-scope='table'][data-part='column-drag-trigger'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-table-drag-size, var(--xh-control-indicator-size));
    block-size: var(--xh-table-drag-size, var(--xh-control-indicator-size));
    border-radius: var(--xh-table-trigger-radius, var(--xh-shape-control));
    color: var(--xh-table-drag-fg, var(--xh-fg-subtle));
    cursor: grab;
    /* 关掉这一轴的默认手势：不关的话触屏上手指一划就被系统当成滚动收走 */
    touch-action: none;
  }

  [data-scope='table'][data-part='column-drag-trigger'][hidden] {
    display: none;
  }

  /* 抓手是两条竖线：盒子取边框盒，两侧描边就是那两条线，宽高与线宽都走令牌。
     :empty 守卫让作者塞进来的图标整个顶掉它，而不是两份叠在一起 */
  [data-scope='table'][data-part='column-drag-trigger']:empty::after {
    content: '';
    display: block;
    inline-size: var(--xh-table-drag-grip-w, var(--xh-space-1));
    block-size: var(--xh-table-drag-grip-h, var(--xh-space-2));
    border-inline: var(--xh-stroke-thin) solid currentColor;
  }

  [data-scope='table'][data-part='column-drag-trigger']:not([data-disabled]):hover,
  [data-scope='table'][data-part='column-drag-trigger'][data-dragging] {
    color: var(--xh-table-drag-fg-active, var(--xh-fg-default));
  }

  [data-scope='table'][data-part='column-drag-trigger'][data-dragging] {
    cursor: grabbing;
  }

  /* 不可拖的列照样带一个把手，这里保住它的位置、只把它压到禁用色。
     收成 display: none 是不行的：把手在行首侧，藏掉之后同一行里能拖与不能拖的两列，
     标题起点会错开一格 */
  [data-scope='table'][data-part='column-drag-trigger'][data-disabled] {
    color: var(--xh-table-drag-fg-disabled, var(--xh-fg-disabled));
  }

  /* 落点指示线：拖到哪一列的哪一侧，线就画在那一列的那条边上。列头与表体的格子一起画，
     线贯穿整张表才看得出这一列要落到哪儿。
     定位上下文由这条规则自己给：列头与格子平时都不定位，缺了它伪元素会一路上溯到表格根，
     线就飞到整张表的左上角去。
     冻结列排除在外：它靠 position: sticky 钉住，在这儿改成 relative 会把吸附顶掉；
     而冻结列既不可拖也不做落点，排除掉不会漏画任何一条线 */
  [data-scope='table'][data-part='column-header'][data-drop]:not([data-frozen]),
  [data-scope='table'][data-part='cell'][data-drop]:not([data-frozen]) {
    position: relative;
  }

  /* 线整条画在盒内：列头与格子都收 overflow: hidden，压着边画会被裁掉半条 */
  [data-scope='table'][data-part='column-header'][data-drop]:not([data-frozen])::after,
  [data-scope='table'][data-part='cell'][data-drop]:not([data-frozen])::after {
    content: '';
    position: absolute;
    inset-block: 0;
    inline-size: var(--xh-table-drop-line, var(--xh-stroke-thick));
    background: var(--xh-table-drop-fg, var(--xh-bg-brand));
  }

  /* 落在哪一侧走逻辑属性：rtl 下 before 自己就换到右边去了。
     换成 box-shadow: inset 的话偏移量是物理的，书写方向一反 before 与 after 就调个个儿 */
  [data-scope='table'][data-part='column-header'][data-drop='before']:not([data-frozen])::after,
  [data-scope='table'][data-part='cell'][data-drop='before']:not([data-frozen])::after {
    inset-inline-start: 0;
  }

  [data-scope='table'][data-part='column-header'][data-drop='after']:not([data-frozen])::after,
  [data-scope='table'][data-part='cell'][data-drop='after']:not([data-frozen])::after {
    inset-inline-end: 0;
  }

  /* 被拖的那一列整列压暗，让人看得出正在搬的是它。这里只动 opacity 与 user-select，
     一个 transform 都不写：冻结列是 position: sticky，祖先一有 transform 就掉出吸附。
     位置的事全交给落点指示线，被拖的列自己原地不动 */
  [data-scope='table'][data-part='column-header'][data-dragging],
  [data-scope='table'][data-part='cell'][data-dragging] {
    opacity: var(--xh-table-dragging-opacity, var(--xh-state-dragging-opacity));
    user-select: none;
  }

  /* —— 行拖拽排序 —— */
  /* 整行都是拖动源，光标换成抓手告诉人这一行按得动。
     这条不写 touch-action：整行关掉纵向手势，表格自己就滚不动了；
     触屏那一路交给下面那块专属把手 */
  [data-scope='table'][data-part='row'][data-draggable] {
    cursor: grab;
  }

  /* 行拖拽把手：行里的一小块专属拖动区，按下即拖。触屏靠它起手，
     代价只是这一小块地方不再跟着表格滚。整行起手那一路原样保留，把手是叠加的第二个入口。
     touch-action 不在这儿写：连接层按「拖不动就不写」把它写进了内联 style，
     皮肤再写一遍会盖掉那份条件判断，让不可拖的行也白白让出滚动 */
  [data-scope='table'][data-part='row-drag-trigger'] {
    display: inline-flex;
    flex: none;
    /* 行是 align-items: stretch 的 flex 容器，不自己居中就会被拉成整行高 */
    align-self: center;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-table-row-drag-size, var(--xh-control-indicator-size));
    block-size: var(--xh-table-row-drag-size, var(--xh-control-indicator-size));
    border-radius: var(--xh-table-trigger-radius, var(--xh-shape-control));
    color: var(--xh-table-row-drag-fg, var(--xh-fg-subtle));
    cursor: grab;
  }

  [data-scope='table'][data-part='row-drag-trigger'][hidden] {
    display: none;
  }

  /* 抓手是两条横线：盒子取边框盒，块向两侧的描边就是那两条线，宽高与线宽都走令牌。
     线的走向与能拖的方向垂直——行沿块向上下排，画横线；列沿行向左右排，那边画的是竖线。
     两处都用逻辑属性，书写模式一换，线跟着排列轴自己转过去。
     :empty 守卫让作者塞进来的图标整个顶掉它，而不是两份叠在一起 */
  [data-scope='table'][data-part='row-drag-trigger']:empty::after {
    content: '';
    display: block;
    inline-size: var(--xh-table-row-drag-grip-long, var(--xh-space-2));
    block-size: var(--xh-table-row-drag-grip-short, var(--xh-space-1));
    border-block: var(--xh-stroke-thin) solid currentColor;
  }

  [data-scope='table'][data-part='row-drag-trigger']:not([data-disabled]):hover,
  [data-scope='table'][data-part='row-drag-trigger'][data-dragging] {
    color: var(--xh-table-row-drag-fg-active, var(--xh-fg-default));
  }

  [data-scope='table'][data-part='row-drag-trigger'][data-dragging] {
    cursor: grabbing;
  }

  /* 不可拖的行照样带一个把手，这里保住它的位置、只把它压到禁用色。
     收成 display: none 是不行的：把手占着行首那一格，藏掉之后同一张表里能拖与不能拖的两行，
     首列内容的起点会错开一格 */
  [data-scope='table'][data-part='row-drag-trigger'][data-disabled] {
    color: var(--xh-table-row-drag-fg-disabled, var(--xh-fg-disabled));
  }

  /* 被拖的行整行压暗，与被拖的列同一档透明度。这里只动 opacity、cursor 与 user-select，
     一个 transform 都不写：斑马纹按 nth-of-type 算、行间线按兄弟选择器算，两者认的都是 DOM 位置，
     跟手让位会让它们在拖动全程与行错开。位置的事全交给落点指示线 */
  [data-scope='table'][data-part='row'][data-dragging] {
    opacity: var(--xh-table-dragging-opacity, var(--xh-state-dragging-opacity));
    cursor: grabbing;
    user-select: none;
  }

  /* 详情行与它的数据行是同一块，一起压暗 */
  [data-scope='table'][data-part='expanded-row'][data-dragging] {
    opacity: var(--xh-table-dragging-opacity, var(--xh-state-dragging-opacity));
  }

  /* 落点指示：插到两行之间画一条横线，落进一行里面画一整圈。两档都靠伪元素画，
     定位上下文只给带 data-drop 的那一行：缺了它伪元素会一路上溯到表格根，指示飞到整张表的左上角；
     写到所有行上则是给每一行都多担一份，而落点同一时刻只有一个 */
  [data-scope='table'][data-part='row'][data-drop] {
    position: relative;
  }

  /* 线贯穿整行宽度，并且要压在单元格之上：行是 flex 容器，横向吸附的格子带着层号，
     伪元素不抬到它上面就会被盖住。
     选择器逐值列出前后两档，不写成裸 [data-drop]：换父那一档用的是同一个 ::after，
     裸写会让它先摊上一条线高的横条，再由下面那块整个改写 */
  [data-scope='table'][data-part='row']:is([data-drop='before'], [data-drop='after'])::after {
    content: '';
    position: absolute;
    z-index: calc(var(--xh-table-sticky-column-layer, 1) + 1);
    inset-inline: 0;
    block-size: var(--xh-table-drop-line, var(--xh-stroke-thick));
    background: var(--xh-table-drop-fg, var(--xh-bg-brand));
  }

  /* 线整条画在行内，不压着边。压着边画的话，首行那条上沿线会被表格根的圆角与滚动裁掉半条 */
  [data-scope='table'][data-part='row'][data-drop='before']::after {
    inset-block-start: 0;
  }

  [data-scope='table'][data-part='row'][data-drop='after']::after {
    inset-block-end: 0;
  }

  /* 落进这一行里面（这一行成为新的父）：整行淡底，与上下沿那条横线一眼分得开。
     底色打在行上而不是伪元素上，横向吸附的格子取的是 background: inherit，跟着一起换色，
     横向滚过去时冻结列不会留下一块没上色的补丁。
     祖先写到 root 与 body 两层，是为把特指度抬到 0-8-0：拖动时指针必然停在落点这一行上、
     悬停恒真，而悬停那条是 0-6-0、选中那条是 0-3-0，少写一层祖先这块淡底就会被那两档盖掉。
     禁用的行不接换父落点，:not([data-disabled]) 不会漏画任何一处高亮 */
  [data-scope='table'][data-part='root'] [data-scope='table'][data-part='body'] > [data-scope='table'][data-part='row'][data-drop='inside']:not([data-disabled]) {
    /* 落点不是选中：品牌淡底专属选中，落点面取悬停之上一档的中性面 */
    background: var(--xh-table-drop-inside-bg, var(--xh-bg-subtle-hover));
  }

  /* 换父那一档的描边：与底色分两层画，因为它得压在横向吸附的格子之上——
     格子带着层号，画在行自己的背景层上会被首尾的冻结列盖掉半圈。
     零偏移的内投影四边同时着色、不涉及方向，书写模式一换也不用调；
     整圈画在行内不压着边，与上下沿那条横线同一口径。
     行上不写 transform：冻结列是 position: sticky，祖先一有 transform 就掉出吸附 */
  [data-scope='table'][data-part='row'][data-drop='inside']::after {
    content: '';
    position: absolute;
    z-index: calc(var(--xh-table-sticky-column-layer, 1) + 1);
    inset: 0;
    box-shadow: inset 0 0 0 var(--xh-table-drop-line, var(--xh-stroke-thick))
      var(--xh-table-drop-fg, var(--xh-bg-brand));
    /* 这一层盖满整行，让它不接指针，落点判定照旧落到行与格子上 */
    pointer-events: none;
  }

  /* 活动区域只说给读屏听，不占版面。声明与 shared/visually-hidden.ts 逐条同值。 */
  [data-scope='table'][data-part='live-region'] {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }

  /* 排序方向用箭头字形表出来：aria-sort 只报给读屏，视觉侧也得有对应的东西。
     箭头是指示符：尺寸读钮自己改接过的 --xh-icon-size（--xh-table-sort-size，缺省与方盒同边长），
     与同一表头里的勾选框方盒、列拖拽把手同走 --xh-control-indicator-size，按图标档取的 20px 会比
     16px 的方盒与列头文字都大一圈。:empty 守卫同展开箭头：作者塞了自己的图标就整个顶掉兜底；
     flex: none 是因为 ghost 那圈透明描边仍占位，不钉住的话与盒同边长的箭头会被挤窄一个描边。
     三态各写一遍尺寸：字形门禁逐条规则查兜底盒有没有按 --xh-icon-size 量 */
  [data-scope='table'][data-part='sort-trigger']:empty::before {
    content: '';
    display: inline-block;
    flex: none;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-sort) center / contain no-repeat;
    mask: var(--xh-glyph-mark-sort) center / contain no-repeat;
  }

  [data-scope='table'][data-part='sort-trigger'][data-sort='asc']:empty::before {
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    -webkit-mask: var(--xh-glyph-mark-sort-asc) center / contain no-repeat;
    mask: var(--xh-glyph-mark-sort-asc) center / contain no-repeat;
  }

  [data-scope='table'][data-part='sort-trigger'][data-sort='desc']:empty::before {
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    -webkit-mask: var(--xh-glyph-mark-sort-desc) center / contain no-repeat;
    mask: var(--xh-glyph-mark-sort-desc) center / contain no-repeat;
  }

  /* 多字段排序的优先级角标：链里第几环就显几，只在参与排序时才有 data-sort-index。
     钮是定尺的 16px 方盒，数字排不进盒里：角标压在盒的行尾上角，写法同 Badge 的 top-end——
     定位上下文由家族给（控件本身 position: relative），inset 走逻辑属性，rtl 下 end 自己换到左边 */
  [data-scope='table'][data-part='sort-trigger'][data-sort-index]::after {
    position: absolute;
    inset-block-start: 0;
    inset-inline-end: 0;
    translate: 50% -50%;
    color: var(--xh-table-sort-fg-active, var(--xh-fg-default));
    font-size: var(--xh-text-caption-size);
    line-height: 1;
    content: attr(data-sort-index);
    pointer-events: none;
  }

  /* rtl 下 translate 的行内轴要跟着翻，否则角标会往盒里面跑 */
  [dir='rtl'] [data-scope='table'][data-part='sort-trigger'][data-sort-index]::after {
    translate: -50% -50%;
  }

  [data-scope='table'][data-part='sort-trigger'][data-disabled] {
    cursor: default;
  }

  /* 排不了序的列不画箭头 */
  [data-scope='table'][data-part='sort-trigger'][data-disabled]:empty::before {
    content: none;
  }

  /* 详情行：靠 data-state 收起，不卸载作者节点。内容长在它的单元格里，行本身只画底色 */
  [data-scope='table'][data-part='expanded-row'] {
    display: flex;
    align-items: stretch;
    background: var(--xh-table-detail-bg, var(--xh-bg-subtle));
  }

  /* 详情行里的格子铺满整行，且不按数据格那样截断成一行 */
  [data-scope='table'][data-part='expanded-row'] > [data-scope='table'][data-part='cell'] {
    padding-block: var(--xh-table-detail-py, var(--xh-space-3));
    padding-inline: var(--xh-table-detail-px, var(--xh-space-4));
    overflow: visible;
    white-space: normal;
  }

  /* 收起态的唯一开关：display 会盖掉 hidden 属性的 UA 规则，漏了这条详情行就收不起来。
     作者写的 hidden 与连接层发的 data-state=closed 都收在这里 */
  [data-scope='table'][data-part='expanded-row'][hidden],
  [data-scope='table'][data-part='expanded-row'][data-state='closed'] {
    display: none;
  }

  /* 两个状态节点常挂，只在表体为空时才显形 */
  [data-scope='table'][data-part='empty'],
  [data-scope='table'][data-part='loading'] {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--xh-table-state-gap, var(--xh-space-2));
    min-block-size: var(--xh-table-state-min-h, 8rem);
    padding-block: var(--xh-table-state-py, var(--xh-space-6));
    padding-inline: var(--xh-table-state-px, var(--xh-space-4));
    color: var(--xh-table-state-fg, var(--xh-fg-muted));
    text-align: center;
  }

  [data-scope='table'][data-part='empty'][hidden],
  [data-scope='table'][data-part='loading'][hidden] {
    display: none;
  }

  [data-scope='table'][data-part='loading'] {
    animation: xh-table-loading-pulse var(--xh-table-loading-duration, var(--xh-shimmer-duration))
      var(--xh-motion-ease-sweep) infinite;
  }

  /* 取下一页的按钮：铺满一行摆在表尾——铺满一行的独立动作条目，接 Action Control 的 row 档、
     ghost 形态：宽度由容器给、高度随内容、按下只换面不缩放；盒几何、悬停 / 按下 / 禁用面、
     焦点环与粗指针热区全由家族给，白底承载 hover 100 → pressed 200。
     这里只把使用者槽映射到桥接槽并把文案居中：它是一行里唯一的东西，靠起始缘会像一条没对齐的行 */
  [data-scope='table'][data-part='load-more-trigger'] {
    --xh-action-gap: var(--xh-table-load-more-trigger-gap, var(--xh-space-2));
    --xh-action-padding-block: var(--xh-table-load-more-trigger-py, var(--xh-space-3));
    --xh-action-padding-inline: var(--xh-table-load-more-trigger-px, var(--xh-space-4));
    --xh-action-radius: var(--xh-table-load-more-trigger-radius, var(--xh-shape-control));
    --xh-action-bg-hover: var(--xh-table-load-more-trigger-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-fg-rest: var(--xh-table-load-more-trigger-fg, var(--xh-fg-brand-strong));
    --xh-action-fg-hover: var(--xh-table-load-more-trigger-fg, var(--xh-fg-brand-strong));
    --xh-action-fg-pressed: var(--xh-table-load-more-trigger-fg, var(--xh-fg-brand-strong));
    --xh-action-font-size: var(--xh-table-load-more-trigger-font-size, var(--xh-_table-font-size));

    justify-content: center;
    text-align: center;
    /* row 档允许换行、高度随内容，折行的文案走正文行高 */
    line-height: var(--xh-leading-normal);
  }

  [data-scope='table'][data-part='load-more-trigger'][hidden] {
    display: none;
  }

  /* 减少动效：呼吸停下，加载态只留静止的文案。两条规则是同一件事的两个触发条件：系统偏好与作者打的 data-motion */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='table'][data-part='loading'] {
      animation: none;
    }
  }

  :where([data-motion='reduce']) [data-scope='table'][data-part='loading'] {
    animation: none;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中。
     尺寸读把手自己改接过的 --xh-icon-size：勾是方盒边长 × 0.75、chevron 与方盒同边长（见把手块） */
  [data-scope='table'][data-part='select-all-trigger']:empty::before,
  [data-scope='table'][data-part='column-visibility-trigger']:empty::before,
  [data-scope='table'][data-part='row-select-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    mask: var(--xh-glyph-mark-check) center / contain no-repeat;
  }

  /* flex: none：方盒是 ghost 形态，家族那圈透明描边仍占位，不钉住的话与盒同边长的 chevron 会被挤窄一个描边 */
  [data-scope='table'][data-part='expand-trigger']:empty::before {
    content: '';
    display: inline-block;
    flex: none;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
  }

  @media print {
    /* 打印：动画会被定格在任意一帧——转了一半的圈、扫到一半的微光。这里换成静止的表达，
       取值与减弱动效那一档相同。两档各写一块、不并进一条媒体查询列表：减弱动效另有一份
       :where([data-motion='reduce']) 的钩子版本与它成对，打印没有对应的钩子可配，
       并成一条之后这层配对关系在文本上就断了。 */
    [data-scope='table'][data-part='loading'] {
      animation: none;
    }

    /* 底色被丢掉：选中行那层淡底没了，与别的行一模一样。改画一条内收的实线框——
       用 outline 不用 border：行是横排 flex，加边会把单元格整体往里推，没选中的行不加边，
       同一屏上的列就对不齐了 */
    [data-scope='table'][data-part='row'][data-selected] {
      outline: var(--xh-stroke-thick) solid currentColor;
      outline-offset: calc(-1 * var(--xh-stroke-thick));
    }

    /* 两个勾选框的实心底也被丢掉，配它的浅色勾落在白纸上就整个不见了——
       勾与框都换成正文色，勾没勾在纸上才分得出 */
    [data-scope='table'][data-part='select-all-trigger']:is([data-state='checked'], [data-state='indeterminate']),
    [data-scope='table'][data-part='row-select-trigger'][data-selected] {
      border-color: var(--xh-fg-default);
    }

    [data-scope='table'][data-part='select-all-trigger'][data-state='checked'],
    [data-scope='table'][data-part='row-select-trigger'][data-selected] {
      color: var(--xh-fg-default);
    }

    /* 半选那枚横杠是伪元素画的，字色照旧留成透明把勾压住，只换横杠自己的颜色 */
    [data-scope='table'][data-part='select-all-trigger'][data-state='indeterminate']::after {
      background-color: var(--xh-fg-default);
    }
  }
}

/* styles/tabs.css */
/* 定义 tabs 样式。 */

/* line 档的页签归 Collection Item 导航当前（nav 语境）：面、字色、字重、光标与按压时间线由家族配方按
   家族角色（data-xh-collection-item / -size / -context）给，本皮肤只映射桥接槽；card / segment 档不归族，面与字仍写在本皮肤。
   line 档的 2px 指示线由本皮肤画：标签带里放了 indicator 部件就由部件滑动，没放则选中标签自画一条静态线 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='tabs'] {
    --xh-tabs-skin: 1;
  }

  [data-scope='tabs'][data-part='root'] {
    /* 尺寸档只换这三个私有槽，标签从 root 继承它们，换档不必给每个部件各写一条选择器 */
    --xh-_tabs-trigger-h: var(--xh-control-h-md);
    --xh-_tabs-trigger-px: var(--xh-control-px-md);
    --xh-_tabs-trigger-font-size: var(--xh-control-font-md);

    /* 缺省是 line 变体：透明标签带，选中项由文字与底部指示条表达。Web Components 升级前还没有
       data-variant，这组几何基础值也必须画成相同结果，避免定义完成时闪换样式；line 档的面与字色由家族
       按升级后写入的家族角色给，升级前那一帧只有几何没有面色（与 side-nav / menu 同）。
       悬停与按下的面按承载面分档：line 档经家族走白底承载 hover 100 → pressed 200；card 坐在
       画布上 hover 100 → pressed 200；segment 坐在淡底轨道里 hover 200 → pressed 300。card / segment 的
       六支面槽只在各自形态块里赋值，line 档不消费它们 */
    --xh-_tabs-list-gap: var(--xh-space-0);
    --xh-_tabs-list-bg: transparent;
    --xh-_tabs-list-p: var(--xh-space-0);
    --xh-_tabs-list-radius: 0;
    --xh-_tabs-list-border-width: 0;
    --xh-_tabs-trigger-border-width: 0;
    --xh-_tabs-trigger-border: transparent;
    --xh-_tabs-trigger-radius: var(--xh-shape-control);

    /* 语气落在选中态：指示条与选中标签的文字。
       没写 data-tone 时 --xh-_tone 一族没被声明，两个槽都退回原来的取色 */
    --xh-_tabs-accent: var(--xh-_tone, var(--xh-bg-brand));
    --xh-_tabs-accent-text: var(--xh-_tone-fg, var(--xh-fg-brand-strong));

    /* 翻页钮的盖底：标签带放不下时它浮在两端，挪到它底下的那截标签要被盖住。line / card 档的标签带是透明的，
       盖底取 surface；坐在别的面上（画布、淡底面板）时由使用者槽换成所在的面。segment 档取轨道的淡底 */
    --xh-_tabs-scroll-trigger-bg: var(--xh-bg-surface);

    display: flex;
    flex-direction: column;
    gap: var(--xh-tabs-gap, var(--xh-stack-gap-md));
    /* 排在一行弹性 / 网格容器里时也让得开：不写这条，根的最小宽是整条标签带的自然宽，
       外层再窄它也不缩，标签带永远"放得下"、翻页钮永远不露面，整行反倒被顶出去 */
    min-inline-size: 0;
  }

  /* 纵向：list 与 panel 并排 */
  [data-scope='tabs'][data-part='root'][data-orientation='vertical'] {
    flex-direction: row;
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里 */
  [data-scope='tabs'][data-part='root'][data-size='sm'] {
    --xh-_tabs-trigger-h: var(--xh-control-h-sm);
    --xh-_tabs-trigger-px: var(--xh-control-px-sm);
    --xh-_tabs-trigger-font-size: var(--xh-control-font-sm);
  }

  [data-scope='tabs'][data-part='root'][data-size='lg'] {
    --xh-_tabs-trigger-h: var(--xh-control-h-lg);
    --xh-_tabs-trigger-px: var(--xh-control-px-lg);
    --xh-_tabs-trigger-font-size: var(--xh-control-font-lg);
  }

  /* —— 变体 —— */
  /* 主变体的显式写法，与缺省视觉一致：透明标签带与底部基线，选中项由文字和滑动指示条强调。 */
  [data-scope='tabs'][data-part='root'][data-variant='line'] {
    --xh-_tabs-list-gap: var(--xh-space-0);
    --xh-_tabs-list-bg: transparent;
    --xh-_tabs-list-p: var(--xh-space-0);
    --xh-_tabs-list-radius: 0;
    --xh-_tabs-list-border-width: 0;
    --xh-_tabs-trigger-border-width: 0;
    --xh-_tabs-trigger-border: transparent;
    --xh-_tabs-trigger-radius: var(--xh-shape-control);
  }

  /* 卡片式：基线收掉，选中的那张标签自己成为一张有描边有底的卡片，顶边一条指示条。
     标签坐在画布上，悬停 100 → 按下 200（白底承载） */
  [data-scope='tabs'][data-part='root'][data-variant='card'] {
    --xh-_tabs-list-gap: var(--xh-control-gap-md);
    --xh-_tabs-list-bg: transparent;
    --xh-_tabs-list-p: var(--xh-space-0);
    --xh-_tabs-list-radius: 0;
    --xh-_tabs-list-border-width: 0;
    --xh-_tabs-trigger-border-width: var(--xh-stroke-thin);
    --xh-_tabs-trigger-radius: var(--xh-shape-control);
    --xh-_tabs-trigger-bg-hover: var(--xh-bg-subtle);
    --xh-_tabs-trigger-bg-pressed: var(--xh-bg-subtle-hover);
    --xh-_tabs-trigger-bg-active: var(--xh-_tone-subtle, var(--xh-bg-surface));
    --xh-_tabs-trigger-bg-active-hover: var(--xh-_tone-subtle-hover, var(--xh-bg-surface));
    --xh-_tabs-trigger-border-active: var(--xh-_tone-border, var(--xh-border-default));
    --xh-_tabs-trigger-shadow-active: inset 0 var(--xh-stroke-thick) 0 0 var(--xh-_tabs-accent);
    /* 选中文字不换品牌色：卡片面与顶边条已经表达选中 */
    --xh-_tabs-accent-text: var(--xh-_tone-fg, var(--xh-fg-default));
  }

  /* 分段式（有滑块开关）：淡底轨道承载一块白色抬起的选中面，选中文字保持默认字色。
     未选中标签坐在淡底轨道里，悬停 200 → 按下 300；选中面自己不再叠悬停 / 按下态。
     选中面的三件（surface-raised 底、border-default 描边、raised 影）写在下面标签自己的规则里 */
  [data-scope='tabs'][data-part='root'][data-variant='segment'] {
    --xh-_tabs-list-gap: var(--xh-space-0_5);
    --xh-_tabs-list-bg: var(--xh-bg-subtle);
    --xh-_tabs-list-p: var(--xh-space-1);
    --xh-_tabs-list-radius: var(--xh-shape-surface);
    --xh-_tabs-list-border-width: 0;
    --xh-_tabs-trigger-border-width: var(--xh-stroke-thin);
    --xh-_tabs-trigger-border: transparent;
    --xh-_tabs-trigger-radius: var(--xh-shape-control);
    --xh-_tabs-trigger-bg-hover: var(--xh-bg-subtle-hover);
    --xh-_tabs-trigger-bg-pressed: var(--xh-bg-subtle-active);
    --xh-_tabs-trigger-bg-active: var(--xh-_tone-subtle, var(--xh-bg-surface-raised));
    --xh-_tabs-trigger-bg-active-hover: var(--xh-_tone-subtle, var(--xh-bg-surface-raised));
    --xh-_tabs-trigger-border-active: var(--xh-_tone-border, var(--xh-border-default));
    --xh-_tabs-accent-text: var(--xh-_tone-fg, var(--xh-fg-default));
    --xh-_tabs-scroll-trigger-bg: var(--xh-bg-subtle);
  }

  /* 一行排不下不折行：标签整条沿主轴位移露出被裁掉的那截，两端的翻页钮与滚轮驱动，位移量由机器写在
     --xh-_tabs-scroll 上（下面孩子那条规则读它）。只裁主轴（overflow-x: clip），交叉轴仍是 visible：
     标签的焦点环画在盒内不受影响，粗指针下往块轴两侧外扩的命中区、segment 档抬起面的投影也都不被裁。
     不做成滚动容器（overflow: hidden 会把两个轴一起裁，粗指针那圈外扩就没了；原生滚动条也不该露在标签带下） */
  [data-scope='tabs'][data-part='list'] {
    /* 位移量：放得下时 0，放不下时由机器写成内联样式盖过这条 */
    --xh-_tabs-scroll: 0;

    position: relative;
    /* 关起标签带内的层序：segment 档的标签抬一层压在滑动的抬起面上、翻页钮再抬一层压在标签上，两个层号都不漏到外面去 */
    isolation: isolate;
    display: flex;
    flex-wrap: nowrap;
    overflow: clip visible;
    align-items: center;
    gap: var(--xh-tabs-list-gap, var(--xh-_tabs-list-gap));
    padding: var(--xh-tabs-list-p, var(--xh-_tabs-list-p));
    border-block-end: var(--xh-_tabs-list-border-width) solid var(--xh-tabs-list-border, var(--xh-border-default));
    border-radius: var(--xh-tabs-list-radius, var(--xh-_tabs-list-radius));
    background: var(--xh-tabs-list-bg, var(--xh-_tabs-list-bg));
  }

  /* 竖排：主轴换成块向，裁块向、行向放开。竖排的标签带高随内容长，只有使用者限了高才会放不下 */
  [data-scope='tabs'][data-part='list'][aria-orientation='vertical'] {
    flex-direction: column;
    align-items: stretch;
    overflow: visible clip;
    border-block-end: 0;
    border-inline-end: var(--xh-_tabs-list-border-width) solid var(--xh-tabs-list-border, var(--xh-border-default));
  }

  /* 排在标签带里的孩子——标签、分隔线、指示条——整体沿主轴位移；两端的翻页钮贴边不动，不在这条里。
     位移量是机器逐帧补间写进来的（屏内的像素级推移走 continuous 档，与指示条同一档），这里不接过渡：
     各部件各有自己的过渡清单（line 档的标签归家族），往每一份里都加一条 translate 会把家族与皮肤耦在一起 */
  [data-scope='tabs'][data-part='list']
    > :not([data-scope='tabs'][data-part='prev-trigger'], [data-scope='tabs'][data-part='next-trigger']) {
    translate: var(--xh-_tabs-scroll) 0;
  }

  [data-scope='tabs'][data-part='list'][aria-orientation='vertical']
    > :not([data-scope='tabs'][data-part='prev-trigger'], [data-scope='tabs'][data-part='next-trigger']) {
    translate: 0 var(--xh-_tabs-scroll);
  }

  /* segment 档的标签带是一块淡底面：--xh-bg-subtle 底 + 一圈透明占位边 + 无影（三选一）。
     它同时是标签的淡底承载面，向内下发 hover 200 → pressed 300 的承载阶梯；
     只写在标签带上不写在 root 上：内容面板里的按钮坐在画布上，不该跟着抬一档 */
  [data-scope='tabs'][data-part='root'][data-variant='segment'] [data-scope='tabs'][data-part='list'] {
    --xh-action-host-bg-hover: var(--xh-bg-subtle-hover);
    --xh-action-host-bg-pressed: var(--xh-bg-subtle-active);

    border: var(--xh-stroke-thin) solid var(--xh-tabs-list-border, transparent);
  }

  /* 标签的几何三档共用；面、字色、字重与光标不在这里写：line 档由家族按投影的家族角色给，
     card / segment 档写在下面带形态限定的规则里。本条 (0,2,0) 压过家族基础块 (0,1,0)，写了面就会盖掉家族的换面 */
  [data-scope='tabs'][data-part='trigger'] {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--xh-tabs-trigger-gap, var(--xh-control-gap-md));
    block-size: var(--xh-tabs-trigger-h, var(--xh-_tabs-trigger-h));
    padding-inline: var(--xh-tabs-trigger-px, var(--xh-_tabs-trigger-px));
    border: var(--xh-_tabs-trigger-border-width) solid var(--xh-tabs-trigger-border, var(--xh-_tabs-trigger-border));
    border-radius: var(--xh-tabs-trigger-radius, var(--xh-_tabs-trigger-radius));
    font-size: var(--xh-tabs-trigger-font-size, var(--xh-_tabs-trigger-font-size));
    line-height: var(--xh-leading-none);
    white-space: nowrap;
    /* 家族基础块给条目写了 min-inline-size: 0（菜单条目要能收窄给文字省略号用）；标签不省略号，
       segment 档又按 flex: 1 1 0 等分带宽，下限归零后排不下的标签会被压到文字之下。
       收回 auto：下限按文字算，排不下的那截由标签带位移露出 */
    min-inline-size: auto;
  }

  /* line 档（导航当前页）：把公开槽映射到 Collection Item 的 nav 语境桥接槽。静息 muted / regular，
     悬停 100 + default 字，按下 200 只换面；当前页透明面 + 品牌深字（随语气的 --xh-_tabs-accent-text）+
     medium，叠悬停 100。2px 指示线不由家族按条目画：放了 indicator 部件是 list 上的滑动部件，
     没放则由下面的静态线规则画在选中标签自己身上。高度由 block-size 定，块向内边距归零 */
  [data-scope='tabs'][data-part='root'][data-variant='line'] [data-scope='tabs'][data-part='trigger'] {
    --xh-collection-block-padding: var(--xh-space-0);
    --xh-collection-bg-rest: var(--xh-tabs-trigger-bg, transparent);
    --xh-collection-fg-rest: var(--xh-tabs-trigger-fg, var(--xh-fg-muted));
    --xh-collection-font-weight-rest: var(--xh-tabs-trigger-font-weight, var(--xh-font-weight-regular));
    --xh-collection-bg-hover: var(--xh-tabs-trigger-bg-hover, var(--xh-bg-subtle));
    --xh-collection-fg-hover: var(--xh-tabs-trigger-fg-hover, var(--xh-fg-default));
    --xh-collection-bg-pressed: var(--xh-tabs-trigger-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-fg-pressed: var(--xh-tabs-trigger-fg-pressed, var(--xh-fg-default));
    --xh-collection-bg-current: var(--xh-tabs-trigger-bg-active, transparent);
    --xh-collection-bg-current-hover: var(--xh-tabs-trigger-bg-active-hover, var(--xh-bg-subtle));
    --xh-collection-fg-current: var(--xh-tabs-trigger-fg-active, var(--xh-_tabs-accent-text));
    --xh-collection-font-weight-current: var(--xh-tabs-trigger-font-weight-active, var(--xh-font-weight-medium));
  }

  /* card / segment 档不归族：面、字色、字重、光标与过渡写在标签自己身上 */
  [data-scope='tabs'][data-part='root']:is([data-variant='card'], [data-variant='segment'])
    [data-scope='tabs'][data-part='trigger'] {
    background: var(--xh-tabs-trigger-bg, transparent);
    color: var(--xh-tabs-trigger-fg, var(--xh-fg-muted));
    font-weight: var(--xh-tabs-trigger-font-weight, var(--xh-text-label-weight));
    cursor: pointer;
    /* 标签是铺开的一段（Tabs trigger 归行级），按下只换面不缩放：transition 里没有 scale */
    transition:
      color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      background-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      box-shadow var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 横排标签的宽随文字走，不把标签带等分铺满一行：line 与 card 档是一排并列的页签，
     每一枚只占自己的字宽加内衬，标签带右侧留白；放不下的那截由标签带位移露出 */
  [data-scope='tabs'][data-part='root'][data-orientation='horizontal']
    [data-scope='tabs'][data-part='trigger'] {
    flex: 0 0 auto;
  }

  /* segment 档是一条轨道里的格子（与 Segmented 同构）：格子按可用宽度等分 */
  [data-scope='tabs'][data-part='root'][data-orientation='horizontal'][data-variant='segment']
    [data-scope='tabs'][data-part='trigger'] {
    flex: 1 1 0;
  }

  /* 禁用项带的是 aria-disabled 而非原生 disabled，:hover 照样命中；
     不挡掉的话置灰的那一页悬停仍会换底，看着还能点。
     悬停面按形态分档：card 100、segment 200（见各形态块上的私有槽）；line 档由家族给 */
  [data-scope='tabs'][data-part='root']:is([data-variant='card'], [data-variant='segment'])
    [data-scope='tabs'][data-part='trigger']:not([data-disabled]):hover {
    background: var(--xh-tabs-trigger-bg-hover, var(--xh-_tabs-trigger-bg-hover));
  }

  /* 按下去要有回应：card / segment 档的未选中标签换到按下面（card 200、segment 300），几何不动。
     选中标签不叠按下面：card 的卡片面与 segment 的抬起面本身就是选中身份（有滑块开关无叠加态） */
  [data-scope='tabs'][data-part='root']:is([data-variant='card'], [data-variant='segment'])
    [data-scope='tabs'][data-part='trigger']:not([data-disabled]):not([data-state='active']):is(:active, [data-pressed]) {
    background: var(--xh-tabs-trigger-bg-pressed, var(--xh-_tabs-trigger-bg-pressed));
    transition-duration: var(--xh-motion-duration-press);
    transition-timing-function: var(--xh-motion-ease-press);
  }

  /* card / segment 档的选中标签：字色收回默认（--xh-_tabs-accent-text 在两档都落 fg-default），
     由卡片面 / 抬起面表达当前；line 档的当前页由家族按 data-current 给 */
  [data-scope='tabs'][data-part='root']:is([data-variant='card'], [data-variant='segment'])
    [data-scope='tabs'][data-part='trigger'][data-state='active'] {
    border-color: var(--xh-tabs-trigger-border-active, var(--xh-_tabs-trigger-border-active));
    background: var(--xh-tabs-trigger-bg-active, var(--xh-_tabs-trigger-bg-active));
    color: var(--xh-tabs-trigger-fg-active, var(--xh-_tabs-accent-text));
    box-shadow: var(--xh-tabs-trigger-shadow-active, var(--xh-_tabs-trigger-shadow-active));
    font-weight: var(--xh-tabs-trigger-font-weight-active, var(--xh-font-weight-medium));
  }

  /* segment 档的选中标签就是那块白色抬起的滑块面（有滑块开关）：surface-raised 底 +
     border-default 描边 + raised 影三件写在标签自己身上。标签带里放了 indicator 部件时，
     这块面搬到部件上跟着滑（见下面的 indicator 规则），标签自己透空、只留字 */
  [data-scope='tabs'][data-part='root'][data-variant='segment']
    [data-scope='tabs'][data-part='trigger'][data-state='active'] {
    border-color: var(--xh-tabs-trigger-border-active, var(--xh-_tone-border, var(--xh-border-default)));
    background: var(--xh-tabs-trigger-bg-active, var(--xh-_tone-subtle, var(--xh-bg-surface-raised)));
    box-shadow: var(--xh-tabs-trigger-shadow-active, var(--xh-elevation-raised));
  }

  /* segment 档的标签压在抬起面之上：面是绝对定位的部件，写在标签之后也不许盖住字。
     层号只在标签带的层叠上下文里比大小（list 上有 isolation: isolate） */
  [data-scope='tabs'][data-part='root'][data-variant='segment'] [data-scope='tabs'][data-part='trigger'] {
    z-index: 1;
  }

  [data-scope='tabs'][data-part='root'][data-variant='segment']
    [data-scope='tabs'][data-part='list']:has([data-scope='tabs'][data-part='indicator']:not([hidden]))
    [data-scope='tabs'][data-part='trigger'][data-state='active'] {
    border-color: transparent;
    background: transparent;
    box-shadow: none;
  }

  /* 选中项被悬停：常态 :hover 那条带着禁用守卫，特指度高过上面那条选中档，
     不单列一条的话指针一压到选中项上，形态档的选中底就被轻档吃掉 */
  [data-scope='tabs'][data-part='root']:is([data-variant='card'], [data-variant='segment'])
    [data-scope='tabs'][data-part='trigger']:not([data-disabled])[data-state='active']:hover {
    background: var(--xh-tabs-trigger-bg-active-hover, var(--xh-_tabs-trigger-bg-active-hover));
  }

  /* line 档的禁用字色由家族按 aria-disabled 给 */
  [data-scope='tabs'][data-part='root']:is([data-variant='card'], [data-variant='segment'])
    [data-scope='tabs'][data-part='trigger'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  [data-scope='tabs'][data-part='content'] {
    padding-block: var(--xh-tabs-content-py, var(--xh-stack-gap-md));
    color: var(--xh-tabs-content-fg, var(--xh-fg-default));
  }

  /* —— 标签拖拽换位 —— */
  /* 整张标签都是拖动源，光标换成抓手告诉人这张标签按得动。
     这条不写 touch-action：整张标签关掉手势，标签带自己就滚不动了；
     触屏那一路交给下面那块专属把手 */
  [data-scope='tabs'][data-part='trigger'][data-draggable] {
    cursor: grab;
  }

  /* 标签拖拽把手：标签里的一小块专属拖动区，按下即拖。触屏靠它起手，
     代价只是这一小块地方不再跟着标签带滚。整张标签起手那一路原样保留，把手是叠加的第二个入口。
     touch-action 不在这儿写：连接层按「拖不动就不写」把它写进了内联 style，
     皮肤再写一遍会盖掉那份条件判断，让不可拖的标签也白白让出滚动 */
  [data-scope='tabs'][data-part='tab-drag-trigger'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-tabs-drag-size, var(--xh-control-indicator-size));
    block-size: var(--xh-tabs-drag-size, var(--xh-control-indicator-size));
    border-radius: var(--xh-tabs-drag-radius, var(--xh-shape-control));
    color: var(--xh-tabs-drag-fg, var(--xh-fg-subtle));
    cursor: grab;
  }

  /* 抓手是两条与排列轴垂直的线：盒子取边框盒，两侧描边就是那两条线，宽高与线宽都走令牌。
     标签带横排时标签左右排开，画的是两条竖线；竖排那一档在下面换成横线。
     基础这一档同时兜住 root 上没写方向的情形。
     :empty 守卫让作者塞进来的图标整个顶掉它，而不是两份叠在一起 */
  [data-scope='tabs'][data-part='tab-drag-trigger']:empty::after {
    content: '';
    display: block;
    inline-size: var(--xh-tabs-drag-grip-short, var(--xh-space-1));
    block-size: var(--xh-tabs-drag-grip-long, var(--xh-space-2));
    border-inline: var(--xh-stroke-thin) solid currentColor;
  }

  /* 竖排的标签上下排开，两条线跟着转九十度：长短对调，描边换到块向两侧，
     行向那两条得显式清零，否则四边都留着描边，抓手成了一个方框 */
  [data-scope='tabs'][data-part='root'][data-orientation='vertical']
    [data-scope='tabs'][data-part='tab-drag-trigger']:empty::after {
    inline-size: var(--xh-tabs-drag-grip-long, var(--xh-space-2));
    block-size: var(--xh-tabs-drag-grip-short, var(--xh-space-1));
    border-inline: 0;
    border-block: var(--xh-stroke-thin) solid currentColor;
  }

  [data-scope='tabs'][data-part='tab-drag-trigger']:not([data-disabled]):hover,
  [data-scope='tabs'][data-part='tab-drag-trigger'][data-dragging] {
    color: var(--xh-tabs-drag-fg-active, var(--xh-fg-default));
  }

  [data-scope='tabs'][data-part='tab-drag-trigger'][data-dragging] {
    cursor: grabbing;
  }

  /* 不可拖的标签照样带一个把手，这里保住它的位置、只把它压到禁用色。
     收成 display: none 是不行的：把手占着标签内的头一格，藏掉之后同一条标签带里
     能拖与不能拖的两张标签，文字起点会错开一格 */
  [data-scope='tabs'][data-part='tab-drag-trigger'][data-disabled] {
    color: var(--xh-tabs-drag-fg-disabled, var(--xh-fg-disabled));
  }

  /* 被拖的那张标签压暗，让人看得出正在搬的是它。这里只动 opacity、cursor 与 user-select，
     一个 transform 都不写：标签原地不动，要落到哪儿全交给落点指示 */
  [data-scope='tabs'][data-part='trigger'][data-dragging] {
    opacity: var(--xh-tabs-dragging-opacity, var(--xh-state-dragging-opacity));
    cursor: grabbing;
    user-select: none;
  }

  /* 落点指示线：插到哪张标签的哪一侧，线就画在那张标签的那条边上。
     定位上下文不必在这儿再给：标签的基础规则里已经是 position: relative。
     线走 ::after：选中态那道指示画的是 box-shadow（card 档的顶边条、segment 档的浮起），
     line 档放了部件时指示条在 list 上，没放时选中标签的静态线也占 ::after——它带 :not([data-drop]) 守卫，
     拖动落到当前页上时让给落点线。标签自身不收 overflow，线不会被裁掉；仍整条画在盒内不压着边 */
  [data-scope='tabs'][data-part='trigger']:is([data-drop='before'], [data-drop='after'])::after {
    content: '';
    position: absolute;
    background: var(--xh-tabs-drop-fg, var(--xh-bg-brand));
  }

  /* 线的方向跟着标签带的排法换：方向写在 root 的 data-orientation 上，从根往下选。
     横排的标签左右排开，线是一条竖的，贯穿标签的块向、贴在行向的前后沿 */
  [data-scope='tabs'][data-part='root'][data-orientation='horizontal']
    [data-scope='tabs'][data-part='trigger']:is([data-drop='before'], [data-drop='after'])::after {
    inset-block: 0;
    inline-size: var(--xh-tabs-drop-line, var(--xh-stroke-thick));
  }

  /* 落在前沿还是后沿走逻辑属性：rtl 下 before 自己就换到右边去了。
     换成 box-shadow 的偏移量则是物理的，写不出逻辑方向 */
  [data-scope='tabs'][data-part='root'][data-orientation='horizontal']
    [data-scope='tabs'][data-part='trigger'][data-drop='before']::after {
    inset-inline-start: 0;
  }

  [data-scope='tabs'][data-part='root'][data-orientation='horizontal']
    [data-scope='tabs'][data-part='trigger'][data-drop='after']::after {
    inset-inline-end: 0;
  }

  /* 竖排的标签上下排开，线是一条横的，贯穿标签的行向、贴在块向的前后沿 */
  [data-scope='tabs'][data-part='root'][data-orientation='vertical']
    [data-scope='tabs'][data-part='trigger']:is([data-drop='before'], [data-drop='after'])::after {
    inset-inline: 0;
    block-size: var(--xh-tabs-drop-line, var(--xh-stroke-thick));
  }

  /* 块向同样走逻辑属性，跟着书写模式走 */
  [data-scope='tabs'][data-part='root'][data-orientation='vertical']
    [data-scope='tabs'][data-part='trigger'][data-drop='before']::after {
    inset-block-start: 0;
  }

  [data-scope='tabs'][data-part='root'][data-orientation='vertical']
    [data-scope='tabs'][data-part='trigger'][data-drop='after']::after {
    inset-block-end: 0;
  }

  /* 活动区域只说给读屏听，不占版面。声明与 shared/visually-hidden.ts 逐条同值。 */
  [data-scope='tabs'][data-part='live-region'] {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }

  /* 选中标签的四个几何量由机器量好写成私有槽 --xh-_tabs-indicator-x / -y / -w / -h（它量得到，样式表量不到）；
     line 档只取主轴那两支画一条线，这里管交叉轴的贴边与粗细，以及长什么样。它是可选部件——不渲染它时，
     line 档由选中标签自画一条同规格的静态线（见下），card 档由卡片面表达，segment 档由标签自己的抬起面表达 */
  [data-scope='tabs'][data-part='indicator'] {
    /* 还没量到时的落点，量到即被机器写的私有槽盖过 */
    --xh-_tabs-indicator-x: 0;
    --xh-_tabs-indicator-y: 0;
    --xh-_tabs-indicator-w: 0;
    --xh-_tabs-indicator-h: 0;

    /* 摆在行首，落点交给 transform（只走合成），长度跟着标签宽走。标签带挪动时整条孩子
       共用的 translate 叠在它之上，两者互不覆盖，过渡也只挂在 transform 上 */
    position: absolute;
    inset-block-end: 0;
    inset-inline-start: 0;
    inline-size: var(--xh-_tabs-indicator-w);
    block-size: var(--xh-tabs-indicator-thickness, var(--xh-stroke-thick));
    border-radius: var(--xh-tabs-indicator-radius, var(--xh-shape-pill));
    background: var(--xh-tabs-indicator-color, var(--xh-_tabs-accent));
    transform: translate(var(--xh-_tabs-indicator-x), 0);
    transition:
      transform var(--xh-motion-duration-move) var(--xh-motion-ease-continuous),
      inline-size var(--xh-motion-duration-move) var(--xh-motion-ease-continuous);
  }

  /* transform 只认物理方向：RTL 下行首在右边，起始缘量出的距离往左推 */
  [data-scope='tabs'][data-part='indicator']:dir(rtl) {
    transform: translate(calc(-1 * var(--xh-_tabs-indicator-x)), 0);
  }

  /* 卡片变体已经由卡片面表达状态，不再叠一条下划线。 */
  [data-scope='tabs'][data-part='indicator'][data-variant='card'] {
    display: none;
  }

  /* segment 档（有滑块开关）：部件就是那块白色抬起的滑块面，四个几何量都取、整块跟着滑——
     surface-raised 底 + border-default 描边 + raised 影三件与 Segmented 的滑块同一套；
     描边吃进盒里（border-box），面与标签仍是同一块矩形。标签压在它上面，点击一律交给标签。
     用连续档而不是进场那条：滑块是被推过去的，起步就该有速度；四个几何量同时走，标签宽不等时才不会先变形再挪位 */
  [data-scope='tabs'][data-part='indicator'][data-variant='segment'] {
    inset-block-end: auto;
    inset-inline-end: auto;
    inset-inline-start: 0;
    inset-block-start: 0;
    inline-size: var(--xh-_tabs-indicator-w);
    block-size: var(--xh-_tabs-indicator-h);
    box-sizing: border-box;
    border: var(--xh-stroke-thin) solid var(--xh-tabs-trigger-border-active, var(--xh-_tone-border, var(--xh-border-default)));
    border-radius: var(--xh-tabs-trigger-radius, var(--xh-_tabs-trigger-radius));
    background: var(--xh-tabs-trigger-bg-active, var(--xh-_tone-subtle, var(--xh-bg-surface-raised)));
    box-shadow: var(--xh-tabs-trigger-shadow-active, var(--xh-elevation-raised));
    pointer-events: none;
    transform: translate(var(--xh-_tabs-indicator-x), var(--xh-_tabs-indicator-y));
    transition:
      transform var(--xh-motion-duration-move) var(--xh-motion-ease-continuous),
      inline-size var(--xh-motion-duration-move) var(--xh-motion-ease-continuous),
      block-size var(--xh-motion-duration-move) var(--xh-motion-ease-continuous);
  }

  [data-scope='tabs'][data-part='indicator'][data-variant='segment']:dir(rtl) {
    transform: translate(calc(-1 * var(--xh-_tabs-indicator-x)), var(--xh-_tabs-indicator-y));
  }

  /* line 档没放 indicator 部件时，选中标签自画一条静态指示线（导航当前页）：
     横向缺省也要像纵向示例那样有一条选中线，作者不必为了这条线多放一个部件。
     线画在选中标签的 ::after 上，以标签盒为定位参照（基础规则里已是 position: relative），
     厚度 / 颜色 / 圆角与 indicator 部件读同一组槽与缺省——作者改一处，部件与静态线一起改。
     不做动画：它随 data-current 在标签间跳，滑动只有部件做得到。
     标签带里一旦放了 indicator 部件，这条线就收起、位置交给部件滑动，不重复画两条：
     由标签带按 :has 探一次，把私有槽写成 none，线的 content 读它；标签自己不必再各带一段 :has。
     ::after 同时是换位落点线的载体：拖动中标签带着 data-drop 时让给落点线，松手即回来 */
  [data-scope='tabs'][data-part='list']:has([data-scope='tabs'][data-part='indicator']) {
    --xh-_tabs-static-line: none;
  }

  [data-scope='tabs'][data-part='root'][data-variant='line']
    [data-scope='tabs'][data-part='trigger'][data-current]:not([data-drop])::after {
    content: var(--xh-_tabs-static-line, '');
    position: absolute;
    pointer-events: none;
    border-radius: var(--xh-tabs-indicator-radius, var(--xh-shape-pill));
    background: var(--xh-tabs-indicator-color, var(--xh-_tabs-accent));
  }

  /* 横排：贴标签的块向末端（底边），横贯整枚标签 */
  [data-scope='tabs'][data-part='root'][data-variant='line'][data-orientation='horizontal']
    [data-scope='tabs'][data-part='trigger'][data-current]:not([data-drop])::after {
    inset-block-end: 0;
    inset-inline: 0;
    block-size: var(--xh-tabs-indicator-thickness, var(--xh-stroke-thick));
  }

  /* 竖排：贴标签的行向末端（与 indicator 部件同一侧，rtl 随逻辑属性镜像），纵贯整枚标签 */
  [data-scope='tabs'][data-part='root'][data-variant='line'][data-orientation='vertical']
    [data-scope='tabs'][data-part='trigger'][data-current]:not([data-drop])::after {
    inset-inline-end: 0;
    inset-block: 0;
    inline-size: var(--xh-tabs-indicator-thickness, var(--xh-stroke-thick));
  }

  /* 竖排 line 档：滑条从基线挪到结束缘那条轨道上，主轴换成块向，取 -y / -h 两支 */
  [data-scope='tabs'][data-part='indicator'][data-orientation='vertical']:not([data-variant='segment']) {
    inset-block-end: auto;
    inset-inline-start: auto;
    inset-inline-end: 0;
    inset-block-start: 0;
    block-size: var(--xh-_tabs-indicator-h);
    inline-size: var(--xh-tabs-indicator-thickness, var(--xh-stroke-thick));
    transform: translate(0, var(--xh-_tabs-indicator-y));
    transition:
      transform var(--xh-motion-duration-move) var(--xh-motion-ease-continuous),
      block-size var(--xh-motion-duration-move) var(--xh-motion-ease-continuous);
  }

  /* 标签之间的细线：横排时是一条竖线，竖排时躺平 */
  [data-scope='tabs'][data-part='separator'] {
    flex: none;
    align-self: center;
    inline-size: var(--xh-tabs-separator-thickness, var(--xh-stroke-thin));
    block-size: var(--xh-tabs-separator-size, var(--xh-space-4));
    border-radius: var(--xh-tabs-separator-radius, var(--xh-shape-pill));
    background: var(--xh-tabs-separator-color, var(--xh-border-default));
  }

  [data-scope='tabs'][data-part='separator'][data-orientation='vertical'] {
    align-self: stretch;
    inline-size: auto;
    block-size: var(--xh-tabs-separator-thickness, var(--xh-stroke-thin));
  }

  /* —— 两端翻页钮 —— */
  /* 标签带放不下时浮在两端的单图标钮，接 Action Control icon 档 ghost 面（连接层投影 profile / variant / size）：
     盒取标签同高的正方形，四态面、0.97 按压与粗指针 44px 命中区由家族配方给。绝对定位贴在标签带两端、
     不随标签位移；挪到它底下的那截标签由静息底盖住（透明 ghost 面盖不住字，静息 / 焦点 / 禁用三列换成盖底槽，
     悬停与按下仍走 ghost 的阶梯——line / card 在白底上 100 → 200，segment 由轨道下发 200 → 300） */
  [data-scope='tabs'][data-part='prev-trigger'],
  [data-scope='tabs'][data-part='next-trigger'] {
    --xh-action-visual-size: var(--xh-tabs-trigger-h, var(--xh-_tabs-trigger-h));
    --xh-action-bg-rest: var(--xh-tabs-scroll-trigger-bg, var(--xh-_tabs-scroll-trigger-bg));
    --xh-action-bg-focus-visible: var(--xh-tabs-scroll-trigger-bg, var(--xh-_tabs-scroll-trigger-bg));
    --xh-action-bg-disabled: var(--xh-tabs-scroll-trigger-bg, var(--xh-_tabs-scroll-trigger-bg));
    --xh-action-fg-rest: var(--xh-tabs-scroll-trigger-fg, var(--xh-fg-muted));
    /* 作者塞进来的图标跟着 icon 档走，与皮肤画的兜底字形同一把尺 */
    --xh-icon-size: var(--xh-tabs-scroll-icon-size, var(--xh-_action-profile-glyph-size));

    position: absolute;
    z-index: 2;
    inset-block-start: 50%;
    translate: 0 -50%;
  }

  /* 贴在标签带内衬盒的两端：segment 档的轨道留着一圈内衬，钮坐在内衬里、不压到轨道边上 */
  [data-scope='tabs'][data-part='prev-trigger'] {
    inset-inline-start: var(--xh-tabs-list-p, var(--xh-_tabs-list-p));
  }

  [data-scope='tabs'][data-part='next-trigger'] {
    inset-inline-end: var(--xh-tabs-list-p, var(--xh-_tabs-list-p));
  }

  /* 竖排：两只钮躺平成横贯标签带的一条，各贴块向的首尾 */
  [data-scope='tabs'][data-part='prev-trigger'][data-orientation='vertical'],
  [data-scope='tabs'][data-part='next-trigger'][data-orientation='vertical'] {
    inline-size: auto;
    inset-inline: var(--xh-tabs-list-p, var(--xh-_tabs-list-p));
    inset-block-start: auto;
    translate: 0 0;
  }

  [data-scope='tabs'][data-part='prev-trigger'][data-orientation='vertical'] {
    inset-block-start: var(--xh-tabs-list-p, var(--xh-_tabs-list-p));
  }

  [data-scope='tabs'][data-part='next-trigger'][data-orientation='vertical'] {
    inset-block-end: var(--xh-tabs-list-p, var(--xh-_tabs-list-p));
  }

  /* 挪到头的那一侧是原生 disabled（不可聚焦），连接层同时给 data-disabled：到头即收起——
     它浮在标签上，留着会盖住边上那枚完整露出的标签；配方 disabled 列给的面被 opacity 0 盖住，两者不冲突 */
  [data-scope='tabs'][data-part='prev-trigger'][data-disabled],
  [data-scope='tabs'][data-part='next-trigger'][data-disabled] {
    opacity: 0;
    pointer-events: none;
  }

  /* 没写内容就由皮肤画兜底字形：横排一左一右的 chevron，竖排一上一下；作者塞了自己的图形这几条即不命中 */
  [data-scope='tabs'][data-part='prev-trigger']:empty::before,
  [data-scope='tabs'][data-part='next-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-left) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-left) center / contain no-repeat;
  }

  [data-scope='tabs'][data-part='next-trigger']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-chevron-right);
    mask-image: var(--xh-glyph-mark-chevron-right);
  }

  /* rtl 下标签序从右往左走，箭头跟着指向行进方向 */
  [dir='rtl'] [data-scope='tabs'][data-part='prev-trigger']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-chevron-right);
    mask-image: var(--xh-glyph-mark-chevron-right);
  }

  [dir='rtl'] [data-scope='tabs'][data-part='next-trigger']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-chevron-left);
    mask-image: var(--xh-glyph-mark-chevron-left);
  }

  [data-scope='tabs'][data-part='prev-trigger'][data-orientation='vertical']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-chevron-up);
    mask-image: var(--xh-glyph-mark-chevron-up);
  }

  [data-scope='tabs'][data-part='next-trigger'][data-orientation='vertical']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-chevron-down);
    mask-image: var(--xh-glyph-mark-chevron-down);
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='tabs'][data-part='root'][hidden],
  [data-scope='tabs'][data-part='list'][hidden],
  [data-scope='tabs'][data-part='trigger'][hidden],
  [data-scope='tabs'][data-part='indicator'][hidden],
  [data-scope='tabs'][data-part='separator'][hidden],
  [data-scope='tabs'][data-part='prev-trigger'][hidden],
  [data-scope='tabs'][data-part='next-trigger'][hidden],
  [data-scope='tabs'][data-part='tab-drag-trigger'][hidden] {
    display: none;
  }

  /* 手指落点：命中区由伪元素向块轴两侧外扩，标签的盒与标签带的高度一点不动——
     加高标签会把基线与滑条一起顶下去。
     只扩块轴：标签在行内轴上首尾相接（segment 档只留半格缝），往两侧扩会与相邻标签的命中区叠上。
     取 8px 是按最矮的 sm 档算的（28 + 8 × 2 = 44），md 与 lg 档更宽裕。
     用 ::before：::after 已经被换位时的落点线占着 */
  @media (pointer: coarse) {
    [data-scope='tabs'][data-part='trigger']::before {
      content: '';
      position: absolute;
      inset-block: -8px;
      inset-inline: 0;
    }
  }

  @media (forced-colors: active) {
    /* 滑条与分隔线画的都是一块纯底色，这一档里底色被统一换成 Canvas，两者整根消失。
       滑条换成系统高亮色、分隔线换成前景色画回来 */
    [data-scope='tabs'][data-part='indicator'] {
      background: Highlight;
    }

    /* 没放部件时选中标签自画的那条静态线同样是一块纯底色，同一档换成系统高亮色 */
    [data-scope='tabs'][data-part='root'][data-variant='line']
      [data-scope='tabs'][data-part='trigger'][data-current]:not([data-drop])::after {
      background: Highlight;
    }

    [data-scope='tabs'][data-part='separator'] {
      background: CanvasText;
    }

    /* 按下：常态靠底色深一档表出，这一档里底色被统一换掉；按住那一下用系统高亮反色画回来。
       line 档的按下反色由家族的 forced-colors 段给 */
    [data-scope='tabs'][data-part='root']:is([data-variant='card'], [data-variant='segment'])
      [data-scope='tabs'][data-part='trigger']:not([data-disabled]):not([data-state='active']):is(:active, [data-pressed]) {
      background: Highlight;
      color: HighlightText;
    }
  }

  @media print {
    /* 打印默认丢背景与投影：三档形态表达选中的三条通道（选中底、card 档的顶边条、
       segment 档的浮起）在纸上一条都不剩，只有一条比别人深一点的字色。
       改用下划线与字重表达同一件事，两者都不改盒子的高度 */
    [data-scope='tabs'][data-part='trigger'][data-state='active'] {
      font-weight: var(--xh-font-weight-semibold);
      text-decoration: underline;
    }

    /* 纸上翻不了页，两只钮不上纸 */
    [data-scope='tabs'][data-part='prev-trigger'],
    [data-scope='tabs'][data-part='next-trigger'] {
      display: none;
    }
  }
}

/* styles/tag-group.css */
/* 定义 tag group 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='tag-group'] {
    --xh-tag-group-skin: 1;
  }

  [data-scope='tag-group'][data-part='root'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-tag-group-gap, var(--xh-space-2));
  }

  [data-scope='tag-group'][data-part='root'][hidden] {
    display: none;
  }

  [data-scope='tag-group'][data-part='label'] {
    color: var(--xh-tag-group-label-fg, var(--xh-fg-muted));
    font-size: var(--xh-tag-group-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-tag-group-label-font-weight, var(--xh-text-label-weight));
    line-height: var(--xh-leading-none);
  }

  [data-scope='tag-group'][data-part='label'][data-disabled] {
    color: var(--xh-fg-subtle);
  }

  /* 一排标签横着排、放不下就换行：标签宽度由文字决定，硬撑一行会把整块版面挤破 */
  [data-scope='tag-group'][data-part='list'] {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--xh-tag-group-list-gap, var(--xh-space-1_5));
  }

  [data-scope='tag-group'][data-part='list'][hidden] {
    display: none;
  }

  /* 竖排时一枚一行，标签各自贴左，不跟着行宽拉长 */
  [data-scope='tag-group'][data-part='list'][data-orientation='vertical'] {
    flex-direction: column;
    align-items: flex-start;
    flex-wrap: nowrap;
  }

  /* 焦点在组外时容器自己进 Tab 序列兜底，落焦不画环：高亮永远长在标签上 */
  [data-scope='tag-group'][data-part='list']:focus-visible {
    outline: none;
  }

  /* 一枚标签就是 tag 的 root（data-scope="tag"）：形态、语气、尺寸、置灰、截断、摘除钮的样子全归 tag.css。
     这里只管它在集合里的那几件事：可点、锚点、选中、只读。
     标签这时是拿焦点的那个节点，按下与松手之间要有回应；选中与锚点的过渡也挂在这一层 */
  [data-scope='tag-group'][data-part='list'] > [data-scope='tag'][data-part='root'] {
    user-select: none;
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      scale var(--xh-motion-duration-release) var(--xh-motion-ease-release);
  }

  /* 参与选中的标签才是点击目标，只是标记的那些不给手势暗示 */
  [data-scope='tag-group'][data-part='list'] > [data-scope='tag'][data-part='root'][data-selectable] {
    cursor: pointer;
  }

  /* 按下去要有回应：可选的芯片是一颗定尺的离散控件，整枚轻微下压并同时换底
     （白底承载 hover 100 → pressed 200），松手即弹回。置灰的不压；
     指针 :active 与 Headless 投影的 data-pressed 看见同一副按压面 */
  [data-scope='tag-group'][data-part='list']
    > [data-scope='tag'][data-part='root'][data-selectable]:not([data-disabled]):not([data-variant='solid']):is(:active, [data-pressed]) {
    scale: var(--xh-motion-scale-press);
    background: var(--xh-tag-group-item-bg-pressed, var(--xh-bg-subtle-hover));
    transition-duration: var(--xh-motion-duration-press);
    transition-timing-function: var(--xh-motion-ease-press);
  }

  /* 写了语气的淡底标签静息是 12% 语气淡底（tag.css），悬停 / 按下沿同一条语气曲线走 20% / 28%，
     不跳回中性阶梯把语气丢掉；与 tag.css 同样带 [data-tone] 限定，语气槽沿继承流下来不算 */
  [data-scope='tag-group'][data-part='list']
    > [data-scope='tag'][data-part='root'][data-selectable][data-tone]:not([data-disabled]):not([data-variant='solid']):is(:active, [data-pressed]) {
    background: var(--xh-tag-group-item-bg-pressed, var(--xh-_tone-subtle-active, var(--xh-bg-subtle-hover)));
  }

  /* 实心档的面本身就是那族色，按下往同一族的 active 档走，字仍是实心底上配对的前景。
     语气那条与 tag.css 同样带 [data-tone] 限定：语气槽沿继承流下来，没写语气的实心标签落在带
     data-tone 的组里，静息面与字仍是品牌那族，按下若读祖先的 --xh-_tone-active 就会跳成另一族 */
  [data-scope='tag-group'][data-part='list']
    > [data-scope='tag'][data-part='root'][data-selectable][data-variant='solid']:not([data-disabled]):is(:active, [data-pressed]) {
    scale: var(--xh-motion-scale-press);
    background: var(--xh-tag-group-item-bg-pressed-solid, var(--xh-bg-brand-active));
    transition-duration: var(--xh-motion-duration-press);
    transition-timing-function: var(--xh-motion-ease-press);
  }

  [data-scope='tag-group'][data-part='list']
    > [data-scope='tag'][data-part='root'][data-selectable][data-variant='solid'][data-tone]:not([data-disabled]):is(:active, [data-pressed]) {
    background: var(--xh-tag-group-item-bg-pressed-solid, var(--xh-_tone-active, var(--xh-bg-brand-active)));
  }

  /* 悬停与键盘锚点共用白底承载的 hover 档（hover 100 → pressed 200）：
     data-highlighted 跟的是连接层记的焦点标签，与选中互相独立。
     实心标签不进这里：它的字是实心底上配对的那支前景色，换成灰底就读不出来了；
     实心档在这两档里面不换，回执落在按压缩放与聚焦环上 */
  [data-scope='tag-group'][data-part='list']
    > [data-scope='tag'][data-part='root']:not([data-disabled]):not([data-variant='solid']):is(:hover, [data-highlighted]) {
    background: var(--xh-tag-group-item-bg-hover, var(--xh-bg-subtle));
  }

  [data-scope='tag-group'][data-part='list']
    > [data-scope='tag'][data-part='root'][data-tone]:not([data-disabled]):not([data-variant='solid']):is(:hover, [data-highlighted]) {
    background: var(--xh-tag-group-item-bg-hover, var(--xh-_tone-subtle-hover, var(--xh-bg-subtle)));
  }

  /* 只读整组都改不动，但不是禁用：颜色照常，只把「可点」这个暗示收回来。
     排掉禁用项是因为这条选择器权重高过 pointer 层那条，不排就会把 not-allowed 覆盖回 default */
  [data-scope='tag-group'][data-part='root'][data-readonly]
    [data-scope='tag-group'][data-part='list']
    > [data-scope='tag'][data-part='root']:not([data-disabled]) {
    cursor: default;
  }

  /* —— 选中 —— */
  /* 与树选择同一种读法：选中的标签面、字与描边都不换，悬停 / 锚点 / 按下沿用未选中的那条阶梯，
     只在文字后亮一枚对号（见下面 item-indicator 那几块） */

  /* 标签里那一格：文字与摘除钮排在一条线上。它是 tag 根与 tag 的 label / close-trigger 之间的一层，
     间距照抄所在标签的那一档，有它与没它标签长得一样 */
  [data-scope='tag-group'][data-part='cell'] {
    display: inline-flex;
    align-items: center;
    /* 弹性子项默认最小尺寸是内容尺寸，不归零则长文本把标签撑破、省略号轮不上 */
    min-inline-size: 0;
    gap: inherit;
  }

  [data-scope='tag-group'][data-part='cell'][hidden] {
    display: none;
  }

  /* 选中标记：跟在文字后面的一枚对号，与摘除钮的叉同一把随文尺（标签是纯行内文字组件）；
     作者写在格里哪儿都排到文字与作者内容之后、摘除钮之前。
     作者塞进来的图标读同一支 --xh-icon-size。连接层没选中时给 hidden，UA 的 display:none 被上面的 display 盖住，
     这里压回去 */
  [data-scope='tag-group'][data-part='item-indicator'] {
    --xh-icon-size: var(--xh-tag-group-item-indicator-size, var(--xh-glyph-size-text));

    display: inline-flex;
    flex: none;
    order: 1;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    /* 与树选择的行尾对号同色：标了语气的组取语气字色，没写语气取品牌前景 */
    color: var(--xh-tag-group-item-indicator-fg, var(--xh-_tone-fg, var(--xh-fg-brand)));
  }

  [data-scope='tag-group'][data-part='item-indicator'][hidden] {
    display: none;
  }

  /* 实心标签的面本身就是那族色，品牌 / 语气字色压在上面读不出来：对号取面配对的那支前景色 */
  [data-scope='tag'][data-part='root'][data-variant='solid'] [data-scope='tag-group'][data-part='item-indicator'] {
    color: var(--xh-tag-group-item-indicator-fg, currentColor);
  }

  /* 置灰的标签里对号跟着字一起退成置灰色 */
  [data-scope='tag-group'][data-part='item-indicator'][data-disabled] {
    color: inherit;
  }

  /* 摘除钮是操作，排在对号之后、格的最末 */
  [data-scope='tag-group'][data-part='cell'] > [data-scope='tag'][data-part='close-trigger'] {
    order: 2;
  }

  /* 没写内容就由皮肤画兜底对号；作者往部件里塞了自己的图形，这条即不命中 */
  [data-scope='tag-group'][data-part='item-indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    mask: var(--xh-glyph-mark-check) center / contain no-repeat;
  }

  @media (forced-colors: active) {
    /* 选中只由对号表达：遮罩出来的那块底色用系统高亮色画，按下时标签整枚反成 Highlight，对号换成反白 */
    [data-scope='tag-group'][data-part='item-indicator']:empty::before {
      background-color: Highlight;
    }

    [data-scope='tag-group'][data-part='list']
      > [data-scope='tag'][data-part='root'][data-selectable]:not([data-disabled]):not([data-variant='solid']):is(:active, [data-pressed])
      [data-scope='tag-group'][data-part='item-indicator']:empty::before {
      background-color: HighlightText;
    }

    /* 按下：常态靠底色深一档表出，这一档里底色被统一换成 Canvas；按住那一下用系统高亮反色画回来 */
    [data-scope='tag-group'][data-part='list']
      > [data-scope='tag'][data-part='root'][data-selectable]:not([data-disabled]):not([data-variant='solid']):is(:active, [data-pressed]) {
      background: Highlight;
      color: HighlightText;
    }
  }

  @media print {
    /* 打印默认丢底色，而对号是遮罩出来的一块底色：标签本就不换面，丢了它选中在纸上就没了踪影 */
    [data-scope='tag-group'][data-part='item-indicator'] {
      print-color-adjust: exact;
    }
  }
}

/* styles/tags-input.css */
/* TagsInput 独立皮肤同时传递引入字段视觉盒与字段内动作；full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='tags-input'] {
    --xh-tags-input-skin: 1;
  }

  /* root 只负责纵向堆叠：标题一行、控件一行。可见的那个"框"长在 control 上，
     因为标签、输入框、清空按钮都在它里面，边框必须把三者一起圈住。
     组件层只把既有公开槽映射到家族合同；形态三档由家族按 control 上的 data-variant 生成，皮肤不再声明 */
  [data-scope='tags-input'][data-part='root'] {
    /* 作者塞进来的图标跟着控件的尺寸档走；它自己写了 size 时仍以作者的为准 */
    --xh-icon-size: var(--xh-tags-input-icon-size, var(--xh-glyph-size-md));

    /* 尺寸档只换这九个私有槽，标题、框、输入框与就地编辑框都从 root 继承它们，
       换档不必给每个部件各写一条选择器。标签本身是 tag，档位由 data-size 传下去，不走这些槽；
       就地编辑框的四个槽照 tag 那一档的行框、内衬与字号写，换进换出时与标签一样高 */
    --xh-_tags-input-control-h: var(--xh-control-h-md);
    --xh-_tags-input-control-px: var(--xh-control-px-md);
    --xh-_tags-input-control-gap: var(--xh-control-gap-md);
    --xh-_tags-input-input-font-size: var(--xh-control-font-md);
    --xh-_tags-input-item-font-size: var(--xh-control-caption-md);
    --xh-_tags-input-item-py: var(--xh-space-1);
    --xh-_tags-input-item-px: var(--xh-space-2);
    --xh-_tags-input-item-line-h: var(--xh-control-indicator-md);
    /* 光标走到的那颗标签是「当前项」，不是选中：淡底 + 淡底前景，随语气走。
       没写 data-tone 时 --xh-_tone-* 没被声明，退回品牌淡底 */
    --xh-_tags-input-accent: var(--xh-_tone-subtle, var(--xh-bg-brand-subtle));
    --xh-_tags-input-accent-fg: var(--xh-_tone-fg, var(--xh-fg-on-brand-subtle));

    display: inline-flex;
    flex-direction: column;
    gap: var(--xh-tags-input-gap, var(--xh-space-1));
    /* 不传尺寸时一律这么宽，宽度不随内容走；父容器给不出这么宽时整件跟着收，地板同步让步，不越出父容器。
       地板不高过缺省宽：使用者把缺省宽钉到底线以下时不必再放开底线 */
    inline-size: var(--xh-tags-input-control-w, var(--xh-control-w));
    min-inline-size: min(var(--xh-tags-input-control-w, var(--xh-control-w)), var(--xh-tags-input-control-min-w, var(--xh-control-min-w)), 100%);
    max-inline-size: 100%;
  }

  /* 只要声明了 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='tags-input'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 尺寸 —— */
  [data-scope='tags-input'][data-part='root'][data-size='sm'] {
    --xh-icon-size: var(--xh-tags-input-icon-size, var(--xh-glyph-size-sm));
    --xh-_tags-input-control-h: var(--xh-control-h-sm);
    --xh-_tags-input-control-px: var(--xh-control-px-sm);
    --xh-_tags-input-control-gap: var(--xh-control-gap-sm);
    --xh-_tags-input-input-font-size: var(--xh-control-font-sm);
    --xh-_tags-input-item-font-size: var(--xh-control-caption-sm);
    --xh-_tags-input-item-py: var(--xh-space-0_5);
    --xh-_tags-input-item-px: var(--xh-space-1_5);
  }

  [data-scope='tags-input'][data-part='root'][data-size='lg'] {
    --xh-icon-size: var(--xh-tags-input-icon-size, var(--xh-glyph-size-lg));
    --xh-_tags-input-control-h: var(--xh-control-h-lg);
    --xh-_tags-input-control-px: var(--xh-control-px-lg);
    --xh-_tags-input-control-gap: var(--xh-control-gap-lg);
    --xh-_tags-input-input-font-size: var(--xh-control-font-lg);
    --xh-_tags-input-item-font-size: var(--xh-control-caption-lg);
    --xh-_tags-input-item-px: var(--xh-space-3);
    --xh-_tags-input-item-line-h: var(--xh-control-indicator-lg);
  }

  [data-scope='tags-input'][data-part='label'] {
    color: var(--xh-tags-input-label-fg, var(--xh-fg-default));
    font-size: var(--xh-tags-input-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-tags-input-label-font-weight, var(--xh-text-label-weight));
  }

  [data-scope='tags-input'][data-part='label'][data-disabled] {
    color: var(--xh-tags-input-label-fg-disabled, var(--xh-fg-subtle));
  }

  /* 标签换行排，输入框跟在最后一个标签后面：描边、底色、圆角、聚焦环、五态与悬停由 Field Chrome
     家族画在 control 上，可换行、自动高、半档纵向内衬与「只有一个标签时仍像普通输入框」的最小高
     由家族按 multi-tag 布局给。组件只映射既有公开槽；只读时盒上不是文本光标 */
  [data-scope='tags-input'][data-part='control'] {
    --xh-field-control-height: var(--xh-tags-input-control-h, var(--xh-_tags-input-control-h));
    --xh-field-control-padding-inline: var(--xh-tags-input-control-px, var(--xh-_tags-input-control-px));
    --xh-field-control-gap: var(--xh-tags-input-control-gap, var(--xh-_tags-input-control-gap));
    --xh-field-control-min-inline-size: var(--xh-tags-input-control-min-w, var(--xh-control-min-w));
    --xh-field-control-radius: var(--xh-tags-input-control-radius, var(--xh-shape-control));
    --xh-field-bg-rest: var(--xh-tags-input-control-bg, var(--xh-_field-variant-bg-rest));
    --xh-field-bg-hover: var(--xh-tags-input-control-bg-hover, var(--xh-_field-variant-bg-hover));
    --xh-field-bg-read-only: var(--xh-tags-input-control-bg-readonly, var(--xh-_field-variant-bg-read-only));
    --xh-field-bg-disabled: var(--xh-tags-input-control-bg-disabled, var(--xh-_field-variant-bg-disabled));
    --xh-field-fg-rest: var(--xh-tags-input-control-fg, var(--xh-fg-default));
    --xh-field-border-rest: var(--xh-tags-input-control-border, var(--xh-_field-variant-border-rest));
    --xh-field-border-hover: var(--xh-tags-input-control-border-hover, var(--xh-_field-variant-border-hover));
    --xh-field-border-focus: var(--xh-tags-input-control-border-focus, var(--xh-_field-variant-border-focus));
    --xh-field-border-invalid: var(--xh-tags-input-control-border-invalid, var(--xh-_field-variant-border-invalid));
    --xh-field-ring-focus: var(--xh-ring-focus);
    --xh-field-ring-invalid: var(--xh-ring-invalid);
    --xh-field-shadow-rest: var(--xh-tags-input-control-shadow, none);
    --xh-field-cursor-read-only: default;
    /* 家族 chrome 会重写 --xh-icon-size，使用者图标槽必须经桥接槽下发才能在盒内生效 */
    --xh-field-glyph-size: var(--xh-tags-input-icon-size, var(--xh-_field-size-glyph-size));

    /* 标签一多就换行，行数没有尽头：框到这个高度就不再长，剩下的标签在框内滚出来。
       上限取滚动面最小的那一档，与页面上其它滚动面用同一把尺 */
    max-block-size: var(--xh-tags-input-control-max-h, var(--xh-viewport-h-sm));
    overflow-y: auto;
  }

  [data-scope='tags-input'][data-part='control'][hidden] {
    display: none;
  }

  /* 顶到上限是 TagsInput 独有状态：再加进不去，边框先给个提示；invalid 同时出现时由 Field Chrome 的
     错误态优先——真出错比"装满了"要紧 */
  [data-scope='tags-input'][data-part='control'][data-at-max]:not([data-invalid]) {
    border-color: var(--xh-tags-input-control-border-at-max, var(--xh-border-at-limit));
  }

  /* 输入框贴着标签排：无边框无底无圆角无落影由家族重置，那两样归 control。
     min-inline-size 保证标签占满一行后它还能换到下一行继续输入，而不是被挤成零宽；
     占位与自动填充的颜色经桥接槽下发 */
  [data-scope='tags-input'][data-part='input'] {
    --xh-field-input-fg: var(--xh-tags-input-input-fg, var(--xh-fg-default));
    --xh-field-input-font-size: var(--xh-tags-input-input-font-size, var(--xh-_tags-input-input-font-size));
    --xh-field-placeholder-fg: var(--xh-tags-input-placeholder-fg, var(--xh-fg-subtle));
    --xh-field-autofill-bg: var(--xh-tags-input-input-autofill-bg, var(--xh-bg-canvas));
    --xh-field-autofill-fg: var(--xh-tags-input-input-autofill-fg, var(--xh-fg-default));

    /* 撑满剩余宽度由家族的 flex: 1 1 auto 给，这里只换起算宽 */
    flex-basis: var(--xh-tags-input-input-basis, 6rem);
    min-inline-size: var(--xh-tags-input-input-min-w, 4rem);
    /* 行盒收到标签那一行的高度以内，输入框不去顶高整个框 */
    block-size: auto;
    line-height: var(--xh-leading-tight);
  }

  /* 一个标签一个条目。条目只是壳：可见的胶囊是里面 tag 的 root（就地编辑时换成 item-input），
     样子全归 tag.css，这里只管它在行里怎么占位——不缩、不超过一行；
     长标签由壳的上限压住，截断落在 tag 自己的 label 上 */
  [data-scope='tags-input'][data-part='item'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    max-inline-size: 100%;
  }

  [data-scope='tags-input'][data-part='item'][hidden] {
    display: none;
  }

  /* 双击标签是进就地编辑，不是选字：选区一闪再换成编辑框，看起来像点错了 */
  [data-scope='tags-input'][data-part='item'] > [data-scope='tag'][data-part='root'] {
    user-select: none;
  }

  /* 光标走到这颗标签上（退格第一下、方向键）：整颗换成「当前项」的淡底，与"删掉它"这件事对得上。
     反白画在 tag 的 root 上，描边一并收成透明——描边档的标签反白后不留一圈异色边；
     禁用态下不给高亮：那时候本来就走不进标签 */
  [data-scope='tags-input'][data-part='item'][data-highlighted]:not([data-disabled]) > [data-scope='tag'][data-part='root'] {
    border-color: transparent;
    background: var(--xh-tags-input-item-bg-highlight, var(--xh-_tags-input-accent));
    color: var(--xh-tags-input-item-fg-highlight, var(--xh-_tags-input-accent-fg));
  }

  /* 反白的面是语气淡底，环压上去与面同族看不出来；叉自己的面是透空的，环取它的字色——
     上面那条反白规则已经把它换成配对的那支色 */
  [data-scope='tags-input'][data-part='item'][data-highlighted]:not([data-disabled]) > [data-scope='tag'][data-part='root']
    [data-scope='tag'][data-part='close-trigger']:focus-visible {
    --xh-_ring-color: currentColor;
  }

  /* 就地编辑框：尺寸对齐胶囊，看起来像是在原地把标签改了，而不是另开一个框。
     阶梯照 tag 的档走：行框取指示符档，竖向内衬、横向内衬与字号随档从 root 的私有槽取。
     不声明 display —— 收起态靠 UA 的 [hidden]{display:none} 就够，
     自己加一条 display 反而要再补一条 [hidden] 规则去抵消它 */
  [data-scope='tags-input'][data-part='item-input'] {
    /* 宽随正在改的那几个字走，不取原生 input 按 20 个字符算出来的宽：字段缺省宽只有 16rem，
       一个 20 字符宽的编辑框会把后面的输入框挤到下一行，进编辑态时框就长高了 */
    field-sizing: content;
    inline-size: auto;
    min-inline-size: 3ch;
    max-inline-size: 100%;
    padding-block: var(--xh-tags-input-item-py, var(--xh-_tags-input-item-py));
    padding-inline: var(--xh-tags-input-item-px, var(--xh-_tags-input-item-px));
    border: var(--xh-stroke-thin) solid var(--xh-tags-input-item-input-border, var(--xh-border-control));
    border-radius: var(--xh-tags-input-item-radius, var(--xh-shape-control));
    background: var(--xh-tags-input-item-input-bg, var(--xh-bg-canvas));
    color: var(--xh-tags-input-item-input-fg, var(--xh-fg-default));
    font-family: inherit;
    font-size: var(--xh-tags-input-item-font-size, var(--xh-_tags-input-item-font-size));
    /* 行框不低于胶囊里那一行的高，编辑框与它换掉的标签一样高，换进换出时行不跳 */
    line-height: max(calc(var(--xh-leading-none) * 1em), var(--xh-_tags-input-item-line-h));
  }

  /* 它是真正持有焦点的那个节点，环画在自己身上；
     外层 control 的 :focus-within 环同时亮着也合理——焦点确实在框内 */
  [data-scope='tags-input'][data-part='item-input']:focus-visible {
    outline: var(--xh-ring-width) solid var(--xh-ring-focus);
    outline-offset: var(--xh-ring-offset);
  }

  /* 校验失败时环也跟着变红：与外框上家族画的那圈同色，两圈相邻不至于一红一蓝 */
  [data-scope='tags-input'][data-part='control'][data-invalid] [data-scope='tags-input'][data-part='item-input']:focus-visible {
    outline-color: var(--xh-ring-invalid);
  }

  [data-scope='tags-input'][data-part='item-input']:disabled {
    color: var(--xh-fg-disabled);
  }

  /* 清空按钮贴在框的末端，与输入框同一行：正方视觉盒、inset 圆角、悬停 100 / 按下 200 与 0.97 按压、
     粗指针热区与 :focus-visible 关环全由 Action Control 的 field-inset ghost 档给，组件只映射既有覆盖槽。
     没值可清时连接层给 hidden 收起 */
  [data-scope='tags-input'][data-part='clear-trigger'] {
    --xh-action-visual-size: var(--xh-tags-input-action-size, var(--xh-_action-profile-visual-size));
    --xh-action-min-inline-size: var(--xh-tags-input-action-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-tags-input-action-radius, var(--xh-shape-inset));
    /* 底色阶梯由 ghost 档给（透明 → 100 → 200），使用者槽只作覆盖入口 */
    --xh-action-bg-rest: var(--xh-tags-input-action-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-tags-input-action-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-tags-input-action-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-tags-input-action-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-tags-input-action-fg-hover, var(--xh-fg-default));
    --xh-action-border-rest: transparent;
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    --xh-action-font-size: var(--xh-tags-input-action-font-size, var(--xh-text-secondary-size));
    /* 配方尚未把 profile 字形档灌进 --xh-icon-size，钮内字形先按 field-inset 档逐钮取值 */
    --xh-icon-size: var(--xh-_action-profile-glyph-size);

    border-width: 0;
  }

  /* 没值可清时连接层只打 hidden；家族那条 display 会盖掉 UA 规则，少了这条按钮就一直杵着 */
  [data-scope='tags-input'][data-part='clear-trigger'][hidden] {
    display: none;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中 */
  [data-scope='tags-input'][data-part='clear-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }

  /* 计数：排在控件行下面靠尾端的一行小字，与标题分列 root 的两端 */
  [data-scope='tags-input'][data-part='count'] {
    align-self: flex-end;
    color: var(--xh-tags-input-count-fg, var(--xh-fg-muted));
    font-size: var(--xh-tags-input-count-font-size, var(--xh-_tags-input-item-font-size));
    font-variant-numeric: tabular-nums;
    line-height: var(--xh-leading-normal);
  }

  /* 没开 showCount 时连接层给的是 hidden 属性；上面那条 align-self 不影响显隐，
     但作者层给这个 part 声明任何一条 display 都会盖掉 UA 规则，这条把它还回去 */
  [data-scope='tags-input'][data-part='count'][hidden] {
    display: none;
  }

  /* 顶到上限：数字先于框被看见，与越界那一档同族颜色 */
  [data-scope='tags-input'][data-part='count'][data-at-max] {
    color: var(--xh-tags-input-count-fg-at-max, var(--xh-fg-warning));
  }

  [data-scope='tags-input'][data-part='count'][data-disabled] {
    color: var(--xh-tags-input-count-fg-disabled, var(--xh-fg-disabled));
  }
}

/* styles/text-field.css */
/* TextField 独立皮肤同时传递引入字段视觉盒与字段内动作；full bundle 递归去重。 */

@layer xihan.components {
  [data-scope='text-field'] {
    --xh-text-field-skin: 1;
  }

  /* 组件层只把既有公开槽映射到家族合同，并保留 label/count 等 TextField 专属结构；
     形态三档由家族按 control 上的 data-variant 生成，皮肤不再声明。 */
  [data-scope='text-field'][data-part='root'] {
    --xh-_text-field-h: var(--xh-control-h-md);
    --xh-_text-field-px: var(--xh-control-px-md);
    --xh-_text-field-gap: var(--xh-control-gap-md);
    --xh-_text-field-font-size: var(--xh-control-font-md);
    --xh-_text-field-action-font-size: var(--xh-control-caption-md);

    --xh-icon-size: var(--xh-text-field-icon-size, var(--xh-glyph-size-md));

    display: inline-flex;
    flex-direction: column;
    gap: var(--xh-text-field-gap, var(--xh-space-1));
    /* 不传尺寸时一律这么宽，宽度不随内容走；父容器给不出这么宽时整件跟着收，地板同步让步，不越出父容器。
       地板不高过缺省宽：使用者把缺省宽钉到底线以下时不必再放开底线 */
    inline-size: var(--xh-text-field-control-w, var(--xh-control-w));
    min-inline-size: min(var(--xh-text-field-control-w, var(--xh-control-w)), var(--xh-text-field-control-min-w, var(--xh-control-min-w)), 100%);
    max-inline-size: 100%;
  }

  [data-scope='text-field'][data-part='root'][hidden] {
    display: none;
  }

  [data-scope='text-field'][data-part='root'][data-size='sm'] {
    --xh-_text-field-h: var(--xh-control-h-sm);
    --xh-_text-field-px: var(--xh-control-px-sm);
    --xh-_text-field-gap: var(--xh-control-gap-sm);
    --xh-_text-field-font-size: var(--xh-control-font-sm);
    --xh-_text-field-action-font-size: var(--xh-control-caption-sm);
    --xh-icon-size: var(--xh-text-field-icon-size, var(--xh-glyph-size-sm));
  }

  [data-scope='text-field'][data-part='root'][data-size='lg'] {
    --xh-_text-field-h: var(--xh-control-h-lg);
    --xh-_text-field-px: var(--xh-control-px-lg);
    --xh-_text-field-gap: var(--xh-control-gap-lg);
    --xh-_text-field-font-size: var(--xh-control-font-lg);
    --xh-_text-field-action-font-size: var(--xh-control-caption-lg);
    --xh-icon-size: var(--xh-text-field-icon-size, var(--xh-glyph-size-lg));
  }

  [data-scope='text-field'][data-part='label'] {
    color: var(--xh-text-field-label-fg, var(--xh-fg-default));
    font-size: var(--xh-text-field-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-text-field-label-font-weight, var(--xh-text-label-weight));
  }

  [data-scope='text-field'][data-part='label'][data-disabled] {
    color: var(--xh-text-field-label-fg-disabled, var(--xh-fg-subtle));
  }

  [data-scope='text-field'][data-part='control'] {
    --xh-field-control-height: var(--xh-text-field-control-h, var(--xh-_text-field-h));
    --xh-field-control-padding-inline: var(--xh-text-field-control-px, var(--xh-_text-field-px));
    --xh-field-control-gap: var(--xh-text-field-control-gap, var(--xh-_text-field-gap));
    --xh-field-control-min-inline-size: var(--xh-text-field-control-min-w, var(--xh-control-min-w));
    --xh-field-control-radius: var(--xh-text-field-control-radius, var(--xh-shape-control));
    --xh-field-bg-rest: var(--xh-text-field-control-bg, var(--xh-_field-variant-bg-rest));
    --xh-field-bg-hover: var(--xh-text-field-control-bg-hover, var(--xh-_field-variant-bg-hover));
    --xh-field-bg-read-only: var(--xh-text-field-control-bg-readonly, var(--xh-_field-variant-bg-read-only));
    --xh-field-bg-disabled: var(--xh-text-field-control-bg-disabled, var(--xh-_field-variant-bg-disabled));
    --xh-field-fg-rest: var(--xh-text-field-control-fg, var(--xh-fg-default));
    --xh-field-border-rest: var(--xh-text-field-control-border, var(--xh-_field-variant-border-rest));
    --xh-field-border-hover: var(--xh-text-field-control-border-hover, var(--xh-_field-variant-border-hover));
    --xh-field-border-focus: var(--xh-text-field-control-border-focus, var(--xh-_field-variant-border-focus));
    --xh-field-border-invalid: var(--xh-text-field-control-border-invalid, var(--xh-_field-variant-border-invalid));
    --xh-field-ring-focus: var(--xh-ring-focus);
    --xh-field-ring-invalid: var(--xh-ring-invalid);
    --xh-field-shadow-rest: var(--xh-text-field-control-shadow, none);
    /* 家族 chrome 会重写 --xh-icon-size，使用者图标槽必须经桥接槽下发才能在盒内生效 */
    --xh-field-glyph-size: var(--xh-text-field-icon-size, var(--xh-_field-size-glyph-size));
  }

  [data-scope='text-field'][data-part='prefix'],
  [data-scope='text-field'][data-part='suffix'] {
    --xh-field-affix-fg: var(--xh-text-field-affix-fg, var(--xh-fg-muted));
    --xh-field-affix-fg-disabled: var(--xh-text-field-affix-fg-disabled, var(--xh-fg-disabled));
    --xh-field-affix-font-size: var(--xh-text-field-affix-font-size, var(--xh-_text-field-font-size));
  }

  [data-scope='text-field'][data-part='input'] {
    --xh-field-input-fg: var(--xh-text-field-input-fg, var(--xh-fg-default));
    --xh-field-input-font-size: var(--xh-text-field-input-font-size, var(--xh-_text-field-font-size));
    --xh-field-placeholder-fg: var(--xh-text-field-placeholder-fg, var(--xh-fg-subtle));
    --xh-field-autofill-bg: var(--xh-text-field-input-autofill-bg, var(--xh-bg-canvas));
    --xh-field-autofill-fg: var(--xh-text-field-input-autofill-fg, var(--xh-fg-default));
    --xh-field-textarea-padding-block: var(--xh-text-field-textarea-py, var(--xh-space-2));
  }

  [data-scope='text-field'][data-part='control'][hidden] {
    display: none;
  }

  /* autoSize 的量高值写在 textarea 上；外壳只负责滚动上限，不能复制量高算法。 */
  [data-scope='text-field'][data-part='control']:has([data-xh-field-input][data-xh-field-auto-size]) {
    max-block-size: var(--xh-text-field-control-max-h, var(--xh-viewport-h-sm));
    overflow-y: auto;
  }

  /* 字数上限是 TextField 独有状态；invalid 同时出现时由 Field Chrome 的错误态优先。 */
  [data-scope='text-field'][data-part='control'][data-at-max]:not([data-invalid]) {
    border-color: var(--xh-text-field-control-border-at-max, var(--xh-border-at-limit));
  }

  /* clear 的视觉、悬停/按压阶梯与粗指针热区来自 field-inset ghost 档，组件只映射既有覆盖槽。 */
  [data-scope='text-field'][data-part='clear-trigger'] {
    --xh-action-visual-size: var(--xh-text-field-action-size, var(--xh-_action-profile-visual-size));
    --xh-action-min-inline-size: var(--xh-text-field-action-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-text-field-action-radius, var(--xh-shape-inset));
    /* 底色阶梯由 ghost 档给（透明 → 100 → 200），使用者槽只作覆盖入口 */
    --xh-action-bg-rest: var(--xh-text-field-action-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-text-field-action-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-text-field-action-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-text-field-action-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-text-field-action-fg-hover, var(--xh-fg-default));
    --xh-action-border-rest: transparent;
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    --xh-action-font-size: var(--xh-text-field-action-font-size, var(--xh-_text-field-action-font-size));
    /* 配方尚未把 profile 字形档灌进 --xh-icon-size，钮内字形先按 field-inset 档逐钮取值 */
    --xh-icon-size: var(--xh-_action-profile-glyph-size);

    border-width: 0;
  }

  [data-scope='text-field'][data-part='clear-trigger'][hidden] {
    display: none;
  }

  [data-scope='text-field'][data-part='clear-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }

  [data-scope='text-field'][data-part='count'] {
    align-self: flex-end;
    color: var(--xh-text-field-count-fg, var(--xh-fg-muted));
    font-size: var(--xh-text-field-count-font-size, var(--xh-_text-field-action-font-size));
    font-variant-numeric: tabular-nums;
    line-height: var(--xh-leading-normal);
  }

  [data-scope='text-field'][data-part='count'][hidden] {
    display: none;
  }

  [data-scope='text-field'][data-part='count'][data-at-max] {
    color: var(--xh-text-field-count-fg-at-max, var(--xh-fg-warning));
  }

  [data-scope='text-field'][data-part='count'][data-disabled] {
    color: var(--xh-text-field-count-fg-disabled, var(--xh-fg-disabled));
  }
}

/* styles/time-field.css */
/* TimeField 独立皮肤同时传递引入字段视觉盒与字段内动作；full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='time-field'] {
    --xh-time-field-skin: 1;
  }

  /* 与文本框、数字框同一套堆叠：标签一行、控件一行。
     组件层只把既有公开槽映射到家族合同；形态三档由家族按 control 上的 data-variant 生成，皮肤不再声明。 */
  [data-scope='time-field'][data-part='root'] {
    /* 作者塞进来的图标跟着控件的尺寸档走；它自己写了 size 时仍以作者的为准 */
    --xh-icon-size: var(--xh-time-field-icon-size, var(--xh-glyph-size-md));

    /* 尺寸档只换这四个私有槽，控件从 root 继承它们，换档不必给每个部件各写一条选择器 */
    --xh-_time-field-control-h: var(--xh-control-h-md);
    --xh-_time-field-control-px: var(--xh-control-px-md);
    --xh-_time-field-gap: var(--xh-control-gap-md);
    --xh-_time-field-font-size: var(--xh-control-font-md);
    /* 段位反白随语气走：当前段是「当前项」，淡底 + 淡底前景。
       没写 data-tone 时这几个 --xh-_tone* 没被声明，退回品牌淡底 */
    --xh-_time-field-segment-bg: var(--xh-_tone-subtle, var(--xh-bg-brand-subtle));
    --xh-_time-field-segment-fg: var(--xh-_tone-fg, var(--xh-fg-on-brand-subtle));

    display: inline-flex;
    flex-direction: column;
    gap: var(--xh-time-field-gap, var(--xh-space-1));

    /* 不传尺寸时一律这么宽，宽度不随内容走；父容器给不出这么宽时整件跟着收，地板同步让步，不越出父容器。
       地板不高过缺省宽：使用者把缺省宽钉到底线以下时不必再放开底线 */
    inline-size: var(--xh-time-field-control-w, var(--xh-control-w));
    min-inline-size: min(var(--xh-time-field-control-w, var(--xh-control-w)), var(--xh-time-field-control-min-w, var(--xh-control-min-w)), 100%);
    max-inline-size: 100%;
  }

  /* —— 尺寸 —— */
  [data-scope='time-field'][data-part='root'][data-size='sm'] {
    --xh-icon-size: var(--xh-time-field-icon-size, var(--xh-glyph-size-sm));
    --xh-_time-field-control-h: var(--xh-control-h-sm);
    --xh-_time-field-control-px: var(--xh-control-px-sm);
    --xh-_time-field-gap: var(--xh-control-gap-sm);
    --xh-_time-field-font-size: var(--xh-control-font-sm);
  }

  [data-scope='time-field'][data-part='root'][data-size='lg'] {
    --xh-icon-size: var(--xh-time-field-icon-size, var(--xh-glyph-size-lg));
    --xh-_time-field-control-h: var(--xh-control-h-lg);
    --xh-_time-field-control-px: var(--xh-control-px-lg);
    --xh-_time-field-gap: var(--xh-control-gap-lg);
    --xh-_time-field-font-size: var(--xh-control-font-lg);
  }

  /* 声明了 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='time-field'][data-part='root'][hidden] {
    display: none;
  }

  [data-scope='time-field'][data-part='label'] {
    color: var(--xh-time-field-label-fg, var(--xh-fg-default));
    font-size: var(--xh-time-field-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-time-field-label-font-weight, var(--xh-text-label-weight));
  }

  [data-scope='time-field'][data-part='label'][data-disabled] {
    color: var(--xh-time-field-label-fg-disabled, var(--xh-fg-subtle));
  }

  /* 几段合起来看着像一个输入框：描边、底色、圆角、聚焦环、五态与悬停由 Field Chrome 家族画在
     control 上，段自己只管一小块可聚焦的高亮区。组件只映射既有公开槽；段位靠键盘编辑，盒上不是文本光标 */
  [data-scope='time-field'][data-part='control'] {
    --xh-field-control-height: var(--xh-time-field-control-h, var(--xh-_time-field-control-h));
    --xh-field-control-padding-inline: var(--xh-time-field-control-px, var(--xh-_time-field-control-px));
    --xh-field-control-gap: var(--xh-time-field-control-gap, var(--xh-_time-field-gap));
    --xh-field-control-min-inline-size: var(--xh-time-field-control-min-w, var(--xh-control-min-w));
    --xh-field-control-radius: var(--xh-time-field-control-radius, var(--xh-shape-control));
    --xh-field-bg-rest: var(--xh-time-field-control-bg, var(--xh-_field-variant-bg-rest));
    --xh-field-bg-hover: var(--xh-time-field-control-bg-hover, var(--xh-_field-variant-bg-hover));
    --xh-field-bg-read-only: var(--xh-time-field-control-bg-readonly, var(--xh-_field-variant-bg-read-only));
    --xh-field-bg-disabled: var(--xh-time-field-control-bg-disabled, var(--xh-_field-variant-bg-disabled));
    --xh-field-fg-rest: var(--xh-time-field-control-fg, var(--xh-fg-default));
    --xh-field-border-rest: var(--xh-time-field-control-border, var(--xh-_field-variant-border-rest));
    --xh-field-border-hover: var(--xh-time-field-control-border-hover, var(--xh-_field-variant-border-hover));
    --xh-field-border-focus: var(--xh-time-field-control-border-focus, var(--xh-_field-variant-border-focus));
    --xh-field-border-invalid: var(--xh-time-field-control-border-invalid, var(--xh-_field-variant-border-invalid));
    --xh-field-ring-focus: var(--xh-ring-focus);
    --xh-field-ring-invalid: var(--xh-ring-invalid);
    --xh-field-shadow-rest: var(--xh-time-field-control-shadow, none);
    --xh-field-cursor-rest: default;
    /* 家族 chrome 会重写 --xh-icon-size，使用者图标槽必须经桥接槽下发才能在盒内生效 */
    --xh-field-glyph-size: var(--xh-time-field-icon-size, var(--xh-_field-size-glyph-size));

    /* 表单控件不继承页面字体，只给字号会让它用 UA 默认字族，与周围文本对不上 */
    font-family: inherit;
    font-size: var(--xh-time-field-font-size, var(--xh-_time-field-font-size));
    /* 等宽数字：各位字宽不一时逐段填入会让整行左右跳 */
    font-variant-numeric: tabular-nums;
    line-height: var(--xh-leading-normal);
  }

  [data-scope='time-field'][data-part='control'][hidden] {
    display: none;
  }

  /* 段位与作者写在段间的分隔符都在这一层里：它占满盒里剩下的宽度，
     清空钮因此靠在框内末端 */
  [data-scope='time-field'][data-part='segment-group'] {
    display: inline-flex;
    flex: 1 1 auto;
    align-items: center;
    min-inline-size: 0;
  }

  [data-scope='time-field'][data-part='segment-group'][hidden] {
    display: none;
  }

  [data-scope='time-field'][data-part='segment-group'] > :not([data-scope]) {
    color: var(--xh-time-field-literal-fg, var(--xh-fg-subtle));
  }

  /* 段是一小块可聚焦区，紧挨着排；间距长在段自己身上 */
  [data-scope='time-field'][data-part='segment'] {
    display: inline-block;
    padding-inline: var(--xh-time-field-segment-px, var(--xh-space-0_5));
    padding-block: var(--xh-time-field-segment-py, var(--xh-space-0));
    border-radius: var(--xh-time-field-segment-radius, var(--xh-shape-inset));
    color: inherit;
    font-variant-numeric: inherit;
    text-align: center;
    /* 段是 role=spinbutton 的展示节点，双击选中一段文字只会碍事 */
    user-select: none;
    /* 触屏上连点两下不该被当成缩放手势 */
    touch-action: manipulation;
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* granularity / hourCycle 关掉的段由连接层打 hidden；上面那条 display 会把 UA 规则盖掉，
     少了这条，收起的段会一直杵在那儿 */
  [data-scope='time-field'][data-part='segment'][hidden] {
    display: none;
  }

  /* 还没填的段压成弱色：一行里哪几段是占位符，一眼要看得出来 */
  [data-scope='time-field'][data-part='segment'][data-placeholder] {
    color: var(--xh-time-field-placeholder-fg, var(--xh-fg-subtle));
  }

  /* 一行段长得差不多，光有边框亮起来看不出正在改哪一段：当前段必须自己有底色。
     data-focus 由机器给（它知道谁是当前段），:focus-visible 兜住机器状态还没回流的那一帧，
     两条同时写不冲突 */
  [data-scope='time-field'][data-part='segment'][data-focus]:not([data-disabled]),
  [data-scope='time-field'][data-part='segment']:focus-visible {
    background: var(--xh-time-field-segment-bg-focus, var(--xh-_time-field-segment-bg));
    color: var(--xh-time-field-segment-fg-focus, var(--xh-_time-field-segment-fg));
    outline: none;
  }

  /* 选中态用了品牌底色之后，占位符那条弱色会被它盖住，这里明确让位给焦点态 */
  [data-scope='time-field'][data-part='segment'][data-focus][data-placeholder]:not([data-disabled]) {
    color: var(--xh-time-field-segment-fg-focus, var(--xh-_time-field-segment-fg));
  }

  [data-scope='time-field'][data-part='segment'][data-invalid] {
    color: var(--xh-time-field-segment-fg-invalid, var(--xh-fg-danger));
  }

  [data-scope='time-field'][data-part='segment'][data-invalid]:is([data-focus], :focus-visible) {
    background: var(
      --xh-time-field-segment-bg-invalid-focus,
      var(--xh-bg-subtle)
    );
    color: var(--xh-time-field-segment-fg-invalid-focus, var(--xh-fg-danger));
  }

  /* 白底承载的悬停走 100：段位铺在 canvas 底的盒里，不是淡底容器 */
  [data-scope='time-field'][data-part='segment']:hover:not([data-focus], [data-disabled]) {
    background: var(--xh-time-field-segment-bg-hover, var(--xh-bg-subtle));
  }

  /* 段是集合条目形态（role=spinbutton 的 span），禁用走 data-disabled 而不是 :disabled */
  [data-scope='time-field'][data-part='segment'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 清空按钮贴在框内末端，靠段位外壳的 flex:1 顶到末端，自己不写 margin：正方视觉盒、inset 圆角、
     悬停 100 / 按下 200 与 0.97 按压、粗指针热区与 :focus-visible 关环全由 Action Control 的
     field-inset ghost 档给，组件只映射既有覆盖槽。没值时连接层给 hidden 收起 */
  [data-scope='time-field'][data-part='clear-trigger'] {
    --xh-action-visual-size: var(--xh-time-field-action-size, var(--xh-_action-profile-visual-size));
    --xh-action-min-inline-size: var(--xh-time-field-action-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-time-field-action-radius, var(--xh-shape-inset));
    /* 底色阶梯由 ghost 档给（透明 → 100 → 200），使用者槽只作覆盖入口 */
    --xh-action-bg-rest: var(--xh-time-field-action-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-time-field-action-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-time-field-action-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-time-field-action-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-time-field-action-fg-hover, var(--xh-fg-default));
    --xh-action-border-rest: transparent;
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    --xh-action-font-size: var(--xh-time-field-action-font-size, var(--xh-text-secondary-size));
    /* 配方尚未把 profile 字形档灌进 --xh-icon-size，钮内字形先按 field-inset 档逐钮取值 */
    --xh-icon-size: var(--xh-_action-profile-glyph-size);

    border-width: 0;
  }

  /* 没值时连接层给的是 hidden 属性；家族那条 display 会把 UA 规则盖掉 */
  [data-scope='time-field'][data-part='clear-trigger'][hidden] {
    display: none;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这条即不命中 */
  [data-scope='time-field'][data-part='clear-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }

  @media (forced-colors: active) {
    [data-scope='time-field'][data-part='segment'][data-invalid]:is([data-focus], :focus-visible) {
      outline: var(--xh-ring-width) solid Highlight;
      outline-offset: var(--xh-ring-offset);
    }
  }

  /* 连接层把它写成 type=hidden，UA 自己就不渲染；这里的视觉隐藏是给元素升级前那一瞬兜底
     （作者手写的是一个普通 input，升级完成前它是可见的文本框）。
     刻意不写 display：写了反而会盖掉 UA 对 type=hidden 的收起，把它显出来 */
  [data-scope='time-field'][data-part='hidden-input'] {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    border: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    pointer-events: none;
  }
}

/* styles/time-picker.css */
/* TimePicker 独立皮肤同时传递引入字段视觉盒、字段内动作与浮层集合行；full bundle 递归去重。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='time-picker'] {
    --xh-time-picker-skin: 1;
  }

  /* 坐标由定位引擎写进 style（inset-inline-start / inset-block-start），这里只定位模式与层级 */
  [data-scope='time-picker'][data-part='positioner'] {
    /* 每个浮层独立声明方向，避免嵌套浮层继承祖先的进场位移。 */
    --xh-_overlay-enter-up: 0;
    --xh-_overlay-enter-down: 0;
    --xh-_overlay-enter-left: 0;
    --xh-_overlay-enter-right: 0;

    position: fixed;
    z-index: var(--xh-time-picker-layer, var(--xh-_layer, var(--xh-layer-popover)));
    /* 空壳不吃指针，交互只发生在 content 里 */
    pointer-events: none;
  }

  /* 锚点被滚出可视区：整个浮层随之收起 */
  [data-scope='time-picker'][data-part='positioner'][data-hidden] {
    visibility: hidden;
  }

  /* 短位移沿实际落位的物理方向，不随书写方向翻转。 */
  [data-scope='time-picker'][data-part='positioner'][data-placement^='top'] {
    --xh-_overlay-enter-down: 1;
  }

  [data-scope='time-picker'][data-part='positioner'][data-placement^='bottom'] {
    --xh-_overlay-enter-up: 1;
  }

  [data-scope='time-picker'][data-part='positioner'][data-placement^='left'] {
    --xh-_overlay-enter-right: 1;
  }

  [data-scope='time-picker'][data-part='positioner'][data-placement^='right'] {
    --xh-_overlay-enter-left: 1;
  }

  /* 私有槽同时声明在根与 positioner 上：浮层被搬到 portal 落点，不是根的后代，继承不过去 */
  [data-scope='time-picker']:is([data-part='root'], [data-part='positioner']) {
    /* 尺寸档只换这几个私有槽，标题、输入行与浮层里的格子都从这两处继承它们，
       换档不必给每个部件各写一条选择器；形态三档由家族按 control 上的 data-variant 生成，皮肤不再声明 */
    --xh-_time-picker-control-h: var(--xh-control-h-md);
    --xh-_time-picker-control-px: var(--xh-control-px-md);
    --xh-_time-picker-gap: var(--xh-control-gap-md);
    --xh-_time-picker-font-size: var(--xh-control-font-md);

    /* 段位强调随语气走：当前段是「当前项」，淡底 + 淡底前景；对号使用普通表面上的前景色。
       没写 data-tone 时这几个 --xh-_tone* 没被声明，退回品牌色 */
    --xh-_time-picker-segment-bg: var(--xh-_tone-subtle, var(--xh-bg-brand-subtle));
    --xh-_time-picker-segment-fg: var(--xh-_tone-fg, var(--xh-fg-on-brand-subtle));
    --xh-_time-picker-check-fg: var(--xh-_tone, var(--xh-fg-brand));
  }

  /* 与文本框、时间输入同一套堆叠：标签一行、控件一行 */
  [data-scope='time-picker'][data-part='root'] {
    /* 作者塞进指示符槽的图标跟着字号走，与皮肤画的兜底字形同一把尺 */
    --xh-icon-size: var(--xh-time-picker-icon-size, var(--xh-glyph-size-md));

    display: inline-flex;
    flex-direction: column;
    gap: var(--xh-time-picker-gap, var(--xh-space-1));

    /* 不传尺寸时一律这么宽，宽度不随内容走；父容器给不出这么宽时整件跟着收，地板同步让步，不越出父容器。
       地板不高过缺省宽：使用者把缺省宽钉到底线以下时不必再放开底线 */
    inline-size: var(--xh-time-picker-control-w, var(--xh-control-w));
    min-inline-size: min(var(--xh-time-picker-control-w, var(--xh-control-w)), var(--xh-time-picker-control-min-w, var(--xh-control-min-w)), 100%);
    max-inline-size: 100%;
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里 */
  [data-scope='time-picker']:is([data-part='root'], [data-part='positioner'])[data-size='sm'] {
    --xh-icon-size: var(--xh-time-picker-icon-size, var(--xh-glyph-size-sm));
    --xh-_time-picker-control-h: var(--xh-control-h-sm);
    --xh-_time-picker-control-px: var(--xh-control-px-sm);
    --xh-_time-picker-gap: var(--xh-control-gap-sm);
    --xh-_time-picker-font-size: var(--xh-control-font-sm);
  }

  [data-scope='time-picker']:is([data-part='root'], [data-part='positioner'])[data-size='lg'] {
    --xh-icon-size: var(--xh-time-picker-icon-size, var(--xh-glyph-size-lg));
    --xh-_time-picker-control-h: var(--xh-control-h-lg);
    --xh-_time-picker-control-px: var(--xh-control-px-lg);
    --xh-_time-picker-gap: var(--xh-control-gap-lg);
    --xh-_time-picker-font-size: var(--xh-control-font-lg);
  }

  /* 声明了 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='time-picker'][data-part='root'][hidden] {
    display: none;
  }

  [data-scope='time-picker'][data-part='label'] {
    color: var(--xh-time-picker-label-fg, var(--xh-fg-default));
    font-size: var(--xh-time-picker-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-time-picker-label-font-weight, var(--xh-text-label-weight));
    line-height: var(--xh-leading-none);
  }

  [data-scope='time-picker'][data-part='label'][data-disabled] {
    color: var(--xh-time-picker-label-fg-disabled, var(--xh-fg-subtle));
  }

  /* 画成一个框的是 control：几段文字、展开按钮、清空按钮要看起来是一体的，
     边框长在其中任何一个身上都会把另外几个割在框外。描边、底色、圆角、聚焦环、五态与悬停由
     Field Chrome 家族画在 control 上（焦点落在段或按钮上，家族 :focus-within 让整框亮起来）；
     组件只映射既有公开槽（shadow 缺省 none：字段静息描边式、无影）。打开中不另画环，由浮层本身承担 */
  [data-scope='time-picker'][data-part='control'] {
    --xh-field-control-height: var(--xh-time-picker-control-h, var(--xh-_time-picker-control-h));
    --xh-field-control-padding-inline: var(--xh-time-picker-control-px, var(--xh-_time-picker-control-px));
    --xh-field-control-gap: var(--xh-time-picker-control-gap, var(--xh-_time-picker-gap));
    --xh-field-control-min-inline-size: var(--xh-time-picker-control-min-w, var(--xh-control-min-w));
    --xh-field-control-radius: var(--xh-time-picker-control-radius, var(--xh-shape-control));
    --xh-field-bg-rest: var(--xh-time-picker-control-bg, var(--xh-_field-variant-bg-rest));
    --xh-field-bg-hover: var(--xh-time-picker-control-bg-hover, var(--xh-_field-variant-bg-hover));
    --xh-field-bg-read-only: var(--xh-time-picker-control-bg-readonly, var(--xh-_field-variant-bg-read-only));
    --xh-field-bg-disabled: var(--xh-time-picker-control-bg-disabled, var(--xh-_field-variant-bg-disabled));
    --xh-field-fg-rest: var(--xh-time-picker-control-fg, var(--xh-fg-default));
    --xh-field-border-rest: var(--xh-time-picker-control-border, var(--xh-_field-variant-border-rest));
    --xh-field-border-hover: var(--xh-time-picker-control-border-hover, var(--xh-_field-variant-border-hover));
    --xh-field-border-focus: var(--xh-time-picker-control-border-focus, var(--xh-_field-variant-border-focus));
    --xh-field-border-invalid: var(--xh-time-picker-control-border-invalid, var(--xh-_field-variant-border-invalid));
    --xh-field-ring-focus: var(--xh-ring-focus);
    --xh-field-ring-invalid: var(--xh-ring-invalid);
    --xh-field-shadow-rest: var(--xh-time-picker-control-shadow, none);
    /* 段位靠键盘编辑，盒上不是文本光标 */
    --xh-field-cursor-rest: default;
    /* 家族 chrome 会重写 --xh-icon-size，使用者图标槽必须经桥接槽下发才能在盒内生效 */
    --xh-field-glyph-size: var(--xh-time-picker-icon-size, var(--xh-_field-size-glyph-size));

    /* 表单控件不继承页面字体，只给字号会让它用 UA 默认字族，与周围文本对不上 */
    font-family: inherit;
    font-size: var(--xh-time-picker-font-size, var(--xh-_time-picker-font-size));
    /* 等宽数字：各位字宽不一时逐段填入会让整行左右跳 */
    font-variant-numeric: tabular-nums;
    line-height: var(--xh-leading-normal);
  }

  [data-scope='time-picker'][data-part='control'][hidden] {
    display: none;
  }

  /* 段位与作者写在段间的分隔符都在这一层里：它占满盒里剩下的宽度，
     尾部按钮因此靠在框内末端 */
  [data-scope='time-picker'][data-part='segment-group'] {
    display: inline-flex;
    flex: 1 1 auto;
    align-items: center;
    min-inline-size: 0;
  }

  [data-scope='time-picker'][data-part='segment-group'][hidden] {
    display: none;
  }

  [data-scope='time-picker'][data-part='segment-group'] > :not([data-scope]) {
    color: var(--xh-time-picker-literal-fg, var(--xh-fg-subtle));
  }

  /* 每一段是一小块可聚焦区，紧挨着排；间距长在段自己身上 */
  [data-scope='time-picker'][data-part='segment'] {
    display: inline-block;
    padding-inline: var(--xh-time-picker-segment-px, var(--xh-space-0_5));
    padding-block: 0;
    border-radius: var(--xh-time-picker-segment-radius, var(--xh-shape-inset));
    color: inherit;
    font-variant-numeric: inherit;
    text-align: center;
    /* 段是 role=spinbutton 的展示节点，双击选中一段文字只会碍事 */
    user-select: none;
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* granularity / hourCycle 关掉的段由连接层打 hidden；上面那条 display 会把 UA 规则盖掉，
     少了这条，收起的段会一直杵在那儿 */
  [data-scope='time-picker'][data-part='segment'][hidden] {
    display: none;
  }

  /* 还没填的段压成弱色：一行里哪几段是占位符，一眼要看得出来 */
  [data-scope='time-picker'][data-part='segment'][data-placeholder] {
    color: var(--xh-time-picker-placeholder-fg, var(--xh-fg-subtle));
  }

  /* 一行段长得差不多，光有边框亮起来看不出正在改哪一段：当前段必须自己有底色。
     data-focus 由机器给（它知道谁是当前段），:focus-visible 兜住机器状态还没回流的那一帧 */
  [data-scope='time-picker'][data-part='segment'][data-focus]:not([data-disabled]),
  [data-scope='time-picker'][data-part='segment']:focus-visible {
    background: var(--xh-time-picker-segment-bg-focus, var(--xh-_time-picker-segment-bg));
    color: var(--xh-time-picker-segment-fg-focus, var(--xh-_time-picker-segment-fg));
    outline: none;
  }

  /* 焦点态用了品牌底色之后，占位符那条弱色会被它盖住，这里明确让位给焦点态 */
  [data-scope='time-picker'][data-part='segment'][data-focus][data-placeholder]:not([data-disabled]) {
    color: var(--xh-time-picker-segment-fg-focus, var(--xh-_time-picker-segment-fg));
  }

  [data-scope='time-picker'][data-part='segment'][data-invalid] {
    color: var(--xh-time-picker-segment-fg-invalid, var(--xh-fg-danger));
  }

  [data-scope='time-picker'][data-part='segment'][data-invalid]:is([data-focus], :focus-visible) {
    background: var(
      --xh-time-picker-segment-bg-invalid-focus,
      var(--xh-bg-subtle)
    );
    color: var(--xh-time-picker-segment-fg-invalid-focus, var(--xh-fg-danger));
  }

  [data-scope='time-picker'][data-part='segment']:hover:not([data-focus], [data-disabled]) {
    background: var(--xh-time-picker-segment-bg-hover, var(--xh-bg-subtle));
  }

  /* 段是集合条目形态（role=spinbutton 的 span），禁用走 data-disabled 而不是 :disabled */
  [data-scope='time-picker'][data-part='segment'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 两个按钮同一副长相：贴在框内末端的小方钮，不占宽度也不撑高 control。正方视觉盒、inset 圆角、
     悬停 100 / 按下 200 与 0.97 按压、粗指针热区、禁用面与 :focus-visible 关环（盒的 :focus-within
     已画了一圈）全由 Action Control 的 field-inset ghost 档给，组件只映射既有覆盖槽。
     打开中与悬停同档：展开钮不另上底，方向由浮层本身承担 */
  [data-scope='time-picker'][data-part='trigger'],
  [data-scope='time-picker'][data-part='clear-trigger'] {
    --xh-action-visual-size: var(--xh-time-picker-action-size, var(--xh-_action-profile-visual-size));
    --xh-action-min-inline-size: var(--xh-time-picker-action-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-time-picker-action-radius, var(--xh-shape-inset));
    /* 底色阶梯由 ghost 档给（透明 → 100 → 200），使用者槽只作覆盖入口 */
    --xh-action-bg-rest: var(--xh-time-picker-action-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-time-picker-action-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-time-picker-action-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-time-picker-action-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-time-picker-action-fg-hover, var(--xh-fg-default));
    --xh-action-border-rest: transparent;
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    --xh-action-font-size: var(--xh-time-picker-action-font-size, var(--xh-text-secondary-size));
    /* 配方尚未把 profile 字形档灌进 --xh-icon-size，钮内字形先按 field-inset 档逐钮取值 */
    --xh-icon-size: var(--xh-_action-profile-glyph-size);

    border-width: 0;
  }

  /* 没值时连接层给的是 hidden 属性；家族那条 display 会把 UA 规则盖掉 */
  [data-scope='time-picker'][data-part='trigger'][hidden],
  [data-scope='time-picker'][data-part='clear-trigger'][hidden] {
    display: none;
  }

  /* 打开中与悬停同档：展开钮的静息底换到悬停那一支中性面，不用品牌色、不另画环；方向由浮层本身承担 */
  [data-scope='time-picker'][data-part='trigger'][data-state='open'] {
    --xh-action-bg-rest: var(--xh-time-picker-action-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-fg-rest: var(--xh-time-picker-action-fg-hover, var(--xh-fg-default));
  }

  /* 有值时清空钮顶上来，展开钮让位：两颗并排堆着用户分不清点哪个 */
  [data-scope='time-picker'][data-part='control']:has(
      > [data-scope='time-picker'][data-part='clear-trigger']:not([hidden])
    )
    > [data-scope='time-picker'][data-part='trigger'] {
    display: none;
  }

  /* 几列并排：整体高度由列自己撑，滚动发生在列里而不是整个面板上——
     整面板滚会让时列与分列一起走，挑分的时候时就看不见了。
     含多列的锚定面板走 floating 材质：实体底 + --xh-border-default 描边 + --xh-elevation-floating 落影，
     不透景、不画顶光 */
  [data-scope='time-picker'][data-part='content'] {
    position: relative;
    display: flex;
    align-items: stretch;
    padding-block: var(--xh-time-picker-content-py, var(--xh-space-1));
    padding-inline: var(--xh-time-picker-content-px, var(--xh-space-1));
    /* 列自己定高，面板整体不该再长过页内滚动面那一档 */
    max-block-size: var(--xh-time-picker-content-max-h, var(--xh-viewport-h-lg));
    border: var(--xh-stroke-thin) solid var(--xh-time-picker-content-border, var(--xh-border-default));
    border-radius: var(--xh-time-picker-content-radius, var(--xh-shape-overlay));
    background: var(--xh-time-picker-content-bg, var(--xh-bg-surface));
    color: var(--xh-time-picker-content-fg, var(--xh-fg-default));
    font-variant-numeric: tabular-nums;
    box-shadow: var(--xh-time-picker-content-shadow, var(--xh-elevation-floating));
    pointer-events: auto;
    /* 快捷选项列与各时间列的条子贴在各自的盒子上、挂在这一层里（它已是定位盒）：轨道不画底 */
    --xh-scrollbar-track-bg: transparent;
  }

  /* 这里刻意没有 [data-part='content'][hidden] { display: none }，与 dialog 一致：
     收起态连接层会给 content 打 hidden，而上面那条 display 正是要盖掉 UA 的
     [hidden]{display:none}——退场动画得先能播。presence 读的是 content 的 animationName，
     真正的收起由宿主在退场结束后落成内联 display:none（Vue 那边直接不渲染）。
     其余声明了 display 的角色节点仍补 [hidden]，那几处没有退场动画。 */

  /* 面板本身不承载焦点（焦点在某一列的某一格上），落焦时不画环 */
  [data-scope='time-picker'][data-part='content']:focus-visible {
    outline: none;
  }

  [data-scope='time-picker'][data-part='content'][data-state='open'] {
    animation: xh-overlay-slide-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 退场：收起那一帧 hidden 由退场闸门押后，这里才播得出来。forwards 把末态钉住，
     免得动画结束到真收起之间闪一下原样 */
  [data-scope='time-picker'][data-part='content'][data-state='closed'] {
    animation: xh-overlay-slide-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* 快捷选项也是一列，与时分秒那几列并排，排在行内起始一侧 */
  [data-scope='time-picker'][data-part='preset-group'] {
    display: flex;
    flex: none;
    flex-direction: column;
    gap: var(--xh-time-picker-preset-group-gap, var(--xh-list-option-gap));
    max-block-size: var(--xh-time-picker-preset-group-h, var(--xh-viewport-h-sm));
    padding-inline: var(--xh-time-picker-preset-group-px, var(--xh-space-1));
    overflow-y: auto;
    /* 浮层滚动面：滚到头不把页面一起带走 */
    overscroll-behavior: contain;
    border-inline-end: var(--xh-stroke-thin) solid var(--xh-time-picker-column-divider, var(--xh-material-frosted-separator));
  }

  [data-scope='time-picker'][data-part='preset-group'][hidden] {
    display: none;
  }

  /* 快捷选项：悬停 / 高亮 100、按下 200、禁用面由 Collection Item 家族按 overlay 语境给（选中 = 透明底 +
