/* styles/time-range-picker.css */
/* TimeRangePicker 独立皮肤同时传递引入字段视觉盒、字段内动作与浮层集合行；full bundle 递归去重。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='time-range-picker'] {
    --xh-time-range-picker-skin: 1;
  }

  /* 坐标由定位引擎写进 style（inset-inline-start / inset-block-start），这里只定位模式与层级 */
  [data-scope='time-range-picker'][data-part='positioner'] {
    /* 落定那一侧的可用宽度，由定位引擎经内联自定义属性写进来，内容层据此夹住行内轴；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时退到视口宽 */
    --xh-_time-range-picker-available-w: 100vw;

    /* 每个浮层独立声明方向，避免嵌套浮层继承祖先的进场位移。 */
    --xh-_overlay-enter-up: 0;
    --xh-_overlay-enter-down: 0;
    --xh-_overlay-enter-left: 0;
    --xh-_overlay-enter-right: 0;

    /* 面板的自绘横条浮在内容之上：轨道不上底色，实色轨道会在面板底缘糊出一条灰带 */
    --xh-scrollbar-track-bg: transparent;

    position: fixed;
    z-index: var(--xh-time-range-picker-layer, var(--xh-_layer, var(--xh-layer-popover)));
    /* 空壳不吃指针，交互只发生在 content 里 */
    pointer-events: none;
  }

  /* 锚点被滚出可视区：整个浮层随之收起 */
  [data-scope='time-range-picker'][data-part='positioner'][data-hidden] {
    visibility: hidden;
  }

  /* 短位移沿实际落位的物理方向，不随书写方向翻转。 */
  [data-scope='time-range-picker'][data-part='positioner'][data-placement^='top'] {
    --xh-_overlay-enter-down: 1;
  }

  [data-scope='time-range-picker'][data-part='positioner'][data-placement^='bottom'] {
    --xh-_overlay-enter-up: 1;
  }

  [data-scope='time-range-picker'][data-part='positioner'][data-placement^='left'] {
    --xh-_overlay-enter-right: 1;
  }

  [data-scope='time-range-picker'][data-part='positioner'][data-placement^='right'] {
    --xh-_overlay-enter-left: 1;
  }

