    --xh-_time-range-picker-segment-bg: var(--xh-_tone-subtle, var(--xh-bg-brand-subtle));
    --xh-_time-range-picker-segment-fg: var(--xh-_tone-fg, var(--xh-fg-on-brand-subtle));
    --xh-_time-range-picker-check-fg: var(--xh-_tone, var(--xh-fg-brand));
