    inline-size: var(--xh-time-range-picker-control-w, var(--xh-control-w));
    min-inline-size: min(var(--xh-time-range-picker-control-w, var(--xh-control-w)), var(--xh-time-range-picker-control-min-w, var(--xh-control-min-w)), 100%);
    max-inline-size: 100%;
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里 */
  [data-scope='time-range-picker']:is([data-part='root'], [data-part='positioner'])[data-size='sm'] {
    --xh-icon-size: var(--xh-time-range-picker-icon-size, var(--xh-glyph-size-sm));
    --xh-_time-range-picker-control-h: var(--xh-control-h-sm);
    --xh-_time-range-picker-control-px: var(--xh-control-px-sm);
    --xh-_time-range-picker-gap: var(--xh-control-gap-sm);
    --xh-_time-range-picker-font-size: var(--xh-control-font-sm);
  }

  [data-scope='time-range-picker']:is([data-part='root'], [data-part='positioner'])[data-size='lg'] {
    --xh-icon-size: var(--xh-time-range-picker-icon-size, var(--xh-glyph-size-lg));
    --xh-_time-range-picker-control-h: var(--xh-control-h-lg);
    --xh-_time-range-picker-control-px: var(--xh-control-px-lg);
    --xh-_time-range-picker-gap: var(--xh-control-gap-lg);
    --xh-_time-range-picker-font-size: var(--xh-control-font-lg);
  }

  /* 声明了 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去 */
  [data-scope='time-range-picker'][data-part='root'][hidden] {
    display: none;
  }

  [data-scope='time-range-picker'][data-part='label'] {
    color: var(--xh-time-range-picker-label-fg, var(--xh-fg-default));
    font-size: var(--xh-time-range-picker-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-time-range-picker-label-font-weight, var(--xh-text-label-weight));
    line-height: var(--xh-leading-none);
  }

  [data-scope='time-range-picker'][data-part='label'][data-disabled] {
    color: var(--xh-time-range-picker-label-fg-disabled, var(--xh-fg-subtle));
  }

  /* 画成一个框的是 control：几段文字、展开按钮、清空按钮要看起来是一体的，
     边框长在其中任何一个身上都会把另外几个割在框外。描边、底色、圆角、聚焦环、五态与悬停由
     Field Chrome 家族画在 control 上（焦点落在段或按钮上，家族 :focus-within 让整框亮起来）；
     组件只映射既有公开槽（shadow 缺省 none：字段静息描边式、无影）。打开中不另画环，由浮层本身承担 */
  [data-scope='time-range-picker'][data-part='control'] {
    --xh-field-control-height: var(--xh-time-range-picker-control-h, var(--xh-_time-range-picker-control-h));
    --xh-field-control-padding-inline: var(--xh-time-range-picker-control-px, var(--xh-_time-range-picker-control-px));
    --xh-field-control-gap: var(--xh-time-range-picker-control-gap, var(--xh-_time-range-picker-gap));
    --xh-field-control-min-inline-size: var(--xh-time-range-picker-control-min-w, var(--xh-control-min-w));
    --xh-field-control-radius: var(--xh-time-range-picker-control-radius, var(--xh-shape-control));
    --xh-field-bg-rest: var(--xh-time-range-picker-control-bg, var(--xh-_field-variant-bg-rest));
    --xh-field-bg-hover: var(--xh-time-range-picker-control-bg-hover, var(--xh-_field-variant-bg-hover));
    --xh-field-bg-read-only: var(--xh-time-range-picker-control-bg-readonly, var(--xh-_field-variant-bg-read-only));
    --xh-field-bg-disabled: var(--xh-time-range-picker-control-bg-disabled, var(--xh-_field-variant-bg-disabled));
    --xh-field-fg-rest: var(--xh-time-range-picker-control-fg, var(--xh-fg-default));
    --xh-field-border-rest: var(--xh-time-range-picker-control-border, var(--xh-_field-variant-border-rest));
    --xh-field-border-hover: var(--xh-time-range-picker-control-border-hover, var(--xh-_field-variant-border-hover));
    --xh-field-border-focus: var(--xh-time-range-picker-control-border-focus, var(--xh-_field-variant-border-focus));
    --xh-field-border-invalid: var(--xh-time-range-picker-control-border-invalid, var(--xh-_field-variant-border-invalid));
    --xh-field-ring-focus: var(--xh-ring-focus);
    --xh-field-ring-invalid: var(--xh-ring-invalid);
    --xh-field-shadow-rest: var(--xh-time-range-picker-control-shadow, none);
    /* 段位靠键盘编辑，盒上不是文本光标 */
    --xh-field-cursor-rest: default;
    /* 家族 chrome 会重写 --xh-icon-size，使用者图标槽必须经桥接槽下发才能在盒内生效 */
    --xh-field-glyph-size: var(--xh-time-range-picker-icon-size, var(--xh-_field-size-glyph-size));

    /* 表单控件不继承页面字体，只给字号会让它用 UA 默认字族，与周围文本对不上 */
    font-family: inherit;
    font-size: var(--xh-time-range-picker-font-size, var(--xh-_time-range-picker-font-size));
    /* 等宽数字：各位字宽不一时逐段填入会让整行左右跳 */
    font-variant-numeric: tabular-nums;
    line-height: var(--xh-leading-normal);
  }

  [data-scope='time-range-picker'][data-part='control'][hidden] {
    display: none;
  }

  /* 起止各一组段位与作者写在段间的分隔符都在各自这一层里：起点那组只占自己的宽度，
     分隔符紧跟在它后面，剩下的宽度全给终点那组，尾部按钮因此靠在框内末端 */
  [data-scope='time-range-picker'][data-part='segment-group'] {
    display: inline-flex;
    flex: 1 1 auto;
    align-items: center;
    min-inline-size: 0;
  }

  [data-scope='time-range-picker'][data-part='segment-group'][data-index='0']:has(+ [data-part='range-separator']) {
    flex: 0 0 auto;
  }

  [data-scope='time-range-picker'][data-part='segment-group'][hidden] {
    display: none;
  }

  [data-scope='time-range-picker'][data-part='range-separator'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    /* 两侧各留一个小间距：把输入行的常规间距收回来，再补上自己那一份 */
    --xh-_time-range-picker-range-separator-mx: calc(var(--xh-time-range-picker-range-separator-px, var(--xh-space-1)) - var(--xh-time-range-picker-control-gap, var(--xh-_time-range-picker-gap)));

    margin-inline: var(--xh-time-range-picker-range-separator-mx, var(--xh-_time-range-picker-range-separator-mx));
    padding-inline: var(--xh-time-range-picker-range-separator-px, var(--xh-space-1));
    color: var(--xh-time-range-picker-range-separator-fg, var(--xh-fg-subtle));
    font: inherit;
    line-height: var(--xh-leading-none);
    pointer-events: none;
    user-select: none;
  }

  /* 作者自己给分隔符加 hidden 时也真的收起：上面那条 display 会盖掉 UA 的兜底 */
  [data-scope='time-range-picker'][data-part='range-separator'][hidden] {
    display: none;
  }

  [data-scope='time-range-picker'][data-part='segment-group'] > :not([data-scope]) {
    color: var(--xh-time-range-picker-literal-fg, var(--xh-fg-subtle));
  }

  /* 每一段是一小块可聚焦区，紧挨着排；间距长在段自己身上 */
  [data-scope='time-range-picker'][data-part='segment'] {
    display: inline-block;
    padding-inline: var(--xh-time-range-picker-segment-px, var(--xh-space-0_5));
    padding-block: 0;
    border-radius: var(--xh-time-range-picker-segment-radius, var(--xh-shape-inset));
    color: inherit;
    font-variant-numeric: inherit;
    text-align: center;
    /* 段是 role=spinbutton 的展示节点，双击选中一段文字只会碍事 */
    user-select: none;
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* granularity / hourCycle 关掉的段由连接层打 hidden；上面那条 display 会把 UA 规则盖掉，
     少了这条，收起的段会一直杵在那儿 */
  [data-scope='time-range-picker'][data-part='segment'][hidden] {
    display: none;
  }

  /* 还没填的段压成弱色：一行里哪几段是占位符，一眼要看得出来 */
  [data-scope='time-range-picker'][data-part='segment'][data-placeholder] {
    color: var(--xh-time-range-picker-placeholder-fg, var(--xh-fg-subtle));
  }

  /* 一行段长得差不多，光有边框亮起来看不出正在改哪一段：当前段必须自己有底色。
     data-focus 由机器给（它知道谁是当前段），:focus-visible 兜住机器状态还没回流的那一帧 */
  [data-scope='time-range-picker'][data-part='segment'][data-focus]:not([data-disabled]),
  [data-scope='time-range-picker'][data-part='segment']:focus-visible {
    background: var(--xh-time-range-picker-segment-bg-focus, var(--xh-_time-range-picker-segment-bg));
    color: var(--xh-time-range-picker-segment-fg-focus, var(--xh-_time-range-picker-segment-fg));
    outline: none;
  }

  /* 焦点态用了品牌底色之后，占位符那条弱色会被它盖住，这里明确让位给焦点态 */
  [data-scope='time-range-picker'][data-part='segment'][data-focus][data-placeholder]:not([data-disabled]) {
    color: var(--xh-time-range-picker-segment-fg-focus, var(--xh-_time-range-picker-segment-fg));
  }

  [data-scope='time-range-picker'][data-part='segment'][data-invalid] {
    color: var(--xh-time-range-picker-segment-fg-invalid, var(--xh-fg-danger));
  }

  [data-scope='time-range-picker'][data-part='segment'][data-invalid]:is([data-focus], :focus-visible) {
    background: var(
      --xh-time-range-picker-segment-bg-invalid-focus,
      var(--xh-bg-subtle)
    );
    color: var(--xh-time-range-picker-segment-fg-invalid-focus, var(--xh-fg-danger));
  }

  [data-scope='time-range-picker'][data-part='segment']:hover:not([data-focus], [data-disabled]) {
    background: var(--xh-time-range-picker-segment-bg-hover, var(--xh-bg-subtle));
  }

  /* 段是集合条目形态（role=spinbutton 的 span），禁用走 data-disabled 而不是 :disabled */
  [data-scope='time-range-picker'][data-part='segment'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 两个按钮同一副长相：贴在框内末端的小方钮，不占宽度也不撑高 control。正方视觉盒、inset 圆角、
     悬停 100 / 按下 200 与 0.97 按压、粗指针热区、禁用面与 :focus-visible 关环（盒的 :focus-within
     已画了一圈）全由 Action Control 的 field-inset ghost 档给，组件只映射既有覆盖槽。
     打开中与悬停同档：展开钮不另上底，方向由浮层本身承担 */
  [data-scope='time-range-picker'][data-part='trigger'],
  [data-scope='time-range-picker'][data-part='clear-trigger'] {
    --xh-action-visual-size: var(--xh-time-range-picker-action-size, var(--xh-_action-profile-visual-size));
    --xh-action-min-inline-size: var(--xh-time-range-picker-action-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-time-range-picker-action-radius, var(--xh-shape-inset));
    /* 底色阶梯由 ghost 档给（透明 → 100 → 200），使用者槽只作覆盖入口 */
    --xh-action-bg-rest: var(--xh-time-range-picker-action-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-time-range-picker-action-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-time-range-picker-action-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-time-range-picker-action-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-time-range-picker-action-fg-hover, var(--xh-fg-default));
    --xh-action-border-rest: transparent;
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    --xh-action-font-size: var(--xh-time-range-picker-action-font-size, var(--xh-text-secondary-size));
    /* 配方尚未把 profile 字形档灌进 --xh-icon-size，钮内字形先按 field-inset 档逐钮取值 */
    --xh-icon-size: var(--xh-_action-profile-glyph-size);

    border-width: 0;
  }

  /* 没值时连接层给的是 hidden 属性；家族那条 display 会把 UA 规则盖掉 */
  [data-scope='time-range-picker'][data-part='trigger'][hidden],
  [data-scope='time-range-picker'][data-part='clear-trigger'][hidden] {
    display: none;
  }

  /* 打开中与悬停同档：展开钮的静息底换到悬停那一支中性面，不用品牌色、不另画环；方向由浮层本身承担 */
  [data-scope='time-range-picker'][data-part='trigger'][data-state='open'] {
    --xh-action-bg-rest: var(--xh-time-range-picker-action-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-fg-rest: var(--xh-time-range-picker-action-fg-hover, var(--xh-fg-default));
  }

  /* 有值时清空钮顶上来，展开钮让位：两颗并排堆着用户分不清点哪个 */
  [data-scope='time-range-picker'][data-part='control']:has(
      > [data-scope='time-range-picker'][data-part='clear-trigger']:not([hidden])
    )
    > [data-scope='time-range-picker'][data-part='trigger'] {
    display: none;
  }

  /* 几列并排：整体高度由列自己撑，滚动发生在列里而不是整个面板上——
     整面板滚会让时列与分列一起走，挑分的时候时就看不见了。
     含多列的锚定面板走 floating 材质：实体底 + --xh-border-default 描边 + --xh-elevation-floating 落影，
     不透景、不画顶光 */
  [data-scope='time-range-picker'][data-part='content'] {
    position: relative;
    display: flex;
    align-items: stretch;
    padding-block: var(--xh-time-range-picker-content-py, var(--xh-space-2));
    padding-inline: var(--xh-time-range-picker-content-px, var(--xh-space-2));
    /* 行内轴的上限是落位后的可用宽度：两组时列并排，秒与上下午都开时八列合计会越过最窄视口，
       放不下时面板内自己横滚，每一列保持自己的宽度不被压 */
    max-inline-size: var(--xh-_time-range-picker-available-w);
    overflow-x: auto;
    /* 浮层滚动面：滚到头不把页面一起带走 */
    overscroll-behavior: contain;
    /* 列自己定高，面板整体不该再长过页内滚动面那一档 */
    max-block-size: var(--xh-time-range-picker-content-max-h, var(--xh-viewport-h-lg));
    border: var(--xh-stroke-thin) solid var(--xh-time-range-picker-content-border, var(--xh-border-default));
    border-radius: var(--xh-time-range-picker-content-radius, var(--xh-shape-overlay));
    background: var(--xh-time-range-picker-content-bg, var(--xh-bg-surface));
    color: var(--xh-time-range-picker-content-fg, var(--xh-fg-default));
    font-variant-numeric: tabular-nums;
    box-shadow: var(--xh-time-range-picker-content-shadow, var(--xh-elevation-floating));
    pointer-events: auto;
    /* 快捷选项列与各时间列的条子贴在各自的盒子上、挂在这一层里（它已是定位盒）：轨道不画底 */
    --xh-scrollbar-track-bg: transparent;
  }

  /* 这里刻意没有 [data-part='content'][hidden] { display: none }，与 dialog 一致：
     收起态连接层会给 content 打 hidden，而上面那条 display 正是要盖掉 UA 的
     [hidden]{display:none}——退场动画得先能播。presence 读的是 content 的 animationName，
     真正的收起由宿主在退场结束后落成内联 display:none（Vue 那边直接不渲染）。
     其余声明了 display 的角色节点仍补 [hidden]，那几处没有退场动画。 */

  /* 面板本身不承载焦点（焦点在某一列的某一格上），落焦时不画环 */
  [data-scope='time-range-picker'][data-part='content']:focus-visible {
    outline: none;
  }

  [data-scope='time-range-picker'][data-part='content'][data-state='open'] {
    animation: xh-overlay-slide-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 退场：收起那一帧 hidden 由退场闸门押后，这里才播得出来。forwards 把末态钉住，
     免得动画结束到真收起之间闪一下原样 */
  [data-scope='time-range-picker'][data-part='content'][data-state='closed'] {
    animation: xh-overlay-slide-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* 快捷选项也是一列，与时分秒那几列并排，排在行内起始一侧 */
  [data-scope='time-range-picker'][data-part='preset-group'] {
    display: flex;
    flex: none;
    flex-direction: column;
    gap: var(--xh-time-range-picker-preset-group-gap, var(--xh-list-option-gap));
    max-block-size: var(--xh-time-range-picker-preset-group-h, var(--xh-viewport-h-sm));
    padding-inline: var(--xh-time-range-picker-preset-group-px, var(--xh-space-1));
    overflow-y: auto;
    /* 浮层滚动面：滚到头不把页面一起带走 */
    overscroll-behavior: contain;
    border-inline-end: var(--xh-stroke-thin) solid var(--xh-time-range-picker-column-divider, var(--xh-material-frosted-separator));
  }

  [data-scope='time-range-picker'][data-part='preset-group'][hidden] {
    display: none;
  }

  /* 快捷选项：悬停 / 高亮 100、按下 200、禁用面由 Collection Item 家族按 overlay 语境给（选中 = 透明底 +
     行尾对号，正文保持 rest 色与常规字重）。选项没有正文部件，匿名文本进不了家族网格的 text 列，
     行保持块级排版，末端为对号预留固定轨 */
  [data-scope='time-range-picker'][data-part='preset'] {
    --xh-collection-block-padding: var(--xh-time-range-picker-preset-py, var(--xh-space-1));
    --xh-collection-inline-padding: var(--xh-time-range-picker-preset-px, var(--xh-space-3));
    --xh-collection-font-size: var(--xh-text-secondary-size);
    --xh-collection-radius: var(--xh-time-range-picker-preset-radius, var(--xh-shape-control));
    /* 面板是实体面（floating），正文取页面前景 */
    --xh-collection-fg-rest: var(--xh-time-range-picker-preset-fg, var(--xh-fg-default));
    --xh-collection-fg-hover: var(--xh-time-range-picker-preset-fg, var(--xh-fg-default));
    --xh-collection-fg-keyboard-highlight: var(--xh-time-range-picker-preset-fg, var(--xh-fg-default));
    --xh-collection-fg-pressed: var(--xh-time-range-picker-preset-fg, var(--xh-fg-default));
    --xh-collection-fg-selected: var(--xh-time-range-picker-preset-fg-checked, var(--xh-time-range-picker-preset-fg, var(--xh-fg-default)));
    --xh-collection-fg-selected-highlight: var(--xh-time-range-picker-preset-fg-checked, var(--xh-time-range-picker-preset-fg, var(--xh-fg-default)));
    --xh-collection-fg-selected-hover: var(--xh-time-range-picker-preset-fg-checked, var(--xh-time-range-picker-preset-fg, var(--xh-fg-default)));
    --xh-collection-fg-selected-pressed: var(--xh-time-range-picker-preset-fg-checked, var(--xh-time-range-picker-preset-fg, var(--xh-fg-default)));
    --xh-collection-fg-disabled: var(--xh-time-range-picker-preset-fg-disabled, var(--xh-fg-disabled));
    --xh-collection-bg-hover: var(--xh-time-range-picker-preset-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-keyboard-highlight: var(--xh-time-range-picker-preset-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-selected-highlight: var(--xh-time-range-picker-preset-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-selected-hover: var(--xh-time-range-picker-preset-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-pressed: var(--xh-time-range-picker-preset-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-bg-selected-pressed: var(--xh-time-range-picker-preset-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-outline-keyboard-highlight: transparent;
    --xh-collection-outline-selected-highlight: transparent;

    position: relative;
    display: block;
    flex: none;
    /* 对号的末端轨始终留着，切换选中时文字与整列宽度都不移动。 */
    padding-inline-end: calc(
      var(--xh-time-range-picker-preset-px, var(--xh-space-3))
      + var(--xh-time-range-picker-preset-check-size, var(--xh-glyph-size-sm))
      + var(--xh-space-1)
    );
    white-space: nowrap;
    user-select: none;
  }

  /* 键盘焦点出现时环才接回并立即到位，不压在背景过渡的中间帧上 */
  [data-scope='time-range-picker'][data-part='preset']:focus-visible:not(:hover) {
    --xh-collection-outline-keyboard-highlight: var(--xh-ring-focus);
    --xh-collection-outline-selected-highlight: var(--xh-ring-focus);

    transition: none;
  }

  /* 对号是 preset 自身的正式选中出口：全部条目恒留末端轨，不依赖作者补节点。 */
  [data-scope='time-range-picker'][data-part='preset']::after {
    content: '';
    position: absolute;
    inset-block-start: 50%;
    inset-inline-end: var(--xh-time-range-picker-preset-px, var(--xh-space-3));
    inline-size: var(--xh-time-range-picker-preset-check-size, var(--xh-glyph-size-sm));
    block-size: var(--xh-time-range-picker-preset-check-size, var(--xh-glyph-size-sm));
    background-color: var(--xh-time-range-picker-preset-check-fg, var(--xh-_time-range-picker-check-fg));
    opacity: 0;
    translate: 0 -50%;
    -webkit-mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    pointer-events: none;
    transition: opacity var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 命中只显示对号；正文不反白、不增重，底色通道留给临时交互状态。 */
  [data-scope='time-range-picker'][data-part='preset'][data-state='checked']::after {
    opacity: 1;
  }

  /* 上面给了 display，UA 的 [hidden]{display:none} 已被盖掉，这里补回来 */
  [data-scope='time-range-picker'][data-part='preset'][hidden] {
    display: none;
  }

  [data-scope='time-range-picker'][data-part='preset'][data-disabled]::after {
    background-color: var(--xh-time-range-picker-preset-fg-disabled, var(--xh-fg-disabled));
  }

  /* 一端的几列成组并排，小标题独占顶上一行；两组之间留一道更宽的分隔，眼睛先分起止、再分时分 */
  [data-scope='time-range-picker'][data-part='column-group'] {
    --xh-_time-range-picker-column-group-label-py: var(
      --xh-time-range-picker-column-group-py,
      var(--xh-time-range-picker-column-group-label-py, var(--xh-space-1))
    );
    --xh-_time-range-picker-column-group-label-h: calc(
      1lh
      + var(--xh-_time-range-picker-column-group-label-py)
      + var(--xh-_time-range-picker-column-group-label-py)
    );

    position: relative;
    display: flex;
    flex: none;
    flex-wrap: nowrap;
    align-content: flex-start;
    align-items: stretch;
    min-inline-size: 0;
    padding-block-start: var(--xh-_time-range-picker-column-group-label-h);
    font-size: var(--xh-text-caption-size);
    line-height: var(--xh-leading-normal);
  }

  [data-scope='time-range-picker'][data-part='column-group'][hidden] {
    display: none;
  }

  [data-scope='time-range-picker'][data-part='column-group'] + [data-scope='time-range-picker'][data-part='column-group'] {
    margin-inline-start: var(--xh-time-range-picker-column-group-gap, var(--xh-space-2));
    padding-inline-start: var(--xh-time-range-picker-column-group-gap, var(--xh-space-2));
    border-inline-start: var(--xh-stroke-thin) solid var(--xh-time-range-picker-column-group-divider, var(--xh-material-frosted-separator));
  }

  /* 组顶上的小标题：独占一行，字号走辅助文本档 */
  [data-scope='time-range-picker'][data-part='column-group-label'] {
    position: absolute;
    inset-block-start: 0;
    inset-inline: 0;
    display: flex;
    box-sizing: border-box;
    align-items: center;
    justify-content: center;
    block-size: var(--xh-_time-range-picker-column-group-label-h);
    padding-block: var(--xh-time-range-picker-column-group-label-py, var(--xh-space-1));
    padding-inline: var(--xh-time-range-picker-column-group-label-px, var(--xh-space-1));
    color: var(--xh-time-range-picker-column-group-label-fg, var(--xh-fg-subtle));
    font-size: var(--xh-text-caption-size);
    line-height: var(--xh-leading-normal);
    text-align: center;
    user-select: none;
  }

  [data-scope='time-range-picker'][data-part='column-group-label'][hidden] {
    display: none;
  }

  /* 一列一个滚动区：列与列之间用细分隔线，视觉上"时 | 分 | 秒"三栏分明 */
  [data-scope='time-range-picker'][data-part='column'] {
    display: flex;
    flex: none;
    flex-direction: column;
    gap: var(--xh-time-range-picker-column-gap, 0);
    min-inline-size: var(--xh-time-range-picker-column-min-w, var(--xh-overlay-column-min-w));
    /* 几列并排：定高而不是随内容收，否则时列与分列的可选值一多一少就错位 */
    block-size: var(--xh-time-range-picker-column-h, var(--xh-viewport-h-sm));
    padding-inline: var(--xh-time-range-picker-column-px, 0);
    overflow-y: auto;
    /* 浮层滚动面：滚到头不把页面一起带走 */
    overscroll-behavior: contain;
    /* 滚动容器在某些浏览器里会被自动塞进 Tab 序列，是否画环见下方按 tabindex 分档的两条 */
  }

  /* granularity 关掉的列（精度不到秒时的秒列）由连接层打 hidden */
  [data-scope='time-range-picker'][data-part='column'][hidden] {
    display: none;
  }

  /* 每列后面紧跟着它自己的贴层条子节点，相邻选择器接不到下一列，按「前面有过列」取第二列起 */
  [data-scope='time-range-picker'][data-part='column'] ~ [data-scope='time-range-picker'][data-part='column'] {
    border-inline-start: var(--xh-stroke-thin) solid var(--xh-time-range-picker-column-divider, var(--xh-material-frosted-separator));
  }

  /* 焦点落在列上有两种情形：指针打开、这一段还空着、还没有任何格当锚点，或整列被界裁空。
     那一刻它认领着 Tab 位，环画在列内沿；有锚点时环长在格上，列不再画 */
  [data-scope='time-range-picker'][data-part='column'][tabindex='0']:focus-visible {
    outline: var(--xh-ring-width) solid var(--xh-ring-focus);
    outline-offset: var(--xh-ring-offset);
  }

  [data-scope='time-range-picker'][data-part='column']:not([tabindex='0']):focus-visible {
    outline: none;
  }

  /* 时间格：悬停 / 高亮 100、按下 200 由 Collection Item 家族按 overlay 语境给，选中只留末端对号——
     浮层瞬态集合的选中不上品牌淡底、不加粗、不变字色。格里只有数字、没有正文部件，保持自己的
     居中排版与等宽标记轨，家族只给状态面。行的字色与字重按值选择族的同一套映射写（--xh-time-range-picker-item-fg
     / -fg-selected / -font-weight-selected 使用者槽，缺省落家族配方的行字色 --xh-material-frosted-fg：
     它在各主题与 forced-colors 下都等于 --xh-fg-default，floating 面板上的面色仍由 content 自己给） */
  [data-scope='time-range-picker'][data-part='item'] {
    --xh-_time-range-picker-item-rail: max(
      var(--xh-time-range-picker-item-px, var(--xh-space-0_5)),
      calc(var(--xh-time-range-picker-item-check-size, var(--xh-glyph-size-sm)) + var(--xh-space-0_5))
    );
    --xh-collection-block-padding: var(--xh-time-range-picker-item-py, 0);
    /* 两侧留同宽轨：对号绝对落在末端，数字仍在整格的数学中心。 */
    --xh-collection-inline-padding: var(--xh-_time-range-picker-item-rail);
    --xh-collection-font-size: var(--xh-time-range-picker-item-font-size, var(--xh-_time-range-picker-font-size));
    --xh-collection-radius: var(--xh-time-range-picker-item-radius, var(--xh-shape-control));
    --xh-collection-fg-rest: var(--xh-time-range-picker-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-hover: var(--xh-time-range-picker-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-keyboard-highlight: var(--xh-time-range-picker-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-pressed: var(--xh-time-range-picker-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-selected: var(--xh-time-range-picker-item-fg-selected, var(--xh-time-range-picker-item-fg, var(--xh-material-frosted-fg)));
    --xh-collection-fg-selected-highlight: var(--xh-time-range-picker-item-fg-selected, var(--xh-time-range-picker-item-fg, var(--xh-material-frosted-fg)));
    --xh-collection-fg-selected-hover: var(--xh-time-range-picker-item-fg-selected, var(--xh-time-range-picker-item-fg, var(--xh-material-frosted-fg)));
    --xh-collection-fg-selected-pressed: var(--xh-time-range-picker-item-fg-selected, var(--xh-time-range-picker-item-fg, var(--xh-material-frosted-fg)));
    --xh-collection-font-weight-selected: var(--xh-time-range-picker-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-font-weight-selected-highlight: var(--xh-time-range-picker-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-font-weight-selected-hover: var(--xh-time-range-picker-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-font-weight-selected-pressed: var(--xh-time-range-picker-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-bg-hover: var(--xh-time-range-picker-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-keyboard-highlight: var(--xh-time-range-picker-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-selected-highlight: var(--xh-time-range-picker-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-selected-hover: var(--xh-time-range-picker-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-pressed: var(--xh-time-range-picker-item-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-bg-selected-pressed: var(--xh-time-range-picker-item-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-outline-keyboard-highlight: transparent;
    --xh-collection-outline-selected-highlight: transparent;

    position: relative;
    display: flex;
    flex: none;
    align-items: center;
    justify-content: center;
    block-size: var(--xh-time-range-picker-item-h, var(--xh-overlay-column-item-h));
    /* 居中的单个数字格没有截断层，行高保持紧排，列内多露几格 */
    line-height: var(--xh-leading-none);
    white-space: nowrap;
    user-select: none;
  }

  /* 键盘焦点出现时环才接回并立即到位，不压在背景过渡的中间帧上 */
  [data-scope='time-range-picker'][data-part='item']:focus-visible:not(:hover) {
    --xh-collection-outline-keyboard-highlight: var(--xh-ring-focus);
    --xh-collection-outline-selected-highlight: var(--xh-ring-focus);

    transition: none;
  }

  /* 作者自己藏掉某几格时要让位，有 display 就得补这条 */
  [data-scope='time-range-picker'][data-part='item'][hidden] {
    display: none;
  }

  [data-scope='time-range-picker'][data-part='item']::after {
    content: '';
    position: absolute;
    inset-block-start: 50%;
    inset-inline-end: var(--xh-space-0_5);
    inline-size: var(--xh-time-range-picker-item-check-size, var(--xh-glyph-size-sm));
    block-size: var(--xh-time-range-picker-item-check-size, var(--xh-glyph-size-sm));
    background-color: var(--xh-time-range-picker-item-check-fg, var(--xh-_time-range-picker-check-fg));
    opacity: 0;
    translate: 0 -50%;
    -webkit-mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    pointer-events: none;
    transition: opacity var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 选中只画对号，正文与静止底保持普通态；悬停 / 高亮 / 按下面由家族给 */
  [data-scope='time-range-picker'][data-part='item'][data-state='checked']::after {
    opacity: 1;
  }

  /* 禁用走 aria-disabled 而非原生 disabled，家族按 aria-disabled 给禁用面；标记跟着降级 */
  [data-scope='time-range-picker'][data-part='item'][data-disabled]::after {
    background-color: var(--xh-fg-disabled);
  }

  @media (forced-colors: active) {
    [data-scope='time-range-picker'][data-part='segment'][data-invalid]:is([data-focus], :focus-visible) {
      outline: var(--xh-ring-width) solid Highlight;
      outline-offset: var(--xh-ring-offset);
    }

    /* mask 保留对号轮廓，系统色接管墨色；关闭自动调整避免伪元素底被系统抹成透明。 */
    [data-scope='time-range-picker'][data-part='preset']::after,
    [data-scope='time-range-picker'][data-part='item']::after {
      background-color: CanvasText;
      forced-color-adjust: none;
    }

    [data-scope='time-range-picker'][data-part='preset'][data-disabled]::after,
    [data-scope='time-range-picker'][data-part='item'][data-disabled]::after {
      background-color: GrayText;
    }
  }

  /* 连接层把它写成 type=hidden，UA 自己就不渲染；这里的视觉隐藏是给元素升级前那一瞬兜底
     （作者手写的是一个普通 input，升级完成前它是可见的文本框）。
     刻意不写 display：写了反而会盖掉 UA 对 type=hidden 的收起，把它显出来 */
  [data-scope='time-range-picker'][data-part='hidden-input'] {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    border: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    pointer-events: none;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中 */
  [data-scope='time-range-picker'][data-part='clear-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }

  [data-scope='time-range-picker'][data-part='trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-clock) center / contain no-repeat;
    mask: var(--xh-glyph-mark-clock) center / contain no-repeat;
  }
}

@layer xihan.motion {
  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。 */
    [data-scope='time-range-picker'][data-part='positioner'] {
      display: none;
    }
  }
}

/* styles/toast.css */
/* 定义 toast 样式。 */

/* Toast 独立皮肤同时传递引入操作 / 关闭钮的动作控件配方；full bundle 递归去重。 */

@layer xihan.motion {
  /* 新条目从视口边缘外进入，同时落到自己的折叠层级。整幅位移取令牌，减弱动效下归零，只剩淡入 */
  @keyframes xh-toast-in {
    from {
      opacity: 0;
      transform: translateY(calc(var(--xh-toast-dir, 1) * (var(--xh-toast-offset-collapsed, 0px) - var(--xh-motion-travel))))
        scale(var(--xh-toast-scale-collapsed, 1));
    }

    to {
      opacity: 1;
      transform: translateY(calc(var(--xh-toast-dir, 1) * var(--xh-toast-offset-collapsed, 0px)))
        scale(var(--xh-toast-scale-collapsed, 1));
    }
  }

  @keyframes xh-toast-out {
    from {
      opacity: 1;
      transform: translateY(calc(var(--xh-toast-dir, 1) * var(--xh-toast-y, 0px)))
        scale(var(--xh-toast-scale, 1));
    }

    to {
      opacity: 0;
      transform: translateY(calc(var(--xh-toast-dir, 1) * (var(--xh-toast-y, 0px) - var(--xh-motion-travel))))
        scale(var(--xh-toast-scale, 1));
    }
  }
}

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='toast'] {
    --xh-toast-skin: 1;
  }

  /* 固定宽度的堆叠定位面；每条 Toast 在其中绝对定位。 */
  [data-scope='toast'][data-part='group'] {
    position: fixed;
    z-index: var(--xh-toast-layer, var(--xh-layer-toast));
    display: block;
    inline-size: min(var(--xh-toast-inline-size, 28.75rem), calc(100vw - var(--xh-space-8)));
    block-size: 0;
    pointer-events: none;
  }

  [data-scope='toast'][data-part='group'][hidden] {
    display: none;
  }

  [data-scope='toast'][data-part='group'][data-placement='bottom'] {
    inset-block-end: max(var(--xh-toast-inset, var(--xh-space-4)), env(safe-area-inset-bottom));
    inset-inline-start: 50%;
    translate: -50% 0;
  }

  [data-scope='toast'][data-part='group'][data-placement='top'] {
    inset-block-start: max(var(--xh-toast-inset, var(--xh-space-4)), env(safe-area-inset-top));
    inset-inline-start: 50%;
    translate: -50% 0;
  }

  [data-scope='toast'][data-part='group'][data-placement$='-start'] {
    inset-inline-start: max(var(--xh-toast-inset, var(--xh-space-4)), env(safe-area-inset-left));
  }

  [data-scope='toast'][data-part='group'][data-placement$='-end'] {
    inset-inline-end: max(var(--xh-toast-inset, var(--xh-space-4)), env(safe-area-inset-right));
  }

  [data-scope='toast'][data-part='group'][data-placement^='bottom'][data-placement$='-start'],
  [data-scope='toast'][data-part='group'][data-placement^='bottom'][data-placement$='-end'] {
    inset-block-end: max(var(--xh-toast-inset, var(--xh-space-4)), env(safe-area-inset-bottom));
  }

  [data-scope='toast'][data-part='group'][data-placement^='top'][data-placement$='-start'],
  [data-scope='toast'][data-part='group'][data-placement^='top'][data-placement$='-end'] {
    inset-block-start: max(var(--xh-toast-inset, var(--xh-space-4)), env(safe-area-inset-top));
  }

  /* 中性浮层承载整条反馈，语气只落到状态字形和标题。
     面走 sheet 三件套（--xh-material-elevated-bg / -border / -shadow，亮暗两档同有 1px 描边）。 */
  [data-scope='toast'][data-part='root'] {
    /* 作者塞进指示符槽的图标与皮肤画的兜底字形同一把尺：Feedback 指示符统一 md 档 */
    --xh-icon-size: var(--xh-toast-icon-size, var(--xh-glyph-size-md));

    --xh-toast-y: var(--xh-toast-offset-collapsed, 0px);
    --xh-toast-scale: var(--xh-toast-scale-collapsed, 1);

    position: relative;
    display: flex;
    flex: none;
    align-items: flex-start;
    gap: var(--xh-toast-gap, var(--xh-space-1_5));
    inline-size: min(var(--xh-toast-inline-size, 28.75rem), 100%);
    padding-block: var(--xh-toast-py, var(--xh-space-3));
    padding-inline: var(--xh-toast-px, var(--xh-space-4));
    border: var(--xh-stroke-thin) solid var(--xh-toast-border, var(--xh-material-elevated-border));
    border-radius: var(--xh-toast-radius, var(--xh-shape-overlay));
    background: var(--xh-toast-bg, var(--xh-material-elevated-bg));
    color: var(--xh-toast-fg, var(--xh-material-elevated-fg));
    box-shadow: var(--xh-toast-shadow, var(--xh-material-elevated-shadow));
    font-size: var(--xh-toast-font-size, var(--xh-text-label-size));
    line-height: var(--xh-toast-leading, var(--xh-text-body-leading));
    /* 摞的定位面整面铺开且不吃指针，条子必须自己吃回来：
       悬停按住计时、按钮可点、焦点进出，全指着这一条 */
    pointer-events: auto;
    transform: translateY(calc(var(--xh-toast-dir, 1) * var(--xh-toast-y))) scale(var(--xh-toast-scale));
    transform-origin: bottom center;
    transition:
      transform var(--xh-motion-duration-move) var(--xh-motion-ease-continuous),
      block-size var(--xh-motion-duration-move) var(--xh-motion-ease-continuous),
      opacity var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='toast'][data-part='group'] [data-scope='toast'][data-part='root'] {
    position: absolute;
    inset-inline: 0;
    inline-size: 100%;
  }

  [data-scope='toast'][data-part='root'][data-placement^='bottom'] {
    --xh-toast-dir: -1;
    inset-block-end: 0;
  }

  [data-scope='toast'][data-part='root'][data-placement^='top'] {
    --xh-toast-dir: 1;
    inset-block-start: 0;
    transform-origin: top center;
  }

  /* 退场窗口走完连接层给的是 hidden 属性，而上面声明了 display——
     漏掉这条，已经"卸载"的提示会一直杵在屏幕上，且再也没人来收 */
  [data-scope='toast'][data-part='root'][hidden] {
    display: none;
  }

  /* 生命周期只有三段，unmounted 那段由上面的 [hidden] 收走，这里只管前两段 */
  [data-scope='toast'][data-part='root'][data-state='visible'] {
    animation: xh-toast-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong) backwards;
  }

  [data-scope='toast'][data-part='root'][data-stack-index]:not([data-frontmost]):not([data-expanded]) {
    block-size: var(--xh-toast-front-height, auto);
    overflow: hidden;
  }

  [data-scope='toast'][data-part='root'][data-stack-index]:not([data-frontmost]):not([data-expanded])
  > :not([data-part='close-trigger']) {
    opacity: 0;
  }

  [data-scope='toast'][data-part='root'][data-expanded] {
    --xh-toast-y: var(--xh-toast-offset-expanded, 0px);
    --xh-toast-scale: 1;
    block-size: var(--xh-toast-height, auto);
  }

  [data-scope='toast'][data-part='root'] > :not([data-part='close-trigger']) {
    transition: opacity var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* forwards 不能省：退场窗口（removeDelay 默认 300ms）比退场动画长，
     不定住末帧的话动画跑完会弹回全不透明，条子在被收起前先闪一下 */
  [data-scope='toast'][data-part='root'][data-state='dismissing'] {
    animation: xh-toast-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /*
   * 语气的非颜色通道。行首字形按 data-tone 区分信息、成功、警告与失败；加载中另由 data-loading 说，
   * 字形换成转圈但配色仍照语气走。
   * 作者未渲染 indicator 时由 root 的伪元素补上。
   */
  [data-scope='toast'][data-part='root']::before {
    content: '';
    flex: none;
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: var(--xh-toast-icon-fg, var(--xh-_tone-fg));
    -webkit-mask: var(--xh-glyph-mark-info) center / contain no-repeat;
    mask: var(--xh-glyph-mark-info) center / contain no-repeat;
  }

  [data-scope='toast'][data-part='root'][data-tone='success']::before {
    -webkit-mask-image: var(--xh-glyph-mark-check);
    mask-image: var(--xh-glyph-mark-check);
  }

  [data-scope='toast'][data-part='root'][data-tone='warning']::before {
    -webkit-mask-image: var(--xh-glyph-mark-warning);
    mask-image: var(--xh-glyph-mark-warning);
  }

  [data-scope='toast'][data-part='root'][data-tone='danger']::before {
    -webkit-mask-image: var(--xh-glyph-mark-close);
    mask-image: var(--xh-glyph-mark-close);
  }

  /* 加载中不是语气：只换字形，颜色沿用当前语气的前景档；写在四档语气之后，转圈压过它们 */
  [data-scope='toast'][data-part='root'][data-loading]::before {
    -webkit-mask-image: var(--xh-glyph-mark-rotate-right);
    mask-image: var(--xh-glyph-mark-rotate-right);
    animation: xh-spin var(--xh-spin-duration) var(--xh-motion-ease-loop) infinite;
  }

  /* 减少动效：转圈停下，静止的箭头仍然读得出「还没好」；「在等什么」由条子上的
     role=status 与可见文案继续承担。
     两组规则是同一件事的两个触发条件：系统偏好与作者打的 data-motion */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='toast'][data-part='root'][data-loading]::before {
      animation: none;
    }
  }

  :where([data-motion='reduce']) [data-scope='toast'][data-part='root'][data-loading]::before {
    animation: none;
  }

  /* 作者渲染了指示符部件，行首那枚兜底字形就让位给它，一行里不出现两枚图形 */
  [data-scope='toast'][data-part='root']:has([data-part='indicator'])::before {
    content: none;
  }

  /* 指示符部件：字形与 root 上那枚同尺同色，作者往里塞节点即整枚换掉 */
  [data-scope='toast'][data-part='indicator'] {
    flex: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-sizing: content-box;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    padding: var(--xh-toast-indicator-p, var(--xh-space-1));
    color: var(--xh-toast-icon-fg, var(--xh-_tone-fg));
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中 */
  [data-scope='toast'][data-part='indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-info) center / contain no-repeat;
    mask: var(--xh-glyph-mark-info) center / contain no-repeat;
  }

  [data-scope='toast'][data-part='indicator'][data-tone='success']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-check);
    mask-image: var(--xh-glyph-mark-check);
  }

  [data-scope='toast'][data-part='indicator'][data-tone='warning']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-warning);
    mask-image: var(--xh-glyph-mark-warning);
  }

  [data-scope='toast'][data-part='indicator'][data-tone='danger']:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-close);
    mask-image: var(--xh-glyph-mark-close);
  }

  [data-scope='toast'][data-part='indicator'][data-loading]:empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-rotate-right);
    mask-image: var(--xh-glyph-mark-rotate-right);
    animation: xh-spin var(--xh-spin-duration) var(--xh-motion-ease-loop) infinite;
  }

  /* 减少动效：与 root 上那枚同一处理——转圈停下，静止的箭头仍读得出「还没好」。
     两组规则是同一件事的两个触发条件：系统偏好与作者打的 data-motion */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='toast'][data-part='indicator'][data-loading]:empty::before {
      animation: none;
    }
  }

  :where([data-motion='reduce']) [data-scope='toast'][data-part='indicator'][data-loading]:empty::before {
    animation: none;
  }

  [data-scope='toast'][data-part='indicator'][hidden] {
    display: none;
  }

  [data-scope='toast'][data-part='content'] {
    flex: 1 1 auto;
    display: flex;
    flex-direction: column;
    align-self: center;
    min-inline-size: 0;
  }

  [data-scope='toast'][data-part='title'],
  [data-scope='toast'][data-part='description'] {
    margin: 0;
    min-inline-size: 0;
  }

  [data-scope='toast'][data-part='title'] {
    color: var(--xh-toast-title-fg, var(--xh-_tone-fg));
    font-size: var(--xh-toast-title-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-toast-title-font-weight, var(--xh-font-weight-semibold));
    line-height: var(--xh-toast-title-leading, var(--xh-text-body-leading));
  }

  [data-scope='toast'][data-part='description'] {
    color: var(--xh-toast-description-fg, var(--xh-fg-muted));
    font-size: var(--xh-toast-description-font-size, var(--xh-text-secondary-size));
    line-height: var(--xh-toast-description-leading, var(--xh-leading-normal));
  }

  /* 没给文案时仍然要留在 DOM 里（aria-labelledby 指着它），
     但空盒子会照吃一份 gap，条子看着就多出一截莫名的留白 */
  [data-scope='toast'][data-part='title']:empty {
    display: none;
  }

  [data-scope='toast'][data-part='description']:empty {
    display: none;
  }

  [data-scope='toast'][data-part='title'][hidden] {
    display: none;
  }

  /* 操作钮是带文案的离散动作钮：盒几何、悬停 / 按下与 0.97 按压、粗指针热区、焦点环、禁用面全由 Action Control
     的 text outline 档给（连接层投 sm；非 Button 的触发器缺省中性描边、透明底），组件只映射既有使用者槽。
     语气只落到状态字形和标题：这颗钮坐在带 data-tone 的条子里，底 / 边 / 字钉在中性语义面上，不随语气；
     条子是 sheet 白面承载：hover --xh-bg-subtle（100）→ pressed --xh-bg-subtle-hover（200）。
     条子是单行 flex，按钮不参与伸缩：文案长了该换行的是文字 */
  [data-scope='toast'][data-part='action-trigger'] {
    --xh-action-visual-size: var(--xh-toast-action-h, var(--xh-_action-profile-visual-size));
    --xh-action-padding-inline: var(--xh-toast-action-px, var(--xh-_action-profile-padding-inline));
    --xh-action-radius: var(--xh-toast-action-radius, var(--xh-shape-control));
    --xh-action-bg-rest: var(--xh-toast-action-bg, transparent);
    --xh-action-bg-hover: var(--xh-toast-action-bg-hover, var(--xh-bg-subtle));
    --xh-action-bg-pressed: var(--xh-toast-action-bg-active, var(--xh-bg-subtle-hover));
    --xh-action-fg-rest: var(--xh-toast-action-fg, var(--xh-fg-default));
    --xh-action-fg-hover: var(--xh-toast-action-fg, var(--xh-fg-default));
    --xh-action-fg-pressed: var(--xh-toast-action-fg, var(--xh-fg-default));
    --xh-action-border-rest: var(--xh-toast-action-border, var(--xh-border-control));
    --xh-action-border-hover: var(--xh-toast-action-border, var(--xh-border-control-hover));
    --xh-action-border-pressed: var(--xh-toast-action-border, var(--xh-border-control-hover));
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;

    flex: none;
    align-self: center;
    font-weight: var(--xh-toast-action-font-weight, var(--xh-font-weight-medium));
  }

  /* 家族那条 display 会把 UA 的 [hidden]{display:none} 盖掉 */
  [data-scope='toast'][data-part='action-trigger'][hidden] {
    display: none;
  }

  /*
   * 倒计时条。总时长由连接层写进 --xh-toast-progress-duration（不自动消失的那些整条收起），
   * 计时被按住时动画一并停住——停表这件事此前没有任何可画的地方。
   * 取装饰档 --xh-_tone-soft：压在同族淡底上仍看得出来。
   */
  [data-scope='toast'][data-part='progress'] {
    position: absolute;
    inset-block-end: 0;
    inset-inline-start: 0;
    overflow: hidden;
    inline-size: 100%;
    block-size: var(--xh-toast-progress-thickness, var(--xh-space-0_5));
    background: var(--xh-toast-progress-bg, var(--xh-_tone-soft));
    animation: xh-countdown var(--xh-toast-progress-duration, var(--xh-motion-duration-slide)) var(--xh-motion-ease-loop) forwards;
  }

  /* 裁切只认物理方向：RTL 下行尾在左边，从左往右收 */
  [data-scope='toast'][data-part='progress']:dir(rtl) {
    --xh-_countdown-cut-left: 100%;
    --xh-_countdown-cut-right: 0;
  }

  /* 减弱动效：倒计时不连续地缩，按秒一格一格走，段数由连接层随时长交出。
     两条规则是同一件事的两个触发条件：系统偏好与作者打的 data-motion */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='toast'][data-part='progress'] {
      animation-timing-function: steps(var(--xh-_toast-progress-steps, 1), end);
    }
  }

  :where([data-motion='reduce']) [data-scope='toast'][data-part='progress'] {
    animation-timing-function: steps(var(--xh-_toast-progress-steps, 1), end);
  }

  [data-scope='toast'][data-part='root'][data-paused] [data-part='progress'] {
    animation-play-state: paused;
  }

  [data-scope='toast'][data-part='progress'][hidden] {
    display: none;
  }

  /* 关闭钮是只有字形的离散动作钮：盒几何、悬停 / 按下与 0.97 按压、粗指针热区、焦点环、禁用面全由 Action Control
     的 icon ghost 档给（连接层投 xs：24px 正方盒，与此前 --xh-control-action-size 同尺寸；那颗叉排在单行短消息里，
     走行级动作钮那一档），组件只映射既有使用者槽。静息透明，sheet 白面承载 hover 100 → pressed 200，
     写了语气时悬停底跟着语气走（--xh-_tone-subtle）。
     有悬停能力的设备上默认静默、指针进入条子或焦点落进条子后显现——不走家族的 hover-focus 显示策略：
     那一档用 visibility 收起，这颗叉占 Tab 位，收成 visibility: hidden 后键盘就够不到它了；
     这里只压 opacity 与 pointer-events，焦点仍能落进来 */
  [data-scope='toast'][data-part='close-trigger'] {
    --xh-action-visual-size: var(--xh-toast-close-size, var(--xh-_action-profile-visual-size));
    --xh-action-min-inline-size: var(--xh-toast-close-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-toast-close-radius, var(--xh-shape-control));
    --xh-action-bg-rest: var(--xh-toast-close-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-toast-close-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-toast-close-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-toast-close-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-toast-close-fg-hover, var(--xh-fg-default));
    --xh-action-fg-pressed: var(--xh-toast-close-fg-hover, var(--xh-fg-default));
    --xh-action-border-rest: var(--xh-toast-close-border, var(--xh-_action-variant-border-rest));
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    /* 叉的字形按钮档取值（xs → 16px），与 root 上给指示符的 md 档分开 */
    --xh-icon-size: var(--xh-toast-icon-size, var(--xh-_action-profile-glyph-size));

    flex: none;
    align-self: center;
  }

  @media (hover: hover) {
    [data-scope='toast'][data-part='close-trigger'] {
      opacity: 0;
      pointer-events: none;
    }

    [data-scope='toast'][data-part='root']:hover [data-part='close-trigger'],
    [data-scope='toast'][data-part='root']:focus-within [data-part='close-trigger'] {
      opacity: 1;
      pointer-events: auto;
    }
  }

  /* 折叠堆叠只允许最前一条露出关闭入口；触屏没有 hover，必须显式收起后台按钮。 */
  [data-scope='toast'][data-part='root'][data-stack-index]:not([data-frontmost]):not([data-expanded])
  [data-part='close-trigger'] {
    opacity: 0;
    pointer-events: none;
  }

  /* closable=false 时连接层同时给了 hidden 与 disabled，这条是它真正收起的那一半：
     上面声明了 display，不补回来就会留下一个按不动的叉，比压根没有叉更让人困惑 */
  [data-scope='toast'][data-part='close-trigger'][hidden] {
    display: none;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中 */
  [data-scope='toast'][data-part='close-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }

  @media print {
    /* 打印：轻提示是瞬态的，打印那一刻恰好在场就会横在正文上，且它已经错过了被读到的时机。 */
    [data-scope='toast'][data-part='group'] {
      display: none;
    }

    /* 摞收起后条子本不该出现在纸上；这一条兜的是作者把条子摆在别处的用法：
       动画会被定格在任意一帧——转了一半的圈。取值与减弱动效那一档相同。 */
    [data-scope='toast'][data-part='root'][data-loading]::before {
      animation: none;
    }
  }

  [data-scope='toast'][data-part='content'][hidden],
  [data-scope='toast'][data-part='description'][hidden] {
    display: none;
  }
}

/* styles/toggle.css */
/* 定义 toggle 样式。 */

@layer xihan.components {
  [data-scope='toggle'] {
    --xh-toggle-skin: 1;
  }

  /* 未按下的四档形态由家族形态矩阵按 data-xh-action-variant 给出（缺省 subtle 由连接层显式投影；solid 未按下时
     投 ghost，只在按下时才是品牌实心）；公开槽桥接到矩阵之前：使用者槽 → 形态矩阵 → 家族缺省。
     按下（on）是无滑块开关的选中面：品牌淡底 12 → 悬停 20 → 按压 28，前景 fg-on-brand-subtle，
     私有槽在下面的 data-state='on' 块里接到桥接槽上。 */
  [data-scope='toggle'][data-part='root'] {
    --xh-_toggle-bg-on: var(--xh-toggle-bg-on, var(--xh-_tone-subtle, var(--xh-bg-brand-subtle)));
    --xh-_toggle-bg-on-hover: var(
      --xh-toggle-bg-on-hover,
      var(
        --xh-_tone-subtle-hover,
        var(--xh-bg-brand-subtle-hover)
      )
    );
    --xh-_toggle-bg-on-active: var(
      --xh-toggle-bg-on-active,
      var(
        --xh-_tone-subtle-active,
        var(--xh-bg-brand-subtle-active)
      )
    );
    --xh-_toggle-fg-on: var(--xh-toggle-fg-on, var(--xh-_tone-fg, var(--xh-fg-on-brand-subtle)));
    --xh-_toggle-border-on: var(--xh-toggle-border-on, transparent);
    /* 禁用同时降级前景与表面，不靠 opacity；选中且禁用时底色掺一半中性面，选中信息不丢。 */
    --xh-_toggle-bg-on-disabled: var(
      --xh-toggle-bg-on-disabled,
      color-mix(in oklab, var(--xh-_toggle-bg-on) 50%, var(--xh-bg-subtle))
    );
    --xh-_toggle-fg-on-disabled: var(--xh-toggle-fg-on-disabled, var(--xh-_toggle-fg-on));
    --xh-action-bg-rest: var(--xh-toggle-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-toggle-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-toggle-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-bg-focus-visible: var(--xh-toggle-bg, var(--xh-_action-variant-bg-focus-visible));
    --xh-action-bg-disabled: var(--xh-toggle-bg-disabled, var(--xh-_action-variant-bg-disabled));
    --xh-action-fg-rest: var(--xh-toggle-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-toggle-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-toggle-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-fg-focus-visible: var(--xh-toggle-fg, var(--xh-_action-variant-fg-focus-visible));
    --xh-action-fg-disabled: var(--xh-toggle-fg-disabled, var(--xh-_action-variant-fg-disabled));
    --xh-action-border-rest: var(--xh-toggle-border, var(--xh-_action-variant-border-rest));
    --xh-action-border-hover: var(--xh-toggle-border, var(--xh-_action-variant-border-hover));
    --xh-action-border-pressed: var(--xh-toggle-border, var(--xh-_action-variant-border-pressed));
    --xh-action-border-focus-visible: var(--xh-toggle-border, var(--xh-_action-variant-border-focus-visible));
    --xh-action-border-disabled: var(--xh-toggle-border-disabled, var(--xh-_action-variant-border-disabled));
    --xh-action-radius: var(--xh-toggle-radius, var(--xh-shape-control));
    --xh-action-visual-size: var(--xh-toggle-h, var(--xh-_action-profile-visual-size));
    --xh-action-padding-inline: var(--xh-toggle-px, var(--xh-_action-profile-padding-inline));
    --xh-action-gap: var(--xh-toggle-gap, var(--xh-_action-profile-gap));
    --xh-action-font-size: var(--xh-toggle-font-size, var(--xh-_action-profile-font-size));
    --xh-icon-size: var(--xh-toggle-icon-size, var(--xh-_action-profile-glyph-size));

    font-weight: var(--xh-toggle-font-weight, var(--xh-text-label-weight));
  }

  [data-scope='toggle'] > svg {
    inline-size: var(--xh-toggle-icon-size, var(--xh-_action-profile-glyph-size));
    block-size: var(--xh-toggle-icon-size, var(--xh-_action-profile-glyph-size));
    flex: none;
    pointer-events: none;
  }

  /* outline 按下后描边仍是可操作区那一档：淡底面上没有描边就与 subtle 的按下态分不开 */
  [data-scope='toggle'][data-part='root'][data-variant='outline'] {
    --xh-_toggle-border-on: var(--xh-toggle-border-on, var(--xh-_tone-border-control, var(--xh-border-control)));
  }

  /* 按下（on）：solid 之外的三档一律品牌淡底；solid 的按下面由矩阵 solid 列给出（连接层此时投影
     data-xh-action-variant='solid'），这里不接管。 */
  [data-scope='toggle'][data-part='root']:not([data-variant='solid'])[data-state='on'] {
    --xh-action-bg-rest: var(--xh-_toggle-bg-on);
    --xh-action-bg-hover: var(--xh-_toggle-bg-on-hover);
    --xh-action-bg-pressed: var(--xh-_toggle-bg-on-active);
    --xh-action-bg-focus-visible: var(--xh-_toggle-bg-on);
    --xh-action-bg-disabled: var(--xh-_toggle-bg-on-disabled);
    --xh-action-fg-rest: var(--xh-_toggle-fg-on);
    --xh-action-fg-hover: var(--xh-_toggle-fg-on);
    --xh-action-fg-pressed: var(--xh-_toggle-fg-on);
    --xh-action-fg-focus-visible: var(--xh-_toggle-fg-on);
    --xh-action-fg-disabled: var(--xh-_toggle-fg-on-disabled);
    --xh-action-border-rest: var(--xh-_toggle-border-on);
    --xh-action-border-hover: var(--xh-_toggle-border-on);
    --xh-action-border-pressed: var(--xh-_toggle-border-on);
    --xh-action-border-focus-visible: var(--xh-_toggle-border-on);
    --xh-action-border-disabled: var(--xh-_toggle-border-on);
  }

  /* 使用者的 --xh-toggle-shadow 只落在按下面上：矩阵各态无影，淡底与阴影互斥 */
  [data-scope='toggle'][data-part='root'][data-state='on'] {
    --xh-action-shadow-rest: var(--xh-toggle-shadow, none);
    --xh-action-shadow-hover: var(--xh-toggle-shadow, none);
    --xh-action-shadow-pressed: var(--xh-toggle-shadow, none);
    --xh-action-shadow-focus-visible: var(--xh-toggle-shadow, none);
    --xh-action-shadow-disabled: none;
  }

  /* solid 按下后是实心面：顶边内高光与全库实心档共用一条式子。
     禁用同样掺一半中性面保留选中信息（与上面三档同一条规则）：矩阵 solid 列的 disabled 是中性
     bg-subtle + fg-disabled，直接吃它就与未按下的禁用面分不开；底取实心面本身（矩阵在暗色下
     换过的品牌实心也一并跟着）掺 --xh-bg-subtle，前景留实心面的配对前景。 */
  [data-scope='toggle'][data-part='root'][data-variant='solid'][data-state='on'] {
    --xh-action-bg-disabled: var(
      --xh-toggle-bg-on-disabled,
      color-mix(in oklab, var(--xh-_action-variant-bg-rest) 50%, var(--xh-bg-subtle))
    );
    --xh-action-fg-disabled: var(--xh-toggle-fg-on-disabled, var(--xh-_action-variant-fg-rest));
    --xh-action-highlight-rest: var(--xh-_highlight-tone);
    --xh-action-highlight-hover: var(--xh-_highlight-tone);
    --xh-action-highlight-pressed: var(--xh-_highlight-tone);
    --xh-action-highlight-focus-visible: var(--xh-_highlight-tone);
  }

  /* 只有 solid 按下后才是实心面：环色与面同族画在面里看不出来，环改取面自己的前景色；
     品牌淡底不是实心面，吃库环 */
  [data-scope='toggle'][data-part='root'][data-variant='solid'][data-state='on']:focus-visible {
    --xh-action-ring-color-focus-visible: currentColor;
  }

  [data-scope='toggle'][data-part='root'][data-full-width] {
    inline-size: 100%;
  }

  [data-scope='toggle'][data-part='root'][hidden] {
    display: none;
  }

  @media print {
    [data-scope='toggle'][data-part='root'][data-state='on'] {
      border-color: currentColor;
      font-weight: var(--xh-font-weight-semibold);
    }
  }
}

/* styles/toggle-group.css */
/* 定义 toggle group 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='toggle-group'] {
    --xh-toggle-group-skin: 1;
  }

  /* 分段控件：段与段之间不留缝，靠共边连成一体，所以 root 不设 gap。
     排布只能读 data-orientation——aria-orientation 在多选模式下连接层根本不输出（role=group 不收） */
  [data-scope='toggle-group'][data-part='root'] {
    /* 组件内那几档层号只在自己人之间排序：建一个层叠上下文把它们关起来，
       既不让页面上的层号插进来，也不让它们漏出去压住别人 */
    isolation: isolate;

    /* 段的度量与字号走私有槽中转，与同族的分段控件一处对一处 */
    --xh-_toggle-group-h: var(--xh-control-h-md);
    --xh-_toggle-group-px: var(--xh-control-px-md);
    --xh-_toggle-group-gap: var(--xh-control-gap-md);
    --xh-_toggle-group-font-size: var(--xh-control-font-md);
    --xh-_group-separator-size: calc(var(--xh-_toggle-group-h) / 2);

    /* 形态的落点：没写 data-variant 时这十支保持缺省档的取值，段的规则读的是
       「使用者令牌 → 这十支 → 语义令牌」三级，使用者令牌永远排在形态之前。
       未选中那五支管段的壳，选中那五支管当前值那一段。
       缺省档（subtle）的段坐在自己的淡底面上，悬停 200 → 按下 300（淡底承载）；
       选中段是无滑块开关：品牌淡底 + 淡底前景，悬停 20% → 按下 28% */
    --xh-_toggle-group-item-bg: var(--xh-bg-subtle);
    --xh-_toggle-group-item-bg-hover: var(--xh-bg-subtle-hover);
    --xh-_toggle-group-item-bg-active: var(--xh-bg-subtle-active);
    --xh-_toggle-group-item-fg: var(--xh-fg-default);
    --xh-_toggle-group-item-border: transparent;
    --xh-_toggle-group-item-bg-on: var(--xh-_tone-subtle, var(--xh-bg-brand-subtle));
    --xh-_toggle-group-item-bg-on-hover: var(
      --xh-_tone-subtle-hover,
      var(--xh-bg-brand-subtle-hover)
    );
    --xh-_toggle-group-item-bg-on-active: var(
      --xh-_tone-subtle-active,
      var(--xh-bg-brand-subtle-active)
    );
    --xh-_toggle-group-item-fg-on: var(--xh-_tone-fg, var(--xh-fg-on-brand-subtle));
    --xh-_toggle-group-item-border-on: transparent;
    --xh-_toggle-group-item-highlight-on: none;

    /* 连续分段不能换行；窄容器由作者改为竖排或全宽布局。 */
    display: inline-flex;
    flex-wrap: nowrap;
    align-items: stretch;
  }

  /* —— 形态 ——
     四档与 toggle 一处对一处：未选中那些段长什么样在这里定，选中那一段用哪一档底也在这里定，
     切换仍由 data-state='on' 那一条统一完成。
     缺省档（没写 data-variant）使用中性浅底，选中段使用品牌淡底 */
  [data-scope='toggle-group'][data-part='root'][data-variant='solid'] {
    --xh-_toggle-group-item-bg: transparent;
    --xh-_toggle-group-item-border: transparent;
    --xh-_toggle-group-item-bg-on: var(--xh-_tone, var(--xh-bg-brand));
    --xh-_toggle-group-item-bg-on-hover: var(--xh-_tone-hover, var(--xh-bg-brand-hover));
    --xh-_toggle-group-item-bg-on-active: var(--xh-_tone-active, var(--xh-bg-brand-active));
    --xh-_toggle-group-item-fg-on: var(--xh-_tone-on, var(--xh-fg-on-brand));
    --xh-_toggle-group-item-border-on: var(--xh-_tone, var(--xh-bg-brand));
    --xh-_toggle-group-item-highlight-on: var(--xh-_highlight-tone);
  }

  [data-scope='toggle-group'][data-part='root'][data-variant='solid']:is(
    :not([data-tone]),
    [data-tone='brand']
  ) {
    --xh-_toggle-group-item-bg-on: var(--xh-action-brand-solid);
    --xh-_toggle-group-item-bg-on-hover: var(--xh-action-brand-solid-hover);
    --xh-_toggle-group-item-bg-on-active: var(--xh-action-brand-solid-active);
    --xh-_toggle-group-item-fg-on: var(--xh-action-on-brand-solid);
    --xh-_toggle-group-item-border-on: var(--xh-action-brand-solid);
  }

  [data-scope='toggle-group'][data-part='root'][data-variant='subtle'] {
    --xh-_toggle-group-item-bg: var(--xh-bg-subtle);
    --xh-_toggle-group-item-bg-hover: var(--xh-bg-subtle-hover);
    --xh-_toggle-group-item-bg-active: var(--xh-bg-subtle-active);
    --xh-_toggle-group-item-fg: var(--xh-fg-default);
    --xh-_toggle-group-item-border: transparent;
    --xh-_toggle-group-item-bg-on: var(--xh-_tone-subtle, var(--xh-bg-brand-subtle));
    --xh-_toggle-group-item-bg-on-hover: var(--xh-_tone-subtle-hover, var(--xh-bg-brand-subtle-hover));
    --xh-_toggle-group-item-bg-on-active: var(--xh-_tone-subtle-active, var(--xh-bg-brand-subtle-active));
    --xh-_toggle-group-item-fg-on: var(--xh-_tone-fg, var(--xh-fg-on-brand-subtle));
    --xh-_toggle-group-item-border-on: transparent;
    --xh-_toggle-group-item-highlight-on: none;
  }

  /* outline 与 ghost 的段坐在画布上：悬停 100 → 按下 200（白底承载） */
  [data-scope='toggle-group'][data-part='root'][data-variant='outline'] {
    --xh-_toggle-group-item-bg: transparent;
    --xh-_toggle-group-item-bg-hover: var(--xh-_tone-subtle, var(--xh-bg-subtle));
    --xh-_toggle-group-item-bg-active: var(--xh-_tone-subtle-hover, var(--xh-bg-subtle-hover));
    --xh-_toggle-group-item-fg: var(--xh-_tone-fg, var(--xh-fg-default));
    --xh-_toggle-group-item-border: transparent;
    --xh-_toggle-group-item-bg-on: var(--xh-_tone-subtle, var(--xh-bg-brand-subtle));
    --xh-_toggle-group-item-bg-on-hover: var(--xh-_tone-subtle-hover, var(--xh-bg-brand-subtle-hover));
    --xh-_toggle-group-item-bg-on-active: var(--xh-_tone-subtle-active, var(--xh-bg-brand-subtle-active));
    --xh-_toggle-group-item-fg-on: var(--xh-_tone-fg, var(--xh-fg-on-brand-subtle));
    --xh-_toggle-group-item-border-on: transparent;
    --xh-_toggle-group-item-highlight-on: none;

    position: relative;
    border-radius: var(--xh-toggle-group-item-radius, var(--xh-shape-control));
  }

  [data-scope='toggle-group'][data-part='root'][data-variant='outline']::after {
    content: '';
    position: absolute;
    z-index: 2;
    inset: 0;
    border: var(--xh-stroke-thin) solid
      var(--xh-toggle-group-outline-color, var(--xh-_tone-border-control, var(--xh-border-control)));
    border-radius: inherit;
    pointer-events: none;
  }

  [data-scope='toggle-group'][data-part='root'][data-variant='ghost'] {
    --xh-_toggle-group-item-bg: transparent;
    --xh-_toggle-group-item-bg-hover: var(--xh-_tone-subtle, var(--xh-bg-subtle));
    --xh-_toggle-group-item-bg-active: var(--xh-_tone-subtle-hover, var(--xh-bg-subtle-hover));
    --xh-_toggle-group-item-fg: var(--xh-_tone-fg, var(--xh-fg-default));
    --xh-_toggle-group-item-border: transparent;
    --xh-_toggle-group-item-bg-on: var(--xh-_tone-subtle, var(--xh-bg-brand-subtle));
    --xh-_toggle-group-item-bg-on-hover: var(--xh-_tone-subtle-hover, var(--xh-bg-brand-subtle-hover));
    --xh-_toggle-group-item-bg-on-active: var(--xh-_tone-subtle-active, var(--xh-bg-brand-subtle-active));
    --xh-_toggle-group-item-fg-on: var(--xh-_tone-fg, var(--xh-fg-on-brand-subtle));
    --xh-_toggle-group-item-border-on: transparent;
    --xh-_toggle-group-item-highlight-on: none;
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里 */
  [data-scope='toggle-group'][data-part='root'][data-size='sm'] {
    --xh-_toggle-group-h: var(--xh-control-h-sm);
    --xh-_toggle-group-px: var(--xh-control-px-sm);
    --xh-_toggle-group-gap: var(--xh-control-gap-sm);
    --xh-_toggle-group-font-size: var(--xh-control-font-sm);
  }

  [data-scope='toggle-group'][data-part='root'][data-size='lg'] {
    --xh-_toggle-group-h: var(--xh-control-h-lg);
    --xh-_toggle-group-px: var(--xh-control-px-lg);
    --xh-_toggle-group-gap: var(--xh-control-gap-lg);
    --xh-_toggle-group-font-size: var(--xh-control-font-lg);
  }

  [data-scope='toggle-group'][data-part='root'][data-orientation='horizontal'] {
    flex-direction: row;
  }

  [data-scope='toggle-group'][data-part='root'][data-orientation='vertical'] {
    flex-direction: column;
    flex-wrap: nowrap;
  }

  /* root 会短暂拿到 tabindex=0，但它的 onFocus 立刻把焦点转投给条目，
     在它身上画环只会闪一下就跳走，高亮要长在条目上 */
  [data-scope='toggle-group'][data-part='root']:focus-visible {
    outline: none;
  }

  /* 段是 Action Control 的 text 档定尺按钮：盒型、三档几何、悬停 / 按下 / 焦点 / 禁用面与过渡都由家族给，
     这里只把使用者槽映射到桥接槽（-gap / -h / -px / -bg / -bg-hover / -bg-active / -fg / -border / -bg-disabled /
     -fg-disabled / -border-disabled / -font-size 使用者槽保留为第一参数，缺省落到 root 上按形态赋值的十支私有槽）。
     状态规则只改写桥接槽，底色 / 描边 / 前景三者永远同步换，不会出现选中了底色却没跟上描边 */
  [data-scope='toggle-group'][data-part='item'] {
    --xh-action-gap: var(--xh-toggle-group-item-gap, var(--xh-_toggle-group-gap));
    --xh-action-visual-size: var(--xh-toggle-group-item-h, var(--xh-_toggle-group-h));
    --xh-action-padding-inline: var(--xh-toggle-group-item-px, var(--xh-_toggle-group-px));
    --xh-action-font-size: var(--xh-toggle-group-item-font-size, var(--xh-_toggle-group-font-size));
    /* 中间段一律直角，圆角只由首末两端补回来 */
    --xh-action-radius: 0;
    --xh-action-bg-rest: var(--xh-toggle-group-item-bg, var(--xh-_toggle-group-item-bg));
    --xh-action-bg-hover: var(--xh-toggle-group-item-bg-hover, var(--xh-_toggle-group-item-bg-hover));
    --xh-action-bg-pressed: var(--xh-toggle-group-item-bg-active, var(--xh-_toggle-group-item-bg-active));
    --xh-action-bg-focus-visible: var(--xh-toggle-group-item-bg, var(--xh-_toggle-group-item-bg));
    --xh-action-bg-disabled: var(--xh-toggle-group-item-bg-disabled, var(--xh-bg-muted));
    --xh-action-fg-rest: var(--xh-toggle-group-item-fg, var(--xh-_toggle-group-item-fg));
    --xh-action-fg-hover: var(--xh-toggle-group-item-fg, var(--xh-_toggle-group-item-fg));
    --xh-action-fg-pressed: var(--xh-toggle-group-item-fg, var(--xh-_toggle-group-item-fg));
    --xh-action-fg-focus-visible: var(--xh-toggle-group-item-fg, var(--xh-_toggle-group-item-fg));
    --xh-action-fg-disabled: var(--xh-toggle-group-item-fg-disabled, var(--xh-fg-disabled));
    --xh-action-border-rest: var(--xh-toggle-group-item-border, var(--xh-_toggle-group-item-border));
    --xh-action-border-hover: var(--xh-toggle-group-item-border, var(--xh-_toggle-group-item-border));
    --xh-action-border-pressed: var(--xh-toggle-group-item-border, var(--xh-_toggle-group-item-border));
    --xh-action-border-focus-visible: var(--xh-toggle-group-item-border, var(--xh-_toggle-group-item-border));
    --xh-action-border-disabled: var(--xh-toggle-group-item-border-disabled, var(--xh-border-subtle));
    --xh-action-highlight-rest: transparent;
    --xh-action-highlight-hover: transparent;
    --xh-action-highlight-pressed: transparent;
    --xh-action-highlight-focus-visible: transparent;
    --xh-action-highlight-disabled: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    --xh-action-shadow-focus-visible: none;
    --xh-action-shadow-disabled: none;
    /* 共边相接的分段按下只换面不缩放：相邻两段靠负外边距压成一条边，缩放任一段都会把接缝拉开 */
    --xh-action-scale-pressed: none;

    /* 相邻两段靠负外边距压掉一条重边，谁的描边浮在上面必须能指定，
       因此条目必须是定位元素——静态元素的 z-index 不生效 */
    z-index: 0;
    font-weight: var(--xh-toggle-group-item-font-weight, var(--xh-text-label-weight));
  }

  /* 共边：后一段往回挪一个描边宽度，两条相邻的边重合成一条。
     方向跟着 data-orientation 走，横排收 inline 轴、竖排收 block 轴 */
  [data-scope='toggle-group'][data-part='root'][data-orientation='horizontal']
    > [data-scope='toggle-group'][data-part='item']
    + [data-scope='toggle-group'][data-part='item'] {
    margin-inline-start: calc(-1 * var(--xh-stroke-thin));
  }

  [data-scope='toggle-group'][data-part='root'][data-orientation='vertical']
    > [data-scope='toggle-group'][data-part='item']
    + [data-scope='toggle-group'][data-part='item'] {
    margin-block-start: calc(-1 * var(--xh-stroke-thin));
  }

  /* 两端圆角用逻辑角属性写，rtl 与竖排都跟着换边，不必另写一套。
     只认 root 的直接子节点：条目之间插了别的节点时宁可退化成直角，也不要圆错位置。
     角画在条目上，槽名也带 item 段，与同文件其余条目槽同段 */
  [data-scope='toggle-group'][data-part='root'][data-orientation='horizontal']
    > [data-scope='toggle-group'][data-part='item']:first-child {
    border-start-start-radius: var(--xh-toggle-group-item-radius, var(--xh-shape-control));
    border-end-start-radius: var(--xh-toggle-group-item-radius, var(--xh-shape-control));
  }

  [data-scope='toggle-group'][data-part='root'][data-orientation='horizontal']
    > [data-scope='toggle-group'][data-part='item']:last-child {
    border-start-end-radius: var(--xh-toggle-group-item-radius, var(--xh-shape-control));
    border-end-end-radius: var(--xh-toggle-group-item-radius, var(--xh-shape-control));
  }

  [data-scope='toggle-group'][data-part='root'][data-orientation='vertical']
    > [data-scope='toggle-group'][data-part='item']:first-child {
    border-start-start-radius: var(--xh-toggle-group-item-radius, var(--xh-shape-control));
    border-start-end-radius: var(--xh-toggle-group-item-radius, var(--xh-shape-control));
  }

  [data-scope='toggle-group'][data-part='root'][data-orientation='vertical']
    > [data-scope='toggle-group'][data-part='item']:last-child {
    border-end-start-radius: var(--xh-toggle-group-item-radius, var(--xh-shape-control));
    border-end-end-radius: var(--xh-toggle-group-item-radius, var(--xh-shape-control));
  }

  /* 选中态：单选是 role=radio + aria-checked，多选是原生按钮 + aria-pressed，
     两套 ARIA 各出一半，样式一条都对不上——只有 data-state 是两种模式共同的出口。
     无滑块开关：品牌淡底 + 淡底前景，悬停 20% → 按下 28%，三态都经桥接槽交给家族画；
     用哪族颜色由 data-tone 决定：语气槽沿继承流下来，root 自己写了 tone 算、
     整组落在语气容器里也算；没有语气就退回品牌配色，与不接语气时逐值相同。
     使用者令牌排在语气之前：写了组件槽就以它为准。
     只有 solid 形态提供内高光（一条 inset 描边式 box-shadow），其余形态在根变量中关闭 */
  [data-scope='toggle-group'][data-part='item'][data-state='on'] {
    --xh-action-bg-rest: var(--xh-toggle-group-item-bg-on, var(--xh-_toggle-group-item-bg-on));
    --xh-action-bg-hover: var(--xh-toggle-group-item-bg-on-hover, var(--xh-_toggle-group-item-bg-on-hover));
    --xh-action-bg-pressed: var(--xh-toggle-group-item-bg-on-active, var(--xh-_toggle-group-item-bg-on-active));
    --xh-action-bg-focus-visible: var(--xh-toggle-group-item-bg-on, var(--xh-_toggle-group-item-bg-on));
    --xh-action-bg-disabled: var(
      --xh-toggle-group-item-bg-on-disabled,
      color-mix(in oklab, var(--xh-_toggle-group-item-bg-on) 50%, var(--xh-bg-muted))
    );
    --xh-action-fg-rest: var(--xh-toggle-group-item-fg-on, var(--xh-_toggle-group-item-fg-on));
    --xh-action-fg-hover: var(--xh-toggle-group-item-fg-on, var(--xh-_toggle-group-item-fg-on));
    --xh-action-fg-pressed: var(--xh-toggle-group-item-fg-on, var(--xh-_toggle-group-item-fg-on));
    --xh-action-fg-focus-visible: var(--xh-toggle-group-item-fg-on, var(--xh-_toggle-group-item-fg-on));
    --xh-action-fg-disabled: var(--xh-toggle-group-item-fg-on-disabled, var(--xh-_toggle-group-item-fg-on));
    --xh-action-border-rest: var(--xh-toggle-group-item-border-on, var(--xh-_toggle-group-item-border-on));
    --xh-action-border-hover: var(--xh-toggle-group-item-border-on, var(--xh-_toggle-group-item-border-on));
    --xh-action-border-pressed: var(--xh-toggle-group-item-border-on, var(--xh-_toggle-group-item-border-on));
    --xh-action-border-focus-visible: var(--xh-toggle-group-item-border-on, var(--xh-_toggle-group-item-border-on));
    --xh-action-border-disabled: var(--xh-toggle-group-item-border-on-disabled, var(--xh-_toggle-group-item-border-on));
    --xh-action-shadow-rest: var(--xh-toggle-group-item-shadow, var(--xh-_toggle-group-item-highlight-on));
    --xh-action-shadow-hover: var(--xh-toggle-group-item-shadow, var(--xh-_toggle-group-item-highlight-on));
    --xh-action-shadow-pressed: var(--xh-toggle-group-item-shadow, var(--xh-_toggle-group-item-highlight-on));
    --xh-action-shadow-focus-visible: var(--xh-toggle-group-item-shadow, var(--xh-_toggle-group-item-highlight-on));

    /* 抬一层，让 brand 描边压住邻居的灰边。共边处两条边重合在同一像素上，
       不抬层就由文档序决定谁在上，选中段的左右两侧会一边有色一边灰 */
    z-index: 1;
  }

  /* solid 档的选中面是实心语气底，默认环压上去不足 3:1：环色改取配对前景色，经家族的焦点环桥接槽灌入 */
  [data-scope='toggle-group'][data-part='root'][data-variant='solid']
    [data-scope='toggle-group'][data-part='item'][data-state='on'] {
    --xh-action-ring-color-focus-visible: currentColor;
  }

  /* 集合条目一律 aria-disabled 而非原生 disabled（禁用项仍要能当方向键的起点），禁用面由家族按 data-disabled 给：
     底 / 字 / 边读上面映射的 -disabled 三支，不用 opacity 变淡（半透明会把压在下面那条边透出来，共边处当场变成两条线）；
     禁用且选中的段底色掺一半 muted 进 brand（映射在选中态那条里），既看得出选中，也看得出改不动；
     改不动的段收掉内高光：底已经掺了灰，再留一条亮线只剩噪点（家族的 -shadow-disabled 缺省 none） */

  /* 焦点环要浮在共边之上：outline 画在元素外侧，不抬层就会被后一段的底色与描边盖掉一半 */
  [data-scope='toggle-group'][data-part='item']:focus-visible {
    z-index: 2;
  }

  /* —— 撑满行宽 —— */
  /* 整组占满可用宽度，每段等分剩余空间。inline-flex 改成 flex：行内盒撑不满一行 */
  [data-scope='toggle-group'][data-part='root'][data-full-width] {
    display: flex;
    inline-size: 100%;
  }

  [data-scope='toggle-group'][data-part='root'][data-full-width]
    > [data-scope='toggle-group'][data-part='item'] {
    flex: 1;
  }

  /* —— 段间的线 —— */
  /* 装饰性的一条线，读屏不念。段本来靠共边连成一体，插了它就是把一排开关分成几组。
     朝向是这条线自己的（横排里是竖线），与 root 的排布相反 */
  [data-scope='toggle-group'][data-part='root'] > [data-xh-toggle-group-separator] {
    flex: none;
    align-self: center;
    z-index: 2;
    border-radius: var(--xh-toggle-group-separator-radius, var(--xh-shape-pill));
    background: var(--xh-toggle-group-separator-color, var(--xh-fg-default));
    opacity: var(--xh-toggle-group-separator-opacity, var(--xh-control-separator-opacity));
    pointer-events: none;
    transition: opacity var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='toggle-group'][data-part='root'] > [data-xh-toggle-group-separator][data-orientation='vertical'] {
    inline-size: var(--xh-toggle-group-separator-thickness, var(--xh-stroke-thin));
    block-size: var(
      --xh-toggle-group-separator-size,
      var(--xh-_group-separator-size)
    );
    margin-inline-start: calc(-1 * var(--xh-toggle-group-separator-thickness, var(--xh-stroke-thin)));
  }

  [data-scope='toggle-group'][data-part='root'] > [data-xh-toggle-group-separator][data-orientation='horizontal'] {
    block-size: var(--xh-toggle-group-separator-thickness, var(--xh-stroke-thin));
    inline-size: var(
      --xh-toggle-group-separator-size,
      var(--xh-_group-separator-size)
    );
    margin-block-start: calc(-1 * var(--xh-toggle-group-separator-thickness, var(--xh-stroke-thin)));
  }

  /* 段都按不动了，段间那条线跟着退到弱边一档 */
  [data-scope='toggle-group'][data-part='root'] > [data-xh-toggle-group-separator][data-disabled] {
    background: var(--xh-toggle-group-separator-color-disabled, var(--xh-border-subtle));
    opacity: var(--xh-toggle-group-separator-opacity-disabled, var(--xh-control-separator-disabled-opacity));
  }

  /* 插了分隔线之后首末两段不再是 root 的首末子节点，圆角改按元素类型认：
     条目是原生 button，分隔线不是。没有分隔线时这两条与上面按子节点认的那几条同值 */
  [data-scope='toggle-group'][data-part='root'][data-orientation='horizontal']
    > [data-scope='toggle-group'][data-part='item']:first-of-type {
    border-start-start-radius: var(--xh-toggle-group-item-radius, var(--xh-shape-control));
    border-end-start-radius: var(--xh-toggle-group-item-radius, var(--xh-shape-control));
  }

  [data-scope='toggle-group'][data-part='root'][data-orientation='horizontal']
    > [data-scope='toggle-group'][data-part='item']:last-of-type {
    border-start-end-radius: var(--xh-toggle-group-item-radius, var(--xh-shape-control));
    border-end-end-radius: var(--xh-toggle-group-item-radius, var(--xh-shape-control));
  }

  [data-scope='toggle-group'][data-part='root'][data-orientation='vertical']
    > [data-scope='toggle-group'][data-part='item']:first-of-type {
    border-start-start-radius: var(--xh-toggle-group-item-radius, var(--xh-shape-control));
    border-start-end-radius: var(--xh-toggle-group-item-radius, var(--xh-shape-control));
  }

  [data-scope='toggle-group'][data-part='root'][data-orientation='vertical']
    > [data-scope='toggle-group'][data-part='item']:last-of-type {
    border-end-start-radius: var(--xh-toggle-group-item-radius, var(--xh-shape-control));
    border-end-end-radius: var(--xh-toggle-group-item-radius, var(--xh-shape-control));
  }

  /* 连接层把它写成 type=hidden，UA 自己就不渲染；这里的视觉隐藏是给元素升级前那一瞬兜底
     （作者手写的是一个普通 input，升级完成前它是可见的文本框）。
     刻意不写 display：写了反而会盖掉 UA 对 type=hidden 的收起，把它显出来 */
  [data-scope='toggle-group'][data-part='hidden-input'] {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    border: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* 给了 display 的角色节点必须补这条：display 声明会盖掉 UA 的 [hidden]{display:none}，
     不补的话作者给节点加 hidden 后它照样显示 */
  [data-scope='toggle-group'][data-part='root'][hidden],
  [data-scope='toggle-group'][data-part='item'][hidden] {
    display: none;
  }

  /* 手指落点由家族给：text 档的 ::after 只在块轴外扩到 44px、行内轴按段的盒不动——
     条目在行内轴上靠负外边距共边相接，往两侧扩会与相邻条目的命中区叠上 */

  @media (forced-colors: active) {
    /* 段间那条线画的是一块纯底色，这一档里底色被统一换成 Canvas，线整条消失，
       几组开关就连成了一长串。换成前景色画回来 */
    [data-scope='toggle-group'][data-part='root'] > [data-xh-toggle-group-separator] {
      background: CanvasText;
    }

    [data-scope='toggle-group'][data-part='root'][data-variant='outline']::after {
      border-color: ButtonText;
    }

  }
}

/* styles/tool-call.css */
/* 定义 tool call 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立；
   独立皮肤同时传递引入开关的动作控件配方，full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='tool-call'] {
    --xh-tool-call-skin: 1;
  }

  /* 一张静态内容面：--xh-border-default 描边 + surface 底 + 无影（边界只由描边承担）；
     审批位与详情区的内部分隔线走另一支 --xh-tool-call-divider（subtle）。
     卡片建出来时淡入并向上收一段，一屏若干张的错峰交给外层容器排 */
  [data-scope='tool-call'][data-part='root'] {
    /* 尺寸缺省档：不写 data-size 时的取值。三档都只写这三个私有槽，
       公开槽留在读处当首选，作者在祖先上设的覆盖才赢得过档位声明 */
    --xh-_tool-call-px: var(--xh-space-3);
    --xh-_tool-call-py: var(--xh-space-2);
    --xh-_tool-call-font-size: var(--xh-control-font-md);

    /* 影另落一份进私有槽给语气档：它要把影与左侧色条叠成一条 box-shadow，缺省无影写成零影占位 */
    --xh-_tool-call-shadow: var(--xh-tool-call-shadow, 0 0 0 transparent);

    /* 作者塞进指示符里的图标与皮肤画的兜底字形同一把尺：md 档，开关上另按家族档取值 */
    --xh-icon-size: var(--xh-tool-call-icon-size, var(--xh-glyph-size-md));

    display: block;
    overflow: hidden;
    border: var(--xh-stroke-thin) solid var(--xh-tool-call-border, var(--xh-border-default));
    border-radius: var(--xh-tool-call-radius, var(--xh-shape-surface));
    background: var(--xh-tool-call-bg, var(--xh-bg-surface));
    box-shadow: var(--xh-tool-call-shadow, none);
    animation: xh-item-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong) both;
  }

  /* 上面声明的 display 会盖掉 UA 的 [hidden]{display:none}，这里补回 */
  [data-scope='tool-call'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 形态 —— */
  /* 缺省档即 outline，写在上面那条基础规则里 */
  /* 底色分区：描边让位给底色，嵌在别人的面里时不再多一圈线；
     淡底承载面向开关下发 hover 200 → pressed 300 */
  [data-scope='tool-call'][data-part='root'][data-variant='subtle'] {
    --xh-action-host-bg-hover: var(--xh-bg-subtle-hover);
    --xh-action-host-bg-pressed: var(--xh-bg-subtle-active);

    border-color: transparent;
    background: var(--xh-tool-call-bg, var(--xh-bg-subtle));
  }

  /* 无壳内联：卡中卡时不再自带一张面，跟着外层的底走 */
  [data-scope='tool-call'][data-part='root'][data-variant='ghost'] {
    --xh-_tool-call-shadow: 0 0 0 transparent;

    overflow: visible;
    border-color: transparent;
    background: none;
    box-shadow: none;
  }

  /* 无壳档的开关只占文字宽度（盖掉 profile 的铺满一行），自己带圆角，悬停时才浮出一块底 */
  [data-scope='tool-call'][data-part='root'][data-variant='ghost'] [data-scope='tool-call'][data-part='trigger'] {
    --xh-action-radius: var(--xh-tool-call-trigger-radius, var(--xh-shape-control));

    inline-size: auto;
  }

  /* 出错态换描边色，与语气轴各管各的：语气是作者定的强调，出错是组件自己的阶段。
     根上的 data-state 已经被开合占着，阶段落成 data-errored 这一位；八个承载阶段的部件
     渲出任何一个时那条 :has() 同样命中，两条并列，作者只渲根也照样变色 */
  [data-scope='tool-call'][data-part='root'][data-errored],
  [data-scope='tool-call'][data-part='root']:has([data-scope='tool-call'][data-state='output-error']) {
    border-color: var(--xh-tool-call-border-error, var(--xh-border-invalid));
  }

  /* 开关铺满一行，盒型、悬停 / 按下 / 禁用面由 Action Control 的 disclosure-trigger 档给（ghost 形态：
     白底承载 hover 100 → pressed 200，按下只换面不缩放）；这里只把使用者槽映射到桥接槽：
     圆角归零贴住卡边，内衬与字号沿用卡片的档位（不取 profile 的 md 档内衬，几何不变），
     字形按开关自己的档位取 --xh-_action-profile-glyph-size */
  [data-scope='tool-call'][data-part='trigger'] {
    --xh-action-radius: 0;
    --xh-action-gap: var(--xh-tool-call-trigger-gap, var(--xh-space-2));
    --xh-action-padding-inline: var(--xh-tool-call-px, var(--xh-_tool-call-px));
    --xh-action-padding-block: var(--xh-tool-call-py, var(--xh-_tool-call-py));
    --xh-action-font-size: var(--xh-tool-call-font-size, var(--xh-_tool-call-font-size));
    --xh-action-fg-rest: var(--xh-tool-call-trigger-fg, var(--xh-fg-default));
    --xh-action-bg-hover: var(--xh-tool-call-trigger-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-icon-size: var(--xh-tool-call-icon-size, var(--xh-_action-profile-glyph-size));

    border-width: 0;
  }

  [data-scope='tool-call'][data-part='trigger'][hidden] {
    display: none;
  }

  /* 指示随开合转向，纯装饰 */
  [data-scope='tool-call'][data-part='indicator'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    color: var(--xh-tool-call-indicator-fg, var(--xh-fg-subtle));
    /* 与详情开合同时长：箭头先转完、内容后到位会像是两件事。收起取 collapse 档，展开（下面的打开态）取 expand 档 */
    transition: rotate var(--xh-motion-duration-collapse) var(--xh-motion-ease-enter-strong);
  }

  /* 没写内容就由皮肤画；作者往部件里塞了自己的图形，这条规则即不命中 */
  [data-scope='tool-call'][data-part='indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-md));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
  }

  [data-scope='tool-call'][data-part='indicator'][hidden] {
    display: none;
  }

  /* 收起时朝向行首、展开时转向下方，与逻辑书写方向一致：
     rtl 下 inline-start 在右侧，箭头因此要反着转 */
  [data-scope='tool-call'][data-part='indicator'][data-state='open'] {
    rotate: 90deg;
    transition: rotate var(--xh-motion-duration-expand) var(--xh-motion-ease-enter-strong);
  }

  [dir='rtl'] [data-scope='tool-call'][data-part='indicator'] {
    rotate: 180deg;
  }

  [dir='rtl'] [data-scope='tool-call'][data-part='indicator'][data-state='open'] {
    rotate: 90deg;
  }

  /* 工具名占满剩余宽度并单行截断：长名字不该把状态挤出去 */
  [data-scope='tool-call'][data-part='label'] {
    display: block;
    overflow: hidden;
    flex: 1 1 auto;
    font-family: var(--xh-tool-call-label-font, var(--xh-font-family-mono));
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  [data-scope='tool-call'][data-part='label'][hidden] {
    display: none;
  }

  /* 有摘要时把剩余宽度让给它：工具名只要放得下自己，摘要才是这一行里最想读到的东西 */
  [data-scope='tool-call'][data-part='trigger']:has([data-part='summary']) [data-part='label'] {
    flex: 0 1 auto;
  }

  /* 一行参数摘要：单行截断的浅底条，收起时也看得见这次查的是什么 */
  [data-scope='tool-call'][data-part='summary'] {
    display: block;
    overflow: hidden;
    flex: 1 1 auto;
    min-inline-size: 0;
    padding-inline: var(--xh-tool-call-summary-px, var(--xh-space-1_5));
    border-radius: var(--xh-tool-call-summary-radius, var(--xh-shape-control));
    background: var(--xh-tool-call-summary-bg, var(--xh-bg-subtle));
    color: var(--xh-tool-call-summary-fg, var(--xh-fg-muted));
    font-family: var(--xh-tool-call-label-font, var(--xh-font-family-mono));
    font-size: var(--xh-tool-call-summary-font-size, var(--xh-text-caption-size));
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  [data-scope='tool-call'][data-part='summary'][hidden] {
    display: none;
  }

  [data-scope='tool-call'][data-part='status'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    color: var(--xh-tool-call-status-fg, var(--xh-fg-muted));
    font-size: var(--xh-tool-call-status-font-size, var(--xh-text-caption-size));
    line-height: var(--xh-leading-none);
  }

  [data-scope='tool-call'][data-part='status'][hidden] {
    display: none;
  }

  /* 三档落定的阶段收成药丸：淡底 + 同族深字。在跑的两档不带底，让扫光自己说话 */
  [data-scope='tool-call'][data-part='status'][data-state='awaiting-approval'],
  [data-scope='tool-call'][data-part='status'][data-state='output-available'],
  [data-scope='tool-call'][data-part='status'][data-state='output-error'] {
    padding-block: var(--xh-tool-call-status-py, var(--xh-space-0_5));
    padding-inline: var(--xh-tool-call-status-px, var(--xh-space-2));
    border-radius: var(--xh-tool-call-status-radius, var(--xh-shape-pill));
  }

  /* 各阶段的状态色：与语气轴分开走，语气是作者定的强调 */
  [data-scope='tool-call'][data-part='status'][data-state='awaiting-approval'] {
    background: var(--xh-tool-call-status-bg-approval, color-mix(in oklab, var(--xh-fg-warning) 12%, var(--xh-bg-surface)));
    color: var(--xh-tool-call-status-fg-approval, color-mix(in oklab, var(--xh-fg-warning) 60%, var(--xh-fg-default)));
  }

  [data-scope='tool-call'][data-part='status'][data-state='output-available'] {
    background: var(--xh-tool-call-status-bg-done, color-mix(in oklab, var(--xh-fg-success) 12%, var(--xh-bg-surface)));
    color: var(--xh-tool-call-status-fg-done, color-mix(in oklab, var(--xh-fg-success) 60%, var(--xh-fg-default)));
  }

  [data-scope='tool-call'][data-part='status'][data-state='output-error'] {
    background: var(--xh-tool-call-status-bg-error, color-mix(in oklab, var(--xh-fg-danger) 12%, var(--xh-bg-surface)));
    color: var(--xh-tool-call-status-fg-error, color-mix(in oklab, var(--xh-fg-danger) 60%, var(--xh-fg-default)));
  }

  /* 在跑的时候状态文字自己扫一道光：data-loading 此前在皮肤里没有任何表达，
     参数在传与参数齐了两档在屏幕上一模一样。
     渐变画在背景上再裁进字形，前景与 WebKit 的字形填充色都要透明才透得出底下那道光 */
  [data-scope='tool-call'][data-part='root'][data-loading] [data-part='status'] {
    background-image: linear-gradient(
      90deg,
      var(--xh-tool-call-status-shimmer-base, var(--xh-fg-subtle)) 35%,
      var(--xh-tool-call-status-shimmer-sheen, var(--xh-fg-default)) 50%,
      var(--xh-tool-call-status-shimmer-base, var(--xh-fg-subtle)) 65%
    );
    background-size: 200% 100%;
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    -webkit-text-fill-color: transparent;
    animation: xh-shimmer var(--xh-tool-call-shimmer-duration, var(--xh-shimmer-duration)) var(--xh-motion-ease-loop) infinite;
  }

  /* 减少动效：整道光撤掉换回平色，"在跑"仍由状态文字本身表达——只停动画的话，
     字形里会留着一段冻住的渐变。两条规则是同一件事的两个触发条件：系统偏好与作者打的 data-motion */
  @media (prefers-reduced-motion: reduce) {
    [data-scope='tool-call'][data-part='root'][data-loading] [data-part='status'] {
      background-image: none;
      color: var(--xh-tool-call-status-fg, var(--xh-fg-muted));
      -webkit-text-fill-color: currentColor;
      animation: none;
    }
  }

  :where([data-motion='reduce']) [data-scope='tool-call'][data-part='root'][data-loading] [data-part='status'] {
    background-image: none;
    color: var(--xh-tool-call-status-fg, var(--xh-fg-muted));
    -webkit-text-fill-color: currentColor;
    animation: none;
  }

  /* 耗时：等宽数位，秒数跳动时不左右挪 */
  [data-scope='tool-call'][data-part='duration'] {
    display: block;
    flex: none;
    color: var(--xh-tool-call-duration-fg, var(--xh-fg-subtle));
    font-size: var(--xh-tool-call-status-font-size, var(--xh-text-caption-size));
    font-variant-numeric: tabular-nums;
  }

  [data-scope='tool-call'][data-part='duration'][hidden] {
    display: none;
  }

  /* 审批闸门常驻在开关与详情之间，不随折叠一起藏起来 */
  [data-scope='tool-call'][data-part='approval'] {
    display: block;
    padding-inline: var(--xh-tool-call-px, var(--xh-_tool-call-px));
    padding-block: var(--xh-tool-call-py, var(--xh-_tool-call-py));
    border-block-start: var(--xh-stroke-thin) solid var(--xh-tool-call-divider, var(--xh-border-subtle));
  }

  [data-scope='tool-call'][data-part='approval'][hidden] {
    display: none;
  }

  /* 这里刻意没有 [data-part='content'][hidden] { display: none }：补了退场一帧都播不出来。
     收起由适配器在退场结束后写内联 display 落成，退场窗口内靠 connect 发的 inert 挡住焦点。
     详情区按阶段取舍，参数、结果与错误同一时刻只排一格，收起时整格随行高归零 */
  [data-scope='tool-call'][data-part='content'] {
    /* 行高与内缩同帧动的共享关键帧读这两条槽：两端内缩同值 */
    --xh-_disclosure-pt: var(--xh-tool-call-py, var(--xh-_tool-call-py));
    --xh-_disclosure-pb: var(--xh-tool-call-py, var(--xh-_tool-call-py));

    display: grid;
    grid-template-rows: 1fr;
    /* 块轴照旧裁掉：收起靠行高归零，多出来的那一截不能露在外面。
       行内一轴改成可横滚，宽过卡片的参数与结果推得回来看，不再被裁掉且取不回 */
    overflow-x: auto;
    overflow-y: clip;
    gap: var(--xh-tool-call-content-gap, var(--xh-space-2));
    padding-inline: var(--xh-tool-call-px, var(--xh-_tool-call-px));
    padding-block: var(--xh-tool-call-py, var(--xh-_tool-call-py));
    border-block-start: var(--xh-stroke-thin) solid var(--xh-tool-call-divider, var(--xh-border-subtle));
  }

  /* 展开那一档才提前备好行高这条通道：属性随 data-state 一起消失，收起后不长期占着 */
  [data-scope='tool-call'][data-part='content'][data-state='open'] {
    will-change: grid-template-rows;
    animation: xh-disclosure-expand var(--xh-motion-duration-expand) var(--xh-motion-ease-enter-strong);
  }

  /* 退场走 exit 档曲线 */
  [data-scope='tool-call'][data-part='content'][data-state='closed'] {
    animation: xh-disclosure-collapse var(--xh-motion-duration-collapse) var(--xh-motion-ease-exit) forwards;
  }

  [data-scope='tool-call'][data-part='input'],
  [data-scope='tool-call'][data-part='output'] {
    display: block;
    min-inline-size: 0;
  }

  [data-scope='tool-call'][data-part='input'][hidden],
  [data-scope='tool-call'][data-part='output'][hidden] {
    display: none;
  }

  /* 出错时开关的 aria-describedby 指过来；流被中止时这里可能是空的 */
  [data-scope='tool-call'][data-part='error'] {
    display: block;
    color: var(--xh-tool-call-error-fg, var(--xh-fg-danger));
    font-size: var(--xh-tool-call-status-font-size, var(--xh-text-caption-size));
  }

  [data-scope='tool-call'][data-part='error'][hidden] {
    display: none;
  }

  /* 尺寸档只改内衬与字号 */
  [data-scope='tool-call'][data-part='root'][data-size='sm'] {
    --xh-_tool-call-px: var(--xh-space-2);
    --xh-_tool-call-py: var(--xh-space-1);
    --xh-_tool-call-font-size: var(--xh-control-font-sm);
  }

  [data-scope='tool-call'][data-part='root'][data-size='md'] {
    --xh-_tool-call-px: var(--xh-space-3);
    --xh-_tool-call-py: var(--xh-space-2);
    --xh-_tool-call-font-size: var(--xh-control-font-md);
  }

  [data-scope='tool-call'][data-part='root'][data-size='lg'] {
    --xh-_tool-call-px: var(--xh-space-4);
    --xh-_tool-call-py: var(--xh-space-3);
    --xh-_tool-call-font-size: var(--xh-control-font-lg);
  }

  /* 语气只染左侧那一条色条，不夺走阶段色；海拔跟着一起写回来，
     box-shadow 是整条替换的，只写色条会把上面那层投影抹掉 */
  [data-scope='tool-call'][data-part='root'][data-tone] {
    box-shadow:
      inset var(--xh-tool-call-tone-bar, var(--xh-stroke-thick)) 0 0 0 var(--xh-tool-call-tone-fg, var(--xh-_tone-soft, var(--xh-bg-brand))),
      var(--xh-_tool-call-shadow);
  }
}

@layer xihan.motion {
  @media print {
    /* 打印：动画会被定格在任意一帧——转了一半的圈、扫到一半的微光。这里换成静止的表达，
       取值与减弱动效那一档相同。两档各写一块、不并进一条媒体查询列表：减弱动效另有一份
       :where([data-motion='reduce']) 的钩子版本与它成对，打印没有对应的钩子可配，
       并成一条之后这层配对关系在文本上就断了。 */
    [data-scope='tool-call'][data-part='root'][data-loading] [data-part='status'] {
      background-image: none;
      color: var(--xh-tool-call-status-fg, var(--xh-fg-muted));
      -webkit-text-fill-color: currentColor;
      animation: none;
    }
  }

  /*
   * 高对比档：扫光那层渐变被丢弃，只剩被裁成透明的字形填充，状态文字整段消失。
   * 把两处填充都还回去，在跑这件事仍由状态文字本身表出。
   */
  @media (forced-colors: active) {
    [data-scope='tool-call'][data-part='root'][data-loading] [data-part='status'] {
      background-image: none;
      -webkit-background-clip: border-box;
      background-clip: border-box;
      color: CanvasText;
      -webkit-text-fill-color: currentColor;
      animation: none;
    }
  }
}

/* styles/toolbar.css */
/* 定义 toolbar 样式。 */

/* 独立皮肤传递引入条目的动作控件配方，full bundle 递归去重。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='toolbar'] {
    --xh-toolbar-skin: 1;
  }

  /* 一条控件带：条目之间留固定间距，分隔线再把它们切成语义上的几段。
     排布只能读 data-orientation——它与 aria-orientation 同源，但样式不该去读 ARIA */
  [data-scope='toolbar'][data-part='root'] {
    /* 尺寸档同时约束工具条排布与默认条目。 */
    --xh-_toolbar-gap: var(--xh-space-2);
    --xh-_toolbar-p: var(--xh-space-1);
    --xh-_toolbar-item-h: var(--xh-control-h-md);
    --xh-_toolbar-separator-size: calc(var(--xh-_toolbar-item-h) / 2);
    --xh-icon-size: var(--xh-toolbar-icon-size, var(--xh-glyph-size-md));

    /* 缺省 ghost：工具条只组织控件，不额外画外框；条目按画布承载走 hover 100 → pressed 200。 */
    --xh-_toolbar-root-p: 0;
    --xh-_toolbar-root-border-width: 0;
    --xh-_toolbar-root-border: transparent;
    --xh-_toolbar-root-bg: transparent;
    --xh-_toolbar-root-bg-disabled: transparent;

    /* 一行排不下就折行：条目宽度由各自的控件决定，硬撑一行会把整条顶出容器 */
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--xh-toolbar-gap, var(--xh-_toolbar-gap));
    padding-block: var(--xh-toolbar-py, var(--xh-_toolbar-root-p));
    padding-inline: var(--xh-toolbar-px, var(--xh-_toolbar-root-p));
    border: var(--xh-_toolbar-root-border-width) solid var(--xh-toolbar-border, var(--xh-_toolbar-root-border));
    border-radius: var(--xh-toolbar-radius, var(--xh-shape-surface));
    background: var(--xh-toolbar-bg, var(--xh-_toolbar-root-bg));
    color: var(--xh-toolbar-fg, var(--xh-fg-default));
    /* 整条置灰与恢复是一次状态切换，底色与字色淡着换，不硬切 */
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  [data-scope='toolbar'][data-part='root'][data-orientation='horizontal'] {
    flex-direction: row;
  }

  /* 竖排时交叉轴改为拉伸：竖着的一条里每个条目该一样宽，居中会让它们参差不齐 */
  [data-scope='toolbar'][data-part='root'][data-orientation='vertical'] {
    flex-direction: column;
    align-items: stretch;
    flex-wrap: nowrap;
  }

  /* —— 变体 —— */
  [data-scope='toolbar'][data-part='root'][data-variant='ghost'] {
    --xh-_toolbar-root-p: 0;
    --xh-_toolbar-root-border-width: 0;
    --xh-_toolbar-root-border: transparent;
    --xh-_toolbar-root-bg: transparent;
    --xh-_toolbar-root-bg-disabled: transparent;
  }

  /* 淡底档：带内距、换成 subtle 底，描边让位给底色但留住 1px 边位（与 outline 几何一致），无影；
     淡底承载面向条目下发 hover 200 → pressed 300 */
  [data-scope='toolbar'][data-part='root'][data-variant='subtle'] {
    --xh-_toolbar-root-p: var(--xh-_toolbar-p);
    --xh-_toolbar-root-border-width: var(--xh-stroke-thin);
    --xh-_toolbar-root-bg: var(--xh-bg-subtle);
    --xh-action-host-bg-hover: var(--xh-bg-subtle-hover);
    --xh-action-host-bg-pressed: var(--xh-bg-subtle-active);
  }

  /* 附着式工具面：一张静态内容面，--xh-border-default 描边 + surface 底 + 无影（边界只由描边承担）。 */
  [data-scope='toolbar'][data-part='root'][data-variant='outline'] {
    --xh-_toolbar-root-p: var(--xh-_toolbar-p);
    --xh-_toolbar-root-border-width: var(--xh-stroke-thin);
    --xh-_toolbar-root-border: var(--xh-border-default);
    --xh-_toolbar-root-bg: var(--xh-bg-surface);
    --xh-_toolbar-root-bg-disabled: var(--xh-bg-muted);

    border-radius: var(--xh-toolbar-radius, var(--xh-shape-surface));
    box-shadow: var(--xh-toolbar-shadow, none);
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里。工具条自己不定条目的高度与字号（那归条目的皮肤），
     这里只换排布尺寸；缺省的 --xh-space-1 已经是控件间距那把尺的小档，容不下三档，故一律取空间尺 */
  [data-scope='toolbar'][data-part='root'][data-size='sm'] {
    --xh-_toolbar-gap: var(--xh-space-0_5);
    --xh-_toolbar-p: var(--xh-space-0_5);
    --xh-_toolbar-item-h: var(--xh-control-h-sm);
    --xh-icon-size: var(--xh-toolbar-icon-size, var(--xh-glyph-size-sm));
  }

  [data-scope='toolbar'][data-part='root'][data-size='lg'] {
    --xh-_toolbar-gap: var(--xh-space-3);
    --xh-_toolbar-p: var(--xh-space-2);
    --xh-_toolbar-item-h: var(--xh-control-h-lg);
    --xh-icon-size: var(--xh-toolbar-icon-size, var(--xh-glyph-size-lg));
  }

  /* root 会在焦点进条前短暂拿到 tabindex=0，但它的 onFocus 立刻把焦点转投给条目，
     在它身上画环只会闪一下就跳走，高亮要长在条目上 */
  [data-scope='toolbar'][data-part='root']:focus-visible {
    outline: none;
  }

  [data-scope='toolbar'][data-part='root'][data-disabled] {
    background: var(--xh-toolbar-bg-disabled, var(--xh-_toolbar-root-bg-disabled));
    color: var(--xh-fg-disabled);
  }

  /* 给了 display 的角色节点必须补这条：display 声明会盖掉 UA 的 [hidden]{display:none}，
     不补的话作者给节点加 hidden 后它照样显示 */
  [data-scope='toolbar'][data-part='root'][hidden] {
    display: none;
  }

  /* 分组只负责把相关操作连成一条，表面与交互状态由每个分段自己绘制。 */
  [data-scope='toolbar'][data-part='group'] {
    display: inline-flex;
    flex-wrap: nowrap;
    align-items: stretch;
    gap: var(--xh-toolbar-group-gap, var(--xh-space-0));
    background: transparent;
  }

  [data-scope='toolbar'][data-part='group'][data-orientation='vertical'] {
    flex-direction: column;
    align-items: stretch;
    flex-wrap: nowrap;
  }

  [data-scope='toolbar'][data-part='group'][hidden] {
    display: none;
  }

  /* 默认条目是一枚无描边工具按钮：盒型、三档几何、悬停 / 按下 / 禁用面与按压缩放由 Action Control 的
     text 档给（ghost 形态：ghost 根按画布承载 hover 100 → pressed 200，subtle 根与分组由 host 槽下发
     200 → 300）；这里只把使用者槽映射到桥接槽（-gap / -h / -px / -radius / -bg / -bg-hover /
     -bg-active / -bg-disabled / -fg / -font-size 保留为第一参数）。作者仍可用类名或内联样式完整覆盖。 */
  [data-scope='toolbar'][data-part='item'] {
    --xh-action-gap: var(--xh-toolbar-item-gap, var(--xh-control-gap-sm));
    --xh-action-visual-size: var(--xh-toolbar-item-h, var(--xh-_action-profile-visual-size));
    --xh-action-padding-inline: var(--xh-toolbar-item-px, var(--xh-_action-profile-padding-inline));
    --xh-action-radius: var(--xh-toolbar-item-radius, var(--xh-_action-profile-radius));
    --xh-action-bg-rest: var(--xh-toolbar-item-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-toolbar-item-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-toolbar-item-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-bg-disabled: var(--xh-toolbar-item-bg-disabled, var(--xh-_action-variant-bg-disabled));
    --xh-action-fg-rest: var(--xh-toolbar-item-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-toolbar-item-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-toolbar-item-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-font-size: var(--xh-toolbar-item-font-size, var(--xh-_action-profile-font-size));

    font-weight: var(--xh-toolbar-item-font-weight, var(--xh-text-label-weight));
    touch-action: manipulation;
  }

  /* 无滑块开关的按下态：品牌淡底 + 淡底前景，hover / 按下沿 12% → 20% → 28% 三档走；
     三态都经桥接槽交给家族画，禁用面仍由家族按 data-disabled 给 */
  [data-scope='toolbar'][data-part='item'][aria-pressed='true'] {
    --xh-action-bg-rest: var(--xh-toolbar-item-bg-pressed, var(--xh-bg-brand-subtle));
    --xh-action-bg-hover: var(--xh-toolbar-item-bg-pressed-hover, var(--xh-bg-brand-subtle-hover));
    --xh-action-bg-pressed: var(--xh-toolbar-item-bg-pressed-active, var(--xh-bg-brand-subtle-active));
    --xh-action-fg-rest: var(--xh-toolbar-item-fg-pressed, var(--xh-fg-on-brand-subtle));
    --xh-action-fg-hover: var(--xh-toolbar-item-fg-pressed, var(--xh-fg-on-brand-subtle));
    --xh-action-fg-pressed: var(--xh-toolbar-item-fg-pressed, var(--xh-fg-on-brand-subtle));
  }

  [data-scope='toolbar'][data-part='item'][hidden] {
    display: none;
  }

  /* 组内分段使用同一块中性操作面（淡底承载：hover 200 → pressed 300 由 host 槽下发）；
     中间段保持直角，只给整组两端补回控件圆角。按下态 / 禁用面与散落条目同一套规则 */
  [data-scope='toolbar'][data-part='group'] > [data-scope='toolbar'][data-part='item'] {
    --xh-action-host-bg-hover: var(--xh-bg-subtle-hover);
    --xh-action-host-bg-pressed: var(--xh-bg-subtle-active);
    --xh-action-radius: 0;
    --xh-action-bg-disabled: var(--xh-toolbar-item-bg-disabled, var(--xh-bg-subtle));

    position: relative;
  }

  /* 组内未选中的段才铺中性面：选中段的品牌淡底由上面 aria-pressed 那条给，这条比它更特定，不守卫会把它盖掉 */
  [data-scope='toolbar'][data-part='group'] > [data-scope='toolbar'][data-part='item']:not([aria-pressed='true']) {
    --xh-action-bg-rest: var(--xh-toolbar-item-bg, var(--xh-bg-subtle));
  }

  [data-scope='toolbar'][data-part='group'][data-orientation='horizontal']
    > [data-scope='toolbar'][data-part='item']:first-of-type {
    border-start-start-radius: var(--xh-toolbar-item-radius, var(--xh-shape-control));
    border-end-start-radius: var(--xh-toolbar-item-radius, var(--xh-shape-control));
  }

  [data-scope='toolbar'][data-part='group'][data-orientation='horizontal']
    > [data-scope='toolbar'][data-part='item']:last-of-type {
    border-start-end-radius: var(--xh-toolbar-item-radius, var(--xh-shape-control));
    border-end-end-radius: var(--xh-toolbar-item-radius, var(--xh-shape-control));
  }

  [data-scope='toolbar'][data-part='group'][data-orientation='vertical']
    > [data-scope='toolbar'][data-part='item']:first-of-type {
    border-start-start-radius: var(--xh-toolbar-item-radius, var(--xh-shape-control));
    border-start-end-radius: var(--xh-toolbar-item-radius, var(--xh-shape-control));
  }

  [data-scope='toolbar'][data-part='group'][data-orientation='vertical']
    > [data-scope='toolbar'][data-part='item']:last-of-type {
    border-end-start-radius: var(--xh-toolbar-item-radius, var(--xh-shape-control));
    border-end-end-radius: var(--xh-toolbar-item-radius, var(--xh-shape-control));
  }

  /* 分隔线取控件高度的一半；横排工具条里画竖线，竖排工具条里画横线。 */
  [data-scope='toolbar'][data-part='separator'] {
    flex: none;
    align-self: center;
    border-radius: var(--xh-toolbar-separator-radius, var(--xh-shape-pill));
    background: var(--xh-toolbar-separator-color, var(--xh-border-default));
  }

  [data-scope='toolbar'][data-part='separator'][data-orientation='vertical'] {
    inline-size: var(--xh-toolbar-separator-thickness, var(--xh-stroke-thin));
    block-size: var(--xh-_toolbar-separator-size);
    margin-block: var(--xh-toolbar-separator-inset, var(--xh-space-0));
    margin-inline: var(--xh-toolbar-separator-gap, var(--xh-space-0));
  }

  [data-scope='toolbar'][data-part='separator'][data-orientation='horizontal'] {
    block-size: var(--xh-toolbar-separator-thickness, var(--xh-stroke-thin));
    inline-size: var(--xh-_toolbar-separator-size);
    margin-block: var(--xh-toolbar-separator-gap, var(--xh-space-0));
    margin-inline: var(--xh-toolbar-separator-inset, var(--xh-space-0));
  }

  /* 组内分隔线覆盖在相邻分段的接缝上，不占额外宽度；半高弱线保留整体连续感。 */
  [data-scope='toolbar'][data-part='group'] > [data-scope='toolbar'][data-part='separator'] {
    background: var(--xh-toolbar-separator-color, var(--xh-fg-default));
    opacity: var(--xh-toolbar-separator-opacity, var(--xh-control-separator-opacity));
    pointer-events: none;
  }

  [data-scope='toolbar'][data-part='group'] > [data-scope='toolbar'][data-part='separator'][data-orientation='vertical'] {
    margin-inline-start: calc(-1 * var(--xh-toolbar-separator-thickness, var(--xh-stroke-thin)));
  }

  [data-scope='toolbar'][data-part='group'] > [data-scope='toolbar'][data-part='separator'][data-orientation='horizontal'] {
    margin-block-start: calc(-1 * var(--xh-toolbar-separator-thickness, var(--xh-stroke-thin)));
  }

  @media (forced-colors: active) {
    /* 分段之间那条线画的是一块纯底色，这一档里底色被统一换成 Canvas，线整条消失，
       几段控件就连成了一长串。换成前景色画回来 */
    [data-scope='toolbar'][data-part='separator'] {
      background: CanvasText;
    }
  }
}

/* styles/tooltip.css */
/* 定义 tooltip 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='tooltip'] {
    --xh-tooltip-skin: 1;
  }

  [data-scope='tooltip'][data-part='trigger'] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--xh-tooltip-trigger-gap, var(--xh-control-gap-sm));
    border: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    cursor: inherit;
  }

  /* 这里的 data-disabled 关掉的是提示，不是宿主控件：光标仍旧交给宿主 */
  [data-scope='tooltip'][data-part='trigger'][data-disabled] {
    cursor: inherit;
  }

  /* 坐标由定位引擎写在行内 style 上，这里只兜底 SSR 首帧 */
  [data-scope='tooltip'][data-part='positioner'] {
    /* 先截断祖先浮层的方向，再按本次实际 placement 只启用一侧。 */
    --xh-_overlay-enter-up: 0;
    --xh-_overlay-enter-down: 0;
    --xh-_overlay-enter-left: 0;
    --xh-_overlay-enter-right: 0;

    position: fixed;
    inset-block-start: 0;
    inset-inline-start: 0;
    z-index: var(--xh-tooltip-layer, var(--xh-_layer, var(--xh-layer-tooltip)));
    /* 浮层不承载交互：指针必须能穿过去点到底下的东西 */
    pointer-events: none;
  }

  /* 锚点滚出可视区时连浮层一起隐藏 */
  [data-scope='tooltip'][data-part='positioner'][data-hidden] {
    visibility: hidden;
  }

  /* 进退位移按落定的那一侧给。placement 与 translate 都是物理方向，不随书写方向翻。 */
  [data-scope='tooltip'][data-part='positioner'][data-placement^='top'] {
    --xh-_overlay-enter-down: 1;
  }

  [data-scope='tooltip'][data-part='positioner'][data-placement^='bottom'] {
    --xh-_overlay-enter-up: 1;
  }

  [data-scope='tooltip'][data-part='positioner'][data-placement^='left'] {
    --xh-_overlay-enter-right: 1;
  }

  [data-scope='tooltip'][data-part='positioner'][data-placement^='right'] {
    --xh-_overlay-enter-left: 1;
  }

  [data-scope='tooltip'][data-part='content'] {
    /* 尺寸档只换这三个私有槽。tooltip 没有 root 部件，两轴都落在浮层树最外层的 content 上，
       箭头是它的后代，语气槽一并继承 */
    --xh-_tooltip-py: var(--xh-space-1);
    --xh-_tooltip-px: var(--xh-space-2);
    --xh-_tooltip-font-size: var(--xh-control-caption-md);
    /* Tooltip 保留反白身份（登记的反白 compact frosted）：短提示要与可交互的普通主题浮层一眼分开。
       94% 是六种 tone 在纯黑/纯白最坏底色上仍托住 4.5:1 正文的首个安全档。
       边不取 --xh-material-frosted-border：那是深色 14% 的透明边，压在反白深底上看不见，
       浮层要的 1px 可见边界由 on 色 20% 拼色承担；浮层不用玻璃高光，顶光缺省不画 */
    --xh-_tooltip-solid: var(--xh-_tone, var(--xh-fg-default));
    --xh-_tooltip-on: var(--xh-_tone-on, var(--xh-bg-surface));
    --xh-_tooltip-border: color-mix(in oklab, var(--xh-_tooltip-on) 20%, transparent);

    /* 与 positioner 相反：浮层本体要能接指针，指针停在提示上就不该收起
       （长文案需要停留细看）。positioner 仍是 none，空白区域照样点得穿。 */
    /* 显式声明 display 是为了盖掉 UA 的 [hidden]{display:none}：收起那一帧 content 仍带 hidden，
       盒子得先在,退场动画才播得出来。真正的收起由宿主在退场结束后落成内联 display */
    display: block;
    position: relative;
    isolation: isolate;
    pointer-events: auto;
    max-inline-size: var(--xh-tooltip-max-w, var(--xh-overlay-max-w));
    padding-block: var(--xh-tooltip-py, var(--xh-_tooltip-py));
    padding-inline: var(--xh-tooltip-px, var(--xh-_tooltip-px));
    /* 这里刻意用 control 而不是浮层那档 surface：提示气泡通常只有一行字、高度接近控件，
       8px 圆角在这个尺寸上占比过大，看着会发胖。档位定义里为此单列了一条 */
    border-radius: var(--xh-tooltip-radius, var(--xh-shape-control));
    border: var(--xh-stroke-thin) solid var(--xh-tooltip-border, var(--xh-_tooltip-border));
    background: transparent;
    color: var(--xh-tooltip-fg, var(--xh-_tooltip-on));
    font-size: var(--xh-tooltip-font-size, var(--xh-_tooltip-font-size));
    line-height: var(--xh-leading-normal);
    overflow-wrap: anywhere;
    text-wrap: pretty;
    --xh-_tooltip-elevation-shadow: var(--xh-tooltip-shadow, var(--xh-material-frosted-compact-shadow));

    /* 顶光槽缺省透明（不用顶部高光），使用者要加自行灌色 */
    box-shadow:
      inset 0 var(--xh-stroke-thin) 0 var(--xh-tooltip-highlight, transparent),
      var(--xh-_tooltip-elevation-shadow);
    -webkit-backdrop-filter: var(--xh-tooltip-backdrop, var(--xh-material-frosted-compact-backdrop));
    backdrop-filter: var(--xh-tooltip-backdrop, var(--xh-material-frosted-compact-backdrop));
  }

  /* 光学层单独承载 tint 与透明度；backdrop-filter 只采样元素背后，不处理正文。 */
  [data-scope='tooltip'][data-part='content']::before {
    content: '';
    position: absolute;
    z-index: -1;
    inset: 0;
    border-radius: inherit;
    background: var(--xh-tooltip-bg, var(--xh-_tooltip-solid));
    opacity: var(--xh-material-frosted-compact-alpha);
    pointer-events: none;
  }

  /* 入场走 enter 档（锚定列表族的 tooltip 入场 --xh-motion-duration-enter），退场仍是 exit */
  [data-scope='tooltip'][data-part='content'][data-state='open'] {
    animation: xh-overlay-slide-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 退场：收起那一帧 hidden 由退场闸门押后，这里才播得出来。forwards 把末态钉住，
     免得动画结束到真收起之间闪一下原样 */
  [data-scope='tooltip'][data-part='content'][data-state='closed'] {
    will-change: opacity, translate;
    animation: xh-overlay-slide-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* —— 尺寸 —— */
  /* 缺省档写在 content 的基础规则里。提示的内边距与字号本就不在 control-* 那把尺上
     （它是浮层不是控件），故按 space / font-size 档上下各挪一级 */
  [data-scope='tooltip'][data-part='content'][data-size='sm'] {
    --xh-_tooltip-py: var(--xh-space-0_5);
    --xh-_tooltip-px: var(--xh-space-1_5);
    --xh-_tooltip-font-size: var(--xh-control-caption-sm);
  }

  [data-scope='tooltip'][data-part='content'][data-size='lg'] {
    --xh-_tooltip-py: var(--xh-space-1_5);
    --xh-_tooltip-px: var(--xh-space-2_5);
    --xh-_tooltip-font-size: var(--xh-control-caption-lg);
  }

  /* 箭头的底色与描边色，几何在 overlay-arrow.css。
     交叉轴落点由定位引擎经内联自定义属性写进来，没给时退回居中 */
  [data-scope='tooltip'][data-part='arrow'] {
    --xh-_tooltip-arrow-x: 50%;
    --xh-_tooltip-arrow-y: 50%;
    --xh-_overlay-arrow-size: var(--xh-tooltip-arrow-size, var(--xh-overlay-arrow-size));
    --xh-_overlay-arrow-x: var(--xh-_tooltip-arrow-x);
    --xh-_overlay-arrow-y: var(--xh-_tooltip-arrow-y);

    background: var(--xh-tooltip-bg, var(--xh-_tooltip-solid));
    border: var(--xh-stroke-thin) solid var(--xh-tooltip-border, var(--xh-_tooltip-border));
    opacity: var(--xh-material-frosted-compact-alpha);
  }

  /* 高对比仍保持反白语义：compact 配方已把 tint / blur / shadow 换成实体档，此处只加强同色边界。 */
  :is([data-contrast='more'] *, [data-contrast='more'])[data-scope='tooltip'][data-part='content'] {
    --xh-_tooltip-border: var(--xh-_tooltip-on);
  }

  @media (forced-colors: active) {
    [data-scope='tooltip'][data-part='content'],
    [data-scope='tooltip'][data-part='arrow'] {
      border-color: CanvasText;
      background: Canvas;
      color: CanvasText;
      box-shadow: none;
      -webkit-backdrop-filter: none;
      backdrop-filter: none;
    }

    [data-scope='tooltip'][data-part='content']::before {
      background: Canvas;
      opacity: 1;
    }
  }

  /* 声明过任何 display 就盖掉了 UA 的 [hidden]{display:none}，收起态得自己还回去。
     写在文件末尾：兜底必须排在该部件所有 display 声明之后 */
  [data-scope='tooltip'][data-part='trigger'][hidden] {
    display: none;
  }

  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。 */
    [data-scope='tooltip'][data-part='positioner'] {
      display: none;
    }
  }
}

/* styles/tour.css */
/* 定义 tour 样式。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.motion {
  /* 高亮框落定时那一下呼吸：换步时视线要跟着它走，纯位移太容易被漏看 */
  @keyframes xh-tour-spotlight-in {
    from {
      opacity: 0;
      scale: calc(2 - var(--xh-motion-scale-enter));
    }

    to {
      opacity: 1;
      scale: 1;
    }
  }

  /* 退场反向放大淡出，幅度比进场浅一档 */
  @keyframes xh-tour-spotlight-out {
    from {
      opacity: 1;
      scale: 1;
    }

    to {
      opacity: 0;
      scale: calc(2 - var(--xh-motion-scale-exit));
    }
  }
}

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='tour'] {
    --xh-tour-skin: 1;
  }

  /* 根节点只是几个浮层的归属容器，不参与排版。
     这里不给 display，UA 的 [hidden]{display:none} 就仍然压得住 */
  [data-scope='tour'][data-part='root'] {
    /* 作者塞进部件里的图标按控件档取字形尺（md = 20px）；四颗按钮各自再按 sm 档收一档 */
    --xh-icon-size: var(--xh-tour-icon-size, var(--xh-glyph-size-md));

    color: var(--xh-tour-fg, var(--xh-fg-default));
  }

  /* 浮层被搬到 portal 落点，继承不到 root 上的槽：这把尺在被搬走的那一侧再声明一次，
     关闭钮与条目里作者塞的图标才和皮肤画的兜底字形一样大 */
  [data-scope='tour'][data-part='content'] {
    --xh-icon-size: var(--xh-tour-icon-size, var(--xh-glyph-size-md));
  }

  /* 遮罩：整页压暗，把注意力逼到高亮框那一块上 */
  [data-scope='tour'][data-part='backdrop'] {
    position: fixed;
    inset: 0;
    z-index: var(--xh-tour-backdrop-layer, var(--xh-_layer, var(--xh-layer-modal)));
    background: var(--xh-tour-backdrop-bg, var(--xh-bg-overlay));
  }

  [data-scope='tour'][data-part='backdrop'][hidden] {
    display: none;
  }

  [data-scope='tour'][data-part='backdrop'][data-state='open'] {
    animation: xh-fade-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter);
  }

  [data-scope='tour'][data-part='backdrop'][data-state='closed'] {
    animation: xh-fade-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* 挖洞的高亮框。位置与尺寸由连接层量出来写进内联 style（position/inset/尺寸那几条轴归它），
     这里只管长相：一圈描边 + 一片铺满视口的投影当暗幕，中间那块因此是亮的——
     这就是"洞"。不吃指针：它盖在目标上面，吃了的话目标就再也点不动了 */
  [data-scope='tour'][data-part='spotlight'] {
    --xh-_tour-spotlight-shroud: transparent;
    --xh-_tour-spotlight-radius: var(--xh-shape-surface);

    z-index: var(--xh-tour-spotlight-layer, var(--xh-_layer, var(--xh-layer-modal)));
    pointer-events: none;
    border-radius: var(
      --xh-tour-spotlight-radius,
      var(--xh-_tour-spotlight-radius, var(--xh-shape-surface))
    );
    box-shadow:
      0 0 0 var(--xh-stroke-thick) var(--xh-tour-spotlight-ring, var(--xh-ring-focus)),
      0 0 0 100vmax var(--xh-_tour-spotlight-shroud);
    /* 换步时框自己滑过去，用户的视线跟得上；逻辑属性照样可过渡 */
    transition:
      inset-inline-start var(--xh-motion-duration-move) var(--xh-motion-ease-continuous),
      inset-block-start var(--xh-motion-duration-move) var(--xh-motion-ease-continuous),
      inline-size var(--xh-motion-duration-move) var(--xh-motion-ease-continuous),
      block-size var(--xh-motion-duration-move) var(--xh-motion-ease-continuous),
      border-radius var(--xh-motion-duration-enter) var(--xh-motion-ease-continuous);
  }

  [data-scope='tour'][data-part='spotlight'][data-dimmed] {
    --xh-_tour-spotlight-shroud: var(--xh-tour-spotlight-shroud, var(--xh-bg-overlay));
  }

  [data-scope='tour'][data-part='spotlight'][hidden] {
    display: none;
  }

  [data-scope='tour'][data-part='spotlight'][data-state='open'] {
    animation: xh-tour-spotlight-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 退场与气泡并行播，同一段时长；收起那一帧 hidden 由宿主押后到气泡的退场结束 */
  [data-scope='tour'][data-part='spotlight'][data-state='closed'] {
    animation: xh-tour-spotlight-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* 锚定步的暗幕由 Spotlight 自己挖洞，Backdrop 只负责拦截背景交互。状态直接由连接层给，
     不依赖两个 Portal shell 在落点里的相对顺序。 */
  [data-scope='tour'][data-part='backdrop'][data-position='anchored'] {
    background: transparent;
  }

  /* 空壳不吃指针，交互只发生在 content 上。
     锚定步的坐标由定位引擎写进内联 style，这里不碰那两条轴 */
  [data-scope='tour'][data-part='positioner'] {
    /* 落定那一侧的可用高度，由定位引擎经内联自定义属性写进来，气泡继承它限高；
       居中步与尚未落位时不额外限高 */
    --xh-_tour-available-h: 100vh;
    /* 落定那一侧的可用宽度，同样由定位引擎经内联自定义属性写进来，行内轴据此夹取；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时退到视口宽 */
    --xh-_tour-available-w: 100vw;

    z-index: var(--xh-tour-positioner-layer, var(--xh-_layer, var(--xh-layer-popover)));
    pointer-events: none;
  }

  /* 居中步：没有锚点，铺满视口把气泡摆中间 */
  [data-scope='tour'][data-part='positioner'][data-position='center'] {
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: var(--xh-tour-positioner-padding, var(--xh-space-4));
  }

  /* 必须排在 data-position='center' 之后：两条选择器的特指度相同（都是三个属性），
     写在前面会被那条 display:flex 盖掉，收起态的居中步就一直摊在屏幕上 */
  [data-scope='tour'][data-part='positioner'][hidden] {
    display: none;
  }

  /* 缩放原点与进场位移按落定的那一侧给：气泡从贴着锚点的那条边涨开、沿主轴退让一小段。
     两个槽由 content 继承。只认锚定步：居中步没有锚点，data-placement 仍带着缺省值。
     placement 是物理方向（引擎按 top / right / bottom / left 出值），origin 与 translate
     也是物理量，两边同轴，不随书写方向翻 */
  [data-scope='tour'][data-part='positioner'][data-position='anchored'][data-placement^='top'] {
    --xh-_overlay-origin-y: 100%;
    --xh-_overlay-enter-down: 1;
  }

  [data-scope='tour'][data-part='positioner'][data-position='anchored'][data-placement^='bottom'] {
    --xh-_overlay-origin-y: 0;
    --xh-_overlay-enter-up: 1;
  }

  [data-scope='tour'][data-part='positioner'][data-position='anchored'][data-placement^='left'] {
    --xh-_overlay-origin-x: 100%;
    --xh-_overlay-enter-right: 1;
  }

  [data-scope='tour'][data-part='positioner'][data-position='anchored'][data-placement^='right'] {
    --xh-_overlay-origin-x: 0;
    --xh-_overlay-enter-left: 1;
  }

  [data-scope='tour'][data-part='content'] {
    position: relative;
    display: flex;
    flex-direction: column;
    gap: var(--xh-tour-gap, var(--xh-space-2));
    inline-size: max-content;
    /* 静态档与落位后的可用宽度取小：窄视口下面板伸出去，最右侧的内容就点不到了 */
    max-inline-size: min(var(--xh-tour-max-w, var(--xh-overlay-max-w-lg)), var(--xh-_tour-available-w));
    padding-block: var(--xh-tour-py, var(--xh-surface-py-md));
    padding-inline: var(--xh-tour-px, var(--xh-surface-px-md));
    /* 引导步骤的正文长度由作者定，矮视口下不限高气泡会整块伸出视口 */
    max-block-size: min(var(--xh-tour-max-h, var(--xh-overlay-max-h)), var(--xh-_tour-available-h));
    /* M4 sheet 三件套，与 dialog 同源：1px 描边是它的边界，不透明底，影只是加成 */
    border: var(--xh-stroke-thin) solid var(--xh-tour-border, var(--xh-material-elevated-border));
    border-radius: var(--xh-tour-radius, var(--xh-shape-overlay));
    background: var(--xh-tour-bg, var(--xh-material-elevated-bg));
    color: var(--xh-tour-fg, var(--xh-material-elevated-fg));
    box-shadow: var(--xh-tour-shadow, var(--xh-material-elevated-shadow));
    pointer-events: auto;
    /* 进退场的缩放锚在贴着锚点的那条边上；两个分量由 positioner 按 placement 写进私有槽 */
    transform-origin: var(--xh-_overlay-origin-x, 50%) var(--xh-_overlay-origin-y, 50%);
  }

  /* 这里刻意没有 [data-part='content'][hidden] { display: none }，与 popover 一致：
     收起态连接层会给 content 打 hidden，补上这条退场动画就一帧都播不出来。
     真正的收起由退场闸门落成内联 display，节点始终留在原地。 */

  /* 焦点落在气泡本身，Enter / Space 落在它身上推进下一步：它是可操作目标，
     环由 focus.css 的默认内收环画，这里不另写 */

  [data-scope='tour'][data-part='content'][data-state='open'] {
    animation: xh-overlay-pop-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 退场：收起那一帧 hidden 由退场闸门押后，这里才播得出来。forwards 把末态钉住，
     免得动画结束到收起落下来之间闪一下原样 */
  [data-scope='tour'][data-part='content'][data-state='closed'] {
    animation: xh-pop-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  [data-scope='tour'][data-part='title'] {
    margin: 0;
    font-size: var(--xh-tour-title-font-size, var(--xh-text-heading-3-size));
    font-weight: var(--xh-tour-title-font-weight, var(--xh-text-heading-3-weight));
    color: var(--xh-tour-title-fg, var(--xh-fg-default));
  }

  /* 关闭按钮是绝对定位的，不占流内宽度：标题得自己让出右上角那块，
     否则长标题会直接钻到按钮底下。只在真有关闭按钮时让位。 */
  [data-scope='tour'][data-part='content']:has([data-scope='tour'][data-part='close-trigger'])
    [data-scope='tour'][data-part='title'] {
    padding-inline-end: calc(var(--xh-tour-close-size, var(--xh-control-h-sm)) + var(--xh-surface-action-inset));
  }

  /* 说明文字走说明档：13px + fg-muted */
  [data-scope='tour'][data-part='description'] {
    margin: 0;
    font-size: var(--xh-text-secondary-size);
    line-height: var(--xh-leading-normal);
    color: var(--xh-tour-description-fg, var(--xh-fg-muted));
  }

  /* "第 m 步，共 n 步"：辅助信息，字号压一档，与按钮排在同一行的两端 */
  [data-scope='tour'][data-part='progress-text'] {
    font-size: var(--xh-tour-progress-font-size, var(--xh-text-caption-size));
    color: var(--xh-tour-progress-fg, var(--xh-fg-subtle));
  }

  /* 圆点组：一步一颗，横排 */
  [data-scope='tour'][data-part='progress-indicator'] {
    display: inline-flex;
    align-items: center;
    gap: var(--xh-tour-progress-indicator-gap, var(--xh-space-1));
  }

  [data-scope='tour'][data-part='progress-indicator'][hidden] {
    display: none;
  }

  /* 圆点：8px 正圆取 circle（分页点统一款），未走到的一档取中性描边色。
     宽度与底色都随状态换，换步那一下能看出进度在推进 */
  [data-scope='tour'][data-part='progress-dot'] {
    inline-size: var(--xh-space-2);
    block-size: var(--xh-space-2);
    border-radius: var(--xh-shape-circle);
    background: var(--xh-tour-progress-dot-bg, var(--xh-border-default));
    transition:
      inline-size var(--xh-motion-duration-nudge) var(--xh-motion-ease-continuous),
      background-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 走过的步：中性色加重一档 */
  [data-scope='tour'][data-part='progress-dot'][data-complete] {
    background: var(--xh-tour-progress-dot-bg-complete, var(--xh-border-strong));
  }

  /* 当前步：拉成 20px 胶囊并换品牌色；一维对象取 pill */
  [data-scope='tour'][data-part='progress-dot'][data-current] {
    inline-size: var(--xh-space-5);
    border-radius: var(--xh-shape-pill);
    background: var(--xh-tour-progress-dot-bg-current, var(--xh-bg-brand));
  }

  /*
   * —— 末行三颗按钮 ——
   * 上一步 / 下一步 / 跳过都是气泡末行的文字按钮：盒型、sm 档几何、四态面、0.97 按压并换底、粗指针命中区与
   * 强制色由家族配方按连接层投影的 data-xh-action-variant / -size 给出。这里只把公开槽桥接到矩阵之前
   * （使用者槽 → 形态矩阵 → 家族缺省）与几何映射；内衬与圆角槽三颗共用。
   */
  [data-scope='tour'][data-part='prev-trigger'],
  [data-scope='tour'][data-part='next-trigger'],
  [data-scope='tour'][data-part='skip-trigger'] {
    --xh-action-padding-inline: var(--xh-tour-skip-trigger-px, var(--xh-_action-profile-padding-inline));
    --xh-action-radius: var(--xh-tour-action-radius, var(--xh-shape-control));
    /* 作者塞进按钮的图标随档取字形尺（sm = 16px） */
    --xh-icon-size: var(--xh-tour-icon-size, var(--xh-_action-profile-glyph-size));
  }

  [data-scope='tour'][data-part='prev-trigger'][hidden],
  [data-scope='tour'][data-part='next-trigger'][hidden],
  [data-scope='tour'][data-part='skip-trigger'][hidden] {
    display: none;
  }

  /* 下一步是整条引导的主线动作，显式 solid：底、字与影三组使用者槽桥到配方 solid 列之前 */
  [data-scope='tour'][data-part='next-trigger'] {
    --xh-action-bg-rest: var(--xh-tour-next-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-tour-next-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-focus-visible: var(--xh-tour-next-bg, var(--xh-_action-variant-bg-focus-visible));
    --xh-action-fg-rest: var(--xh-tour-next-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-tour-next-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-tour-next-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-fg-focus-visible: var(--xh-tour-next-fg, var(--xh-_action-variant-fg-focus-visible));
    --xh-action-shadow-rest: var(--xh-tour-next-shadow, none);
  }

  /* 面是实心的，环色与面同族，画在面里就看不出来；环改取面自己的前景色——
     那一族色本来就要在这块面上把字读清楚，与面的对比是按可读性定的 */
  [data-scope='tour'][data-part='next-trigger'][data-xh-action-variant='solid']:focus-visible {
    --xh-action-ring-color-focus-visible: currentColor;
  }

  /*
   * 关闭钮是气泡角落的单图标钮：正方盒、sm 档几何、ghost 四态面、0.97 按压并换底与粗指针命中区
   * 由家族配方给出——白面上走画布承载阶梯悬停 --xh-bg-subtle（100）→ 按下 --xh-bg-subtle-hover（200），
   * 焦点面透明吃库环。这里只把公开槽桥接到矩阵之前（使用者槽 → 形态矩阵 → 家族缺省）与摆放；
   * 静息前景取 muted 字色，悬停 / 按下 / 聚焦回到 fg-default。
   */
  [data-scope='tour'][data-part='close-trigger'] {
    --xh-action-visual-size: var(--xh-tour-close-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-tour-close-radius, var(--xh-shape-control));
    --xh-action-bg-hover: var(--xh-tour-close-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-tour-close-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-tour-close-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-tour-close-fg-hover, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-tour-close-fg-hover, var(--xh-_action-variant-fg-pressed));
    --xh-action-fg-focus-visible: var(--xh-tour-close-fg-hover, var(--xh-_action-variant-fg-focus-visible));
    /* 作者塞进按钮的图标随档取字形尺（sm = 16px），与皮肤画的兜底字形同一把尺 */
    --xh-icon-size: var(--xh-tour-icon-size, var(--xh-_action-profile-glyph-size));

    position: absolute;
    inset-block-start: var(--xh-surface-action-inset);
    inset-inline-end: var(--xh-surface-action-inset);
  }

  [data-scope='tour'][data-part='close-trigger'][hidden] {
    display: none;
  }

  /* 箭头的底色与描边色，几何在 overlay-arrow.css。
     交叉轴落点由定位引擎经内联自定义属性写进来，没给时退回居中 */
  [data-scope='tour'][data-part='arrow'] {
    --xh-_tour-arrow-x: 50%;
    --xh-_tour-arrow-y: 50%;
    --xh-_overlay-arrow-size: var(--xh-tour-arrow-size, var(--xh-overlay-arrow-size));
    --xh-_overlay-arrow-x: var(--xh-_tour-arrow-x);
    --xh-_overlay-arrow-y: var(--xh-_tour-arrow-y);

    background: var(--xh-tour-bg, var(--xh-material-elevated-bg));
    border: var(--xh-stroke-thin) solid var(--xh-tour-border, var(--xh-material-elevated-border));
  }

  /* 居中步没有锚点，连接层会给箭头发 hidden */
  [data-scope='tour'][data-part='arrow'][hidden] {
    display: none;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中 */
  [data-scope='tour'][data-part='close-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }
}

@layer xihan.components {
  /* 气泡限高之后只让正文让步：标题与上下步按钮滚出视线就点不到了。
     模态气泡里的原生细条滚动面：细条由 reset 层统一给，滚到头不把页面一起带走；内容高度不动态变化，不写 gutter */
  [data-scope='tour'][data-part='description'] {
    flex: 1 1 auto;
    min-block-size: 0;
    overflow-y: auto;
    overscroll-behavior: contain;
  }

  @media (forced-colors: active) {
    /* 这一档丢掉底色：走过的那几颗改由一圈描边表出，当前那颗仍靠宽度分辨 */
    [data-scope='tour'][data-part='progress-dot'][data-complete] {
      outline: var(--xh-stroke-thin) solid CanvasText;
    }
  }

  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。
       居中那一档的选择器多带一个属性、权重高一级，所以把它一并列出来，靠同权重下的书写顺序压回去。 */
    [data-scope='tour'][data-part='backdrop'],
    [data-scope='tour'][data-part='positioner'],
    [data-scope='tour'][data-part='positioner'][data-position='center'] {
      display: none;
    }
  }
}
/* 排在六份浮层皮肤之后：箭头几何里摘边框那几条要压过它们的 border 简写 */

/* styles/overlay-arrow.css */
/*
 * 浮层箭头的几何，八类浮层共用一份，只匹配这些组件自身的 arrow 部件。
 *
 * 箭头是正方形转 45°，构成尖角的是哪两条物理边，所以贴边与摘边框都写物理属性。
 * 行内轴上的中心点仍写逻辑属性：定位引擎在 RTL 下已把 arrow-x 镜像成逻辑量。
 *
 * 底色与描边色留在各组件皮肤，它们同时把自己的内联落点槽接到这里的统一名字上。
 * 引入顺序排在消费方皮肤之后；作用域使用 :where，维持原有特异性和摘边优先级。
 */
@layer xihan.components {
  :where([data-scope='context-menu'], [data-scope='hover-card'], [data-scope='menu'], [data-scope='menubar'], [data-scope='popconfirm'], [data-scope='popover'], [data-scope='tour'], [data-scope='tooltip'])[data-part='arrow'] {
    position: absolute;
    inline-size: var(--xh-_overlay-arrow-size);
    block-size: var(--xh-_overlay-arrow-size);
    rotate: 45deg;
  }

  /* 浮层落在锚点下方：箭头贴 content 上缘，摘掉埋进 content 的下、右两条边 */
  :where([data-scope='context-menu'], [data-scope='hover-card'], [data-scope='menu'], [data-scope='menubar'], [data-scope='popconfirm'], [data-scope='popover'], [data-scope='tour'], [data-scope='tooltip'])[data-part='arrow'][data-placement^='bottom'] {
    top: calc(var(--xh-_overlay-arrow-size) / -2);
    inset-inline-start: calc(var(--xh-_overlay-arrow-x) - var(--xh-_overlay-arrow-size) / 2);
    border-right: 0;
    border-bottom: 0;
  }

  /* 浮层落在锚点上方：箭头贴 content 下缘，摘掉上、左两条边 */
  :where([data-scope='context-menu'], [data-scope='hover-card'], [data-scope='menu'], [data-scope='menubar'], [data-scope='popconfirm'], [data-scope='popover'], [data-scope='tour'], [data-scope='tooltip'])[data-part='arrow'][data-placement^='top'] {
    bottom: calc(var(--xh-_overlay-arrow-size) / -2);
    inset-inline-start: calc(var(--xh-_overlay-arrow-x) - var(--xh-_overlay-arrow-size) / 2);
    border-top: 0;
    border-left: 0;
  }

  /* 浮层落在锚点右侧：箭头贴 content 左缘，摘掉上、右两条边 */
  :where([data-scope='context-menu'], [data-scope='hover-card'], [data-scope='menu'], [data-scope='menubar'], [data-scope='popconfirm'], [data-scope='popover'], [data-scope='tour'], [data-scope='tooltip'])[data-part='arrow'][data-placement^='right'] {
    top: calc(var(--xh-_overlay-arrow-y) - var(--xh-_overlay-arrow-size) / 2);
    /* stylelint-disable-next-line property-disallowed-list -- 旋转是物理的，贴边跟着物理走 */
    left: calc(var(--xh-_overlay-arrow-size) / -2);
    border-top: 0;
    border-right: 0;
  }

  /* 浮层落在锚点左侧：箭头贴 content 右缘，摘掉下、左两条边 */
  :where([data-scope='context-menu'], [data-scope='hover-card'], [data-scope='menu'], [data-scope='menubar'], [data-scope='popconfirm'], [data-scope='popover'], [data-scope='tour'], [data-scope='tooltip'])[data-part='arrow'][data-placement^='left'] {
    top: calc(var(--xh-_overlay-arrow-y) - var(--xh-_overlay-arrow-size) / 2);
    /* stylelint-disable-next-line property-disallowed-list -- 旋转是物理的，贴边跟着物理走 */
    right: calc(var(--xh-_overlay-arrow-size) / -2);
    border-bottom: 0;
    border-left: 0;
  }
}

/* styles/transfer.css */
/* 定义 transfer 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='transfer'] {
    --xh-transfer-skin: 1;
  }

  /* 三栏栅格：宽档两侧面板各占一栏、跨两行，中间那栏上下各放一个搬运按钮；
     窄档四个节点改按行叠放，中栏被两个按钮各跨一半、宽度收成零，两钮因此仍在中线相遇。
     两档共用这一份轨道声明，换档靠四个子节点各自换安放。
     栅格的列号本身就是随书写方向走的（第 1 栏永远在行首侧），dir=rtl 时整块自动镜像。
     中间那栏没有对应的角色节点（anatomy 里两个按钮是 root 的直接子节点），
     所以只能按位置显式安放，不能靠自动流——自动流会把"往回搬"甩到目标面板的位置上 */
  [data-scope='transfer'][data-part='root'] {
    /* 条目外的字形（空态占位里作者塞的图标）按档取尺，缺省 md；条目内的字形由家族随 data-xh-collection-size
       下发，搬运钮内的按 Action Control icon 档取，勾选格里的勾按边长比例取 */
    --xh-icon-size: var(--xh-transfer-icon-size, var(--xh-glyph-size-md));
    /* 两侧定高小列表的自绘条挂在根上：根是条子的定位盒（面板不定位），轨道底色关掉才不会在列表边缘糊出一条灰带 */
    --xh-scrollbar-track-bg: transparent;

    /* 尺寸档只换这五个私有槽，面板头、搜索框、条目与勾选格都从 root 继承它们，
       换档不必给每个部件各写一条选择器 */
    --xh-_transfer-item-py: var(--xh-list-option-py-md);
    --xh-_transfer-px: var(--xh-control-px-md);
    --xh-_transfer-gap: var(--xh-control-gap-md);
    --xh-_transfer-font-size: var(--xh-control-font-md);
    --xh-_transfer-box: var(--xh-control-indicator-md);

    /* 勾选格的填色随语气走；没写 data-tone 时退回品牌色 */
    --xh-_transfer-accent: var(--xh-_tone, var(--xh-bg-brand));
    --xh-_transfer-on-accent: var(--xh-_tone-on, var(--xh-fg-on-brand));

    position: relative;
    display: grid;
    grid-template-rows: auto auto;
    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
    gap: var(--xh-transfer-gap, var(--xh-space-3));
    align-items: center;
    color: var(--xh-transfer-fg, var(--xh-fg-default));
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里 */
  [data-scope='transfer'][data-part='root'][data-size='sm'] {
    --xh-icon-size: var(--xh-transfer-icon-size, var(--xh-glyph-size-sm));
    --xh-_transfer-item-py: var(--xh-list-option-py-sm);
    --xh-_transfer-px: var(--xh-control-px-sm);
    --xh-_transfer-gap: var(--xh-control-gap-sm);
    --xh-_transfer-font-size: var(--xh-control-font-sm);
    --xh-_transfer-box: var(--xh-control-indicator-sm);
  }

  [data-scope='transfer'][data-part='root'][data-size='lg'] {
    --xh-icon-size: var(--xh-transfer-icon-size, var(--xh-glyph-size-lg));
    --xh-_transfer-item-py: var(--xh-list-option-py-lg);
    --xh-_transfer-px: var(--xh-control-px-lg);
    --xh-_transfer-gap: var(--xh-control-gap-lg);
    --xh-_transfer-font-size: var(--xh-control-font-lg);
    --xh-_transfer-box: var(--xh-control-indicator-lg);
  }

  /* 校验失败：两侧面板换成错误描边，与其余表单控件同一套表达 */
  [data-scope='transfer'][data-part='root'][data-invalid]
    :is([data-scope='transfer'][data-part='source-panel'], [data-scope='transfer'][data-part='target-panel']) {
    border-color: var(--xh-transfer-panel-border-invalid, var(--xh-border-invalid));
  }

  /* 只读勾不动也搬不动，但不是禁用：颜色照常，只把"可点"这个暗示收回来。
     排掉禁用项是因为这条选择器权重高过条目那条，不排就会把禁用的手势指示覆盖回 default */
  [data-scope='transfer'][data-part='root'][data-readonly]
    [data-scope='transfer'][data-part='item']:not([data-disabled]) {
    cursor: default;
  }

  /* 窄档：源面板在上、目标面板在下，各自跨满三栏 */
  [data-scope='transfer'][data-part='source-panel'] {
    grid-row: 1;
    grid-column: 1 / 4;
  }

  [data-scope='transfer'][data-part='target-panel'] {
    grid-row: 3;
    grid-column: 1 / 4;
  }

  /* 两钮同占中间一行，各跨到中栏为止，一个贴行尾侧、一个贴行首侧，
     因此夹着中线成对出现，而不是各自漂在半行中央 */
  [data-scope='transfer'][data-part='to-target-trigger'] {
    grid-row: 2;
    grid-column: 1 / 3;
    justify-self: end;
  }

  [data-scope='transfer'][data-part='to-source-trigger'] {
    grid-row: 2;
    grid-column: 2 / 4;
    justify-self: start;
  }

  [data-scope='transfer'][data-part='source-panel'],
  [data-scope='transfer'][data-part='target-panel'] {
    display: flex;
    flex-direction: column;
    block-size: 100%;
    min-inline-size: 0;
    border: var(--xh-stroke-thin) solid var(--xh-transfer-panel-border, var(--xh-border-default));
    border-radius: var(--xh-transfer-panel-radius, var(--xh-shape-surface));
    background: var(--xh-transfer-panel-bg, var(--xh-bg-surface));
    overflow: hidden;
  }

  /* 整体禁用只写在 root 与各角色节点上；面板自己也带 data-disabled，观感一处收口 */
  [data-scope='transfer'][data-part='source-panel'][data-disabled],
  [data-scope='transfer'][data-part='target-panel'][data-disabled] {
    background: var(--xh-transfer-panel-bg-disabled, var(--xh-bg-muted));
  }

  /* 面板内三个角色的槽都带 panel- 段，与部件名逐字对上 */
  [data-scope='transfer'][data-part='panel-header'] {
    display: flex;
    gap: var(--xh-transfer-panel-header-gap, var(--xh-_transfer-gap));
    align-items: center;
    padding-block: var(--xh-transfer-panel-header-py, var(--xh-space-2));
    padding-inline: var(--xh-transfer-panel-header-px, var(--xh-_transfer-px));
    border-block-end: var(--xh-stroke-thin) solid var(--xh-transfer-panel-border, var(--xh-border-default));
  }

  /* 标题占满剩余宽度，把计数挤到行尾侧 */
  [data-scope='transfer'][data-part='panel-title'] {
    flex: 1;
    min-inline-size: 0;
    overflow: hidden;
    color: var(--xh-transfer-panel-title-fg, var(--xh-fg-default));
    /* 面板标头是 Surface 内的标题：14 / 600 */
    font-size: var(--xh-transfer-panel-title-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-transfer-panel-title-font-weight, var(--xh-font-weight-semibold));
    line-height: var(--xh-leading-none);
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  [data-scope='transfer'][data-part='panel-count'] {
    flex: none;
    color: var(--xh-transfer-panel-count-fg, var(--xh-fg-subtle));
    font-size: var(--xh-transfer-panel-count-font-size, var(--xh-text-caption-size));
    line-height: var(--xh-leading-none);
    font-variant-numeric: tabular-nums;
  }

  /* 连接层只给数字（data-checked-count / data-count），文案是作者的事：
     语言、量词、单复数都由他定。作者什么都不写时这里补出"勾中/可见"，
     写了内容就用作者的（:empty 只命中空节点） */
  [data-scope='transfer'][data-part='panel-count']:empty::after {
    content: attr(data-checked-count) ' / ' attr(data-count);
  }

  [data-scope='transfer'][data-part='search'] {
    display: block;
    inline-size: 100%;
    block-size: var(--xh-transfer-search-h, var(--xh-control-h-sm));
    padding-inline: var(--xh-transfer-search-px, var(--xh-_transfer-px));
    border: 0;
    border-block-end: var(--xh-stroke-thin) solid var(--xh-transfer-search-border, var(--xh-border-control));
    background: var(--xh-transfer-search-bg, transparent);
    color: var(--xh-transfer-search-fg, var(--xh-fg-default));
    font: inherit;
    font-size: var(--xh-transfer-search-font-size, var(--xh-_transfer-font-size));
  }

  /* 单体控件的禁用是原生 disabled，样式只能写 :disabled；集合条目才读 data-disabled */
  [data-scope='transfer'][data-part='search']:disabled {
    color: var(--xh-fg-disabled);
  }

  /* 两侧列表定高：高度只由这个槽给，与条目数无关。左右两块因此恒等高，
     搬走条目、搜索筛掉条目、整侧搬空，面板都停在原地不缩。
     flex-basis 取 auto 而不是 0，块尺寸才是这一栏真正的主轴基准 */
  [data-scope='transfer'][data-part='list'] {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    gap: var(--xh-transfer-list-gap, var(--xh-list-option-gap));
    block-size: var(--xh-transfer-list-h, var(--xh-viewport-h-md));
    padding-block: var(--xh-transfer-list-py, var(--xh-space-1));
    padding-inline: var(--xh-transfer-list-px, var(--xh-space-1));
    overflow: auto;
  }

  /* 焦点在列表外时容器自己进 Tab 序列兜底，落焦不画环：高亮永远长在条目上 */
  [data-scope='transfer'][data-part='list']:focus-visible {
    outline: none;
  }

  /* 空态占位：待在面板里、list 的兄弟（列表框只许拥有 option 与 group）。
     盒归面板，这里只画一句居中的次要文字 */
  [data-scope='transfer'][data-part='empty'] {
    display: block;
    flex: none;
    padding-block: var(--xh-transfer-empty-py, var(--xh-space-3));
    padding-inline: var(--xh-transfer-empty-px, var(--xh-_transfer-px));
    color: var(--xh-transfer-empty-fg, var(--xh-fg-subtle));
    font-size: var(--xh-transfer-empty-font-size, var(--xh-_transfer-font-size));
    line-height: var(--xh-leading-none);
    text-align: center;
  }

  /* 上面给了 display，UA 的 [hidden]{display:none} 已被盖掉，这里补回来 */
  [data-scope='transfer'][data-part='empty'][hidden] {
    display: none;
  }

  [data-scope='transfer'][data-part='empty'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 在途占位：与空态占位同一个位置、同一副观感，两者不同屏 */
  [data-scope='transfer'][data-part='loading'] {
    display: block;
    flex: none;
    padding-block: var(--xh-transfer-loading-py, var(--xh-space-3));
    padding-inline: var(--xh-transfer-loading-px, var(--xh-_transfer-px));
    color: var(--xh-transfer-loading-fg, var(--xh-fg-subtle));
    font-size: var(--xh-transfer-loading-font-size, var(--xh-_transfer-font-size));
    line-height: var(--xh-leading-none);
    text-align: center;
  }

  [data-scope='transfer'][data-part='loading'][hidden] {
    display: none;
  }

  [data-scope='transfer'][data-part='loading'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  [data-scope='transfer'][data-part='group'] {
    display: flex;
    flex: none;
    flex-direction: column;
    gap: var(--xh-transfer-group-gap, var(--xh-list-option-gap));
  }

  [data-scope='transfer'][data-part='group'][hidden] {
    display: none;
  }

  /* 组内条目搬到对面、或被搜索筛掉时都只是打 hidden，一条不剩的分组连标题一起撤下，
     免得列表里留着一排够不着的标题 */
  [data-scope='transfer'][data-part='group']:not(:has([data-part='item']:not([hidden]))) {
    display: none;
  }

  /* 组间留白只加在后继分组上：首组顶上已经有 list 的内边距，再加一层会显得头重 */
  [data-scope='transfer'][data-part='group'] + [data-scope='transfer'][data-part='group'] {
    margin-block-start: var(--xh-transfer-group-spacing, var(--xh-space-1_5));
  }

  /* 分组标题不是选项、进不了导航，画成小号次要文字，
     内缩与条目对齐（同一个 padding-inline），标题与条目文字才在一条竖线上 */
  [data-scope='transfer'][data-part='group-label'] {
    display: block;
    padding-block: var(--xh-transfer-group-label-py, var(--xh-space-1));
    padding-inline: var(--xh-transfer-group-label-px, var(--xh-_transfer-px));
    color: var(--xh-transfer-group-label-fg, var(--xh-fg-subtle));
    font-size: var(--xh-transfer-group-label-font-size, var(--xh-text-caption-size));
    font-weight: var(--xh-transfer-group-label-font-weight, var(--xh-font-weight-medium));
    line-height: var(--xh-leading-none);
    user-select: none;
  }

  [data-scope='transfer'][data-part='group-label'][hidden] {
    display: none;
  }

  [data-scope='transfer'][data-part='group-label'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 条目走 Collection Item 的 page 语境（页内持久集合）：悬停 / 高亮 / 按下面（白底承载 hover 100 →
     pressed 200）与勾选行的选中面（品牌淡底 + 淡底前景，selected+hover 20% / +pressed 28%）都由家族按
     aria-selected / aria-disabled 给出，标记由行首的勾选方框承担；禁用面（字色降级、not-allowed、不换面）
     也归家族。这里只把公开槽映射到桥接槽。
     布局保持 flex 而不用家族网格：间距统一由行的 gap 给，家族按槽下发的外边距（--xh-collection-gap）归零 */
  [data-scope='transfer'][data-part='item'] {
    --xh-collection-block-padding: var(--xh-transfer-item-py, var(--xh-_transfer-item-py));
    --xh-collection-inline-padding: var(--xh-transfer-item-px, var(--xh-_transfer-px));
    --xh-collection-gap: 0;
    --xh-collection-font-size: var(--xh-transfer-item-font-size, var(--xh-_transfer-font-size));
    --xh-collection-radius: var(--xh-transfer-item-radius, var(--xh-shape-control));
    /* 作者的图标尺槽经桥接槽下发到条目，家族缺省按 data-xh-collection-size 取档 */
    --xh-collection-glyph-size: var(--xh-transfer-icon-size, var(--xh-_collection-glyph-size));
    --xh-collection-fg-rest: var(--xh-transfer-item-fg, var(--xh-fg-default));
    --xh-collection-fg-hover: var(--xh-transfer-item-fg, var(--xh-fg-default));
    --xh-collection-fg-keyboard-highlight: var(--xh-transfer-item-fg, var(--xh-fg-default));
    --xh-collection-fg-pressed: var(--xh-transfer-item-fg, var(--xh-fg-default));
    --xh-collection-fg-selected: var(--xh-transfer-item-fg-selected, var(--xh-fg-on-brand-subtle));
    --xh-collection-fg-selected-hover: var(--xh-transfer-item-fg-selected, var(--xh-fg-on-brand-subtle));
    --xh-collection-fg-selected-highlight: var(--xh-transfer-item-fg-selected, var(--xh-fg-on-brand-subtle));
    --xh-collection-fg-selected-pressed: var(--xh-transfer-item-fg-selected, var(--xh-fg-on-brand-subtle));
    --xh-collection-bg-hover: var(--xh-transfer-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-keyboard-highlight: var(--xh-transfer-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-pressed: var(--xh-transfer-item-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-bg-selected: var(--xh-transfer-item-bg-selected, var(--xh-bg-brand-subtle));
    /* data-highlighted 跟的是连接层记的焦点条目（指针点选也会落焦）：只换面，焦点环在 :focus-visible 下再接回 */
    --xh-collection-outline-keyboard-highlight: transparent;
    --xh-collection-outline-selected-highlight: transparent;

    display: flex;
    flex: none;
    gap: var(--xh-transfer-item-gap, var(--xh-_transfer-gap));
    align-items: center;
    /* 行高留出文字的上下伸展空间，行内那层 overflow:hidden 才不会把字削掉 */
    line-height: var(--xh-transfer-item-leading, var(--xh-leading-normal));
    white-space: nowrap;
    user-select: none;
  }

  /* 键盘焦点出现时环才接回并立即到位，不压在背景过渡的中间帧上 */
  [data-scope='transfer'][data-part='item']:focus-visible:not(:hover) {
    --xh-collection-outline-keyboard-highlight: var(--xh-ring-focus);
    --xh-collection-outline-selected-highlight: var(--xh-ring-focus);

    transition: none;
  }

  [data-scope='transfer'][data-part='item-text'] {
    flex: 1;
    min-inline-size: 0;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  /* 条目的勾选格与全选格共用同一套盒子，并成一条规则写：分开写迟早只改到一半，
     两个方框就此走形。全选格没有对应的角色节点（它自己就是按钮），由伪元素补出来 */
  [data-scope='transfer'][data-part='item-checkbox'],
  [data-scope='transfer'][data-part='select-all-trigger']::before {
    /* 方框里的勾按边长的比例取尺（与 Checkbox 同一比例），不吃家族按档下发的行内字形尺 */
    --xh-icon-size: calc(var(--xh-transfer-checkbox-size, var(--xh-_transfer-box)) * 0.75);

    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-transfer-checkbox-size, var(--xh-_transfer-box));
    block-size: var(--xh-transfer-checkbox-size, var(--xh-_transfer-box));
    border: var(--xh-stroke-thin) solid var(--xh-transfer-checkbox-border, var(--xh-border-control));
    border-radius: var(--xh-transfer-checkbox-radius, var(--xh-shape-inset));
    background: var(--xh-transfer-checkbox-bg, transparent);
    color: var(--xh-transfer-checkbox-fg, var(--xh-_transfer-on-accent));
    font-size: var(--xh-transfer-checkbox-font-size, calc(var(--xh-_transfer-box) * 0.75));
    line-height: var(--xh-leading-none);
    transition:
      background var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      border-color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* content 只能给伪元素，绝不能并进上面那条：content 落在普通元素上会顶掉它的全部子节点，
     item-checkbox 里作者写的图标就此消失 */
  [data-scope='transfer'][data-part='select-all-trigger']::before {
    content: '';
  }

  /* 勾中即填色。全选格三态里 all 与 some 都算"有值"，与条目共用同一副填色 */
  [data-scope='transfer'][data-part='item-checkbox'][data-state='checked'],
  [data-scope='transfer'][data-part='select-all-trigger']:is([data-state='checked'], [data-state='indeterminate'])::before {
    border-color: var(--xh-transfer-checkbox-border-checked, var(--xh-_transfer-accent));
    background: var(--xh-transfer-checkbox-bg-checked, var(--xh-_transfer-accent));
  }

  /* 面是实心的，环色与面同族，画在面里就看不出来；环改取面自己的前景色——
     那一族色本来就要在这块面上把字读清楚，与面的对比是按可读性定的 */
  [data-scope='transfer'][data-part='item-checkbox'][data-state='checked']:focus-visible {
    --xh-_ring-color: currentColor;
  }

  /* 没写内容就由皮肤画勾；作者往格子里塞了自己的图形，这条规则即不命中。
     底下两处（全选格的两态）不带这条守卫：触发器里装的是全选那行文字，:empty 恒不命中 */
  [data-scope='transfer'][data-part='item-checkbox'][data-state='checked']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    mask: var(--xh-glyph-mark-check) center / contain no-repeat;
  }

  /* 全选格的三态：all 打勾、some 打横杠、none 留空。
     some 就是读屏听到的 aria-checked=mixed，两者同源，样式只认 data-state。

     字形走 ::after 而不是画方框的那颗 ::before：mask 会把所在元素的描边与底色一并裁成
     字形的轮廓，写在 ::before 上就等于把方框本身裁没了，只剩一枚白勾。条目那一侧是
     真实节点当方框、它的 ::before 当字形的两层结构，这里没有第二个节点，只能用
     第二个伪元素补上那一层。
     方框是行首那颗 ::before、宽度即勾选格尺寸，所以字形按「盒与字形的宽度差之半」
     内推即落在圆心；纵向靠 inset-block: 0 + margin-block: auto 居中。
     font-size 与 ::before 同值，--xh-icon-size 的 1em 兜底才和条目那侧量得一样大 */
  [data-scope='transfer'][data-part='select-all-trigger'][data-state='checked']::after {
    content: '';
    position: absolute;
    inset-block: 0;
    inset-inline-start: 0;
    margin-block: auto;
    margin-inline-start: calc(
      (var(--xh-transfer-checkbox-size, var(--xh-_transfer-box)) - var(--xh-icon-size, var(--xh-glyph-size-text))) /
        2
    );
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    background-color: var(--xh-transfer-checkbox-fg, var(--xh-_transfer-on-accent));
    font-size: var(--xh-transfer-checkbox-font-size, calc(var(--xh-_transfer-box) * 0.75));
    -webkit-mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    mask: var(--xh-glyph-mark-check) center / contain no-repeat;
  }

  [data-scope='transfer'][data-part='select-all-trigger'][data-state='indeterminate']::after {
    content: '';
    position: absolute;
    inset-block: 0;
    inset-inline-start: 0;
    margin-block: auto;
    margin-inline-start: calc(
      (var(--xh-transfer-checkbox-size, var(--xh-_transfer-box)) - var(--xh-icon-size, var(--xh-glyph-size-text))) /
        2
    );
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    background-color: var(--xh-transfer-checkbox-fg, var(--xh-_transfer-on-accent));
    font-size: var(--xh-transfer-checkbox-font-size, calc(var(--xh-_transfer-box) * 0.75));
    -webkit-mask: var(--xh-glyph-mark-minus) center / contain no-repeat;
    mask: var(--xh-glyph-mark-minus) center / contain no-repeat;
  }

  [data-scope='transfer'][data-part='item-checkbox'][data-disabled] {
    border-color: var(--xh-transfer-checkbox-border-disabled, var(--xh-border-default));
    background: var(--xh-transfer-checkbox-bg-disabled, var(--xh-bg-muted));
  }

  /* 全选格是原生按钮（三态经 aria-checked 上报，激活由平台负责），禁用同时打原生 disabled 与 data-disabled。
     它是「方框 + 文案」的整行命中区：接 Action Control text 档、ghost 形态，悬停 / 按下 / 禁用面与过渡由家族给
     （白底承载 hover 100 → pressed 200），按下只换面不缩放（--xh-action-scale-pressed: none），勾选回执落在方框上；
     盒随内容收宽、高度取 xs 档的 24px 命中地板（方框 16px 居中其间），text 档的内距与最小宽度归零。
     position 是给叠在方框上的那颗字形 ::after 当定位基准 */
  [data-scope='transfer'][data-part='select-all-trigger'] {
    /* 叠在方框上的那颗字形 ::after 与方框里的勾同一把尺 */
    --xh-icon-size: calc(var(--xh-transfer-checkbox-size, var(--xh-_transfer-box)) * 0.75);

    --xh-action-min-inline-size: 0;
    --xh-action-padding-inline: 0;
    --xh-action-gap: var(--xh-transfer-select-all-gap, var(--xh-control-gap-sm));
    /* 全选格是嵌在面板头里的勾选小块：inset 档圆角（身份表登记） */
    --xh-action-radius: var(--xh-transfer-select-all-radius, var(--xh-shape-inset));
    --xh-action-bg-hover: var(--xh-transfer-select-all-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-transfer-select-all-bg-pressed, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-transfer-select-all-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-transfer-select-all-fg, var(--xh-fg-muted));
    --xh-action-fg-pressed: var(--xh-transfer-select-all-fg, var(--xh-fg-muted));
    --xh-action-fg-focus-visible: var(--xh-transfer-select-all-fg, var(--xh-fg-muted));
    --xh-action-font-size: var(--xh-transfer-select-all-font-size, var(--xh-text-caption-size));
    --xh-action-scale-pressed: none;

    flex: none;
    justify-content: start;
    padding: 0;
    font-weight: var(--xh-font-weight-medium);
  }

  /* 家族 text 档在粗指针下用 ::after 扩热区，勾中 / 半选时这里的 ::after 是叠在方框上的字形：钉回原位、下限归零 */
  @media (pointer: coarse) {
    [data-scope='transfer'][data-part='select-all-trigger']:is([data-state='checked'], [data-state='indeterminate'])::after {
      min-block-size: 0;
      translate: none;
    }
  }

  /* 两颗搬运钮是只有字形的离散动作钮：接 Action Control 的 icon 档、outline 形态（中性描边、透明底，
     白底承载 hover 100 → pressed 200，按下 0.97 并同时换底），盒、焦点环、粗指针热区与禁用面由家族给；
     此前的 raised 悬停抬升退役（边界只由描边承担）。这里只把使用者槽映射到桥接槽；
     钮是正方盒，按 sm 档取一个控件高 */
  [data-scope='transfer'][data-part='to-target-trigger'],
  [data-scope='transfer'][data-part='to-source-trigger'] {
    --xh-action-visual-size: var(--xh-transfer-trigger-size, var(--xh-_action-profile-visual-size));
    --xh-action-min-inline-size: var(--xh-transfer-trigger-size, var(--xh-_action-profile-visual-size));
    --xh-action-padding-inline: var(--xh-transfer-trigger-px, var(--xh-_action-profile-padding-inline));
    --xh-action-radius: var(--xh-transfer-trigger-radius, var(--xh-shape-control));
    --xh-action-border-rest: var(--xh-transfer-trigger-border, var(--xh-_action-variant-border-rest));
    --xh-action-border-hover: var(--xh-transfer-trigger-border, var(--xh-_action-variant-border-hover));
    --xh-action-border-pressed: var(--xh-transfer-trigger-border, var(--xh-_action-variant-border-pressed));
    --xh-action-bg-rest: var(--xh-transfer-trigger-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-transfer-trigger-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-transfer-trigger-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-transfer-trigger-fg, var(--xh-_action-variant-fg-rest));
    --xh-action-fg-hover: var(--xh-transfer-trigger-fg, var(--xh-_action-variant-fg-hover));
    --xh-action-fg-pressed: var(--xh-transfer-trigger-fg, var(--xh-_action-variant-fg-pressed));
    --xh-action-shadow-hover: var(--xh-transfer-trigger-shadow-hover, none);
    --xh-action-shadow-pressed: var(--xh-transfer-trigger-shadow-active, none);
    --xh-action-font-size: var(--xh-transfer-trigger-font-size, var(--xh-text-label-size));
    /* 作者塞进钮里的图标与皮肤画的兜底箭头同一把尺：按 icon 档取字形尺寸。
       配方尚未把 profile 字形档灌进 --xh-icon-size，钮内字形先按 icon 档逐钮取值 */
    --xh-icon-size: var(--xh-transfer-icon-size, var(--xh-_action-profile-glyph-size));
  }

  /* 上面凡是给了 display 的角色节点都要补这条：display 声明会盖掉 UA 的 [hidden]{display:none}，
     不补的话收起态整个失效。连接层真正会写 hidden 的是 search（searchable 关掉时）、
     item（不属于本侧、或被搜索筛掉）、item-checkbox（oneWay 下的右侧），
     其余几个是作者自己收起时的兜底 */
  [data-scope='transfer'][data-part='root'][hidden],
  [data-scope='transfer'][data-part='source-panel'][hidden],
  [data-scope='transfer'][data-part='target-panel'][hidden],
  [data-scope='transfer'][data-part='panel-header'][hidden],
  [data-scope='transfer'][data-part='search'][hidden],
  [data-scope='transfer'][data-part='list'][hidden],
  [data-scope='transfer'][data-part='item'][hidden],
  [data-scope='transfer'][data-part='item-checkbox'][hidden],
  [data-scope='transfer'][data-part='select-all-trigger'][hidden],
  [data-scope='transfer'][data-part='to-target-trigger'][hidden],
  [data-scope='transfer'][data-part='to-source-trigger'][hidden] {
    display: none;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中。
     堆叠时目标面板在下方，箭头因此朝下与朝上，指的是条目真正要去的方向 */
  [data-scope='transfer'][data-part='to-source-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-up) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-up) center / contain no-repeat;
  }

  [data-scope='transfer'][data-part='to-target-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
  }

  /* 宽档：视口放得下两块面板，回到并排——两侧面板各占一栏、跨两行，
     中间那栏上下各放一个搬运按钮，上格贴底、下格贴顶，两钮夹着中线相遇 */
  @media (min-width: 640px) {
    [data-scope='transfer'][data-part='source-panel'] {
      grid-row: 1 / 3;
      grid-column: 1;
    }

    [data-scope='transfer'][data-part='target-panel'] {
      grid-row: 1 / 3;
      grid-column: 3;
    }

    [data-scope='transfer'][data-part='to-target-trigger'] {
      grid-row: 1;
      grid-column: 2;
      align-self: end;
      justify-self: stretch;
    }

    [data-scope='transfer'][data-part='to-source-trigger'] {
      grid-row: 2;
      grid-column: 2;
      align-self: start;
      justify-self: stretch;
    }

    /* 单向组合的唯一动作跨过两行，中心才与两侧面板的中心重合。 */
    [data-scope='transfer'][data-part='root'][data-one-way]
      > [data-scope='transfer'][data-part='to-target-trigger'] {
      grid-row: 1 / 3;
      align-self: center;
    }

    /* 并排时目标面板在行尾侧，箭头改回朝行尾与朝行首。
       盒的量法与窄档那两条逐字相同：兜底字形的盒必须按 --xh-icon-size 量，
       作者换成自己的图标才和皮肤画的一样大 */
    [data-scope='transfer'][data-part='to-source-trigger']:empty::before {
      content: '';
      display: inline-block;
      inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
      block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
      vertical-align: var(--xh-glyph-baseline-shift);
      background-color: currentColor;
      -webkit-mask: var(--xh-glyph-mark-chevron-left) center / contain no-repeat;
      mask: var(--xh-glyph-mark-chevron-left) center / contain no-repeat;
    }

    [data-scope='transfer'][data-part='to-target-trigger']:empty::before {
      content: '';
      display: inline-block;
      inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
      block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
      vertical-align: var(--xh-glyph-baseline-shift);
      background-color: currentColor;
      -webkit-mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
      mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
    }
  }
}

/* styles/tree.css */
/* 定义 tree 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='tree'] {
    --xh-tree-skin: 1;
  }

  [data-scope='tree'][data-part='root'] {
    /* 行外的字形（空态 / 在途占位里作者塞的图标）按档取尺，树没有 size 轴、固定 md；
       行内的由家族随 data-xh-collection-size 下发。这支只管作者放进行里的图标：
       树自绘的状态字形（展开方向、行尾对号与半选杠）是指示符，各部件在自己身上
       把 --xh-icon-size 改接到 --xh-control-indicator-* 一族的盒尺 */
    --xh-icon-size: var(--xh-tree-icon-size, var(--xh-glyph-size-md));

    display: flex;
    flex-direction: column;
    gap: var(--xh-tree-gap, var(--xh-space-2));
  }

  [data-scope='tree'][data-part='root'][hidden] {
    display: none;
  }

  /* 淡底档：描边透明、底换成 subtle；outline 即基础规则。
     形态由 root 的 data-variant 向容器下发，容器基础规则直接写 border-default / bg-surface，
     与 list / descriptions 的 outline 面同源（列表容器族） */
  [data-scope='tree'][data-part='root'][data-variant='subtle'] [data-scope='tree'][data-part='tree'] {
    border-color: transparent;
    background: var(--xh-tree-bg, var(--xh-bg-subtle));
  }

  /* 无框档：边框留着但透明，去掉外框不会让行的位置跳一格 */
  [data-scope='tree'][data-part='root'][data-variant='ghost'] [data-scope='tree'][data-part='tree'] {
    border-color: transparent;
    background: transparent;
  }

  [data-scope='tree'][data-part='label'] {
    color: var(--xh-tree-label-fg, var(--xh-fg-muted));
    font-size: var(--xh-tree-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-tree-label-font-weight, var(--xh-text-label-weight));
    line-height: var(--xh-leading-none);
  }

  /* 整棵树禁用会把 data-disabled 一路打到 label / tree 上，各处观感保持一致 */
  [data-scope='tree'][data-part='label'][data-disabled] {
    color: var(--xh-fg-subtle);
  }

  /* 常驻容器不是浮层：留边框与底色，但不投影、不脱离文档流，滚动发生在容器自身 */
  [data-scope='tree'][data-part='tree'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-tree-tree-gap, var(--xh-list-option-gap));
    max-block-size: var(--xh-tree-max-h, var(--xh-viewport-h-lg));
    padding-block: var(--xh-tree-py, var(--xh-space-1));
    padding-inline: var(--xh-tree-px, var(--xh-space-1));
    border: var(--xh-stroke-thin) solid var(--xh-tree-border, var(--xh-border-default));
    border-radius: var(--xh-tree-radius, var(--xh-shape-surface));
    background: var(--xh-tree-bg, var(--xh-bg-surface));
    color: var(--xh-tree-fg, var(--xh-fg-default));
    /* 两轴一起给：深层节点靠缩进往右推，横向溢出是常态，得够得着 */
    overflow: auto;
  }

  /* display 会盖掉 hidden 属性的 UA 规则，作者手动收起时要显式让位 */
  [data-scope='tree'][data-part='tree'][hidden] {
    display: none;
  }

  /* 空态占位：待在 root 里、tree 的兄弟（role=tree 只许拥有 treeitem 与 group）。
     盒归 tree，这里只画一句居中的次要文字 */
  [data-scope='tree'][data-part='empty'] {
    display: block;
    padding-block: var(--xh-tree-empty-py, var(--xh-space-3));
    padding-inline: var(--xh-tree-empty-px, var(--xh-space-3));
    color: var(--xh-tree-empty-fg, var(--xh-fg-subtle));
    font-size: var(--xh-tree-empty-font-size, var(--xh-text-body-size));
    line-height: var(--xh-leading-none);
    text-align: center;
  }

  /* 上面给了 display，UA 的 [hidden]{display:none} 已被盖掉，这里补回来 */
  [data-scope='tree'][data-part='empty'][hidden] {
    display: none;
  }

  [data-scope='tree'][data-part='empty'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 在途占位：与空态占位同一个位置、同一副观感，两者不同屏 */
  [data-scope='tree'][data-part='loading'] {
    display: block;
    padding-block: var(--xh-tree-loading-py, var(--xh-space-3));
    padding-inline: var(--xh-tree-loading-px, var(--xh-space-3));
    color: var(--xh-tree-loading-fg, var(--xh-fg-subtle));
    font-size: var(--xh-tree-loading-font-size, var(--xh-text-body-size));
    line-height: var(--xh-leading-none);
    text-align: center;
  }

  [data-scope='tree'][data-part='loading'][hidden] {
    display: none;
  }

  [data-scope='tree'][data-part='loading'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 焦点在树外时容器自己进 Tab 序列兜底，落焦不画环：高亮永远长在行上 */
  [data-scope='tree'][data-part='tree']:focus-visible {
    outline: none;
  }

  /* 分支只是"这一行 + 它的子层"的外壳，不自带内边距：
     真正长成一行的是 branch-control，子层缩进归 branch-content。
     行距由这里出：分支自己那一行与它展开的子层之间，同样按条目间距断开 */
  [data-scope='tree'][data-part='branch'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-tree-branch-gap, var(--xh-list-option-gap));
  }

  [data-scope='tree'][data-part='branch'][hidden] {
    display: none;
  }

  /* 焦点落在 branch 上（它才是 treeitem），但环画在它自己那一行上：
     整棵子树套一圈描边会把展开的层级全框进去 */
  [data-scope='tree'][data-part='branch']:focus-visible {
    outline: none;
  }

  [data-scope='tree'][data-part='branch']:focus-visible > [data-scope='tree'][data-part='branch-control'] {
    outline: var(--xh-ring-width) solid var(--xh-ring-focus);
    outline-offset: var(--xh-ring-offset);
  }

  /* 行：叶子与分支共用同一套盒子，两种行在视觉上必须齐平。
     行走 Collection Item 的 overlay 语境，与树选择同一种选中读法：悬停 / 高亮 / 按下面（白底承载
     hover 100 → pressed 200）由家族给，选中不换面、不换字色，只在行尾亮对号，选中叠悬停 / 按下沿用同一条阶梯；
     家族按 aria-selected / data-selected 与 aria-disabled / data-disabled 给出，这里只把公开槽映射到桥接槽。
     布局保持 flex 而不用家族网格：一行里可以并排多个前导部件（箭头、拖拽把手）与作者自己的图标、
     按钮，单列的 prefix 放不下；间距统一由行的 gap 给，家族按槽下发的外边距（--xh-collection-gap）归零 */
  [data-scope='tree'][data-part='item'],
  [data-scope='tree'][data-part='branch-control'] {
    --xh-collection-block-padding: var(--xh-tree-row-py, var(--xh-list-option-py-md));
    --xh-collection-inline-padding: var(--xh-tree-row-px, var(--xh-control-px-md));
    --xh-collection-gap: 0;
    --xh-collection-font-size: var(--xh-tree-row-font-size, var(--xh-text-body-size));
    --xh-collection-radius: var(--xh-tree-row-radius, var(--xh-shape-control));
    /* 作者的图标尺槽经桥接槽下发到行，家族缺省按 md 档 */
    --xh-collection-glyph-size: var(--xh-tree-icon-size, var(--xh-_collection-glyph-size));
    /* 箭头 / 对号盒与叶子的占位同一把尺：指示符档，与同一行里的拖拽把手同走
       --xh-control-indicator-size（comfortable 16 / compact 14）。不读家族按档下发的 --xh-icon-size——
       那支只管作者放进行里的图标，按图标档取的 20px 会比 16px 的指示符盒大一圈 */
    --xh-_tree-indicator-size: var(--xh-tree-indicator-size, var(--xh-control-indicator-size));
    --xh-collection-fg-rest: var(--xh-tree-row-fg, var(--xh-fg-default));
    --xh-collection-fg-hover: var(--xh-tree-row-fg, var(--xh-fg-default));
    --xh-collection-fg-keyboard-highlight: var(--xh-tree-row-fg, var(--xh-fg-default));
    --xh-collection-fg-pressed: var(--xh-tree-row-fg, var(--xh-fg-default));
    --xh-collection-fg-selected: var(--xh-tree-row-fg-selected, var(--xh-tree-row-fg, var(--xh-fg-default)));
    --xh-collection-fg-selected-hover: var(--xh-tree-row-fg-selected, var(--xh-tree-row-fg, var(--xh-fg-default)));
    --xh-collection-fg-selected-highlight: var(--xh-tree-row-fg-selected, var(--xh-tree-row-fg, var(--xh-fg-default)));
    --xh-collection-fg-selected-pressed: var(--xh-tree-row-fg-selected, var(--xh-tree-row-fg, var(--xh-fg-default)));
    --xh-collection-font-weight-selected: var(--xh-tree-row-selected-font-weight, var(--xh-font-weight-regular));
    --xh-collection-font-weight-selected-hover: var(--xh-tree-row-selected-font-weight, var(--xh-font-weight-regular));
    --xh-collection-font-weight-selected-highlight: var(--xh-tree-row-selected-font-weight, var(--xh-font-weight-regular));
    --xh-collection-font-weight-selected-pressed: var(--xh-tree-row-selected-font-weight, var(--xh-font-weight-regular));
    --xh-collection-bg-hover: var(--xh-tree-row-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-keyboard-highlight: var(--xh-tree-row-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-pressed: var(--xh-tree-row-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-bg-selected-hover: var(--xh-tree-row-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-selected-highlight: var(--xh-tree-row-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-selected-pressed: var(--xh-tree-row-bg-pressed, var(--xh-bg-subtle-hover));
    /* data-highlighted 跟的是连接层记的焦点行（指针点选也会落焦）：只换面，焦点环在 :focus-visible 下再接回 */
    --xh-collection-outline-keyboard-highlight: transparent;
    --xh-collection-outline-selected-highlight: transparent;
    /* 行尾对号：槽按本部件取名（item-check-fg），标记部件的旧槽留在兜底位 */
    --xh-collection-indicator-fg-rest: var(--xh-tree-item-check-fg, var(--xh-tree-item-indicator-fg, var(--xh-fg-brand)));
    --xh-collection-indicator-fg-checked: var(--xh-tree-item-check-fg, var(--xh-tree-item-indicator-fg, var(--xh-fg-brand)));
    --xh-collection-indicator-fg-selected: var(--xh-tree-item-check-fg, var(--xh-tree-item-indicator-fg, var(--xh-fg-brand)));
    --xh-collection-indicator-fg-selected-hover: var(--xh-tree-item-check-fg, var(--xh-tree-item-indicator-fg, var(--xh-fg-brand)));
    --xh-collection-indicator-fg-selected-highlight: var(--xh-tree-item-check-fg, var(--xh-tree-item-indicator-fg, var(--xh-fg-brand)));
    --xh-collection-indicator-fg-selected-pressed: var(--xh-tree-item-check-fg, var(--xh-tree-item-indicator-fg, var(--xh-fg-brand)));

    display: flex;
    align-items: center;
    gap: var(--xh-tree-row-gap, var(--xh-control-gap-md));
    /* 行高留出文字的上下伸展空间，行内那层 overflow:hidden 才不会把字削掉 */
    line-height: var(--xh-tree-row-leading, var(--xh-leading-normal));
    white-space: nowrap;
    user-select: none;
    /* 换面走家族的按下 / 释放时间线（与家族基础块同一份，描边色同样不进过渡）；box-shadow 一并接过渡：
       换父落点那圈内描边挂在行自己身上，跟着 data-drop 在行间移动 */
    transition:
      background-color var(--xh-motion-duration-release) var(--xh-motion-ease-release),
      color var(--xh-motion-duration-micro) var(--xh-motion-ease-enter),
      box-shadow var(--xh-motion-duration-micro) var(--xh-motion-ease-enter);
  }

  /* 分支行的首格是展开箭头，叶子行没有这一格，由行盒自己补出来（对号在行尾，不再替叶子顶这一格），
     否则叶子会比同级分支往行首缩一格，层级关系读不出来。占位宽度与箭头盒同一把尺 */
  [data-orientation='vertical'] > [data-scope='tree'][data-part='item'] {
    padding-inline-start: calc(
      var(--xh-tree-row-px, var(--xh-control-px-md)) +
        var(--xh-_tree-indicator-size) +
        var(--xh-tree-row-gap, var(--xh-control-gap-md))
    );
  }

  /* 家族给了 display，UA 的 [hidden]{display:none} 已被盖掉 */
  [data-scope='tree'][data-part='item'][hidden],
  [data-scope='tree'][data-part='branch-control'][hidden] {
    display: none;
  }

  /* 键盘焦点出现时环才接回并立即到位，不压在背景过渡的中间帧上：叶子自己承载焦点；
     分支的焦点在 branch 上、环画在它那一行（见上面 branch:focus-visible 那条） */
  [data-scope='tree'][data-part='item']:focus-visible:not(:hover) {
    --xh-collection-outline-keyboard-highlight: var(--xh-ring-focus);
    --xh-collection-outline-selected-highlight: var(--xh-ring-focus);

    transition: none;
  }

  /* 禁用走 aria-disabled 而非原生 disabled：叶子的禁用面由家族按 aria-disabled 给；
     分支行不是 treeitem 本体（aria-disabled 在 branch 上），按连接层的 data-disabled 映射到家族槽：
     字色降级、光标 not-allowed，悬停 / 高亮 / 按下由家族守卫拦掉 */
  [data-scope='tree'][data-part='branch-control'][data-disabled] {
    --xh-collection-fg-rest: var(--xh-fg-disabled);
    --xh-collection-cursor-rest: not-allowed;
  }

  [data-scope='tree'][data-part='item-text'],
  [data-scope='tree'][data-part='branch-text'] {
    flex: 1;
    /* 弹性子项默认最小尺寸是内容尺寸，不归零则长文本把行撑破、省略号轮不上 */
    min-inline-size: 0;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  /* 选中对号落在行尾，与树选择同位：作者在行里摆在哪儿都排到最后，
     行尾那一格（item-suffix）在它之前；正文吃满剩余宽度，对号因此贴着行的末端。
     未选中时占位不塌，切换选中不引起行宽抖动。盒尺取指示符档；盒里的对号是指示符，
     在自己身上把 --xh-icon-size 改接到盒的尺，兜底对号与作者塞进盒里的 XhIcon 读同一把尺、与盒同边长 */
  [data-scope='tree'][data-part='item-indicator'] {
    --xh-icon-size: var(--xh-_tree-indicator-size);

    display: inline-flex;
    flex: none;
    order: 1;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-_tree-indicator-size);
  }

  [data-scope='tree'][data-part='item-indicator'][hidden] {
    display: none;
  }

  /* 家族只按行的 aria-selected 显示对号：分支行的 aria-selected 在 branch 上、半选没有选中语义，
     这两档按标记自身的 data-selected / data-indeterminate 显形 */
  [data-scope='tree'][data-part='item-indicator']:is([data-selected], [data-indeterminate]) {
    visibility: visible;
  }

  /* 分支行的禁用不在行的 aria-disabled 上（那在 branch 上），标记按自身的 data-disabled 降级 */
  [data-scope='tree'][data-part='item-indicator'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 展开箭头与方向指示符：两者都可能被作者用作"点这里展开"的把手，
     所以尺寸与叶子的勾选标记一致，两种行的文字起点才对得齐。
     盒里的 chevron 是指示符：与盒同边长，--xh-icon-size 在自己身上改接到盒的尺 */
  [data-scope='tree'][data-part='branch-trigger'],
  [data-scope='tree'][data-part='branch-indicator'] {
    --xh-icon-size: var(--xh-_tree-indicator-size);

    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-_tree-indicator-size);
    color: var(--xh-tree-branch-indicator-fg, var(--xh-fg-subtle));
    transition: rotate var(--xh-motion-duration-nudge) var(--xh-motion-ease-enter-strong);
  }

  [data-scope='tree'][data-part='branch-trigger'][hidden],
  [data-scope='tree'][data-part='branch-indicator'][hidden] {
    display: none;
  }

  /* 收起时朝向行首、展开时转向下方，与逻辑书写方向一致：
     rtl 下 inline-start 在右侧，箭头因此要反着转 */
  [data-scope='tree'][data-part='branch-trigger'][data-state='open'],
  [data-scope='tree'][data-part='branch-indicator'][data-state='open'] {
    rotate: 90deg;
  }

  [dir='rtl'] [data-scope='tree'][data-part='branch-trigger'],
  [dir='rtl'] [data-scope='tree'][data-part='branch-indicator'] {
    rotate: 180deg;
  }

  [dir='rtl'] [data-scope='tree'][data-part='branch-trigger'][data-state='open'],
  [dir='rtl'] [data-scope='tree'][data-part='branch-indicator'][data-state='open'] {
    rotate: 90deg;
  }

  [data-scope='tree'][data-part='branch-trigger'][data-disabled],
  [data-scope='tree'][data-part='branch-indicator'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 层级缩进靠子层容器自己顶：分支物理嵌套着子层，每深一层就多缩一格，
     无需把层级号写进内联样式，也就不必在两个适配器里各写一遍 */
  [data-scope='tree'][data-part='branch-content'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-tree-branch-content-gap, var(--xh-list-option-gap));
    padding-inline-start: var(--xh-tree-indent, var(--xh-space-4));
  }

  /* 末端那一层横排：子节点并排铺开、必要时折行。缩进照旧由子层容器自己顶——
     那是这一层相对上一层的位置，与层内怎么排无关 */
  [data-scope='tree'][data-part='branch-content'][data-orientation='horizontal'] {
    flex-flow: row wrap;
    align-items: center;
    column-gap: var(--xh-tree-leaf-row-gap, var(--xh-space-3));
    row-gap: var(--xh-tree-branch-content-gap, var(--xh-list-option-gap));
  }

  /* 横排的一层里节点并排，行盒不能再各自吃满一行 */
  [data-orientation='horizontal'] > [data-scope='tree'][data-part='item'] {
    flex: none;
  }

  /* 收起态的唯一开关：display 会盖掉 hidden 属性的 UA 规则，漏了这条整棵子树就收不起来。
     作者写的 hidden 与连接层发的 data-state=closed 都收在这里 */
  [data-scope='tree'][data-part='branch-content'][hidden],
  [data-scope='tree'][data-part='branch-content'][data-state='closed'] {
    display: none;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中。
     尺寸读部件自己改接过的 --xh-icon-size：chevron 与对号都与盒同边长（见上面两块） */
  [data-scope='tree'][data-part='branch-trigger']:empty::before,
  [data-scope='tree'][data-part='branch-indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
  }

  [data-scope='tree'][data-part='item-indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    mask: var(--xh-glyph-mark-check) center / contain no-repeat;
  }

  [data-scope='tree'][data-part='item-indicator'][data-indeterminate]:not([data-selected]):empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-minus);
    mask-image: var(--xh-glyph-mark-minus);
  }

  /* —— 节点拖拽搬家 —— */
  /* 整行都是拖动源，光标换成抓手告诉人这一行按得动。
     这条不写 touch-action：整行关掉纵向手势，树容器自己就滚不动了；
     触屏那一路交给下面那块专属把手 */
  [data-scope='tree'][data-part='item'][data-draggable],
  [data-scope='tree'][data-part='branch-control'][data-draggable] {
    cursor: grab;
  }

  /* 节点拖拽把手：行里的一小块专属拖动区，按下即拖。触屏靠它起手，
     代价只是这一小块地方不再跟着树滚。整行起手那一路原样保留，把手是叠加的第二个入口。
     touch-action 不在这儿写：连接层按「拖不动就不写」把它写进了内联 style，
     皮肤再写一遍会盖掉那份条件判断，让不可拖的节点也白白让出滚动 */
  [data-scope='tree'][data-part='node-drag-trigger'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-tree-drag-size, var(--xh-control-indicator-size));
    block-size: var(--xh-tree-drag-size, var(--xh-control-indicator-size));
    border-radius: var(--xh-tree-drag-radius, var(--xh-shape-control));
    color: var(--xh-tree-drag-fg, var(--xh-fg-subtle));
    cursor: grab;
  }

  [data-scope='tree'][data-part='node-drag-trigger'][hidden] {
    display: none;
  }

  /* 抓手是两条横线：盒子取边框盒，块向两侧的描边就是那两条线，宽高与线宽都走令牌。
     线的走向与能拖的方向垂直——节点沿块向上下排，画的就是横线。
     用逻辑属性写，书写模式一换，线跟着排列轴自己转过去。
     :empty 守卫让作者塞进来的图标整个顶掉它，而不是两份叠在一起 */
  [data-scope='tree'][data-part='node-drag-trigger']:empty::after {
    content: '';
    display: block;
    inline-size: var(--xh-tree-drag-grip-long, var(--xh-space-2));
    block-size: var(--xh-tree-drag-grip-short, var(--xh-space-1));
    border-block: var(--xh-stroke-thin) solid currentColor;
  }

  [data-scope='tree'][data-part='node-drag-trigger']:not([data-disabled]):hover,
  [data-scope='tree'][data-part='node-drag-trigger'][data-dragging] {
    color: var(--xh-tree-drag-fg-active, var(--xh-fg-default));
  }

  [data-scope='tree'][data-part='node-drag-trigger'][data-dragging] {
    cursor: grabbing;
  }

  /* 不可拖的节点照样带一个把手，这里保住它的位置、只把它压到禁用色。
     收成 display: none 是不行的：把手占着行首那一格，藏掉之后同一层里能拖与不能拖的两个节点，
     文字起点会错开一格，层级关系跟着读歪 */
  [data-scope='tree'][data-part='node-drag-trigger'][data-disabled] {
    color: var(--xh-tree-drag-fg-disabled, var(--xh-fg-disabled));
  }

  /* 被拖的那一行压暗，让人看得出正在搬的是它。这里只动 opacity、cursor 与 user-select，
     一个 transform 都不写：行原地不动，要落到哪儿全交给落点指示 */
  [data-scope='tree'][data-part='item'][data-dragging],
  [data-scope='tree'][data-part='branch-control'][data-dragging] {
    opacity: var(--xh-tree-dragging-opacity, var(--xh-state-dragging-opacity));
    cursor: grabbing;
    user-select: none;
  }

  /* 落点指示线：插到哪一行的哪一侧，横线就画在那一行的那条边上。
     定位上下文只给要画线的那一行：行平时都不定位，缺了它伪元素会一路上溯到最近的定位祖先，
     线就画到树外面去；写到所有行上则是给每一行都多担一份，而落点同一时刻只有一个。
     整块高亮那一档不在此列：它不靠伪元素，用不着这层上下文 */
  [data-scope='tree'][data-part='item']:is([data-drop='before'], [data-drop='after']),
  [data-scope='tree'][data-part='branch-control']:is([data-drop='before'], [data-drop='after']) {
    position: relative;
  }

  /* 线贯穿整行宽度。行自身不收 overflow，线不会被行裁掉；
     但仍整条画在行内不压着边——压着边画的话，首行那条上沿线会被树容器的圆角与滚动裁掉半条 */
  [data-scope='tree'][data-part='item']:is([data-drop='before'], [data-drop='after'])::after,
  [data-scope='tree'][data-part='branch-control']:is([data-drop='before'], [data-drop='after'])::after {
    content: '';
    position: absolute;
    inset-inline: 0;
    block-size: var(--xh-tree-drop-line, var(--xh-stroke-thick));
    background: var(--xh-tree-drop-fg, var(--xh-border-control-focus));
  }

  /* 落在上沿还是下沿走逻辑属性，块向跟着书写模式走。
     换成 box-shadow 的偏移量则是物理的，写不出逻辑方向 */
  [data-scope='tree'][data-part='item'][data-drop='before']::after,
  [data-scope='tree'][data-part='branch-control'][data-drop='before']::after {
    inset-block-start: 0;
  }

  [data-scope='tree'][data-part='item'][data-drop='after']::after,
  [data-scope='tree'][data-part='branch-control'][data-drop='after']::after {
    inset-block-end: 0;
  }

  /* 放进这个节点里面：整行淡底加一圈内描边，与上下沿那条横线一眼分得开。
     描边走零偏移的内投影，四边同时着色、不涉及方向，也跟着行的圆角走。
     选择器里那条 :not([data-disabled]) 是把特指度补到与悬停那条齐平，再靠排在它之后压过它：
     指针本来就停在落点这一行上，少了这一段，落点底色会被悬停那档灰盖掉。
     禁用的节点从来不做落点，这一段因此不会漏画任何一处高亮 */
  [data-scope='tree'][data-part='item'][data-drop='inside']:not([data-disabled]),
  [data-scope='tree'][data-part='branch-control'][data-drop='inside']:not([data-disabled]) {
    /* 落点不是选中：品牌淡底专属选中 / 当前，落点面取悬停之上一档的中性面 */
    background: var(--xh-tree-drop-inside-bg, var(--xh-bg-subtle-hover));
    box-shadow: inset 0 0 0 var(--xh-tree-drop-line, var(--xh-stroke-thick))
      var(--xh-tree-drop-fg, var(--xh-border-control-focus));
  }

  /* 活动区域只说给读屏听，不占版面。声明与 shared/visually-hidden.ts 逐条同值。 */
  [data-scope='tree'][data-part='live-region'] {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }

  @media print {
    /* 打印默认丢底色，而对号与半选杠是遮罩出来的一块底色：行本就不换面，丢了它选中在纸上就没了踪影 */
    [data-scope='tree'][data-part='item-indicator'] {
      print-color-adjust: exact;
    }
  }
}

/* styles/tree-select.css */
/* TreeSelect 独立皮肤同时传递引入字段视觉盒、字段内动作与浮层集合行；full bundle 递归去重。 */

/* 共享关键帧由 family/motion.css 提供，本皮肤 @import 它，单独引入仍成立。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='tree-select'] {
    --xh-tree-select-skin: 1;
  }

  /* 坐标由定位引擎写进 style（inset-inline-start / inset-block-start），这里只定位模式与层级 */
  [data-scope='tree-select'][data-part='positioner'] {
    /* 落定那一侧的可用高度，由定位引擎经内联自定义属性写进来，内容层继承它限高；
       引擎没算（尚未落位 / 无引擎）时不额外限高 */
    --xh-_tree-select-available-h: 100vh;
    /* 落定那一侧的可用宽度，同样由定位引擎经内联自定义属性写进来，行内轴据此夹取；
       引擎没算（尚未落位 / 无引擎 / 贴边归零）时退到视口宽 */
    --xh-_tree-select-available-w: 100vw;
    /* 触发器实测宽度，由定位引擎经内联自定义属性写进来，内容层拿它当最小宽的下界；
       引擎没算（尚未落位 / 无引擎）时为 0，max 取静态档，等于不抬宽 */
    --xh-_tree-select-anchor-w: 0px;
    /* 独立浮层先截断祖先方向，再按自身 placement 开启一侧。 */
    --xh-_overlay-enter-up: 0;
    --xh-_overlay-enter-down: 0;
    --xh-_overlay-enter-left: 0;
    --xh-_overlay-enter-right: 0;

    /* 树的自绘条浮在内容之上：轨道不上底色，实色轨道会沿内容边缘糊出一条灰带 */
    --xh-scrollbar-track-bg: transparent;

    position: fixed;
    z-index: var(--xh-tree-select-layer, var(--xh-_layer, var(--xh-layer-popover)));
    /* 空壳不吃指针，交互只发生在 content 里 */
    pointer-events: none;
  }

  /* 锚点被滚出可视区：整个浮层随之收起 */
  [data-scope='tree-select'][data-part='positioner'][data-hidden] {
    visibility: hidden;
  }

  /* 位移按实际落位的物理方向给，不随书写方向翻转。 */
  [data-scope='tree-select'][data-part='positioner'][data-placement^='top'] {
    --xh-_overlay-enter-down: 1;
  }

  [data-scope='tree-select'][data-part='positioner'][data-placement^='bottom'] {
    --xh-_overlay-enter-up: 1;
  }

  [data-scope='tree-select'][data-part='positioner'][data-placement^='left'] {
    --xh-_overlay-enter-right: 1;
  }

  [data-scope='tree-select'][data-part='positioner'][data-placement^='right'] {
    --xh-_overlay-enter-left: 1;
  }

  /* 私有槽同时声明在根与 positioner 上：浮层被搬到 portal 落点，不是根的后代，继承不过去 */
  [data-scope='tree-select']:is([data-part='root'], [data-part='positioner']) {
    /* 作者塞进触发器指示符槽 / 清除钮的图标跟着尺寸档走，与皮肤画的兜底字形同一把尺。这支只管作者放进
       盒与行里的图标：面板里自绘的状态字形（展开方向、行尾对号与半选杠）是指示符，各部件在自己身上
       把 --xh-icon-size 改接到 --xh-control-indicator-* 一族的盒尺 */
    --xh-icon-size: var(--xh-tree-select-icon-size, var(--xh-glyph-size-md));

    /* 尺寸档只换这几个私有槽，盒与树里的行都从这两处继承它们，换档不必给每个部件各写一条选择器；
       形态三档由家族按 control 上的 data-variant 生成，浮层与树不跟着变，皮肤不再声明 */
    --xh-_tree-select-h: var(--xh-control-h-md);
    --xh-_tree-select-px: var(--xh-control-px-md);
    --xh-_tree-select-row-py: var(--xh-list-option-py-md);
    --xh-_tree-select-row-px: var(--xh-control-px-md);
    --xh-_tree-select-gap: var(--xh-control-gap-md);
    --xh-_tree-select-font-size: var(--xh-control-font-md);

    /* 强调色随语气走，只落在勾选标记上；没写 data-tone 时退回品牌色 */
    --xh-_tree-select-accent: var(--xh-_tone, var(--xh-fg-brand));
  }

  /* 标签一行、盒一行的两行堆叠 */
  [data-scope='tree-select'][data-part='root'] {
    display: inline-flex;
    flex-direction: column;
    gap: var(--xh-tree-select-gap, var(--xh-space-1));

    /* 不传尺寸时一律这么宽，宽度不随内容走；父容器给不出这么宽时整件跟着收，地板同步让步，不越出父容器。
       地板不高过缺省宽：使用者把缺省宽钉到底线以下时不必再放开底线 */
    inline-size: var(--xh-tree-select-control-w, var(--xh-control-w));
    min-inline-size: min(var(--xh-tree-select-control-w, var(--xh-control-w)), var(--xh-tree-select-control-min-w, var(--xh-control-min-w)), 100%);
    max-inline-size: 100%;
  }

  /* 只要声明了 display 就盖掉了 UA 的 [hidden]{display:none}，作者手动收起时要自己还回去 */
  [data-scope='tree-select'][data-part='root'][hidden] {
    display: none;
  }

  /* —— 尺寸 —— */
  /* 缺省档写在上面的基础规则里 */
  [data-scope='tree-select']:is([data-part='root'], [data-part='positioner'])[data-size='sm'] {
    --xh-icon-size: var(--xh-tree-select-icon-size, var(--xh-glyph-size-sm));
    --xh-_tree-select-h: var(--xh-control-h-sm);
    --xh-_tree-select-px: var(--xh-control-px-sm);
    --xh-_tree-select-row-py: var(--xh-list-option-py-sm);
    --xh-_tree-select-row-px: var(--xh-control-px-sm);
    --xh-_tree-select-gap: var(--xh-control-gap-sm);
    --xh-_tree-select-font-size: var(--xh-control-font-sm);
  }

  [data-scope='tree-select']:is([data-part='root'], [data-part='positioner'])[data-size='lg'] {
    --xh-icon-size: var(--xh-tree-select-icon-size, var(--xh-glyph-size-lg));
    --xh-_tree-select-h: var(--xh-control-h-lg);
    --xh-_tree-select-px: var(--xh-control-px-lg);
    --xh-_tree-select-row-py: var(--xh-list-option-py-lg);
    --xh-_tree-select-row-px: var(--xh-control-px-lg);
    --xh-_tree-select-gap: var(--xh-control-gap-lg);
    --xh-_tree-select-font-size: var(--xh-control-font-lg);
  }

  [data-scope='tree-select'][data-part='label'] {
    color: var(--xh-tree-select-label-fg, var(--xh-fg-default));
    font-size: var(--xh-tree-select-label-font-size, var(--xh-text-label-size));
    font-weight: var(--xh-tree-select-label-font-weight, var(--xh-text-label-weight));
    line-height: var(--xh-leading-none);
  }

  /* 整个控件禁用会把 data-disabled 一路打到 label / value-text / indicator 上，各处观感保持一致 */
  [data-scope='tree-select'][data-part='label'][data-disabled] {
    color: var(--xh-fg-subtle);
  }

  /* 盒：描边、底色、圆角、控件高度、行内内衬、聚焦环、五态与悬停由 Field Chrome 家族画在这一层，
     触发按钮与清空按钮在里面并排；Tab 停靠点是盒里的 trigger（展开后才移进树里），环由家族的
     :focus-within 画在盒上。组件只映射既有公开槽（shadow 缺省 none：字段静息描边式、无影）；盒里是按钮 */
  [data-scope='tree-select'][data-part='control'] {
    --xh-field-control-height: var(--xh-tree-select-control-h, var(--xh-_tree-select-h));
    --xh-field-control-padding-inline: var(--xh-tree-select-control-px, var(--xh-_tree-select-px));
    --xh-field-control-gap: var(--xh-tree-select-control-gap, var(--xh-_tree-select-gap));
    --xh-field-control-min-inline-size: var(--xh-tree-select-control-min-w, var(--xh-control-min-w));
    --xh-field-control-radius: var(--xh-tree-select-control-radius, var(--xh-shape-control));
    --xh-field-bg-rest: var(--xh-tree-select-control-bg, var(--xh-_field-variant-bg-rest));
    --xh-field-bg-hover: var(--xh-tree-select-control-bg-hover, var(--xh-_field-variant-bg-hover));
    --xh-field-bg-read-only: var(--xh-tree-select-control-bg-readonly, var(--xh-_field-variant-bg-read-only));
    --xh-field-bg-disabled: var(--xh-tree-select-control-bg-disabled, var(--xh-_field-variant-bg-disabled));
    --xh-field-fg-rest: var(--xh-tree-select-control-fg, var(--xh-fg-default));
    --xh-field-border-rest: var(--xh-tree-select-control-border, var(--xh-_field-variant-border-rest));
    --xh-field-border-hover: var(--xh-tree-select-control-border-hover, var(--xh-_field-variant-border-hover));
    --xh-field-border-focus: var(--xh-tree-select-control-border-focus, var(--xh-_field-variant-border-focus));
    --xh-field-border-invalid: var(--xh-tree-select-control-border-invalid, var(--xh-_field-variant-border-invalid));
    --xh-field-ring-focus: var(--xh-ring-focus);
    --xh-field-ring-invalid: var(--xh-ring-invalid);
    --xh-field-shadow-rest: var(--xh-tree-select-control-shadow, none);
    --xh-field-cursor-rest: pointer;
    /* 家族 chrome 会重写 --xh-icon-size，使用者图标槽必须经桥接槽下发才能在盒内生效 */
    --xh-field-glyph-size: var(--xh-tree-select-icon-size, var(--xh-_field-size-glyph-size));
  }

  [data-scope='tree-select'][data-part='control'][hidden] {
    display: none;
  }

  /* 盒内那颗可聚焦的按钮：不画描边不铺底也不自带高度，只占满剩余宽度、排布回显与箭头 */
  [data-scope='tree-select'][data-part='trigger'] {
    display: inline-flex;
    flex: 1 1 auto;
    align-items: center;
    justify-content: space-between;
    gap: var(--xh-tree-select-trigger-gap, var(--xh-_tree-select-gap));
    min-inline-size: 0;
    padding: 0;
    border: 0;
    background: transparent;
    color: var(--xh-tree-select-trigger-fg, var(--xh-fg-default));
    font-family: inherit;
    font-size: var(--xh-tree-select-trigger-font-size, var(--xh-_tree-select-font-size));
    line-height: var(--xh-leading-none);
    text-align: start;
    cursor: pointer;
  }

  [data-scope='tree-select'][data-part='trigger'][hidden] {
    display: none;
  }

  /* trigger 是单体控件，用原生 disabled（树里的集合条目一律 aria-disabled，写 :disabled 永不命中） */
  [data-scope='tree-select'][data-part='trigger']:disabled {
    color: var(--xh-fg-disabled);
  }

  /* 多选时值会连成很长一串，必须能截断；框宽由盒定，这里得允许自己被压缩 */
  [data-scope='tree-select'][data-part='value-text'] {
    flex: 1 1 auto;
    min-inline-size: 0;
    overflow: hidden;
    /* 行高留出文字的上下伸展空间，本行那层 overflow:hidden 才不会把字削掉；
       触发框自带固定高度，抬行高不改变几何 */
    line-height: var(--xh-tree-select-value-leading, var(--xh-leading-normal));
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  /* 无选中：显示的是 placeholder，画淡一档 */
  [data-scope='tree-select'][data-part='value-text'][data-placeholder] {
    color: var(--xh-tree-select-placeholder-fg, var(--xh-fg-subtle));
  }

  [data-scope='tree-select'][data-part='value-text'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 有值时清空钮顶上来，箭头让位：两个图标并排堆着，用户分不清点哪个。
     判据查的是盒里此刻真有一颗没收起的清空钮，不是「有没有值」——
     作者没摆清空钮时箭头照常留着，不然让了位没人接，指示符整个消失 */
  [data-scope='tree-select'][data-part='control']:has([data-part='clear-trigger']:not([hidden])) [data-part='indicator'] {
    display: none;
  }

  [data-scope='tree-select'][data-part='indicator'] {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    color: var(--xh-tree-select-indicator-fg, var(--xh-fg-muted));
    transition: rotate var(--xh-motion-duration-nudge) var(--xh-motion-ease-enter-strong);
  }

  [data-scope='tree-select'][data-part='indicator'][hidden] {
    display: none;
  }

  [data-scope='tree-select'][data-part='indicator'][data-state='open'] {
    rotate: 180deg;
  }

  [data-scope='tree-select'][data-part='indicator'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 盒内靠右的小方钮，不撑高那一行：正方视觉盒、inset 圆角、悬停 100 / 按下 200 与 0.97 按压、粗指针热区与
     :focus-visible 关环（盒的 :focus-within 已画了一圈）全由 Action Control 的 field-inset ghost 档给，
     组件只映射既有覆盖槽 */
  [data-scope='tree-select'][data-part='clear-trigger'] {
    --xh-action-visual-size: var(--xh-tree-select-action-size, var(--xh-_action-profile-visual-size));
    --xh-action-min-inline-size: var(--xh-tree-select-action-size, var(--xh-_action-profile-visual-size));
    --xh-action-radius: var(--xh-tree-select-action-radius, var(--xh-shape-inset));
    /* 底色阶梯由 ghost 档给（透明 → 100 → 200），使用者槽只作覆盖入口 */
    --xh-action-bg-rest: var(--xh-tree-select-action-bg, var(--xh-_action-variant-bg-rest));
    --xh-action-bg-hover: var(--xh-tree-select-action-bg-hover, var(--xh-_action-variant-bg-hover));
    --xh-action-bg-pressed: var(--xh-tree-select-action-bg-active, var(--xh-_action-variant-bg-pressed));
    --xh-action-fg-rest: var(--xh-tree-select-action-fg, var(--xh-fg-muted));
    --xh-action-fg-hover: var(--xh-tree-select-action-fg-hover, var(--xh-fg-default));
    --xh-action-border-rest: transparent;
    --xh-action-highlight-rest: transparent;
    --xh-action-shadow-rest: none;
    --xh-action-shadow-hover: none;
    --xh-action-shadow-pressed: none;
    --xh-action-font-size: var(--xh-tree-select-action-font-size, var(--xh-text-secondary-size));
    /* 配方尚未把 profile 字形档灌进 --xh-icon-size，钮内字形先按 field-inset 档逐钮取值 */
    --xh-icon-size: var(--xh-_action-profile-glyph-size);

    border-width: 0;
  }

  /* 没值时连接层给的是 hidden 属性；家族那条 display 会把 UA 规则盖掉 */
  [data-scope='tree-select'][data-part='clear-trigger'][hidden] {
    display: none;
  }

  [data-scope='tree-select'][data-part='content'] {
    position: relative;
    display: flex;
    flex-direction: column;
    /* min 优先于 max，锚点与静态下界也必须受可用宽度约束。 */
    min-inline-size: min(
      max(var(--xh-tree-select-content-min-w, var(--xh-overlay-min-w)), var(--xh-_tree-select-anchor-w)),
      var(--xh-_tree-select-available-w)
    );
    /* 静态档与落位后的可用宽度取小：窄视口下面板伸出去，最右侧的内容就点不到了 */
    max-inline-size: min(var(--xh-tree-select-content-max-w, var(--xh-overlay-max-w)), var(--xh-_tree-select-available-w));
    max-block-size: min(var(--xh-tree-select-content-max-h, var(--xh-overlay-max-h)), var(--xh-_tree-select-available-h));
    padding-block: var(--xh-tree-select-content-py, var(--xh-space-1));
    padding-inline: var(--xh-tree-select-content-px, var(--xh-space-1));
    border: var(--xh-stroke-thin) solid var(--xh-tree-select-content-border, var(--xh-material-frosted-border));
    border-radius: var(--xh-tree-select-content-radius, var(--xh-shape-overlay));
    background: var(--xh-tree-select-content-bg, var(--xh-material-frosted-bg));
    color: var(--xh-tree-select-content-fg, var(--xh-material-frosted-fg));
    box-shadow: var(--xh-tree-select-content-shadow, var(--xh-material-frosted-shadow));
    -webkit-backdrop-filter: var(--xh-tree-select-content-backdrop, var(--xh-material-frosted-backdrop));
    backdrop-filter: var(--xh-tree-select-content-backdrop, var(--xh-material-frosted-backdrop));
    /* 两轴一起给：深层节点靠缩进往行末推，横向溢出是常态，得够得着 */
    overflow: auto;
    /* 浮层滚动面：滚到头不把页面一起带走 */
    overscroll-behavior: contain;
    pointer-events: auto;
  }

  /* 顶光位于真实边框内侧，不参与布局或拦截树行操作。 */
  [data-scope='tree-select'][data-part='content']::before {
    content: '';
    position: absolute;
    inset-block-start: 0;
    inset-inline: 0;
    block-size: var(--xh-stroke-thin);
    border-radius: inherit;
    background: var(--xh-tree-select-content-highlight, var(--xh-material-frosted-highlight));
    pointer-events: none;
  }

  /* 这里刻意没有 [data-part='content'][hidden] { display: none }，与 dialog 一致：
     收起态连接层会给 content 打 hidden，而上面那条 display 正是要盖掉 UA 的
     [hidden]{display:none}——退场动画得先能播。presence 读的是 content 的 animationName，
     真正的收起由宿主在退场结束后落成内联 display:none（Vue 那边直接不渲染）。
     其余声明了 display 的角色节点仍补 [hidden]，那几处没有退场动画。 */

  /* 容器只是焦点域的兜底落点，落焦不画环：高亮永远长在行上 */
  [data-scope='tree-select'][data-part='content']:focus-visible {
    outline: none;
  }

  [data-scope='tree-select'][data-part='content'][data-state='open'] {
    animation: xh-overlay-slide-in var(--xh-motion-duration-enter) var(--xh-motion-ease-enter-strong);
  }

  /* 退场：收起那一帧 hidden 由退场闸门押后，这里才播得出来。forwards 把末态钉住，
     免得动画结束到真收起之间闪一下原样 */
  [data-scope='tree-select'][data-part='content'][data-state='closed'] {
    animation: xh-overlay-slide-out var(--xh-motion-duration-exit) var(--xh-motion-ease-exit) forwards;
  }

  /* 边框、底色与滚动都归 content，树本身只把行竖着排开 */
  [data-scope='tree-select'][data-part='tree'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-tree-select-tree-gap, var(--xh-list-option-gap));
  }

  [data-scope='tree-select'][data-part='tree'][hidden] {
    display: none;
  }

  /* 空态占位：待在 content 里、tree 的兄弟（role=tree 只许拥有 treeitem 与 group）。
     盒与阴影归 content，这里只画一句居中的次要文字 */
  [data-scope='tree-select'][data-part='empty'] {
    display: block;
    flex: none;
    padding-block: var(--xh-tree-select-empty-py, var(--xh-space-3));
    padding-inline: var(--xh-tree-select-empty-px, var(--xh-_tree-select-row-px));
    color: var(--xh-tree-select-empty-fg, var(--xh-material-frosted-fg-muted));
    font-size: var(--xh-tree-select-empty-font-size, var(--xh-_tree-select-font-size));
    line-height: var(--xh-leading-none);
    text-align: center;
  }

  /* 上面给了 display，UA 的 [hidden]{display:none} 已被盖掉，这里补回来 */
  [data-scope='tree-select'][data-part='empty'][hidden] {
    display: none;
  }

  /* 在途占位：与空态占位同一个位置、同一副观感，两者不同屏 */
  [data-scope='tree-select'][data-part='loading'] {
    display: block;
    flex: none;
    padding-block: var(--xh-tree-select-loading-py, var(--xh-space-3));
    padding-inline: var(--xh-tree-select-loading-px, var(--xh-_tree-select-row-px));
    color: var(--xh-tree-select-loading-fg, var(--xh-material-frosted-fg-muted));
    font-size: var(--xh-tree-select-loading-font-size, var(--xh-_tree-select-font-size));
    line-height: var(--xh-leading-none);
    text-align: center;
  }

  [data-scope='tree-select'][data-part='loading'][hidden] {
    display: none;
  }

  /* 浮层底部的操作区：排在树下面，与树之间用一条分隔线断开；不参与收缩，行再多也压不扁它 */
  [data-scope='tree-select'][data-part='footer'] {
    display: flex;
    flex: none;
    align-items: center;
    gap: var(--xh-tree-select-footer-gap, var(--xh-space-2));
    padding-block: var(--xh-tree-select-footer-py, var(--xh-space-2));
    padding-inline: var(--xh-tree-select-footer-px, var(--xh-space-2));
    border-block-start: var(--xh-stroke-thin) solid var(--xh-tree-select-footer-border, var(--xh-material-frosted-separator));
    color: var(--xh-tree-select-footer-fg, var(--xh-material-frosted-fg-muted));
    font-size: var(--xh-tree-select-footer-font-size, var(--xh-text-secondary-size));
  }

  /* 上面给了 display，UA 的 [hidden]{display:none} 已被盖掉，这里补回来 */
  [data-scope='tree-select'][data-part='footer'][hidden] {
    display: none;
  }

  [data-scope='tree-select'][data-part='tree']:not([tabindex='0']):focus-visible {
    outline: none;
  }

  /* 分支是"这一行 + 它的子层"的外壳，不自带内边距：真正长成一行的是 branch-control，
     子层缩进归 branch-content。行距由这里出：分支自己那一行与它展开的子层之间，
     同样按条目间距断开 */
  [data-scope='tree-select'][data-part='branch'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-tree-select-branch-gap, var(--xh-list-option-gap));
  }

  /* display 盖掉了 UA 的 [hidden]{display:none}，收起时要显式让位 */
  [data-scope='tree-select'][data-part='branch'][hidden] {
    display: none;
  }

  /* 焦点落在 branch 上（它才是 treeitem），但环画在它自己那一行上：
     整棵子树套一圈描边会把展开的层级全框进去 */
  [data-scope='tree-select'][data-part='branch']:focus-visible {
    outline: none;
  }

  /* 行：叶子与分支共用同一套盒子，两种行在视觉上必须齐平。网格、尺寸档、悬停 / 高亮 100、按下 200 与
     选中标记由 Collection Item 家族按 overlay 语境给（选中 = 透明底 + 行尾对号，正文保持 rest 色与常规
     字重），公开 TreeSelect 槽只映射到家族合同。data-highlighted 跟的是连接层记的焦点行（指针与键盘共用），
     环只在真正的键盘焦点上接回，见下 */
  [data-scope='tree-select'][data-part='item'],
  [data-scope='tree-select'][data-part='branch-control'] {
    --xh-collection-block-padding: var(--xh-tree-select-item-py, var(--xh-_tree-select-row-py));
    --xh-collection-inline-padding: var(--xh-tree-select-item-px, var(--xh-_tree-select-row-px));
    --xh-collection-gap: var(--xh-tree-select-item-gap, var(--xh-_tree-select-gap));
    --xh-collection-font-size: var(--xh-tree-select-item-font-size, var(--xh-_tree-select-font-size));
    --xh-collection-radius: var(--xh-tree-select-item-radius, var(--xh-shape-control));
    --xh-collection-glyph-size: var(--xh-tree-select-icon-size, var(--xh-_collection-glyph-size));
    --xh-collection-fg-rest: var(--xh-tree-select-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-hover: var(--xh-tree-select-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-keyboard-highlight: var(--xh-tree-select-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-fg-selected: var(--xh-tree-select-item-fg-selected, var(--xh-tree-select-item-fg, var(--xh-material-frosted-fg)));
    --xh-collection-fg-selected-highlight: var(--xh-tree-select-item-fg-selected, var(--xh-tree-select-item-fg, var(--xh-material-frosted-fg)));
    --xh-collection-fg-selected-hover: var(--xh-tree-select-item-fg-selected, var(--xh-tree-select-item-fg, var(--xh-material-frosted-fg)));
    --xh-collection-fg-selected-pressed: var(--xh-tree-select-item-fg-selected, var(--xh-tree-select-item-fg, var(--xh-material-frosted-fg)));
    --xh-collection-fg-pressed: var(--xh-tree-select-item-fg, var(--xh-material-frosted-fg));
    --xh-collection-font-weight-selected: var(--xh-tree-select-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-font-weight-selected-highlight: var(--xh-tree-select-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-font-weight-selected-hover: var(--xh-tree-select-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-font-weight-selected-pressed: var(--xh-tree-select-item-font-weight-selected, var(--xh-font-weight-regular));
    --xh-collection-bg-hover: var(--xh-tree-select-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-keyboard-highlight: var(--xh-tree-select-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-selected-highlight: var(--xh-tree-select-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-selected-hover: var(--xh-tree-select-item-bg-hover, var(--xh-bg-subtle));
    --xh-collection-bg-pressed: var(--xh-tree-select-item-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-bg-selected-pressed: var(--xh-tree-select-item-bg-pressed, var(--xh-bg-subtle-hover));
    --xh-collection-outline-keyboard-highlight: transparent;
    --xh-collection-outline-selected-highlight: transparent;
    --xh-collection-indicator-fg-rest: var(--xh-tree-select-item-check-fg, var(--xh-tree-select-item-indicator-fg, var(--xh-_tree-select-accent)));
    --xh-collection-indicator-fg-checked: var(--xh-tree-select-item-check-fg, var(--xh-tree-select-item-indicator-fg, var(--xh-_tree-select-accent)));
    --xh-collection-indicator-fg-selected: var(--xh-tree-select-item-check-fg, var(--xh-tree-select-item-indicator-fg, var(--xh-_tree-select-accent)));
    --xh-collection-indicator-fg-selected-hover: var(--xh-tree-select-item-check-fg, var(--xh-tree-select-item-indicator-fg, var(--xh-_tree-select-accent)));
    --xh-collection-indicator-fg-selected-highlight: var(--xh-tree-select-item-check-fg, var(--xh-tree-select-item-indicator-fg, var(--xh-_tree-select-accent)));
    --xh-collection-indicator-fg-selected-pressed: var(--xh-tree-select-item-check-fg, var(--xh-tree-select-item-indicator-fg, var(--xh-_tree-select-accent)));

    /* 行高留出文字的上下伸展空间，行内那层 overflow:hidden 才不会把字削掉 */
    line-height: var(--xh-tree-select-item-leading, var(--xh-leading-normal));
    white-space: nowrap;
    user-select: none;
  }

  /* 家族给了 display，UA 的 [hidden]{display:none} 已被盖掉，这里补回来 */
  [data-scope='tree-select'][data-part='item'][hidden],
  [data-scope='tree-select'][data-part='branch-control'][hidden] {
    display: none;
  }

  /* 叶子在家族网格的首列放一格与分支箭头等宽的占位：两种行的文字起点才对得齐；
     选中标记独立固定在行尾（indicator 列），不再同时承担层级缩进 */
  [data-scope='tree-select'][data-part='item']::before {
    content: '';
    grid-column: prefix;
    grid-row: 1 / span 2;
    inline-size: var(--xh-tree-select-branch-indicator-size, var(--xh-control-indicator-size));
    margin-inline-end: var(--xh-tree-select-item-gap, var(--xh-_tree-select-gap));
  }

  /* 键盘焦点出现时环才接回并立即到位，不压在背景过渡的中间帧上：叶子自己承载焦点，
     分支的焦点在 branch 上、环画在它那一行 */
  [data-scope='tree-select'][data-part='item']:focus-visible:not(:hover),
  [data-scope='tree-select'][data-part='branch']:focus-visible > [data-scope='tree-select'][data-part='branch-control'] {
    --xh-collection-outline-keyboard-highlight: var(--xh-ring-focus);
    --xh-collection-outline-selected-highlight: var(--xh-ring-focus);

    transition: none;
  }

  /* 分支行不是 treeitem 本体（aria-disabled 在 branch 上），禁用面按连接层的 data-disabled 映射到家族槽：
     字色降级、悬停 / 高亮 / 按下不换面、光标 not-allowed */
  [data-scope='tree-select'][data-part='branch-control'][data-disabled] {
    --xh-collection-fg-rest: var(--xh-fg-disabled);
    --xh-collection-fg-hover: var(--xh-fg-disabled);
    --xh-collection-fg-keyboard-highlight: var(--xh-fg-disabled);
    --xh-collection-fg-pressed: var(--xh-fg-disabled);
    --xh-collection-bg-hover: transparent;
    --xh-collection-bg-keyboard-highlight: transparent;
    --xh-collection-bg-pressed: transparent;
    --xh-collection-cursor-rest: not-allowed;
    --xh-collection-cursor-hover: not-allowed;
    --xh-collection-cursor-keyboard-highlight: not-allowed;
    --xh-collection-cursor-pressed: not-allowed;
  }

  /* 懒分支取数失败不预设错误面（文案与重试归作者结构接线）：家族按 data-error 给的告警面在这里映射回常态 */
  [data-scope='tree-select'][data-part='branch-control'][data-error] {
    --xh-collection-bg-error: transparent;
    --xh-collection-fg-error: var(--xh-material-frosted-fg);
    --xh-collection-description-fg-error: var(--xh-material-frosted-fg-muted);
    --xh-collection-indicator-fg-error: var(--xh-_tree-select-accent);
    --xh-collection-outline-error: transparent;
  }

  /* 取数失败的行仍可激活（Enter / 点行触发重试），而家族的悬停、高亮与按下三段都排除了 [data-error]：
     这里在家族解算点上把同一阶梯接回（行槽以 item 取名、叶子与分支行共用，登记见 check-spacing-slots）：
     悬停与键盘高亮 100 档、按下 200 档并走按下时长，
     键盘焦点环随 branch 的 :focus-visible 画在这一行；禁用分支不进这三段 */
  [data-scope='tree-select'][data-part='branch-control'][data-error]:not([data-disabled]):is(:hover, [data-highlighted]) {
    --xh-_collection-bg: var(--xh-tree-select-item-bg-hover, var(--xh-bg-subtle));
  }

  [data-scope='tree-select'][data-part='branch']:focus-visible > [data-scope='tree-select'][data-part='branch-control'][data-error]:not([data-disabled]) {
    --xh-_collection-bg: var(--xh-tree-select-item-bg-hover, var(--xh-bg-subtle));
    --xh-_collection-outline: var(--xh-ring-focus);
  }

  [data-scope='tree-select'][data-part='branch-control'][data-error]:not([data-disabled]):is(:active, [data-pressed]) {
    --xh-_collection-bg: var(--xh-tree-select-item-bg-pressed, var(--xh-bg-subtle-hover));

    transition-duration: var(--xh-motion-duration-press);
    transition-timing-function: var(--xh-motion-ease-press);
  }

  /* 正文落在家族网格的 text 列；网格项默认最小尺寸是内容尺寸，不归零则长文本把行撑破、省略号轮不上 */
  [data-scope='tree-select'][data-part='item-text'],
  [data-scope='tree-select'][data-part='branch-text'] {
    min-inline-size: 0;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  /* 勾选标记落在家族网格的 indicator 列；未选中时占位不塌，切换选中不引起行宽抖动。
     尺寸槽按各自部件取名：行内的勾与展开箭头分别是 item- 与 branch- 段，
     触发器上那枚箭头是 --xh-tree-select-indicator-*，三处各调各的。
     盒里的对号 / 半选杠是指示符：在自己身上把 --xh-icon-size 改接到盒的尺，兜底字形与作者
     塞进盒里的 XhIcon 读同一把尺、与盒同边长；不读家族按档下发到行的 --xh-icon-size——那支只管
     作者放进行里的图标，按图标档取的 20px 会比 16 / 14 的盒还大 */
  [data-scope='tree-select'][data-part='item-indicator'] {
    --xh-icon-size: var(--xh-tree-select-item-indicator-size, var(--xh-control-indicator-size));

    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-tree-select-item-indicator-size, var(--xh-control-indicator-size));
    block-size: var(--xh-tree-select-item-indicator-size, var(--xh-control-indicator-size));
  }

  [data-scope='tree-select'][data-part='item-indicator'][hidden] {
    display: none;
  }

  /* 家族只按行的 aria-selected 显示对号：分支行的 aria-selected 在 branch 上、半选没有选中语义，
     这两档按标记自身的 data-selected / data-indeterminate 显形 */
  [data-scope='tree-select'][data-part='item-indicator']:is([data-selected], [data-indeterminate]) {
    visibility: visible;
  }

  /* 分支行的禁用不在行的 aria-disabled 上（那在 branch 上），标记按自身的 data-disabled 降级 */
  [data-scope='tree-select'][data-part='item-indicator'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 展开箭头与方向指示符：两者都可能被作者用作「点这里展开」的把手，
     所以尺寸与叶子的勾选标记一致，两种行的文字起点才对得齐。
     盒里的 chevron 是指示符：与盒同边长，--xh-icon-size 在自己身上改接到盒的尺 */
  [data-scope='tree-select'][data-part='branch-trigger'],
  [data-scope='tree-select'][data-part='branch-indicator'] {
    --xh-icon-size: var(--xh-tree-select-branch-indicator-size, var(--xh-control-indicator-size));

    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--xh-tree-select-branch-indicator-size, var(--xh-control-indicator-size));
    color: var(--xh-tree-select-branch-indicator-fg, var(--xh-fg-subtle));
    transition: rotate var(--xh-motion-duration-nudge) var(--xh-motion-ease-enter-strong);
  }

  [data-scope='tree-select'][data-part='branch-trigger'][hidden],
  [data-scope='tree-select'][data-part='branch-indicator'][hidden] {
    display: none;
  }

  /* 收起时朝向行首、展开时转向下方，与逻辑书写方向一致：
     rtl 下 inline-start 在右侧，箭头因此要反着转 */
  [data-scope='tree-select'][data-part='branch-trigger'][data-state='open'],
  [data-scope='tree-select'][data-part='branch-indicator'][data-state='open'] {
    rotate: 90deg;
  }

  [dir='rtl'] [data-scope='tree-select'][data-part='branch-trigger'],
  [dir='rtl'] [data-scope='tree-select'][data-part='branch-indicator'] {
    rotate: 180deg;
  }

  [dir='rtl'] [data-scope='tree-select'][data-part='branch-trigger'][data-state='open'],
  [dir='rtl'] [data-scope='tree-select'][data-part='branch-indicator'][data-state='open'] {
    rotate: 90deg;
  }

  [data-scope='tree-select'][data-part='branch-trigger'][data-disabled],
  [data-scope='tree-select'][data-part='branch-indicator'][data-disabled] {
    color: var(--xh-fg-disabled);
  }

  /* 层级缩进靠子层容器自己顶：分支物理嵌套着子层，每深一层就多缩一格，
     无需把层级号写进内联样式，也就不必在两个适配器里各写一遍 */
  [data-scope='tree-select'][data-part='branch-content'] {
    display: flex;
    flex-direction: column;
    gap: var(--xh-tree-select-branch-content-gap, var(--xh-list-option-gap));
    padding-inline-start: var(--xh-tree-select-indent, var(--xh-space-4));
  }

  /* 收起态的唯一开关：display 盖掉了 UA 的 [hidden]{display:none}，漏了这条整棵子树就收不起来 */
  [data-scope='tree-select'][data-part='branch-content'][hidden],
  [data-scope='tree-select'][data-part='branch-content'][data-state='closed'] {
    display: none;
  }

  /* 没写内容就由皮肤画兜底字形；作者往部件里塞了自己的图形，这几条即不命中。
     尺寸读各部件的 --xh-icon-size：触发器箭头与清除钮的叉按图标档，行尾对号 / 半选杠与展开 chevron
     读部件自己改接过的盒尺、与盒同边长（见上面两块） */
  [data-scope='tree-select'][data-part='indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-down) center / contain no-repeat;
  }

  [data-scope='tree-select'][data-part='item-indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-check) center / contain no-repeat;
    mask: var(--xh-glyph-mark-check) center / contain no-repeat;
  }

  [data-scope='tree-select'][data-part='item-indicator'][data-indeterminate]:not([data-selected]):empty::before {
    -webkit-mask-image: var(--xh-glyph-mark-minus);
    mask-image: var(--xh-glyph-mark-minus);
  }

  [data-scope='tree-select'][data-part='branch-trigger']:empty::before,
  [data-scope='tree-select'][data-part='branch-indicator']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
    mask: var(--xh-glyph-mark-chevron-right) center / contain no-repeat;
  }

  [data-scope='tree-select'][data-part='clear-trigger']:empty::before {
    content: '';
    display: inline-block;
    inline-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    block-size: var(--xh-icon-size, var(--xh-glyph-size-text));
    vertical-align: var(--xh-glyph-baseline-shift);
    background-color: currentColor;
    -webkit-mask: var(--xh-glyph-mark-close) center / contain no-repeat;
    mask: var(--xh-glyph-mark-close) center / contain no-repeat;
  }

  @media print {
    /* 打印：定位层与遮罩是交互期才存在的东西，落到纸上只会盖住底下的正文。
       收起写在这份皮肤里而不是 reset：reset 层排在组件层之前，组件层里任何一条 display 都压得住它。 */
    [data-scope='tree-select'][data-part='positioner'] {
      display: none;
    }
  }
}

/* styles/virtualizer.css */
/* 定义 virtualizer 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='virtualizer'] {
    --xh-virtualizer-skin: 1;
  }

  /* 定位分工：条目在**主轴**上的位移、以及 content 在主轴上的总长，
     由连接层每帧写进内联样式（竖向是 inset-block-start / block-size，横向是
     inset-inline-start / inline-size）。这份皮肤一个都不碰：内联优先级高于样式表，
     写了不但是死声明，换向的那一帧还会跟连接层清空另一轴的动作抢位置。
     皮肤只管另一条轴（交叉轴）、滚动能力与焦点表现。

     刻意不写任何过渡与动画：条目的位移每帧都在变，一加过渡整列就永远追在滚动后面；
     条目的进出走的是 [hidden]（display:none），也没有退场动画可言。

     主轴尺寸这里同样不给：给了就把动态测量钉死在这个值上——量到的永远等于钉上去的，
     measureElement 再也收敛不了。等高列表由作者按 api 给出的 size 自己写。 */

  [data-scope='virtualizer'][data-part='root'] {
    display: block;
    /* 作者给 root 定了尺寸后，长列表不该漫出这个框；
       自建定位上下文，作者往里挂的 scrollbar 贴的是这个框 */
    position: relative;
    overflow: hidden;
  }

  /* 真正滚动的那层。滚动能力一点不减——键盘（PageUp/PageDown、方向键、Home/End）
     与滚轮走的都还是浏览器原生通路，组件只是跟着滚动量换一批该渲的下标。 */
  [data-scope='virtualizer'][data-part='viewport'] {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    /* 逻辑等价物 overflow-inline / overflow-block 至今只有个别引擎实现，
       这两条是本文件里仅有的物理属性，换成逻辑写法会在多数浏览器上直接失效 */
    overflow-x: auto;
    overflow-y: auto;
    /* 页内结构容器，滚到尽头把剩余的滚动交给外层（overscroll-behavior 保持 auto）：
       contain 只给浮层、模态 body 与粘底视口。滚动条走 reset 层的原生细条 */
  }

  /* 单向列表把另一条轴关掉：那一向既没有内容也没有位移，能滚就成了滚不回来的暗格 */
  [data-scope='virtualizer'][data-part='viewport'][data-orientation='vertical'] {
    overflow-x: hidden;
  }

  [data-scope='virtualizer'][data-part='viewport'][data-orientation='horizontal'] {
    overflow-y: hidden;
  }

  /* 撑出总长的那层，同时是条目的定位上下文——条目是绝对定位的，
     没有它就会以最近的定位祖先（多半是页面某处）为参照，整列飘走。 */
  [data-scope='virtualizer'][data-part='content'] {
    position: relative;
    display: block;
    inline-size: 100%;
  }

  /* 主轴长度来自内联样式，交叉轴铺满视口 */
  [data-scope='virtualizer'][data-part='content'][data-orientation='horizontal'] {
    inline-size: auto;
    block-size: 100%;
  }

  /* 条目。主轴位移来自内联样式，这里只给定位模式与单列时的交叉轴。
     多列（lanes > 1）时交叉轴改由连接层写进内联样式，会盖过下面这两条。 */
  [data-scope='virtualizer'][data-part='item'] {
    position: absolute;
    display: block;
    box-sizing: border-box;
  }

  [data-scope='virtualizer'][data-part='item'][data-orientation='vertical'] {
    inset-inline-start: 0;
    inline-size: 100%;
  }

  [data-scope='virtualizer'][data-part='item'][data-orientation='horizontal'] {
    inset-block-start: 0;
    block-size: 100%;
  }

  /* 除视口外全是纯容器：既不进 Tab 序列也不承载焦点，作者若给它们加了 tabindex，
     该显形的也该是视口那圈环，不是这里再多画一圈。
     条目内部的可聚焦内容（按钮、链接）有它们自己的焦点环，不受这条影响。 */
  [data-scope='virtualizer'][data-part='root']:focus-visible,
  [data-scope='virtualizer'][data-part='content']:focus-visible,
  [data-scope='virtualizer'][data-part='item']:focus-visible {
    outline: none;
  }

  /* root 上还有一个 data-scrolling 标记（手正在滚时在场）。这份皮肤刻意不用它：
     滚动期间关掉 pointer-events 之类的常见招数会让"滚一下就点"落空，
     留给作者按自己的取舍去接。 */

  /* display 会盖掉 UA 的 [hidden]{display:none}，凡是被赋了 display 的角色节点都要显式让位。
     连接层只在条目上写 hidden（不在窗口里的那些），其余三个是防作者自己写 hidden */
  [data-scope='virtualizer'][data-part='root'][hidden],
  [data-scope='virtualizer'][data-part='viewport'][hidden],
  [data-scope='virtualizer'][data-part='content'][hidden],
  [data-scope='virtualizer'][data-part='item'][hidden] {
    display: none;
  }
}

/* styles/watermark.css */
/* 定义 watermark 样式。 */

@layer xihan.components {
  /* 皮肤在场的标记：开发模式下按 scope 探一次，取不到就说明这份皮肤没被引入。 */
  [data-scope='watermark'] {
    --xh-watermark-skin: 1;
  }

  /*
   * 盖水印的那块地。层叠上下文就地隔离，印子只压在这块地里，不会盖到组件外面去。
   */
  [data-scope='watermark'][data-part='root'] {
    position: relative;
    isolation: isolate;
  }

  /* 被盖住的内容排在印子下面；这层不自建层叠上下文，里面展开的浮层按自己的层号压过印子 */
  [data-scope='watermark'][data-part='content'] {
    position: relative;
  }

  /*
   * 印子。图样由连接层算成一张 SVG，这里当遮罩用而不是当背景图铺：
   * 遮罩只取图样的透明度，颜色从下面这个槽来，深浅主题各自跟着走；
   * 当背景图铺就得把颜色写死在 SVG 里，换主题时那张图不会跟着变。
   * 两条前缀都写：一部分 WebKit 只认带前缀那条。
   *
   * 没有可印的文字时 root 落 data-state="empty"，整层不画。
   */
  [data-scope='watermark'][data-part='root'][data-state='ready']::after {
    content: '';

    position: absolute;
    z-index: 1;
    inset: 0;

    /* 它只是一层印子：不吃点击，底下的内容照常点、照常选 */
    pointer-events: none;
    background-color: var(--xh-watermark-fg, var(--xh-fg-muted));
    -webkit-mask-image: var(--xh-watermark-image, none);
    mask-image: var(--xh-watermark-image, none);
    -webkit-mask-repeat: repeat;
    mask-repeat: repeat;
    -webkit-mask-size: var(--xh-watermark-tile, auto);
    mask-size: var(--xh-watermark-tile, auto);
  }

  /* 遮罩不支持时整层不画：只剩底色的话，盖上去的会是一整块实心色 */
  @supports not ((mask-image: none) or (-webkit-mask-image: none)) {
    [data-scope='watermark'][data-part='root'][data-state='ready']::after {
      display: none;
    }
  }
}

/* 排在全部组件皮肤之后：高对比档的状态环靠源序压过组件里同特指度的 outline 声明。 */

/* styles/forced-colors.css */
/*
 * 高对比档（forced-colors: active）的公共补救层。
 *
 * 这一档里系统接管配色：作者写的每一个颜色取值都被换成系统调色板里的对应角色，
 * box-shadow 与 background-image 直接丢弃。于是「只靠底色差表达的状态」全部塌成同一个样子——
 * 列表的悬停档与展开路径档、勾选与未勾选、当前页与别的页，看上去一模一样。
 *
 * 这份文件按状态词汇表逐个把通道补回来：outline 在这一档里不被丢弃，用它画两档可分的环。
 * 逐组件写不动的东西收在这里，组件自己特有的（画的就是颜色、或者靠背景图承载信息）
 * 在各自皮肤里另有 forced-colors 块。
 *
 * 取值只用 system color keyword：这一档里 --xh-* 令牌已经不生效，写了是误导。
 * 排在全部组件皮肤之后：同特指度靠源序取胜，组件皮肤里任何与这里同特指度的 outline 声明
 * 都压不掉这里的状态环。选择器一律停在两个属性（0,2,0），组件的 :focus-visible 规则
 * 特指度更高，聚焦环恒压在状态环之上。
 */
@layer xihan.components {
  @media (forced-colors: active) {
    /* 轻档：方向键锚定的那一条（焦点仍在宿主上）。虚线环，与强档一眼分得开。 */
    [data-scope][data-highlighted] {
      outline: var(--xh-stroke-thin) dashed CanvasText;
      outline-offset: calc(-1 * var(--xh-stroke-thin));
    }

    /*
     * 强档：选中、当前项、展开路径、勾选、激活、按下、走到的步骤、区间内的日期。
     * 实线环加系统高亮色，比轻档粗一档。
     *
     * data-state=open 那条要摘掉三个部件：定位层与遮罩都铺满视口，画上环就是绕着整块屏幕
     * 描一圈；content 面的边由下面那条浮层规则统一给，不走状态环。
     * 摘除写在 :where() 里，它不计特指度，整条选择器仍停在 (0,2,0)。
     */
    [data-scope][data-selected],
    [data-scope][data-current],
    [data-scope][data-in-path],
    [data-scope][data-in-range],
    [data-scope][data-indeterminate],
    [data-scope][data-passed],
    [data-scope][data-state='checked'],
    [data-scope][data-state='indeterminate'],
    [data-scope][data-state='active'],
    [data-scope][data-state='on'],
    [data-scope][data-state='current'],
    [data-scope][data-state='completed'],
    [data-scope][data-state='open']:where(:not([data-part='positioner'], [data-part='content'], [data-part='backdrop'])) {
      outline: var(--xh-stroke-thick) solid Highlight;
      outline-offset: calc(-1 * var(--xh-stroke-thick));
    }

    /*
     * 禁用：常态靠淡化的前景色表达，这一档里前景被统一换成 CanvasText，淡化那一层没了。
     * GrayText 是系统给「不可用」留的那个角色。
     */
    [data-scope][data-disabled] {
      color: GrayText;
      border-color: GrayText;
    }

    /*
     * 只读：常态是压低一档底色，这一档里底色被统一换掉，与能改的控件一模一样。
     * 改画虚线边——只读仍要照读，字色一动不动，改不动这件事写在框上。
     */
    [data-scope][data-readonly] {
      border-style: dashed;
    }

    /*
     * 浮层面：三档海拔角色都写在 box-shadow 上，这一档里整层丢弃，浮层与页面之间零分界。
     * 定位层里的那张面补一圈实边把它框出来。
     */
    [data-scope][data-part='positioner'] [data-scope][data-part='content'] {
      border: var(--xh-stroke-thin) solid CanvasText;
    }

    /*
     * 正在编辑的那一段：日期与时间的分段框里，当前段常态靠反白表达，这一档里底色被统一换掉，
     * 整行数字看上去一模一样，而这类框本来就没有光标那道线。改画一圈实边把它框出来。
     *
     * 这一条走三个属性而不是上面那些的两个：分段框的皮肤在同一档上写了 outline: none
     * （常态下环画在外层的 control 上），那条规则本身就是三个属性，两个属性压不过它。
     * data-focus 只长在日期段与时间段上，这条选到的正是它们。
     */
    [data-scope][data-part='segment'][data-focus] {
      outline: var(--xh-stroke-thick) solid Highlight;
      outline-offset: calc(-1 * var(--xh-stroke-thick));
    }
  }
}
